-- ============================================================
-- INCREMENTO 1 (paneles) · Farmacia tenant (promoción super_admin + scoping)
-- ============================================================
-- Captura (ELEVADO) de actores. Orden: P67 (no-super promueve→falla) → P68
-- (super promueve→liga la farmacia) → P65/P66 (ajeno) → P69 (dueño) → P70 (público).
SELECT set_config('role', 'none', true);
SELECT set_config('probe.farm',
  (SELECT id::text FROM public.farmacias ORDER BY id LIMIT 1), false);
SELECT set_config('probe.farm_emp',
  (SELECT id::text FROM public.empresas_proveedoras WHERE tipo='farmacia' LIMIT 1), false);
SELECT set_config('probe.farm_owner',  -- ADMIN de la empresa promovida (con permiso de edición)
  (SELECT cp.id::text FROM public.cuentas_proveedor cp
     WHERE cp.empresa_id = current_setting('probe.farm_emp', true)::uuid
       AND cp.rol_en_empresa='admin' AND cp.activo ORDER BY cp.id LIMIT 1), false);
-- El "ajeno" es una cuenta de OTRO tenant cuya empresa se convierte en una 2a farmacia (abajo).
-- EXCLUIR empresa_afin NO es cosmetico: en prod hay UNA sola empresa afin, y el INCREMENTO 3
-- (P114-P121) la necesita viva como afin. Cuando este fixture la elegia, la convertia en farmacia y
-- 300 lineas mas abajo `probe.af_emp` no encontraba ninguna -> NULL -> el UPDATE top-level de
-- af_admin ponia empresa_id=NULL -> 23502 -> MORIA LA TRANSACCION ENTERA del harness.
-- Paso el 2026-09-03 al crear las 11 cuentas QA de proveedor: 5 cayeron en la afin con uuids bajos
-- y el ORDER BY cp.id las puso primeras. El fixture no debe depender del orden de los uuids.
SELECT set_config('probe.farm_ajeno',
  (SELECT cp.id::text FROM public.cuentas_proveedor cp JOIN public.empresas_proveedoras e ON e.id=cp.empresa_id
     WHERE e.tipo NOT IN ('farmacia','empresa_afin') AND cp.activo ORDER BY cp.id LIMIT 1), false);
SELECT set_config('probe.farm_ajeno_emp',
  (SELECT cp.empresa_id::text FROM public.cuentas_proveedor cp
     WHERE cp.id = NULLIF(current_setting('probe.farm_ajeno', true),'')::uuid), false);
-- Aislamiento ENTRE tenants: convertir la empresa del ajeno en OTRA empresa-farmacia
-- (así P65/P66 prueban tenant-vs-tenant, no usuario-sin-empresa). Dentro del ROLLBACK.
-- B2 fase 1 (FX12): envuelto. ANTES era un UPDATE top-level y su WHERE, si el ajeno no resolvia,
-- NO MATCHEABA NINGUNA FILA Y SEGUIA EN SILENCIO. Ese silencio es lo que hizo que el incidente del
-- lote 1 apareciera 300 lineas despues y pareciera otra cosa: el ajeno resolvio a la unica
-- empresa_afin de la base, esta linea la convirtio en farmacia, y el INCREMENTO 3 se quedo sin afin.
-- Ahora la premisa se verifica ANTES y el resultado se PUBLICA, matcheara o no.
DO $$
DECLARE v_emp uuid; v_n int;
BEGIN
  v_emp := NULLIF(current_setting('probe.farm_ajeno_emp', true),'')::uuid;
  IF v_emp IS NULL THEN
    PERFORM set_config('probe.fx_ajeno',
      'ROJO (el ajeno NO resolvio: probe.farm_ajeno_emp vacio. P65/P66 no miden tenant-vs-tenant)', false);
  ELSE
    UPDATE public.empresas_proveedoras SET tipo='farmacia' WHERE id = v_emp;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    PERFORM set_config('probe.fx_ajeno', CASE WHEN v_n = 1
      THEN 'OK (empresa del ajeno '||left(v_emp::text,8)||' convertida a farmacia para P65/P66)'
      ELSE 'ROJO (el WHERE no matcheo: '||v_n||' filas para '||left(v_emp::text,8)||')' END, false);
  END IF;
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('probe.fx_ajeno','ROJO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;

-- P67 — NEG: un no-super_admin NO promueve una farmacia (vía RPC)
SELECT set_config('request.jwt.claims',
  json_build_object('sub', current_setting('probe.np_medico', true), 'role','authenticated')::text, true);
SELECT set_config('role', 'authenticated', true);
DO $$ BEGIN
  PERFORM public.promover_farmacia_a_tenant(NULLIF(current_setting('probe.farm', true), '')::int, NULLIF(current_setting('probe.farm_emp', true), '')::uuid);
  PERFORM set_config('probe.p67','PERMITIDO (no-super promovió)',false);
EXCEPTION
  WHEN undefined_function THEN PERFORM set_config('probe.p67','N/A (RPC no existe aún)',false);
  WHEN others THEN PERFORM set_config('probe.p67','BLOQUEADO ('||SQLSTATE||')',false);
END $$;

