  PERFORM set_config('probe.st_rpc',
    CASE WHEN to_regprocedure('public.stats_finanzas_sucursal(date,date,integer)') IS NOT NULL
          AND to_regprocedure('public.stats_recetas_sucursal(date,date,integer)') IS NOT NULL
