    ELSE PERFORM set_config('probe.p182','FALLO (n_pop='||n_pop||')',false); END IF;
  END IF;
EXCEPTION WHEN others THEN PERFORM set_config('probe.p182','FALLO ('||SQLERRM||')',false); END $$;

