    ELSE PERFORM set_config('probe.p192','FALLO (farm='||a||' lab='||b||')',false); END IF;
  END IF;
EXCEPTION WHEN others THEN PERFORM set_config('probe.p192','FALLO ('||SQLERRM||')',false); END $$;

