SELECT set_config('role','none', true);
DO $$ DECLARE v_recipok boolean; BEGIN
  IF coalesce(current_setting('probe.c8_denied',true),'')='' OR current_setting('probe.c8_denied',true)='SKIP' THEN PERFORM set_config('probe.p407','N/A',false); RETURN; END IF;
  SELECT EXISTS(SELECT 1 FROM public.notificaciones WHERE usuario_id=NULLIF(current_setting('probe.c8_recip',true), '')::uuid AND tipo='mensaje_interno' AND created_at>now()-interval '2 minutes') INTO v_recipok;
  IF current_setting('probe.c8_denied',true)='PT002' AND current_setting('probe.c8_flag',true)='false' AND current_setting('probe.c8_legit',true)='OK' AND v_recipok
    THEN PERFORM set_config('probe.p407','OK (no-autor PT002 sin quemar flag; autor notifica)',false);
    ELSE PERFORM set_config('probe.p407','FALLO (denied='||current_setting('probe.c8_denied',true)||' flag='||current_setting('probe.c8_flag',true)||' legit='||current_setting('probe.c8_legit',true)||' recip='||COALESCE(v_recipok::text,'∅')||')',false); END IF;
END $$;

-- P408 recipients derivados (2 miembros menos autor; 0 ajenos incl. otra empresa) + visibilidad RLS
DO $$ DECLARE v_in int; v_autor_n int; v_other_n int; BEGIN
  IF current_setting('probe.c8_legit',true) IS DISTINCT FROM 'OK' THEN PERFORM set_config('probe.p408','N/A',false); RETURN; END IF;
  SELECT count(*) INTO v_in FROM public.notificaciones WHERE usuario_id IN (NULLIF(current_setting('probe.c8_recip',true), '')::uuid, NULLIF(current_setting('probe.c8_recip2',true), '')::uuid) AND tipo='mensaje_interno' AND accion_url='/proveedor/mensajes' AND created_at>now()-interval '2 minutes';
  SELECT count(*) INTO v_autor_n FROM public.notificaciones WHERE usuario_id=NULLIF(current_setting('probe.c8_autor',true), '')::uuid AND tipo='mensaje_interno' AND created_at>now()-interval '2 minutes';
  SELECT count(*) INTO v_other_n FROM public.notificaciones WHERE usuario_id=NULLIF(current_setting('probe.c8_other',true), '')::uuid AND tipo='mensaje_interno' AND created_at>now()-interval '2 minutes';
  PERFORM set_config('probe.p408', CASE WHEN v_in=2 AND v_autor_n=0 AND v_other_n=0 THEN 'OK (2 recipients, autor 0, otra-empresa 0)' ELSE 'FALLO (in='||v_in||' autor='||v_autor_n||' other='||v_other_n||')' END, false);
END $$;
SELECT set_config('request.jwt.claims', json_build_object('sub', current_setting('probe.c8_recip',true),'role','authenticated')::text, true);
SELECT set_config('role','authenticated', true);
DO $$ DECLARE v_n int; BEGIN
  IF current_setting('probe.c8_legit',true) IS DISTINCT FROM 'OK' THEN RETURN; END IF;
  SELECT count(*) INTO v_n FROM public.notificaciones WHERE usuario_id=NULLIF(current_setting('probe.c8_recip',true), '')::uuid AND tipo='mensaje_interno' AND created_at>now()-interval '2 minutes';
  IF NOT (v_n>0) THEN PERFORM set_config('probe.p408','FALLO (recipient no lee su fila RLS)',false);
  ELSIF current_setting('probe.p408',true) LIKE 'OK%' THEN PERFORM set_config('probe.p408', current_setting('probe.p408',true)||' + recipient lee (RLS)', false); END IF;
END $$;
SELECT set_config('role','none', true);

-- P409 PHI: cuerpo crudo NO en contenido
DO $$ DECLARE v_leak int; BEGIN
  IF current_setting('probe.c8_legit',true) IS DISTINCT FROM 'OK' THEN PERFORM set_config('probe.p409','N/A',false); RETURN; END IF;
  SELECT count(*) INTO v_leak FROM public.notificaciones WHERE tipo='mensaje_interno' AND created_at>now()-interval '2 minutes' AND (mensaje LIKE '%CUERPO8SECRETO%' OR titulo LIKE '%CUERPO8SECRETO%');
  PERFORM set_config('probe.p409', CASE WHEN v_leak=0 THEN 'OK (cuerpo NO en contenido)' ELSE 'FALLO (cuerpo filtrado en '||v_leak||')' END, false);
END $$;

-- P410 idempotencia: 2º call → 0 fila nueva (conteo owner)
SELECT set_config('role','none', true);
DO $$ BEGIN
  IF current_setting('probe.c8_legit',true) IS DISTINCT FROM 'OK' THEN PERFORM set_config('probe.c8_before','',false); RETURN; END IF;
  PERFORM set_config('probe.c8_before', (SELECT count(*)::text FROM public.notificaciones WHERE tipo='mensaje_interno' AND created_at>now()-interval '3 minutes'), false);
END $$;
SELECT set_config('request.jwt.claims', json_build_object('sub', current_setting('probe.c8_autor',true),'role','authenticated')::text, true);
SELECT set_config('role','authenticated', true);
DO $$ BEGIN
  IF coalesce(current_setting('probe.c8_before',true),'')='' THEN RETURN; END IF;
  PERFORM public.notificar_chat_interno(NULLIF(current_setting('probe.c8_msg',true), '')::uuid);  -- 2º call (ya notificado → no-op)
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.b2_fallos', coalesce(current_setting('probe.b2_fallos', true),'')||'L6897('||SQLSTATE||') ', false);
END $$;
SELECT set_config('role','none', true);
DO $$ DECLARE v_after int; v_before int; BEGIN
  IF coalesce(current_setting('probe.c8_before',true),'')='' THEN PERFORM set_config('probe.p410','N/A',false); RETURN; END IF;
  v_before := NULLIF(current_setting('probe.c8_before',true), '')::int;
  SELECT count(*) INTO v_after FROM public.notificaciones WHERE tipo='mensaje_interno' AND created_at>now()-interval '3 minutes';
  PERFORM set_config('probe.p410', CASE WHEN v_after=v_before AND v_before>0 THEN 'OK (2º call sin fila nueva: '||v_after||'='||v_before||')' ELSE 'FALLO (before='||v_before||' after='||v_after||')' END, false);
END $$;
SELECT set_config('role','none', true);

-- ============================================================
-- Fix push transaccional · EVENTO 4 FOLD (push server-side en notificar_resultado_examen) (P411–P413). Red-first.
-- ============================================================
-- Reusa el fixture evt4 (lx_ex/lx_owner/lx_pac/lx_med/lx_lab). P411 estructural (push x2 + DEFINER + sp '').
-- P412 no-regresión (tipos + 2 filas + gateado). P413 PHI (resultado crudo ausente + accion_url interna).

-- P411 estructural: push_notificar para AMBAS tablas + DEFINER + sp '' (l.50: CREATE OR REPLACE no preserva)
DO $$ DECLARE v_def text; v_secdef boolean; v_cfg text[]; v_sp boolean; v_pac boolean; v_med boolean; BEGIN
  IF to_regprocedure('public.notificar_resultado_examen(integer)') IS NULL THEN PERFORM set_config('probe.p411','ROJO (ausente)',false); RETURN; END IF;
  SELECT pg_get_functiondef(oid), prosecdef, proconfig INTO v_def, v_secdef, v_cfg FROM pg_proc WHERE oid='public.notificar_resultado_examen(integer)'::regprocedure;
  v_sp  := EXISTS(SELECT 1 FROM unnest(coalesce(v_cfg,'{}'::text[])) e WHERE e LIKE 'search_path=%' AND e <> 'search_path=public');
  v_pac := v_def ILIKE '%push_notificar(''notificaciones_pacientes''%';
  v_med := v_def ILIKE '%push_notificar(''notificaciones'',%';
  IF v_secdef AND v_sp AND v_pac AND v_med
    THEN PERFORM set_config('probe.p411','OK (push_notificar x2 [pac+med] + DEFINER + sp'''')',false);
    ELSE PERFORM set_config('probe.p411','ROJO (secdef='||v_secdef||' sp='||v_sp||' pac='||v_pac||' med='||v_med||')',false); END IF;
END $$;

-- Setup P412/P413: re-afirmar lx_ex como del lab dueño + resultado sentinel; llamar como lx_owner.
SELECT set_config('role','none', true);
DO $$ BEGIN
  IF current_setting('probe.lx_ready',true)='1' AND coalesce(current_setting('probe.lx_ex',true),'')<>'' AND coalesce(current_setting('probe.lx_lab',true),'')<>'' THEN
    -- sentinels: resultado crudo + TIPO de examen + NOMBRE de paciente → ninguno debe llegar al cuerpo (lock screen)
    UPDATE public.examenes SET laboratorio_id=NULLIF(current_setting('probe.lx_lab',true), '')::uuid,
      resultados='PHISENTINEL_EVT4', tipo='TIPOSENTINEL_EVT4', paciente_nombre='NOMBRESENTINEL_EVT4'
      WHERE id=NULLIF(current_setting('probe.lx_ex',true), '')::int;
  END IF;
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.b2_fallos', coalesce(current_setting('probe.b2_fallos', true),'')||'L6930('||SQLSTATE||') ', false);
END $$;
SELECT set_config('request.jwt.claims', json_build_object('sub', current_setting('probe.lx_owner',true),'role','authenticated')::text, true);
SELECT set_config('role','authenticated', true);
DO $$ BEGIN
  IF current_setting('probe.lx_ready',true)<>'1' OR coalesce(current_setting('probe.lx_owner',true),'')='' OR to_regprocedure('public.notificar_resultado_examen(integer)') IS NULL THEN PERFORM set_config('probe.fold4_call','SKIP',false); RETURN; END IF;
  BEGIN PERFORM public.notificar_resultado_examen(current_setting('probe.lx_ex',true)::int); PERFORM set_config('probe.fold4_call','OK',false);
  EXCEPTION WHEN others THEN PERFORM set_config('probe.fold4_call','ERR:'||SQLSTATE,false); END;
END $$;
SELECT set_config('role','none', true);

-- P412 no-regresión: tipos 'examen'/'examen_resultado' + 2 filas + RPC gateado (DEFINER)
DO $$ DECLARE v_pac boolean; v_med boolean; v_gated boolean; BEGIN
  IF current_setting('probe.fold4_call',true) IS DISTINCT FROM 'OK' THEN PERFORM set_config('probe.p412', CASE WHEN current_setting('probe.fold4_call',true)='SKIP' THEN 'N/A' ELSE 'FALLO ('||current_setting('probe.fold4_call',true)||')' END, false); RETURN; END IF;
  SELECT EXISTS(SELECT 1 FROM public.notificaciones_pacientes WHERE paciente_id=NULLIF(current_setting('probe.lx_pac',true), '')::int AND tipo='examen' AND titulo='Resultado de examen listo') INTO v_pac;
  SELECT EXISTS(SELECT 1 FROM public.notificaciones WHERE usuario_id=NULLIF(current_setting('probe.lx_med',true), '')::uuid AND tipo='examen_resultado' AND titulo='Resultado de examen listo' AND accion_url='/medico/citas') INTO v_med;
  SELECT prosecdef INTO v_gated FROM pg_proc WHERE oid='public.notificar_resultado_examen(integer)'::regprocedure;
  PERFORM set_config('probe.p412', CASE WHEN v_pac AND v_med AND v_gated THEN 'OK (tipos examen/examen_resultado + 2 filas + DEFINER)' ELSE 'FALLO (pac='||COALESCE(v_pac::text,'∅')||' med='||COALESCE(v_med::text,'∅')||' definer='||COALESCE(v_gated::text,'∅')||')' END, false);
END $$;

-- P413 PHI ENDURECIDO: ni resultado crudo NI tipo de examen NI nombre de paciente en titulo/mensaje de NINGUNA
-- fila (3 sentinels ausentes) + accion_url interna (^/). El detalle vive in-app tras la accion_url.
DO $$ DECLARE v_leak int; v_url_ok boolean; BEGIN
  IF current_setting('probe.fold4_call',true) IS DISTINCT FROM 'OK' THEN PERFORM set_config('probe.p413','N/A',false); RETURN; END IF;
  SELECT (SELECT count(*) FROM public.notificaciones_pacientes WHERE paciente_id=NULLIF(current_setting('probe.lx_pac',true), '')::int AND titulo='Resultado de examen listo'
            AND (titulo ~ 'PHISENTINEL_EVT4|TIPOSENTINEL_EVT4|NOMBRESENTINEL_EVT4' OR mensaje ~ 'PHISENTINEL_EVT4|TIPOSENTINEL_EVT4|NOMBRESENTINEL_EVT4'))
       + (SELECT count(*) FROM public.notificaciones WHERE usuario_id=NULLIF(current_setting('probe.lx_med',true), '')::uuid AND titulo='Resultado de examen listo'
            AND (titulo ~ 'PHISENTINEL_EVT4|TIPOSENTINEL_EVT4|NOMBRESENTINEL_EVT4' OR mensaje ~ 'PHISENTINEL_EVT4|TIPOSENTINEL_EVT4|NOMBRESENTINEL_EVT4')) INTO v_leak;
  SELECT bool_and(accion_url ~ '^/') INTO v_url_ok FROM (
    SELECT accion_url FROM public.notificaciones_pacientes WHERE paciente_id=NULLIF(current_setting('probe.lx_pac',true), '')::int AND titulo='Resultado de examen listo'
    UNION ALL
    SELECT accion_url FROM public.notificaciones WHERE usuario_id=NULLIF(current_setting('probe.lx_med',true), '')::uuid AND titulo='Resultado de examen listo') t;
  PERFORM set_config('probe.p413', CASE WHEN v_leak=0 AND COALESCE(v_url_ok,false) THEN 'OK (resultado+tipo+nombre ausentes en ambas + accion_url interna)' ELSE 'FALLO (leak='||v_leak||' url_ok='||COALESCE(v_url_ok::text,'∅')||')' END, false);
END $$;
SELECT set_config('role','none', true);

-- ============================================================
-- Fix confused-deputy · HELPER enviar-notificacion → 6 RPCs gateados (P414–P418). Red-first.
-- ============================================================
-- Fixture: empresa A=411d6f8c (9ca0b977=admin, d50e7efd=editor, b38847e5=visitador_medico) + empresa B=cc17afe8
-- (e7935069=admin) + admin EzPay e56879c0. Inserta pago/solicitudes/visitas (owner, bypassa RLS).
-- triggers de visita OFF para sembrar estados exactos (rolled back en la txn del harness; postgres = dueño).
SELECT set_config('role','none', true);
-- B2 fase 1 (FX15): par 1 de DISABLE, envuelto. Sostiene el fixture del helper
-- enviar-notificacion (P414-P418), que necesita sembrar visitas en estados exactos.
-- ⚠️ CAVEAT DEL LOCK (el mismo que quedo escrito en P475): `ALTER TABLE ... DISABLE TRIGGER` toma
-- un ACCESS EXCLUSIVE sobre visitas_agendadas que se sostiene HASTA EL FINAL de la transaccion del
-- harness, no hasta el ENABLE. Con la tabla en uso real, correr el harness bloquearia a los lectores
-- durante toda la corrida. Alternativas para ese dia: sembrar con una funcion DEFINER que no dispare
-- el trigger, o mover estos probes a staging.
DO $$
BEGIN
  ALTER TABLE public.visitas_agendadas DISABLE TRIGGER trg_gate_visita_pais;
  ALTER TABLE public.visitas_agendadas DISABLE TRIGGER trigger_forzar_estado_propuesta;
  PERFORM set_config('probe.fx_trg1_off','OK (2 triggers de visitas_agendadas OFF para el fixture P414-P418)', false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('probe.fx_trg1_off','ROJO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;
-- B2: limpia h_ready ANTES del fixture, en una sentencia TOP-LEVEL — fuera del savepoint.
-- probe.h_ready lo escriben DOS frentes que no se conocen: el de citas/medico-huerfano (L6325) y
-- este (P414-P418). Si este bloque cae, h_ready vuelve al '1' del otro frente y P414-P418 corren
-- contra un fixture inexistente en vez de declararse SKIP. Colision de nombre, no de intencion.
SELECT set_config('probe.h_ready','',false);
DO $$ DECLARE v_A uuid:='411d6f8c-a405-49d6-9ed6-fbeb0db05133'; v_B uuid:='cc17afe8-fcd5-4ab0-84c4-08ba919d8481';
  v_adm uuid:='9ca0b977-3c91-48dc-aa04-2f1fab766963'; v_edi uuid:='d50e7efd-d0c6-4f14-a47b-f6b4845b25e9';
  v_vis uuid:='b38847e5-e52a-4c11-9aec-487fb558532f'; v_ext uuid:='e7935069-fd08-4ac5-a094-9c481313f4d3';
  v_ez uuid:='e56879c0-4025-4f1f-832d-2753d9ab63e1'; v_med uuid:='5f638655-f21f-4b81-8138-db76a183de67';
  v_pais uuid; v_pago uuid; v_solpub uuid; v_solrech uuid; v_solenv uuid; v_vprop uuid; v_vok uuid; v_vcanc uuid; v_vbad uuid; v_ok boolean; BEGIN
  v_ok := EXISTS(SELECT 1 FROM public.cuentas_proveedor WHERE id=v_adm) AND EXISTS(SELECT 1 FROM public.empresas_proveedoras WHERE id=v_A)
       AND EXISTS(SELECT 1 FROM public.perfiles WHERE id=v_ez AND rol IN ('ezpay_admin','super_admin','admin_finanzas'));
  IF v_ok THEN
    -- re-afirmar roles (probes previos reasignan cuentas en la misma txn)
    UPDATE public.cuentas_proveedor SET empresa_id=v_A, rol_en_empresa='admin',            activo=true, equipo_id=NULL WHERE id=v_adm;
    UPDATE public.cuentas_proveedor SET empresa_id=v_A, rol_en_empresa='editor',           activo=true, equipo_id=NULL WHERE id=v_edi;
    UPDATE public.cuentas_proveedor SET empresa_id=v_A, rol_en_empresa='visitador_medico', activo=true, equipo_id=NULL WHERE id=v_vis;
    UPDATE public.cuentas_proveedor SET empresa_id=v_B, rol_en_empresa='admin',            activo=true, equipo_id=NULL WHERE id=v_ext;
    SELECT id INTO v_pais FROM public.configuracion_pais ORDER BY id LIMIT 1;
    INSERT INTO public.pagos_proveedor (empresa_id, tipo, monto, moneda, estado) VALUES (v_A,'campana',100,'GTQ','verificado') RETURNING id INTO v_pago;
    INSERT INTO public.solicitudes_campana (empresa_id, cuenta_proveedor_id, titulo, fecha_inicio, fecha_fin, pais_id, estado, notas_admin)
      VALUES (v_A, v_adm, 'CAMP_QA_PUB', CURRENT_DATE, CURRENT_DATE+30, v_pais, 'publicada', 'NOTASQA_SECRETO') RETURNING id INTO v_solpub;
    INSERT INTO public.solicitudes_campana (empresa_id, cuenta_proveedor_id, titulo, fecha_inicio, fecha_fin, pais_id, estado, notas_admin)
      VALUES (v_A, v_adm, 'CAMP_QA_RECH', CURRENT_DATE, CURRENT_DATE+30, v_pais, 'rechazada', 'NOTASQA_SECRETO') RETURNING id INTO v_solrech;
    INSERT INTO public.solicitudes_campana (empresa_id, cuenta_proveedor_id, titulo, fecha_inicio, fecha_fin, pais_id, estado, monto_pagado)
      VALUES (v_A, v_adm, 'CAMP_QA_ENV', CURRENT_DATE, CURRENT_DATE+30, v_pais, 'enviada', 250) RETURNING id INTO v_solenv;
    -- triggers de visita deshabilitados afuera (gate_visita_pais exige plan país + mi_empresa; forzar_estado forzaría 'pendiente')
    INSERT INTO public.visitas_agendadas (empresa_id, medico_id, cuenta_proveedor_id, fecha_visita, hora_inicio, hora_fin, propuesta_por, estado)
      VALUES (v_A, v_med, v_vis, CURRENT_DATE+1, '09:00','09:30', v_vis, 'pendiente') RETURNING id INTO v_vprop;
    INSERT INTO public.visitas_agendadas (empresa_id, medico_id, cuenta_proveedor_id, fecha_visita, hora_inicio, hora_fin, estado)
      VALUES (v_A, v_med, v_edi, CURRENT_DATE+1, '10:00','10:30', 'confirmada') RETURNING id INTO v_vok;   -- cuenta∈A, rama aprobada
    INSERT INTO public.visitas_agendadas (empresa_id, medico_id, cuenta_proveedor_id, fecha_visita, hora_inicio, hora_fin, estado)
      VALUES (v_A, v_med, v_vis, CURRENT_DATE+1, '12:00','12:30', 'rechazada') RETURNING id INTO v_vcanc;  -- cuenta∈A, rama rechazada (estado REAL que deja rechazar())
    INSERT INTO public.visitas_agendadas (empresa_id, medico_id, cuenta_proveedor_id, fecha_visita, hora_inicio, hora_fin, estado)
      VALUES (v_A, v_med, v_ext, CURRENT_DATE+1, '11:00','11:30', 'confirmada') RETURNING id INTO v_vbad;  -- cuenta de empresa B → relación FAIL
  END IF;
  PERFORM set_config('probe.h_ready', CASE WHEN v_ok THEN '1' ELSE '0' END, false);
  PERFORM set_config('probe.h_A', v_A::text, false);        PERFORM set_config('probe.h_adm', v_adm::text, false);
  PERFORM set_config('probe.h_edi', v_edi::text, false);    PERFORM set_config('probe.h_vis', v_vis::text, false);
  PERFORM set_config('probe.h_ext', v_ext::text, false);    PERFORM set_config('probe.h_ez', v_ez::text, false);
  PERFORM set_config('probe.h_pago', coalesce(v_pago::text,''), false);   PERFORM set_config('probe.h_solpub', coalesce(v_solpub::text,''), false);
  PERFORM set_config('probe.h_solenv', coalesce(v_solenv::text,''), false); PERFORM set_config('probe.h_vprop', coalesce(v_vprop::text,''), false);
  PERFORM set_config('probe.h_vok', coalesce(v_vok::text,''), false);     PERFORM set_config('probe.h_vbad', coalesce(v_vbad::text,''), false);
  PERFORM set_config('probe.h_solrech', coalesce(v_solrech::text,''), false); PERFORM set_config('probe.h_vcanc', coalesce(v_vcanc::text,''), false);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.b2_fallos', coalesce(current_setting('probe.b2_fallos', true),'')||'L6999('||SQLSTATE||') ', false);
END $$;
-- B2 fase 1 (FX16): par 1 de ENABLE, envuelto Y VERIFICADO. Si el harness muriera entre el DISABLE
-- y este ENABLE, el ROLLBACK restauraria los triggers igual — pero nadie se enteraria de que la
-- ventana existio. Este probe lo DICE: cuenta cuantos quedaron deshabilitados (tgenabled='D').
DO $$
DECLARE v_off int;
BEGIN
  ALTER TABLE public.visitas_agendadas ENABLE TRIGGER trg_gate_visita_pais;
  ALTER TABLE public.visitas_agendadas ENABLE TRIGGER trigger_forzar_estado_propuesta;
  SELECT count(*) INTO v_off FROM pg_trigger t
   WHERE t.tgrelid = 'public.visitas_agendadas'::regclass
     AND t.tgname IN ('trg_gate_visita_pais','trigger_forzar_estado_propuesta')
     AND t.tgenabled = 'D';
  PERFORM set_config('probe.fx_trg1_on', CASE WHEN v_off = 0
    THEN 'OK (el ENABLE corrio: 0 triggers de visitas quedaron deshabilitados)'
    ELSE 'ROJO ('||v_off||' triggers quedaron OFF tras el ENABLE)' END, false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('probe.fx_trg1_on','ROJO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;

-- P414 estructural ENDURECIDO: 6 RPCs DEFINER+sp''+grants + FIRMA uuid-only (sin params de contenido/target, l.55)
-- + prosrc SIN push_notificar/net.http (in-app ONLY) + columna notificado_envio + helpers sp-safe.
DO $$ DECLARE r record; v_bad text:=''; v_def boolean; v_cfg text[]; v_sp boolean; v_anon boolean; v_auth boolean; v_args text; v_src text; BEGIN
  FOR r IN SELECT unnest(ARRAY['notificar_empresa_estado','notificar_pago_resultado','notificar_campana_resultado','notificar_campana_enviada','notificar_visita_propuesta','notificar_visita_resultado']) AS fn LOOP
    IF to_regprocedure('public.'||r.fn||'(uuid)') IS NULL THEN v_bad:=v_bad||r.fn||':ausente '; CONTINUE; END IF;
    SELECT prosecdef, proconfig, prosrc INTO v_def, v_cfg, v_src FROM pg_proc WHERE oid=('public.'||r.fn||'(uuid)')::regprocedure;
    v_sp := EXISTS(SELECT 1 FROM unnest(coalesce(v_cfg,'{}'::text[])) e WHERE e LIKE 'search_path=%' AND e<>'search_path=public');
    v_anon := has_function_privilege('anon','public.'||r.fn||'(uuid)','EXECUTE');
    v_auth := has_function_privilege('authenticated','public.'||r.fn||'(uuid)','EXECUTE');
    v_args := pg_get_function_identity_arguments(('public.'||r.fn||'(uuid)')::regprocedure);
    -- firma: exactamente 1 arg (sin coma) uuid + nombre del param NO es de contenido/target (l.55)
    IF position(',' in v_args)>0 OR v_args NOT LIKE '%uuid%'
       OR v_args ~* 'tipo|mensaje|target|user|contenido|nota|estado|url|titulo|usuario_id'
       THEN v_bad:=v_bad||r.fn||':firma['||v_args||'] '; END IF;
    -- in-app ONLY: el cuerpo NO debe empujar push ni hacer http
    IF v_src ILIKE '%push_notificar%' OR v_src ILIKE '%net.http%' OR v_src ILIKE '%http_post%'
       THEN v_bad:=v_bad||r.fn||':push '; END IF;
    IF NOT (v_def AND v_sp AND NOT v_anon AND v_auth) THEN v_bad:=v_bad||r.fn||'(def='||v_def||' sp='||v_sp||' anon='||v_anon||' auth='||v_auth||') '; END IF;
  END LOOP;
  IF NOT EXISTS(SELECT 1 FROM information_schema.columns WHERE table_name='solicitudes_campana' AND column_name='notificado_envio') THEN v_bad:=v_bad||'col_notificado_envio '; END IF;
  IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE proname='tiene_rol' AND pronamespace='private'::regnamespace AND array_to_string(coalesce(proconfig,'{}'::text[]),',') LIKE '%search_path=%') THEN v_bad:=v_bad||'tiene_rol_sp '; END IF;
  IF (SELECT count(*) FROM pg_proc WHERE proname IN ('obtener_usuarios_empresa','obtener_admins_ezpay','mi_empresa_proveedor') AND array_to_string(coalesce(proconfig,'{}'::text[]),',') LIKE '%search_path=%') < 3 THEN v_bad:=v_bad||'helper_sp '; END IF;
  PERFORM set_config('probe.p414', CASE WHEN v_bad='' THEN 'OK (6 RPCs DEFINER+sp''+grants + firma uuid-only + in-app-only + columna + helpers sp-safe)' ELSE 'ROJO ('||v_bad||')' END, false);
END $$;

