      VALUES (current_setting('probe.v8_A',true)::uuid, current_setting('probe.v8_med',true)::uuid, current_setting('probe.v8_ext',true)::uuid, CURRENT_DATE+3, '08:00','08:30','pendiente');
    v:='PERMITIDO';
