-- P430 POS no-regresión × 3: (a) médico de cita + (b) primario + (c) NULL → TODOS pasan pre y post
SELECT set_config('request.jwt.claims', json_build_object('sub', current_setting('probe.ch_pauth',true),'role','authenticated')::text, true);
SELECT set_config('role','authenticated', true);
DO $$ DECLARE a text; b text; c text; BEGIN
  IF current_setting('probe.ch_ready',true)<>'1' THEN PERFORM set_config('probe.p430','N/A',false); RETURN; END IF;
  -- (a) médico de cita real (si existe)
  IF coalesce(current_setting('probe.ch_cita',true),'')<>'' THEN
    BEGIN INSERT INTO public.chat_mensajes (paciente_id, medico_id, remitente, mensaje, leido)
      VALUES (current_setting('probe.ch_pac',true)::int, current_setting('probe.ch_cita',true)::uuid, 'paciente', 'pos cita', false); a:='OK';
      EXCEPTION WHEN others THEN a:='ERR('||SQLSTATE||')'; END;
  ELSE a:='OK'; END IF;  -- sin cita → no aplica, no es regresión
  -- (b) primario / pacientes.medico_id (si existe)
  IF coalesce(current_setting('probe.ch_prim',true),'')<>'' THEN
    BEGIN INSERT INTO public.chat_mensajes (paciente_id, medico_id, remitente, mensaje, leido)
      VALUES (current_setting('probe.ch_pac',true)::int, current_setting('probe.ch_prim',true)::uuid, 'paciente', 'pos primario', false); b:='OK';
      EXCEPTION WHEN others THEN b:='ERR('||SQLSTATE||')'; END;
  ELSE b:='OK'; END IF;
  -- (c) medico_id NULL (grandfather)
  BEGIN INSERT INTO public.chat_mensajes (paciente_id, medico_id, remitente, mensaje, leido)
    VALUES (current_setting('probe.ch_pac',true)::int, NULL, 'paciente', 'pos null', false); c:='OK';
    EXCEPTION WHEN others THEN c:='ERR('||SQLSTATE||')'; END;
  PERFORM set_config('probe.p430', CASE WHEN a='OK' AND b='OK' AND c='OK' THEN 'OK (cita + primario + NULL pasan, sin regresión)' ELSE 'FALLO (cita='||a||' prim='||b||' null='||c||')' END, false);
END $$;
SELECT set_config('role','none', true);

-- ============================================================
-- CIERRE FINAL bloque 1 (P431–P434). Red-first (ROJO pre-136, verde post).
-- ============================================================
SELECT set_config('role','none', true);

-- P431: REVOKE EXECUTE notificar_paciente → anon/public/authenticated SIN execute (función aún existe)
DO $$ DECLARE v_anon boolean; v_pub boolean; v_auth boolean; BEGIN
  IF to_regprocedure('public.notificar_paciente(integer,text,text,text,text)') IS NULL THEN PERFORM set_config('probe.p431','N/A (función ausente)',false); RETURN; END IF;
  v_anon := has_function_privilege('anon','public.notificar_paciente(integer,text,text,text,text)','EXECUTE');
  v_pub  := has_function_privilege('public','public.notificar_paciente(integer,text,text,text,text)','EXECUTE');
  v_auth := has_function_privilege('authenticated','public.notificar_paciente(integer,text,text,text,text)','EXECUTE');
  PERFORM set_config('probe.p431', CASE WHEN NOT v_anon AND NOT v_pub AND NOT v_auth THEN 'OK (EXECUTE revocado anon/public/auth)' ELSE 'ROJO (anon='||v_anon||' pub='||v_pub||' auth='||v_auth||')' END, false);
END $$;

-- P432: notificar_laboratorio DROPEADO
DO $$ BEGIN
  PERFORM set_config('probe.p432', CASE WHEN to_regprocedure('public.notificar_laboratorio(uuid,text,text,text,text)') IS NULL THEN 'OK (dropeado)' ELSE 'ROJO (aún existe)' END, false);
END $$;

-- P433: REVOKE INSERT directo en ambas tablas (anon✗ auth✗); DEFINER no usa el grant (se valida en los probes de RPC existentes)
DO $$ DECLARE v_n_anon boolean; v_n_auth boolean; v_np_anon boolean; v_np_auth boolean; BEGIN
  v_n_anon := has_table_privilege('anon','public.notificaciones','INSERT');
  v_n_auth := has_table_privilege('authenticated','public.notificaciones','INSERT');
  v_np_anon := has_table_privilege('anon','public.notificaciones_pacientes','INSERT');
  v_np_auth := has_table_privilege('authenticated','public.notificaciones_pacientes','INSERT');
  PERFORM set_config('probe.p433', CASE WHEN NOT v_n_anon AND NOT v_n_auth AND NOT v_np_anon AND NOT v_np_auth
    THEN 'OK (INSERT directo revocado en ambas tablas, anon+auth)'
    ELSE 'ROJO (notif anon='||v_n_anon||'/auth='||v_n_auth||' notif_pac anon='||v_np_anon||'/auth='||v_np_auth||')' END, false);
END $$;

-- P434: split policies — sin ALL dual-use; super_admin SELECT+UPDATE (preserva archivar seguimientos); paciente
-- SELECT+UPDATE-leída; SIN INSERT-policy directa en ninguna (INSERT/DELETE solo por RPC DEFINER).
DO $$ DECLARE v_all_notif int; v_all_np int; v_sa_sel boolean; v_sa_upd boolean; v_np_sel boolean; v_np_upd boolean; v_notif_ins int; v_np_ins int; BEGIN
  SELECT count(*) INTO v_all_notif FROM pg_policy WHERE polrelid='public.notificaciones'::regclass AND polcmd='*';
  SELECT count(*) INTO v_all_np FROM pg_policy WHERE polrelid='public.notificaciones_pacientes'::regclass AND polcmd='*';
  v_sa_sel := EXISTS(SELECT 1 FROM pg_policy WHERE polrelid='public.notificaciones'::regclass AND polcmd='r' AND pg_get_expr(polqual,polrelid) ILIKE '%super_admin%');
  v_sa_upd := EXISTS(SELECT 1 FROM pg_policy WHERE polrelid='public.notificaciones'::regclass AND polcmd='w' AND pg_get_expr(polqual,polrelid) ILIKE '%super_admin%');
  v_np_sel := EXISTS(SELECT 1 FROM pg_policy WHERE polrelid='public.notificaciones_pacientes'::regclass AND polcmd='r' AND pg_get_expr(polqual,polrelid) ILIKE '%auth_user_id = auth.uid()%');
  v_np_upd := EXISTS(SELECT 1 FROM pg_policy WHERE polrelid='public.notificaciones_pacientes'::regclass AND polcmd='w' AND pg_get_expr(polqual,polrelid) ILIKE '%auth_user_id = auth.uid()%');
  SELECT count(*) INTO v_notif_ins FROM pg_policy WHERE polrelid='public.notificaciones'::regclass AND polcmd='a';            -- INSERT-policy directa: 0
  SELECT count(*) INTO v_np_ins FROM pg_policy WHERE polrelid='public.notificaciones_pacientes'::regclass AND polcmd='a';     -- INSERT-policy directa: 0
  -- column-scope: authenticated puede UPDATE(leida) pero NO UPDATE(mensaje) en notificaciones_pacientes
  DECLARE v_col_leida boolean; v_col_msg boolean; BEGIN
    v_col_leida := has_column_privilege('authenticated','public.notificaciones_pacientes','leida','UPDATE');
    v_col_msg   := has_column_privilege('authenticated','public.notificaciones_pacientes','mensaje','UPDATE');
    PERFORM set_config('probe.p434', CASE WHEN v_all_notif=0 AND v_all_np=0 AND v_sa_sel AND v_sa_upd AND v_np_sel AND v_np_upd AND v_notif_ins=0 AND v_np_ins=0 AND v_col_leida AND NOT v_col_msg
      THEN 'OK (sin ALL; super_admin SELECT+UPDATE; paciente SELECT+UPDATE-leída col-scoped; 0 INSERT-policy directa)'
      ELSE 'ROJO (all_n='||v_all_notif||' all_np='||v_all_np||' sa_sel='||v_sa_sel||' sa_upd='||v_sa_upd||' np_sel='||v_np_sel||' np_upd='||v_np_upd||' n_ins='||v_notif_ins||' np_ins='||v_np_ins||' col_leida='||v_col_leida||' col_msg='||v_col_msg||')' END, false);
  END;
END $$;
SELECT set_config('role','none', true);

-- ===== P-inv (R11 candado anti-regresión): farm_med_tenant_all exige inventario_editar en escritura, SELECT intacto =====
-- R11 fue FALSO POSITIVO (la policy ya gatea por inventario_editar desde mig 079, reforzado en 114). Estos probes
-- BLINDAN ese estado: si un futuro cambio quita el término permiso de la escritura, o lo mete en la lectura, vira a ROJO.
-- Actor = cuenta admin de una empresa-con-farmacia, rol mutado in-txn a cajero (SIN inventario_editar) con sucursal_id
-- NULL (rama grandfather → término sucursal PASA → único factor bajo prueba = permiso). Restaura rol/sucursal al final.
DO $$
DECLARE v_uid uuid; v_fm uuid; v_farm int; v_orig_rol text; v_orig_suc int; v_n int; v_ins text; v_upd text; v_del text;
BEGIN
  SELECT cp.id, cp.rol_en_empresa, cp.sucursal_id, f.id
    INTO v_uid, v_orig_rol, v_orig_suc, v_farm
    FROM public.cuentas_proveedor cp
    JOIN public.farmacias f ON f.empresa_id = cp.empresa_id
   WHERE cp.empresa_id IS NOT NULL AND cp.activo = true
   ORDER BY cp.id LIMIT 1;
  SELECT fm.id INTO v_fm FROM public.farmacia_medicamentos fm WHERE fm.farmacia_id = v_farm LIMIT 1;
  IF v_uid IS NULL OR v_fm IS NULL THEN
    PERFORM set_config('probe.pinv_neg','N/A (sin fixture farmacia-empresa)',false);
    PERFORM set_config('probe.pinv_pos_w','N/A',false); PERFORM set_config('probe.pinv_pos_sel','N/A',false); RETURN;
  END IF;

  -- ACTOR cajero (sin inventario_editar), sucursal NULL
  UPDATE public.cuentas_proveedor SET rol_en_empresa='cajero', sucursal_id=NULL WHERE id=v_uid;
  PERFORM set_config('request.jwt.claims', json_build_object('sub',v_uid,'role','authenticated')::text, true);
  PERFORM set_config('role','authenticated', true);
  -- GUARD: la lectura del cajero NO se rompe (cubierta por farm_med_propia_empresa, SELECT sin permiso)
  SELECT count(*) INTO v_n FROM public.farmacia_medicamentos WHERE id=v_fm;
  PERFORM set_config('probe.pinv_pos_sel', CASE WHEN v_n>=1 THEN 'OK (cajero lee stock; guard SELECT intacto)' ELSE 'ROJO (cajero no lee stock)' END, false);
  -- NEG: escritura denegada (sin inventario_editar)
  BEGIN UPDATE public.farmacia_medicamentos SET stock_actual=stock_actual WHERE id=v_fm; GET DIAGNOSTICS v_n=ROW_COUNT;
    v_upd := CASE WHEN v_n>0 THEN 'U-PERMITIDO' ELSE 'U-deneg' END;
  EXCEPTION WHEN others THEN v_upd := 'U-deneg('||SQLSTATE||')'; END;
  BEGIN INSERT INTO public.farmacia_medicamentos (farmacia_id,nombre_medicamento,stock_actual,precio_unitario) VALUES (v_farm,'__PROBE_PINV',1,1);
    v_ins := 'I-PERMITIDO';
  EXCEPTION WHEN others THEN v_ins := 'I-deneg('||SQLSTATE||')'; END;
  BEGIN DELETE FROM public.farmacia_medicamentos WHERE id=v_fm; GET DIAGNOSTICS v_n=ROW_COUNT;
    v_del := CASE WHEN v_n>0 THEN 'D-PERMITIDO' ELSE 'D-deneg' END;
  EXCEPTION WHEN others THEN v_del := 'D-deneg('||SQLSTATE||')'; END;
  PERFORM set_config('probe.pinv_neg', CASE WHEN v_ins LIKE 'I-deneg%' AND v_upd LIKE 'U-deneg%' AND v_del LIKE 'D-deneg%'
    THEN 'OK (cajero INSERT/UPDATE/DELETE denegados sin inventario_editar)'
    ELSE 'REGRESION ('||v_ins||' '||v_upd||' '||v_del||')' END, false);

  -- POS escritura: actor con inventario_editar (rol inventario) escribe OK
  PERFORM set_config('role','none',true);
  UPDATE public.cuentas_proveedor SET rol_en_empresa='inventario', sucursal_id=NULL WHERE id=v_uid;
  PERFORM set_config('request.jwt.claims', json_build_object('sub',v_uid,'role','authenticated')::text, true);
  PERFORM set_config('role','authenticated', true);
  BEGIN UPDATE public.farmacia_medicamentos SET stock_actual=stock_actual WHERE id=v_fm; GET DIAGNOSTICS v_n=ROW_COUNT;
    PERFORM set_config('probe.pinv_pos_w', CASE WHEN v_n=1 THEN 'OK (inventario_editar escribe)' ELSE 'ROJO ('||v_n||' filas)' END, false);
  EXCEPTION WHEN others THEN PERFORM set_config('probe.pinv_pos_w','ROJO ('||SQLSTATE||')',false); END;

  -- restaurar fixture (no contamina probes posteriores; el ROLLBACK final igual revierte)
  PERFORM set_config('role','none',true);
  UPDATE public.cuentas_proveedor SET rol_en_empresa=v_orig_rol, sucursal_id=v_orig_suc WHERE id=v_uid;
END $$;
SELECT set_config('role','none', true);

-- ===== Pinvit (Invitación Opción B, mig 138 DORMANT): pre-gate + vincular_membresia_proveedor =====
-- Guardados con to_regprocedure → N/A si 138 no está aplicada (red-first: verdes en dry-run con 138 inyectada).
-- Invitador = admin de empresa-con-farmacia (rol mutado in-txn para no-admin; restaurado). Identidad por EMAIL
-- (138 ya NO acepta uid). target_libre = auth.users SIN membresía (rama ii); ocupado = ya tiene (rama iii).
DO $$
DECLARE v_admin uuid; v_emp uuid; v_orig_rol text; v_tgt_libre uuid; v_mail_libre text; v_mail_ocup text;
        v_emp_ins uuid; v_pwd_pre text; v_pwd_post text; v_sig text;
BEGIN
  IF to_regprocedure('public.vincular_membresia_proveedor(text,text,text,text,integer)') IS NULL
     OR to_regprocedure('public.autorizar_invitacion_staff(text)') IS NULL THEN
    PERFORM set_config('probe.pinvit_pregate','N/A (138 no aplicada)',false);
    PERFORM set_config('probe.pinvit_rolcat','N/A',false); PERFORM set_config('probe.pinvit_409','N/A',false);
    PERFORM set_config('probe.pinvit_pos','N/A',false); PERFORM set_config('probe.pinvit_xempresa','N/A',false); RETURN;
  END IF;
  SELECT cp.id, cp.empresa_id, cp.rol_en_empresa INTO v_admin, v_emp, v_orig_rol
    FROM public.cuentas_proveedor cp JOIN public.empresas_proveedoras e ON e.id=cp.empresa_id
   WHERE e.tipo='farmacia' AND cp.activo ORDER BY cp.id LIMIT 1;
  SELECT u.id, u.email INTO v_tgt_libre, v_mail_libre FROM auth.users u
   WHERE NOT EXISTS (SELECT 1 FROM public.cuentas_proveedor c WHERE c.id=u.id) AND u.email IS NOT NULL LIMIT 1;
  SELECT email INTO v_mail_ocup FROM public.cuentas_proveedor WHERE email IS NOT NULL LIMIT 1;
  IF v_admin IS NULL OR v_tgt_libre IS NULL THEN
    PERFORM set_config('probe.pinvit_pregate','N/A (sin fixture)',false); PERFORM set_config('probe.pinvit_rolcat','N/A',false);
    PERFORM set_config('probe.pinvit_409','N/A',false); PERFORM set_config('probe.pinvit_pos','N/A',false); PERFORM set_config('probe.pinvit_xempresa','N/A',false); RETURN;
  END IF;

  -- (estructural) cross-empresa imposible: la firma de vincular NO tiene parámetro de empresa
  v_sig := pg_get_function_identity_arguments('public.vincular_membresia_proveedor(text,text,text,text,integer)'::regprocedure);
  PERFORM set_config('probe.pinvit_xempresa', CASE WHEN v_sig NOT ILIKE '%empresa%' THEN 'OK (sin param empresa → empresa=invitador, cross-empresa estructuralmente imposible)' ELSE 'FALLO (firma expone empresa: '||v_sig||')' END, false);

  -- PRE-GATE no-admin: autorizar_invitacion_staff como cajero → 42501 ANTES de cualquier createUser (orden #1)
  UPDATE public.cuentas_proveedor SET rol_en_empresa='cajero' WHERE id=v_admin;
  PERFORM set_config('request.jwt.claims', json_build_object('sub',v_admin,'role','authenticated')::text, true);
  PERFORM set_config('role','authenticated', true);
  BEGIN PERFORM public.autorizar_invitacion_staff('cajero');
    PERFORM set_config('probe.pinvit_pregate','PERMITIDO (pre-gate dejó pasar no-admin)',false);
  EXCEPTION WHEN others THEN PERFORM set_config('probe.pinvit_pregate', CASE WHEN SQLSTATE='42501' THEN 'OK (pre-gate BLOQUEA no-admin 42501, antes de createUser)' ELSE 'OK? ('||SQLSTATE||')' END, false); END;

  -- restaurar admin
  PERFORM set_config('role','none',true);
  UPDATE public.cuentas_proveedor SET rol_en_empresa='admin' WHERE id=v_admin;
  PERFORM set_config('request.jwt.claims', json_build_object('sub',v_admin,'role','authenticated')::text, true);
  PERFORM set_config('role','authenticated', true);

  -- NEG rol fuera de catálogo del tipo (visitador_medico no es de farmacia) → 22023
  BEGIN PERFORM public.vincular_membresia_proveedor(v_mail_libre,'visitador_medico',NULL,NULL);
    PERFORM set_config('probe.pinvit_rolcat','PERMITIDO (rol fuera de catálogo)',false);
  EXCEPTION WHEN others THEN PERFORM set_config('probe.pinvit_rolcat', CASE WHEN SQLSTATE='22023' THEN 'OK (rol fuera de catálogo BLOQUEADO 22023)' ELSE 'OK? ('||SQLSTATE||')' END, false); END;

  -- NEG rama (iii): email de usuario que YA tiene membresía → 23505 (→409)
  BEGIN PERFORM public.vincular_membresia_proveedor(v_mail_ocup,'cajero',NULL,NULL);
    PERFORM set_config('probe.pinvit_409','PERMITIDO (segunda membresía)',false);
  EXCEPTION WHEN others THEN PERFORM set_config('probe.pinvit_409', CASE WHEN SQLSTATE='23505' THEN 'OK (1:1 guard 23505→409)' ELSE 'OK? ('||SQLSTATE||')' END, false); END;

  -- POS rama (ii): usuario existente SIN membresía → crea membresía (empresa=invitador) SIN tocar su credencial.
  -- (auth.users solo lo lee el owner → captura pre/post bajo rol 'none'; el vincular corre como admin.)
  PERFORM set_config('role','none',true);
  SELECT encrypted_password INTO v_pwd_pre FROM auth.users WHERE id=v_tgt_libre;
  PERFORM set_config('request.jwt.claims', json_build_object('sub',v_admin,'role','authenticated')::text, true);
  PERFORM set_config('role','authenticated', true);
  BEGIN
    PERFORM public.vincular_membresia_proveedor(v_mail_libre,'cajero','QA Vinculado',NULL);
    PERFORM set_config('role','none',true);
    SELECT empresa_id INTO v_emp_ins FROM public.cuentas_proveedor WHERE id=v_tgt_libre;
    SELECT encrypted_password INTO v_pwd_post FROM auth.users WHERE id=v_tgt_libre;
    PERFORM set_config('probe.pinvit_pos', CASE
      WHEN v_emp_ins = v_emp AND v_pwd_post IS NOT DISTINCT FROM v_pwd_pre
        THEN 'OK (vinculado: membresía empresa=invitador, credencial intacta)'
      WHEN v_emp_ins IS DISTINCT FROM v_emp THEN 'FALLO (empresa '||COALESCE(v_emp_ins::text,'∅')||' ≠ invitador '||v_emp||')'
      ELSE 'FALLO (credencial del usuario existente cambió)' END, false);
  EXCEPTION WHEN others THEN PERFORM set_config('role','none',true); PERFORM set_config('probe.pinvit_pos','FALLO ('||SQLSTATE||')',false); END;

  PERFORM set_config('role','none',true);
  UPDATE public.cuentas_proveedor SET rol_en_empresa=v_orig_rol WHERE id=v_admin;
END $$;
SELECT set_config('role','none', true);

-- ===== Pgest (Spine sucursales 3.1, mig 139 DORMANT): CRUD de sucursales =====
-- Guardados con to_regprocedure → N/A si 139 no aplicada. Admin = farmacia.qa (empresa con farmacia 147).
DO $$
DECLARE v_admin uuid; v_emp uuid; v_orig_rol text; v_suc int; v_global int; v_libre uuid;
        v_new int; v_act boolean; v_invcount int; r record; v_g42 boolean; v_e42 boolean;
        v_gate_listar text; v_gate_crear text; v_gate_edit text; v_gate_desact text; v_sig text; v_haslatlng int;
BEGIN
  IF to_regprocedure('public.listar_sucursales()') IS NULL THEN
    PERFORM set_config('probe.pgest_gate','N/A (139 no aplicada)',false);
    PERFORM set_config('probe.pgest_xempresa','N/A',false); PERFORM set_config('probe.pgest_scope','N/A',false);
    PERFORM set_config('probe.pgest_nogeo','N/A',false); PERFORM set_config('probe.pgest_softdelete','N/A',false);
    PERFORM set_config('probe.pgest_staffblock','N/A',false); PERFORM set_config('probe.pgest_unicidad','N/A',false);
    PERFORM set_config('probe.pgest_pos','N/A',false); RETURN;
  END IF;
  SELECT cp.id, cp.empresa_id, cp.rol_en_empresa INTO v_admin, v_emp, v_orig_rol
    FROM public.cuentas_proveedor cp JOIN public.empresas_proveedoras e ON e.id=cp.empresa_id
   WHERE e.tipo='farmacia' AND cp.activo ORDER BY cp.id LIMIT 1;
  SELECT id INTO v_suc FROM public.farmacias WHERE empresa_id=v_emp LIMIT 1;
  SELECT id INTO v_global FROM public.farmacias WHERE empresa_id IS NULL LIMIT 1;
  SELECT u.id INTO v_libre FROM auth.users u WHERE NOT EXISTS (SELECT 1 FROM public.cuentas_proveedor c WHERE c.id=u.id) LIMIT 1;
  IF v_admin IS NULL OR v_suc IS NULL THEN
    PERFORM set_config('probe.pgest_gate','N/A (sin fixture)',false); PERFORM set_config('probe.pgest_xempresa','N/A',false);
    PERFORM set_config('probe.pgest_scope','N/A',false); PERFORM set_config('probe.pgest_nogeo','N/A',false);
    PERFORM set_config('probe.pgest_softdelete','N/A',false); PERFORM set_config('probe.pgest_staffblock','N/A',false);
    PERFORM set_config('probe.pgest_unicidad','N/A',false); PERFORM set_config('probe.pgest_pos','N/A',false); RETURN;
  END IF;

  -- (estructural) no-geo: tabla sin lat/lng + firmas sin coord
  SELECT count(*) INTO v_haslatlng FROM information_schema.columns WHERE table_name='farmacias' AND (column_name ILIKE '%lat%' OR column_name ILIKE '%lng%' OR column_name ILIKE '%lon%');
  v_sig := pg_get_function_identity_arguments('public.crear_sucursal(text,text,text,text,text)'::regprocedure)||' '||pg_get_function_identity_arguments('public.editar_sucursal(integer,text,text,text,text,text)'::regprocedure);
  PERFORM set_config('probe.pgest_nogeo', CASE WHEN v_haslatlng=0 AND v_sig NOT ILIKE '%lat%' AND v_sig NOT ILIKE '%lng%' THEN 'OK (sin lat/lng en tabla ni firmas)' ELSE 'FALLO (geo presente)' END, false);

  -- GATE: rol sin sucursales_gestionar (cajero) denegado en los 4 RPCs
  UPDATE public.cuentas_proveedor SET rol_en_empresa='cajero' WHERE id=v_admin;
  PERFORM set_config('request.jwt.claims', json_build_object('sub',v_admin,'role','authenticated')::text, true);
  PERFORM set_config('role','authenticated', true);
  BEGIN PERFORM count(*) FROM public.listar_sucursales(); v_gate_listar:='PERMITIDO'; EXCEPTION WHEN others THEN v_gate_listar:=SQLSTATE; END;
  BEGIN PERFORM public.crear_sucursal('PGEST GATE'); v_gate_crear:='PERMITIDO'; EXCEPTION WHEN others THEN v_gate_crear:=SQLSTATE; END;
  BEGIN PERFORM public.editar_sucursal(v_suc,'PGEST GATE'); v_gate_edit:='PERMITIDO'; EXCEPTION WHEN others THEN v_gate_edit:=SQLSTATE; END;
  BEGIN PERFORM public.desactivar_sucursal(v_suc,false); v_gate_desact:='PERMITIDO'; EXCEPTION WHEN others THEN v_gate_desact:=SQLSTATE; END;
  PERFORM set_config('probe.pgest_gate', CASE WHEN v_gate_listar<>'PERMITIDO' AND v_gate_crear<>'PERMITIDO' AND v_gate_edit<>'PERMITIDO' AND v_gate_desact<>'PERMITIDO'
    THEN 'OK (4 RPCs denegados sin sucursales_gestionar)' ELSE 'PERMITIDO/FALLO (l='||v_gate_listar||' c='||v_gate_crear||' e='||v_gate_edit||' d='||v_gate_desact||')' END, false);

  -- restaurar admin
  PERFORM set_config('role','none',true);
  UPDATE public.cuentas_proveedor SET rol_en_empresa='admin' WHERE id=v_admin;
  PERFORM set_config('request.jwt.claims', json_build_object('sub',v_admin,'role','authenticated')::text, true);
  PERFORM set_config('role','authenticated', true);

  -- X-EMPRESA / GLOBALES: editar/desactivar una sucursal NO de mi empresa (global empresa_id NULL) → 42501
  v_g42:=false; v_e42:=false;
  IF v_global IS NOT NULL THEN
    BEGIN PERFORM public.editar_sucursal(v_global,'HACK'); EXCEPTION WHEN others THEN v_e42:=(SQLSTATE='42501'); END;
    BEGIN PERFORM public.desactivar_sucursal(v_global,false); EXCEPTION WHEN others THEN v_g42:=(SQLSTATE='42501'); END;
    PERFORM set_config('probe.pgest_xempresa', CASE WHEN v_e42 AND v_g42 THEN 'OK (editar/desactivar global/ajena → 42501)' ELSE 'FALLO (e42='||v_e42||' d42='||v_g42||')' END, false);
  ELSE PERFORM set_config('probe.pgest_xempresa','N/A (sin global)',false); END IF;

  -- SCOPE: listar NO incluye la global + todo lo que devuelve es de mi empresa
  IF v_global IS NOT NULL THEN
    SELECT bool_or(s.id=v_global) INTO v_act FROM public.listar_sucursales() s;
  ELSE v_act:=false; END IF;
  SELECT count(*) INTO v_new FROM public.listar_sucursales() s WHERE NOT EXISTS (SELECT 1 FROM public.farmacias f WHERE f.id=s.id AND f.empresa_id=v_emp);
  PERFORM set_config('probe.pgest_scope', CASE WHEN COALESCE(v_act,false)=false AND v_new=0 THEN 'OK (listar solo mi empresa, excluye globales)' ELSE 'FALLO (global_en_lista='||COALESCE(v_act::text,'∅')||' ajenas='||v_new||')' END, false);

  -- UNICIDAD: crear dup (case-insensitive), editar a nombre activo, reactivar que choca → 23505
  DECLARE v_u1 text; v_u2 text; v_u3 text; v_id2 int; v_a int; v_b int; BEGIN
    PERFORM public.crear_sucursal('PGEST UNICA');                                    -- activa
    BEGIN PERFORM public.crear_sucursal('pgest unica'); v_u1:='PERMITIDO'; EXCEPTION WHEN others THEN v_u1:=SQLSTATE; END;  -- dup activa (ci)
    v_id2 := public.crear_sucursal('PGEST OTRA');
    BEGIN PERFORM public.editar_sucursal(v_id2,'PGEST UNICA'); v_u2:='PERMITIDO'; EXCEPTION WHEN others THEN v_u2:=SQLSTATE; END;  -- editar→nombre activo
    -- reactivar-colisión: A inactiva 'PGEST DUP', B activa 'PGEST DUP' (permitida pq A inactiva), reactivar A → 23505
    v_a := public.crear_sucursal('PGEST DUP'); PERFORM public.desactivar_sucursal(v_a,false);
    v_b := public.crear_sucursal('PGEST DUP');
    BEGIN PERFORM public.desactivar_sucursal(v_a,true); v_u3:='PERMITIDO'; EXCEPTION WHEN others THEN v_u3:=SQLSTATE; END;
    PERFORM set_config('probe.pgest_unicidad', CASE WHEN v_u1='23505' AND v_u2='23505' AND v_u3='23505' THEN 'OK (crear/editar/reactivar dup → 23505)' ELSE 'FALLO (c='||v_u1||' e='||v_u2||' r='||v_u3||')' END, false);
  END;

  -- STAFF-BLOCK: sucursal DEDICADA (no contamina v_suc/softdelete). Staff activo → P0001; inactivo no bloquea.
  DECLARE v_sb int; v_block text; v_noblock text; BEGIN
    IF v_libre IS NULL THEN PERFORM set_config('probe.pgest_staffblock','N/A (sin auth user libre)',false);
    ELSE
      v_sb := public.crear_sucursal('PGEST STAFFBLOCK');   -- admin (authenticated)
      PERFORM set_config('role','none',true);
      INSERT INTO public.cuentas_proveedor (id,empresa_id,email,nombre_completo,rol_en_empresa,activo,sucursal_id)
        VALUES (v_libre, v_emp, 'pgest-staff@x.test','PGEST Staff','cajero',true,v_sb);
      PERFORM set_config('request.jwt.claims', json_build_object('sub',v_admin,'role','authenticated')::text, true);
      PERFORM set_config('role','authenticated', true);
      BEGIN PERFORM public.desactivar_sucursal(v_sb,false); v_block:='PERMITIDO'; EXCEPTION WHEN others THEN v_block:=SQLSTATE; END;  -- esperado P0001
      PERFORM set_config('role','none',true);
      UPDATE public.cuentas_proveedor SET activo=false WHERE id=v_libre;       -- ahora inactivo
      PERFORM set_config('request.jwt.claims', json_build_object('sub',v_admin,'role','authenticated')::text, true);
      PERFORM set_config('role','authenticated', true);
      BEGIN PERFORM public.desactivar_sucursal(v_sb,false); v_noblock:='OK-no-bloquea'; EXCEPTION WHEN others THEN v_noblock:=SQLSTATE; END;
      PERFORM set_config('probe.pgest_staffblock', CASE WHEN v_block='P0001' AND v_noblock='OK-no-bloquea' THEN 'OK (staff activo bloquea P0001; inactivo no bloquea)' ELSE 'FALLO (activo='||v_block||' inactivo='||v_noblock||')' END, false);
      PERFORM set_config('role','none',true); DELETE FROM public.cuentas_proveedor WHERE id=v_libre;
      PERFORM set_config('request.jwt.claims', json_build_object('sub',v_admin,'role','authenticated')::text, true);
      PERFORM set_config('role','authenticated', true);
    END IF;
  END;

  -- SOFT-DELETE preserva FK + reactivación. Sucursal DEDICADA + 1 fila de inventario sembrada (aísla del
  -- ruido de C.2 que siembra sucursal_id en cuentas dentro del harness). desactivar → activo=false + FK intacta → reactivar.
  DECLARE v_sd int; BEGIN
    v_sd := public.crear_sucursal('PGEST SOFTDEL');                 -- admin (authenticated), sin staff
    PERFORM set_config('role','none',true);
    -- 'PGEST MED' se siembra en el catalogo global al inicio del archivo (PW001). Handler = red.
    BEGIN
      INSERT INTO public.farmacia_medicamentos (farmacia_id, nombre_medicamento, stock_actual, precio_unitario)
        VALUES (v_sd, 'PGEST MED', 5, 1);
      PERFORM set_config('probe.fx_pgest_med','OK (PGEST MED en catalogo global + inventario sembrado)',false);
    EXCEPTION WHEN OTHERS THEN
      PERFORM set_config('probe.fx_pgest_med','ROJO (no se pudo sembrar la precondicion: '||SQLSTATE||' '||SQLERRM||')',false);
    END;
    PERFORM set_config('request.jwt.claims', json_build_object('sub',v_admin,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    SELECT count(*) INTO v_invcount FROM public.farmacia_medicamentos WHERE farmacia_id=v_sd;  -- =1
    BEGIN
      PERFORM public.desactivar_sucursal(v_sd,false);
      SELECT activo INTO v_act FROM public.farmacias WHERE id=v_sd;
      PERFORM public.desactivar_sucursal(v_sd,true);
      PERFORM set_config('probe.pgest_softdelete', CASE
        WHEN v_act=false AND (SELECT count(*) FROM public.farmacia_medicamentos WHERE farmacia_id=v_sd)=v_invcount AND (SELECT activo FROM public.farmacias WHERE id=v_sd)=true
          THEN 'OK (soft-delete activo=false, FK inventario intacta, reactiva)'
        ELSE 'FALLO (act='||COALESCE(v_act::text,'∅')||' inv='||v_invcount||')' END, false);
    EXCEPTION WHEN others THEN PERFORM set_config('probe.pgest_softdelete','FALLO ('||SQLSTATE||': '||SQLERRM||')',false); END;
  END;

  -- POS e2e: crear → aparece en listar → editar → desactivar → reactivar
  BEGIN
    v_new := public.crear_sucursal('PGEST POS E2E','Dir POS');
    SELECT bool_or(s.id=v_new) INTO v_act FROM public.listar_sucursales() s;
    PERFORM public.editar_sucursal(v_new,'PGEST POS E2E v2','Dir POS 2');
    PERFORM public.desactivar_sucursal(v_new,false);
    PERFORM public.desactivar_sucursal(v_new,true);
    PERFORM set_config('probe.pgest_pos', CASE WHEN COALESCE(v_act,false) THEN 'OK (crear/listar/editar/desactivar/reactivar propia e2e)' ELSE 'FALLO (no apareció en listar)' END, false);
  EXCEPTION WHEN others THEN PERFORM set_config('probe.pgest_pos','FALLO ('||SQLSTATE||')',false); END;

  PERFORM set_config('role','none',true);
  UPDATE public.cuentas_proveedor SET rol_en_empresa=v_orig_rol WHERE id=v_admin;
END $$;
SELECT set_config('role','none', true);

-- ===== Pasign (Spine sucursales 3.2, mig 140 DORMANT): asignación personal→sucursal + ACTIVACIÓN C.2 =====
-- Guardado con to_regprocedure. Siembra cuentas (cajero/finanzas/null) en empresa-farmacia + 2 sucursales X/Y
-- con inventario en cada una → primera vez que se ejerce farmacia_id=mi_sucursal() con dato real.
DO $$
DECLARE v_admin uuid; v_emp uuid; v_x int; v_y int; v_inact int; v_global int; v_target_b uuid;
        v_u uuid[]; v_cajero uuid; v_fin uuid; v_nullc uuid; v_mail4 text;
        v_xcnt int; v_ycnt int; v_pos int; v_exe int; v_grand int; v_rev int;
        v_gate text; v_xt text; v_xg text; v_xi text; v_suc_caj int; v_admin_suc int; v_admin_suc_pre int;
        v_alta_global text; v_alta_suc int;
BEGIN
  IF to_regprocedure('public.asignar_sucursal_a_miembro(uuid,integer)') IS NULL THEN
    PERFORM set_config('probe.pasign_gate','N/A (140 no aplicada)',false); PERFORM set_config('probe.pasign_xempresa','N/A',false);
    PERFORM set_config('probe.pasign_c2','N/A',false); PERFORM set_config('probe.pasign_desasignar','N/A',false);
    PERFORM set_config('probe.pasign_noregr','N/A',false); PERFORM set_config('probe.pasign_138alta','N/A',false); RETURN;
  END IF;
  SELECT cp.id, cp.empresa_id INTO v_admin, v_emp FROM public.cuentas_proveedor cp JOIN public.empresas_proveedoras e ON e.id=cp.empresa_id
   WHERE e.tipo='farmacia' AND cp.activo AND cp.rol_en_empresa='admin' ORDER BY cp.id LIMIT 1;
  SELECT id INTO v_x FROM public.farmacias WHERE empresa_id=v_emp AND activo=true ORDER BY id LIMIT 1;
  SELECT id INTO v_global FROM public.farmacias WHERE empresa_id IS NULL LIMIT 1;
  SELECT id INTO v_target_b FROM public.cuentas_proveedor WHERE empresa_id IS DISTINCT FROM v_emp LIMIT 1;
  SELECT array_agg(id) INTO v_u FROM (SELECT u.id FROM auth.users u WHERE NOT EXISTS (SELECT 1 FROM public.cuentas_proveedor c WHERE c.id=u.id) AND u.email IS NOT NULL ORDER BY u.id LIMIT 4) t;
  IF v_admin IS NULL OR v_x IS NULL OR v_u IS NULL OR array_length(v_u,1) < 3 THEN
    PERFORM set_config('probe.pasign_gate','N/A (sin fixture/auth libres)',false); PERFORM set_config('probe.pasign_xempresa','N/A',false);
    PERFORM set_config('probe.pasign_c2','N/A',false); PERFORM set_config('probe.pasign_desasignar','N/A',false);
    PERFORM set_config('probe.pasign_noregr','N/A',false); PERFORM set_config('probe.pasign_138alta','N/A',false); RETURN;
  END IF;
  v_cajero:=v_u[1]; v_fin:=v_u[2]; v_nullc:=v_u[3];
  SELECT sucursal_id INTO v_admin_suc_pre FROM public.cuentas_proveedor WHERE id=v_admin;  -- baseline (puede no ser NULL por ruido de probes C.2 previos en el txn)

  -- admin crea Y (+ inactiva) y siembra inventario en Y; siembra las 3 cuentas
  PERFORM set_config('request.jwt.claims', json_build_object('sub',v_admin,'role','authenticated')::text, true);
  PERFORM set_config('role','authenticated', true);
  v_y := public.crear_sucursal('PASIGN Y'); v_inact := public.crear_sucursal('PASIGN INACT'); PERFORM public.desactivar_sucursal(v_inact,false);
  PERFORM set_config('role','none',true);
  -- 'PASIGN MED Y' se siembra en el catalogo global al inicio del archivo (PW001). Handler = red.
  BEGIN
    INSERT INTO public.farmacia_medicamentos (farmacia_id,nombre_medicamento,stock_actual,precio_unitario) VALUES (v_y,'PASIGN MED Y',5,1);
    PERFORM set_config('probe.fx_pasign_med','OK (PASIGN MED Y en catalogo global + inventario sembrado)',false);
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('probe.fx_pasign_med','ROJO (no se pudo sembrar la precondicion: '||SQLSTATE||' '||SQLERRM||')',false);
  END;
  INSERT INTO public.cuentas_proveedor (id,empresa_id,email,nombre_completo,rol_en_empresa,activo,sucursal_id) VALUES
    (v_cajero,v_emp,'pasign-caj@x.test','C','cajero',true,NULL),
    (v_fin,v_emp,'pasign-fin@x.test','F','finanzas',true,NULL),
    (v_nullc,v_emp,'pasign-null@x.test','N','cajero',true,NULL);
  SELECT count(*) INTO v_xcnt FROM public.farmacia_medicamentos WHERE farmacia_id=v_x;
  SELECT count(*) INTO v_ycnt FROM public.farmacia_medicamentos WHERE farmacia_id=v_y;

  -- GATE: como cajero (sin usuarios_roles) → asignar → 42501
  PERFORM set_config('request.jwt.claims', json_build_object('sub',v_cajero,'role','authenticated')::text, true);
  PERFORM set_config('role','authenticated', true);
  BEGIN PERFORM public.asignar_sucursal_a_miembro(v_nullc, v_x); v_gate:='PERMITIDO'; EXCEPTION WHEN others THEN v_gate:=SQLSTATE; END;
  PERFORM set_config('probe.pasign_gate', CASE WHEN v_gate='42501' THEN 'OK (no-admin no asigna → 42501)' ELSE 'PERMITIDO/FALLO ('||v_gate||')' END, false);

  -- admin de nuevo
  PERFORM set_config('role','none',true);
  PERFORM set_config('request.jwt.claims', json_build_object('sub',v_admin,'role','authenticated')::text, true);
  PERFORM set_config('role','authenticated', true);

  -- X-EMPRESA: target de otra empresa / sucursal global / sucursal inactiva → 42501
  BEGIN PERFORM public.asignar_sucursal_a_miembro(v_target_b, v_x); v_xt:='PERMITIDO'; EXCEPTION WHEN others THEN v_xt:=SQLSTATE; END;
  BEGIN PERFORM public.asignar_sucursal_a_miembro(v_cajero, v_global); v_xg:='PERMITIDO'; EXCEPTION WHEN others THEN v_xg:=SQLSTATE; END;
  BEGIN PERFORM public.asignar_sucursal_a_miembro(v_cajero, v_inact); v_xi:='PERMITIDO'; EXCEPTION WHEN others THEN v_xi:=SQLSTATE; END;
  PERFORM set_config('probe.pasign_xempresa', CASE WHEN COALESCE(v_target_b::text,'')<>'' AND v_xt='42501' AND v_xg='42501' AND v_xi='42501'
    THEN 'OK (target-B/global/inactiva → 42501)' ELSE 'FALLO (t='||v_xt||' g='||v_xg||' i='||v_xi||')' END, false);

  -- ACTIVACIÓN C.2: cajero→X (confinable), finanzas→X (exento), nullc queda NULL (grandfather)
  PERFORM public.asignar_sucursal_a_miembro(v_cajero, v_x);
  PERFORM public.asignar_sucursal_a_miembro(v_fin, v_x);
  PERFORM set_config('request.jwt.claims', json_build_object('sub',v_cajero,'role','authenticated')::text, true); PERFORM set_config('role','authenticated', true);
  SELECT count(*) INTO v_pos FROM public.farmacia_medicamentos WHERE farmacia_id IN (v_x,v_y);   -- confinable: solo X
  PERFORM set_config('request.jwt.claims', json_build_object('sub',v_fin,'role','authenticated')::text, true); PERFORM set_config('role','authenticated', true);
  SELECT count(*) INTO v_exe FROM public.farmacia_medicamentos WHERE farmacia_id IN (v_x,v_y);    -- exento: X+Y
  PERFORM set_config('request.jwt.claims', json_build_object('sub',v_nullc,'role','authenticated')::text, true); PERFORM set_config('role','authenticated', true);
  SELECT count(*) INTO v_grand FROM public.farmacia_medicamentos WHERE farmacia_id IN (v_x,v_y);  -- grandfather: X+Y
  PERFORM set_config('role','none',true);
  PERFORM set_config('request.jwt.claims', json_build_object('sub',v_admin,'role','authenticated')::text, true); PERFORM set_config('role','authenticated', true);
  PERFORM public.asignar_sucursal_a_miembro(v_cajero, NULL);  -- desasignar
  PERFORM set_config('request.jwt.claims', json_build_object('sub',v_cajero,'role','authenticated')::text, true); PERFORM set_config('role','authenticated', true);
  SELECT count(*) INTO v_rev FROM public.farmacia_medicamentos WHERE farmacia_id IN (v_x,v_y);    -- revertido: X+Y
  PERFORM set_config('probe.pasign_c2', CASE
    WHEN v_ycnt>=1 AND v_pos=v_xcnt AND v_exe=v_xcnt+v_ycnt AND v_grand=v_xcnt+v_ycnt AND v_rev=v_xcnt+v_ycnt
      THEN 'OK (confinable ve solo X='||v_pos||'; exento/grandfather/revert ven X+Y='||v_exe||')'
    ELSE 'FALLO (pos='||v_pos||' exe='||v_exe||' grand='||v_grand||' rev='||v_rev||' xcnt='||v_xcnt||' ycnt='||v_ycnt||')' END, false);

  -- DESASIGNAR explícito: asignar X luego NULL → sucursal_id NULL
  PERFORM set_config('role','none',true);
  PERFORM set_config('request.jwt.claims', json_build_object('sub',v_admin,'role','authenticated')::text, true); PERFORM set_config('role','authenticated', true);
  PERFORM public.asignar_sucursal_a_miembro(v_cajero, v_x); PERFORM public.asignar_sucursal_a_miembro(v_cajero, NULL);
  PERFORM set_config('role','none',true);
  SELECT sucursal_id INTO v_suc_caj FROM public.cuentas_proveedor WHERE id=v_cajero;
  PERFORM set_config('probe.pasign_desasignar', CASE WHEN v_suc_caj IS NULL THEN 'OK (NULL → grandfather)' ELSE 'FALLO (quedó '||v_suc_caj||')' END, false);

  -- NO-REGRESIÓN: nuestras asignaciones NO tocan al admin pre-existente (su sucursal_id queda igual al baseline)
  SELECT sucursal_id INTO v_admin_suc FROM public.cuentas_proveedor WHERE id=v_admin;
  PERFORM set_config('probe.pasign_noregr', CASE WHEN v_admin_suc IS NOT DISTINCT FROM v_admin_suc_pre THEN 'OK (miembro existente intacto: sucursal sin cambios)' ELSE 'FALLO (admin cambió de '||COALESCE(v_admin_suc_pre::text,'∅')||' a '||COALESCE(v_admin_suc::text,'∅')||')' END, false);

  -- 138-EXTENDIDO: alta con sucursal (rama i/ii setea) + sucursal global en alta → 42501
  IF array_length(v_u,1) >= 4 THEN
    SELECT email INTO v_mail4 FROM auth.users WHERE id=v_u[4];
    PERFORM set_config('request.jwt.claims', json_build_object('sub',v_admin,'role','authenticated')::text, true); PERFORM set_config('role','authenticated', true);
    BEGIN PERFORM public.vincular_membresia_proveedor(v_mail4,'cajero',NULL,NULL,v_global); v_alta_global:='PERMITIDO'; EXCEPTION WHEN others THEN v_alta_global:=SQLSTATE; END;  -- global → 42501
    BEGIN PERFORM public.vincular_membresia_proveedor(v_mail4,'cajero','QA',NULL,v_x);
      PERFORM set_config('role','none',true); SELECT sucursal_id INTO v_alta_suc FROM public.cuentas_proveedor WHERE id=v_u[4];
      PERFORM set_config('request.jwt.claims', json_build_object('sub',v_admin,'role','authenticated')::text, true); PERFORM set_config('role','authenticated', true);
    EXCEPTION WHEN others THEN v_alta_suc:=-1; END;
    PERFORM set_config('probe.pasign_138alta', CASE WHEN v_alta_global='42501' AND v_alta_suc=v_x THEN 'OK (alta global rechazada 42501; alta con sucursal válida la setea)' ELSE 'FALLO (global='||v_alta_global||' suc='||COALESCE(v_alta_suc::text,'∅')||')' END, false);
  ELSE PERFORM set_config('probe.pasign_138alta','N/A (sin 4º auth libre)',false); END IF;

  -- cleanup seeds
  PERFORM set_config('role','none',true);
  DELETE FROM public.cuentas_proveedor WHERE id = ANY(v_u);
END $$;
SELECT set_config('role','none', true);

-- ===== Pruta (Spine sucursales 3.3, filtro de ruteo — SIN migración, frontend+query): replica el filtro =====
-- bajo JWT de médico QA. El filtro de ruteo = empresa_id NOT NULL + activo + stock>0, stackeado sobre la RLS
-- farm_med_disp_medico (que aplica país). Setup-guard: médico QA y la 3337 en el MISMO país (si no → N/A, no falso-rojo).
DO $$
DECLARE v_med uuid := '09d243d5-b222-482a-9762-94a582e9e752'; v_pais_med uuid; v_3337_pais uuid; v_med_global text;
        v_glob int; v_inact int; v_otropais int; v_global_med_rows int; v_3337_rows int; v_3337_dir text; v_pais_leak int;
BEGIN
  SELECT pais_id INTO v_3337_pais FROM public.farmacias WHERE id=3337;
  IF v_3337_pais IS NULL THEN
    PERFORM set_config('probe.pruta_filtro','N/A (sin 3337)',false);
    PERFORM set_config('probe.pruta_global','N/A',false); PERFORM set_config('probe.pruta_3337','N/A',false);
    PERFORM set_config('probe.pruta_pais','N/A',false); RETURN;
  END IF;
  -- Determinismo: neutralizar mutaciones de probes previos en la MISMA txn (rolled-back igual): fijar el
  -- país del médico QA = país de la 3337 Y restaurar rol='medico' (la RLS farm_med_disp_medico exige rol médico;
  -- probes previos mutan rol/país de fixtures que resuelven al QA). Sin esto, falso-rojo por estado heredado.
  UPDATE public.perfiles SET pais_id = v_3337_pais, rol = 'medico' WHERE id = v_med;
  v_pais_med := v_3337_pais;
  SELECT fm.nombre_medicamento INTO v_med_global FROM public.farmacia_medicamentos fm JOIN public.farmacias f ON f.id=fm.farmacia_id
   WHERE f.empresa_id IS NULL AND fm.stock_actual>0 AND fm.nombre_medicamento NOT ILIKE '%MED 3337%'
     -- La premisa del probe es "solo-en-global": se exige por construccion, no se asume. Sin esto,
     -- un nombre que ademas exista en una farmacia CON empresa aparece legitimamente en el ruteo y
     -- el probe reporta FALLO sin que nada de la RLS haya cambiado.
     AND NOT EXISTS (SELECT 1 FROM public.farmacia_medicamentos fm2
                       JOIN public.farmacias f2 ON f2.id = fm2.farmacia_id
                      WHERE f2.empresa_id IS NOT NULL AND fm2.nombre_medicamento = fm.nombre_medicamento)
   ORDER BY fm.nombre_medicamento LIMIT 1;   -- ORDER BY: sin el, el pick depende del orden fisico

  -- médico JWT
  PERFORM set_config('request.jwt.claims', json_build_object('sub',v_med,'role','authenticated')::text, true);
  PERFORM set_config('role','authenticated', true);

  -- (1) El FILTRO de ruteo (empresa_id NOT NULL + activo) no deja entrar globales/inactivas; RLS conserva país.
  SELECT count(*) FILTER (WHERE f.empresa_id IS NULL), count(*) FILTER (WHERE f.activo=false), count(*) FILTER (WHERE f.pais_id IS DISTINCT FROM v_pais_med)
    INTO v_glob, v_inact, v_otropais
    FROM public.farmacia_medicamentos fm JOIN public.farmacias f ON f.id=fm.farmacia_id
    WHERE fm.stock_actual>0 AND f.empresa_id IS NOT NULL AND f.activo=true;
  PERFORM set_config('probe.pruta_filtro', CASE WHEN v_glob=0 AND v_inact=0 AND v_otropais=0 THEN 'OK (filtro excluye global/inactiva; país conservado)' ELSE 'FALLO (glob='||v_glob||' inact='||v_inact||' otropais='||v_otropais||')' END, false);

  -- (2) Un med solo-en-global NO aparece bajo el filtro de ruteo.
  IF v_med_global IS NULL THEN PERFORM set_config('probe.pruta_global','N/A (sin med global)',false);
  ELSE
    SELECT count(*) INTO v_global_med_rows FROM public.farmacia_medicamentos fm JOIN public.farmacias f ON f.id=fm.farmacia_id
      WHERE fm.nombre_medicamento=v_med_global AND fm.stock_actual>0 AND f.empresa_id IS NOT NULL AND f.activo=true;
    PERFORM set_config('probe.pruta_global', CASE WHEN v_global_med_rows=0 THEN 'OK (med solo-en-global no aparece en ruteo)' ELSE 'FALLO ('||v_global_med_rows||' filas)' END, false);
  END IF;

  -- (3) El med de la 3337 (real-empresa, activa) SÍ aparece, con su direccion.
  SELECT count(*), max(f.direccion) INTO v_3337_rows, v_3337_dir FROM public.farmacia_medicamentos fm JOIN public.farmacias f ON f.id=fm.farmacia_id
    WHERE fm.nombre_medicamento ILIKE '%MED 3337%' AND fm.stock_actual>0 AND f.empresa_id IS NOT NULL AND f.activo=true AND f.id=3337;
  PERFORM set_config('probe.pruta_3337', CASE WHEN v_3337_rows>=1 AND v_3337_dir IS NOT NULL THEN 'OK (3337 aparece con direccion: '||left(v_3337_dir,24)||'…)' ELSE 'FALLO (rows='||v_3337_rows||' dir='||COALESCE(v_3337_dir,'∅')||')' END, false);

  -- (4) No-regresión país (RLS): el médico NO ve NINGÚN farmacia_medicamentos de otro país (ni con/ni sin filtro).
  SELECT count(*) INTO v_pais_leak FROM public.farmacia_medicamentos fm JOIN public.farmacias f ON f.id=fm.farmacia_id
    WHERE f.pais_id IS DISTINCT FROM v_pais_med;
  PERFORM set_config('probe.pruta_pais', CASE WHEN v_pais_leak=0 THEN 'OK (RLS aísla país: 0 filas de otro país)' ELSE 'FALLO/LEAK ('||v_pais_leak||' filas de otro país)' END, false);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.b2_fallos', coalesce(current_setting('probe.b2_fallos', true),'')||'L7986('||SQLSTATE||') ', false);
END $$;
SELECT set_config('role','none', true);

-- ===== Pbuz (Spine sucursales 3.4, mig 141): buzón + despacho confinados por sucursal =====
-- Guard por PRESENCIA del término (la función ya existe; solo el término es nuevo) → N/A sin 141.
-- Siembra: receta + 3 ítems (A,C → X=147; B → Y=3337) + recetas_avanzadas (token) + cajero@X + cajero@NULL.
-- Lista bajo 3 actores; NEG/POS de las 2 vías de despacho (dirigida + walk-in); detalle. Todo rolled-back.
DO $$
DECLARE v_x int; v_y int; v_emp uuid := '548741e4-dc6d-4b8b-81db-c30f5ef5b142'; v_med uuid := '09d243d5-b222-482a-9762-94a582e9e752';
        v_admin uuid := 'cb2fd5c6-e154-4ce5-b960-fb13c039d1d8'; v_pac bigint := 23; v_estado text; v_tok text := 'PBUZ-TOKEN-3p4';
        v_rid bigint; v_iA bigint; v_iB bigint; v_iC bigint; v_u uuid[]; v_cajx uuid; v_cajn uuid;
        v_lst jsonb; v_caj_ve text; v_adm_ve text; v_gf_ve text; v_b_dispensado boolean;
        v_neg_dir text; v_neg_wlk text; v_pos_dir text; v_pos_wlk text; v_det_ve text;
BEGIN
  IF (SELECT prosrc FROM pg_proc WHERE proname='listar_recetas_entrantes') NOT ILIKE '%sucursal_visible%' THEN
    PERFORM set_config('probe.pbuz_lista','N/A (141 no aplicada)',false); PERFORM set_config('probe.pbuz_neg','N/A',false);
    PERFORM set_config('probe.pbuz_pos','N/A',false); PERFORM set_config('probe.pbuz_detalle','N/A',false); RETURN;
  END IF;
  SELECT id INTO v_x FROM public.farmacias WHERE empresa_id=v_emp AND activo ORDER BY id LIMIT 1;     -- 147
  SELECT id INTO v_y FROM public.farmacias WHERE empresa_id=v_emp AND activo AND id<>v_x ORDER BY id LIMIT 1;  -- 3337
  SELECT array_agg(id) INTO v_u FROM (SELECT u.id FROM auth.users u WHERE NOT EXISTS (SELECT 1 FROM public.cuentas_proveedor c WHERE c.id=u.id) ORDER BY u.id LIMIT 2) t;
  IF v_x IS NULL OR v_y IS NULL OR v_u IS NULL OR array_length(v_u,1)<2 THEN
    PERFORM set_config('probe.pbuz_lista','N/A (sin fixture X/Y/auth)',false); PERFORM set_config('probe.pbuz_neg','N/A',false);
    PERFORM set_config('probe.pbuz_pos','N/A',false); PERFORM set_config('probe.pbuz_detalle','N/A',false); RETURN;
  END IF;
  v_cajx:=v_u[1]; v_cajn:=v_u[2];
  SELECT estado INTO v_estado FROM public.recetas LIMIT 1;  -- reusar un estado válido (evita CHECK)
  -- Determinismo del actor EXENTO: neutralizar mutaciones de empresa/rol/sucursal/activo de cb2fd5c6 por
  -- probes previos en la MISMA txn (rolled-back igual). empresa=QA Farmacia + admin + sucursal NULL + activo
  -- → exento real de la empresa correcta → debe ver TODO el buzón (A,B,C).
  UPDATE public.cuentas_proveedor SET empresa_id=v_emp, rol_en_empresa='admin', sucursal_id=NULL, activo=true WHERE id=v_admin;

  -- SEED (role none): receta + 3 ítems (A,C→X ; B→Y) + recetas_avanzadas + cuentas confinable/grandfather
  INSERT INTO public.recetas (medico_id, paciente_id, estado, notificado) VALUES (v_med, v_pac, v_estado, true) RETURNING id INTO v_rid;
  INSERT INTO public.receta_items (receta_id, nombre_medicamento, dosis, frecuencia, cantidad, dispensado, farmacia_id)
    VALUES (v_rid,'PBUZ MED A','1','c/8h',1,false,v_x) RETURNING id INTO v_iA;
  INSERT INTO public.receta_items (receta_id, nombre_medicamento, dosis, frecuencia, cantidad, dispensado, farmacia_id)
    VALUES (v_rid,'PBUZ MED B','1','c/8h',1,false,v_y) RETURNING id INTO v_iB;
  INSERT INTO public.receta_items (receta_id, nombre_medicamento, dosis, frecuencia, cantidad, dispensado, farmacia_id)
    VALUES (v_rid,'PBUZ MED C','1','c/8h',1,false,v_x) RETURNING id INTO v_iC;
  INSERT INTO public.recetas_avanzadas (receta_base_id, paciente_id, medico_id, dispatch_token, dispatch_token_expira_at)
    VALUES (v_rid, v_pac, v_med, v_tok, now()+interval '1 day');
  INSERT INTO public.cuentas_proveedor (id,empresa_id,email,nombre_completo,rol_en_empresa,activo,sucursal_id) VALUES
    (v_cajx,v_emp,'pbuz-cajx@x.test','CajX','cajero',true,v_x),
    (v_cajn,v_emp,'pbuz-cajn@x.test','CajN','cajero',true,NULL);

  -- helper inline: bajo el JWT actual, qué ítems PBUZ de v_rid ve el buzón
  -- (1) LISTA confinable X
  PERFORM set_config('request.jwt.claims', json_build_object('sub',v_cajx,'role','authenticated')::text, true); PERFORM set_config('role','authenticated', true);
  v_lst := public.listar_recetas_entrantes();
  SELECT string_agg(it->>'nombre_medicamento', ',' ORDER BY it->>'nombre_medicamento') INTO v_caj_ve
    FROM jsonb_array_elements(v_lst) rec, jsonb_array_elements(COALESCE(rec->'items_pendientes','[]'::jsonb)) it
    WHERE (rec->>'receta_id')::bigint=v_rid AND it->>'nombre_medicamento' LIKE 'PBUZ%';
  -- (2) LISTA exento (admin)
  PERFORM set_config('request.jwt.claims', json_build_object('sub',v_admin,'role','authenticated')::text, true); PERFORM set_config('role','authenticated', true);
  v_lst := public.listar_recetas_entrantes();
  SELECT string_agg(it->>'nombre_medicamento', ',' ORDER BY it->>'nombre_medicamento') INTO v_adm_ve
    FROM jsonb_array_elements(v_lst) rec, jsonb_array_elements(COALESCE(rec->'items_pendientes','[]'::jsonb)) it
    WHERE (rec->>'receta_id')::bigint=v_rid AND it->>'nombre_medicamento' LIKE 'PBUZ%';
  -- (3) LISTA grandfather (cajero NULL)
  PERFORM set_config('request.jwt.claims', json_build_object('sub',v_cajn,'role','authenticated')::text, true); PERFORM set_config('role','authenticated', true);
  v_lst := public.listar_recetas_entrantes();
  SELECT string_agg(it->>'nombre_medicamento', ',' ORDER BY it->>'nombre_medicamento') INTO v_gf_ve
    FROM jsonb_array_elements(v_lst) rec, jsonb_array_elements(COALESCE(rec->'items_pendientes','[]'::jsonb)) it
    WHERE (rec->>'receta_id')::bigint=v_rid AND it->>'nombre_medicamento' LIKE 'PBUZ%';
  PERFORM set_config('probe.pbuz_lista', CASE
    WHEN v_caj_ve='PBUZ MED A,PBUZ MED C' AND v_adm_ve='PBUZ MED A,PBUZ MED B,PBUZ MED C' AND v_gf_ve='PBUZ MED A,PBUZ MED B,PBUZ MED C'
      THEN 'OK (confinable X: A,C / exento: A,B,C / grandfather: A,B,C)'
    ELSE 'FALLO (cajx='||COALESCE(v_caj_ve,'∅')||' adm='||COALESCE(v_adm_ve,'∅')||' gf='||COALESCE(v_gf_ve,'∅')||')' END, false);

  -- (4) NEG acción: cajero@X intenta despachar ítem B (Y) por dirigida y walk-in → DENEGADO + B intacto
  PERFORM set_config('request.jwt.claims', json_build_object('sub',v_cajx,'role','authenticated')::text, true); PERFORM set_config('role','authenticated', true);
  BEGIN PERFORM public.registrar_dispensacion_dirigida(v_rid, ARRAY[v_iB], 'Farm QA'); v_neg_dir:='PERMITIDO'; EXCEPTION WHEN others THEN v_neg_dir:='DENEGADO'; END;
  BEGIN PERFORM public.registrar_dispensacion(v_tok, ARRAY[v_iB], 'Farm QA'); v_neg_wlk:='PERMITIDO'; EXCEPTION WHEN others THEN v_neg_wlk:='DENEGADO'; END;
  PERFORM set_config('role','none',true);
  SELECT dispensado INTO v_b_dispensado FROM public.receta_items WHERE id=v_iB;
  PERFORM set_config('probe.pbuz_neg', CASE WHEN v_neg_dir='DENEGADO' AND v_neg_wlk='DENEGADO' AND v_b_dispensado=false
    THEN 'OK (dirigida+walkin de ítem ajeno DENEGADOS; ítem Y intacto)' ELSE 'FALLO/LEAK (dir='||v_neg_dir||' wlk='||v_neg_wlk||' B_dispensado='||v_b_dispensado||')' END, false);

  -- (5) POS acción: cajero@X despacha A (dirigida) y C (walk-in) → OK
  PERFORM set_config('request.jwt.claims', json_build_object('sub',v_cajx,'role','authenticated')::text, true); PERFORM set_config('role','authenticated', true);
  BEGIN PERFORM public.registrar_dispensacion_dirigida(v_rid, ARRAY[v_iA], 'Farm QA'); v_pos_dir:='OK'; EXCEPTION WHEN others THEN v_pos_dir:='FALLO('||SQLSTATE||')'; END;
  BEGIN PERFORM public.registrar_dispensacion(v_tok, ARRAY[v_iC], 'Farm QA'); v_pos_wlk:='OK'; EXCEPTION WHEN others THEN v_pos_wlk:='FALLO('||SQLSTATE||')'; END;
  PERFORM set_config('probe.pbuz_pos', CASE WHEN v_pos_dir='OK' AND v_pos_wlk='OK' THEN 'OK (confinable X despacha sus ítems X: dirigida+walkin)' ELSE 'FALLO (dir='||v_pos_dir||' wlk='||v_pos_wlk||')' END, false);

  -- (6) detalle: cajero@X NO ve el ítem B (Y) en el detalle
  v_lst := public.detalle_receta_entrante(v_rid);
  SELECT string_agg(it->>'nombre_medicamento', ',' ORDER BY it->>'nombre_medicamento') INTO v_det_ve
    FROM jsonb_array_elements(COALESCE(v_lst->'items','[]'::jsonb)) it WHERE it->>'nombre_medicamento' LIKE 'PBUZ%';
  PERFORM set_config('probe.pbuz_detalle', CASE WHEN v_det_ve LIKE '%PBUZ MED A%' AND v_det_ve LIKE '%PBUZ MED C%' AND v_det_ve NOT LIKE '%PBUZ MED B%'
    THEN 'OK (detalle confinable X: A,C sin B)' ELSE 'FALLO ('||COALESCE(v_det_ve,'∅')||')' END, false);

  PERFORM set_config('role','none',true);
  DELETE FROM public.cuentas_proveedor WHERE id = ANY(v_u);
END $$;
SELECT set_config('role','none', true);

-- ===== Pcadena (fix nombre-de-cadena, mig 142): RPC nombre_cadena_por_farmacias =====
-- Guard por to_regprocedure → N/A sin 142. Determinismo: medico.qa rol='medico' (neutraliza mutaciones previas).
DO $$
DECLARE v_med uuid := '09d243d5-b222-482a-9762-94a582e9e752'; v_pac uuid := '5bfb5b4c-dc91-4714-93cb-a292faa6717d';
        v_n int; v_distinct int; v_nulls int; v_nomed int; v_anon boolean; v_shape text;
BEGIN
  IF to_regprocedure('public.nombre_cadena_por_farmacias(integer[])') IS NULL THEN
    PERFORM set_config('probe.pcad_medico','N/A (142 no aplicada)',false); PERFORM set_config('probe.pcad_anon','N/A',false);
    PERFORM set_config('probe.pcad_nomedico','N/A',false); PERFORM set_config('probe.pcad_shape','N/A',false); RETURN;
  END IF;
  -- (b) estructural: anon NO ejecuta; (d) shape = solo (farmacia_id int, nombre_empresa text), sin contacto
  v_anon := has_function_privilege('anon','public.nombre_cadena_por_farmacias(integer[])','EXECUTE');
  v_shape := pg_get_function_result('public.nombre_cadena_por_farmacias(integer[])'::regprocedure);
  PERFORM set_config('probe.pcad_anon', CASE WHEN v_anon=false THEN 'OK (anon NO ejecuta)' ELSE 'FALLO (anon ejecuta)' END, false);
  PERFORM set_config('probe.pcad_shape', CASE WHEN v_shape ILIKE '%farmacia_id%' AND v_shape ILIKE '%nombre_empresa%'
      AND v_shape NOT ILIKE '%ruc%' AND v_shape NOT ILIKE '%email%' AND v_shape NOT ILIKE '%telefono%' AND v_shape NOT ILIKE '%direccion%'
    THEN 'OK (solo farmacia_id+nombre_empresa; sin contacto)' ELSE 'FALLO (shape='||v_shape||')' END, false);

  -- determinismo del médico (rol mutable por probes previos en la txn; rolled-back igual)
  UPDATE public.perfiles SET rol='medico' WHERE id=v_med;

  -- (a) médico recibe nombre_empresa de sus farmacias (3337,147 → QA Farmacia ; 3755 → Farmacias del Norte SA)
  PERFORM set_config('request.jwt.claims', json_build_object('sub',v_med,'role','authenticated')::text, true);
  PERFORM set_config('role','authenticated', true);
  SELECT count(*), count(DISTINCT nombre_empresa), count(*) FILTER (WHERE nombre_empresa IS NULL)
    INTO v_n, v_distinct, v_nulls FROM public.nombre_cadena_por_farmacias(ARRAY[3337,147,3755]);
  PERFORM set_config('probe.pcad_medico', CASE WHEN v_n>=2 AND v_distinct>=1 AND v_nulls=0
    THEN 'OK (médico recibe nombre_empresa: '||v_n||' filas, '||v_distinct||' cadenas, 0 null)'
    ELSE 'FALLO (n='||v_n||' distinct='||v_distinct||' nulls='||v_nulls||')' END, false);

  -- (c) no-médico authenticated (paciente) → 0 filas (fail-closed)
  PERFORM set_config('role','none',true);
  PERFORM set_config('request.jwt.claims', json_build_object('sub',v_pac,'role','authenticated')::text, true);
  PERFORM set_config('role','authenticated', true);
  SELECT count(*) INTO v_nomed FROM public.nombre_cadena_por_farmacias(ARRAY[3337,147,3755]);
  PERFORM set_config('probe.pcad_nomedico', CASE WHEN v_nomed=0 THEN 'OK (no-médico → 0 filas, fail-closed)' ELSE 'FALLO ('||v_nomed||' filas a no-médico)' END, false);
  PERFORM set_config('role','none',true);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.b2_fallos', coalesce(current_setting('probe.b2_fallos', true),'')||'L8138('||SQLSTATE||') ', false);
END $$;
SELECT set_config('role','none', true);

-- ===== Pqr (mig 143): preview del QR (verificar_receta_despacho) confinado por sucursal =====
-- Guard por presencia del término → N/A sin 143. Receta repartida: iA→147(X), iB→3337(Y) empresa A; iC→3755 empresa B.
DO $$
DECLARE v_emp uuid := '548741e4-dc6d-4b8b-81db-c30f5ef5b142'; v_admin uuid := 'cb2fd5c6-e154-4ce5-b960-fb13c039d1d8';
        v_med uuid := '09d243d5-b222-482a-9762-94a582e9e752'; v_pac bigint := 23; v_tok text := 'PQR-TOK-143'; v_est text;
        v_rid bigint; v_iA bigint; v_iB bigint; v_iC bigint; v_u uuid[]; v_cajx uuid; v_gf uuid;
        v_prev jsonb; v_caj text; v_adm text; v_gfv text; v_dispA text; v_dispB text;
BEGIN
  IF (SELECT prosrc FROM pg_proc WHERE proname='verificar_receta_despacho') NOT ILIKE '%sucursal_visible%' THEN
    PERFORM set_config('probe.pqr_confinable','N/A (143 no aplicada)',false); PERFORM set_config('probe.pqr_exento','N/A',false);
    PERFORM set_config('probe.pqr_grandfather','N/A',false); PERFORM set_config('probe.pqr_coherencia','N/A',false); RETURN;
  END IF;
  SELECT array_agg(id) INTO v_u FROM (SELECT u.id FROM auth.users u WHERE NOT EXISTS (SELECT 1 FROM public.cuentas_proveedor c WHERE c.id=u.id) ORDER BY u.id LIMIT 2) t;
  IF v_u IS NULL OR array_length(v_u,1)<2 THEN
    PERFORM set_config('probe.pqr_confinable','N/A (sin auth libres)',false); PERFORM set_config('probe.pqr_exento','N/A',false);
    PERFORM set_config('probe.pqr_grandfather','N/A',false); PERFORM set_config('probe.pqr_coherencia','N/A',false); RETURN;
  END IF;
  v_cajx:=v_u[1]; v_gf:=v_u[2];
  SELECT estado INTO v_est FROM public.recetas LIMIT 1;
  -- seed (role none)
  INSERT INTO public.recetas (medico_id,paciente_id,estado,notificado) VALUES (v_med,v_pac,v_est,true) RETURNING id INTO v_rid;
  INSERT INTO public.receta_items (receta_id,nombre_medicamento,dosis,frecuencia,cantidad,dispensado,farmacia_id) VALUES (v_rid,'PQR MED A','1','c/8h',1,false,147) RETURNING id INTO v_iA;
  INSERT INTO public.receta_items (receta_id,nombre_medicamento,dosis,frecuencia,cantidad,dispensado,farmacia_id) VALUES (v_rid,'PQR MED B','1','c/8h',1,false,3337) RETURNING id INTO v_iB;
  INSERT INTO public.receta_items (receta_id,nombre_medicamento,dosis,frecuencia,cantidad,dispensado,farmacia_id) VALUES (v_rid,'PQR MED C','1','c/8h',1,false,3755) RETURNING id INTO v_iC;
  INSERT INTO public.recetas_avanzadas (receta_base_id,paciente_id,medico_id,dispatch_token,dispatch_token_expira_at) VALUES (v_rid,v_pac,v_med,v_tok,now()+interval '1 day');
  INSERT INTO public.cuentas_proveedor (id,empresa_id,email,nombre_completo,rol_en_empresa,activo,sucursal_id) VALUES
    (v_cajx,v_emp,'pqr-cajx@x.test','CajX','cajero',true,147),
    (v_gf,v_emp,'pqr-gf@x.test','GF','cajero',true,NULL);
  -- pin del exento (cb2fd5c6): empresa A, admin, sucursal NULL (neutraliza mutaciones previas)
  UPDATE public.cuentas_proveedor SET empresa_id=v_emp, rol_en_empresa='admin', sucursal_id=NULL, activo=true WHERE id=v_admin;

  -- (a) confinable@X (147): preview SOLO PQR MED A (no B=otra sucursal, no C=otra empresa)
  PERFORM set_config('request.jwt.claims', json_build_object('sub',v_cajx,'role','authenticated')::text, true); PERFORM set_config('role','authenticated', true);
  v_prev := public.verificar_receta_despacho(v_tok);
  SELECT string_agg(it->>'nombre_medicamento', ',' ORDER BY it->>'nombre_medicamento') INTO v_caj FROM jsonb_array_elements(COALESCE(v_prev->'items','[]'::jsonb)) it WHERE it->>'nombre_medicamento' LIKE 'PQR%';
  PERFORM set_config('probe.pqr_confinable', CASE WHEN v_caj='PQR MED A' THEN 'OK (confinable@X ve solo su sucursal; no otra sucursal ni otra empresa)' ELSE 'FALLO/LEAK ('||COALESCE(v_caj,'∅')||')' END, false);

  -- (b) exento (admin): preview A+B (empresa A, ambas sucursales); NO C (empresa B)
  PERFORM set_config('request.jwt.claims', json_build_object('sub',v_admin,'role','authenticated')::text, true); PERFORM set_config('role','authenticated', true);
  v_prev := public.verificar_receta_despacho(v_tok);
  SELECT string_agg(it->>'nombre_medicamento', ',' ORDER BY it->>'nombre_medicamento') INTO v_adm FROM jsonb_array_elements(COALESCE(v_prev->'items','[]'::jsonb)) it WHERE it->>'nombre_medicamento' LIKE 'PQR%';
  PERFORM set_config('probe.pqr_exento', CASE WHEN v_adm='PQR MED A,PQR MED B' THEN 'OK (exento ve toda su empresa A; cross-empresa C excluido)' ELSE 'FALLO ('||COALESCE(v_adm,'∅')||')' END, false);

  -- (d) grandfather (cajero@NULL): preview A+B (no-regresión); NO C
  PERFORM set_config('request.jwt.claims', json_build_object('sub',v_gf,'role','authenticated')::text, true); PERFORM set_config('role','authenticated', true);
  v_prev := public.verificar_receta_despacho(v_tok);
  SELECT string_agg(it->>'nombre_medicamento', ',' ORDER BY it->>'nombre_medicamento') INTO v_gfv FROM jsonb_array_elements(COALESCE(v_prev->'items','[]'::jsonb)) it WHERE it->>'nombre_medicamento' LIKE 'PQR%';
  PERFORM set_config('probe.pqr_grandfather', CASE WHEN v_gfv='PQR MED A,PQR MED B' THEN 'OK (grandfather ve toda su empresa; cross-empresa C excluido)' ELSE 'FALLO ('||COALESCE(v_gfv,'∅')||')' END, false);

  -- (e) coherencia despacho: confinable@X despacha lo que el preview mostró (A) OK; lo que NO mostró (B) DENEGADO
  PERFORM set_config('request.jwt.claims', json_build_object('sub',v_cajx,'role','authenticated')::text, true); PERFORM set_config('role','authenticated', true);
  BEGIN PERFORM public.registrar_dispensacion(v_tok, ARRAY[v_iB], 'Farm QA'); v_dispB:='PERMITIDO'; EXCEPTION WHEN others THEN v_dispB:='DENEGADO'; END;
  BEGIN PERFORM public.registrar_dispensacion(v_tok, ARRAY[v_iA], 'Farm QA'); v_dispA:='OK'; EXCEPTION WHEN others THEN v_dispA:='FALLO('||SQLSTATE||')'; END;
  PERFORM set_config('probe.pqr_coherencia', CASE WHEN v_dispA='OK' AND v_dispB='DENEGADO' THEN 'OK (despacha lo que el preview mostró [A]; lo oculto [B] DENEGADO)' ELSE 'FALLO (A='||v_dispA||' B='||v_dispB||')' END, false);

  PERFORM set_config('role','none',true);
  DELETE FROM public.cuentas_proveedor WHERE id = ANY(v_u);
END $$;
SELECT set_config('role','none', true);

-- ===== Bloque 262 · guard de perfiles: rol + pais_id + rol_id + activo (P435–P446) =====
-- Cierra P435: la policy "Actualizar propio perfil" (FOR UPDATE USING auth.uid()=id, with_check NULL
-- → WITH CHECK efectivo = el propio USING) valida QUIÉN es la fila, no QUÉ columnas cambian; y las
-- policies permisivas se combinan con OR, así que habilita el self-update aunque la policy de admin
-- lo rechace. El trigger BEFORE UPDATE trg_perfiles_guard_rol_update es el único control real.
-- LECCIÓN: cuando dos controles comparten SQLSTATE (RLS y guard usan 42501), el que corre primero
-- enmascara al otro. Orden de un UPDATE con RLS: (1) USING filtra filas → (2) triggers BEFORE ROW →
-- (3) WITH CHECK sobre la fila NEW. Por eso P445 pasó de cortarlo la RLS a cortarlo el guard, y por eso
-- el centinela de aislamiento (P446) se apoya en el USING (paso 1) y no en el WITH CHECK (paso 3).
-- Cada probe deshace su propio UPDATE con un RAISE centinela ('PROBE_UNDO'): la subtransacción se
-- revierte y el probe no deja residuo para los siguientes dentro de esta transacción.
-- Actores: admin_pais QA 8f391caf / super_admin 41904e2c / medico 09d243d5 / tercero GT 66168f15.
SELECT set_config('role','none', true);

-- P435 — admin_pais NO puede cambiarse su propio pais_id (era el hueco; mig 262)
DO $$ DECLARE v_n bigint := 0; v_err text := NULL; v_msg text := NULL; BEGIN
  PERFORM set_config('request.jwt.claims','{"sub":"8f391caf-85bc-4413-af8a-4006452ae09f","role":"authenticated"}', true);
  BEGIN
