-- P446 — CENTINELA del aislamiento por país. Se apoya en el USING (paso 1), no en el WITH CHECK (paso 3):
-- admin_pais de GT toca un perfil de SV en una columna NO vigilada (nombre_completo). Si el aislamiento
-- funciona el USING filtra la fila ⇒ filas_afectadas = 0 SIN excepción. VERDE = 0 filas, no 1.
-- Fixture propia (hoy los perfiles de prod están todos en GT): crea su sujeto y lo revierte con el
-- RAISE centinela. El INSERT en auth.users no dispara on_auth_user_created_paciente (ese trigger sale
-- por RETURN NEW salvo raw_user_meta_data->>'tipo' = 'paciente').
DO $$ DECLARE v_n bigint := -1; v_err text := NULL; v_msg text := NULL;
             v_uid uuid := '00000000-0000-4446-8446-000000000446'; BEGIN
  BEGIN
    INSERT INTO auth.users (id) VALUES (v_uid);
    INSERT INTO public.perfiles (id, email, nombre_completo, rol, pais_id, activo)
      VALUES (v_uid, 'probe446@example.invalid', 'Sujeto Probe 446', 'cliente', 'f2c75b8e-ef54-4a05-b2ff-7363e448f680', true)
      ON CONFLICT (id) DO UPDATE SET rol='cliente', pais_id='f2c75b8e-ef54-4a05-b2ff-7363e448f680', activo=true;
    PERFORM set_config('request.jwt.claims','{"sub":"8f391caf-85bc-4413-af8a-4006452ae09f","role":"authenticated"}', true);
    PERFORM set_config('role','authenticated', true);
    UPDATE public.perfiles SET nombre_completo = nombre_completo||' (probe446)' WHERE id = v_uid;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    PERFORM set_config('role','none', true);
    RAISE EXCEPTION 'PROBE_UNDO';   -- revierte fixture + UPDATE
  EXCEPTION WHEN OTHERS THEN
    IF SQLERRM <> 'PROBE_UNDO' THEN v_err := SQLSTATE; v_msg := SQLERRM; END IF;
  END;
  PERFORM set_config('role','none', true);
  PERFORM set_config('probe.p446', CASE
    WHEN v_msg IS NULL AND v_n = 0 THEN 'BLOQUEADO (USING aisló el país: 0 filas, sin excepción)'
    WHEN v_msg IS NULL AND v_n = 1 THEN 'ROJO (AISLAMIENTO POR PAÍS ROTO: admin_pais GT tocó un perfil de SV)'
    WHEN v_msg LIKE 'No autorizado a modificar%' THEN 'ROJO (probe mal escrito: eligió una columna vigilada por el guard)'
    ELSE 'ROJO (excepción inesperada '||COALESCE(v_err,'?')||': '||COALESCE(v_msg,'?')||')' END, false);
END $$;
SELECT set_config('role','none', true);

-- ===== Bloque 263 · roles comerciales + catálogos de prospección (P447–P456) =====
-- Maquinaria INERTE: ningún frontend ni edge function consume esto todavía. Los probes verifican
-- que el andamiaje quedó bien puesto y con la higiene de privilegios correcta.
--
-- ORIGEN DEL CORTE: la RLS, el guard de perfiles, un CHECK y un REVOKE comparten SQLSTATE en
-- distintas combinaciones (42501 lo usan RLS y GRANT; 23514 el CHECK; 23503 la FK), así que cada
-- probe aserta sobre el MENSAJE, no sobre el código pelado. Ver la lección del bloque 262 (P445):
-- cuando dos controles comparten SQLSTATE, el que corre primero enmascara al de atrás.
--
-- P449/P450 y el orden FK-antes-que-CHECK: perfiles.rol tiene FK a roles_catalogo(codigo). Si la 263
-- NO estuviera aplicada, el INSERT lo cortaría perfiles_rol_fkey (23503) y no el CHECK — por eso los
-- verdicts distinguen ese caso explícitamente en vez de reportar un ROJO mudo.
--
-- Cada probe con fixtures deshace lo suyo con un RAISE centinela ('PROBE_UNDO'): la subtransacción se
-- revierte y no deja residuo para los siguientes dentro de la transacción única del harness.
-- Fixtures: 00000000-0000-4263-8449/8450/8451-0000000004xx. GT = cbbbbe6d-59fe-4cf2-91ee-3e31ba1d5909.
SELECT set_config('role','none', true);

-- P447 — roles_catalogo (autoridad real, FK de perfiles.rol): los 2 roles con orden 16/17,
-- ámbito sistema, no super, no staff de clínica, activos.
DO $$ DECLARE v_ok boolean; v_det text; v_n bigint := 0; BEGIN
  SELECT count(*), string_agg(codigo||' orden='||orden||' activo='||activo||' ambito='||ambito, ' | ' ORDER BY orden)
    INTO v_n, v_det
    FROM public.roles_catalogo WHERE codigo IN ('asesor_comercial','supervisor_comercial');
  v_ok := EXISTS (SELECT 1 FROM public.roles_catalogo WHERE codigo='asesor_comercial'
                   AND activo AND orden=16 AND ambito='sistema' AND NOT es_super AND NOT es_staff_clinica)
      AND EXISTS (SELECT 1 FROM public.roles_catalogo WHERE codigo='supervisor_comercial'
                   AND activo AND orden=17 AND ambito='sistema' AND NOT es_super AND NOT es_staff_clinica);
  PERFORM set_config('probe.p447', CASE WHEN v_ok
    THEN 'OK (2 roles en roles_catalogo: '||v_det||')'
    ELSE 'ROJO (n='||v_n||': '||COALESCE(v_det,'ninguno presente')||')' END, false);
END $$;
SELECT set_config('role','none', true);

-- P448 — public.roles (RBAC legacy que consume crear-empleado / AsignacionRolesPage): los 2 roles
-- con nivel=1. nivel=1 los deja FUERA de la escalada de notificar-admin, que no filtra por país.
DO $$ DECLARE v_n bigint := 0; v_mal bigint := 0; v_det text; BEGIN
  SELECT count(*), count(*) FILTER (WHERE nivel <> 1),
         string_agg(nombre||' nivel='||nivel||' permisos='||permisos::text, ' | ' ORDER BY nombre)
    INTO v_n, v_mal, v_det
    FROM public.roles WHERE nombre IN ('asesor_comercial','supervisor_comercial');
  PERFORM set_config('probe.p448', CASE WHEN v_n = 2 AND v_mal = 0
    THEN 'OK (2 roles en public.roles: '||v_det||')'
    ELSE 'ROJO (n='||v_n||' con_nivel_distinto_de_1='||v_mal||': '||COALESCE(v_det,'ninguno presente')||')' END, false);
END $$;
SELECT set_config('role','none', true);

-- P449 — NEG: un perfil comercial SIN pais_id es imposible, por INSERT (a) y por UPDATE (b).
-- Corre como postgres, así que el guard de perfiles (mig 262) queda exento y lo único bajo prueba
-- es el CHECK comercial_requiere_pais. El seeding de (b) tiene su propio handler: sin la 263 aplicada
-- falla por la FK y sin handler abortaría la transacción entera del harness.
DO $$
DECLARE v_uid uuid := '00000000-0000-4263-8449-000000000449';
        v_err text; v_msg text; v_n bigint; v_sembrado boolean;
        v_a text; v_b text; v_fatal text := NULL;
BEGIN
  BEGIN
    INSERT INTO auth.users (id) VALUES (v_uid);

    -- (a) INSERT directo con pais_id NULL
    v_err := NULL; v_msg := NULL; v_n := 0;
    BEGIN
      INSERT INTO public.perfiles (id, email, nombre_completo, rol, pais_id, activo)
        VALUES (v_uid, 'probe449@example.invalid', 'Probe 449', 'asesor_comercial', NULL, true);
      GET DIAGNOSTICS v_n = ROW_COUNT;
    EXCEPTION WHEN OTHERS THEN v_err := SQLSTATE; v_msg := SQLERRM; v_n := 0; END;
    v_a := CASE
      WHEN v_err = '23514' AND v_msg LIKE '%comercial_requiere_pais%' THEN 'BLOQUEADO (CHECK comercial_requiere_pais)'
      WHEN v_err = '23503' THEN 'ROJO (cortó la FK perfiles_rol_fkey: el rol no está en roles_catalogo → mig 263 sin aplicar)'
      WHEN v_err IS NOT NULL THEN 'ROJO ('||v_err||': '||v_msg||')'
      ELSE 'PERMITIDO (comercial sin país, filas='||v_n||')' END;

    -- (b) sembrar válido (país GT) y después intentar borrarle el país
    v_err := NULL; v_msg := NULL; v_n := 0; v_sembrado := true;
    BEGIN
      INSERT INTO public.perfiles (id, email, nombre_completo, rol, pais_id, activo)
        VALUES (v_uid, 'probe449@example.invalid', 'Probe 449', 'asesor_comercial',
                'cbbbbe6d-59fe-4cf2-91ee-3e31ba1d5909', true);
    EXCEPTION WHEN OTHERS THEN v_sembrado := false; v_err := SQLSTATE; v_msg := SQLERRM; END;

    IF NOT v_sembrado THEN
      v_b := 'ROJO (no se pudo sembrar la fila base: '||v_err||' '||v_msg||')';
    ELSE
      v_err := NULL; v_msg := NULL; v_n := 0;
      BEGIN
        UPDATE public.perfiles SET pais_id = NULL WHERE id = v_uid;
        GET DIAGNOSTICS v_n = ROW_COUNT;
      EXCEPTION WHEN OTHERS THEN v_err := SQLSTATE; v_msg := SQLERRM; v_n := 0; END;
      v_b := CASE
        WHEN v_err = '23514' AND v_msg LIKE '%comercial_requiere_pais%' THEN 'BLOQUEADO (CHECK comercial_requiere_pais)'
        WHEN v_err IS NOT NULL THEN 'ROJO ('||v_err||': '||v_msg||')'
        ELSE 'PERMITIDO (le borró el país a un comercial, filas='||v_n||')' END;
    END IF;

    RAISE EXCEPTION 'PROBE_UNDO';
  EXCEPTION WHEN OTHERS THEN
    IF SQLERRM <> 'PROBE_UNDO' THEN v_fatal := SQLSTATE||' '||SQLERRM; END IF;
  END;
  PERFORM set_config('probe.p449a', COALESCE('ROJO (fatal: '||v_fatal||')', v_a, 'ROJO (sin resultado)'), false);
  PERFORM set_config('probe.p449b', COALESCE('ROJO (fatal: '||v_fatal||')', v_b, 'ROJO (sin resultado)'), false);
END $$;
SELECT set_config('role','none', true);

-- P450 — POS: el mismo perfil con pais_id = GT entra sin problema. Control de que el CHECK no
-- bloquea el alta legítima.
DO $$
DECLARE v_uid uuid := '00000000-0000-4263-8450-000000000450';
        v_err text; v_msg text; v_n bigint := 0; v_res text; v_fatal text := NULL;
BEGIN
  BEGIN
    INSERT INTO auth.users (id) VALUES (v_uid);
    BEGIN
      INSERT INTO public.perfiles (id, email, nombre_completo, rol, pais_id, activo)
        VALUES (v_uid, 'probe450@example.invalid', 'Probe 450', 'asesor_comercial',
                'cbbbbe6d-59fe-4cf2-91ee-3e31ba1d5909', true);
      GET DIAGNOSTICS v_n = ROW_COUNT;
    EXCEPTION WHEN OTHERS THEN v_err := SQLSTATE; v_msg := SQLERRM; v_n := 0; END;
    v_res := CASE
      WHEN v_err IS NULL AND v_n = 1 THEN 'OK (alta de comercial con país, filas=1)'
      WHEN v_err = '23503' THEN 'ROJO (cortó la FK perfiles_rol_fkey: el rol no está en roles_catalogo → mig 263 sin aplicar)'
      WHEN v_err IS NOT NULL THEN 'ROJO ('||v_err||': '||v_msg||')'
      ELSE 'ROJO (filas='||v_n||')' END;
    RAISE EXCEPTION 'PROBE_UNDO';
  EXCEPTION WHEN OTHERS THEN
    IF SQLERRM <> 'PROBE_UNDO' THEN v_fatal := SQLSTATE||' '||SQLERRM; END IF;
  END;
  PERFORM set_config('probe.p450', COALESCE('ROJO (fatal: '||v_fatal||')', v_res, 'ROJO (sin resultado)'), false);
END $$;
SELECT set_config('role','none', true);

-- P451 — NEG de no-regresión: admin_pais_requiere_pais (mig 216) sigue vivo e INDEPENDIENTE del
-- constraint nuevo. Dos aserciones: sigue cortando (23514) y los dos constraints coexisten separados.
DO $$
DECLARE v_uid uuid := '00000000-0000-4263-8451-000000000451';
        v_err text; v_msg text; v_n bigint := 0; v_res text; v_fatal text := NULL;
        v_viejo boolean; v_nuevo boolean;
BEGIN
  v_viejo := EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='public.perfiles'::regclass AND conname='admin_pais_requiere_pais');
  v_nuevo := EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='public.perfiles'::regclass AND conname='comercial_requiere_pais');
  BEGIN
    INSERT INTO auth.users (id) VALUES (v_uid);
    BEGIN
      INSERT INTO public.perfiles (id, email, nombre_completo, rol, pais_id, activo)
        VALUES (v_uid, 'probe451@example.invalid', 'Probe 451', 'admin_pais', NULL, true);
      GET DIAGNOSTICS v_n = ROW_COUNT;
    EXCEPTION WHEN OTHERS THEN v_err := SQLSTATE; v_msg := SQLERRM; v_n := 0; END;
    v_res := CASE
      WHEN v_err = '23514' AND v_msg LIKE '%admin_pais_requiere_pais%' AND v_viejo AND v_nuevo
        THEN 'BLOQUEADO (CHECK admin_pais_requiere_pais; los 2 constraints coexisten separados)'
      WHEN v_err = '23514' AND NOT (v_viejo AND v_nuevo)
        THEN 'ROJO (cortó un CHECK pero faltan constraints: viejo='||v_viejo||' nuevo='||v_nuevo||')'
      WHEN v_err IS NOT NULL THEN 'ROJO ('||v_err||': '||v_msg||' viejo='||v_viejo||' nuevo='||v_nuevo||')'
      ELSE 'PERMITIDO (admin_pais sin país, filas='||v_n||')' END;
    RAISE EXCEPTION 'PROBE_UNDO';
  EXCEPTION WHEN OTHERS THEN
    IF SQLERRM <> 'PROBE_UNDO' THEN v_fatal := SQLSTATE||' '||SQLERRM; END IF;
  END;
  PERFORM set_config('probe.p451', COALESCE('ROJO (fatal: '||v_fatal||')', v_res, 'ROJO (sin resultado)'), false);
END $$;
SELECT set_config('role','none', true);

-- P452 — CONTRATO: los códigos de catalogo_prospecto_tipo que se solapan con empresas_proveedoras.tipo
-- coinciden EXACTAMENTE. La lista de tipos NO está escrita a mano: sale del CHECK vivo por regexp, así
-- que si alguien agrega un tipo de empresa y no lo replica en el catálogo, esto vira a ROJO solo.
-- De esa coincidencia depende la conversión prospecto -> empresa (el tipo se copia tal cual).
DO $$ DECLARE v_tipos text; v_faltan text; v_extra text; v_n bigint := 0; BEGIN
  IF to_regclass('public.catalogo_prospecto_tipo') IS NULL THEN
    PERFORM set_config('probe.p452','ROJO (objeto ausente: public.catalogo_prospecto_tipo)', false); RETURN;
  END IF;
  SELECT count(*), string_agg(t, ', ' ORDER BY t) INTO v_n, v_tipos FROM (
    SELECT DISTINCT m[1] AS t FROM pg_constraint c,
      LATERAL regexp_matches(pg_get_constraintdef(c.oid), '''([a-z_]+)''::text', 'g') AS m
    WHERE c.conrelid='public.empresas_proveedoras'::regclass AND c.conname='empresas_proveedoras_tipo_check') s;
  SELECT string_agg(t, ', ' ORDER BY t) INTO v_faltan FROM (
    SELECT DISTINCT m[1] AS t FROM pg_constraint c,
      LATERAL regexp_matches(pg_get_constraintdef(c.oid), '''([a-z_]+)''::text', 'g') AS m
    WHERE c.conrelid='public.empresas_proveedoras'::regclass AND c.conname='empresas_proveedoras_tipo_check'
    EXCEPT SELECT codigo FROM public.catalogo_prospecto_tipo WHERE activo) s;
  SELECT string_agg(t, ', ' ORDER BY t) INTO v_extra FROM (
    SELECT codigo AS t FROM public.catalogo_prospecto_tipo WHERE activo
    EXCEPT SELECT DISTINCT m[1] FROM pg_constraint c,
      LATERAL regexp_matches(pg_get_constraintdef(c.oid), '''([a-z_]+)''::text', 'g') AS m
    WHERE c.conrelid='public.empresas_proveedoras'::regclass AND c.conname='empresas_proveedoras_tipo_check') s;
  PERFORM set_config('probe.p452', CASE WHEN v_n > 0 AND v_faltan IS NULL
    THEN 'OK (CHECK vivo ['||v_n||']: '||v_tipos||' | solo-prospección: '||COALESCE(v_extra,'ninguno')||')'
    ELSE 'ROJO (faltan en catálogo: '||COALESCE(v_faltan,'?')||' | CHECK vivo: '||COALESCE(v_tipos,'∅')||')' END, false);
END $$;
SELECT set_config('role','none', true);

-- P453 — catalogo_pipeline_estado: 6 filas, exactamente 2 terminales y órdenes sin duplicados
-- (el orden define la secuencia del pipeline; un duplicado la vuelve ambigua).
DO $$ DECLARE v_n bigint := 0; v_term bigint := 0; v_ord bigint := 0; v_det text; BEGIN
  IF to_regclass('public.catalogo_pipeline_estado') IS NULL THEN
    PERFORM set_config('probe.p453','ROJO (objeto ausente: public.catalogo_pipeline_estado)', false); RETURN;
  END IF;
  SELECT count(*), count(*) FILTER (WHERE es_terminal), count(DISTINCT orden),
         string_agg(codigo||'('||orden||CASE WHEN es_terminal THEN ',T' ELSE '' END||')', ' -> ' ORDER BY orden)
    INTO v_n, v_term, v_ord, v_det FROM public.catalogo_pipeline_estado;
  PERFORM set_config('probe.p453', CASE WHEN v_n = 6 AND v_term = 2 AND v_ord = v_n
    THEN 'OK ('||v_det||')'
    ELSE 'ROJO (filas='||v_n||' terminales='||v_term||' ordenes_distintos='||v_ord||': '||COALESCE(v_det,'∅')||')' END, false);
END $$;
SELECT set_config('role','none', true);

-- P454 — NEG de higiene: como authenticated, INSERT en catalogo_prospecto_tipo denegado.
-- Los default privileges de Supabase dan ALL a authenticated al crear la tabla; sin el REVOKE de la
-- 263 este INSERT pasaría. Se exige que corte el GRANT (permission denied), no la RLS: si cortara la
-- RLS significaría que el REVOKE no se aplicó y solo salva la ausencia de policy de INSERT.
DO $$ DECLARE v_err text; v_msg text; v_n bigint := 0; v_res text; v_fatal text := NULL; BEGIN
  IF to_regclass('public.catalogo_prospecto_tipo') IS NULL THEN
    PERFORM set_config('probe.p454','ROJO (objeto ausente: public.catalogo_prospecto_tipo)', false); RETURN;
  END IF;
  BEGIN
    PERFORM set_config('request.jwt.claims','{"sub":"09d243d5-b222-482a-9762-94a582e9e752","role":"authenticated"}', true);
    BEGIN
      PERFORM set_config('role','authenticated', true);
      INSERT INTO public.catalogo_prospecto_tipo (codigo, etiqueta, orden, activo)
        VALUES ('probe454_intruso', 'Intruso probe 454', 999, true);
      GET DIAGNOSTICS v_n = ROW_COUNT;
      PERFORM set_config('role','none', true);
    EXCEPTION WHEN OTHERS THEN
      PERFORM set_config('role','none', true);
      v_err := SQLSTATE; v_msg := SQLERRM; v_n := 0;
    END;
    v_res := CASE
      WHEN v_msg LIKE '%permission denied%' THEN 'BLOQUEADO (GRANT: '||v_msg||')'
      WHEN v_msg LIKE '%row-level security policy%' THEN 'ROJO (lo frenó la RLS, no el REVOKE: falta el REVOKE de la mig 263)'
      WHEN v_err IS NOT NULL THEN 'ROJO ('||v_err||': '||v_msg||')'
      ELSE 'PERMITIDO (authenticated escribió el catálogo, filas='||v_n||')' END;
    RAISE EXCEPTION 'PROBE_UNDO';
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    IF SQLERRM <> 'PROBE_UNDO' THEN v_fatal := SQLSTATE||' '||SQLERRM; END IF;
  END;
  PERFORM set_config('probe.p454', COALESCE('ROJO (fatal: '||v_fatal||')', v_res, 'ROJO (sin resultado)'), false);
END $$;
SELECT set_config('role','none', true);

-- P455 — POS de higiene: como authenticated, SELECT en los DOS catálogos devuelve las 6 filas activas.
-- Control de que el REVOKE de P454 no se pasó de rosca y dejó los catálogos ilegibles para la app.
DO $$ DECLARE v_err text; v_msg text; v_t bigint := -1; v_p bigint := -1; BEGIN
  IF to_regclass('public.catalogo_prospecto_tipo') IS NULL OR to_regclass('public.catalogo_pipeline_estado') IS NULL THEN
    PERFORM set_config('probe.p455','ROJO (objeto ausente: falta alguno de los dos catálogos)', false); RETURN;
  END IF;
  PERFORM set_config('request.jwt.claims','{"sub":"09d243d5-b222-482a-9762-94a582e9e752","role":"authenticated"}', true);
  BEGIN
    PERFORM set_config('role','authenticated', true);
    SELECT count(*) INTO v_t FROM public.catalogo_prospecto_tipo;
    SELECT count(*) INTO v_p FROM public.catalogo_pipeline_estado;
    PERFORM set_config('role','none', true);
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    v_err := SQLSTATE; v_msg := SQLERRM;
  END;
  PERFORM set_config('probe.p455', CASE
    WHEN v_err IS NULL AND v_t = 6 AND v_p = 6 THEN 'OK (authenticated lee ambos catálogos: 6 y 6)'
    WHEN v_err IS NOT NULL THEN 'ROJO ('||v_err||': '||v_msg||')'
    ELSE 'ROJO (prospecto_tipo='||v_t||' pipeline_estado='||v_p||')' END, false);
END $$;
SELECT set_config('role','none', true);

-- P456 — NEG: como anon los catálogos no se leen (REVOKE ALL FROM anon). Verde = permission denied;
-- se acepta 0 filas sin excepción. Cualquier lectura con filas > 0 es ROJO.
DO $$ DECLARE v_err text; v_msg text; v_t bigint := 0; v_p bigint := 0; BEGIN
  IF to_regclass('public.catalogo_prospecto_tipo') IS NULL OR to_regclass('public.catalogo_pipeline_estado') IS NULL THEN
    PERFORM set_config('probe.p456','ROJO (objeto ausente: falta alguno de los dos catálogos)', false); RETURN;
  END IF;
  PERFORM set_config('request.jwt.claims','{"role":"anon"}', true);
  BEGIN
    PERFORM set_config('role','anon', true);
    SELECT count(*) INTO v_t FROM public.catalogo_prospecto_tipo;
    SELECT count(*) INTO v_p FROM public.catalogo_pipeline_estado;
    PERFORM set_config('role','none', true);
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    v_err := SQLSTATE; v_msg := SQLERRM; v_t := 0; v_p := 0;
  END;
  PERFORM set_config('probe.p456', CASE
    WHEN v_msg LIKE '%permission denied%' THEN 'BLOQUEADO (GRANT: anon sin privilegios)'
    WHEN v_err IS NULL AND v_t = 0 AND v_p = 0 THEN 'BLOQUEADO (0 filas para anon)'
    WHEN v_err IS NOT NULL THEN 'ROJO ('||v_err||': '||v_msg||')'
    ELSE 'PERMITIDO (anon leyó los catálogos: '||v_t||' y '||v_p||')' END, false);
END $$;
SELECT set_config('role','none', true);



-- ===== Bloque 264 · módulo comercial: estructura y lectura (P457–P479) =====
-- Mismo contrato que el harness de escritura: TODO adentro de una transacción que termina en
-- ROLLBACK; el veredicto de cada probe viaja en un setting de sesión y se devuelve como result set.
--
--   BLOQUEADO  → falló por RLS / GRANT / constraint / guard   (VERDE cuando se espera bloqueo)
--   PERMITIDO  → se ejecutó sin bloqueo                        (ROJO cuando se espera bloqueo)
--   OK         → la operación legítima funcionó                (VERDE)
--   ROJO       → el probe encontró algo distinto de lo esperado
--
-- RED-FIRST: cada probe abre con un guard `to_regclass` / `to_regprocedure`. Si la 264 NO está
-- aplicada, el probe reporta 'ROJO (mig 264 sin aplicar)' y sigue — no aborta el harness. Eso hace
-- que el archivo se pueda correr ANTES de aplicar (para capturar el rojo) y DESPUÉS (para el verde).
--
-- NINGUNA SENTENCIA FUERA DE UN HANDLER: cada bloque es un DO con BEGIN…EXCEPTION. Lo único a nivel
-- top-level son los `SELECT set_config('role','none',true)` de saneo entre probes y el result set
-- final. Las fixtures se deshacen con el centinela RAISE 'PROBE_UNDO', que revierte la
-- subtransacción y no deja residuo para los probes siguientes.
--
-- ORIGEN DEL CORTE: 42501 lo comparten la RLS y los GRANT; 23505 el UNIQUE; 23503 la FK; 23514 el
-- CHECK; PA001–PA005 y PA007 el guard de jerarquía; PA006 el guard de coherencia de país del
-- prospecto (trg_prospectos_guard_pais). Cuando dos controles pueden disparar, los probes
-- asertan sobre el MENSAJE además del SQLSTATE — el que corre primero enmascara al otro (lección
-- del bloque 262, P445).
--
-- FIXTURES (namespace propio, todas revertidas):
--   00000000-0000-4264-0462-0000000000NN → suite de normalización
--   00000000-0000-4264-0464-0000000000NN → suite del trigger de jerarquía
--   00000000-0000-4264-0470-0000000000NN → suite de visibilidad
-- PAÍSES REALES usados: GT = cbbbbe6d-59fe-4cf2-91ee-3e31ba1d5909
--                       SV = f2c75b8e-ef54-4a05-b2ff-7363e448f680
-- USUARIOS REALES usados: super_admin 41904e2c-5ef3-4fee-bd48-9ea58e0c8c37
--                         medico      09d243d5-b222-482a-9762-94a582e9e752 (rol NO comercial)

SELECT set_config('role','none', true);

-- ============================================================================
-- ESTRUCTURA (P457–P461)
-- ============================================================================

-- P457 — las 3 tablas existen y tienen RLS habilitada (relrowsecurity).
DO $$
DECLARE v_faltan text; v_sin_rls text;
BEGIN
  SELECT string_agg(t, ', ') INTO v_faltan
    FROM unnest(ARRAY['public.asesores_perfil','public.prospectos','public.prospecto_contactos']) t
   WHERE to_regclass(t) IS NULL;
  IF v_faltan IS NOT NULL THEN
    PERFORM set_config('probe.p457','ROJO (mig 264 sin aplicar; faltan: '||v_faltan||')', false);
    RETURN;
  END IF;
  BEGIN
  SELECT string_agg(c.relname, ', ') INTO v_sin_rls
    FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
   WHERE n.nspname = 'public'
     AND c.relname IN ('asesores_perfil','prospectos','prospecto_contactos')
     AND NOT c.relrowsecurity;
  PERFORM set_config('probe.p457', CASE WHEN v_sin_rls IS NULL
    THEN 'OK (3 tablas presentes, las 3 con RLS habilitada)'
    ELSE 'ROJO (sin RLS: '||v_sin_rls||')' END, false);
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('probe.p457','ROJO (fatal: '||SQLSTATE||' '||SQLERRM||')', false);
  END;
END $$;
SELECT set_config('role','none', true);

-- P458 — higiene de privilegios: authenticated SOLO con SELECT; anon sin NINGÚN privilegio.
-- Los default privileges de Supabase dan ALL a authenticated al crear la tabla: sin el REVOKE de la
-- 264 este probe sale ROJO aunque las policies estén perfectas.
DO $$
DECLARE r record; v_mal text := ''; v_ok_sel int := 0;
BEGIN
  IF to_regclass('public.asesores_perfil') IS NULL THEN
    PERFORM set_config('probe.p458','ROJO (mig 264 sin aplicar)', false); RETURN;
  END IF;
  BEGIN
  FOR r IN SELECT unnest(ARRAY['public.asesores_perfil','public.prospectos','public.prospecto_contactos']) AS t
  LOOP
    IF has_table_privilege('authenticated', r.t, 'SELECT') THEN v_ok_sel := v_ok_sel + 1;
    ELSE v_mal := v_mal || r.t || ':authenticated_sin_SELECT '; END IF;
    IF has_table_privilege('authenticated', r.t, 'INSERT') THEN v_mal := v_mal || r.t || ':authenticated_INSERT '; END IF;
    IF has_table_privilege('authenticated', r.t, 'UPDATE') THEN v_mal := v_mal || r.t || ':authenticated_UPDATE '; END IF;
    IF has_table_privilege('authenticated', r.t, 'DELETE') THEN v_mal := v_mal || r.t || ':authenticated_DELETE '; END IF;
    IF has_table_privilege('anon', r.t, 'SELECT') THEN v_mal := v_mal || r.t || ':anon_SELECT '; END IF;
    IF has_table_privilege('anon', r.t, 'INSERT') THEN v_mal := v_mal || r.t || ':anon_INSERT '; END IF;
    IF has_table_privilege('anon', r.t, 'UPDATE') THEN v_mal := v_mal || r.t || ':anon_UPDATE '; END IF;
    IF has_table_privilege('anon', r.t, 'DELETE') THEN v_mal := v_mal || r.t || ':anon_DELETE '; END IF;
  END LOOP;
  PERFORM set_config('probe.p458', CASE WHEN v_mal = '' AND v_ok_sel = 3
    THEN 'OK (authenticated: SELECT en las 3 y nada más; anon: sin privilegios)'
    ELSE 'ROJO (privilegios de más/de menos: '||v_mal||')' END, false);
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('probe.p458','ROJO (fatal: '||SQLSTATE||' '||SQLERRM||')', false);
  END;
END $$;
SELECT set_config('role','none', true);

-- P459 — CERO policies de escritura. La escritura llega en la 265 por RPC DEFINER; si acá apareciera
-- una policy de INSERT/UPDATE/DELETE/ALL, la superficie de escritura se habría abierto sin diseño.
DO $$
DECLARE v_sel int; v_esc int; v_det text;
BEGIN
  IF to_regclass('public.asesores_perfil') IS NULL THEN
    PERFORM set_config('probe.p459','ROJO (mig 264 sin aplicar)', false); RETURN;
  END IF;
  BEGIN
  SELECT count(*) FILTER (WHERE cmd = 'SELECT'),
         count(*) FILTER (WHERE cmd <> 'SELECT'),
         string_agg(policyname||'['||cmd||']', ', ' ORDER BY tablename, policyname)
    INTO v_sel, v_esc, v_det
    FROM pg_policies
   WHERE schemaname = 'public'
     AND tablename IN ('asesores_perfil','prospectos','prospecto_contactos');
  PERFORM set_config('probe.p459', CASE WHEN v_esc = 0 AND v_sel = 3
    THEN 'OK (3 policies, todas SELECT, cero de escritura: '||v_det||')'
    ELSE 'ROJO (select='||v_sel||' escritura='||v_esc||': '||COALESCE(v_det,'ninguna')||')' END, false);
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('probe.p459','ROJO (fatal: '||SQLSTATE||' '||SQLERRM||')', false);
  END;
END $$;
SELECT set_config('role','none', true);

-- P460 — FKs con ON DELETE RESTRICT (confdeltype='r') en TODO eje de aislamiento, y los 2 UNIQUE.
-- Una FK en CASCADE acá sería borrado de evidencia comercial y una forma silenciosa de mover filas.
DO $$
DECLARE v_fk_total int; v_fk_norestrict text; v_uniq int; v_det text;
BEGIN
  IF to_regclass('public.prospectos') IS NULL THEN
    PERFORM set_config('probe.p460','ROJO (mig 264 sin aplicar)', false); RETURN;
  END IF;
  BEGIN
  SELECT count(*), string_agg(conname||'->'||confdeltype::text, ', ') FILTER (WHERE confdeltype <> 'r')
    INTO v_fk_total, v_fk_norestrict
    FROM pg_constraint
   WHERE contype = 'f'
     AND conrelid IN ('public.asesores_perfil'::regclass,'public.prospectos'::regclass,'public.prospecto_contactos'::regclass);
  SELECT count(*), string_agg(conname, ', ' ORDER BY conname) INTO v_uniq, v_det
    FROM pg_constraint
   WHERE contype = 'u'
     AND conname IN ('asesores_perfil_pais_codigo_uniq','prospectos_pais_nombrenorm_uniq');
  -- 10 FKs esperadas: asesores_perfil 3 (id, pais_id, supervisor_id) + prospectos 6 (pais_id,
  -- asesor_id, tipo, estado_pipeline, empresa_proveedora_id, creado_por) + contactos 1 (prospecto_id).
  PERFORM set_config('probe.p460', CASE WHEN v_fk_norestrict IS NULL AND v_fk_total = 10 AND v_uniq = 2
    THEN 'OK ('||v_fk_total||' FKs, todas ON DELETE RESTRICT; 2 UNIQUE: '||v_det||')'
    ELSE 'ROJO (fks='||v_fk_total||' sin_restrict=['||COALESCE(v_fk_norestrict,'ninguna')||'] uniques='||v_uniq||' ['||COALESCE(v_det,'∅')||'])' END, false);
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('probe.p460','ROJO (fatal: '||SQLSTATE||' '||SQLERRM||')', false);
  END;
END $$;
SELECT set_config('role','none', true);

-- P461 — nombre_norm es GENERATED STORED (attgenerated='s') y la función que la alimenta es IMMUTABLE
-- (provolatile='i'). Si la función no fuera IMMUTABLE, Postgres ni habría dejado crear la columna:
-- el probe existe para detectar el caso en que alguien la reemplace por una STABLE y re-arme la
-- columna a mano, que es como se rompe el significado del UNIQUE.
DO $$
DECLARE v_gen char; v_vol char; v_def text;
BEGIN
  IF to_regclass('public.prospectos') IS NULL OR to_regprocedure('private.norm_prospecto_nombre(text)') IS NULL THEN
    PERFORM set_config('probe.p461','ROJO (mig 264 sin aplicar)', false); RETURN;
  END IF;
  BEGIN
  SELECT a.attgenerated INTO v_gen
    FROM pg_attribute a WHERE a.attrelid = 'public.prospectos'::regclass AND a.attname = 'nombre_norm';
  SELECT p.provolatile INTO v_vol FROM pg_proc p WHERE p.oid = 'private.norm_prospecto_nombre(text)'::regprocedure;
  SELECT pg_get_expr(d.adbin, d.adrelid) INTO v_def
    FROM pg_attrdef d JOIN pg_attribute a ON a.attrelid = d.adrelid AND a.attnum = d.adnum
   WHERE d.adrelid = 'public.prospectos'::regclass AND a.attname = 'nombre_norm';
  PERFORM set_config('probe.p461', CASE
    WHEN v_gen = 's' AND v_vol = 'i' THEN 'OK (nombre_norm GENERATED STORED sobre función IMMUTABLE: '||COALESCE(v_def,'?')||')'
    WHEN v_gen IS DISTINCT FROM 's' THEN 'ROJO (nombre_norm no es GENERATED STORED: attgenerated='||COALESCE(v_gen::text,'∅')||')'
    ELSE 'ROJO (norm_prospecto_nombre no es IMMUTABLE: provolatile='||COALESCE(v_vol::text,'∅')||')' END, false);
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('probe.p461','ROJO (fatal: '||SQLSTATE||' '||SQLERRM||')', false);
  END;
END $$;
SELECT set_config('role','none', true);


-- ============================================================================
-- NORMALIZACIÓN Y DEDUP (P462–P463)
-- Fixture compartida: DOS asesores, uno por país, CADA UNO CON FICHA en asesores_perfil.
-- Las fichas ya no son opcionales: desde PA006 un prospecto solo puede existir si su pais_id coincide
-- con el país de la ficha de su asesor, así que el prospecto de SV necesita un asesor de SV con ficha
-- (con un solo asesor de GT, el insert de P463 moriría en PA006 y no llegaría a medir el UNIQUE).
-- Se revierte con PROBE_UNDO.
-- ============================================================================
DO $$
DECLARE
  v_asGT uuid := '00000000-0000-4264-0462-000000000001';
  v_asSV uuid := '00000000-0000-4264-0462-000000000002';
  v_gt   uuid := 'cbbbbe6d-59fe-4cf2-91ee-3e31ba1d5909';
  v_sv   uuid := 'f2c75b8e-ef54-4a05-b2ff-7363e448f680';
  v_err text; v_msg text; v_n bigint;
  v_462 text; v_463 text; v_fatal text := NULL;
  v_norm1 text; v_norm2 text;
BEGIN
  IF to_regclass('public.prospectos') IS NULL THEN
    PERFORM set_config('probe.p462','ROJO (mig 264 sin aplicar)', false);
    PERFORM set_config('probe.p463','ROJO (mig 264 sin aplicar)', false);
    RETURN;
  END IF;
  BEGIN
    INSERT INTO auth.users (id) VALUES (v_asGT),(v_asSV);
    INSERT INTO public.perfiles (id, email, nombre_completo, rol, pais_id, activo) VALUES
      (v_asGT, 'probe264_462gt@example.invalid', 'Probe 462 GT', 'asesor_comercial', v_gt, true),
      (v_asSV, 'probe264_462sv@example.invalid', 'Probe 462 SV', 'asesor_comercial', v_sv, true);
    INSERT INTO public.asesores_perfil (id, pais_id, codigo_asesor) VALUES
      (v_asGT, v_gt, 'P264-462GT'),
      (v_asSV, v_sv, 'P264-462SV');

    -- P462 — dos grafías del mismo nombre colisionan en el UNIQUE dentro del MISMO país.
    INSERT INTO public.prospectos (pais_id, asesor_id, tipo, nombre, creado_por)
      VALUES (v_gt, v_asGT, 'laboratorio_farmaceutico', 'Laboratorios  Fármaco, S.A.', v_asGT);
    SELECT nombre_norm INTO v_norm1 FROM public.prospectos WHERE pais_id = v_gt AND asesor_id = v_asGT;

    v_err := NULL; v_msg := NULL; v_n := 0;
    BEGIN
      INSERT INTO public.prospectos (pais_id, asesor_id, tipo, nombre, creado_por)
        VALUES (v_gt, v_asGT, 'laboratorio_farmaceutico', 'laboratorios farmaco sa', v_asGT);
      GET DIAGNOSTICS v_n = ROW_COUNT;
    EXCEPTION WHEN OTHERS THEN v_err := SQLSTATE; v_msg := SQLERRM; v_n := 0; END;
    v_462 := CASE
      WHEN v_err = '23505' AND v_msg LIKE '%prospectos_pais_nombrenorm_uniq%'
        THEN 'BLOQUEADO (UNIQUE pais+nombre_norm; ambas normalizan a "'||COALESCE(v_norm1,'?')||'")'
      WHEN v_err = '23505' THEN 'ROJO (23505 pero de otro constraint: '||v_msg||')'
      WHEN v_err IS NOT NULL THEN 'ROJO ('||v_err||': '||v_msg||')'
      ELSE 'PERMITIDO (el duplicado entró, filas='||v_n||'; norm="'||COALESCE(v_norm1,'?')||'")' END;

    -- P463 — el MISMO nombre en OTRO país NO colisiona: el dedup es por país, no global.
    -- Usa el asesor de SV (con ficha de SV): el par (prospecto SV, asesor SV) es coherente para PA006.
    v_err := NULL; v_msg := NULL; v_n := 0;
    BEGIN
      INSERT INTO public.prospectos (pais_id, asesor_id, tipo, nombre, creado_por)
        VALUES (v_sv, v_asSV, 'laboratorio_farmaceutico', 'Laboratorios Fármaco S.A.', v_asSV);
      GET DIAGNOSTICS v_n = ROW_COUNT;
    EXCEPTION WHEN OTHERS THEN v_err := SQLSTATE; v_msg := SQLERRM; v_n := 0; END;
    SELECT nombre_norm INTO v_norm2 FROM public.prospectos WHERE pais_id = v_sv;
    v_463 := CASE
      WHEN v_err IS NULL AND v_n = 1 AND v_norm2 = v_norm1
        THEN 'OK (mismo nombre_norm "'||v_norm2||'" en 2 países, sin colisión: el UNIQUE es por país)'
      WHEN v_err = '23505' THEN 'ROJO (colisionó entre países: el UNIQUE no incluye pais_id)'
      WHEN v_err = 'PA006' THEN 'ROJO (PA006: la fixture quedó incoherente, no es un fallo del UNIQUE)'
      WHEN v_err IS NOT NULL THEN 'ROJO ('||v_err||': '||v_msg||')'
      ELSE 'ROJO (filas='||v_n||' norm_gt="'||COALESCE(v_norm1,'?')||'" norm_sv="'||COALESCE(v_norm2,'?')||'")' END;

    RAISE EXCEPTION 'PROBE_UNDO';
  EXCEPTION WHEN OTHERS THEN
    IF SQLERRM <> 'PROBE_UNDO' THEN v_fatal := SQLSTATE||' '||SQLERRM; END IF;
  END;
  PERFORM set_config('probe.p462', COALESCE('ROJO (fatal: '||v_fatal||')', v_462, 'ROJO (sin resultado)'), false);
  PERFORM set_config('probe.p463', COALESCE('ROJO (fatal: '||v_fatal||')', v_463, 'ROJO (sin resultado)'), false);
END $$;
SELECT set_config('role','none', true);


-- ============================================================================
-- TRIGGER DE JERARQUÍA (P464–P469) — un caso negativo por ERRCODE + un positivo.
-- Fixture compartida. Recordar el orden documentado en la 264: PA005 se evalúa ANTES del corte por
-- supervisor_id IS NULL, así que enmascara a PA001–PA004 cuando el propio rol es supervisor.
-- ============================================================================
DO $$
DECLARE
  v_gt uuid := 'cbbbbe6d-59fe-4cf2-91ee-3e31ba1d5909';
  v_sv uuid := 'f2c75b8e-ef54-4a05-b2ff-7363e448f680';
  v_medico uuid := '09d243d5-b222-482a-9762-94a582e9e752';   -- rol 'medico' real: NO es supervisor
  -- fixtures
  v_supOK   uuid := '00000000-0000-4264-0464-000000000001';  -- supervisor GT válido (ficha activa, sin jefe)
  v_supSinF uuid := '00000000-0000-4264-0464-000000000002';  -- supervisor GT SIN ficha
  v_supOff  uuid := '00000000-0000-4264-0464-000000000003';  -- supervisor GT con ficha INACTIVA
  v_supSV   uuid := '00000000-0000-4264-0464-000000000004';  -- supervisor SV (otro país)
  v_supEnc  uuid := '00000000-0000-4264-0464-000000000005';  -- supervisor GT que cuelga de otro (encadenado)
  v_as      uuid := '00000000-0000-4264-0464-000000000010';  -- el asesor bajo prueba
  v_asSup   uuid := '00000000-0000-4264-0464-000000000011';  -- perfil con rol supervisor (para PA005)
  v_err text; v_msg text; v_n bigint;
  v_464 text; v_465a text; v_465b text; v_466 text; v_467 text; v_468 text; v_469 text;
  v_478 text; v_479 text;
  v_fatal text := NULL;
BEGIN
  IF to_regclass('public.asesores_perfil') IS NULL THEN
    PERFORM set_config('probe.p464','ROJO (mig 264 sin aplicar)', false);
    PERFORM set_config('probe.p465a','ROJO (mig 264 sin aplicar)', false);
    PERFORM set_config('probe.p465b','ROJO (mig 264 sin aplicar)', false);
    PERFORM set_config('probe.p466','ROJO (mig 264 sin aplicar)', false);
    PERFORM set_config('probe.p467','ROJO (mig 264 sin aplicar)', false);
    PERFORM set_config('probe.p468','ROJO (mig 264 sin aplicar)', false);
    PERFORM set_config('probe.p469','ROJO (mig 264 sin aplicar)', false);
    PERFORM set_config('probe.p478','ROJO (mig 264 sin aplicar)', false);
    PERFORM set_config('probe.p479','ROJO (mig 264 sin aplicar)', false);
    RETURN;
  END IF;
  BEGIN
    -- ---------- fixture: perfiles ----------
    INSERT INTO auth.users (id) VALUES (v_supOK),(v_supSinF),(v_supOff),(v_supSV),(v_supEnc),(v_as),(v_asSup);
    INSERT INTO public.perfiles (id, email, nombre_completo, rol, pais_id, activo) VALUES
      (v_supOK,  'probe264_sup_ok@example.invalid',   'Sup OK GT',      'supervisor_comercial', v_gt, true),
      (v_supSinF,'probe264_sup_sinf@example.invalid', 'Sup sin ficha',  'supervisor_comercial', v_gt, true),
      (v_supOff, 'probe264_sup_off@example.invalid',  'Sup inactivo',   'supervisor_comercial', v_gt, true),
      (v_supSV,  'probe264_sup_sv@example.invalid',   'Sup SV',         'supervisor_comercial', v_sv, true),
      (v_supEnc, 'probe264_sup_enc@example.invalid',  'Sup encadenado', 'supervisor_comercial', v_gt, true),
      (v_as,     'probe264_asesor@example.invalid',   'Asesor prueba',  'asesor_comercial',     v_gt, true),
      (v_asSup,  'probe264_selfsup@example.invalid',  'Self supervisor','supervisor_comercial', v_gt, true);

    -- ---------- fixture: fichas ----------
    INSERT INTO public.asesores_perfil (id, pais_id, codigo_asesor, activo) VALUES
      (v_supOK,  v_gt, 'P264-SUPOK',  true),
      (v_supOff, v_gt, 'P264-SUPOFF', false),
      (v_supSV,  v_sv, 'P264-SUPSV',  true);
    -- El supervisor "encadenado" es imposible de crear con el trigger puesto (daría PA005): se lo
    -- siembra deshabilitando el trigger como owner. Es exactamente el escenario que PA004 vigila
    -- cuando el dato llega por una vía que no pasa por el guard.
    ALTER TABLE public.asesores_perfil DISABLE TRIGGER trg_asesores_perfil_guard_supervisor;
    INSERT INTO public.asesores_perfil (id, pais_id, codigo_asesor, activo, supervisor_id)
      VALUES (v_supEnc, v_gt, 'P264-SUPENC', true, v_supOK);
    ALTER TABLE public.asesores_perfil ENABLE TRIGGER trg_asesores_perfil_guard_supervisor;

    -- ---------- P464: PA001 — el supervisor no tiene rol supervisor_comercial ----------
    v_err := NULL; v_msg := NULL;
    BEGIN
      INSERT INTO public.asesores_perfil (id, pais_id, codigo_asesor, supervisor_id)
        VALUES (v_as, v_gt, 'P264-A1', v_medico);
    EXCEPTION WHEN OTHERS THEN v_err := SQLSTATE; v_msg := SQLERRM; END;
    v_464 := CASE WHEN v_err = 'PA001' THEN 'BLOQUEADO (PA001: '||v_msg||')'
                  WHEN v_err IS NOT NULL THEN 'ROJO ('||v_err||': '||v_msg||')'
                  ELSE 'PERMITIDO (aceptó un supervisor con rol medico)' END;

    -- ---------- P465a: PA002 — supervisor sin ficha en asesores_perfil ----------
    v_err := NULL; v_msg := NULL;
    BEGIN
      INSERT INTO public.asesores_perfil (id, pais_id, codigo_asesor, supervisor_id)
        VALUES (v_as, v_gt, 'P264-A2', v_supSinF);
    EXCEPTION WHEN OTHERS THEN v_err := SQLSTATE; v_msg := SQLERRM; END;
    v_465a := CASE WHEN v_err = 'PA002' THEN 'BLOQUEADO (PA002 sin ficha: '||v_msg||')'
                   WHEN v_err IS NOT NULL THEN 'ROJO ('||v_err||': '||v_msg||')'
                   ELSE 'PERMITIDO (aceptó un supervisor sin ficha)' END;

    -- ---------- P465b: PA002 — supervisor con ficha INACTIVA ----------
    v_err := NULL; v_msg := NULL;
    BEGIN
      INSERT INTO public.asesores_perfil (id, pais_id, codigo_asesor, supervisor_id)
        VALUES (v_as, v_gt, 'P264-A3', v_supOff);
    EXCEPTION WHEN OTHERS THEN v_err := SQLSTATE; v_msg := SQLERRM; END;
    v_465b := CASE WHEN v_err = 'PA002' THEN 'BLOQUEADO (PA002 ficha inactiva: '||v_msg||')'
                   WHEN v_err IS NOT NULL THEN 'ROJO ('||v_err||': '||v_msg||')'
                   ELSE 'PERMITIDO (aceptó un supervisor con ficha inactiva)' END;

    -- ---------- P466: PA003 — supervisor de OTRO país (el vector de fuga) ----------
    v_err := NULL; v_msg := NULL;
    BEGIN
      INSERT INTO public.asesores_perfil (id, pais_id, codigo_asesor, supervisor_id)
        VALUES (v_as, v_gt, 'P264-A4', v_supSV);
    EXCEPTION WHEN OTHERS THEN v_err := SQLSTATE; v_msg := SQLERRM; END;
    v_466 := CASE WHEN v_err = 'PA003' THEN 'BLOQUEADO (PA003 cross-país: '||v_msg||')'
                  WHEN v_err IS NOT NULL THEN 'ROJO ('||v_err||': '||v_msg||')'
                  ELSE 'PERMITIDO (la jerarquía cruzó países — ES EL VECTOR DE FUGA)' END;

    -- ---------- P467: PA004 — el supervisor cuelga a su vez de otro ----------
    v_err := NULL; v_msg := NULL;
    BEGIN
      INSERT INTO public.asesores_perfil (id, pais_id, codigo_asesor, supervisor_id)
        VALUES (v_as, v_gt, 'P264-A5', v_supEnc);
    EXCEPTION WHEN OTHERS THEN v_err := SQLSTATE; v_msg := SQLERRM; END;
    v_467 := CASE WHEN v_err = 'PA004' THEN 'BLOQUEADO (PA004 cadena de 3 niveles: '||v_msg||')'
                  WHEN v_err IS NOT NULL THEN 'ROJO ('||v_err||': '||v_msg||')'
                  ELSE 'PERMITIDO (armó una cadena de 3 niveles)' END;

    -- ---------- P468: PA005 — el propio perfil es supervisor y trae supervisor_id ----------
    -- Nota de orden: acá el supervisor apuntado es VÁLIDO; lo único mal es que el titular de la ficha
    -- es supervisor_comercial. Si saliera PA001..PA004 en vez de PA005, el orden documentado cambió.
    v_err := NULL; v_msg := NULL;
    BEGIN
      INSERT INTO public.asesores_perfil (id, pais_id, codigo_asesor, supervisor_id)
        VALUES (v_asSup, v_gt, 'P264-A6', v_supOK);
    EXCEPTION WHEN OTHERS THEN v_err := SQLSTATE; v_msg := SQLERRM; END;
    v_468 := CASE WHEN v_err = 'PA005' THEN 'BLOQUEADO (PA005 supervisor no cuelga de nadie: '||v_msg||')'
                  WHEN v_err IS NOT NULL THEN 'ROJO ('||v_err||': '||v_msg||')'
                  ELSE 'PERMITIDO (un supervisor_comercial quedó colgado de otro)' END;

    -- ---------- P469: POSITIVO — supervisor válido del mismo país, activo, sin jefe propio ----------
    v_err := NULL; v_msg := NULL;
    BEGIN
      INSERT INTO public.asesores_perfil (id, pais_id, codigo_asesor, supervisor_id)
        VALUES (v_as, v_gt, 'P264-A7', v_supOK);
    EXCEPTION WHEN OTHERS THEN v_err := SQLSTATE; v_msg := SQLERRM; END;
    v_469 := CASE WHEN v_err IS NULL THEN 'OK (alta legítima con supervisor válido del mismo país)'
                  ELSE 'ROJO (el guard bloqueó un alta legítima: '||v_err||' '||v_msg||')' END;

    -- ---------- P478: PA007 — no se mueve de país a un supervisor CON asesores a cargo ----------
    -- ESTE ES EL AGUJERO SIMÉTRICO DE PA003. Tras P469, v_supOK tiene un subordinado (v_as), los dos
    -- en GT. Sin PA007, este UPDATE pasaba: el trigger dispara sobre la fila del supervisor, que no
    -- tiene supervisor_id, y salía por el corte por NULL sin validar nada — dejando a v_as apuntando
    -- a un supervisor de SV. O sea: el estado que PA003 prohíbe, alcanzado por la puerta de al lado.
    v_err := NULL; v_msg := NULL; v_n := 0;
    BEGIN
      UPDATE public.asesores_perfil SET pais_id = v_sv WHERE id = v_supOK;
      GET DIAGNOSTICS v_n = ROW_COUNT;
    EXCEPTION WHEN OTHERS THEN v_err := SQLSTATE; v_msg := SQLERRM; v_n := 0; END;
    v_478 := CASE WHEN v_err = 'PA007' THEN 'BLOQUEADO (PA007: '||v_msg||')'
                  WHEN v_err IS NOT NULL THEN 'ROJO ('||v_err||': '||v_msg||')'
                  ELSE 'PERMITIDO — FAIL-OPEN (movió de país a un supervisor con equipo, filas='||v_n||'; sus asesores quedaron cross-país)' END;

    -- ---------- P479: POSITIVO de PA007 — SIN subordinados, el cambio de país sí procede ----------
    -- Control de que PA007 no se pasó de rosca: v_supSV no tiene a nadie a cargo, así que moverlo de
    -- país es una operación legítima y tiene que pasar. Si esto se pone rojo, PA007 quedó demasiado
    -- ancho y bloquea altas/correcciones normales.
    v_err := NULL; v_msg := NULL; v_n := 0;
    BEGIN
      UPDATE public.asesores_perfil SET pais_id = v_gt WHERE id = v_supSV;
      GET DIAGNOSTICS v_n = ROW_COUNT;
    EXCEPTION WHEN OTHERS THEN v_err := SQLSTATE; v_msg := SQLERRM; v_n := 0; END;
    v_479 := CASE WHEN v_err IS NULL AND v_n = 1 THEN 'OK (ficha sin subordinados cambia de país, filas=1)'
                  WHEN v_err = 'PA007' THEN 'ROJO (PA007 demasiado ancho: bloqueó una ficha SIN subordinados)'
                  WHEN v_err IS NOT NULL THEN 'ROJO ('||v_err||': '||v_msg||')'
                  ELSE 'ROJO (filas='||v_n||')' END;

    RAISE EXCEPTION 'PROBE_UNDO';
  EXCEPTION WHEN OTHERS THEN
    IF SQLERRM <> 'PROBE_UNDO' THEN v_fatal := SQLSTATE||' '||SQLERRM; END IF;
  END;
  PERFORM set_config('probe.p464',  COALESCE('ROJO (fatal: '||v_fatal||')', v_464,  'ROJO (sin resultado)'), false);
  PERFORM set_config('probe.p465a', COALESCE('ROJO (fatal: '||v_fatal||')', v_465a, 'ROJO (sin resultado)'), false);
  PERFORM set_config('probe.p465b', COALESCE('ROJO (fatal: '||v_fatal||')', v_465b, 'ROJO (sin resultado)'), false);
  PERFORM set_config('probe.p466',  COALESCE('ROJO (fatal: '||v_fatal||')', v_466,  'ROJO (sin resultado)'), false);
  PERFORM set_config('probe.p467',  COALESCE('ROJO (fatal: '||v_fatal||')', v_467,  'ROJO (sin resultado)'), false);
  PERFORM set_config('probe.p468',  COALESCE('ROJO (fatal: '||v_fatal||')', v_468,  'ROJO (sin resultado)'), false);
  PERFORM set_config('probe.p469',  COALESCE('ROJO (fatal: '||v_fatal||')', v_469,  'ROJO (sin resultado)'), false);
  PERFORM set_config('probe.p478',  COALESCE('ROJO (fatal: '||v_fatal||')', v_478,  'ROJO (sin resultado)'), false);
  PERFORM set_config('probe.p479',  COALESCE('ROJO (fatal: '||v_fatal||')', v_479,  'ROJO (sin resultado)'), false);
END $$;
SELECT set_config('role','none', true);


-- ============================================================================
-- VISIBILIDAD (P470–P477) — el núcleo del bloque.
--
-- FIXTURE: 2 países (GT / SV), 2 supervisores en GT + 1 en SV, 4 asesores, 1 asesor "rogue"
-- sembrado saltando el trigger, y 6 prospectos repartidos.
--
--   GT: supA ── asA1, asA2          (+ cartera propia de supA)
--       supA2 ── asA3
--       rogue  (país GT, supervisor_id = supB de SV — sembrado con el trigger deshabilitado)
--   SV: supB ── asB1
--
-- Prospectos: pA1(asA1) pA2(asA2) pA3(asA3) pSupA(supA) pRogue(rogue) → todos GT
--             pB1(asB1) → SV
-- El prospecto incoherente YA NO SE SIEMBRA: desde PA006 no se puede escribir, y P477 pasó a ser el
-- negativo que lo comprueba (intenta insertarlo y espera PA006) en vez de un conteo de fuga.
--
-- Todas las mediciones se hacen con `role=authenticated` + jwt del viewer, que es la única forma de
-- que la RLS realmente se evalúe (como owner, RLS no aplica y todo probe daría verde falso).
-- ============================================================================
DO $$
DECLARE
  v_gt uuid := 'cbbbbe6d-59fe-4cf2-91ee-3e31ba1d5909';
  v_sv uuid := 'f2c75b8e-ef54-4a05-b2ff-7363e448f680';
  v_sa uuid := '41904e2c-5ef3-4fee-bd48-9ea58e0c8c37';        -- super_admin real
  v_med uuid := '09d243d5-b222-482a-9762-94a582e9e752';        -- medico real (rol NO comercial)
  v_supA   uuid := '00000000-0000-4264-0470-000000000001';
  v_supA2  uuid := '00000000-0000-4264-0470-000000000002';
  v_supB   uuid := '00000000-0000-4264-0470-000000000003';
  v_asA1   uuid := '00000000-0000-4264-0470-000000000011';
  v_asA2   uuid := '00000000-0000-4264-0470-000000000012';
  v_asA3   uuid := '00000000-0000-4264-0470-000000000013';
  v_asB1   uuid := '00000000-0000-4264-0470-000000000014';
  v_rogue  uuid := '00000000-0000-4264-0470-000000000099';
  v_admA   uuid := '00000000-0000-4264-0470-0000000000a1';
  v_admB   uuid := '00000000-0000-4264-0470-0000000000b1';
  v_pA1 uuid; v_pRogue uuid;
  r record;
  v_res jsonb := '{}'::jsonb;
  v_pros bigint; v_ases bigint; v_cont bigint; v_cargo bigint; v_nom text;
  v_err text; v_msg text; v_n bigint;
  v_fatal text := NULL;
  v_ok boolean;
  -- Los veredictos van a VARIABLES y se publican con set_config DESPUES del bloque: un
  -- set_config dentro de la subtransaccion lo revierte el RAISE 'PROBE_UNDO' junto con las fixtures.
  v_470 text; v_471 text; v_472 text; v_473 text; v_474 text; v_475 text; v_476 text; v_477 text;
BEGIN
  IF to_regclass('public.prospectos') IS NULL OR to_regprocedure('private.asesores_a_cargo()') IS NULL THEN
    PERFORM set_config('probe.p470','ROJO (mig 264 sin aplicar)', false);
    PERFORM set_config('probe.p471','ROJO (mig 264 sin aplicar)', false);
    PERFORM set_config('probe.p472','ROJO (mig 264 sin aplicar)', false);
    PERFORM set_config('probe.p473','ROJO (mig 264 sin aplicar)', false);
    PERFORM set_config('probe.p474','ROJO (mig 264 sin aplicar)', false);
    PERFORM set_config('probe.p475','ROJO (mig 264 sin aplicar)', false);
    PERFORM set_config('probe.p476','ROJO (mig 264 sin aplicar)', false);
    PERFORM set_config('probe.p477','ROJO (mig 264 sin aplicar)', false);
    RETURN;
  END IF;
  BEGIN
    -- ---------- perfiles ----------
    INSERT INTO auth.users (id) VALUES
      (v_supA),(v_supA2),(v_supB),(v_asA1),(v_asA2),(v_asA3),(v_asB1),(v_rogue),(v_admA),(v_admB);
    INSERT INTO public.perfiles (id, email, nombre_completo, rol, pais_id, activo) VALUES
      (v_supA, 'p264_supA@example.invalid',  'Sup A GT',   'supervisor_comercial', v_gt, true),
      (v_supA2,'p264_supA2@example.invalid', 'Sup A2 GT',  'supervisor_comercial', v_gt, true),
      (v_supB, 'p264_supB@example.invalid',  'Sup B SV',   'supervisor_comercial', v_sv, true),
      (v_asA1, 'p264_asA1@example.invalid',  'Asesor A1',  'asesor_comercial',     v_gt, true),
      (v_asA2, 'p264_asA2@example.invalid',  'Asesor A2',  'asesor_comercial',     v_gt, true),
      (v_asA3, 'p264_asA3@example.invalid',  'Asesor A3',  'asesor_comercial',     v_gt, true),
      (v_asB1, 'p264_asB1@example.invalid',  'Asesor B1',  'asesor_comercial',     v_sv, true),
      (v_rogue,'p264_rogue@example.invalid', 'Asesor rogue','asesor_comercial',    v_gt, true),
      (v_admA, 'p264_admA@example.invalid',  'Admin GT',   'admin_pais',           v_gt, true),
      (v_admB, 'p264_admB@example.invalid',  'Admin SV',   'admin_pais',           v_sv, true);

    -- ---------- fichas ----------
    INSERT INTO public.asesores_perfil (id, pais_id, codigo_asesor, supervisor_id) VALUES
      (v_supA,  v_gt, 'P264-SUPA',  NULL),
      (v_supA2, v_gt, 'P264-SUPA2', NULL),
      (v_supB,  v_sv, 'P264-SUPB',  NULL);
    INSERT INTO public.asesores_perfil (id, pais_id, codigo_asesor, supervisor_id) VALUES
      (v_asA1, v_gt, 'P264-ASA1', v_supA),
      (v_asA2, v_gt, 'P264-ASA2', v_supA),
      (v_asA3, v_gt, 'P264-ASA3', v_supA2),
      (v_asB1, v_sv, 'P264-ASB1', v_supB);
    -- ROGUE: asesor de GT colgado de un supervisor de SV. El trigger lo prohíbe (PA003), así que se
    -- siembra por SQL directo con el trigger deshabilitado — que es justo el escenario que el
    -- centinela P475 tiene que sobrevivir: dato corrupto en la jerarquía, y el país cortando igual.
    -- (Con PA007 puesto, la otra vía para llegar a este estado —crear la jerarquía en GT y después
    --  mover de país al supervisor— quedó cerrada, así que el DISABLE TRIGGER es la única forma de
    --  sembrarlo. Ver P478.)
    --
    -- ⚠️ CAVEAT DEL DISABLE TRIGGER: `ALTER TABLE ... DISABLE TRIGGER` toma un lock ACCESS EXCLUSIVE
    -- sobre asesores_perfil que se sostiene hasta el final de la transacción del harness. HOY es
    -- inocuo porque la tabla está vacía y sin tráfico (maquinaria inerte). El día que tenga datos y
    -- lectores reales, este probe hay que revisarlo: bloquearía la tabla entera mientras corre el
    -- harness. Alternativas para ese momento: sembrar el rogue con una función DEFINER que haga el
    -- INSERT sin pasar por el trigger, o mover este probe a un entorno de staging.
    ALTER TABLE public.asesores_perfil DISABLE TRIGGER trg_asesores_perfil_guard_supervisor;
    INSERT INTO public.asesores_perfil (id, pais_id, codigo_asesor, supervisor_id)
      VALUES (v_rogue, v_gt, 'P264-ROGUE', v_supB);
    ALTER TABLE public.asesores_perfil ENABLE TRIGGER trg_asesores_perfil_guard_supervisor;

    -- ---------- prospectos ----------
    INSERT INTO public.prospectos (pais_id, asesor_id, tipo, nombre, creado_por) VALUES
      (v_gt, v_asA1,  'laboratorio_farmaceutico', 'P264 Prospecto A1',    v_asA1),
      (v_gt, v_asA2,  'farmacia',                 'P264 Prospecto A2',    v_asA2),
      (v_gt, v_asA3,  'clinica',                  'P264 Prospecto A3',    v_asA3),
      (v_gt, v_supA,  'empresa_afin',             'P264 Prospecto SupA',  v_supA),
      (v_gt, v_rogue, 'farmacia',                 'P264 Prospecto Rogue', v_rogue),
      (v_sv, v_asB1,  'laboratorio_clinico',      'P264 Prospecto B1',    v_asB1);

    SELECT id INTO v_pA1    FROM public.prospectos WHERE nombre = 'P264 Prospecto A1';
    SELECT id INTO v_pRogue FROM public.prospectos WHERE nombre = 'P264 Prospecto Rogue';

    -- ---------- contactos ----------
    INSERT INTO public.prospecto_contactos (prospecto_id, nombre, es_decisor)
      VALUES (v_pA1, 'Contacto de A1', true), (v_pRogue, 'Contacto de Rogue', false);

    -- ---------- MEDICIONES: un pase por cada viewer, cada uno en su propio handler ----------
    FOR r IN
      SELECT * FROM (VALUES
        ('asA1', v_asA1), ('supA', v_supA), ('supA2', v_supA2), ('supB', v_supB),
        ('admA', v_admA), ('admB', v_admB), ('super', v_sa),   ('medico', v_med)
      ) t(etq, uid)
    LOOP
      v_pros := -1; v_ases := -1; v_cont := -1; v_cargo := -1; v_nom := NULL;
      BEGIN
        PERFORM set_config('request.jwt.claims',
                 json_build_object('sub', r.uid::text, 'role','authenticated')::text, true);
        PERFORM set_config('role','authenticated', true);
        SELECT count(*) INTO v_cargo FROM private.asesores_a_cargo();
        SELECT count(*) INTO v_ases  FROM public.asesores_perfil;
        SELECT count(*) INTO v_cont  FROM public.prospecto_contactos;
        SELECT count(*), string_agg(replace(nombre,'P264 Prospecto ',''), ',' ORDER BY nombre)
          INTO v_pros, v_nom FROM public.prospectos;
        PERFORM set_config('role','none', true);
      EXCEPTION WHEN OTHERS THEN
        PERFORM set_config('role','none', true);
        v_nom := 'ERROR '||SQLSTATE||' '||SQLERRM;
      END;
      v_res := v_res || jsonb_build_object(r.etq, jsonb_build_object(
        'pros', v_pros, 'ases', v_ases, 'cont', v_cont, 'cargo', v_cargo,
        'nombres', COALESCE(v_nom,'∅')));
    END LOOP;
    PERFORM set_config('role','none', true);

    -- ---------- P470: el asesor ve SOLO sus prospectos ----------
    v_ok := (v_res#>>'{asA1,pros}')::bigint = 1 AND (v_res#>>'{asA1,nombres}') = 'A1'
        AND (v_res#>>'{asA1,cargo}')::bigint = 1;
    v_470 := CASE WHEN v_ok
      THEN 'OK (asesor ve 1 prospecto, el propio; cargo=1)'
      ELSE 'ROJO (asA1 pros='||(v_res#>>'{asA1,pros}')||' cargo='||(v_res#>>'{asA1,cargo}')||' ve=['||(v_res#>>'{asA1,nombres}')||'])' END;

    -- ---------- P471: el supervisor ve los de SUS asesores + los propios, y NO los del otro ----------
    -- supA ve A1,A2,SupA (3) y NO A3 (que es de supA2). supA2 ve A3 + nada propio (1).
    v_ok := (v_res#>>'{supA,pros}')::bigint = 3
        AND (v_res#>>'{supA,nombres}') = 'A1,A2,SupA'
        AND (v_res#>>'{supA2,pros}')::bigint = 1
        AND (v_res#>>'{supA2,nombres}') = 'A3';
    v_471 := CASE WHEN v_ok
      THEN 'OK (supA ve [A1,A2,SupA] y NO A3; supA2 ve [A3] — carteras de supervisores aisladas)'
      ELSE 'ROJO (supA='||(v_res#>>'{supA,pros}')||' ['||(v_res#>>'{supA,nombres}')||'] supA2='||(v_res#>>'{supA2,pros}')||' ['||(v_res#>>'{supA2,nombres}')||'])' END;

    -- ---------- P472: admin_pais ve TODOS los de su país y NINGUNO del otro ----------
    -- admA (GT) ve A1,A2,A3,Rogue,SupA = 5 y nada de SV. admB (SV) ve solo B1.
    v_ok := (v_res#>>'{admA,pros}')::bigint = 5
        AND (v_res#>>'{admA,nombres}') = 'A1,A2,A3,Rogue,SupA'
        AND (v_res#>>'{admB,nombres}') NOT LIKE '%A1%'
        AND (v_res#>>'{admB,nombres}') NOT LIKE '%A3%';
    v_472 := CASE WHEN v_ok
      THEN 'OK (admin GT ve los 5 de GT; admin SV no ve ninguno de GT — ve ['||(v_res#>>'{admB,nombres}')||'])'
      ELSE 'ROJO (admA='||(v_res#>>'{admA,pros}')||' ['||(v_res#>>'{admA,nombres}')||'] admB='||(v_res#>>'{admB,pros}')||' ['||(v_res#>>'{admB,nombres}')||'])' END;

    -- ---------- P473: super_admin ve todos (6) ----------
    v_ok := (v_res#>>'{super,pros}')::bigint = 6;
    v_473 := CASE WHEN v_ok
      THEN 'OK (super_admin ve los 6 sin término de país)'
      ELSE 'ROJO (super_admin ve '||(v_res#>>'{super,pros}')||': ['||(v_res#>>'{super,nombres}')||'])' END;

    -- ---------- P474: un rol NO comercial ve CERO y su asesores_a_cargo() es vacío ----------
    v_ok := (v_res#>>'{medico,pros}')::bigint = 0
        AND (v_res#>>'{medico,ases}')::bigint = 0
        AND (v_res#>>'{medico,cont}')::bigint = 0
        AND (v_res#>>'{medico,cargo}')::bigint = 0;
    v_474 := CASE WHEN v_ok
      THEN 'OK (medico: 0 prospectos, 0 fichas, 0 contactos, asesores_a_cargo() vacío — fail-closed)'
      ELSE 'ROJO (medico pros='||(v_res#>>'{medico,pros}')||' ases='||(v_res#>>'{medico,ases}')||' cont='||(v_res#>>'{medico,cont}')||' cargo='||(v_res#>>'{medico,cargo}')||')' END;

    -- ---------- P475: CENTINELA DE FAIL-OPEN — el doble candado ----------
    -- supB (SV) tiene al rogue (GT) dentro de asesores_a_cargo() por el supervisor_id corrupto.
    -- El término de país tiene que cortarlo igual: ni la ficha ni el prospecto del rogue deben
    -- aparecer. Si este probe se pone rojo, el país dejó de ser conjuntivo y la jerarquía volvió a
    -- ser el vector de fuga.
    v_ok := (v_res#>>'{supB,nombres}') NOT LIKE '%Rogue%'
        AND (v_res#>>'{supB,ases}')::bigint = 2          -- solo supB + asB1 (NO el rogue de GT)
        AND (v_res#>>'{supB,cargo}')::bigint = 3;        -- el chokepoint SÍ lo incluye: 3
    v_475 := CASE WHEN v_ok
      THEN 'BLOQUEADO (doble candado: asesores_a_cargo()=3 incluye al rogue, pero el país lo corta — fichas visibles=2, prospectos=['||(v_res#>>'{supB,nombres}')||'] sin Rogue)'
      ELSE 'ROJO — FAIL-OPEN (supB cargo='||(v_res#>>'{supB,cargo}')||' fichas='||(v_res#>>'{supB,ases}')||' ve=['||(v_res#>>'{supB,nombres}')||'])' END;

    -- ---------- P476: los contactos heredan el gate del prospecto ----------
    -- asA1 ve 1 contacto (el de su prospecto) y no el del rogue; medico ve 0; super_admin ve los 2.
    v_ok := (v_res#>>'{asA1,cont}')::bigint = 1
        AND (v_res#>>'{medico,cont}')::bigint = 0
        AND (v_res#>>'{super,cont}')::bigint = 2;
    v_476 := CASE WHEN v_ok
      THEN 'OK (contactos heredan el gate vía prospecto_visible(): asesor 1, medico 0, super_admin 2)'
      ELSE 'ROJO (asA1='||(v_res#>>'{asA1,cont}')||' medico='||(v_res#>>'{medico,cont}')||' super='||(v_res#>>'{super,cont}')||')' END;

    -- ---------- P477: PA006 — el prospecto con país incoherente NO SE PUEDE ESCRIBIR ----------
    -- Escenario exacto que sin PA006 filtraba: prospecto marcado en SV cuyo asesor (rogue) es de GT
    -- pero cuelga de supB (SV). Para supB los DOS términos de la policy pasarían — país SV = su país,
    -- y rogue ∈ asesores_a_cargo() — y vería el prospecto desde el país equivocado.
    -- Se corre como OWNER a propósito: es la vía que NO pasa por la RPC de la 265 (owner,
    -- service_role, fix manual por SQL). Si el control viviera solo en la RPC, este INSERT entraría.
    v_err := NULL; v_msg := NULL; v_n := 0;
    BEGIN
      INSERT INTO public.prospectos (pais_id, asesor_id, tipo, nombre, creado_por)
        VALUES (v_sv, v_rogue, 'farmacia', 'P264 Prospecto Incoherente', v_rogue);
      GET DIAGNOSTICS v_n = ROW_COUNT;
    EXCEPTION WHEN OTHERS THEN v_err := SQLSTATE; v_msg := SQLERRM; v_n := 0; END;
    v_477 := CASE
      WHEN v_err = 'PA006' THEN 'BLOQUEADO (PA006: '||v_msg||')'
      WHEN v_err IS NOT NULL THEN 'ROJO ('||v_err||': '||v_msg||')'
      ELSE 'PERMITIDO — FAIL-OPEN (entró un prospecto SV con asesor de GT, filas='||v_n||'; supB lo vería desde el país equivocado)' END;

    RAISE EXCEPTION 'PROBE_UNDO';
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    IF SQLERRM <> 'PROBE_UNDO' THEN
      v_fatal := SQLSTATE||' '||SQLERRM;
      PERFORM set_config('probe.p470','ROJO (fatal: '||v_fatal||')', false);
      PERFORM set_config('probe.p471','ROJO (fatal: '||v_fatal||')', false);
      PERFORM set_config('probe.p472','ROJO (fatal: '||v_fatal||')', false);
      PERFORM set_config('probe.p473','ROJO (fatal: '||v_fatal||')', false);
      PERFORM set_config('probe.p474','ROJO (fatal: '||v_fatal||')', false);
      PERFORM set_config('probe.p475','ROJO (fatal: '||v_fatal||')', false);
      PERFORM set_config('probe.p476','ROJO (fatal: '||v_fatal||')', false);
      PERFORM set_config('probe.p477','ROJO (fatal: '||v_fatal||')', false);
    END IF;
  END;
  -- Publicacion FUERA de la subtransaccion revertida (ver nota en el DECLARE).
  IF v_fatal IS NULL THEN
    PERFORM set_config('probe.p470', COALESCE(v_470,'ROJO (sin resultado)'), false);
    PERFORM set_config('probe.p471', COALESCE(v_471,'ROJO (sin resultado)'), false);
    PERFORM set_config('probe.p472', COALESCE(v_472,'ROJO (sin resultado)'), false);
    PERFORM set_config('probe.p473', COALESCE(v_473,'ROJO (sin resultado)'), false);
    PERFORM set_config('probe.p474', COALESCE(v_474,'ROJO (sin resultado)'), false);
    PERFORM set_config('probe.p475', COALESCE(v_475,'ROJO (sin resultado)'), false);
    PERFORM set_config('probe.p476', COALESCE(v_476,'ROJO (sin resultado)'), false);
    PERFORM set_config('probe.p477', COALESCE(v_477,'ROJO (sin resultado)'), false);
  END IF;
END $$;
SELECT set_config('role','none', true);


-- ############################################################################################
-- PAQUETE PA-FAILOPEN - LOTE 0 - P480-P484 (centinela de fail-open + helpers de la mig 265)
-- ############################################################################################
-- ============================================================================================
-- HERRAMIENTA DEL CENTINELA (pg_temp: vive y muere con la transaccion)
-- --------------------------------------------------------------------------------------------
-- pg_temp.gate_fail_open(gate) — walker de parentesis. Devuelve TRUE si en el gate hay alguna
-- llamada a los 5 helpers de identidad que NO este lexicamente encerrada por un COALESCE(...).
--
-- POR QUE UN WALKER Y NO UN REGEX: "COALESCE envolvente" es una propiedad de anidamiento, no de
-- texto. `IF NOT (COALESCE(tiene_rol(...),false) OR (get_auth_user_rol()='admin_pais' AND ...))`
-- CONTIENE la palabra COALESCE y sigue siendo fail-open — el COALESCE cubre el otro termino. Un
-- regex que busque "COALESCE" da verde falso justo en el patron que estamos cazando (es el de la
-- mig 222). El walker mantiene una pila de parentesis y marca cual de ellos abrio un COALESCE.
--
-- POR QUE ALCANZA CON DETECTAR LA LLAMADA (y no la comparacion): ninguno de los 5 helpers devuelve
-- boolean — get_auth_user_rol() y mi_rol_proveedor() devuelven text; get_auth_user_pais_id(),
-- mi_pais() y mi_empresa_proveedor() devuelven uuid. Dentro de una expresion booleana de gate NO
-- pueden aparecer sueltos: siempre son operando de una comparacion. Detectar la llamada ES detectar
-- la comparacion directa, sin tener que adivinar de que lado del `=` cayo el helper.
-- ============================================================================================
CREATE OR REPLACE FUNCTION pg_temp.gate_fail_open(p_gate text) RETURNS boolean AS $fn$
DECLARE
  i int := 1; n int := length(p_gate); ch text; prev text;
  st boolean[] := ARRAY[]::boolean[];   -- pila: TRUE si ese '(' lo abrio un COALESCE
  in_str boolean := false;
  cubierto boolean;
BEGIN
  WHILE i <= n LOOP
    ch := substr(p_gate, i, 1);
    -- literales de cadena: no se parsean (sus parentesis no cuentan)
    IF in_str THEN
      IF ch = '''' THEN in_str := false; END IF;
      i := i + 1; CONTINUE;
    END IF;
    IF ch = '''' THEN in_str := true; i := i + 1; CONTINUE; END IF;

    -- arranca aca una llamada a uno de los 5 helpers de identidad?
    IF substr(p_gate, i, 40) ~* '^(public\.|private\.)?(get_auth_user_rol|get_auth_user_pais_id|mi_pais|mi_empresa_proveedor|mi_rol_proveedor)\s*\(' THEN
      cubierto := false;
      IF array_length(st,1) IS NOT NULL THEN
        SELECT bool_or(x) INTO cubierto FROM unnest(st) AS t(x);
      END IF;
      IF NOT COALESCE(cubierto, false) THEN RETURN true; END IF;
    END IF;

    IF ch = '(' THEN
      prev := regexp_replace(substr(p_gate, 1, i-1), '\s+$', '');
      st := st || (prev ~* 'coalesce$');
    ELSIF ch = ')' THEN
      IF array_length(st,1) IS NOT NULL THEN st := st[1:array_length(st,1)-1]; END IF;
    END IF;
    i := i + 1;
  END LOOP;
  RETURN false;
END;
$fn$ LANGUAGE plpgsql IMMUTABLE;

-- pg_temp.censo_fail_open() — LA consulta del censo, encapsulada. P480 y P481 consumen ESTA, para
-- que el probe y el probe-del-probe no puedan divergir.
--
-- EXTRACCION DEL GATE: `\m(IF|ELSIF)\s+([^;]*?)\s+THEN[^;]{0,250}?\mRAISE`.
--   - `[^;]*?` para el gate: una expresion booleana no lleva `;`. Sin esta restriccion el motor
--     backtrackea hasta un THEN lejano y se traga statements enteros (paso: daba 39 funciones, 12
--     de ellas artefacto del propio regex).
--   - `[^;]{0,250}?` entre el THEN y el RAISE: exige que el RAISE sea el PRIMER statement de la
--     rama. Eso es un GATE. Si hay un `;` en el medio es una rama de logica, no un gate.
--     (250 y no mas: el limite de repeticion acotada de Postgres es 255.)
CREATE OR REPLACE FUNCTION pg_temp.censo_fail_open()
RETURNS TABLE(func text, gates_n bigint, gates text) LANGUAGE sql STABLE AS $fn$
  WITH candidatas AS (
    SELECT p.oid, n.nspname, p.proname, p.prosrc
    FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    JOIN pg_language  l ON l.oid = p.prolang
    WHERE p.prosecdef
      AND n.nspname IN ('public','private')
      AND l.lanname = 'plpgsql'
  ),
  gates AS (
    SELECT c.nspname, c.proname, g.m[1] AS gate
    FROM candidatas c
    CROSS JOIN LATERAL regexp_matches(
      c.prosrc, '\m(?:IF|ELSIF)\s+([^;]*?)\s+THEN[^;]{0,250}?\mRAISE', 'gi') AS g(m)
  )
  SELECT nspname||'.'||proname,
         count(*),
         string_agg(regexp_replace(gate, '\s+', ' ', 'g'), ' ||| ')
  FROM gates
  WHERE gate ~* '(get_auth_user_rol|get_auth_user_pais_id|mi_pais|mi_empresa_proveedor|mi_rol_proveedor)\s*\('
    AND pg_temp.gate_fail_open(gate)
  GROUP BY 1
  ORDER BY 1;
$fn$;


-- ============================================================================================
-- P480 — CENTINELA DE GATE FAIL-OPEN
-- --------------------------------------------------------------------------------------------
-- ⚠️ LA ALLOWLIST ES DEUDA CON FECHA, NO UNA EXCEPCION PERMANENTE.
--
-- Estas 27 funciones son el censo del 2026-09-02 contra el proyecto vivo: TODAS tienen hoy el gate
-- trivaluado de la mig 222 y TODAS se van a migrar a private.puede_admin_pais / es_admin_pais
-- (mig 265) en los lotes 1..N del paquete PA-FAILOPEN. Cada lote que migra un grupo BORRA sus
-- entradas de esta lista en el mismo commit. Cuando la lista llegue a cero, el ARRAY queda vacio y
-- el probe pasa a ser un guardian permanente: cualquier funcion nueva que compare a mano contra los
-- helpers de identidad lo pone ROJO.
--
-- Una entrada aca NO dice "esto esta bien". Dice "esto esta roto, ya esta contado, y tiene lote
-- asignado". Agregar una entrada nueva para hacer pasar el harness es exactamente lo que este probe
-- existe para impedir: si aparece una funcion nueva en rojo, se arregla la funcion, no la lista.
--
-- Dos entradas estan en la lista aunque NO sean explotables, porque el criterio del centinela es
-- sintactico a proposito (mas ancho que el riesgo, para que no haya que juzgar caso por caso):
--   - notificar_resultado_examen: usa `IS DISTINCT FROM`, que es NULL-safe.
--   - activar_capacidad_suelta / asignar_tier: el termino directo esta en una rama POSITIVA de
--     scope de catalogo (`IF get_auth_user_rol()='admin_pais' THEN ... RAISE`), y el gate real de
--     la funcion ya es private.admin_puede_gestionar_empresa, que si esta COALESCE-ado. Con rol
--     NULL la rama se saltea, pero el gate de arriba ya bloqueo.
-- Igual se migran: la comparacion a mano se va, y con ella la duda.
-- ============================================================================================
SELECT set_config('role','none',true);
DO $$
DECLARE
  -- ALLOWLIST — censo 2026-09-02, paquete PA-FAILOPEN. Se vacia lote por lote.
  v_allow text[] := ARRAY[]::text[];  -- VACIA: el paquete PA-FAILOPEN termino. Ver P481.
  v_allow_historico text[] := ARRAY[
    -- SALDADA por la mig 271 (lote 6): 'public.activar_capacidad_suelta'
    -- SALDADA por la mig 268 (lote 3): 'public.aprobar_personalizacion'
    -- SALDADA por la mig 270 (lote 5): 'public.aprobar_solicitud_campana'
    -- SALDADA por la mig 271 (lote 6): 'public.asignar_tier'
    -- SALDADA por la mig 267 (lote 2): 'public.cerrar_liquidacion'
    -- SALDADA por la mig 268 (lote 3): 'public.crear_capacidad_pais'
    -- SALDADA por la mig 268 (lote 3): 'public.crear_tier_pais'
    -- SALDADA por la mig 267 (lote 2): 'public.liquidar_comision'
    -- SALDADA por la mig 269 (lote 4): 'public.listar_canjes_pendientes'
    -- SALDADA por la mig 269 (lote 4): 'public.listar_capacidades_pais'
    -- SALDADA por la mig 269 (lote 4): 'public.listar_propuestas_especialidad'
    -- SALDADA por la mig 269 (lote 4): 'public.listar_solicitudes_personalizacion'
    -- SALDADA por la mig 269 (lote 4): 'public.listar_tiers_pais'
    -- SALDADA por la mig 267 (lote 2): 'public.marcar_liquidacion_cobrada'
    -- SALDADA por la mig 266 (lote 1, 2026-09-03): gate -> private.puede_admin_pais + REVOKE de
    -- anon. PRIMERA de las 27 que se vacia. El centinela debe quedar VERDE con 26, no con 27.
    -- 'public.metricas_campana_pais',
    -- SALDADA por la mig 270 (lote 5): 'public.notificar_campana_resultado'
    -- SALDADA por la mig 271 (lote 6): 'public.notificar_empresa_estado'
    -- SALDADA por la mig 270 (lote 5): 'public.notificar_pago_resultado'
    -- SALDADA por la mig 271 (lote 6): 'public.notificar_resultado_examen'
    -- SALDADA por la mig 269 (lote 4): 'public.obtener_resumen_pais'
    -- SALDADA por la mig 268 (lote 3): 'public.rechazar_personalizacion'
    -- SALDADA por la mig 271 (lote 6): 'public.registrar_evidencia_entrega'
    -- SALDADA por la mig 270 (lote 5): 'public.resolver_canje'
    -- SALDADA por la mig 268 (lote 3): 'public.resolver_propuesta_especialidad'
    -- SALDADA por la mig 268 (lote 3): 'public.solicitar_capacidad_pais'
    -- SALDADA por la mig 267 (lote 2): 'public.solicitar_contrato_comision'
    -- SALDADA por la mig 268 (lote 3): 'public.solicitar_tier_pais'
    NULL::text   -- relleno: el array historico esta VACIO de entradas vivas, es solo el registro
  ];
  v_rojas    text[];
  v_nuevas   text[];
  v_saldadas text[];
BEGIN
  SELECT COALESCE(array_agg(func ORDER BY func), ARRAY[]::text[]) INTO v_rojas
    FROM pg_temp.censo_fail_open();

  SELECT COALESCE(array_agg(x ORDER BY x), ARRAY[]::text[]) INTO v_nuevas
    FROM unnest(v_rojas) x WHERE x <> ALL (v_allow);

  SELECT COALESCE(array_agg(x ORDER BY x), ARRAY[]::text[]) INTO v_saldadas
    FROM unnest(v_allow) x WHERE x <> ALL (v_rojas);

  IF array_length(v_nuevas,1) IS NOT NULL THEN
    PERFORM set_config('probe.p480',
      'ROJO — GATE FAIL-OPEN NUEVO ('||array_length(v_nuevas,1)||'): '||array_to_string(v_nuevas,', ')||
      '. Arreglar la funcion (consumir private.puede_admin_pais / es_admin_pais), NO agregarla a la allowlist.', false);
  ELSE
    PERFORM set_config('probe.p480',
      'OK ('||COALESCE(array_length(v_rojas,1),0)||' con gate fail-open, todas en la allowlist; 0 nuevas'||
      CASE WHEN array_length(v_saldadas,1) IS NOT NULL
           THEN '. DEUDA SALDADA, quitar de la allowlist: '||array_to_string(v_saldadas,', ')
           ELSE '' END||')', false);
  END IF;
END $$;

-- ============================================================================================
-- P481 — EL PROBE DEL PROBE (FORMA INVERTIDA, desde el lote 6)
-- --------------------------------------------------------------------------------------------
-- ESTE ES EL UNICO PROBE DEL HARNESS CUYO TRABAJO ES FALLAR SI EL INSTRUMENTO SE ROMPE.
-- No verifica ninguna funcion de produccion: verifica que P480 siga siendo capaz de ver.
--
-- POR QUE CAMBIO DE FORMA. Hasta el lote 5 este probe le sacaba UNA entrada a la allowlist y exigia
-- que el centinela la marcara como nueva. Esa forma dependia de que quedara algo roto en la lista, y
-- hubo que re-apuntarlo TRES veces (lote 1: metricas_campana_pais; lote 2: cerrar_liquidacion;
-- lote 5: aprobar_solicitud_campana), cada vez que el lote saldaba la entrada apuntada.
-- Con el lote 6 la allowlist quedo en CERO: la forma vieja se quedaria sin entradas que sacar y
-- pasaria a dar VERDE POR VACIO — exactamente el falso verde que este paquete persigue.
--
-- FORMA NUEVA: se SIEMBRAN dos funciones de fixture dentro del ROLLBACK y se exige que el detector
-- distinga entre ellas.
--   (a) POSITIVA: patron EXACTO del bug (SECURITY DEFINER + gate con RAISE + comparacion directa
--       sobre get_auth_user_pais_id() sin COALESCE envolvente). El centinela DEBE marcarla.
--   (b) NEGATIVA: el MISMO patron pero CON el COALESCE envolvente correcto. El centinela NO debe
--       marcarla. Sin esta mitad, un detector que marcara TODO tambien pasaria el probe — y un
--       detector que marca todo es tan inutil como uno que no marca nada, porque obliga a
--       allowlistear el mundo y nadie vuelve a mirarlo.
--
-- Las dos funciones se crean por DDL dentro de la transaccion del harness y desaparecen con el
-- ROLLBACK (el DDL en Postgres es transaccional). Nunca tocan produccion.
-- ============================================================================================
DO $$
DECLARE
  v_rojas text[];
  v_pos boolean; v_neg boolean;
BEGIN
  -- (a) TRAMPA: el patron exacto de la mig 222, fail-open
  EXECUTE $ddl$
    CREATE FUNCTION public.p481_fixture_fail_open(p_pais_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $fx$
    BEGIN
      IF NOT ( public.get_auth_user_rol() = 'super_admin'
               OR ( public.get_auth_user_rol() = 'admin_pais'
                    AND public.get_auth_user_pais_id() = p_pais_id ) ) THEN
        RAISE EXCEPTION 'no_autorizado' USING ERRCODE = '42501';
      END IF;
    END $fx$;
  $ddl$;

  -- (b) CONTROL: mismo patron, con el COALESCE envolvente correcto -> NO debe marcarse
  EXECUTE $ddl$
    CREATE FUNCTION public.p481_fixture_ok(p_pais_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $fx$
    BEGIN
      IF NOT COALESCE( public.get_auth_user_rol() = 'super_admin'
                       OR ( public.get_auth_user_rol() = 'admin_pais'
                            AND public.get_auth_user_pais_id() = p_pais_id ), false ) THEN
        RAISE EXCEPTION 'no_autorizado' USING ERRCODE = '42501';
      END IF;
    END $fx$;
  $ddl$;

  SELECT COALESCE(array_agg(func ORDER BY func), ARRAY[]::text[]) INTO v_rojas
    FROM pg_temp.censo_fail_open();

  v_pos := 'public.p481_fixture_fail_open' = ANY (v_rojas);
  v_neg := 'public.p481_fixture_ok'        = ANY (v_rojas);

  -- se borran explicitamente ademas del ROLLBACK: si algun dia este bloque se corriera fuera de una
  -- transaccion, no debe dejar funciones colgadas en public.
  EXECUTE 'DROP FUNCTION IF EXISTS public.p481_fixture_fail_open(uuid)';
  EXECUTE 'DROP FUNCTION IF EXISTS public.p481_fixture_ok(uuid)';

  IF v_pos AND NOT v_neg THEN
    PERFORM set_config('probe.p481',
      'OK (el detector VE: caza la funcion sembrada con el patron del bug y NO marca la que tiene el COALESCE envolvente — P480 mide algo real con la allowlist vacia)', false);
  ELSIF NOT v_pos THEN
    PERFORM set_config('probe.p481',
      'ROJO — EL CENTINELA ESTA CIEGO: sembre una funcion con el patron exacto del bug y P480 NO la detecto. El detector se rompio; todo verde de P480 es falso hasta arreglarlo.', false);
  ELSE
    PERFORM set_config('probe.p481',
      'ROJO — EL CENTINELA MARCA TODO: tambien marco la funcion CORRECTA (con COALESCE envolvente). Un detector que marca todo obliga a allowlistear el mundo y deja de servir.', false);
  END IF;
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.b2_fallos', coalesce(current_setting('probe.b2_fallos', true),'')||'L9703('||SQLSTATE||') ', false);
END $$;

-- ============================================================================================
-- P482 — los 2 helpers de la mig 265 existen con la firma y los flags correctos
-- --------------------------------------------------------------------------------------------
-- Firma exacta (incluido el DEFAULT de p_roles), SECURITY DEFINER, STABLE, search_path='', y los
-- grants: authenticated SI, anon NO, PUBLIC NO. El chequeo de PUBLIC es aparte del de anon: anon
-- hereda de PUBLIC, asi que un GRANT a PUBLIC olvidado se veria como "anon puede" — pero al reves
-- no, y el REVOKE de la migracion nombra a los dos.
-- ============================================================================================
DO $$
DECLARE
  v_p oid; v_e oid; v_txt text; v_ok boolean;
  v_det text := '';
BEGIN
  v_p := to_regprocedure('private.puede_admin_pais(uuid,text[])');
  v_e := to_regprocedure('private.es_admin_pais()');
  IF v_p IS NULL OR v_e IS NULL THEN
    PERFORM set_config('probe.p482','ROJO (mig 265 sin aplicar: puede_admin_pais='||
      COALESCE(v_p::text,'AUSENTE')||' es_admin_pais='||COALESCE(v_e::text,'AUSENTE')||')', false);
    RETURN;
  END IF;

  SELECT bool_and(x) INTO v_ok FROM (
    -- OJO con proconfig: `SET search_path = ''` NO se guarda como 'search_path=' sino como
    -- 'search_path=""' — pg_proc conserva las comillas del literal vacio. Comparar contra
    -- 'search_path=' da ROJO con la migracion perfectamente aplicada (pasó en la primera corrida
    -- de este probe). Se compara contra el array exacto para que no haya duda de que hay UN solo
    -- elemento en proconfig y es ese.
    SELECT p.prosecdef AND p.provolatile = 's'
       AND p.proconfig = ARRAY['search_path=""']
       AND has_function_privilege('authenticated', p.oid, 'EXECUTE')
       AND NOT has_function_privilege('anon', p.oid, 'EXECUTE')
       AND NOT EXISTS (SELECT 1 FROM aclexplode(p.proacl) a
                        WHERE a.grantee = 0 AND a.privilege_type = 'EXECUTE')  -- PUBLIC
      AS x
    FROM pg_proc p WHERE p.oid IN (v_p, v_e)
  ) s;

  v_txt := pg_get_function_arguments(v_p);
  IF v_ok AND v_txt ILIKE '%p_roles text[] DEFAULT ARRAY[%super_admin%' THEN
    PERFORM set_config('probe.p482',
      'OK (ambos DEFINER+STABLE+search_path="", EXECUTE solo authenticated (anon y PUBLIC sin), default p_roles=[super_admin])', false);
  ELSE
    SELECT string_agg(format('%s: secdef=%s vol=%s cfg=%s auth=%s anon=%s public=%s',
             p.proname, p.prosecdef, p.provolatile, COALESCE(array_to_string(p.proconfig,','),'(null)'),
             has_function_privilege('authenticated', p.oid, 'EXECUTE'),
             has_function_privilege('anon', p.oid, 'EXECUTE'),
             EXISTS (SELECT 1 FROM aclexplode(p.proacl) a WHERE a.grantee=0 AND a.privilege_type='EXECUTE')), ' | ')
      INTO v_det FROM pg_proc p WHERE p.oid IN (v_p, v_e);
    PERFORM set_config('probe.p482','ROJO ('||v_det||' | args='||v_txt||')', false);
  END IF;
END $$;
SELECT set_config('role','none',true);

-- ============================================================================================
-- P483 — FAIL-CLOSED: caller SIN fila en perfiles obtiene false, NO NULL
-- --------------------------------------------------------------------------------------------
-- Es el corazon del paquete. El caller es un uuid que no esta en perfiles — el caso real de toda
-- cuenta de proveedor (viven en cuentas_proveedor) y de anon donde haya GRANT.
--
-- CONTROL NEGATIVO EN EL MISMO PROBE: se evalua tambien la expresion VIEJA (la de la mig 222) para
-- ese mismo caller y se exige que de NULL. Sin el control, un helper que devolviera false por una
-- razon equivocada (o un caller que si tuviera perfil) daria verde igual. El control demuestra que
-- el escenario es el correcto: la expresion vieja falla abierta aca, la nueva no.
-- ============================================================================================
DO $$
DECLARE
  v_nadie uuid := '00000000-0000-4265-0480-0000000000ff';   -- sin fila en perfiles, a proposito
  v_gt    uuid := 'cbbbbe6d-59fe-4cf2-91ee-3e31ba1d5909';
  v_a boolean; v_b boolean; v_viejo boolean; v_err text := NULL;
BEGIN
  IF to_regprocedure('private.puede_admin_pais(uuid,text[])') IS NULL THEN
    PERFORM set_config('probe.p483','ROJO (mig 265 sin aplicar)', false); RETURN;
  END IF;
  BEGIN
    PERFORM set_config('request.jwt.claims',
      json_build_object('sub', v_nadie::text, 'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);

    SELECT private.puede_admin_pais(v_gt) INTO v_a;
    SELECT private.es_admin_pais()        INTO v_b;
    -- expresion VIEJA, tal cual vive hoy en metricas_campana_pais (control negativo)
    SELECT NOT ( public.get_auth_user_rol() = 'super_admin'
                 OR ( public.get_auth_user_rol() = 'admin_pais'
                      AND public.get_auth_user_pais_id() = v_gt ) ) INTO v_viejo;

    PERFORM set_config('role','none', true);
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    v_err := SQLSTATE||' '||SQLERRM;
  END;

  IF v_err IS NOT NULL THEN
    PERFORM set_config('probe.p483','ROJO (excepcion: '||v_err||')', false);
  ELSIF v_a IS NOT NULL AND v_a = false AND v_b IS NOT NULL AND v_b = false AND v_viejo IS NULL THEN
    PERFORM set_config('probe.p483',
      'OK (sin perfil: puede_admin_pais=false y es_admin_pais=false, ninguno NULL; y el control negativo confirma que la expresion vieja da NULL = RAISE saltado)', false);
  ELSE
    PERFORM set_config('probe.p483',
      'ROJO (puede='||COALESCE(v_a::text,'NULL')||' es_admin='||COALESCE(v_b::text,'NULL')||
      ' control_expresion_vieja='||COALESCE(v_viejo::text,'NULL')||
      CASE WHEN v_viejo IS NOT NULL THEN ' <- el control NO dio NULL: el escenario no es el que se cree' ELSE '' END||')', false);
  END IF;
END $$;
SELECT set_config('role','none',true);

-- ============================================================================================
-- P484 — SCOPE: admin_pais legitimo true en SU pais / false en el otro; super_admin true en ambos
-- --------------------------------------------------------------------------------------------
-- Fixtures propias (no reusa las de la 264: este bloque tiene que poder correr solo). Se siembran
-- dentro de una subtransaccion que termina en RAISE 'PROBE_UNDO', y los veredictos se publican
-- DESPUES del bloque: un set_config adentro lo revierte el RAISE junto con las fixtures.
-- super_admin va como control POSITIVO cruzado: si diera false en algun pais, el helper estaria
-- roto del otro lado (cerrado de mas) y el probe de aislamiento solo no lo detectaria.
-- ============================================================================================
DO $$
DECLARE
  v_gt   uuid := 'cbbbbe6d-59fe-4cf2-91ee-3e31ba1d5909';
  v_sv   uuid := 'f2c75b8e-ef54-4a05-b2ff-7363e448f680';
  v_sa   uuid := '41904e2c-5ef3-4fee-bd48-9ea58e0c8c37';   -- super_admin real
  v_admGT uuid := '00000000-0000-4265-0484-0000000000a1';
  v_admSV uuid := '00000000-0000-4265-0484-0000000000b1';
  v_gt_gt boolean; v_gt_sv boolean; v_gt_es boolean;
  v_sa_gt boolean; v_sa_sv boolean; v_sa_es boolean;
  v_484 text; v_err text := NULL;
BEGIN
  IF to_regprocedure('private.puede_admin_pais(uuid,text[])') IS NULL THEN
    PERFORM set_config('probe.p484','ROJO (mig 265 sin aplicar)', false); RETURN;
  END IF;
  BEGIN
    INSERT INTO auth.users (id) VALUES (v_admGT), (v_admSV);
    INSERT INTO public.perfiles (id, email, nombre_completo, rol, pais_id, activo) VALUES
      (v_admGT, 'p265_admGT@example.invalid', 'Admin GT 265', 'admin_pais', v_gt, true),
      (v_admSV, 'p265_admSV@example.invalid', 'Admin SV 265', 'admin_pais', v_sv, true);

    -- admin_pais de GT
    PERFORM set_config('request.jwt.claims',
      json_build_object('sub', v_admGT::text, 'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    SELECT private.puede_admin_pais(v_gt) INTO v_gt_gt;
    SELECT private.puede_admin_pais(v_sv) INTO v_gt_sv;
    SELECT private.es_admin_pais()        INTO v_gt_es;
    PERFORM set_config('role','none', true);

    -- super_admin (control positivo cruzado)
    PERFORM set_config('request.jwt.claims',
      json_build_object('sub', v_sa::text, 'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    SELECT private.puede_admin_pais(v_gt) INTO v_sa_gt;
    SELECT private.puede_admin_pais(v_sv) INTO v_sa_sv;
    SELECT private.es_admin_pais()        INTO v_sa_es;
    PERFORM set_config('role','none', true);

    IF v_gt_gt AND NOT v_gt_sv AND v_gt_es AND v_sa_gt AND v_sa_sv AND NOT v_sa_es THEN
      v_484 := 'OK (admin GT: su pais=true, otro pais=false, es_admin_pais=true; super_admin: true en ambos paises y es_admin_pais=false)';
    ELSE
      v_484 := 'ROJO (admGT[gt='||COALESCE(v_gt_gt::text,'NULL')||' sv='||COALESCE(v_gt_sv::text,'NULL')||
               ' es='||COALESCE(v_gt_es::text,'NULL')||'] super[gt='||COALESCE(v_sa_gt::text,'NULL')||
               ' sv='||COALESCE(v_sa_sv::text,'NULL')||' es='||COALESCE(v_sa_es::text,'NULL')||'])';
    END IF;

    RAISE EXCEPTION 'PROBE_UNDO';
  EXCEPTION
    WHEN OTHERS THEN
      PERFORM set_config('role','none', true);
      IF SQLERRM <> 'PROBE_UNDO' THEN v_err := SQLSTATE||' '||SQLERRM; END IF;
  END;
  PERFORM set_config('probe.p484', COALESCE('ROJO (excepcion sembrando/midiendo: '||v_err||')', v_484), false);
END $$;
SELECT set_config('role','none',true);


-- ############################################################################################
-- PAQUETE PA-FAILOPEN - LOTE 1 - P485-P489 (metricas_campana_pais: REVOKE anon + gate migrado)
-- ############################################################################################
-- ============================================================================================
-- P485 — SIN SESION: anon no puede ni invocarla
-- --------------------------------------------------------------------------------------------
-- Es EL probe del lote: antes de la mig 266 esta misma llamada devolvia 14 filas por PostgREST con
-- la anon key (verificado en vivo, HTTP 200). Ahora debe cortar. Distingue cual control corto.
-- ============================================================================================
SELECT set_config('role','none',true);
DO $$
DECLARE v_gt uuid := 'cbbbbe6d-59fe-4cf2-91ee-3e31ba1d5909'; v_n bigint; v_msg text;
BEGIN
  BEGIN
    PERFORM set_config('request.jwt.claims', NULL, true);
    PERFORM set_config('role','anon', true);
    SELECT count(*) INTO v_n FROM public.metricas_campana_pais(v_gt);
    PERFORM set_config('role','none', true);
    PERFORM set_config('probe.p485',
      'ROJO — PERMITIDO SIN SESION ('||v_n||' filas devueltas a anon)', false);
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    v_msg := SQLERRM;
    IF v_msg ILIKE '%permission denied%' THEN
      PERFORM set_config('probe.p485',
        'BLOQUEADO por GRANT ('||SQLSTATE||': '||left(v_msg,60)||') — anon sin EXECUTE, no llega ni a evaluar el gate', false);
    ELSIF v_msg ILIKE '%no_autorizado%' THEN
      PERFORM set_config('probe.p485',
        'BLOQUEADO por el RAISE del gate ('||SQLSTATE||' no_autorizado) — OJO: el GRANT de anon sigue puesto, lo corto el gate', false);
    ELSE
      PERFORM set_config('probe.p485','BLOQUEADO por otra causa ('||SQLSTATE||': '||left(v_msg,70)||')', false);
    END IF;
  END;
END $$;
SELECT set_config('role','none',true);

-- ============================================================================================
-- P486 — AUTENTICADO SIN FILA EN perfiles: 42501 'no_autorizado' del gate, y CERO filas
-- --------------------------------------------------------------------------------------------
-- El corazon del paquete. Con el gate viejo este caller pasaba: get_auth_user_rol() = NULL y el
-- IF NOT (NULL) no ejecutaba el RAISE. Ahora private.puede_admin_pais devuelve false y corta.
-- Se exige ADEMAS que el mensaje sea 'no_autorizado' y no 'permission denied': este caller SI tiene
-- EXECUTE (es authenticated), asi que quien tiene que cortar es el GATE. Si cortara el grant,
-- estariamos verdes por el control equivocado y no lo sabriamos.
-- ============================================================================================
DO $$
DECLARE
  v_gt  uuid := 'cbbbbe6d-59fe-4cf2-91ee-3e31ba1d5909';
  v_sin uuid;   -- farmacia.qa: cuentas_proveedor SI, perfiles NO
  v_n bigint; v_msg text;
BEGIN
  SELECT id INTO v_sin FROM auth.users WHERE email = 'farmacia.qa@ezpayconnect.com';
  IF v_sin IS NULL THEN PERFORM set_config('probe.p486','ROJO (fixture ausente: farmacia.qa)', false); RETURN; END IF;
  BEGIN
    PERFORM set_config('request.jwt.claims',
      json_build_object('sub', v_sin::text, 'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    SELECT count(*) INTO v_n FROM public.metricas_campana_pais(v_gt);
    PERFORM set_config('role','none', true);
    PERFORM set_config('probe.p486',
      'ROJO — FAIL-OPEN VIVO (caller sin perfil obtuvo '||v_n||' filas)', false);
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    v_msg := SQLERRM;
    IF SQLSTATE = '42501' AND v_msg ILIKE '%no_autorizado%' THEN
      PERFORM set_config('probe.p486',
        'BLOQUEADO (42501 no_autorizado del GATE, 0 filas — el caller tiene EXECUTE, corto el gate)', false);
    ELSE
      PERFORM set_config('probe.p486',
        'ROJO (corto el control equivocado o falla distinta: '||SQLSTATE||' '||left(v_msg,70)||')', false);
    END IF;
  END;
END $$;
SELECT set_config('role','none',true);

-- ============================================================================================
-- P487 — POSITIVO: admin_pais legitimo sobre SU pais devuelve filas
-- --------------------------------------------------------------------------------------------
-- No-regresion: cerrar el agujero no puede romper al usuario legitimo. Exige filas > 0, no solo
-- "no exploto": una funcion que devuelve 0 filas por un gate mal migrado tambien "no explota".
-- ============================================================================================
DO $$
DECLARE v_gt uuid := 'cbbbbe6d-59fe-4cf2-91ee-3e31ba1d5909'; v_adm uuid; v_n bigint;
BEGIN
  SELECT id INTO v_adm FROM auth.users WHERE email = 'adminpais.qa@ezpayconnect.com';
  IF v_adm IS NULL THEN PERFORM set_config('probe.p487','ROJO (fixture ausente: adminpais.qa)', false); RETURN; END IF;
  BEGIN
    PERFORM set_config('request.jwt.claims',
      json_build_object('sub', v_adm::text, 'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    SELECT count(*) INTO v_n FROM public.metricas_campana_pais(v_gt);
    PERFORM set_config('role','none', true);
    IF v_n > 0 THEN
      PERFORM set_config('probe.p487','OK (admin_pais GT ve '||v_n||' campanas de SU pais)', false);
    ELSE
      PERFORM set_config('probe.p487','ROJO (admin_pais legitimo obtuvo 0 filas: el gate quedo cerrado de mas)', false);
    END IF;
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    PERFORM set_config('probe.p487','ROJO (admin_pais legitimo RECHAZADO: '||SQLSTATE||' '||left(SQLERRM,60)||')', false);
  END;
END $$;
SELECT set_config('role','none',true);

-- ============================================================================================
-- P488 — NEGATIVO CROSS-PAIS: admin_pais de GT sobre El Salvador
-- --------------------------------------------------------------------------------------------
-- El aislamiento por pais, que es la razon de ser del rol. Mismo caller que P487, otro p_pais_id.
-- ============================================================================================
DO $$
DECLARE v_sv uuid := 'f2c75b8e-ef54-4a05-b2ff-7363e448f680'; v_adm uuid; v_n bigint;
BEGIN
  SELECT id INTO v_adm FROM auth.users WHERE email = 'adminpais.qa@ezpayconnect.com';
  IF v_adm IS NULL THEN PERFORM set_config('probe.p488','ROJO (fixture ausente: adminpais.qa)', false); RETURN; END IF;
  BEGIN
    PERFORM set_config('request.jwt.claims',
      json_build_object('sub', v_adm::text, 'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    SELECT count(*) INTO v_n FROM public.metricas_campana_pais(v_sv);
    PERFORM set_config('role','none', true);
    PERFORM set_config('probe.p488',
      'ROJO — FUGA CROSS-PAIS (admin de GT obtuvo '||v_n||' filas de SV)', false);
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    IF SQLSTATE = '42501' AND SQLERRM ILIKE '%no_autorizado%' THEN
      PERFORM set_config('probe.p488','BLOQUEADO (42501 no_autorizado — admin de GT no ve SV, 0 filas)', false);
    ELSE
      PERFORM set_config('probe.p488','ROJO (falla distinta: '||SQLSTATE||' '||left(SQLERRM,70)||')', false);
    END IF;
  END;
END $$;
SELECT set_config('role','none',true);

-- ============================================================================================
-- P489 — POSITIVO super_admin: autoridad global, cualquier pais
-- --------------------------------------------------------------------------------------------
-- La rama super_admin del helper llega por private.tiene_rol(p_roles) con el default
-- ARRAY['super_admin']. Se prueba sobre GT y sobre SV: si el helper hubiera perdido esa rama, un
-- solo pais podria dar verde por casualidad (si el super_admin tuviera pais_id = ese).
-- ============================================================================================
DO $$
DECLARE
  v_gt uuid := 'cbbbbe6d-59fe-4cf2-91ee-3e31ba1d5909';
  v_sv uuid := 'f2c75b8e-ef54-4a05-b2ff-7363e448f680';
  v_sa uuid; v_ngt bigint; v_nsv bigint;
BEGIN
  SELECT id INTO v_sa FROM auth.users WHERE email = 'superadmin@ezpayconnect.com';
  IF v_sa IS NULL THEN PERFORM set_config('probe.p489','ROJO (fixture ausente: superadmin)', false); RETURN; END IF;
  BEGIN
    PERFORM set_config('request.jwt.claims',
      json_build_object('sub', v_sa::text, 'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    SELECT count(*) INTO v_ngt FROM public.metricas_campana_pais(v_gt);
    SELECT count(*) INTO v_nsv FROM public.metricas_campana_pais(v_sv);
    PERFORM set_config('role','none', true);
    IF v_ngt > 0 THEN
      PERFORM set_config('probe.p489',
        'OK (super_admin global: GT='||v_ngt||' filas, SV='||v_nsv||' filas, sin excepcion en ninguno)', false);
    ELSE
      PERFORM set_config('probe.p489',
        'ROJO (super_admin obtuvo 0 filas en GT: perdio la autoridad global)', false);
    END IF;
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    PERFORM set_config('probe.p489','ROJO (super_admin RECHAZADO: '||SQLSTATE||' '||left(SQLERRM,60)||')', false);
  END;
END $$;
SELECT set_config('role','none',true);

-- ############################################################################################
-- PAQUETE PA-FAILOPEN - LOTE 2 - P490-P496 + FX07 (las 4 funciones de DINERO)
-- ############################################################################################
-- ============================================================================================
-- FIXTURES DEL LOTE 2
-- ============================================================================================
SELECT set_config('role','none',true);
DO $$
DECLARE
  v_gt   uuid := 'cbbbbe6d-59fe-4cf2-91ee-3e31ba1d5909';
  v_sv   uuid := 'f2c75b8e-ef54-4a05-b2ff-7363e448f680';
  v_sa   uuid;
  v_emp_gt uuid; v_emp_sv uuid; v_liq_gt uuid; v_liq_sv uuid;
BEGIN
  SELECT id INTO v_sa FROM public.perfiles WHERE email='superadmin@ezpayconnect.com';
  SELECT id INTO v_emp_gt FROM public.empresas_proveedoras
    WHERE tipo='farmacia' AND pais_id=v_gt ORDER BY id LIMIT 1;

  -- (b) empresa farmacia en El Salvador (no existe ninguna no-GT en prod)
  INSERT INTO public.empresas_proveedoras (nombre_empresa, email_contacto, tipo, pais_id, estado)
    VALUES ('Probe SV Farmacia', 'svfarm@probe.test', 'farmacia', v_sv, 'activa')
    RETURNING id INTO v_emp_sv;

  -- (a) una liquidacion PENDIENTE en cada pais. anio=2020 (el CHECK exige anio>=2020) y un mes que
  --     no choca con el indice unico (empresa, anio, mes) ni con la liquidacion QA de jul-2026 cobrada.
  INSERT INTO public.liquidaciones_comision
    (empresa_id, pais_id, anio, mes, total_dispensado, comision_total, n_dispensaciones,
     monto_sin_contrato, estado, cerrada_por)
    VALUES (v_emp_gt, v_gt, 2020, 1, 1000, 50, 3, 0, 'pendiente', v_sa)
    RETURNING id INTO v_liq_gt;
  INSERT INTO public.liquidaciones_comision
    (empresa_id, pais_id, anio, mes, total_dispensado, comision_total, n_dispensaciones,
     monto_sin_contrato, estado, cerrada_por)
    VALUES (v_emp_sv, v_sv, 2020, 1, 2000, 80, 4, 0, 'pendiente', v_sa)
    RETURNING id INTO v_liq_sv;

  PERFORM set_config('probe.l2_emp_gt', v_emp_gt::text, false);
  PERFORM set_config('probe.l2_emp_sv', v_emp_sv::text, false);
  PERFORM set_config('probe.l2_liq_gt', v_liq_gt::text, false);
  PERFORM set_config('probe.l2_liq_sv', v_liq_sv::text, false);
  PERFORM set_config('probe.fx_l2',
    'OK (empresa SV + 2 liquidaciones pendientes sembradas)', false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('probe.fx_l2','ROJO (no se pudo sembrar: '||SQLSTATE||' '||SQLERRM||')', false);
END $$;

-- ============================================================================================
-- P490 — EL PROBE QUE IMPORTA: caller SIN PERFIL no puede cobrar una liquidacion
-- --------------------------------------------------------------------------------------------
-- Reproduce el escenario exacto del censo. ANTES de la mig 267 este caller llevaba la liquidacion de
-- 'pendiente' a 'cobrada' SIN EXCEPCION: mutacion de dinero por parte de un empleado de farmacia.
--
-- SE MIDE EL ESTADO DE LA FILA, no solo la excepcion. Una excepcion sin verificar el estado deja
-- pasar el caso en que la funcion muta y DESPUES falla por otra cosa; y un estado sin verificar la
-- excepcion no distingue "bloqueado" de "no hizo nada por otro motivo". Hacen falta los dos.
-- ============================================================================================
SELECT set_config('role','none',true);
DO $$
DECLARE
  v_sin uuid; v_liq uuid; v_estado_antes text; v_estado_despues text;
  v_msg text; v_state text; v_excepcion boolean := false;
BEGIN
  SELECT id INTO v_sin FROM auth.users WHERE email='farmacia.qa@ezpayconnect.com';
  v_liq := NULLIF(current_setting('probe.l2_liq_gt', true),'')::uuid;
  IF v_sin IS NULL OR v_liq IS NULL THEN
    PERFORM set_config('probe.p490','ROJO (fixture ausente)', false); RETURN; END IF;

  SELECT estado INTO v_estado_antes FROM public.liquidaciones_comision WHERE id = v_liq;

  BEGIN
    PERFORM set_config('request.jwt.claims',
      json_build_object('sub', v_sin::text, 'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    PERFORM public.marcar_liquidacion_cobrada(v_liq, 'transferencia', 'PROBE-490');
    PERFORM set_config('role','none', true);
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    v_excepcion := true; v_state := SQLSTATE; v_msg := SQLERRM;
  END;

  SELECT estado INTO v_estado_despues FROM public.liquidaciones_comision WHERE id = v_liq;

  IF NOT v_excepcion THEN
    PERFORM set_config('probe.p490',
      'ROJO — MUTACION DE DINERO SIN AUTORIZACION (sin excepcion; estado '||v_estado_antes||' -> '||v_estado_despues||')', false);
  ELSIF v_state = 'PC019' AND v_estado_despues = 'pendiente' AND v_estado_antes = 'pendiente' THEN
    PERFORM set_config('probe.p490',
      'BLOQUEADO (PC019 no autorizado, y el estado NO cambio: sigue pendiente)', false);
  ELSIF v_estado_despues <> v_estado_antes THEN
    PERFORM set_config('probe.p490',
      'ROJO — MUTO IGUAL pese a la excepcion ('||v_state||'): estado '||v_estado_antes||' -> '||v_estado_despues, false);
  ELSE
    PERFORM set_config('probe.p490',
      'ROJO (bloqueo por el codigo equivocado: esperaba PC019, obtuvo '||v_state||' '||left(v_msg,60)||')', false);
  END IF;
END $$;
SELECT set_config('role','none',true);

-- ============================================================================================
-- P491-P493 — el mismo caller SIN PERFIL contra las otras 3
-- --------------------------------------------------------------------------------------------
-- P493 (solicitar_contrato_comision) ademas CUENTA las filas de contratos_comision antes y despues:
-- es un INSERT, y una excepcion posterior al INSERT dentro de la misma llamada dejaria la fila.
-- ============================================================================================
DO $$
DECLARE
  v_sin uuid; v_emp uuid; v_n bigint;
  v_491 text; v_492 text; v_493 text;
  v_ct_antes bigint; v_ct_despues bigint; v_state text;
BEGIN
  SELECT id INTO v_sin FROM auth.users WHERE email='farmacia.qa@ezpayconnect.com';
  v_emp := NULLIF(current_setting('probe.l2_emp_gt', true),'')::uuid;
  IF v_sin IS NULL OR v_emp IS NULL THEN
    PERFORM set_config('probe.p491','ROJO (fixture ausente)', false);
    PERFORM set_config('probe.p492','ROJO (fixture ausente)', false);
    PERFORM set_config('probe.p493','ROJO (fixture ausente)', false); RETURN; END IF;

  PERFORM set_config('request.jwt.claims',
    json_build_object('sub', v_sin::text, 'role','authenticated')::text, true);

  -- P491: cerrar_liquidacion (INSERT de liquidacion)
  BEGIN
    PERFORM set_config('role','authenticated', true);
    PERFORM public.cerrar_liquidacion(v_emp, 2020, 2);
    PERFORM set_config('role','none', true);
    v_491 := 'ROJO — PERMITIDO (creo una liquidacion sin autorizacion)';
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    -- Cualquier SQLSTATE que no sea PC019 significa que EL GATE NO BLOQUEO: la llamada lo paso y
    -- murio despues, en logica de negocio (p.ej. PC021 'nada que liquidar'). Para una funcion de
    -- dinero eso NO es un bloqueo, es un permiso que se salvo por no haber datos ese mes.
    v_491 := CASE WHEN SQLSTATE='PC019' THEN 'BLOQUEADO (PC019)'
                  ELSE 'ROJO — EL GATE NO BLOQUEO (paso el gate y murio despues en '||SQLSTATE||': '||left(SQLERRM,45)||')' END;
  END;

  -- P492: liquidar_comision (lectura del agregado de dinero)
  BEGIN
    PERFORM set_config('role','authenticated', true);
    SELECT count(*) INTO v_n FROM public.liquidar_comision(v_emp, '2020-01-01'::date, '2020-12-31'::date);
    PERFORM set_config('role','none', true);
    v_492 := 'ROJO — PERMITIDO (leyo el agregado de comisiones: '||v_n||' filas)';
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    v_492 := CASE WHEN SQLSTATE='PC019' THEN 'BLOQUEADO (PC019, 0 filas)'
                  ELSE 'ROJO (codigo equivocado: '||SQLSTATE||' '||left(SQLERRM,50)||')' END;
  END;

  -- P493: solicitar_contrato_comision (INSERT de contrato) + conteo antes/despues
  SELECT count(*) INTO v_ct_antes FROM public.contratos_comision;
  BEGIN
    PERFORM set_config('role','authenticated', true);
    PERFORM public.solicitar_contrato_comision(v_emp, 7.5, '2020-01-01'::date, NULL);
    PERFORM set_config('role','none', true);
    v_state := NULL;
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    v_state := SQLSTATE;
  END;
  SELECT count(*) INTO v_ct_despues FROM public.contratos_comision;
  v_493 := CASE
    WHEN v_state IS NULL THEN 'ROJO — PERMITIDO (inserto contrato sin autorizacion)'
    WHEN v_state='PC019' AND v_ct_despues = v_ct_antes THEN 'BLOQUEADO (PC019, y contratos_comision sin filas nuevas: '||v_ct_antes||'='||v_ct_despues||')'
    WHEN v_ct_despues <> v_ct_antes THEN 'ROJO — INSERTO IGUAL pese a '||v_state||' ('||v_ct_antes||' -> '||v_ct_despues||')'
    ELSE 'ROJO (codigo equivocado: '||v_state||')' END;

  PERFORM set_config('probe.p491', v_491, false);
  PERFORM set_config('probe.p492', v_492, false);
  PERFORM set_config('probe.p493', v_493, false);
END $$;
SELECT set_config('role','none',true);

-- ============================================================================================
-- P494 / P495 — NO REGRESION: super_admin y admin_pais legitimo siguen pasando el gate en las 4
-- --------------------------------------------------------------------------------------------
-- ES EL PROBE MAS IMPORTANTE DESPUES DEL P490. Son funciones de dinero: un gate cerrado de mas
-- rompe produccion, y "no explota" no alcanza como criterio.
--
-- CRITERIO: lo que se afirma es que el caller PASA EL GATE, no que la operacion termine bien. Estas
-- funciones pueden fallar legitimamente DESPUES del gate por razones de negocio (PC020 ya existe
-- liquidacion, PC021 nada que liquidar, 'Empresa no encontrada'). Por eso la asercion es
-- "NO devuelve PC019", que es el unico error que emite el gate. Confundir "no explota" con "paso el
-- gate" haria que un gate cerrado de mas pasara desapercibido si la funcion fallara por otra causa.
-- ============================================================================================
DO $$
DECLARE
  r record; v_emp uuid; v_liq uuid; v_res text; v_out text; v_probe text;
  v_pc019 int;
BEGIN
  v_emp := NULLIF(current_setting('probe.l2_emp_gt', true),'')::uuid;
  v_liq := NULLIF(current_setting('probe.l2_liq_gt', true),'')::uuid;

  FOR r IN
    SELECT 'p494' AS pr, 'super_admin' AS etq, id AS uid FROM public.perfiles WHERE email='superadmin@ezpayconnect.com'
    UNION ALL
    SELECT 'p495', 'admin_pais GT', id FROM public.perfiles WHERE email='adminpais.qa@ezpayconnect.com'
  LOOP
    v_out := ''; v_pc019 := 0;
    PERFORM set_config('request.jwt.claims',
      json_build_object('sub', r.uid::text, 'role','authenticated')::text, true);

    -- 1) cerrar_liquidacion
    BEGIN
      PERFORM set_config('role','authenticated', true);
      PERFORM public.cerrar_liquidacion(v_emp, 2020, 3);
      PERFORM set_config('role','none', true);
      v_out := v_out || 'cerrar=paso(ok) ';
    EXCEPTION WHEN OTHERS THEN
      PERFORM set_config('role','none', true);
      IF SQLSTATE='PC019' THEN v_pc019 := v_pc019+1; v_out := v_out || 'cerrar=PC019! ';
      ELSE v_out := v_out || 'cerrar=paso('||SQLSTATE||') '; END IF;
    END;

    -- 2) marcar_liquidacion_cobrada
    BEGIN
      PERFORM set_config('role','authenticated', true);
      PERFORM public.marcar_liquidacion_cobrada(v_liq, 'transferencia', 'PROBE-NOREG');
      PERFORM set_config('role','none', true);
      v_out := v_out || 'cobrar=paso(ok) ';
    EXCEPTION WHEN OTHERS THEN
      PERFORM set_config('role','none', true);
      IF SQLSTATE='PC019' THEN v_pc019 := v_pc019+1; v_out := v_out || 'cobrar=PC019! ';
      ELSE v_out := v_out || 'cobrar=paso('||SQLSTATE||') '; END IF;
    END;

    -- 3) liquidar_comision
    BEGIN
      PERFORM set_config('role','authenticated', true);
      PERFORM count(*) FROM public.liquidar_comision(v_emp, '2020-01-01'::date, '2020-12-31'::date);
      PERFORM set_config('role','none', true);
      v_out := v_out || 'liquidar=paso(ok) ';
    EXCEPTION WHEN OTHERS THEN
      PERFORM set_config('role','none', true);
      IF SQLSTATE='PC019' THEN v_pc019 := v_pc019+1; v_out := v_out || 'liquidar=PC019! ';
      ELSE v_out := v_out || 'liquidar=paso('||SQLSTATE||') '; END IF;
    END;

    -- 4) solicitar_contrato_comision
    BEGIN
      PERFORM set_config('role','authenticated', true);
      PERFORM public.solicitar_contrato_comision(v_emp, 6.25, '2020-06-01'::date, NULL);
      PERFORM set_config('role','none', true);
      v_out := v_out || 'contrato=paso(ok)';
    EXCEPTION WHEN OTHERS THEN
      PERFORM set_config('role','none', true);
      IF SQLSTATE='PC019' THEN v_pc019 := v_pc019+1; v_out := v_out || 'contrato=PC019!';
      ELSE v_out := v_out || 'contrato=paso('||SQLSTATE||')'; END IF;
    END;

    v_res := CASE WHEN v_pc019 = 0
      THEN 'OK ('||r.etq||' pasa el gate en las 4: '||v_out||')'
      ELSE 'ROJO — REGRESION ('||r.etq||' rechazado por PC019 en '||v_pc019||' de 4: '||v_out||')' END;
    PERFORM set_config('probe.'||r.pr, v_res, false);
  END LOOP;
END $$;
SELECT set_config('role','none',true);

-- ============================================================================================
-- P496 — NEGATIVO CROSS-PAIS: admin_pais de GT contra la empresa/liquidacion de El Salvador
-- --------------------------------------------------------------------------------------------
-- El aislamiento por pais sobre dinero. Exige PC019 en las 4. Sin la empresa SV sembrada arriba este
-- probe no tendria nada que cruzar (las 7 empresas de prod son de Guatemala) y daria verde vacio.
-- ============================================================================================
DO $$
DECLARE
  v_adm uuid; v_emp_sv uuid; v_liq_sv uuid; v_out text := ''; v_ok int := 0;
BEGIN
  SELECT id INTO v_adm FROM public.perfiles WHERE email='adminpais.qa@ezpayconnect.com';
  v_emp_sv := NULLIF(current_setting('probe.l2_emp_sv', true),'')::uuid;
  v_liq_sv := NULLIF(current_setting('probe.l2_liq_sv', true),'')::uuid;
  IF v_adm IS NULL OR v_emp_sv IS NULL OR v_liq_sv IS NULL THEN
    PERFORM set_config('probe.p496','ROJO (fixture ausente)', false); RETURN; END IF;

  PERFORM set_config('request.jwt.claims',
    json_build_object('sub', v_adm::text, 'role','authenticated')::text, true);

  BEGIN PERFORM set_config('role','authenticated', true);
    PERFORM public.cerrar_liquidacion(v_emp_sv, 2020, 4);
    PERFORM set_config('role','none', true); v_out := v_out || 'cerrar=PERMITIDO! ';
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none', true);
    IF SQLSTATE='PC019' THEN v_ok := v_ok+1; v_out := v_out || 'cerrar=PC019 ';
    ELSE v_out := v_out || 'cerrar='||SQLSTATE||'! '; END IF; END;

  BEGIN PERFORM set_config('role','authenticated', true);
    PERFORM public.marcar_liquidacion_cobrada(v_liq_sv, 'transferencia', 'PROBE-496');
    PERFORM set_config('role','none', true); v_out := v_out || 'cobrar=PERMITIDO! ';
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none', true);
    IF SQLSTATE='PC019' THEN v_ok := v_ok+1; v_out := v_out || 'cobrar=PC019 ';
    ELSE v_out := v_out || 'cobrar='||SQLSTATE||'! '; END IF; END;

  BEGIN PERFORM set_config('role','authenticated', true);
    PERFORM count(*) FROM public.liquidar_comision(v_emp_sv, '2020-01-01'::date, '2020-12-31'::date);
    PERFORM set_config('role','none', true); v_out := v_out || 'liquidar=PERMITIDO! ';
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none', true);
    IF SQLSTATE='PC019' THEN v_ok := v_ok+1; v_out := v_out || 'liquidar=PC019 ';
    ELSE v_out := v_out || 'liquidar='||SQLSTATE||'! '; END IF; END;

  BEGIN PERFORM set_config('role','authenticated', true);
    PERFORM public.solicitar_contrato_comision(v_emp_sv, 5.0, '2020-01-01'::date, NULL);
    PERFORM set_config('role','none', true); v_out := v_out || 'contrato=PERMITIDO!';
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none', true);
    IF SQLSTATE='PC019' THEN v_ok := v_ok+1; v_out := v_out || 'contrato=PC019';
    ELSE v_out := v_out || 'contrato='||SQLSTATE||'!'; END IF; END;

  IF v_ok = 4 THEN
    PERFORM set_config('probe.p496','BLOQUEADO (PC019 en las 4: admin de GT no toca dinero de SV)', false);
  ELSE
    PERFORM set_config('probe.p496','ROJO — FUGA CROSS-PAIS ('||v_ok||'/4 bloqueadas: '||v_out||')', false);
  END IF;
END $$;
SELECT set_config('role','none',true);

-- ############################################################################################
-- PAQUETE PA-FAILOPEN - LOTE 3 - P497-P500 + FX08 (las 7 de config y aprobacion, mig 268)
-- ############################################################################################
DO $$
DECLARE
  v_gt  uuid := 'cbbbbe6d-59fe-4cf2-91ee-3e31ba1d5909';
  v_sv  uuid := 'f2c75b8e-ef54-4a05-b2ff-7363e448f680';
  v_sinperfil uuid;   -- cuenta de proveedor: existe en auth.users, NO en perfiles
  v_super     uuid;
  v_adminpais uuid;
  v_emp_gt uuid; v_emp_sv uuid;
  v_med_gt uuid; v_med_sv uuid; v_clin_gt uuid;
  -- solicitudes de personalizacion: una por actor (la moderacion consume el registro)
  v_sp_np uuid := '00000000-0000-4268-0497-000000000001';
  v_sp_sa uuid := '00000000-0000-4268-0497-000000000002';
  v_sp_ap uuid := '00000000-0000-4268-0497-000000000003';
  v_sp_r  uuid := '00000000-0000-4268-0497-000000000004';   -- para rechazar_personalizacion
  v_sp_sv uuid := '00000000-0000-4268-0497-000000000005';   -- tenant de SV (cross-pais)
  -- propuestas de especialidad
  v_pe_np uuid := '00000000-0000-4268-0497-00000000000a';
  v_pe_sa uuid := '00000000-0000-4268-0497-00000000000b';
  v_pe_ap uuid := '00000000-0000-4268-0497-00000000000c';
  v_pe_sv uuid := '00000000-0000-4268-0497-00000000000d';
  v_users_sv uuid := '00000000-0000-4268-0497-0000000000f1';

  -- conteos para medir EFECTO
  v_cap0 bigint; v_cap1 bigint;
  v_tier0 bigint; v_tier1 bigint;
  v_sol0 bigint; v_sol1 bigint;
  v_est_sp text; v_est_pe text;

  v_err text; v_state text; v_msg text;
  v_det text := '';
  v_ok boolean;
  v_497 text; v_498 text; v_499 text; v_500 text; v_fx text;
  v_fatal text := NULL;
BEGIN
  IF to_regprocedure('private.puede_admin_pais(uuid,text[])') IS NULL THEN
    PERFORM set_config('probe.p497','ROJO (mig 265 sin aplicar)', false);
    PERFORM set_config('probe.p498','ROJO (mig 265 sin aplicar)', false);
    PERFORM set_config('probe.p499','ROJO (mig 265 sin aplicar)', false);
    PERFORM set_config('probe.p500','ROJO (mig 265 sin aplicar)', false);
    PERFORM set_config('probe.fx_l3','ROJO (mig 265 sin aplicar)', false);
    RETURN;
  END IF;

  BEGIN
    -- ================= FIXTURES =================
    SELECT u.id INTO v_sinperfil FROM auth.users u
      WHERE u.email='farmacia.qa@ezpayconnect.com'
        AND NOT EXISTS (SELECT 1 FROM public.perfiles p WHERE p.id=u.id);
    SELECT id INTO v_super     FROM public.perfiles WHERE email='superadmin@ezpayconnect.com';
    SELECT id INTO v_adminpais FROM public.perfiles WHERE email='adminpais.qa@ezpayconnect.com';
    SELECT id INTO v_emp_gt    FROM public.empresas_proveedoras WHERE pais_id=v_gt LIMIT 1;
    SELECT id INTO v_clin_gt   FROM public.clinicas WHERE pais_id=v_gt LIMIT 1;
    SELECT id INTO v_med_gt    FROM public.medicos WHERE pais_id=v_gt LIMIT 1;

    IF v_sinperfil IS NULL OR v_super IS NULL OR v_adminpais IS NULL
       OR v_emp_gt IS NULL OR v_med_gt IS NULL THEN
      v_fatal := 'faltan actores base (sinperfil/super/adminpais/empresa GT/medico GT)';
      RAISE EXCEPTION 'PROBE_UNDO';
    END IF;

    -- empresa de SV: no existe ninguna en prod (las 7 son GT) -> sin esto P500 daria verde vacio
    INSERT INTO public.empresas_proveedoras (nombre_empresa, tipo, estado, pais_id, email_contacto)
      VALUES ('P268 Empresa SV', 'farmacia', 'activa', v_sv, 'p268.sv@example.invalid')
      RETURNING id INTO v_emp_sv;

    -- medico de SV: idem, para la propuesta de especialidad cross-pais.
    -- medicos.id tiene FK a perfiles (medicos_id_perfiles_fkey), no solo a auth.users: hace falta
    -- la cadena completa auth.users -> perfiles -> medicos.
    INSERT INTO auth.users (id) VALUES (v_users_sv);
    INSERT INTO public.perfiles (id, email, nombre_completo, rol, pais_id, activo)
      VALUES (v_users_sv, 'p268_medico_sv@example.invalid', 'P268 Medico SV', 'medico', v_sv, true);
    INSERT INTO public.medicos (id, clinica_id, nombre_completo, pais_id)
      VALUES (v_users_sv, v_clin_gt, 'P268 Medico SV', v_sv);
    v_med_sv := v_users_sv;

    -- solicitudes de personalizacion PENDIENTES: una por actor
    INSERT INTO public.solicitudes_personalizacion (id, tenant_tipo, tenant_id, estado, solicitado_por) VALUES
      (v_sp_np,'empresa_proveedora', v_emp_gt,'pendiente', v_super),
      (v_sp_sa,'empresa_proveedora', v_emp_gt,'pendiente', v_super),
      (v_sp_ap,'empresa_proveedora', v_emp_gt,'pendiente', v_super),
      (v_sp_r ,'empresa_proveedora', v_emp_gt,'pendiente', v_super),
      (v_sp_sv,'empresa_proveedora', v_emp_sv,'pendiente', v_super);

    -- propuestas de especialidad PENDIENTES
    INSERT INTO public.especialidades_propuestas (id, medico_id, nombre_propuesto, estado) VALUES
      (v_pe_np, v_med_gt, 'P268 Esp NP', 'pendiente'),
      (v_pe_sa, v_med_gt, 'P268 Esp SA', 'pendiente'),
      (v_pe_ap, v_med_gt, 'P268 Esp AP', 'pendiente'),
      (v_pe_sv, v_med_sv, 'P268 Esp SV', 'pendiente');

    v_fx := 'OK (empresa SV + medico SV + 5 solicitudes + 4 propuestas sembradas)';

    -- ================= P497: SIN PERFIL, MIDIENDO EFECTO =================
    SELECT count(*) INTO v_cap0  FROM public.capacidades_catalogo;
    SELECT count(*) INTO v_tier0 FROM public.tiers_catalogo;
    SELECT count(*) INTO v_sol0  FROM public.solicitudes_capacidad_pais;

    PERFORM set_config('request.jwt.claims',
      json_build_object('sub', v_sinperfil::text,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    v_det := '';

    BEGIN PERFORM public.crear_capacidad_pais('P268CAP','P268 Cap',NULL,v_gt,900);
      v_det := v_det||'crear_capacidad=PASO! ';
    EXCEPTION WHEN OTHERS THEN
      v_det := v_det||'crear_capacidad='||CASE WHEN SQLSTATE='P0001' AND SQLERRM LIKE 'No autorizado%'
               THEN 'BLOQ' ELSE 'otro('||SQLSTATE||')' END||' '; END;

    BEGIN PERFORM public.crear_tier_pais('P268TIER','P268 Tier',NULL,v_gt,900,NULL);
      v_det := v_det||'crear_tier=PASO! ';
    EXCEPTION WHEN OTHERS THEN
      v_det := v_det||'crear_tier='||CASE WHEN SQLSTATE='P0001' AND SQLERRM LIKE 'No autorizado%'
               THEN 'BLOQ' ELSE 'otro('||SQLSTATE||')' END||' '; END;

    BEGIN PERFORM public.solicitar_capacidad_pais(v_gt,'P268SCAP','P268 SCap',NULL,900);
      v_det := v_det||'solicitar_capacidad=PASO! ';
    EXCEPTION WHEN OTHERS THEN
      v_det := v_det||'solicitar_capacidad='||CASE WHEN SQLSTATE='PC019' THEN 'BLOQ'
               ELSE 'otro('||SQLSTATE||')' END||' '; END;

    BEGIN PERFORM public.solicitar_tier_pais(v_gt,'P268STIER','P268 STier',NULL,900,NULL);
      v_det := v_det||'solicitar_tier=PASO! ';
    EXCEPTION WHEN OTHERS THEN
      v_det := v_det||'solicitar_tier='||CASE WHEN SQLSTATE='PC019' THEN 'BLOQ'
               ELSE 'otro('||SQLSTATE||')' END||' '; END;

    BEGIN PERFORM public.aprobar_personalizacion(v_sp_np);
      v_det := v_det||'aprobar_pers=PASO! ';
    EXCEPTION WHEN OTHERS THEN
      v_det := v_det||'aprobar_pers='||CASE WHEN SQLSTATE='PT001' THEN 'BLOQ'
               ELSE 'otro('||SQLSTATE||')' END||' '; END;

    BEGIN PERFORM public.rechazar_personalizacion(v_sp_r,'motivo');
      v_det := v_det||'rechazar_pers=PASO! ';
    EXCEPTION WHEN OTHERS THEN
      v_det := v_det||'rechazar_pers='||CASE WHEN SQLSTATE='PT001' THEN 'BLOQ'
               ELSE 'otro('||SQLSTATE||')' END||' '; END;

    BEGIN PERFORM public.resolver_propuesta_especialidad(v_pe_np, true);
      v_det := v_det||'resolver_prop=PASO! ';
    EXCEPTION WHEN OTHERS THEN
      v_det := v_det||'resolver_prop='||CASE WHEN SQLSTATE='P0001' AND SQLERRM='no_autorizado'
               THEN 'BLOQ' ELSE 'otro('||SQLSTATE||')' END||' '; END;

    PERFORM set_config('role','none', true);

    -- EFECTO: nada escrito, y los dos registros de moderacion siguen pendientes
    SELECT count(*) INTO v_cap1  FROM public.capacidades_catalogo;
    SELECT count(*) INTO v_tier1 FROM public.tiers_catalogo;
    SELECT count(*) INTO v_sol1  FROM public.solicitudes_capacidad_pais;
    SELECT estado INTO v_est_sp FROM public.solicitudes_personalizacion WHERE id=v_sp_np;
    SELECT estado INTO v_est_pe FROM public.especialidades_propuestas   WHERE id=v_pe_np;

    v_ok := v_det NOT LIKE '%PASO!%' AND v_det NOT LIKE '%otro(%'
        AND v_cap1=v_cap0 AND v_tier1=v_tier0 AND v_sol1=v_sol0
        AND v_est_sp='pendiente' AND v_est_pe='pendiente';
    v_497 := CASE WHEN v_ok
      THEN 'BLOQUEADO en las 7 con la señal de autz correcta, Y SIN EFECTO: capacidades '||v_cap0||'='||v_cap1
           ||', tiers '||v_tier0||'='||v_tier1||', solicitudes '||v_sol0||'='||v_sol1
           ||', solicitud_personalizacion sigue '||v_est_sp||', propuesta sigue '||v_est_pe
      ELSE 'ROJO ('||v_det||'| capacidades '||v_cap0||'->'||v_cap1||' tiers '||v_tier0||'->'||v_tier1
           ||' solicitudes '||v_sol0||'->'||v_sol1||' sp='||COALESCE(v_est_sp,'?')||' pe='||COALESCE(v_est_pe,'?')||')' END;

    -- ================= P498 / P499: NO REGRESION (super_admin y admin_pais GT) =================
    FOR v_state IN SELECT unnest(ARRAY['super','adminpais']) LOOP
      PERFORM set_config('request.jwt.claims',
        json_build_object('sub', CASE WHEN v_state='super' THEN v_super ELSE v_adminpais END::text,
                          'role','authenticated')::text, true);
      PERFORM set_config('role','authenticated', true);
      v_det := '';

      BEGIN PERFORM public.crear_capacidad_pais('P268CAP_'||v_state,'P268 Cap',NULL,v_gt,900);
        v_det := v_det||'crear_capacidad=paso ';
      EXCEPTION WHEN OTHERS THEN
        v_det := v_det||'crear_capacidad='||CASE WHEN SQLSTATE='P0001' AND SQLERRM LIKE 'No autorizado%'
                 THEN 'RECHAZO_AUTZ!' ELSE 'paso('||SQLSTATE||')' END||' '; END;

      BEGIN PERFORM public.crear_tier_pais('P268TIER_'||v_state,'P268 Tier',NULL,v_gt,900,NULL);
        v_det := v_det||'crear_tier=paso ';
      EXCEPTION WHEN OTHERS THEN
        v_det := v_det||'crear_tier='||CASE WHEN SQLSTATE='P0001' AND SQLERRM LIKE 'No autorizado%'
                 THEN 'RECHAZO_AUTZ!' ELSE 'paso('||SQLSTATE||')' END||' '; END;

      BEGIN PERFORM public.solicitar_capacidad_pais(v_gt,'P268SCAP_'||v_state,'P268 SCap',NULL,900);
        v_det := v_det||'solicitar_capacidad=paso ';
      EXCEPTION WHEN OTHERS THEN
        v_det := v_det||'solicitar_capacidad='||CASE WHEN SQLSTATE='PC019' THEN 'RECHAZO_AUTZ!'
                 ELSE 'paso('||SQLSTATE||')' END||' '; END;

      BEGIN PERFORM public.solicitar_tier_pais(v_gt,'P268STIER_'||v_state,'P268 STier',NULL,900,NULL);
        v_det := v_det||'solicitar_tier=paso ';
      EXCEPTION WHEN OTHERS THEN
        v_det := v_det||'solicitar_tier='||CASE WHEN SQLSTATE='PC019' THEN 'RECHAZO_AUTZ!'
                 ELSE 'paso('||SQLSTATE||')' END||' '; END;

      BEGIN PERFORM public.aprobar_personalizacion(CASE WHEN v_state='super' THEN v_sp_sa ELSE v_sp_ap END);
        v_det := v_det||'aprobar_pers=paso ';
      EXCEPTION WHEN OTHERS THEN
        v_det := v_det||'aprobar_pers='||CASE WHEN SQLSTATE='PT001' THEN 'RECHAZO_AUTZ!'
                 ELSE 'paso('||SQLSTATE||')' END||' '; END;

      BEGIN PERFORM public.resolver_propuesta_especialidad(
               CASE WHEN v_state='super' THEN v_pe_sa ELSE v_pe_ap END, true);
        v_det := v_det||'resolver_prop=paso ';
      EXCEPTION WHEN OTHERS THEN
        v_det := v_det||'resolver_prop='||CASE WHEN SQLSTATE='P0001' AND SQLERRM='no_autorizado'
                 THEN 'RECHAZO_AUTZ!' ELSE 'paso('||SQLSTATE||')' END||' '; END;

      PERFORM set_config('role','none', true);

      IF v_state='super' THEN
        v_498 := CASE WHEN v_det NOT LIKE '%RECHAZO_AUTZ!%'
          THEN 'OK (super_admin sin rechazo de autz en las 7: '||v_det||')'
          ELSE 'ROJO — GATE CERRADO DE MAS para super_admin ('||v_det||')' END;
      ELSE
        v_499 := CASE WHEN v_det NOT LIKE '%RECHAZO_AUTZ!%'
          THEN 'OK (admin_pais GT sin rechazo de autz en las 7 sobre SU pais: '||v_det||')'
          ELSE 'ROJO — GATE CERRADO DE MAS para admin_pais ('||v_det||')' END;
      END IF;
    END LOOP;

    -- ================= P500: CROSS-PAIS (admin de GT contra recursos de SV) =================
    PERFORM set_config('request.jwt.claims',
      json_build_object('sub', v_adminpais::text,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    v_det := '';

    BEGIN PERFORM public.crear_capacidad_pais('P268CAPX','P268 CapX',NULL,v_sv,900);
      v_det := v_det||'crear_capacidad=PASO! ';
    EXCEPTION WHEN OTHERS THEN
      v_det := v_det||'crear_capacidad='||CASE WHEN SQLSTATE='P0001' AND SQLERRM LIKE 'No autorizado%'
               THEN 'BLOQ' ELSE 'otro('||SQLSTATE||')' END||' '; END;

    BEGIN PERFORM public.crear_tier_pais('P268TIERX','P268 TierX',NULL,v_sv,900,NULL);
      v_det := v_det||'crear_tier=PASO! ';
    EXCEPTION WHEN OTHERS THEN
      v_det := v_det||'crear_tier='||CASE WHEN SQLSTATE='P0001' AND SQLERRM LIKE 'No autorizado%'
               THEN 'BLOQ' ELSE 'otro('||SQLSTATE||')' END||' '; END;

    BEGIN PERFORM public.solicitar_capacidad_pais(v_sv,'P268SCAPX','P268 SCapX',NULL,900);
      v_det := v_det||'solicitar_capacidad=PASO! ';
    EXCEPTION WHEN OTHERS THEN
      v_det := v_det||'solicitar_capacidad='||CASE WHEN SQLSTATE='PC019' THEN 'BLOQ'
               ELSE 'otro('||SQLSTATE||')' END||' '; END;

    BEGIN PERFORM public.solicitar_tier_pais(v_sv,'P268STIERX','P268 STierX',NULL,900,NULL);
      v_det := v_det||'solicitar_tier=PASO! ';
    EXCEPTION WHEN OTHERS THEN
      v_det := v_det||'solicitar_tier='||CASE WHEN SQLSTATE='PC019' THEN 'BLOQ'
               ELSE 'otro('||SQLSTATE||')' END||' '; END;

    BEGIN PERFORM public.aprobar_personalizacion(v_sp_sv);
      v_det := v_det||'aprobar_pers=PASO! ';
    EXCEPTION WHEN OTHERS THEN
      v_det := v_det||'aprobar_pers='||CASE WHEN SQLSTATE='PT001' THEN 'BLOQ'
               ELSE 'otro('||SQLSTATE||')' END||' '; END;

    BEGIN PERFORM public.rechazar_personalizacion(v_sp_sv,'motivo');
      v_det := v_det||'rechazar_pers=PASO! ';
    EXCEPTION WHEN OTHERS THEN
      v_det := v_det||'rechazar_pers='||CASE WHEN SQLSTATE='PT001' THEN 'BLOQ'
               ELSE 'otro('||SQLSTATE||')' END||' '; END;

    BEGIN PERFORM public.resolver_propuesta_especialidad(v_pe_sv, true);
      v_det := v_det||'resolver_prop=PASO! ';
    EXCEPTION WHEN OTHERS THEN
      v_det := v_det||'resolver_prop='||CASE WHEN SQLSTATE='P0001' AND SQLERRM='no_autorizado'
               THEN 'BLOQ' ELSE 'otro('||SQLSTATE||')' END||' '; END;

    PERFORM set_config('role','none', true);

    SELECT estado INTO v_est_sp FROM public.solicitudes_personalizacion WHERE id=v_sp_sv;
    SELECT estado INTO v_est_pe FROM public.especialidades_propuestas   WHERE id=v_pe_sv;
    v_ok := v_det NOT LIKE '%PASO!%' AND v_det NOT LIKE '%otro(%'
        AND v_est_sp='pendiente' AND v_est_pe='pendiente';
    v_500 := CASE WHEN v_ok
      THEN 'BLOQUEADO (admin de GT no toca config ni moderacion de SV en las 7; el registro de SV sigue '||v_est_sp||'/'||v_est_pe||')'
      ELSE 'ROJO — FUGA CROSS-PAIS ('||v_det||'| sp='||COALESCE(v_est_sp,'?')||' pe='||COALESCE(v_est_pe,'?')||')' END;

    RAISE EXCEPTION 'PROBE_UNDO';
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    IF SQLERRM <> 'PROBE_UNDO' THEN v_fatal := COALESCE(v_fatal, SQLSTATE||' '||SQLERRM); END IF;
  END;

  PERFORM set_config('probe.fx_l3', COALESCE('ROJO (fixtures: '||v_fatal||')', v_fx, 'ROJO (sin resultado)'), false);
  PERFORM set_config('probe.p497',  COALESCE('ROJO (fatal: '||v_fatal||')', v_497, 'ROJO (sin resultado)'), false);
  PERFORM set_config('probe.p498',  COALESCE('ROJO (fatal: '||v_fatal||')', v_498, 'ROJO (sin resultado)'), false);
  PERFORM set_config('probe.p499',  COALESCE('ROJO (fatal: '||v_fatal||')', v_499, 'ROJO (sin resultado)'), false);
  PERFORM set_config('probe.p500',  COALESCE('ROJO (fatal: '||v_fatal||')', v_500, 'ROJO (sin resultado)'), false);
END $$;
SELECT set_config('role','none', true);

-- ############################################################################################
-- PAQUETE PA-FAILOPEN - LOTE 4 - P501-P506 + FX09 (las 6 de LECTURA, mig 269)
-- ############################################################################################
DO $$
DECLARE
  v_gt uuid := 'cbbbbe6d-59fe-4cf2-91ee-3e31ba1d5909';
  v_sv uuid := 'f2c75b8e-ef54-4a05-b2ff-7363e448f680';
  v_sinperfil uuid; v_super uuid; v_adminpais uuid;
  v_pac bigint; v_clin_gt uuid; v_emp_gt uuid; v_emp_sv uuid;
  v_med_gt uuid; v_med_sv uuid := '00000000-0000-4269-0501-0000000000f1';
  v_premio_gt bigint; v_premio_sv bigint;
  v_sp_gt uuid := '00000000-0000-4269-0501-000000000001';
  v_sp_sv uuid := '00000000-0000-4269-0501-000000000002';
  v_pe_gt uuid := '00000000-0000-4269-0501-00000000000a';
  v_pe_sv uuid := '00000000-0000-4269-0501-00000000000b';
  v_j jsonb; v_n bigint; v_txt text;
  v_det text := ''; v_ok boolean;
  v_501 text; v_502 text; v_503 text; v_504 text; v_505 text; v_506 text; v_fx text;
  v_fatal text := NULL;
  r record;
BEGIN
  IF to_regprocedure('private.puede_admin_pais(uuid,text[])') IS NULL
     OR to_regprocedure('private.es_admin_pais()') IS NULL THEN
    PERFORM set_config('probe.p501','ROJO (mig 265 sin aplicar)', false);
    PERFORM set_config('probe.p502','ROJO (mig 265 sin aplicar)', false);
    PERFORM set_config('probe.p503','ROJO (mig 265 sin aplicar)', false);
    PERFORM set_config('probe.p504','ROJO (mig 265 sin aplicar)', false);
    PERFORM set_config('probe.p505','ROJO (mig 265 sin aplicar)', false);
    PERFORM set_config('probe.p506','ROJO (mig 265 sin aplicar)', false);
    PERFORM set_config('probe.fx_l4','ROJO (mig 265 sin aplicar)', false);
    RETURN;
  END IF;

  BEGIN
    -- ===================== FIXTURES: filas en DOS paises =====================
    SELECT u.id INTO v_sinperfil FROM auth.users u
      WHERE u.email='farmacia.qa@ezpayconnect.com'
        AND NOT EXISTS (SELECT 1 FROM public.perfiles p WHERE p.id=u.id);
    SELECT id INTO v_super     FROM public.perfiles WHERE email='superadmin@ezpayconnect.com';
    SELECT id INTO v_adminpais FROM public.perfiles WHERE email='adminpais.qa@ezpayconnect.com';
    SELECT id INTO v_pac       FROM public.pacientes WHERE auth_user_id IS NOT NULL LIMIT 1;
    SELECT id INTO v_clin_gt   FROM public.clinicas WHERE pais_id=v_gt LIMIT 1;
    SELECT id INTO v_emp_gt    FROM public.empresas_proveedoras WHERE pais_id=v_gt LIMIT 1;
    SELECT id INTO v_med_gt    FROM public.medicos WHERE pais_id=v_gt LIMIT 1;
    IF v_sinperfil IS NULL OR v_super IS NULL OR v_adminpais IS NULL OR v_pac IS NULL
       OR v_emp_gt IS NULL OR v_med_gt IS NULL THEN
      v_fatal := 'faltan actores base'; RAISE EXCEPTION 'PROBE_UNDO';
    END IF;

    -- empresa y medico de SV (prod es 100% GT: sin esto, P504/P505/P506 dan verde vacio)
    INSERT INTO public.empresas_proveedoras (nombre_empresa, tipo, estado, pais_id, email_contacto)
      VALUES ('P269 Empresa SV','farmacia','activa', v_sv, 'p269.sv@example.invalid')
      RETURNING id INTO v_emp_sv;
    INSERT INTO auth.users (id) VALUES (v_med_sv);
    INSERT INTO public.perfiles (id, email, nombre_completo, rol, pais_id, activo)
      VALUES (v_med_sv,'p269_medico_sv@example.invalid','P269 Medico SV','medico', v_sv, true);
    INSERT INTO public.medicos (id, clinica_id, nombre_completo, pais_id)
      VALUES (v_med_sv, v_clin_gt, 'P269 Medico SV', v_sv);

    -- canjes pendientes en ambos paises (el pais del canje sale de premios.pais_id)
    INSERT INTO public.premios (nombre, costo_puntos, pais_id, tipo, activo)
      VALUES ('P269 Premio GT', 10, v_gt, 'fisico', true) RETURNING id INTO v_premio_gt;
    INSERT INTO public.premios (nombre, costo_puntos, pais_id, tipo, activo)
      VALUES ('P269 Premio SV', 10, v_sv, 'fisico', true) RETURNING id INTO v_premio_sv;
    INSERT INTO public.canjes (paciente_id, premio_id, costo_puntos, estado)
      VALUES (v_pac, v_premio_gt, 10, 'pendiente'), (v_pac, v_premio_sv, 10, 'pendiente');

    -- propuestas de especialidad en ambos paises (pais = del medico)
    INSERT INTO public.especialidades_propuestas (id, medico_id, nombre_propuesto, estado) VALUES
      (v_pe_gt, v_med_gt, 'P269 Esp GT', 'pendiente'),
      (v_pe_sv, v_med_sv, 'P269 Esp SV', 'pendiente');

    -- solicitudes de personalizacion en ambos paises (pais = del tenant)
    INSERT INTO public.solicitudes_personalizacion (id, tenant_tipo, tenant_id, estado, solicitado_por) VALUES
      (v_sp_gt,'empresa_proveedora', v_emp_gt,'pendiente', v_super),
      (v_sp_sv,'empresa_proveedora', v_emp_sv,'pendiente', v_super);

    -- catalogos en ambos paises
    INSERT INTO public.capacidades_catalogo (codigo,nombre,pais_id,orden,activo) VALUES
      ('P269CAPGT','P269 Cap GT', v_gt, 900, true), ('P269CAPSV','P269 Cap SV', v_sv, 900, true);
    INSERT INTO public.tiers_catalogo (codigo,nombre,pais_id,orden,activo) VALUES
      ('P269TIERGT','P269 Tier GT', v_gt, 900, true), ('P269TIERSV','P269 Tier SV', v_sv, 900, true);

    v_fx := 'OK (empresa+medico SV, 2 premios, 2 canjes, 2 propuestas, 2 solicitudes, 2 capacidades, 2 tiers)';

    -- ===================== P501: SIN PERFIL contra las 6 =====================
    PERFORM set_config('request.jwt.claims',
      json_build_object('sub', v_sinperfil::text,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    v_det := '';

    BEGIN SELECT public.listar_canjes_pendientes() INTO v_j;
      v_det := v_det||'canjes=DEVOLVIO('||jsonb_array_length(v_j)||') ';
    EXCEPTION WHEN OTHERS THEN v_det := v_det||'canjes=BLOQ('||SQLSTATE||') '; END;

    BEGIN SELECT public.listar_propuestas_especialidad(NULL) INTO v_j;
      v_det := v_det||'propuestas=DEVOLVIO('||jsonb_array_length(v_j)||') ';
    EXCEPTION WHEN OTHERS THEN v_det := v_det||'propuestas=BLOQ('||SQLSTATE||') '; END;

    BEGIN SELECT count(*) INTO v_n FROM public.listar_solicitudes_personalizacion(NULL);
      v_det := v_det||'solicitudes=DEVOLVIO('||v_n||') ';
    EXCEPTION WHEN OTHERS THEN v_det := v_det||'solicitudes=BLOQ('||SQLSTATE||') '; END;

    BEGIN SELECT count(*) INTO v_n FROM public.listar_capacidades_pais(v_sv);
      v_det := v_det||'capacidades_SV=FUGA('||v_n||') ';
    EXCEPTION WHEN OTHERS THEN v_det := v_det||'capacidades_SV=BLOQ('||SQLSTATE||') '; END;

    BEGIN SELECT count(*) INTO v_n FROM public.listar_tiers_pais(v_sv);
      v_det := v_det||'tiers_SV=FUGA('||v_n||') ';
    EXCEPTION WHEN OTHERS THEN v_det := v_det||'tiers_SV=BLOQ('||SQLSTATE||') '; END;

    BEGIN SELECT public.obtener_resumen_pais(v_sv) INTO v_j;
      v_det := v_det||'resumen_SV=FUGA('||COALESCE(v_j->>'nombre','?')||') ';
    EXCEPTION WHEN OTHERS THEN v_det := v_det||'resumen_SV=BLOQ('||SQLSTATE||') '; END;

    PERFORM set_config('role','none', true);
    v_ok := v_det NOT LIKE '%DEVOLVIO%' AND v_det NOT LIKE '%FUGA%';
    v_501 := CASE WHEN v_ok
      THEN 'BLOQUEADO en las 6, sin devolver nada: '||v_det
      ELSE 'ROJO ('||v_det||')' END;

    -- ===================== P502 / P503: NO REGRESION =====================
    FOR r IN SELECT * FROM (VALUES ('super', v_super), ('adminpais', v_adminpais)) t(etq, uid) LOOP
      PERFORM set_config('request.jwt.claims',
        json_build_object('sub', r.uid::text,'role','authenticated')::text, true);
      PERFORM set_config('role','authenticated', true);
      v_det := '';
      BEGIN PERFORM public.listar_canjes_pendientes(); v_det := v_det||'canjes=paso ';
      EXCEPTION WHEN OTHERS THEN v_det := v_det||'canjes=RECHAZO('||SQLSTATE||') '; END;
      BEGIN PERFORM public.listar_propuestas_especialidad(NULL); v_det := v_det||'propuestas=paso ';
      EXCEPTION WHEN OTHERS THEN v_det := v_det||'propuestas=RECHAZO('||SQLSTATE||') '; END;
      BEGIN PERFORM count(*) FROM public.listar_solicitudes_personalizacion(NULL); v_det := v_det||'solicitudes=paso ';
      EXCEPTION WHEN OTHERS THEN v_det := v_det||'solicitudes=RECHAZO('||SQLSTATE||') '; END;
      BEGIN PERFORM count(*) FROM public.listar_capacidades_pais(v_gt); v_det := v_det||'capacidades=paso ';
      EXCEPTION WHEN OTHERS THEN v_det := v_det||'capacidades=RECHAZO('||SQLSTATE||') '; END;
      BEGIN PERFORM count(*) FROM public.listar_tiers_pais(v_gt); v_det := v_det||'tiers=paso ';
      EXCEPTION WHEN OTHERS THEN v_det := v_det||'tiers=RECHAZO('||SQLSTATE||') '; END;
      BEGIN PERFORM public.obtener_resumen_pais(v_gt); v_det := v_det||'resumen=paso ';
      EXCEPTION WHEN OTHERS THEN v_det := v_det||'resumen=RECHAZO('||SQLSTATE||') '; END;
      PERFORM set_config('role','none', true);
      IF r.etq='super' THEN
        v_502 := CASE WHEN v_det NOT LIKE '%RECHAZO%' THEN 'OK (super_admin sin rechazo en las 6: '||v_det||')'
                      ELSE 'ROJO — GATE CERRADO DE MAS para super_admin ('||v_det||')' END;
      ELSE
        v_503 := CASE WHEN v_det NOT LIKE '%RECHAZO%' THEN 'OK (admin_pais GT sin rechazo en las 6 sobre SU pais: '||v_det||')'
                      ELSE 'ROJO — GATE CERRADO DE MAS para admin_pais ('||v_det||')' END;
      END IF;
    END LOOP;

    -- ===================== P504: CROSS-PAIS en las 3 parametrizadas =====================
    PERFORM set_config('request.jwt.claims',
      json_build_object('sub', v_adminpais::text,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    v_det := '';
    BEGIN SELECT count(*) INTO v_n FROM public.listar_capacidades_pais(v_sv);
      v_det := v_det||'capacidades_SV=FUGA('||v_n||') ';
    EXCEPTION WHEN OTHERS THEN v_det := v_det||'capacidades_SV='||CASE WHEN SQLSTATE='PC019' THEN 'BLOQ' ELSE 'otro('||SQLSTATE||')' END||' '; END;
    BEGIN SELECT count(*) INTO v_n FROM public.listar_tiers_pais(v_sv);
      v_det := v_det||'tiers_SV=FUGA('||v_n||') ';
    EXCEPTION WHEN OTHERS THEN v_det := v_det||'tiers_SV='||CASE WHEN SQLSTATE='PC019' THEN 'BLOQ' ELSE 'otro('||SQLSTATE||')' END||' '; END;
    BEGIN SELECT public.obtener_resumen_pais(v_sv) INTO v_j;
      v_det := v_det||'resumen_SV=FUGA('||COALESCE(v_j->>'nombre','?')||') ';
    EXCEPTION WHEN OTHERS THEN v_det := v_det||'resumen_SV='||CASE WHEN SQLSTATE='PC019' THEN 'BLOQ' ELSE 'otro('||SQLSTATE||')' END||' '; END;
    PERFORM set_config('role','none', true);
    v_504 := CASE WHEN v_det NOT LIKE '%FUGA%' AND v_det NOT LIKE '%otro(%'
      THEN 'BLOQUEADO (PC019 en las 3 parametrizadas: admin de GT no lee config de SV)'
      ELSE 'ROJO ('||v_det||')' END;

    -- ===================== P505: CONFINAMIENTO por CONTENIDO (admin_pais GT) =====================
    PERFORM set_config('request.jwt.claims',
      json_build_object('sub', v_adminpais::text,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    v_det := '';
    SELECT public.listar_canjes_pendientes() INTO v_j;
    v_det := v_det||'canjes[GT='||(v_j::text LIKE '%P269 Premio GT%')::text
                  ||' SV='||(v_j::text LIKE '%P269 Premio SV%')::text||'] ';
    SELECT public.listar_propuestas_especialidad(NULL) INTO v_j;
    v_det := v_det||'propuestas[GT='||(v_j::text LIKE '%P269 Esp GT%')::text
                  ||' SV='||(v_j::text LIKE '%P269 Esp SV%')::text||'] ';
    SELECT string_agg(tenant_id::text, ',') INTO v_txt FROM public.listar_solicitudes_personalizacion(NULL);
    v_det := v_det||'solicitudes[GT='||(COALESCE(v_txt,'') LIKE '%'||v_emp_gt::text||'%')::text
                  ||' SV='||(COALESCE(v_txt,'') LIKE '%'||v_emp_sv::text||'%')::text||']';
    PERFORM set_config('role','none', true);
    v_ok := v_det LIKE '%canjes[GT=true SV=false]%'
        AND v_det LIKE '%propuestas[GT=true SV=false]%'
        AND v_det LIKE '%solicitudes[GT=true SV=false]%';
    v_505 := CASE WHEN v_ok
      THEN 'BLOQUEADO (admin_pais GT ve SOLO contenido de GT en los 3 listar_*: '||v_det||')'
      ELSE 'ROJO — FUGA CROSS-PAIS EN EL CONTENIDO ('||v_det||')' END;

    -- ===================== P506: ANTI-FILTRO-DE-MAS (super_admin ve ambos) =====================
    PERFORM set_config('request.jwt.claims',
      json_build_object('sub', v_super::text,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    v_det := '';
    SELECT public.listar_canjes_pendientes() INTO v_j;
    v_det := v_det||'canjes[GT='||(v_j::text LIKE '%P269 Premio GT%')::text
                  ||' SV='||(v_j::text LIKE '%P269 Premio SV%')::text||'] ';
    SELECT public.listar_propuestas_especialidad(NULL) INTO v_j;
    v_det := v_det||'propuestas[GT='||(v_j::text LIKE '%P269 Esp GT%')::text
                  ||' SV='||(v_j::text LIKE '%P269 Esp SV%')::text||'] ';
    SELECT string_agg(tenant_id::text, ',') INTO v_txt FROM public.listar_solicitudes_personalizacion(NULL);
    v_det := v_det||'solicitudes[GT='||(COALESCE(v_txt,'') LIKE '%'||v_emp_gt::text||'%')::text
                  ||' SV='||(COALESCE(v_txt,'') LIKE '%'||v_emp_sv::text||'%')::text||']';
    PERFORM set_config('role','none', true);
    v_ok := v_det LIKE '%canjes[GT=true SV=true]%'
        AND v_det LIKE '%propuestas[GT=true SV=true]%'
        AND v_det LIKE '%solicitudes[GT=true SV=true]%';
    v_506 := CASE WHEN v_ok
      THEN 'OK (super_admin sigue viendo AMBOS paises en los 3 listar_*: '||v_det||')'
      ELSE 'ROJO — FILTRO DE MAS: el panel maestro perdio filas ('||v_det||')' END;

    RAISE EXCEPTION 'PROBE_UNDO';
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    IF SQLERRM <> 'PROBE_UNDO' THEN v_fatal := COALESCE(v_fatal, SQLSTATE||' '||SQLERRM); END IF;
  END;

  PERFORM set_config('probe.fx_l4', COALESCE('ROJO (fixtures: '||v_fatal||')', v_fx, 'ROJO (sin resultado)'), false);
  PERFORM set_config('probe.p501',  COALESCE('ROJO (fatal: '||v_fatal||')', v_501, 'ROJO (sin resultado)'), false);
  PERFORM set_config('probe.p502',  COALESCE('ROJO (fatal: '||v_fatal||')', v_502, 'ROJO (sin resultado)'), false);
  PERFORM set_config('probe.p503',  COALESCE('ROJO (fatal: '||v_fatal||')', v_503, 'ROJO (sin resultado)'), false);
  PERFORM set_config('probe.p504',  COALESCE('ROJO (fatal: '||v_fatal||')', v_504, 'ROJO (sin resultado)'), false);
  PERFORM set_config('probe.p505',  COALESCE('ROJO (fatal: '||v_fatal||')', v_505, 'ROJO (sin resultado)'), false);
  PERFORM set_config('probe.p506',  COALESCE('ROJO (fatal: '||v_fatal||')', v_506, 'ROJO (sin resultado)'), false);
END $$;
SELECT set_config('role','none', true);

-- ############################################################################################
-- PAQUETE PA-FAILOPEN - LOTE 5 - P507-P510 + FX10 (notificaciones, campanas y canjes, mig 270)
-- ############################################################################################
DO $$
DECLARE
  v_gt uuid := 'cbbbbe6d-59fe-4cf2-91ee-3e31ba1d5909';
  v_sv uuid := 'f2c75b8e-ef54-4a05-b2ff-7363e448f680';
  v_sinperfil uuid; v_super uuid; v_adminpais uuid;
  v_emp_gt uuid; v_emp_sv uuid; v_cta uuid; v_pac bigint;
  v_pago_gt uuid; v_pago_sv uuid;
  v_solpub_gt uuid; v_solpub_sv uuid;                    -- 'publicada' -> notificar_campana_resultado
  v_solpend_np uuid; v_solpend_sa uuid; v_solpend_ap uuid; v_solpend_sv uuid;  -- 'enviada' -> aprobar (el CHECK admite borrador|enviada|publicada|rechazada, NO 'pendiente')
  v_premio_gt bigint; v_premio_sv bigint;
  v_canje_np bigint; v_canje_sa bigint; v_canje_ap bigint; v_canje_sv bigint;
  v_notif0 bigint; v_notif1 bigint; v_camp0 bigint; v_camp1 bigint;
  v_est_sol text; v_est_canje text;
  v_det text := ''; v_ok boolean;
  v_507 text; v_508 text; v_509 text; v_510 text; v_fx text;
  v_fatal text := NULL; r record;
BEGIN
  IF to_regprocedure('private.puede_admin_pais(uuid,text[])') IS NULL THEN
    PERFORM set_config('probe.p507','ROJO (mig 265 sin aplicar)', false);
    PERFORM set_config('probe.p508','ROJO (mig 265 sin aplicar)', false);
    PERFORM set_config('probe.p509','ROJO (mig 265 sin aplicar)', false);
    PERFORM set_config('probe.p510','ROJO (mig 265 sin aplicar)', false);
    PERFORM set_config('probe.fx_l5','ROJO (mig 265 sin aplicar)', false);
    RETURN;
  END IF;

  BEGIN
    SELECT u.id INTO v_sinperfil FROM auth.users u
      WHERE u.email='farmacia.qa@ezpayconnect.com'
        AND NOT EXISTS (SELECT 1 FROM public.perfiles p WHERE p.id=u.id);
    SELECT id INTO v_super     FROM public.perfiles WHERE email='superadmin@ezpayconnect.com';
    SELECT id INTO v_adminpais FROM public.perfiles WHERE email='adminpais.qa@ezpayconnect.com';
    SELECT cp.empresa_id, cp.id INTO v_emp_gt, v_cta FROM public.cuentas_proveedor cp
      JOIN public.empresas_proveedoras e ON e.id=cp.empresa_id
      WHERE e.pais_id=v_gt AND cp.activo LIMIT 1;
    SELECT id INTO v_pac FROM public.pacientes WHERE auth_user_id IS NOT NULL LIMIT 1;
    IF v_sinperfil IS NULL OR v_super IS NULL OR v_adminpais IS NULL OR v_emp_gt IS NULL OR v_pac IS NULL THEN
      v_fatal := 'faltan actores base'; RAISE EXCEPTION 'PROBE_UNDO';
    END IF;

    INSERT INTO public.empresas_proveedoras (nombre_empresa, tipo, estado, pais_id, email_contacto)
      VALUES ('P270 Empresa SV','farmacia','activa', v_sv, 'p270.sv@example.invalid') RETURNING id INTO v_emp_sv;

    -- pagos en estado NOTIFICABLE ('verificado')
    INSERT INTO public.pagos_proveedor (empresa_id, tipo, monto, moneda, estado)
      VALUES (v_emp_gt,'plan',100,'GTQ','verificado') RETURNING id INTO v_pago_gt;
    INSERT INTO public.pagos_proveedor (empresa_id, tipo, monto, moneda, estado)
      VALUES (v_emp_sv,'plan',100,'USD','verificado') RETURNING id INTO v_pago_sv;

    -- solicitudes de campana: 'publicada' (notificable) y 'pendiente' (aprobable, una por actor)
    INSERT INTO public.solicitudes_campana (empresa_id, cuenta_proveedor_id, titulo, tipo,
                                            fecha_inicio, fecha_fin, pais_id, estado)
      VALUES (v_emp_gt, v_cta,'P270 Camp GT pub','banner', CURRENT_DATE, CURRENT_DATE+30, v_gt,'publicada')
      RETURNING id INTO v_solpub_gt;
    INSERT INTO public.solicitudes_campana (empresa_id, cuenta_proveedor_id, titulo, tipo,
                                            fecha_inicio, fecha_fin, pais_id, estado)
      VALUES (v_emp_sv, v_cta,'P270 Camp SV pub','banner', CURRENT_DATE, CURRENT_DATE+30, v_sv,'publicada')
      RETURNING id INTO v_solpub_sv;
    INSERT INTO public.solicitudes_campana (empresa_id, cuenta_proveedor_id, titulo, tipo,
                                            fecha_inicio, fecha_fin, pais_id, estado)
      VALUES (v_emp_gt, v_cta,'P270 Camp NP','banner', CURRENT_DATE, CURRENT_DATE+30, v_gt,'enviada')
      RETURNING id INTO v_solpend_np;
    INSERT INTO public.solicitudes_campana (empresa_id, cuenta_proveedor_id, titulo, tipo,
                                            fecha_inicio, fecha_fin, pais_id, estado)
      VALUES (v_emp_gt, v_cta,'P270 Camp SA','banner', CURRENT_DATE, CURRENT_DATE+30, v_gt,'enviada')
      RETURNING id INTO v_solpend_sa;
    INSERT INTO public.solicitudes_campana (empresa_id, cuenta_proveedor_id, titulo, tipo,
                                            fecha_inicio, fecha_fin, pais_id, estado)
      VALUES (v_emp_gt, v_cta,'P270 Camp AP','banner', CURRENT_DATE, CURRENT_DATE+30, v_gt,'enviada')
      RETURNING id INTO v_solpend_ap;
    INSERT INTO public.solicitudes_campana (empresa_id, cuenta_proveedor_id, titulo, tipo,
                                            fecha_inicio, fecha_fin, pais_id, estado)
      VALUES (v_emp_sv, v_cta,'P270 Camp SV pend','banner', CURRENT_DATE, CURRENT_DATE+30, v_sv,'enviada')
      RETURNING id INTO v_solpend_sv;

    -- canjes pendientes (el pais sale de premios.pais_id); resolver_canje CONSUME -> uno por actor
    INSERT INTO public.premios (nombre, costo_puntos, pais_id, tipo, activo)
      VALUES ('P270 Premio GT', 10, v_gt, 'fisico', true) RETURNING id INTO v_premio_gt;
    INSERT INTO public.premios (nombre, costo_puntos, pais_id, tipo, activo)
      VALUES ('P270 Premio SV', 10, v_sv, 'fisico', true) RETURNING id INTO v_premio_sv;
    INSERT INTO public.canjes (paciente_id, premio_id, costo_puntos, estado)
      VALUES (v_pac, v_premio_gt, 10, 'pendiente') RETURNING id INTO v_canje_np;
    INSERT INTO public.canjes (paciente_id, premio_id, costo_puntos, estado)
      VALUES (v_pac, v_premio_gt, 10, 'pendiente') RETURNING id INTO v_canje_sa;
    INSERT INTO public.canjes (paciente_id, premio_id, costo_puntos, estado)
      VALUES (v_pac, v_premio_gt, 10, 'pendiente') RETURNING id INTO v_canje_ap;
    INSERT INTO public.canjes (paciente_id, premio_id, costo_puntos, estado)
      VALUES (v_pac, v_premio_sv, 10, 'pendiente') RETURNING id INTO v_canje_sv;

    v_fx := 'OK (empresa SV, 2 pagos, 6 solicitudes de campana, 2 premios, 4 canjes)';

    -- ===================== P507: SIN PERFIL, MIDIENDO EFECTO =====================
    SELECT count(*) INTO v_notif0 FROM public.notificaciones;
    SELECT count(*) INTO v_camp0  FROM public.campanas_publicitarias;

    PERFORM set_config('request.jwt.claims',
      json_build_object('sub', v_sinperfil::text,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    v_det := '';

    BEGIN PERFORM public.notificar_pago_resultado(v_pago_gt); v_det := v_det||'notif_pago=PASO! ';
    EXCEPTION WHEN OTHERS THEN
      v_det := v_det||'notif_pago='||CASE WHEN SQLSTATE='PT002' THEN 'BLOQ' ELSE 'otro('||SQLSTATE||')' END||' '; END;

    BEGIN PERFORM public.notificar_campana_resultado(v_solpub_gt); v_det := v_det||'notif_campana=PASO! ';
    EXCEPTION WHEN OTHERS THEN
      v_det := v_det||'notif_campana='||CASE WHEN SQLSTATE='PT002' THEN 'BLOQ' ELSE 'otro('||SQLSTATE||')' END||' '; END;

    BEGIN PERFORM public.aprobar_solicitud_campana(v_solpend_np, 'nota'); v_det := v_det||'aprobar_campana=PASO! ';
    EXCEPTION WHEN OTHERS THEN
      v_det := v_det||'aprobar_campana='||CASE WHEN SQLSTATE='P0001' AND SQLERRM LIKE 'No autorizado%'
               THEN 'BLOQ' ELSE 'otro('||SQLSTATE||')' END||' '; END;

    BEGIN PERFORM public.resolver_canje(v_canje_np, true, NULL); v_det := v_det||'resolver_canje=PASO! ';
    EXCEPTION WHEN OTHERS THEN
      v_det := v_det||'resolver_canje='||CASE WHEN SQLSTATE='P0001' AND SQLERRM='no_autorizado'
               THEN 'BLOQ' ELSE 'otro('||SQLSTATE||')' END||' '; END;

    PERFORM set_config('role','none', true);

    SELECT count(*) INTO v_notif1 FROM public.notificaciones;
    SELECT count(*) INTO v_camp1  FROM public.campanas_publicitarias;
    SELECT estado INTO v_est_sol   FROM public.solicitudes_campana WHERE id=v_solpend_np;
    SELECT estado INTO v_est_canje FROM public.canjes              WHERE id=v_canje_np;

    v_ok := v_det NOT LIKE '%PASO!%' AND v_det NOT LIKE '%otro(%'
        AND v_notif1=v_notif0 AND v_camp1=v_camp0
        AND v_est_sol='enviada' AND v_est_canje='pendiente';
    v_507 := CASE WHEN v_ok
      THEN 'BLOQUEADO en las 4 con la senal correcta, Y SIN EFECTO: notificaciones '||v_notif0||'='||v_notif1
           ||', campanas '||v_camp0||'='||v_camp1||', solicitud sigue '||v_est_sol||' (enviada), canje sigue '||v_est_canje
      ELSE 'ROJO ('||v_det||'| notificaciones '||v_notif0||'->'||v_notif1||' campanas '||v_camp0||'->'||v_camp1
           ||' solicitud='||COALESCE(v_est_sol,'?')||' canje='||COALESCE(v_est_canje,'?')||')' END;

    -- ===================== P508 / P509: NO REGRESION =====================
    FOR r IN SELECT * FROM (VALUES ('super', v_super, v_solpend_sa, v_canje_sa),
                                   ('adminpais', v_adminpais, v_solpend_ap, v_canje_ap)) t(etq,uid,sol,canje) LOOP
      PERFORM set_config('request.jwt.claims',
        json_build_object('sub', r.uid::text,'role','authenticated')::text, true);
      PERFORM set_config('role','authenticated', true);
      v_det := '';
      BEGIN PERFORM public.notificar_pago_resultado(v_pago_gt); v_det := v_det||'notif_pago=paso ';
      EXCEPTION WHEN OTHERS THEN v_det := v_det||'notif_pago='||CASE WHEN SQLSTATE='PT002' THEN 'RECHAZO_AUTZ!' ELSE 'paso('||SQLSTATE||')' END||' '; END;
      BEGIN PERFORM public.notificar_campana_resultado(v_solpub_gt); v_det := v_det||'notif_campana=paso ';
      EXCEPTION WHEN OTHERS THEN v_det := v_det||'notif_campana='||CASE WHEN SQLSTATE='PT002' THEN 'RECHAZO_AUTZ!' ELSE 'paso('||SQLSTATE||')' END||' '; END;
      BEGIN PERFORM public.aprobar_solicitud_campana(r.sol,'nota'); v_det := v_det||'aprobar_campana=paso ';
      EXCEPTION WHEN OTHERS THEN v_det := v_det||'aprobar_campana='||CASE WHEN SQLSTATE='P0001' AND SQLERRM LIKE 'No autorizado%' THEN 'RECHAZO_AUTZ!' ELSE 'paso('||SQLSTATE||')' END||' '; END;
      BEGIN PERFORM public.resolver_canje(r.canje, true, NULL); v_det := v_det||'resolver_canje=paso ';
      EXCEPTION WHEN OTHERS THEN v_det := v_det||'resolver_canje='||CASE WHEN SQLSTATE='P0001' AND SQLERRM='no_autorizado' THEN 'RECHAZO_AUTZ!' ELSE 'paso('||SQLSTATE||')' END||' '; END;
      PERFORM set_config('role','none', true);
      IF r.etq='super' THEN
        v_508 := CASE WHEN v_det NOT LIKE '%RECHAZO_AUTZ!%' THEN 'OK (super_admin sin rechazo de autz en las 4: '||v_det||')'
                      ELSE 'ROJO — GATE CERRADO DE MAS para super_admin ('||v_det||')' END;
      ELSE
        v_509 := CASE WHEN v_det NOT LIKE '%RECHAZO_AUTZ!%' THEN 'OK (admin_pais GT sin rechazo de autz en las 4 sobre SU pais: '||v_det||')'
                      ELSE 'ROJO — GATE CERRADO DE MAS para admin_pais ('||v_det||')' END;
      END IF;
    END LOOP;

    -- ===================== P510: CROSS-PAIS =====================
    PERFORM set_config('request.jwt.claims',
      json_build_object('sub', v_adminpais::text,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    v_det := '';
    BEGIN PERFORM public.notificar_pago_resultado(v_pago_sv); v_det := v_det||'notif_pago=PASO! ';
    EXCEPTION WHEN OTHERS THEN v_det := v_det||'notif_pago='||CASE WHEN SQLSTATE='PT002' THEN 'BLOQ' ELSE 'otro('||SQLSTATE||')' END||' '; END;
    BEGIN PERFORM public.notificar_campana_resultado(v_solpub_sv); v_det := v_det||'notif_campana=PASO! ';
    EXCEPTION WHEN OTHERS THEN v_det := v_det||'notif_campana='||CASE WHEN SQLSTATE='PT002' THEN 'BLOQ' ELSE 'otro('||SQLSTATE||')' END||' '; END;
    BEGIN PERFORM public.aprobar_solicitud_campana(v_solpend_sv,'nota'); v_det := v_det||'aprobar_campana=PASO! ';
    EXCEPTION WHEN OTHERS THEN v_det := v_det||'aprobar_campana='||CASE WHEN SQLSTATE='P0001' AND SQLERRM LIKE 'No autorizado%' THEN 'BLOQ' ELSE 'otro('||SQLSTATE||')' END||' '; END;
    BEGIN PERFORM public.resolver_canje(v_canje_sv, true, NULL); v_det := v_det||'resolver_canje=PASO! ';
    EXCEPTION WHEN OTHERS THEN v_det := v_det||'resolver_canje='||CASE WHEN SQLSTATE='P0001' AND SQLERRM='no_autorizado' THEN 'BLOQ' ELSE 'otro('||SQLSTATE||')' END||' '; END;
    PERFORM set_config('role','none', true);

    SELECT estado INTO v_est_sol   FROM public.solicitudes_campana WHERE id=v_solpend_sv;
    SELECT estado INTO v_est_canje FROM public.canjes              WHERE id=v_canje_sv;
    v_ok := v_det NOT LIKE '%PASO!%' AND v_det NOT LIKE '%otro(%'
        AND v_est_sol='enviada' AND v_est_canje='pendiente';
    v_510 := CASE WHEN v_ok
      THEN 'BLOQUEADO (admin de GT no notifica ni resuelve nada de SV; los registros de SV siguen '||v_est_sol||'/'||v_est_canje||')'
      ELSE 'ROJO — FUGA CROSS-PAIS ('||v_det||'| solicitud='||COALESCE(v_est_sol,'?')||' canje='||COALESCE(v_est_canje,'?')||')' END;

    RAISE EXCEPTION 'PROBE_UNDO';
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    IF SQLERRM <> 'PROBE_UNDO' THEN v_fatal := COALESCE(v_fatal, SQLSTATE||' '||SQLERRM); END IF;
  END;

  PERFORM set_config('probe.fx_l5', COALESCE('ROJO (fixtures: '||v_fatal||')', v_fx, 'ROJO (sin resultado)'), false);
  PERFORM set_config('probe.p507',  COALESCE('ROJO (fatal: '||v_fatal||')', v_507, 'ROJO (sin resultado)'), false);
  PERFORM set_config('probe.p508',  COALESCE('ROJO (fatal: '||v_fatal||')', v_508, 'ROJO (sin resultado)'), false);
  PERFORM set_config('probe.p509',  COALESCE('ROJO (fatal: '||v_fatal||')', v_509, 'ROJO (sin resultado)'), false);
  PERFORM set_config('probe.p510',  COALESCE('ROJO (fatal: '||v_fatal||')', v_510, 'ROJO (sin resultado)'), false);
END $$;
SELECT set_config('role','none', true);

-- ############################################################################################
-- PAQUETE PA-FAILOPEN - LOTE 6 - P511-P515 + FX11 (las 5 fragiles, mig 271). CIERRA EL PAQUETE.
-- ############################################################################################
DO $$
DECLARE
  v_gt uuid := 'cbbbbe6d-59fe-4cf2-91ee-3e31ba1d5909';
  v_sv uuid := 'f2c75b8e-ef54-4a05-b2ff-7363e448f680';
  -- caller SIN NADA: ni perfiles ni cuentas_proveedor -> get_auth_user_rol() y
  -- mi_empresa_proveedor() son ambos NULL. farmacia.qa NO sirve para esto: tiene cuentas_proveedor.
  v_nadie uuid := '00000000-0000-4271-0511-0000000000ff';
  v_super uuid; v_adminpais uuid;
  v_emp_gt uuid; v_emp_sv uuid;
  v_tier_gt uuid; v_tier_sv uuid;
  v_examen_sinlab integer;
  v_notif0 bigint; v_notif1 bigint; v_cap0 bigint; v_cap1 bigint;
  v_det text := ''; v_ok boolean;
  v_511 text; v_512 text; v_513 text; v_514 text; v_515 text; v_fx text;
  v_fatal text := NULL; r record;
BEGIN
  IF to_regprocedure('private.puede_admin_pais(uuid,text[])') IS NULL THEN
    PERFORM set_config('probe.p511','ROJO (mig 265 sin aplicar)', false);
    PERFORM set_config('probe.p512','ROJO (mig 265 sin aplicar)', false);
    PERFORM set_config('probe.p513','ROJO (mig 265 sin aplicar)', false);
    PERFORM set_config('probe.p514','ROJO (mig 265 sin aplicar)', false);
    PERFORM set_config('probe.p515','ROJO (mig 265 sin aplicar)', false);
    PERFORM set_config('probe.fx_l6','ROJO (mig 265 sin aplicar)', false);
    RETURN;
  END IF;

  BEGIN
    SELECT id INTO v_super     FROM public.perfiles WHERE email='superadmin@ezpayconnect.com';
    SELECT id INTO v_adminpais FROM public.perfiles WHERE email='adminpais.qa@ezpayconnect.com';
    SELECT id INTO v_emp_gt    FROM public.empresas_proveedoras WHERE pais_id=v_gt LIMIT 1;
    IF v_super IS NULL OR v_adminpais IS NULL OR v_emp_gt IS NULL THEN
      v_fatal := 'faltan actores base'; RAISE EXCEPTION 'PROBE_UNDO';
    END IF;

    INSERT INTO public.empresas_proveedoras (nombre_empresa, tipo, estado, pais_id, email_contacto)
      VALUES ('P271 Empresa SV','farmacia','activa', v_sv,'p271.sv@example.invalid') RETURNING id INTO v_emp_sv;

    -- catalogos: una GLOBAL (pais_id NULL), una de GT, una de SV
    INSERT INTO public.capacidades_catalogo (codigo,nombre,pais_id,orden,activo) VALUES
      ('P271CAPGLOB','P271 Cap global', NULL, 900, true),
      ('P271CAPGT',  'P271 Cap GT',     v_gt, 900, true),
      ('P271CAPSV',  'P271 Cap SV',     v_sv, 900, true);
    INSERT INTO public.tiers_catalogo (codigo,nombre,pais_id,orden,activo)
      VALUES ('P271TIERGT','P271 Tier GT', v_gt, 900, true) RETURNING id INTO v_tier_gt;
    INSERT INTO public.tiers_catalogo (codigo,nombre,pais_id,orden,activo)
      VALUES ('P271TIERSV','P271 Tier SV', v_sv, 900, true) RETURNING id INTO v_tier_sv;

    -- examen SIN laboratorio: el caso 'ambos NULL' de notificar_resultado_examen
    INSERT INTO public.examenes (tipo, fecha_solicitud, estado, laboratorio_id, origen, prioridad)
      VALUES ('P271 examen sin lab', CURRENT_DATE, 'completado', NULL, 'clinica', 'normal')
      RETURNING id INTO v_examen_sinlab;

    v_fx := 'OK (empresa SV, 3 capacidades incl. GLOBAL, 2 tiers, 1 examen sin laboratorio)';

    -- ===================== P511: CALLER SIN IDENTIDAD contra las 5 =====================
    SELECT count(*) INTO v_cap0   FROM public.empresa_capacidades;
    SELECT count(*) INTO v_notif0 FROM public.notificaciones;
    PERFORM set_config('request.jwt.claims',
      json_build_object('sub', v_nadie::text,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    v_det := '';
    BEGIN PERFORM public.activar_capacidad_suelta(v_emp_gt,'P271CAPGT',NULL); v_det := v_det||'activar_cap=PASO! ';
    EXCEPTION WHEN OTHERS THEN v_det := v_det||'activar_cap='||CASE WHEN SQLSTATE='PC001' THEN 'BLOQ' ELSE 'otro('||SQLSTATE||')' END||' '; END;
    BEGIN PERFORM public.asignar_tier(v_emp_gt, v_tier_gt, NULL); v_det := v_det||'asignar_tier=PASO! ';
    EXCEPTION WHEN OTHERS THEN v_det := v_det||'asignar_tier='||CASE WHEN SQLSTATE='PC001' THEN 'BLOQ' ELSE 'otro('||SQLSTATE||')' END||' '; END;
    BEGIN PERFORM public.notificar_empresa_estado(v_emp_gt); v_det := v_det||'notif_empresa=PASO! ';
    EXCEPTION WHEN OTHERS THEN v_det := v_det||'notif_empresa='||CASE WHEN SQLSTATE='PT002' THEN 'BLOQ' ELSE 'otro('||SQLSTATE||')' END||' '; END;
    BEGIN PERFORM public.registrar_evidencia_entrega(1,'x/1/foto.png','foto'); v_det := v_det||'evidencia=PASO! ';
    EXCEPTION WHEN OTHERS THEN v_det := v_det||'evidencia=BLOQ '; END;
    PERFORM set_config('role','none', true);
    SELECT count(*) INTO v_cap1   FROM public.empresa_capacidades;
    SELECT count(*) INTO v_notif1 FROM public.notificaciones;
    v_ok := v_det NOT LIKE '%PASO!%' AND v_det NOT LIKE '%otro(%' AND v_cap1=v_cap0 AND v_notif1=v_notif0;
    v_511 := CASE WHEN v_ok
      THEN 'BLOQUEADO (candado: sigue bloqueando, capacidades '||v_cap0||'='||v_cap1||', notificaciones '||v_notif0||'='||v_notif1||') '||v_det
      ELSE 'ROJO ('||v_det||'| capacidades '||v_cap0||'->'||v_cap1||' notificaciones '||v_notif0||'->'||v_notif1||')' END;

    -- ===================== P512 / P513: NO REGRESION =====================
    FOR r IN SELECT * FROM (VALUES ('super', v_super), ('adminpais', v_adminpais)) t(etq,uid) LOOP
      PERFORM set_config('request.jwt.claims',
        json_build_object('sub', r.uid::text,'role','authenticated')::text, true);
      PERFORM set_config('role','authenticated', true);
      v_det := '';
      -- capacidad de SU pais
      BEGIN PERFORM public.activar_capacidad_suelta(v_emp_gt,'P271CAPGT',NULL); v_det := v_det||'cap_GT=paso ';
      EXCEPTION WHEN OTHERS THEN v_det := v_det||'cap_GT=RECHAZO('||SQLSTATE||') '; END;
      -- capacidad GLOBAL (pais_id NULL): el termino load-bearing
      BEGIN PERFORM public.activar_capacidad_suelta(v_emp_gt,'P271CAPGLOB',NULL); v_det := v_det||'cap_GLOBAL=paso ';
      EXCEPTION WHEN OTHERS THEN v_det := v_det||'cap_GLOBAL=RECHAZO('||SQLSTATE||') '; END;
      BEGIN PERFORM public.asignar_tier(v_emp_gt, v_tier_gt, NULL); v_det := v_det||'tier_GT=paso ';
      EXCEPTION WHEN OTHERS THEN v_det := v_det||'tier_GT=RECHAZO('||SQLSTATE||') '; END;
      BEGIN PERFORM public.notificar_empresa_estado(v_emp_gt); v_det := v_det||'notif_empresa=paso ';
      EXCEPTION WHEN OTHERS THEN v_det := v_det||'notif_empresa='||CASE WHEN SQLSTATE='PT002' THEN 'RECHAZO_AUTZ!' ELSE 'paso('||SQLSTATE||')' END||' '; END;
      PERFORM set_config('role','none', true);
      IF r.etq='super' THEN
        v_512 := CASE WHEN v_det NOT LIKE '%RECHAZO%' THEN 'OK (super_admin sin rechazo: '||v_det||')'
                      ELSE 'ROJO — GATE CERRADO DE MAS para super_admin ('||v_det||')' END;
      ELSE
        v_513 := CASE WHEN v_det NOT LIKE '%RECHAZO%'
                      THEN 'OK (admin_pais GT sin rechazo, INCLUIDA la capacidad GLOBAL: '||v_det||')'
                      ELSE 'ROJO — GATE CERRADO DE MAS para admin_pais ('||v_det||')' END;
      END IF;
    END LOOP;

    -- ===================== P514: CROSS-PAIS (PC015 / PC016) =====================
    PERFORM set_config('request.jwt.claims',
      json_build_object('sub', v_adminpais::text,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    v_det := '';
    BEGIN PERFORM public.activar_capacidad_suelta(v_emp_gt,'P271CAPSV',NULL); v_det := v_det||'cap_SV=PASO! ';
    EXCEPTION WHEN OTHERS THEN v_det := v_det||'cap_SV='||CASE WHEN SQLSTATE='PC015' THEN 'BLOQ' ELSE 'otro('||SQLSTATE||')' END||' '; END;
    BEGIN PERFORM public.asignar_tier(v_emp_gt, v_tier_sv, NULL); v_det := v_det||'tier_SV=PASO! ';
    EXCEPTION WHEN OTHERS THEN v_det := v_det||'tier_SV='||CASE WHEN SQLSTATE='PC016' THEN 'BLOQ' ELSE 'otro('||SQLSTATE||')' END||' '; END;
    PERFORM set_config('role','none', true);
    v_514 := CASE WHEN v_det NOT LIKE '%PASO!%' AND v_det NOT LIKE '%otro(%'
      THEN 'BLOQUEADO (PC015/PC016: admin de GT no asigna catalogo de SV) '||v_det
      ELSE 'ROJO ('||v_det||')' END;

    -- ===================== P515: EL CAMBIO DE COMPORTAMIENTO DECLARADO =====================
    -- notificar_resultado_examen sobre un examen con laboratorio_id NULL, llamada por un caller
    -- cuyo mi_empresa_proveedor() tambien es NULL. ANTES: IS DISTINCT FROM (NULL,NULL) = false ->
    -- no levantaba -> pasaba y notificaba. AHORA: NOT COALESCE(NULL = NULL, false) = true -> PT002.
    SELECT count(*) INTO v_notif0 FROM public.notificaciones;
    PERFORM set_config('request.jwt.claims',
      json_build_object('sub', v_nadie::text,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    v_det := '';
    BEGIN PERFORM public.notificar_resultado_examen(v_examen_sinlab); v_det := 'PASO (ambos NULL colaban)';
    EXCEPTION WHEN OTHERS THEN v_det := CASE WHEN SQLSTATE='PT002' THEN 'BLOQ(PT002)' ELSE 'otro('||SQLSTATE||')' END; END;
    PERFORM set_config('role','none', true);
    SELECT count(*) INTO v_notif1 FROM public.notificaciones;
    v_515 := CASE WHEN v_det='BLOQ(PT002)' AND v_notif1=v_notif0
      THEN 'BLOQUEADO (el caso ambos-NULL ya no pasa; notificaciones '||v_notif0||'='||v_notif1||')'
      ELSE 'ROJO/PREVIO ('||v_det||'; notificaciones '||v_notif0||'->'||v_notif1||')' END;

    RAISE EXCEPTION 'PROBE_UNDO';
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    IF SQLERRM <> 'PROBE_UNDO' THEN v_fatal := COALESCE(v_fatal, SQLSTATE||' '||SQLERRM); END IF;
  END;

  PERFORM set_config('probe.fx_l6', COALESCE('ROJO (fixtures: '||v_fatal||')', v_fx, 'ROJO (sin resultado)'), false);
  PERFORM set_config('probe.p511',  COALESCE('ROJO (fatal: '||v_fatal||')', v_511, 'ROJO (sin resultado)'), false);
  PERFORM set_config('probe.p512',  COALESCE('ROJO (fatal: '||v_fatal||')', v_512, 'ROJO (sin resultado)'), false);
  PERFORM set_config('probe.p513',  COALESCE('ROJO (fatal: '||v_fatal||')', v_513, 'ROJO (sin resultado)'), false);
  PERFORM set_config('probe.p514',  COALESCE('ROJO (fatal: '||v_fatal||')', v_514, 'ROJO (sin resultado)'), false);
  PERFORM set_config('probe.p515',  COALESCE('ROJO (fatal: '||v_fatal||')', v_515, 'ROJO (sin resultado)'), false);
END $$;
SELECT set_config('role','none', true);

-- ############################################################################################
-- B2 FASE 1 - P516: SENALIZADOR DEL GATE DE ESTRUCTURA (NO MIDE NADA)
-- ############################################################################################
-- ESTE PROBE NO ES UN CONTROL. No puede serlo: para medir la estructura del harness habria que leer
-- ESTE ARCHIVO desde SQL, y no se puede — pg_read_file() lee del SERVIDOR y exige superusuario o
-- pg_read_server_files, mientras que este archivo vive en la maquina del cliente y viaja por la
-- Management API. Un probe no puede autoexaminarse el fuente.
--
-- El gate REAL vive en `tests/rls/b2_guard.py`, que parsea el archivo y sale con codigo != 0 si
-- alguno de los dos numeros CRECE. Este probe solo PUBLICA el baseline declarado, para que quien lea
-- la salida del harness sepa que ese gate existe y cuales son los numeros que hay que sostener.
-- Si el baseline de aca y el del script divergen, el que manda es el script: es el unico que cuenta.
--
--   top_level_dml_ddl = 0    Sentencias DML/DDL fuera de todo bloque DO. La fase 1 las llevo a CERO:
--                            14 envueltas (FX12-FX18). Se EXCLUYE `CREATE ... pg_temp.*`, que es DDL
--                            transaccional sobre un schema temporal, no puede corromper ningun
--                            fixture y desaparece con el ROLLBACK.
--
--   cast_directo = 0         Bloques DO sin handler con `current_setting('x',true)::T` SIN NULLIF.
--                            El harness setea CADENAS VACIAS a proposito (88 coalesce(...,'') dentro
--                            de set_config) y ''::uuid es 22P02: mata la transaccion igual que un
--                            NOT NULL. Fase 2.1 CERRADA: 155 -> 0 en tres tandas.
--
--   do_sin_handler = 155     Bloques DO sin `EXCEPTION WHEN`. YA NO ES DEUDA: la fase 2.2 cerro los
--                            55 bloques que ESCRIBEN (211 -> 193 -> 175 -> 157 -> 156, P481 incluido)
--                            y los 156 que quedan solo LEEN y publican — si uno cae no arrastra estado
--                            ajeno. Este numero es el normal del archivo; sube si alguien agrega un
--                            bloque sin handler. La regla es ESTRICTA — un `RAISE EXCEPTION` NO cuenta
--                            como handler, es lo contrario; el detector ademas quita los literales SQL
--                            antes de buscar (b2_guard_test.py fija las dos direcciones del error). Cuando uno envuelto cae, su veredicto queda
--                            vacio (lo caza P000) y FX19 dice cual y con que SQLSTATE — las tres senales
--                            se PROBARON en rojo a proposito, no se asumieron (ver el commit de la tanda 2).
--                            Para los bloques que no publican veredicto propio, FX19 es el UNICO delator.
--
-- POR QUE IMPORTA: cuatro de las sentencias top-level ya mataron la transaccion entera una vez
-- (incidente del lote 1: empresa_id=NULL -> 23502, sin una sola fila de salida). Un harness que
-- muere no da rojo: no da NADA, y eso se lee como "todavia no lo corri".
-- ############################################################################################
DO $$
BEGIN
  PERFORM set_config('probe.p516',
    'OK-SENAL (baseline declarado: top_level_dml_ddl=0 excluyendo pg_temp, cast_directo=0 CERRADO, do_sin_handler=155, fase 2.2 CERRADA: los restantes solo LEEN). '||
    'El gate real es tests/rls/b2_guard.py — este probe NO mide, senaliza.', false);
EXCEPTION WHEN OTHERS THEN
  -- handler puesto por coherencia: el propio b2_guard.py conto este bloque como deuda nueva cuando
  -- se escribio sin el. Subir el baseline para acomodar el codigo del gate habria sido exactamente
  -- lo que el gate existe para impedir.
  PERFORM set_config('probe.p516','ROJO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;

-- ############################################################################################
-- B2 FASE 2.2 - FX19: REPORTE DE CAIDAS DE LOS BLOQUES ENVUELTOS
-- ############################################################################################
-- Los handlers de la fase 2.2 NO publican el veredicto de su bloque, a proposito: si lo hicieran
-- inventarian un texto que podria leerse como verde. Cuando un bloque envuelto cae pasan DOS cosas,
-- las dos VISIBLES, y entre las dos distinguen "paso" de "exploto":
--   1) el bloque se revierte hasta su savepoint implicito, asi que su propio veredicto queda SIN
--      publicar -> el centinela anti-null P000 lo caza como VACIO;
--   2) FX19 dice CUAL cayo (linea de inicio) y con que SQLSTATE.
-- El set_config del handler SI persiste: corre DESPUES del rollback al savepoint, en el contexto
-- que sobrevive. Antes de la fase 2.2 esa misma caida mataba la transaccion entera y no habia NADA.
-- ############################################################################################
DO $$
DECLARE v text := coalesce(current_setting('probe.b2_fallos', true), '');
BEGIN
  PERFORM set_config('probe.fx_b2fallos', CASE WHEN v = ''
    THEN 'OK (ningun bloque envuelto por la fase 2.2 cayo)'
    ELSE 'ROJO - bloques caidos, el harness sobrevivio gracias al handler: '||v END, false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('probe.fx_b2fallos','ROJO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;


-- ############################################################################################
-- MODULO COMERCIAL · RPCs de escritura (P517-P534). RED-FIRST: las 7 RPCs no existen todavia.
-- --------------------------------------------------------------------------------------------
-- Cada probe distingue TRES estados, y esa distincion es lo que la vuelve un gate y no un adorno:
--   'ROJO — RPC AUSENTE'   la funcion no existe             <- rojo legitimo de la fase red-first
--   'ROJO (PERMITIDO...)'  existe y NO rechazo              <- el bug que se busca
--   'OK (...)'             rechazo con el errcode esperado, o permitio donde D1 manda permitir
-- Sin esa distincion "rojo porque no existe" y "rojo porque no autorizo" se leen igual, y una
-- probe que no los separa no cierra nada.
--
-- LOS SUJETOS DE OTRO PAIS NO EXISTEN EN LA BASE: hoy los dos admin_pais son GT y los tres
-- asesores tambien. Se siembran aca dentro y mueren con el ROLLBACK. Los tres perfiles que se
-- mutan (df452940, 85a3faf8, 55aaa118) se verificaron sin uso en el resto del harness.
-- nombre_norm NO se setea: es GENERATED ALWAYS AS (private.norm_prospecto_nombre(nombre)).
-- ############################################################################################
SELECT set_config('role','none', true);
DO $$
DECLARE v_gt uuid := 'cbbbbe6d-59fe-4cf2-91ee-3e31ba1d5909'; v_hn uuid := '704aecfa-65c2-47f9-9a98-7a9bdfeba583';
        v_admgt uuid := '8f391caf-85bc-4413-af8a-4006452ae09f';   -- admin_pais GT (real, no se toca)
        v_admhn uuid := 'df452940-cc30-48b7-80e5-09e637bf97de';   -- se convierte en admin_pais HN
        -- LOS TRES SUJETOS COMERCIALES SE RESUELVEN POR EMAIL, NO POR UUID LITERAL.
        -- Estaban clavados como literales y el 8-sep-2026 la limpieza de datos QA borro esas tres
        -- filas: 23 probes se pusieron rojas de golpe, la mayoria diciendo "TABLAS AUSENTES", que
        -- apunta al lado equivocado. El email es estable y la fila se puede recrear; el uuid lo
        -- asigna Auth y cambia en cada alta. Mismo patron que ya usaba el archivo para
        -- superadmin@ezpayconnect.com y adminpais.qa@ezpayconnect.com.
        -- Las cuentas las recrea `scripts/recrear-fixtures-harness-comercial.mjs`.
        v_sup   uuid;   -- supervisor_comercial GT
        v_ase1  uuid;   -- asesor GT, EN la cartera del sup
        v_ase2  uuid;   -- asesor GT, FUERA de esa cartera
        v_asehn uuid := '85a3faf8-9986-4c8e-821b-4351473a91f0';   -- se convierte en asesor HN
        v_medf  uuid := '55aaa118-1b02-44ed-b2b7-dcd2b8741cd7';   -- medico GT + ficha (para PA009)
        v_p1 uuid; v_p2 uuid; v_pt uuid; v_c2 uuid; v_ok boolean;
BEGIN
  -- Si alguno no existe queda NULL, los EXISTS de abajo dan false y v_ok cae solo: el fixture se
  -- declara AUSENTE como ya hacia, sin guard extra y sin reventar.
  SELECT id INTO v_sup  FROM public.perfiles WHERE email = 'supervisor.qa@ezpayconnect.com';
  SELECT id INTO v_ase1 FROM public.perfiles WHERE email = 'asesor1.qa@ezpayconnect.com';
  SELECT id INTO v_ase2 FROM public.perfiles WHERE email = 'asesor2.qa@ezpayconnect.com';

  v_ok := EXISTS(SELECT 1 FROM public.asesores_perfil WHERE id=v_ase1 AND supervisor_id=v_sup)
      AND EXISTS(SELECT 1 FROM public.asesores_perfil WHERE id=v_ase2 AND supervisor_id IS NULL)
      AND EXISTS(SELECT 1 FROM public.asesores_perfil WHERE id=v_sup)
      AND EXISTS(SELECT 1 FROM public.perfiles WHERE id=v_admhn)
      AND EXISTS(SELECT 1 FROM public.perfiles WHERE id=v_asehn)
      AND EXISTS(SELECT 1 FROM public.perfiles WHERE id=v_medf);
  IF NOT v_ok THEN PERFORM set_config('probe.co_ready','0',false); RETURN; END IF;

  -- admin_pais de OTRO pais
  UPDATE public.perfiles SET pais_id = v_hn, rol = 'admin_pais' WHERE id = v_admhn;
  -- asesor de OTRO pais, con ficha propia en HN
  -- supervisor_comercial, no asesor: P529 mide PA003 (pais de la jerarquia) y si fuera
  -- asesor el guard cortaria antes en PA001 (rol) y la probe mediria otra cosa.
  UPDATE public.perfiles SET pais_id = v_hn, rol = 'supervisor_comercial' WHERE id = v_asehn;
  INSERT INTO public.asesores_perfil (id, codigo_asesor, pais_id, activo)
    VALUES (v_asehn, 'QA-SUP-HN-COM', v_hn, true)
    ON CONFLICT (id) DO UPDATE SET pais_id = EXCLUDED.pais_id, activo = true;
  -- ficha para un MEDICO: hoy nada en la DB lo impide, y es exactamente lo que viene a cerrar PA009
  INSERT INTO public.asesores_perfil (id, codigo_asesor, pais_id, activo)
    VALUES (v_medf, 'QA-MED-FICHA-COM', v_gt, true)
    ON CONFLICT (id) DO UPDATE SET pais_id = EXCLUDED.pais_id, activo = true;

  -- prospectos: uno de ase1 (cartera del supervisor), uno de ase2 (fuera), uno TERMINAL
  INSERT INTO public.prospectos (nombre, tipo, pais_id, asesor_id, creado_por, estado_pipeline)
    VALUES ('QA COM fixture ASE1','farmacia',v_gt,v_ase1,v_admgt,'nuevo') RETURNING id INTO v_p1;
  INSERT INTO public.prospectos (nombre, tipo, pais_id, asesor_id, creado_por, estado_pipeline)
    VALUES ('QA COM fixture ASE2','farmacia',v_gt,v_ase2,v_admgt,'nuevo') RETURNING id INTO v_p2;
  INSERT INTO public.prospectos (nombre, tipo, pais_id, asesor_id, creado_por, estado_pipeline)
    VALUES ('QA COM fixture TERMINAL','farmacia',v_gt,v_ase1,v_admgt,'ganado') RETURNING id INTO v_pt;
  INSERT INTO public.prospecto_contactos (prospecto_id, nombre) VALUES (v_p2,'QA COM contacto de ASE2') RETURNING id INTO v_c2;

  PERFORM set_config('probe.co_gt',     v_gt::text,     false);
  PERFORM set_config('probe.co_hn',     v_hn::text,     false);
  PERFORM set_config('probe.co_admgt',  v_admgt::text,  false);
  PERFORM set_config('probe.co_admhn',  v_admhn::text,  false);
  PERFORM set_config('probe.co_sup',    v_sup::text,    false);
  PERFORM set_config('probe.co_ase1',   v_ase1::text,   false);
  PERFORM set_config('probe.co_ase2',   v_ase2::text,   false);
  PERFORM set_config('probe.co_asehn',  v_asehn::text,  false);
  PERFORM set_config('probe.co_medf',   v_medf::text,   false);
  PERFORM set_config('probe.co_p_ase1', v_p1::text,     false);
  PERFORM set_config('probe.co_p_ase2', v_p2::text,     false);
  PERFORM set_config('probe.co_p_term', v_pt::text,     false);
  PERFORM set_config('probe.co_c_ase2', v_c2::text,     false);
  PERFORM set_config('probe.co_ready',  '1', false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('probe.co_ready','0',false);
  PERFORM set_config('probe.co_fx','ROJO ('||SQLSTATE||' '||SQLERRM||')',false);
END $$;

DO $$ BEGIN
  PERFORM set_config('probe.co_fx', coalesce(NULLIF(current_setting('probe.co_fx',true),''),
    CASE WHEN current_setting('probe.co_ready',true)='1'
         THEN 'OK (fixture comercial: admin HN, asesor HN, ficha de medico, 3 prospectos, 1 contacto)'
         ELSE 'ROJO (fixture comercial NO sembrado y sin error capturado)' END), false);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.co_fx','ROJO ('||SQLSTATE||')',false); END $$;

-- P517 — crear_prospecto con asesor de OTRO pais -> OK (42501 no_autorizado)
--   por que: el pais NO es parametro: sale de la ficha. Admin GT + comercial HN => el gate cae sobre HN
SELECT set_config('request.jwt.claims', json_build_object('sub', current_setting('probe.co_admgt',true), 'role','authenticated')::text, true);
SELECT set_config('role','authenticated', true);
DO $$ BEGIN
  IF current_setting('probe.co_ready',true)<>'1' THEN PERFORM set_config('probe.p517','N/A (fixture comercial ausente)',false); RETURN; END IF;
  IF to_regprocedure('public.crear_prospecto(text,text,uuid,text,numeric,numeric,text,uuid)') IS NULL THEN
    PERFORM set_config('probe.p517','ROJO — RPC AUSENTE (todavia no existe; esto NO es un rechazo)',false); RETURN; END IF;
  BEGIN
    PERFORM public.crear_prospecto('QA COM P517 asesor ajeno','farmacia',NULLIF(current_setting('probe.co_asehn',true),'')::uuid);
    PERFORM set_config('probe.p517','ROJO (PERMITIDO — tenia que rechazar con 42501)',false);
  EXCEPTION WHEN insufficient_privilege THEN PERFORM set_config('probe.p517','OK (42501 no_autorizado)',false);
            WHEN others THEN PERFORM set_config('probe.p517','FALLO (esperaba 42501, vino '||SQLSTATE||': '||SQLERRM||')',false);
