-- P597 — CONTROL POSITIVO de adopcion: ase2 planifica para HOY sin jornada -> jornada_id NULL;
--        abre la jornada -> la visita queda con jornada_id = la nueva. Se lee la fila en cada paso.
DO $$ DECLARE v_id uuid; v_j_antes uuid; v_j uuid; v_j_despues uuid; BEGIN
  IF coalesce(current_setting('probe.ag_ready',true),'')<>'1' THEN PERFORM set_config('probe.p597','N/A',false); RETURN; END IF;
  BEGIN
    SELECT public.planificar_visita(NULLIF(current_setting('probe.ag_p_b2',true),'')::uuid, CURRENT_DATE, NULL) INTO v_id;
  EXCEPTION WHEN others THEN PERFORM set_config('probe.p597','FALLO (no se pudo planificar: '||SQLSTATE||' '||SQLERRM||')',false); RETURN; END;
  SELECT jornada_id INTO v_j_antes FROM public.visitas_comerciales WHERE id = v_id;
  IF v_j_antes IS NOT NULL THEN
    PERFORM set_config('probe.p597','FALLO (la visita nacio con jornada_id, el fixture no es huerfano: ase2 ya tenia jornada)',false); RETURN; END IF;
  BEGIN
    SELECT public.abrir_jornada(NULL,NULL,NULL) INTO v_j;
  EXCEPTION WHEN others THEN PERFORM set_config('probe.p597','FALLO (ase2 no pudo abrir jornada: '||SQLSTATE||' '||SQLERRM||')',false); RETURN; END;
  SELECT jornada_id INTO v_j_despues FROM public.visitas_comerciales WHERE id = v_id;
  PERFORM set_config('probe.p597', CASE
    WHEN v_j_despues = v_j THEN 'OK (nacio huerfana con jornada_id NULL y abrir_jornada la ADOPTO: jornada_id = la nueva)'
    WHEN v_j_despues IS NULL THEN 'ROJO (abrir_jornada NO adopto la visita huerfana: sigue con jornada_id NULL)'
    ELSE 'FALLO (jornada_id apunta a otra jornada: '||v_j_despues||' vs '||v_j||')' END, false);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p597','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;
SELECT set_config('role','none', true);

-- ============================================================================================
-- Lectura de las FILAS como owner: P586, P587, P591, P595 se resuelven con lo que quedo escrito
-- ============================================================================================
DO $$ DECLARE r record; v_ase1 uuid; v_sup uuid; v_jhoy uuid; BEGIN
  IF coalesce(current_setting('probe.ag_ready',true),'')<>'1' THEN RETURN; END IF;
  v_ase1 := NULLIF(current_setting('probe.co_ase1',true),'')::uuid;
  v_sup  := NULLIF(current_setting('probe.co_sup',true),'')::uuid;
  v_jhoy := NULLIF(current_setting('probe.vj_jornada',true),'')::uuid;

  IF current_setting('probe.p586',true) = 'PENDIENTE' THEN
    SELECT * INTO r FROM public.visitas_comerciales WHERE id = NULLIF(current_setting('probe.ag_v_a1',true),'')::uuid;
    PERFORM set_config('probe.p586', CASE
      WHEN r.id IS NULL THEN 'FALLO (la RPC devolvio id pero no hay fila)'
      WHEN r.planificada_por IS DISTINCT FROM v_ase1 THEN 'ROJO (planificada_por='||coalesce(r.planificada_por::text,'NULL')||', se esperaba el asesor)'
      WHEN r.hora_planificada IS DISTINCT FROM '10:30'::time THEN 'ROJO (hora_planificada='||coalesce(r.hora_planificada::text,'NULL')||', se envio 10:30)'
      WHEN r.fecha_planificada <> CURRENT_DATE + 1 THEN 'ROJO (fecha='||r.fecha_planificada||')'
      ELSE 'OK (fila: planificada_por = asesor, hora = 10:30, fecha = manana, estado = '||r.estado||')' END, false);
  END IF;

  IF current_setting('probe.p587',true) = 'PENDIENTE' THEN
    SELECT * INTO r FROM public.visitas_comerciales WHERE id = NULLIF(current_setting('probe.ag_v_a2',true),'')::uuid;
    PERFORM set_config('probe.p587', CASE
      WHEN r.id IS NULL THEN 'FALLO (sin fila)'
      WHEN r.asesor_id IS DISTINCT FROM v_ase1 THEN 'ROJO (asesor_id='||coalesce(r.asesor_id::text,'NULL')||': el supervisor se apropio de la visita)'
      WHEN r.planificada_por IS DISTINCT FROM v_sup THEN 'ROJO (planificada_por='||coalesce(r.planificada_por::text,'NULL')||', se esperaba el supervisor)'
      WHEN r.hora_planificada IS DISTINCT FROM '16:15'::time THEN 'ROJO (hora='||coalesce(r.hora_planificada::text,'NULL')||')'
      ELSE 'OK (fila: asesor_id = asesor, planificada_por = SUPERVISOR — la autoria quedo, la visita no cambio de dueno)' END, false);
  END IF;

  IF current_setting('probe.p591',true) = 'PENDIENTE' THEN
    SELECT * INTO r FROM public.visitas_comerciales WHERE id = NULLIF(current_setting('probe.ag_v_a4',true),'')::uuid;
    PERFORM set_config('probe.p591', CASE
      WHEN r.id IS NULL THEN 'FALLO (sin fila)'
      WHEN r.fecha_planificada <> CURRENT_DATE THEN 'ROJO (fecha no cambio: '||r.fecha_planificada||')'
      WHEN r.hora_planificada IS DISTINCT FROM '11:00'::time THEN 'ROJO (hora='||coalesce(r.hora_planificada::text,'NULL')||', se envio 11:00)'
      WHEN r.jornada_id IS NULL THEN 'ROJO (reprogramada a HOY pero jornada_id sigue NULL: no se recalculo)'
      WHEN r.jornada_id IS DISTINCT FROM v_jhoy THEN 'FALLO (jornada_id='||r.jornada_id||' no es la jornada de hoy de ase1 '||coalesce(v_jhoy::text,'?')||')'
      ELSE 'OK (fecha y hora cambiaron; jornada_id RECALCULADO: de NULL a la jornada de hoy)' END, false);
  END IF;

  IF current_setting('probe.p595',true) = 'PENDIENTE' THEN
    SELECT * INTO r FROM public.visitas_comerciales WHERE id = NULLIF(current_setting('probe.ag_v_a5',true),'')::uuid;
    PERFORM set_config('probe.p595', CASE
      WHEN r.id IS NULL THEN 'FALLO (sin fila)'
      WHEN r.estado <> 'cancelada' THEN 'ROJO (estado='||r.estado||', se esperaba cancelada)'
      WHEN coalesce(r.cancelacion_motivo,'') = '' THEN 'ROJO (cancelada SIN motivo guardado: el CHECK no deberia haberlo permitido)'
      ELSE 'OK (estado = cancelada, motivo = "'||r.cancelacion_motivo||'")' END, false);
  END IF;
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('probe.p586','FALLO al leer filas ('||SQLSTATE||' '||SQLERRM||')',false);
END $$;

-- P598 — anon SIN EXECUTE sobre las 3 RPCs (y abrir_jornada, que se recreo)
DO $$ DECLARE v_malas text; BEGIN
  IF to_regprocedure('public.planificar_visita(uuid,date,time without time zone)') IS NULL THEN
    PERFORM set_config('probe.p598','ROJO — MIG 280 AUSENTE',false); RETURN; END IF;
  SELECT string_agg(f, ', ') INTO v_malas FROM (
    SELECT p.oid::regprocedure::text AS f FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
     WHERE n.nspname='public'
       AND p.proname IN ('planificar_visita','reprogramar_visita_comercial','cancelar_visita_comercial','abrir_jornada')
       AND (has_function_privilege('anon', p.oid, 'EXECUTE') OR NOT has_function_privilege('authenticated', p.oid, 'EXECUTE'))
  ) s;
  PERFORM set_config('probe.p598', CASE WHEN v_malas IS NULL
    THEN 'OK (anon=false y authenticated=true en las 4 funciones)'
    ELSE 'ROJO (privilegios mal en: '||v_malas||')' END, false);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p598','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;

-- ############################################################################################
-- P599-P601 — privilegio POR COLUMNA sobre visitas_comerciales (mig 281)
-- ############################################################################################
-- CONTEXTO. Desde la 277 `authenticated` no tiene SELECT de TABLA sobre visitas_comerciales: tiene
-- SELECT columna por columna, para dejar afuera las 4 de coordenada. La 280 agrego 3 columnas y no
-- las incluyo en ningun GRANT, y como el front pide una lista EXPLICITA de columnas, se rompio TODA
-- la lectura de visitas con 42501/403. Un ALTER TABLE ADD COLUMN sobre una tabla con grants por
-- columna es un cambio de privilegios disfrazado de cambio de esquema, y nada lo estaba mirando.
--
-- P599 es el CASO: reproduce el SELECT que rompio en el navegador.
-- P600 es el CENSO: la forma de P574 pero invertida. P574 pregunta "ninguna coordenada es legible";
--   P600 pregunta "toda columna que NO es coordenada SI lo es". Es censo y no caso porque manana
--   alguien agrega otra columna y el caso puntual no la ve — que es exactamente como paso esta vez.
-- P601 es el CONTROL POSITIVO de P600: sin el, alguien "arregla" el 403 con un GRANT de tabla
--   entera, P600 queda verde y las coordenadas vuelven a ser legibles.
--
-- Los tres usan has_column_privilege() y no information_schema.column_privileges, que es lo que usa
-- P574: information_schema solo lista los grants por columna EXPLICITOS, asi que un GRANT de tabla
-- entera lo dejaria pasar. has_column_privilege() responde la pregunta real —"puede leer esto?"— y
-- cubre las dos formas. Y la enumeracion sale de pg_attribute y no de information_schema.columns,
-- que esta FILTRADA POR PRIVILEGIO: leida como authenticated, una columna sin grant no aparece, y el
-- probe reportaria "la columna no existe" en vez de "no la puede leer".

-- P599 — como el ASESOR, SELECT explicito de las 3 columnas que agrego la 280
SELECT set_config('request.jwt.claims', json_build_object('sub', current_setting('probe.co_ase1',true), 'role','authenticated')::text, true);
SELECT set_config('role','authenticated', true);
DO $$ DECLARE v_n int; v_faltan text; v_msg text; BEGIN
  IF to_regclass('public.visitas_comerciales') IS NULL THEN
    PERFORM set_config('probe.p599','ROJO — TABLA AUSENTE (esto NO es un rechazo)',false); RETURN; END IF;
  -- pg_attribute y no information_schema.columns: la segunda esta filtrada por privilegio y sin el
  -- GRANT las columnas no aparecerian, disfrazando el 403 de "columna inexistente".
  SELECT string_agg(c, ', ') INTO v_faltan
    FROM unnest(ARRAY['hora_planificada','planificada_por','cancelacion_motivo']) c
   WHERE NOT EXISTS (SELECT 1 FROM pg_catalog.pg_attribute a
                      WHERE a.attrelid='public.visitas_comerciales'::regclass
                        AND a.attname=c AND a.attnum>0 AND NOT a.attisdropped);
  IF v_faltan IS NOT NULL THEN
    PERFORM set_config('probe.p599','ROJO — MIG 280 AUSENTE (faltan las columnas: '||v_faltan||'; esto NO es un rechazo)',false); RETURN; END IF;
  BEGIN
    SELECT count(*) INTO v_n
      FROM (SELECT hora_planificada, planificada_por, cancelacion_motivo
              FROM public.visitas_comerciales) q;
    -- el privilegio se verifica al planear, no al devolver filas: 0 filas visibles bajo RLS sigue
    -- siendo prueba de que el GRANT esta. Se dice el conteo igual, para no leer un 0 como un verde.
    PERFORM set_config('probe.p599','OK (el asesor LEE las 3 columnas de la 280; '||v_n||' filas visibles bajo RLS)',false);
  EXCEPTION WHEN insufficient_privilege THEN
    GET STACKED DIAGNOSTICS v_msg = MESSAGE_TEXT;
    PERFORM set_config('probe.p599','ROJO — SIN GRANT (42501: '||v_msg||'). El front pide estas columnas: TODA lectura de visitas falla',false);
  WHEN others THEN
    PERFORM set_config('probe.p599','FALLO (esperaba leer, vino '||SQLSTATE||': '||SQLERRM||')',false);
  END;
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p599','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;
SELECT set_config('role','none', true);

-- P600 — CENSO INVERTIDO: toda columna que NO es de coordenada tiene que ser legible por
-- authenticated. Esta es la que hace que el proximo ALTER TABLE ADD COLUMN se ponga rojo solo.
DO $$ DECLARE v_faltan text; v_total int; BEGIN
  IF to_regclass('public.visitas_comerciales') IS NULL THEN
    PERFORM set_config('probe.p600','ROJO — TABLAS AUSENTES (esto NO es un rechazo)',false); RETURN; END IF;
  SELECT count(*), string_agg(t||'.'||c, ', ') FILTER (WHERE NOT lee) INTO v_total, v_faltan FROM (
    SELECT cl.relname::text AS t, a.attname::text AS c,
           has_column_privilege('authenticated', cl.oid, a.attnum, 'SELECT') AS lee
      FROM pg_catalog.pg_attribute a
      JOIN pg_catalog.pg_class cl ON cl.oid = a.attrelid
      JOIN pg_catalog.pg_namespace n ON n.oid = cl.relnamespace
     WHERE n.nspname='public'
       AND cl.relname IN ('visitas_comerciales','jornadas_comerciales')
       AND a.attnum > 0 AND NOT a.attisdropped
       AND a.attname NOT LIKE '%\_lat' AND a.attname NOT LIKE '%\_lng'
     ORDER BY cl.relname, a.attnum) s;
  PERFORM set_config('probe.p600', CASE
    WHEN v_total = 0 THEN 'ROJO — CENSO VACIO (no censo ninguna columna; no esta midiendo nada)'
    WHEN v_faltan IS NULL THEN 'OK ('||v_total||' columnas no-coordenada de visitas y jornadas, todas legibles por authenticated)'
    ELSE 'ROJO — SIN GRANT: '||v_faltan||'  (de '||v_total||' censadas; un ADD COLUMN sobre una tabla con grants por columna es un cambio de privilegios)' END, false);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p600','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;

-- P601 — CONTROL POSITIVO de P600: las columnas de coordenada siguen SIN poder leerse. Cuenta
-- cuantas censo, porque un censo de cero columnas pasa la negativa sin medir nada (leccion de P553).
DO $$ DECLARE v_coord text; v_total int; BEGIN
  IF to_regclass('public.visitas_comerciales') IS NULL THEN
    PERFORM set_config('probe.p601','ROJO — TABLAS AUSENTES (esto NO es un rechazo)',false); RETURN; END IF;
  SELECT count(*), string_agg(t||'.'||c, ', ') FILTER (WHERE lee) INTO v_total, v_coord FROM (
    SELECT cl.relname::text AS t, a.attname::text AS c,
           has_column_privilege('authenticated', cl.oid, a.attnum, 'SELECT') AS lee
      FROM pg_catalog.pg_attribute a
      JOIN pg_catalog.pg_class cl ON cl.oid = a.attrelid
      JOIN pg_catalog.pg_namespace n ON n.oid = cl.relnamespace
     WHERE n.nspname='public'
       AND cl.relname IN ('visitas_comerciales','jornadas_comerciales')
       AND a.attnum > 0 AND NOT a.attisdropped
       AND (a.attname LIKE '%\_lat' OR a.attname LIKE '%\_lng')
     ORDER BY cl.relname, a.attnum) s;
  PERFORM set_config('probe.p601', CASE
    WHEN v_total = 0 THEN 'ROJO — NO HAY COLUMNAS DE COORDENADA que controlar (el control no mide nada)'
    WHEN v_coord IS NOT NULL THEN 'ROJO (authenticated LEE coordenadas: '||v_coord||'; de '||v_total||' censadas)'
    ELSE 'OK (las '||v_total||' columnas de coordenada siguen ilegibles para authenticated)' END, false);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p601','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;

-- ############################################################################################
-- P602-P606 — el UNIQUE por dia NO debe contar las canceladas (mig 282)
-- ############################################################################################
-- EL CASO: cancelar una visita no liberaba el dia. `visitas_com_una_por_dia` es TOTAL, asi que la
-- fila cancelada seguia ocupando la terna (prospecto, asesor, fecha) y re-agendar daba 23505/409.
-- Oscar lo reprodujo en el navegador.
--
-- P602 es el caso exacto que reprodujo. P603 y P604 son las NEGATIVAS que se conservan: aflojar el
-- UNIQUE tiene que aflojarlo SOLO para la cancelacion. P605 es el control positivo. P606 es
-- estructural: mira el indexdef, porque las cuatro anteriores tambien pasarian si alguien
-- directamente BORRARA el indice, que seria "arreglar" el 409 abriendo el duplicado.
--
-- Fixture propio, 4 prospectos frescos de ase1 y una fecha distinta por probe: cada caso tiene que
-- poder fallar sin arrastrar a los otros. Todo muere con el ROLLBACK.
SELECT set_config('role','none', true);
DO $$
DECLARE v_gt uuid := NULLIF(current_setting('probe.co_gt',true),'')::uuid;
        v_ase1 uuid := NULLIF(current_setting('probe.co_ase1',true),'')::uuid;
        v_adm uuid := NULLIF(current_setting('probe.co_admgt',true),'')::uuid;
        r record; v_id uuid;
BEGIN
  IF coalesce(current_setting('probe.co_ready',true),'')<>'1' OR to_regclass('public.visitas_comerciales') IS NULL THEN
    PERFORM set_config('probe.un_ready','0',false);
    PERFORM set_config('probe.un_fx','ROJO — TABLAS AUSENTES (esto NO es un rechazo)',false); RETURN; END IF;
  IF to_regprocedure('public.cancelar_visita_comercial(uuid,text)') IS NULL THEN
    PERFORM set_config('probe.un_ready','0',false);
    PERFORM set_config('probe.un_fx','ROJO — MIG 280 AUSENTE (sin cancelar_visita_comercial no hay caso que probar)',false); RETURN; END IF;

  FOR r IN SELECT * FROM (VALUES
      ('un_p_recicla','QA UN recicla dia'), ('un_p_viva','QA UN visita viva'),
      ('un_p_real','QA UN realizada'),      ('un_p_doscancel','QA UN dos canceladas'),
      ('un_p_reprog','QA UN reprogramar a dia con cancelada')
    ) AS t(clave, nombre) LOOP
    INSERT INTO public.prospectos (nombre, tipo, pais_id, asesor_id, creado_por, estado_pipeline)
      VALUES (r.nombre, 'farmacia', v_gt, v_ase1, v_adm, 'nuevo') RETURNING id INTO v_id;
    PERFORM set_config('probe.'||r.clave, v_id::text, false);
  END LOOP;

  -- La 'realizada' de P604 se siembra como OWNER y no por checkin+checkout: la via canonica exige
  -- config geo del pais (que en GT esta AUSENTE a proposito, fail-closed) y jornada abierta. Lo que
  -- P604 mide es el PREDICADO DEL INDICE, no el camino del check-in — ese ya lo cubre el bloque 273.
  -- checkin_at va poblado porque visitas_com_checkout_exige_checkin lo obliga: la fila representa
  -- una visita realmente ocurrida, con entrada y salida.
  INSERT INTO public.visitas_comerciales
    (prospecto_id, asesor_id, pais_id, fecha_planificada, estado, planificada_por,
     checkin_at, checkin_origen, checkout_at)
  VALUES (NULLIF(current_setting('probe.un_p_real',true),'')::uuid, v_ase1, v_gt,
          CURRENT_DATE + 7, 'realizada', v_adm, now() - interval '3 hours', 'en_linea', now());

  PERFORM set_config('probe.un_ready','1', false);
  PERFORM set_config('probe.un_fx','OK (fixture unique: 5 prospectos frescos de ase1 + 1 visita realizada con checkin y checkout)', false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('probe.un_ready','0',false);
  PERFORM set_config('probe.un_fx','ROJO ('||SQLSTATE||' '||SQLERRM||')',false);
END $$;

-- ============================================================================================
-- Como ASESOR1
-- ============================================================================================
SELECT set_config('request.jwt.claims', json_build_object('sub', current_setting('probe.co_ase1',true), 'role','authenticated')::text, true);
SELECT set_config('role','authenticated', true);

-- P602 — EL CASO DE OSCAR: planificar -> cancelar -> planificar la MISMA fecha y prospecto.
-- Hoy 23505 (el dia quedo quemado). Con la 282, permitido.
DO $$ DECLARE v_pros uuid; v_v1 uuid; v_v2 uuid; BEGIN
  IF coalesce(current_setting('probe.un_ready',true),'')<>'1' THEN PERFORM set_config('probe.p602','N/A',false); RETURN; END IF;
  v_pros := NULLIF(current_setting('probe.un_p_recicla',true),'')::uuid;
  BEGIN
    SELECT public.planificar_visita(v_pros, CURRENT_DATE + 5, '09:00'::time) INTO v_v1;
    PERFORM public.cancelar_visita_comercial(v_v1, 'El cliente pidio moverla');
  EXCEPTION WHEN others THEN
    PERFORM set_config('probe.p602','FALLO (no se pudo armar el caso: '||SQLSTATE||' '||SQLERRM||')',false); RETURN; END;
  BEGIN
    SELECT public.planificar_visita(v_pros, CURRENT_DATE + 5, '14:00'::time) INTO v_v2;
    PERFORM set_config('probe.un_v2', v_v2::text, false);
    PERFORM set_config('probe.p602','PENDIENTE', false);   -- las FILAS se leen como owner mas abajo
  EXCEPTION WHEN unique_violation THEN
    PERFORM set_config('probe.p602','ROJO — DIA QUEMADO (23505: el UNIQUE cuenta la cancelada, re-agendar es imposible)',false);
  WHEN others THEN
    PERFORM set_config('probe.p602','FALLO (esperaba PERMITIDO, vino '||SQLSTATE||': '||SQLERRM||')',false);
  END;
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p602','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;

-- P603 — NEGATIVA QUE SE CONSERVA: con una visita PLANIFICADA viva, la misma fecha sigue dando 23505
DO $$ DECLARE v_pros uuid; BEGIN
  IF coalesce(current_setting('probe.un_ready',true),'')<>'1' THEN PERFORM set_config('probe.p603','N/A',false); RETURN; END IF;
  v_pros := NULLIF(current_setting('probe.un_p_viva',true),'')::uuid;
  BEGIN PERFORM public.planificar_visita(v_pros, CURRENT_DATE + 6, NULL);
  EXCEPTION WHEN others THEN
    PERFORM set_config('probe.p603','FALLO (la PRIMERA no paso: '||SQLSTATE||' '||SQLERRM||')',false); RETURN; END;
  BEGIN
    PERFORM public.planificar_visita(v_pros, CURRENT_DATE + 6, '16:00'::time);
    PERFORM set_config('probe.p603','ROJO (PERMITIO DOS visitas vivas al mismo prospecto el mismo dia: la 282 aflojo de mas)',false);
  EXCEPTION WHEN unique_violation THEN
    PERFORM set_config('probe.p603','OK (23505: una visita viva por prospecto y dia, sin cambios)',false);
  WHEN others THEN
    PERFORM set_config('probe.p603','FALLO (esperaba 23505, vino '||SQLSTATE||': '||SQLERRM||')',false);
  END;
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p603','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;

-- P604 — NEGATIVA: una visita REALIZADA (con check-in y checkout) sigue bloqueando el dia. El
-- predicado del indice es `<> 'cancelada'`, NO "estados vivos": un hecho ocurrido no se recicla.
DO $$ DECLARE v_pros uuid; BEGIN
  IF coalesce(current_setting('probe.un_ready',true),'')<>'1' THEN PERFORM set_config('probe.p604','N/A',false); RETURN; END IF;
  v_pros := NULLIF(current_setting('probe.un_p_real',true),'')::uuid;
  -- control del control: la fila sembrada TIENE que estar realizada y con checkout, si no P604 no
  -- estaria midiendo lo que dice medir.
  IF NOT EXISTS (SELECT 1 FROM public.visitas_comerciales v
                  WHERE v.prospecto_id=v_pros AND v.fecha_planificada=CURRENT_DATE + 7
                    AND v.estado='realizada' AND v.checkin_at IS NOT NULL AND v.checkout_at IS NOT NULL) THEN
    PERFORM set_config('probe.p604','FALLO (el fixture no quedo realizada+checkout: no mide nada)',false); RETURN; END IF;
  BEGIN
    PERFORM public.planificar_visita(v_pros, CURRENT_DATE + 7, NULL);
    PERFORM set_config('probe.p604','ROJO (PERMITIO re-agendar sobre una visita YA REALIZADA: el predicado excluye de mas)',false);
  EXCEPTION WHEN unique_violation THEN
    PERFORM set_config('probe.p604','OK (23505: las terminales NO canceladas siguen bloqueando el dia)',false);
  WHEN others THEN
    PERFORM set_config('probe.p604','FALLO (esperaba 23505, vino '||SQLSTATE||': '||SQLERRM||')',false);
  END;
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p604','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;

-- P605 — CONTROL POSITIVO: DOS canceladas de la misma terna pueden coexistir (cancelar, re-agendar,
-- cancelar otra vez). Hoy es imposible: la segunda planificacion muere antes de poder cancelarse.
DO $$ DECLARE v_pros uuid; v_v1 uuid; v_v2 uuid; BEGIN
  IF coalesce(current_setting('probe.un_ready',true),'')<>'1' THEN PERFORM set_config('probe.p605','N/A',false); RETURN; END IF;
  v_pros := NULLIF(current_setting('probe.un_p_doscancel',true),'')::uuid;
  BEGIN
    SELECT public.planificar_visita(v_pros, CURRENT_DATE + 8, NULL) INTO v_v1;
    PERFORM public.cancelar_visita_comercial(v_v1, 'Primera cancelacion');
  EXCEPTION WHEN others THEN
    PERFORM set_config('probe.p605','FALLO (no se pudo armar el caso: '||SQLSTATE||' '||SQLERRM||')',false); RETURN; END;
  BEGIN
    SELECT public.planificar_visita(v_pros, CURRENT_DATE + 8, NULL) INTO v_v2;
    PERFORM public.cancelar_visita_comercial(v_v2, 'Segunda cancelacion');
    PERFORM set_config('probe.p605','PENDIENTE', false);   -- las FILAS se cuentan como owner mas abajo
  EXCEPTION WHEN unique_violation THEN
    PERFORM set_config('probe.p605','ROJO — DIA QUEMADO (23505: no se puede cancelar dos veces el mismo dia)',false);
  WHEN others THEN
    PERFORM set_config('probe.p605','FALLO (esperaba PERMITIDO, vino '||SQLSTATE||': '||SQLERRM||')',false);
  END;
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p605','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;

-- P607 — EL MISMO BUG POR EL CAMINO DEL UPDATE, que es el que P602 no toca. reprogramar_visita_comercial
-- mueve fecha_planificada, asi que mover una visita HACIA un dia que tiene una cancelada del mismo
-- prospecto choca contra el mismo UNIQUE total. Un indice que ignora canceladas lo arregla en los dos
-- caminos a la vez; una solucion que solo arreglara el INSERT dejaria este 409 vivo.
-- Veredicto COMPUESTO a proposito: el caso y su negativa viajan juntos y ninguno puede perderse.
--   (a) reprogramar HACIA un dia con una CANCELADA  -> hoy 23505, con la 282 permitido
--   (b) reprogramar HACIA un dia con una visita VIVA -> 23505 en los dos mundos, sin cambios
DO $$ DECLARE v_pros uuid; v_vb uuid; v_va uuid; v_vc uuid;
        v_a date; v_b date; v_c date; v_mueve text; v_bloquea text; v_fecha date; v_estado text;
BEGIN
  IF coalesce(current_setting('probe.un_ready',true),'')<>'1' THEN PERFORM set_config('probe.p607','N/A',false); RETURN; END IF;
  IF to_regprocedure('public.reprogramar_visita_comercial(uuid,date,time without time zone)') IS NULL THEN
    PERFORM set_config('probe.p607','ROJO — RPC AUSENTE',false); RETURN; END IF;
  v_pros := NULLIF(current_setting('probe.un_p_reprog',true),'')::uuid;
  v_a := CURRENT_DATE + 9; v_b := CURRENT_DATE + 10; v_c := CURRENT_DATE + 11;

  -- Siembra: B queda con una CANCELADA, A con la visita viva a mover, C con una visita VIVA.
  BEGIN
    SELECT public.planificar_visita(v_pros, v_b, NULL) INTO v_vb;
    PERFORM public.cancelar_visita_comercial(v_vb, 'Libero el dia B');
    SELECT public.planificar_visita(v_pros, v_a, '08:00'::time) INTO v_va;
    SELECT public.planificar_visita(v_pros, v_c, NULL) INTO v_vc;
  EXCEPTION WHEN others THEN
    PERFORM set_config('probe.p607','FALLO (no se pudo armar el caso: '||SQLSTATE||' '||SQLERRM||')',false); RETURN; END;

  -- control del control: si B no quedo con exactamente una cancelada, (a) no mide lo que dice.
  IF (SELECT count(*) FROM public.visitas_comerciales
       WHERE prospecto_id=v_pros AND fecha_planificada=v_b AND estado='cancelada') <> 1 THEN
    PERFORM set_config('probe.p607','FALLO (el dia B no quedo con una cancelada: no mide nada)',false); RETURN; END IF;

  -- (a) mover A -> B, el dia que solo tiene una cancelada
  BEGIN
    PERFORM public.reprogramar_visita_comercial(v_va, v_b, NULL);
    SELECT v.fecha_planificada, v.estado INTO v_fecha, v_estado
      FROM public.visitas_comerciales v WHERE v.id = v_va;   -- se lee LA FILA, no el retorno
    v_mueve := CASE WHEN v_fecha = v_b AND v_estado = 'planificada'
                    THEN 'OK' ELSE 'FALLO (la RPC paso pero la fila quedo en '||v_fecha||'/'||v_estado||')' END;
  EXCEPTION WHEN unique_violation THEN v_mueve := 'ROJO (23505: no se puede mover a un dia que solo tiene una CANCELADA)';
            WHEN others THEN v_mueve := 'FALLO ('||SQLSTATE||' '||SQLERRM||')';
  END;

  -- (b) NEGATIVA: mover hacia C, que tiene una visita VIVA -> tiene que seguir rebotando
  BEGIN
    PERFORM public.reprogramar_visita_comercial(v_va, v_c, NULL);
    v_bloquea := 'ROJO (PERMITIO mover sobre una visita VIVA: la 282 aflojo de mas)';
  EXCEPTION WHEN unique_violation THEN v_bloquea := 'OK';
            WHEN others THEN v_bloquea := 'FALLO (esperaba 23505, vino '||SQLSTATE||': '||SQLERRM||')';
  END;

  PERFORM set_config('probe.p607', CASE WHEN v_mueve='OK' AND v_bloquea='OK'
    THEN 'OK (reprograma sobre dia con cancelada; sigue rebotando contra visita viva)'
    ELSE 'a_dia_cancelado='||v_mueve||' | b_dia_con_visita_viva='||v_bloquea END, false);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p607','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;

SELECT set_config('role','none', true);

-- Lectura de las FILAS de P602 y P605 como owner: el veredicto no puede depender de que la RPC no
-- haya tirado, tiene que mirar lo que quedo en la tabla.
DO $$ DECLARE v_tot int; v_can int; v_plan int; BEGIN
  IF coalesce(current_setting('probe.p602',true),'')<>'PENDIENTE' THEN RETURN; END IF;
  SELECT count(*), count(*) FILTER (WHERE estado='cancelada'), count(*) FILTER (WHERE estado='planificada')
    INTO v_tot, v_can, v_plan
    FROM public.visitas_comerciales
   WHERE prospecto_id = NULLIF(current_setting('probe.un_p_recicla',true),'')::uuid
     AND fecha_planificada = CURRENT_DATE + 5;
  PERFORM set_config('probe.p602', CASE
    WHEN v_tot=2 AND v_can=1 AND v_plan=1 THEN 'OK (el dia se reciclo: 1 cancelada + 1 planificada nueva conviven)'
    ELSE 'FALLO (esperaba 1 cancelada + 1 planificada, hay total='||v_tot||' cancel='||v_can||' plan='||v_plan||')' END, false);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p602','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;

DO $$ DECLARE v_tot int; v_can int; BEGIN
  IF coalesce(current_setting('probe.p605',true),'')<>'PENDIENTE' THEN RETURN; END IF;
  SELECT count(*), count(*) FILTER (WHERE estado='cancelada') INTO v_tot, v_can
    FROM public.visitas_comerciales
   WHERE prospecto_id = NULLIF(current_setting('probe.un_p_doscancel',true),'')::uuid
     AND fecha_planificada = CURRENT_DATE + 8;
  PERFORM set_config('probe.p605', CASE
    WHEN v_tot=2 AND v_can=2 THEN 'OK (dos canceladas de la misma terna coexisten)'
    ELSE 'FALLO (esperaba 2 canceladas, hay total='||v_tot||' cancel='||v_can||')' END, false);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p605','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;

-- P606 — ESTRUCTURAL: el indice existe, es UNIQUE, es PARCIAL y su predicado excluye 'cancelada'.
-- Sin esta, borrar el indice entero pondria P602 y P605 en verde y solo P603/P604 en rojo: la mitad
-- de la evidencia diria "arreglado". Ademas mira que ya NO sea una CONSTRAINT, porque una
-- constraint UNIQUE no puede ser parcial — si volvio a serlo, el dia cancelado sigue quemado.
DO $$ DECLARE v_def text; v_unico boolean; v_parcial boolean; v_pred text; v_con boolean; BEGIN
  IF to_regclass('public.visitas_comerciales') IS NULL THEN
    PERFORM set_config('probe.p606','ROJO — TABLA AUSENTE (esto NO es un rechazo)',false); RETURN; END IF;
  IF to_regclass('public.visitas_com_una_por_dia') IS NULL THEN
    PERFORM set_config('probe.p606','ROJO — EL INDICE NO EXISTE (nada impide dos visitas al mismo prospecto el mismo dia)',false); RETURN; END IF;
  SELECT pg_get_indexdef(i.indexrelid), i.indisunique, i.indpred IS NOT NULL,
         pg_get_expr(i.indpred, i.indrelid)
    INTO v_def, v_unico, v_parcial, v_pred
    FROM pg_index i WHERE i.indexrelid='public.visitas_com_una_por_dia'::regclass;
  SELECT EXISTS (SELECT 1 FROM pg_constraint
                  WHERE conrelid='public.visitas_comerciales'::regclass
                    AND conname='visitas_com_una_por_dia') INTO v_con;
  PERFORM set_config('probe.p606', CASE
    WHEN NOT v_unico       THEN 'ROJO (el indice NO es UNIQUE: '||v_def||')'
    WHEN v_con             THEN 'ROJO (sigue siendo CONSTRAINT: una constraint UNIQUE no puede ser parcial, el dia cancelado sigue quemado)'
    WHEN NOT v_parcial     THEN 'ROJO — INDICE TOTAL (sin WHERE: cuenta las canceladas y quema el dia)'
    WHEN v_pred NOT ILIKE '%cancelada%' THEN 'ROJO (parcial pero con OTRO predicado: '||v_pred||')'
    ELSE 'OK (UNIQUE parcial, no constraint, predicado: '||v_pred||')' END, false);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p606','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;

-- ############################################################################################
-- P608-P614 — comercial_asesores_visibles() (mig 283)
-- ############################################################################################
-- La RPC lee perfiles SIN RLS (SECURITY DEFINER, owner postgres con bypassrls, tablas sin FORCE),
-- asi que su WHERE es la unica barrera. Estas probes miden esa barrera desde los cuatro roles y
-- desde el catalogo, y la ultima —P614— mide lo que NO cambio: que perfiles siga cerrada.
--
-- P608 supervisor · P609 asesor · P610 admin_pais GT · P611 super_admin
-- P612 CENSO del tipo de retorno · P613 anon sin EXECUTE · P614 perfiles sigue cerrada
--
-- Fixture: se apoya en el comercial (co_*), que ya siembra un asesor de HN (QA-SUP-HN-COM) y una
-- ficha de medico en GT. Lo unico propio es el id de un super_admin.
SELECT set_config('role','none', true);
DO $$ DECLARE v_sa uuid; v_n int; BEGIN
  IF coalesce(current_setting('probe.co_ready',true),'')<>'1' THEN
    PERFORM set_config('probe.av_ready','0',false);
    PERFORM set_config('probe.av_fx','ROJO — FIXTURE COMERCIAL AUSENTE (esto NO es un rechazo)',false); RETURN; END IF;
  SELECT id INTO v_sa FROM public.perfiles WHERE rol='super_admin' ORDER BY id LIMIT 1;
  IF v_sa IS NULL THEN
    PERFORM set_config('probe.av_ready','0',false);
    PERFORM set_config('probe.av_fx','ROJO — NO HAY SUPER_ADMIN en perfiles (P611 no podria medir)',false); RETURN; END IF;
  PERFORM set_config('probe.av_sa', v_sa::text, false);
  -- control del fixture: tiene que haber fichas en LOS DOS paises, si no P610 y P611 pasan vacias
  SELECT count(DISTINCT pais_id) INTO v_n FROM public.asesores_perfil;
  IF v_n < 2 THEN
    PERFORM set_config('probe.av_ready','0',false);
    PERFORM set_config('probe.av_fx','ROJO — asesores_perfil tiene fichas de UN solo pais ('||v_n||'): el aislamiento no se puede medir',false); RETURN; END IF;
  PERFORM set_config('probe.av_ready','1', false);
  PERFORM set_config('probe.av_fx','OK (fixture asesores visibles: super_admin identificado, fichas en '||v_n||' paises)', false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('probe.av_ready','0',false);
  PERFORM set_config('probe.av_fx','ROJO ('||SQLSTATE||' '||SQLERRM||')',false);
END $$;

-- P608 — SUPERVISOR: ve a su asesor a cargo CON nombre_completo, y a si mismo.
SELECT set_config('request.jwt.claims', json_build_object('sub', current_setting('probe.co_sup',true), 'role','authenticated')::text, true);
SELECT set_config('role','authenticated', true);
DO $$ DECLARE v_ase1 uuid; v_sup uuid; v_n int; v_nom text; v_yo int; v_sinnom int; BEGIN
  IF coalesce(current_setting('probe.av_ready',true),'')<>'1' THEN PERFORM set_config('probe.p608','N/A',false); RETURN; END IF;
  IF to_regprocedure('public.comercial_asesores_visibles()') IS NULL THEN
    PERFORM set_config('probe.p608','ROJO — RPC AUSENTE',false); RETURN; END IF;
  v_ase1 := NULLIF(current_setting('probe.co_ase1',true),'')::uuid;
  v_sup  := NULLIF(current_setting('probe.co_sup',true),'')::uuid;
  SELECT count(*), count(*) FILTER (WHERE r.id = v_sup),
         count(*) FILTER (WHERE r.nombre_completo IS NULL),
         max(r.nombre_completo) FILTER (WHERE r.id = v_ase1)
    INTO v_n, v_yo, v_sinnom, v_nom
    FROM public.comercial_asesores_visibles() r;
  PERFORM set_config('probe.p608', CASE
    WHEN v_nom IS NULL AND v_n = 0 THEN 'ROJO (la RPC no devolvio NADA: el supervisor no ve ni a su asesor ni a si mismo)'
    WHEN v_nom IS NULL THEN 'ROJO (ve '||v_n||' filas pero el nombre de su asesor sigue sin llegar)'
    WHEN v_yo = 0 THEN 'FALLO (ve el nombre del asesor pero NO se ve a si mismo: '||v_n||' filas)'
    WHEN v_sinnom > 0 THEN 'FALLO ('||v_sinnom||' filas con nombre_completo NULL)'
    ELSE 'OK (ve '||v_n||' fichas, incluida la propia; su asesor llega con nombre: '||v_nom||')' END, false);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p608','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;

-- P609 — ASESOR: se ve a si mismo y NO ve a otros asesores del MISMO pais.
-- El control positivo esta adentro: si no se viera ni a si mismo, "no ve a ase2" seria trivial.
SELECT set_config('request.jwt.claims', json_build_object('sub', current_setting('probe.co_ase1',true), 'role','authenticated')::text, true);
SELECT set_config('role','authenticated', true);
DO $$ DECLARE v_ase1 uuid; v_ase2 uuid; v_n int; v_yo int; v_otro int; BEGIN
  IF coalesce(current_setting('probe.av_ready',true),'')<>'1' THEN PERFORM set_config('probe.p609','N/A',false); RETURN; END IF;
  IF to_regprocedure('public.comercial_asesores_visibles()') IS NULL THEN
    PERFORM set_config('probe.p609','ROJO — RPC AUSENTE',false); RETURN; END IF;
  v_ase1 := NULLIF(current_setting('probe.co_ase1',true),'')::uuid;
  v_ase2 := NULLIF(current_setting('probe.co_ase2',true),'')::uuid;
  SELECT count(*), count(*) FILTER (WHERE r.id=v_ase1), count(*) FILTER (WHERE r.id=v_ase2)
    INTO v_n, v_yo, v_otro FROM public.comercial_asesores_visibles() r;
  PERFORM set_config('probe.p609', CASE
    WHEN v_otro > 0 THEN 'ROJO (el asesor ve la ficha de OTRO asesor del pais: '||v_n||' filas)'
    WHEN v_yo = 0   THEN 'ROJO — CONTROL POSITIVO CAIDO (no se ve ni a si mismo: la negativa no mide nada)'
    ELSE 'OK (se ve a si mismo y a nadie mas: '||v_n||' fila(s), ase2 ausente)' END, false);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p609','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;

-- P610 — ADMIN_PAIS de GT: ve los de GT, NO los de HN.
-- CONTROL POSITIVO explicito: la lista de GT no puede venir vacia (leccion P553). Un admin_pais que
-- no viera NADA pasaria la negativa "no ve HN" sin medir absolutamente nada.
SELECT set_config('request.jwt.claims', json_build_object('sub', current_setting('probe.co_admgt',true), 'role','authenticated')::text, true);
SELECT set_config('role','authenticated', true);
DO $$ DECLARE v_hn uuid; v_gt int; v_hn_n int; BEGIN
  IF coalesce(current_setting('probe.av_ready',true),'')<>'1' THEN PERFORM set_config('probe.p610','N/A',false); RETURN; END IF;
  IF to_regprocedure('public.comercial_asesores_visibles()') IS NULL THEN
    PERFORM set_config('probe.p610','ROJO — RPC AUSENTE',false); RETURN; END IF;
  v_hn := NULLIF(current_setting('probe.co_hn',true),'')::uuid;
  SELECT count(*) FILTER (WHERE ap.pais_id <> v_hn), count(*) FILTER (WHERE ap.pais_id = v_hn)
    INTO v_gt, v_hn_n
    FROM public.comercial_asesores_visibles() r
    JOIN public.asesores_perfil ap ON ap.id = r.id;
  PERFORM set_config('probe.p610', CASE
    WHEN v_hn_n > 0 THEN 'ROJO (el admin de GT ve '||v_hn_n||' ficha(s) de HN)'
    -- OJO: el admin_pais NO es supervisor de nadie, asi que asesores_a_cargo() le da vacio y la
    -- rama de pais no lo alcanza. Cero filas aca NO es un aislamiento correcto: es una RPC que no
    -- le sirve al rol. Se reporta distinto de un verde para que no se lea como exito.
    WHEN v_gt = 0 THEN 'ROJO — CONTROL POSITIVO CAIDO (admin de GT ve CERO fichas de GT: la negativa no mide nada)'
    ELSE 'OK (ve '||v_gt||' de GT y 0 de HN)' END, false);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p610','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;

-- P611 — SUPER_ADMIN: ve fichas de LOS DOS paises (la rama sin restriccion de pais).
SELECT set_config('role','none', true);
DO $$ DECLARE v_sa text; BEGIN
  v_sa := coalesce(current_setting('probe.av_sa',true),'');
  IF v_sa <> '' THEN
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_sa, 'role','authenticated')::text, true);
  END IF;
EXCEPTION WHEN OTHERS THEN NULL; END $$;
SELECT set_config('role','authenticated', true);
DO $$ DECLARE v_n int; v_paises int; BEGIN
  IF coalesce(current_setting('probe.av_ready',true),'')<>'1' THEN PERFORM set_config('probe.p611','N/A',false); RETURN; END IF;
  IF to_regprocedure('public.comercial_asesores_visibles()') IS NULL THEN
    PERFORM set_config('probe.p611','ROJO — RPC AUSENTE',false); RETURN; END IF;
  SELECT count(*), count(DISTINCT ap.pais_id) INTO v_n, v_paises
    FROM public.comercial_asesores_visibles() r
    JOIN public.asesores_perfil ap ON ap.id = r.id;
  PERFORM set_config('probe.p611', CASE
    WHEN v_n = 0      THEN 'ROJO (el super_admin no ve NADA: la rama super_admin del gate no funciona)'
    WHEN v_paises < 2 THEN 'ROJO (el super_admin ve '||v_n||' fichas de UN solo pais: no cruza paises)'
    ELSE 'OK (ve '||v_n||' fichas de '||v_paises||' paises)' END, false);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p611','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;
SELECT set_config('role','none', true);

-- P612 — CENSO del tipo de retorno, por CATALOGO y no por una llamada: manana alguien agrega una
-- columna al RETURNS TABLE y ninguna de las probes de arriba se entera, porque todas cuentan filas.
DO $$ DECLARE v_oid oid; v_cols text[]; v_malas text; BEGIN
  v_oid := to_regprocedure('public.comercial_asesores_visibles()');
  IF v_oid IS NULL THEN PERFORM set_config('probe.p612','ROJO — RPC AUSENTE',false); RETURN; END IF;
  SELECT array_agg(a.name ORDER BY a.ord) INTO v_cols
    FROM unnest((SELECT proargnames FROM pg_proc WHERE oid=v_oid),
                (SELECT proargmodes FROM pg_proc WHERE oid=v_oid)) WITH ORDINALITY AS a(name, mode, ord)
   WHERE a.mode IN ('t','o');
  SELECT string_agg(c, ', ') INTO v_malas FROM unnest(coalesce(v_cols,'{}')) c
   WHERE c IN ('email','telefono','celular','avatar_url','lat','lng','bio')
      OR c LIKE 'direccion%' OR c LIKE 'foto%';
  PERFORM set_config('probe.p612', CASE
    WHEN v_malas IS NOT NULL THEN 'ROJO — COLUMNAS SENSIBLES en el retorno: '||v_malas
    WHEN v_cols IS DISTINCT FROM ARRAY['id','codigo_asesor','nombre_completo','activo','supervisor_id']
      THEN 'ROJO (el retorno no es el contratado: '||coalesce(array_to_string(v_cols,', '),'(vacio)')||')'
    ELSE 'OK (exactamente 5 columnas: id, codigo_asesor, nombre_completo, activo, supervisor_id)' END, false);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p612','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;

-- P613 — anon SIN EXECUTE (y authenticated CON), que es el par que hace util al primero.
DO $$ DECLARE v_oid oid; v_anon boolean; v_auth boolean; BEGIN
  v_oid := to_regprocedure('public.comercial_asesores_visibles()');
  IF v_oid IS NULL THEN PERFORM set_config('probe.p613','ROJO — RPC AUSENTE',false); RETURN; END IF;
  v_anon := has_function_privilege('anon', v_oid, 'EXECUTE');
  v_auth := has_function_privilege('authenticated', v_oid, 'EXECUTE');
  PERFORM set_config('probe.p613', CASE
    WHEN v_anon      THEN 'ROJO (anon puede ejecutar la RPC)'
    WHEN NOT v_auth  THEN 'ROJO (authenticated NO puede ejecutarla: la RPC no le sirve a nadie)'
    ELSE 'OK (anon=false, authenticated=true)' END, false);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p613','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;

-- P614 — LA NEGATIVA QUE NO DEBE CAMBIAR: perfiles sigue cerrada. Esta es la que prueba que la 283
-- no abrio la tabla. Dos mitades: por CATALOGO (siguen siendo las 5 policies de siempre, ninguna
-- nueva de SELECT) y por CAMINO REAL (el supervisor lee perfiles como lo haria PostgREST y NO
-- encuentra la fila de su asesor). El catalogo solo no alcanza: una policy podria cambiar de
-- contenido sin cambiar de nombre ni de cuenta.
SELECT set_config('request.jwt.claims', json_build_object('sub', current_setting('probe.co_sup',true), 'role','authenticated')::text, true);
SELECT set_config('role','authenticated', true);
DO $$ DECLARE v_ve int; v_yo int; BEGIN
  IF coalesce(current_setting('probe.av_ready',true),'')<>'1' THEN PERFORM set_config('probe.p614','N/A',false); RETURN; END IF;
  SELECT count(*) FILTER (WHERE p.id = NULLIF(current_setting('probe.co_ase1',true),'')::uuid),
         count(*) FILTER (WHERE p.id = NULLIF(current_setting('probe.co_sup',true),'')::uuid)
    INTO v_ve, v_yo FROM public.perfiles p;
  PERFORM set_config('probe.p614_directo', CASE
    WHEN v_ve > 0 THEN 'ABIERTA'
    WHEN v_yo = 0 THEN 'CIEGA'
    ELSE 'CERRADA' END, false);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p614_directo','FALLO('||SQLSTATE||')',false); END $$;
SELECT set_config('role','none', true);
-- Mitad CATALOGO: el (policyname,cmd) de perfiles debe ser EXACTAMENTE el set de 6, + 0 ALL + 1 INSERT.
-- Set actualizado por migs 318 (DROP Insertar propio perfil) y 319 (split ALL->S/U/D). El conteo
-- hardcodeado viejo (5 policies) quedo desactualizado; ahora se compara el conjunto y se listan
-- sobrantes/faltantes.
DO $$ DECLARE v_dir text; v_sobra text; v_falta text; v_all int; v_ins int; BEGIN
  IF coalesce(current_setting('probe.av_ready',true),'')<>'1' THEN PERFORM set_config('probe.p614','N/A',false); RETURN; END IF;
  v_dir := coalesce(current_setting('probe.p614_directo',true),'');
  SELECT string_agg(nm||':'||cm, ', ' ORDER BY nm) INTO v_sobra FROM (
    SELECT policyname::text nm, cmd::text cm FROM pg_policies WHERE schemaname='public' AND tablename='perfiles'
    EXCEPT
    SELECT * FROM (VALUES
      ('Admin borra perfiles de su pais','DELETE'),('Admins pueden insertar perfiles','INSERT'),
      ('Admin lee perfiles de su pais','SELECT'),('Ver propio perfil','SELECT'),
      ('Actualizar propio perfil','UPDATE'),('Admin actualiza perfiles de su pais','UPDATE')) AS x(nm,cm)
  ) s;
  SELECT string_agg(nm||':'||cm, ', ' ORDER BY nm) INTO v_falta FROM (
    SELECT * FROM (VALUES
      ('Admin borra perfiles de su pais','DELETE'),('Admins pueden insertar perfiles','INSERT'),
      ('Admin lee perfiles de su pais','SELECT'),('Ver propio perfil','SELECT'),
      ('Actualizar propio perfil','UPDATE'),('Admin actualiza perfiles de su pais','UPDATE')) AS x(nm,cm)
    EXCEPT
    SELECT policyname::text, cmd::text FROM pg_policies WHERE schemaname='public' AND tablename='perfiles'
  ) s;
  SELECT count(*) FILTER (WHERE cmd='ALL'), count(*) FILTER (WHERE cmd='INSERT') INTO v_all, v_ins
    FROM pg_policies WHERE schemaname='public' AND tablename='perfiles';
  PERFORM set_config('probe.p614', CASE
    WHEN v_dir = 'ABIERTA' THEN 'ROJO — SE ABRIO perfiles (el supervisor ahora LEE la fila de su asesor por camino directo)'
    WHEN v_dir = 'CIEGA'   THEN 'FALLO (el supervisor no ve ni su propio perfil: la mitad directa no mide nada)'
    WHEN v_dir <> 'CERRADA' THEN 'FALLO (mitad directa: '||v_dir||')'
    WHEN v_sobra IS NOT NULL OR v_falta IS NOT NULL OR v_all <> 0 OR v_ins <> 1
      THEN 'ROJO (perfiles cambio — sobrantes: ['||coalesce(v_sobra,'-')||'] faltantes: ['||coalesce(v_falta,'-')||'] cmd_ALL='||v_all||' cmd_INSERT='||v_ins||')'
    ELSE 'OK (perfiles intacta: set exacto de 6 policies [318/319], 0 ALL, 1 INSERT, y el supervisor sigue sin leer la fila de su asesor)' END, false);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p614','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;

-- ############################################################################################
-- P639-P643 — comercial_perfiles_sin_ficha(uuid) (mig 286)
-- ############################################################################################
-- La funcion contesta "a quien le falta la ficha de asesor en este pais". Es LECTURA: un llamante
-- sin autoridad recibe CERO FILAS, no 42501 — por eso todas las negativas de abajo miden conjunto
-- vacio y no un errcode.
--
-- Las cinco comparan el CONJUNTO EXACTO por id, no `count > 0`. La diferencia importa: una funcion
-- que devolviera de mas pasaria todos los "count>0" del mundo. Se mide "esta el que tiene que
-- estar" Y "no esta el que no tiene que estar", en la misma probe.
--
-- Fixture: TRES perfiles frescos, creados como owner con INSERT directo en auth.users + perfiles
-- (mismo patron que P446/P449/P450). Ninguno recibe fila en asesores_perfil — ese es justamente el
-- estado que la funcion busca.
SELECT set_config('role','none', true);
DO $$
DECLARE v_gt uuid := NULLIF(current_setting('probe.co_gt',true),'')::uuid;
        v_hn uuid := NULLIF(current_setting('probe.co_hn',true),'')::uuid;
        v_ase uuid; v_sup uuid; v_med uuid; v_sa uuid;
BEGIN
  IF coalesce(current_setting('probe.co_ready',true),'')<>'1' THEN
    PERFORM set_config('probe.sf_ready','0',false);
    PERFORM set_config('probe.sf_fx','ROJO — FIXTURE COMERCIAL AUSENTE (esto NO es un rechazo)',false); RETURN; END IF;
  IF v_gt IS NULL OR v_hn IS NULL THEN
    PERFORM set_config('probe.sf_ready','0',false);
    PERFORM set_config('probe.sf_fx','ROJO — faltan los ids de pais (GT/HN)',false); RETURN; END IF;

  v_ase := gen_random_uuid(); v_sup := gen_random_uuid(); v_med := gen_random_uuid();

  -- (1) asesor_comercial de GT SIN ficha -> tiene que APARECER
  INSERT INTO auth.users (id) VALUES (v_ase);
  INSERT INTO public.perfiles (id, email, nombre_completo, rol, pais_id, activo)
    VALUES (v_ase, 'p639.ase@example.invalid', 'QA SF asesor sin ficha', 'asesor_comercial', v_gt, true);

  -- (2) supervisor_comercial de GT SIN ficha -> tambien aparece: la funcion cubre los DOS roles,
  --     y con uno solo no se distingue "filtra por rol" de "filtra por un rol".
  INSERT INTO auth.users (id) VALUES (v_sup);
  INSERT INTO public.perfiles (id, email, nombre_completo, rol, pais_id, activo)
    VALUES (v_sup, 'p639.sup@example.invalid', 'QA SF supervisor sin ficha', 'supervisor_comercial', v_gt, true);

  -- (3) MEDICO de GT sin ficha -> NO debe aparecer (censo de rol, P641)
  INSERT INTO auth.users (id) VALUES (v_med);
  INSERT INTO public.perfiles (id, email, nombre_completo, rol, pais_id, activo)
    VALUES (v_med, 'p639.med@example.invalid', 'QA SF medico sin ficha', 'medico', v_gt, true);

  SELECT id INTO v_sa FROM public.perfiles WHERE rol='super_admin' ORDER BY id LIMIT 1;

  PERFORM set_config('probe.sf_ase', v_ase::text, false);
  PERFORM set_config('probe.sf_sup', v_sup::text, false);
  PERFORM set_config('probe.sf_med', v_med::text, false);
  PERFORM set_config('probe.sf_sa',  coalesce(v_sa::text,''), false);
  PERFORM set_config('probe.sf_ready','1', false);
  PERFORM set_config('probe.sf_fx','OK (fixture sin-ficha: asesor + supervisor + medico de GT, ninguno con ficha)', false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('probe.sf_ready','0',false);
  PERFORM set_config('probe.sf_fx','ROJO ('||SQLSTATE||' '||SQLERRM||')',false);
END $$;

-- P639 — POSITIVO: el admin_pais de GT ve a los DOS comerciales sin ficha de su pais.
-- Se compara el conjunto EXACTO de ids, no el conteo.
SELECT set_config('request.jwt.claims', json_build_object('sub', current_setting('probe.co_admgt',true), 'role','authenticated')::text, true);
SELECT set_config('role','authenticated', true);
DO $$ DECLARE v_ase uuid; v_sup uuid; v_hay_ase int; v_hay_sup int; v_n int; BEGIN
  IF coalesce(current_setting('probe.sf_ready',true),'')<>'1' THEN PERFORM set_config('probe.p639','N/A',false); RETURN; END IF;
  IF to_regprocedure('public.comercial_perfiles_sin_ficha(uuid)') IS NULL THEN
    PERFORM set_config('probe.p639','ROJO — RPC AUSENTE',false); RETURN; END IF;
  v_ase := NULLIF(current_setting('probe.sf_ase',true),'')::uuid;
  v_sup := NULLIF(current_setting('probe.sf_sup',true),'')::uuid;
  SELECT count(*), count(*) FILTER (WHERE r.id = v_ase), count(*) FILTER (WHERE r.id = v_sup)
    INTO v_n, v_hay_ase, v_hay_sup
    FROM public.comercial_perfiles_sin_ficha(NULLIF(current_setting('probe.co_gt',true),'')::uuid) r;
  PERFORM set_config('probe.p639', CASE
    WHEN v_n = 0                    THEN 'ROJO (el admin de GT no recibio NINGUNA fila)'
    WHEN v_hay_ase = 0              THEN 'ROJO (el asesor_comercial de GT sin ficha NO aparece; '||v_n||' filas)'
    WHEN v_hay_sup = 0              THEN 'ROJO (el supervisor_comercial de GT sin ficha NO aparece; '||v_n||' filas)'
    ELSE 'OK (el admin de GT ve a los dos comerciales sin ficha; '||v_n||' filas en total)' END, false);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p639','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;

-- P641 — CENSO DE ROL: ningun perfil NO comercial entra en el resultado. El medico del fixture es
-- el caso puntual; el censo mira TODO el conjunto, porque manana alguien afloja el IN y un caso
-- suelto no se entera.
DO $$ DECLARE v_med uuid; v_hay_med int; v_malos text; BEGIN
  IF coalesce(current_setting('probe.sf_ready',true),'')<>'1' THEN PERFORM set_config('probe.p641','N/A',false); RETURN; END IF;
  IF to_regprocedure('public.comercial_perfiles_sin_ficha(uuid)') IS NULL THEN
    PERFORM set_config('probe.p641','ROJO — RPC AUSENTE',false); RETURN; END IF;
  v_med := NULLIF(current_setting('probe.sf_med',true),'')::uuid;
  SELECT count(*) FILTER (WHERE r.id = v_med),
         string_agg(DISTINCT r.rol, ', ') FILTER (WHERE r.rol NOT IN ('asesor_comercial','supervisor_comercial'))
    INTO v_hay_med, v_malos
    FROM public.comercial_perfiles_sin_ficha(NULLIF(current_setting('probe.co_gt',true),'')::uuid) r;
  PERFORM set_config('probe.p641', CASE
    WHEN v_hay_med > 0   THEN 'ROJO (el MEDICO sin ficha aparece en la lista de fichas comerciales)'
    WHEN v_malos IS NOT NULL THEN 'ROJO (roles no comerciales en el resultado: '||v_malos||')'
    ELSE 'OK (ningun rol fuera de asesor_comercial/supervisor_comercial, y el medico del fixture no esta)' END, false);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p641','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;

-- P642 — CENSO DEL NOT EXISTS: quien YA tiene ficha no aparece, aunque cumpla rol y pais.
-- Se usa QA-ASE-01 (ficha real, rol asesor_comercial, pais GT) y ademas se censa el conjunto
-- entero contra asesores_perfil: si UNA sola fila del resultado ya tuviera ficha, el NOT EXISTS
-- no esta haciendo nada.
DO $$ DECLARE v_ase1 uuid; v_hay int; v_con_ficha int; BEGIN
  IF coalesce(current_setting('probe.sf_ready',true),'')<>'1' THEN PERFORM set_config('probe.p642','N/A',false); RETURN; END IF;
  IF to_regprocedure('public.comercial_perfiles_sin_ficha(uuid)') IS NULL THEN
    PERFORM set_config('probe.p642','ROJO — RPC AUSENTE',false); RETURN; END IF;
  v_ase1 := NULLIF(current_setting('probe.co_ase1',true),'')::uuid;
  SELECT count(*) FILTER (WHERE r.id = v_ase1),
         count(*) FILTER (WHERE EXISTS (SELECT 1 FROM public.asesores_perfil ap WHERE ap.id = r.id))
    INTO v_hay, v_con_ficha
    FROM public.comercial_perfiles_sin_ficha(NULLIF(current_setting('probe.co_gt',true),'')::uuid) r;
  PERFORM set_config('probe.p642', CASE
    WHEN v_hay > 0        THEN 'ROJO (QA-ASE-01 TIENE ficha y aparece igual: el NOT EXISTS no filtra)'
    WHEN v_con_ficha > 0  THEN 'ROJO ('||v_con_ficha||' fila(s) del resultado YA tienen ficha en asesores_perfil)'
    ELSE 'OK (ninguna fila del resultado tiene ficha; QA-ASE-01 excluido)' END, false);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p642','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;
SELECT set_config('role','none', true);

-- P640 — NEGATIVA DE AISLAMIENTO: el admin_pais de HN pide la lista de GT y recibe CERO FILAS.
-- Es lectura, asi que la negativa es un conjunto vacio y NO un 42501: si algun dia empieza a
-- lanzar, esta probe lo dice en vez de leerlo como exito.
SELECT set_config('request.jwt.claims', json_build_object('sub', current_setting('probe.co_admhn',true), 'role','authenticated')::text, true);
SELECT set_config('role','authenticated', true);
DO $$ DECLARE v_n int; v_ase int; BEGIN
  IF coalesce(current_setting('probe.sf_ready',true),'')<>'1' THEN PERFORM set_config('probe.p640','N/A',false); RETURN; END IF;
  IF to_regprocedure('public.comercial_perfiles_sin_ficha(uuid)') IS NULL THEN
    PERFORM set_config('probe.p640','ROJO — RPC AUSENTE',false); RETURN; END IF;
  BEGIN
    SELECT count(*), count(*) FILTER (WHERE r.id = NULLIF(current_setting('probe.sf_ase',true),'')::uuid)
      INTO v_n, v_ase
      FROM public.comercial_perfiles_sin_ficha(NULLIF(current_setting('probe.co_gt',true),'')::uuid) r;
    PERFORM set_config('probe.p640', CASE
      WHEN v_ase > 0 THEN 'ROJO (el admin de HN VE al asesor sin ficha de GT)'
      WHEN v_n > 0   THEN 'ROJO (el admin de HN recibio '||v_n||' fila(s) de la lista de GT)'
      ELSE 'OK (0 filas: pide GT y no es admin de GT)' END, false);
  EXCEPTION WHEN insufficient_privilege THEN
    PERFORM set_config('probe.p640','FALLO (lanzo 42501; esta funcion es lectura y debe devolver 0 filas)',false);
  WHEN others THEN PERFORM set_config('probe.p640','FALLO ('||SQLSTATE||' '||SQLERRM||')',false);
  END;
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p640','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;
SELECT set_config('role','none', true);

-- P643 — POSITIVO super_admin: la otra rama del gate. Sin esto, el 0 filas de P640 tambien lo
-- cumpliria una funcion que no le devuelve nada a nadie.
DO $$ DECLARE v_sa text; BEGIN
  v_sa := coalesce(current_setting('probe.sf_sa',true),'');
  IF v_sa <> '' THEN
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_sa, 'role','authenticated')::text, true);
  END IF;
EXCEPTION WHEN OTHERS THEN NULL; END $$;
SELECT set_config('role','authenticated', true);
DO $$ DECLARE v_n int; v_ase int; v_sup int; BEGIN
  IF coalesce(current_setting('probe.sf_ready',true),'')<>'1' THEN PERFORM set_config('probe.p643','N/A',false); RETURN; END IF;
  IF coalesce(current_setting('probe.sf_sa',true),'')='' THEN
    PERFORM set_config('probe.p643','ROJO — NO HAY SUPER_ADMIN (la rama no se puede medir)',false); RETURN; END IF;
  IF to_regprocedure('public.comercial_perfiles_sin_ficha(uuid)') IS NULL THEN
    PERFORM set_config('probe.p643','ROJO — RPC AUSENTE',false); RETURN; END IF;
  SELECT count(*), count(*) FILTER (WHERE r.id = NULLIF(current_setting('probe.sf_ase',true),'')::uuid),
         count(*) FILTER (WHERE r.id = NULLIF(current_setting('probe.sf_sup',true),'')::uuid)
    INTO v_n, v_ase, v_sup
    FROM public.comercial_perfiles_sin_ficha(NULLIF(current_setting('probe.co_gt',true),'')::uuid) r;
  PERFORM set_config('probe.p643', CASE
    WHEN v_ase = 0 OR v_sup = 0 THEN 'ROJO (el super_admin NO ve los comerciales sin ficha de GT: '||v_n||' filas)'
    ELSE 'OK (super_admin ve los dos sin ficha de GT pasando su pais_id; '||v_n||' filas)' END, false);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p643','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;
SELECT set_config('role','none', true);

-- ############################################################################################
-- P644-P648 — comercial_supervisores_del_pais(uuid) (mig 287)
-- ############################################################################################
-- La funcion contesta "a quien puedo poner de supervisor en este pais". Devuelve las TRES
-- condiciones que el guard `guard_supervisor_asesor` (mig 264) exige y que se pueden saber de
-- antemano: rol supervisor_comercial (PA001), ficha activa (PA002) y mismo pais (PA003). PA004
-- (dos niveles) NO se anticipa: depende del asesor que se este editando.
--
-- Es LECTURA: sin autoridad devuelve CERO FILAS, no 42501. Las negativas miden conjunto vacio.
--
-- EL FIXTURE DE `activo` ES PROPIO, NO UNA MUTACION REVERTIDA. Se siembra un supervisor
-- INACTIVO nuevo en vez de desactivar a QA-SUP-01 y volver a activarlo: no toca datos existentes,
-- no depende de que la reversion funcione, y —lo que importa— deja al activo y al inactivo VIVOS a
-- la vez, asi que P647 mide el filtro y no la ausencia de fila. Si `activo = true` no estuviera en
-- el WHERE, el inactivo apareceria y P647 se pone roja.
SELECT set_config('role','none', true);
DO $$
DECLARE v_gt uuid := NULLIF(current_setting('probe.co_gt',true),'')::uuid;
        v_off uuid; v_sa uuid;
BEGIN
  IF coalesce(current_setting('probe.co_ready',true),'')<>'1' THEN
    PERFORM set_config('probe.sv_ready','0',false);
    PERFORM set_config('probe.sv_fx','ROJO — FIXTURE COMERCIAL AUSENTE (esto NO es un rechazo)',false); RETURN; END IF;
  IF v_gt IS NULL THEN
    PERFORM set_config('probe.sv_ready','0',false);
    PERFORM set_config('probe.sv_fx','ROJO — falta el id de GT',false); RETURN; END IF;

  -- supervisor_comercial de GT con ficha INACTIVA: cumple rol y pais, falla solo por `activo`.
  v_off := gen_random_uuid();
  INSERT INTO auth.users (id) VALUES (v_off);
  INSERT INTO public.perfiles (id, email, nombre_completo, rol, pais_id, activo)
    VALUES (v_off, 'p647.supoff@example.invalid', 'QA SV supervisor INACTIVO', 'supervisor_comercial', v_gt, true);
  INSERT INTO public.asesores_perfil (id, codigo_asesor, pais_id, activo)
    VALUES (v_off, 'QA-SUP-OFF-647', v_gt, false);

  SELECT id INTO v_sa FROM public.perfiles WHERE rol='super_admin' ORDER BY id LIMIT 1;

  PERFORM set_config('probe.sv_off', v_off::text, false);
  PERFORM set_config('probe.sv_sa',  coalesce(v_sa::text,''), false);
  PERFORM set_config('probe.sv_ready','1', false);
  PERFORM set_config('probe.sv_fx','OK (fixture supervisores: 1 supervisor de GT con ficha INACTIVA, junto al QA-SUP-01 activo)', false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('probe.sv_ready','0',false);
  PERFORM set_config('probe.sv_fx','ROJO ('||SQLSTATE||' '||SQLERRM||')',false);
END $$;

-- P644 — POSITIVO: el admin_pais de GT ve a QA-SUP-01 (activo, supervisor_comercial, GT).
-- Se busca el id EXACTO, no `count > 0`.
SELECT set_config('request.jwt.claims', json_build_object('sub', current_setting('probe.co_admgt',true), 'role','authenticated')::text, true);
SELECT set_config('role','authenticated', true);
DO $$ DECLARE v_sup uuid; v_n int; v_hay int; BEGIN
  IF coalesce(current_setting('probe.sv_ready',true),'')<>'1' THEN PERFORM set_config('probe.p644','N/A',false); RETURN; END IF;
  IF to_regprocedure('public.comercial_supervisores_del_pais(uuid)') IS NULL THEN
    PERFORM set_config('probe.p644','ROJO — RPC AUSENTE',false); RETURN; END IF;
  v_sup := NULLIF(current_setting('probe.co_sup',true),'')::uuid;
  SELECT count(*), count(*) FILTER (WHERE r.id = v_sup) INTO v_n, v_hay
    FROM public.comercial_supervisores_del_pais(NULLIF(current_setting('probe.co_gt',true),'')::uuid) r;
  PERFORM set_config('probe.p644', CASE
    WHEN v_n = 0   THEN 'ROJO (el admin de GT no recibio NINGUN supervisor)'
    WHEN v_hay = 0 THEN 'ROJO (QA-SUP-01 es supervisor activo de GT y NO aparece; '||v_n||' filas)'
    ELSE 'OK (el admin de GT ve a QA-SUP-01 entre los candidatos; '||v_n||' filas)' END, false);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p644','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;

-- P646 — CENSO DE ROL: ningun asesor_comercial entra. QA-ASE-01 tiene ficha ACTIVA en GT, asi que
-- cumple todo menos el rol: es el caso que distingue "filtra por rol" de "filtra por ficha activa".
-- Ademas se censa el conjunto entero contra perfiles.rol, no solo ese id.
DO $$ DECLARE v_ase1 uuid; v_hay int; v_malos text; BEGIN
  IF coalesce(current_setting('probe.sv_ready',true),'')<>'1' THEN PERFORM set_config('probe.p646','N/A',false); RETURN; END IF;
  IF to_regprocedure('public.comercial_supervisores_del_pais(uuid)') IS NULL THEN
    PERFORM set_config('probe.p646','ROJO — RPC AUSENTE',false); RETURN; END IF;
  v_ase1 := NULLIF(current_setting('probe.co_ase1',true),'')::uuid;
  SELECT count(*) FILTER (WHERE r.id = v_ase1),
         string_agg(DISTINCT p.rol, ', ') FILTER (WHERE p.rol IS DISTINCT FROM 'supervisor_comercial')
    INTO v_hay, v_malos
    FROM public.comercial_supervisores_del_pais(NULLIF(current_setting('probe.co_gt',true),'')::uuid) r
    JOIN public.perfiles p ON p.id = r.id;
  PERFORM set_config('probe.p646', CASE
    WHEN v_hay > 0           THEN 'ROJO (QA-ASE-01 es asesor_comercial y aparece como candidato a supervisor)'
    WHEN v_malos IS NOT NULL THEN 'ROJO (roles distintos de supervisor_comercial en el resultado: '||v_malos||')'
    ELSE 'OK (todos los candidatos son supervisor_comercial; QA-ASE-01 excluido)' END, false);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p646','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;

-- P647 — CENSO DE `activo`: el supervisor con ficha INACTIVA no entra, y el ACTIVO sigue estando.
-- Las dos mitades en la misma probe: sin la segunda, un WHERE que no devolviera nada tambien
-- pasaria la primera.
DO $$ DECLARE v_off uuid; v_sup uuid; v_hay_off int; v_hay_on int; v_inactivas int; BEGIN
  IF coalesce(current_setting('probe.sv_ready',true),'')<>'1' THEN PERFORM set_config('probe.p647','N/A',false); RETURN; END IF;
  IF to_regprocedure('public.comercial_supervisores_del_pais(uuid)') IS NULL THEN
    PERFORM set_config('probe.p647','ROJO — RPC AUSENTE',false); RETURN; END IF;
  v_off := NULLIF(current_setting('probe.sv_off',true),'')::uuid;
  v_sup := NULLIF(current_setting('probe.co_sup',true),'')::uuid;
  -- control del control: el fixture TIENE que estar inactivo, si no la probe no mide nada.
  IF NOT EXISTS (SELECT 1 FROM public.asesores_perfil WHERE id = v_off AND activo = false) THEN
    PERFORM set_config('probe.p647','FALLO (el fixture inactivo no quedo con activo=false: no mide el filtro)',false); RETURN; END IF;
  SELECT count(*) FILTER (WHERE r.id = v_off), count(*) FILTER (WHERE r.id = v_sup),
         count(*) FILTER (WHERE NOT ap.activo)
    INTO v_hay_off, v_hay_on, v_inactivas
    FROM public.comercial_supervisores_del_pais(NULLIF(current_setting('probe.co_gt',true),'')::uuid) r
    JOIN public.asesores_perfil ap ON ap.id = r.id;
  PERFORM set_config('probe.p647', CASE
    WHEN v_hay_off > 0   THEN 'ROJO (el supervisor con ficha INACTIVA aparece como candidato)'
    WHEN v_inactivas > 0 THEN 'ROJO ('||v_inactivas||' candidato(s) con ficha inactiva en el resultado)'
    WHEN v_hay_on = 0    THEN 'ROJO — CONTROL POSITIVO CAIDO (tampoco esta el ACTIVO: el filtro vacia todo, no filtra)'
    ELSE 'OK (el inactivo queda fuera y el activo sigue estando: el filtro activo=true se ejercita)' END, false);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p647','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;
SELECT set_config('role','none', true);

-- P645 — NEGATIVA DE AISLAMIENTO: el admin de HN pide los supervisores de GT -> 0 filas.
-- Es lectura: si algun dia lanza 42501, esta probe lo reporta como FALLO y no como exito.
SELECT set_config('request.jwt.claims', json_build_object('sub', current_setting('probe.co_admhn',true), 'role','authenticated')::text, true);
SELECT set_config('role','authenticated', true);
DO $$ DECLARE v_n int; v_sup int; BEGIN
  IF coalesce(current_setting('probe.sv_ready',true),'')<>'1' THEN PERFORM set_config('probe.p645','N/A',false); RETURN; END IF;
  IF to_regprocedure('public.comercial_supervisores_del_pais(uuid)') IS NULL THEN
    PERFORM set_config('probe.p645','ROJO — RPC AUSENTE',false); RETURN; END IF;
  BEGIN
    SELECT count(*), count(*) FILTER (WHERE r.id = NULLIF(current_setting('probe.co_sup',true),'')::uuid)
      INTO v_n, v_sup
      FROM public.comercial_supervisores_del_pais(NULLIF(current_setting('probe.co_gt',true),'')::uuid) r;
    PERFORM set_config('probe.p645', CASE
      WHEN v_sup > 0 THEN 'ROJO (el admin de HN VE a QA-SUP-01, supervisor de GT)'
      WHEN v_n > 0   THEN 'ROJO (el admin de HN recibio '||v_n||' fila(s) de la lista de GT)'
      ELSE 'OK (0 filas: pide GT y no es admin de GT)' END, false);
  EXCEPTION WHEN insufficient_privilege THEN
    PERFORM set_config('probe.p645','FALLO (lanzo 42501; esta funcion es lectura y debe devolver 0 filas)',false);
  WHEN others THEN PERFORM set_config('probe.p645','FALLO ('||SQLSTATE||' '||SQLERRM||')',false);
  END;
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p645','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;
SELECT set_config('role','none', true);

-- P648 — POSITIVO super_admin: la otra rama del gate, y el MISMO conjunto que ve el admin de GT.
-- Sin esta, el 0 filas de P645 tambien lo cumpliria una funcion que no le devuelve nada a nadie.
DO $$ DECLARE v_sa text; BEGIN
  v_sa := coalesce(current_setting('probe.sv_sa',true),'');
  IF v_sa <> '' THEN
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_sa, 'role','authenticated')::text, true);
  END IF;
EXCEPTION WHEN OTHERS THEN NULL; END $$;
SELECT set_config('role','authenticated', true);
DO $$ DECLARE v_n int; v_hay int; v_off int; BEGIN
  IF coalesce(current_setting('probe.sv_ready',true),'')<>'1' THEN PERFORM set_config('probe.p648','N/A',false); RETURN; END IF;
  IF coalesce(current_setting('probe.sv_sa',true),'')='' THEN
    PERFORM set_config('probe.p648','ROJO — NO HAY SUPER_ADMIN (la rama no se puede medir)',false); RETURN; END IF;
  IF to_regprocedure('public.comercial_supervisores_del_pais(uuid)') IS NULL THEN
    PERFORM set_config('probe.p648','ROJO — RPC AUSENTE',false); RETURN; END IF;
  SELECT count(*), count(*) FILTER (WHERE r.id = NULLIF(current_setting('probe.co_sup',true),'')::uuid),
         count(*) FILTER (WHERE r.id = NULLIF(current_setting('probe.sv_off',true),'')::uuid)
    INTO v_n, v_hay, v_off
    FROM public.comercial_supervisores_del_pais(NULLIF(current_setting('probe.co_gt',true),'')::uuid) r;
  PERFORM set_config('probe.p648', CASE
    WHEN v_hay = 0 THEN 'ROJO (el super_admin no ve a QA-SUP-01 en GT: '||v_n||' filas)'
    WHEN v_off > 0 THEN 'ROJO (el super_admin SI ve al inactivo: el filtro activo=true no aplica en esta rama)'
    ELSE 'OK (super_admin ve el mismo conjunto que el admin de GT: '||v_n||' fila(s), sin el inactivo)' END, false);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p648','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;
SELECT set_config('role','none', true);

-- ############################################################################################
-- P615-P630 — las cuatro RPCs del frente de visitas que estaban sin cobertura
-- ############################################################################################
-- LEIDAS DEL CUERPO REAL antes de escribir estas probes, no de la memoria del contrato. Tres cosas
-- salieron distintas de lo que se suponia y las probes miden lo que la funcion HACE:
--
--   1. `cerrar_jornada` usa UN SOLO errcode (PA021) para dos situaciones distintas: "no abriste
--      jornada hoy" y "ya la cerraste". El SELECT filtra `fin_at IS NULL`, asi que la jornada ya
--      cerrada simplemente no aparece. No se distinguen. P620/P621 lo fijan tal cual es.
--   2. `checkout_visita_comercial` NO chequea `checkout_at IS NULL`: el doble checkout esta
--      PERMITIDO y pisaba checkout_at. CERRADO por la mig 285 con PA029: P625 ahora lo EXIGE.
--   3. `config_visitas_efectiva` no rechaza a nadie. Para un rol no comercial devuelve UNA fila
--      con la config de SU PROPIO pais (mi_pais() lee perfiles.pais_id, sin mirar el rol). No es
--      fuga —no revela config ajena— pero tampoco es un rechazo. P629 lo mide.
--
-- Numeracion: P615-P619 coordenadas_visita · P620-P622 cerrar_jornada ·
--             P623-P626 checkout_visita_comercial · P627-P630 config_visitas_efectiva

-- ============================================================================================
-- coordenadas_visita(uuid) — gate real: COALESCE(private.puede_admin_pais(v.pais_id), false)
-- puede_admin_pais = super_admin O (admin_pais Y mismo pais). SOLO ADMINS: ni el supervisor del
-- asesor ni el ASESOR DUENO de la visita pasan. Confirmado contra el cuerpo, no asumido.
-- ============================================================================================
SELECT set_config('role','none', true);
DO $$ DECLARE v_sa uuid; BEGIN
  IF coalesce(current_setting('probe.vj_ready',true),'')<>'1'
     OR coalesce(current_setting('probe.vj_v_cerca',true),'')='' THEN
    PERFORM set_config('probe.cv_ready','0',false);
    PERFORM set_config('probe.cv_fx','ROJO — FIXTURE DE VISITAS AUSENTE (esto NO es un rechazo)',false); RETURN; END IF;
  SELECT id INTO v_sa FROM public.perfiles WHERE rol='super_admin' ORDER BY id LIMIT 1;
  IF v_sa IS NULL THEN
    PERFORM set_config('probe.cv_ready','0',false);
    PERFORM set_config('probe.cv_fx','ROJO — NO HAY SUPER_ADMIN (P618 no podria medir)',false); RETURN; END IF;
  PERFORM set_config('probe.cv_sa', v_sa::text, false);
  PERFORM set_config('probe.cv_ready','1', false);
  PERFORM set_config('probe.cv_fx','OK (fixture coordenadas: visita con check-in + super_admin identificado)', false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('probe.cv_ready','0',false);
  PERFORM set_config('probe.cv_fx','ROJO ('||SQLSTATE||' '||SQLERRM||')',false);
END $$;

-- P615 — CONTROL POSITIVO: admin_pais de GT SI ve las coordenadas de una visita de su pais.
-- Va PRIMERO a proposito: sin el, las cuatro negativas de abajo pasarian aunque la RPC rechazara a
-- todo el mundo, que es la forma mas facil de tener un frente entero en verde sin medir nada.
SELECT set_config('request.jwt.claims', json_build_object('sub', current_setting('probe.co_admgt',true), 'role','authenticated')::text, true);
SELECT set_config('role','authenticated', true);
DO $$ DECLARE v_n int; v_lat numeric; BEGIN
  IF coalesce(current_setting('probe.cv_ready',true),'')<>'1' THEN PERFORM set_config('probe.p615','N/A',false); RETURN; END IF;
  IF to_regprocedure('public.coordenadas_visita(uuid)') IS NULL THEN
    PERFORM set_config('probe.p615','ROJO — RPC AUSENTE',false); RETURN; END IF;
  BEGIN
    SELECT count(*), max(c.checkin_lat) INTO v_n, v_lat
      FROM public.coordenadas_visita(NULLIF(current_setting('probe.vj_v_cerca',true),'')::uuid) c;
    PERFORM set_config('probe.p615', CASE
      WHEN v_n = 0    THEN 'ROJO (el admin del pais no recibio NINGUNA fila)'
      WHEN v_lat IS NULL THEN 'ROJO (recibio fila pero checkin_lat vino NULL: la visita del fixture tiene check-in con coordenada)'
      ELSE 'OK (admin_pais LEE la coordenada de una visita de su pais: '||v_n||' fila, lat no nula)' END, false);
  EXCEPTION WHEN insufficient_privilege THEN
    PERFORM set_config('probe.p615','ROJO (42501 al admin del PROPIO pais: la RPC no le sirve a nadie)',false);
  WHEN others THEN PERFORM set_config('probe.p615','FALLO ('||SQLSTATE||' '||SQLERRM||')',false);
  END;
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p615','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;

-- P616 — el SUPERVISOR del asesor de esa visita NO. Es el caso que motivo la mig 277: el que
-- supervisa necesita saber si alguien estuvo donde dijo, no DONDE estuvo.
SELECT set_config('request.jwt.claims', json_build_object('sub', current_setting('probe.co_sup',true), 'role','authenticated')::text, true);
SELECT set_config('role','authenticated', true);
DO $$ DECLARE v_n int; BEGIN
  IF coalesce(current_setting('probe.cv_ready',true),'')<>'1' THEN PERFORM set_config('probe.p616','N/A',false); RETURN; END IF;
  IF to_regprocedure('public.coordenadas_visita(uuid)') IS NULL THEN
    PERFORM set_config('probe.p616','ROJO — RPC AUSENTE',false); RETURN; END IF;
  BEGIN
    SELECT count(*) INTO v_n FROM public.coordenadas_visita(NULLIF(current_setting('probe.vj_v_cerca',true),'')::uuid) c;
    PERFORM set_config('probe.p616','ROJO (PERMITIO — el supervisor leyo las coordenadas: '||v_n||' fila(s))',false);
  EXCEPTION WHEN insufficient_privilege THEN
    PERFORM set_config('probe.p616','OK (42501 no_autorizado al supervisor del asesor)',false);
  WHEN others THEN PERFORM set_config('probe.p616','FALLO (esperaba 42501, vino '||SQLSTATE||': '||SQLERRM||')',false);
  END;
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p616','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;

-- P617 — el ASESOR DUENO de la visita TAMPOCO. Confirmado contra el cuerpo: el gate es
-- puede_admin_pais(), no hay ninguna rama `asesor_id = auth.uid()`. Es contraintuitivo —son SUS
-- coordenadas— y por eso tiene probe propia: si manana alguien "corrige" eso creyendo que es un
-- olvido, esta fila se pone roja y obliga a decidirlo a proposito.
SELECT set_config('request.jwt.claims', json_build_object('sub', current_setting('probe.co_ase1',true), 'role','authenticated')::text, true);
SELECT set_config('role','authenticated', true);
DO $$ DECLARE v_n int; BEGIN
  IF coalesce(current_setting('probe.cv_ready',true),'')<>'1' THEN PERFORM set_config('probe.p617','N/A',false); RETURN; END IF;
  IF to_regprocedure('public.coordenadas_visita(uuid)') IS NULL THEN
    PERFORM set_config('probe.p617','ROJO — RPC AUSENTE',false); RETURN; END IF;
  BEGIN
    SELECT count(*) INTO v_n FROM public.coordenadas_visita(NULLIF(current_setting('probe.vj_v_cerca',true),'')::uuid) c;
    PERFORM set_config('probe.p617','ROJO (PERMITIO — el asesor dueno leyo las coordenadas: '||v_n||' fila(s))',false);
  EXCEPTION WHEN insufficient_privilege THEN
    PERFORM set_config('probe.p617','OK (42501: ni el dueno de la visita; el gate es solo admins)',false);
  WHEN others THEN PERFORM set_config('probe.p617','FALLO (esperaba 42501, vino '||SQLSTATE||': '||SQLERRM||')',false);
  END;
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p617','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;

-- P618 — admin_pais de OTRO pais NO (la visita es de GT, el admin es de HN).
-- Y de paso, el CONTROL de la otra rama: el super_admin SI, que es lo que prueba que el 42501 de
-- arriba viene del PAIS y no de que la funcion rechace a todo el mundo.
SELECT set_config('request.jwt.claims', json_build_object('sub', current_setting('probe.co_admhn',true), 'role','authenticated')::text, true);
SELECT set_config('role','authenticated', true);
DO $$ DECLARE v_n int; v_hn text; BEGIN
  IF coalesce(current_setting('probe.cv_ready',true),'')<>'1' THEN PERFORM set_config('probe.p618','N/A',false); RETURN; END IF;
  IF to_regprocedure('public.coordenadas_visita(uuid)') IS NULL THEN
    PERFORM set_config('probe.p618','ROJO — RPC AUSENTE',false); RETURN; END IF;
  BEGIN
    SELECT count(*) INTO v_n FROM public.coordenadas_visita(NULLIF(current_setting('probe.vj_v_cerca',true),'')::uuid) c;
    v_hn := 'ROJO (PERMITIO — el admin de HN leyo coordenadas de una visita de GT: '||v_n||' fila(s))';
  EXCEPTION WHEN insufficient_privilege THEN v_hn := 'OK';
  WHEN others THEN v_hn := 'FALLO (esperaba 42501, vino '||SQLSTATE||': '||SQLERRM||')';
  END;
  PERFORM set_config('probe.p618_hn', v_hn, false);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p618_hn','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;
SELECT set_config('role','none', true);
DO $$ DECLARE v_sa text; BEGIN
  v_sa := coalesce(current_setting('probe.cv_sa',true),'');
  IF v_sa <> '' THEN
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_sa, 'role','authenticated')::text, true);
  END IF;
EXCEPTION WHEN OTHERS THEN NULL; END $$;
SELECT set_config('role','authenticated', true);
DO $$ DECLARE v_n int; v_sa text; v_hn text; BEGIN
  IF coalesce(current_setting('probe.cv_ready',true),'')<>'1' THEN PERFORM set_config('probe.p618','N/A',false); RETURN; END IF;
  BEGIN
    SELECT count(*) INTO v_n FROM public.coordenadas_visita(NULLIF(current_setting('probe.vj_v_cerca',true),'')::uuid) c;
    v_sa := CASE WHEN v_n > 0 THEN 'OK' ELSE 'ROJO (super_admin recibio 0 filas)' END;
  EXCEPTION WHEN insufficient_privilege THEN v_sa := 'ROJO (42501 al super_admin: la rama tiene_rol no funciona)';
  WHEN others THEN v_sa := 'FALLO ('||SQLSTATE||' '||SQLERRM||')';
  END;
  v_hn := coalesce(current_setting('probe.p618_hn',true),'(sin medir)');
  PERFORM set_config('probe.p618', CASE WHEN v_hn='OK' AND v_sa='OK'
    THEN 'OK (admin de HN rechazado con 42501; super_admin SI ve: el corte es por pais, no un rechazo a todos)'
    ELSE 'admin_HN='||v_hn||' | super_admin='||v_sa END, false);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p618','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;
SELECT set_config('role','none', true);

-- P619 — anon sin EXECUTE en las CUATRO RPCs de este bloque, y authenticated con.
-- El par importa: "anon=false" solo tambien lo cumple una funcion que nadie puede llamar.
DO $$ DECLARE v_malas text; BEGIN
  SELECT string_agg(f, ', ') INTO v_malas FROM (
    SELECT p.oid::regprocedure::text AS f FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
     WHERE n.nspname='public' AND p.prokind='f'
       AND p.proname IN ('coordenadas_visita','cerrar_jornada','checkout_visita_comercial','config_visitas_efectiva')
       AND (has_function_privilege('anon', p.oid, 'EXECUTE')
            OR NOT has_function_privilege('authenticated', p.oid, 'EXECUTE'))
  ) s;
  IF NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
                  WHERE n.nspname='public' AND p.proname='coordenadas_visita') THEN
    PERFORM set_config('probe.p619','ROJO — RPCs AUSENTES (esto NO es un rechazo)',false); RETURN; END IF;
  PERFORM set_config('probe.p619', CASE WHEN v_malas IS NULL
    THEN 'OK (anon=false y authenticated=true en las 4)'
    ELSE 'ROJO (privilegios mal en: '||v_malas||')' END, false);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p619','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;

-- ============================================================================================
-- cerrar_jornada(numeric,numeric,numeric,text)
-- Gate real: busca la jornada de auth.uid() de HOY con fin_at IS NULL; si no hay -> PA021.
-- ============================================================================================
-- LIMPIEZA LOCAL. La del principio del archivo desacopla el lote de lo que haya en PRODUCCION,
-- pero no del estado que crean los bloques intermedios: P597 (control de adopcion de la mig 280)
-- deja a asesor2 CON jornada abierta. Sin esto, P622 no puede medir "sin jornada abierta" y P620 no
-- puede abrir la suya (PA020). Es el mismo problema una capa mas adentro.
DO $$ DECLARE v_n int; BEGIN
  IF to_regclass('public.jornadas_comerciales') IS NULL THEN
    PERFORM set_config('probe.cj_limpieza','N/A (tabla ausente)',false); RETURN; END IF;
  WITH borradas AS (
    DELETE FROM public.jornadas_comerciales j
     WHERE j.fecha = CURRENT_DATE
       AND j.asesor_id = NULLIF(current_setting('probe.co_ase2',true),'')::uuid   -- asesor2.qa
    RETURNING 1)
  SELECT count(*) INTO v_n FROM borradas;
  PERFORM set_config('probe.cj_limpieza','OK (jornadas de hoy de ase2 borradas antes del lote de cerrar_jornada: '||v_n||')',false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('probe.cj_limpieza','ROJO ('||SQLSTATE||' '||SQLERRM||') — P620/P621/P622 pueden estar midiendo otra cosa',false);
END $$;

-- P622 va primero en el codigo aunque tenga numero mas alto: es la NEGATIVA "sin jornada abierta",
-- y tiene que medirse ANTES de que P620 abra/cierre nada.
SELECT set_config('request.jwt.claims', json_build_object('sub', current_setting('probe.co_ase2',true), 'role','authenticated')::text, true);
SELECT set_config('role','authenticated', true);
DO $$ DECLARE v_hay int; BEGIN
  IF coalesce(current_setting('probe.co_ready',true),'')<>'1' THEN PERFORM set_config('probe.p622','N/A',false); RETURN; END IF;
  IF to_regprocedure('public.cerrar_jornada(numeric,numeric,numeric,text)') IS NULL THEN
    PERFORM set_config('probe.p622','ROJO — RPC AUSENTE',false); RETURN; END IF;
  -- control del control: si ase2 YA tuviera jornada abierta hoy, esta probe no mide "sin jornada".
  SELECT count(*) INTO v_hay FROM public.jornadas_comerciales
   WHERE asesor_id = NULLIF(current_setting('probe.co_ase2',true),'')::uuid
     AND fecha = CURRENT_DATE AND fin_at IS NULL;
  IF v_hay > 0 THEN
    PERFORM set_config('probe.p622','FALLO (ase2 YA tiene jornada abierta: la probe no mide "sin jornada")',false); RETURN; END IF;
  BEGIN
    PERFORM public.cerrar_jornada(NULL,NULL,NULL,NULL);
    PERFORM set_config('probe.p622','ROJO (PERMITIO cerrar sin ninguna jornada abierta)',false);
  EXCEPTION WHEN sqlstate 'PA021' THEN PERFORM set_config('probe.p622','OK (PA021 no tenes jornada abierta hoy)',false);
  WHEN others THEN PERFORM set_config('probe.p622','FALLO (esperaba PA021, vino '||SQLSTATE||': '||SQLERRM||')',false);
  END;
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p622','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;
SELECT set_config('role','none', true);

-- P620 — CONTROL POSITIVO: asesor2 abre su jornada y la cierra. Se verifica LA FILA (fin_at y las
-- notas), no que la RPC "no exploto".
-- P621 — la SEGUNDA llamada sobre la MISMA jornada ya cerrada -> tambien PA021, porque el SELECT
-- de la RPC filtra `fin_at IS NULL` y la jornada cerrada deja de existir para ella. "No abriste" y
-- "ya cerraste" NO se distinguen desde el cliente: eso queda escrito en el veredicto.
SELECT set_config('request.jwt.claims', json_build_object('sub', current_setting('probe.co_ase2',true), 'role','authenticated')::text, true);
SELECT set_config('role','authenticated', true);
DO $$ DECLARE v_j uuid; v_fin timestamptz; v_notas text; v_seg text; BEGIN
  IF coalesce(current_setting('probe.co_ready',true),'')<>'1' THEN
    PERFORM set_config('probe.p620','N/A',false); PERFORM set_config('probe.p621','N/A',false); RETURN; END IF;
  IF to_regprocedure('public.cerrar_jornada(numeric,numeric,numeric,text)') IS NULL THEN
    PERFORM set_config('probe.p620','ROJO — RPC AUSENTE',false);
    PERFORM set_config('probe.p621','ROJO — RPC AUSENTE',false); RETURN; END IF;
  BEGIN
    SELECT public.abrir_jornada(NULL,NULL,NULL) INTO v_j;
  EXCEPTION WHEN others THEN
    PERFORM set_config('probe.p620','FALLO (no se pudo abrir la jornada base: '||SQLSTATE||' '||SQLERRM||')',false);
    PERFORM set_config('probe.p621','N/A (sin jornada base)',false); RETURN; END;
  BEGIN
    PERFORM public.cerrar_jornada(NULL,NULL,NULL,'QA cierre P620');
  EXCEPTION WHEN others THEN
    PERFORM set_config('probe.p620','FALLO (esperaba PERMITIDO, vino '||SQLSTATE||': '||SQLERRM||')',false);
    PERFORM set_config('probe.p621','N/A (no cerro la primera)',false); RETURN; END;
  SELECT j.fin_at, j.notas_cierre INTO v_fin, v_notas
    FROM public.jornadas_comerciales j WHERE j.id = v_j;
  PERFORM set_config('probe.p620', CASE
    WHEN v_fin IS NULL THEN 'ROJO (la RPC paso pero fin_at quedo NULL: la jornada sigue abierta)'
    WHEN v_notas IS DISTINCT FROM 'QA cierre P620' THEN 'FALLO (fin_at ok pero notas_cierre quedo: '||coalesce(v_notas,'nulo')||')'
    ELSE 'OK (la FILA quedo con fin_at y notas_cierre)' END, false);
  -- segunda llamada, misma jornada, ya cerrada
  BEGIN
    PERFORM public.cerrar_jornada(NULL,NULL,NULL,'QA segundo cierre');
    v_seg := 'ROJO (PERMITIO cerrar dos veces la misma jornada)';
  EXCEPTION WHEN sqlstate 'PA021' THEN
    v_seg := 'OK (PA021 — MISMO errcode que "no abriste jornada": la RPC no distingue los dos casos, el SELECT filtra fin_at IS NULL)';
  WHEN others THEN v_seg := 'FALLO (esperaba PA021, vino '||SQLSTATE||': '||SQLERRM||')';
  END;
  PERFORM set_config('probe.p621', v_seg, false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('probe.p620','FALLO ('||SQLSTATE||' '||SQLERRM||')',false);
  PERFORM set_config('probe.p621','FALLO ('||SQLSTATE||' '||SQLERRM||')',false);
END $$;
SELECT set_config('role','none', true);

-- ============================================================================================
-- checkout_visita_comercial(uuid,numeric,numeric)
-- Gate real: `asesor_id = auth.uid()` dentro de COALESCE -> 42501. Sin check-in -> PA022.
-- Jornada de la visita cerrada -> PA019. NO hay chequeo de checkout_at: ver P625.
-- ============================================================================================
-- P624 — NEGATIVA primero: el SUPERVISOR hace checkout de una visita ajena -> 42501. Se mide antes
-- que el positivo para que la visita todavia este sin checkout y el rechazo sea del GATE y no de
-- un estado ya consumido.
SELECT set_config('request.jwt.claims', json_build_object('sub', current_setting('probe.co_sup',true), 'role','authenticated')::text, true);
SELECT set_config('role','authenticated', true);
DO $$ DECLARE v_msg text; BEGIN
  IF coalesce(current_setting('probe.vj_ready',true),'')<>'1'
     OR coalesce(current_setting('probe.vj_v_cerca',true),'')='' THEN
    PERFORM set_config('probe.p624','N/A (falta la visita con check-in)',false); RETURN; END IF;
  IF to_regprocedure('public.checkout_visita_comercial(uuid,numeric,numeric)') IS NULL THEN
    PERFORM set_config('probe.p624','ROJO — RPC AUSENTE',false); RETURN; END IF;
  BEGIN
    PERFORM public.checkout_visita_comercial(NULLIF(current_setting('probe.vj_v_cerca',true),'')::uuid, NULL, NULL);
    PERFORM set_config('probe.p624','ROJO (PERMITIO — el supervisor cerro una visita ajena)',false);
  EXCEPTION WHEN insufficient_privilege THEN
    GET STACKED DIAGNOSTICS v_msg = MESSAGE_TEXT;
    PERFORM set_config('probe.p624', CASE
      WHEN v_msg ILIKE '%no_autorizado%' THEN 'OK (42501 no_autorizado al supervisor)'
      ELSE 'FALLO (42501 pero el mensaje dice: '||v_msg||')' END, false);
  WHEN others THEN PERFORM set_config('probe.p624','FALLO (esperaba 42501, vino '||SQLSTATE||': '||SQLERRM||')',false);
  END;
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p624','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;
SELECT set_config('role','none', true);

-- P623 — CONTROL POSITIVO: el asesor dueno cierra su visita con check-in previo. Se lee LA FILA:
-- checkout_at poblado Y estado='realizada'.
-- P625 — DOBLE CHECKOUT, cerrado por la mig 285. `checkout_visita_comercial` chequea
-- `checkout_at IS NOT NULL` y responde PA029: cerrar una visita dos veces es reescribir un hecho ya
-- registrado, y ahora no se puede. Esta probe fue ROJA y vivio en la lista DEUDA del runner
-- nombrando el pendiente #3; al aplicarse la 285 salio de esa lista. Si alguien quitara el guard,
-- vuelve a rojo por si sola.
SELECT set_config('request.jwt.claims', json_build_object('sub', current_setting('probe.co_ase1',true), 'role','authenticated')::text, true);
SELECT set_config('role','authenticated', true);
DO $$ DECLARE v_id uuid; v_out1 timestamptz; v_out2 timestamptz; v_estado text; v_seg text; BEGIN
  IF coalesce(current_setting('probe.vj_ready',true),'')<>'1'
     OR coalesce(current_setting('probe.vj_v_cerca',true),'')='' THEN
    PERFORM set_config('probe.p623','N/A (falta la visita con check-in)',false);
    PERFORM set_config('probe.p625','N/A',false); RETURN; END IF;
  IF to_regprocedure('public.checkout_visita_comercial(uuid,numeric,numeric)') IS NULL THEN
    PERFORM set_config('probe.p623','ROJO — RPC AUSENTE',false);
    PERFORM set_config('probe.p625','ROJO — RPC AUSENTE',false); RETURN; END IF;
  v_id := NULLIF(current_setting('probe.vj_v_cerca',true),'')::uuid;
  BEGIN
    PERFORM public.checkout_visita_comercial(v_id, NULL, NULL);
  EXCEPTION WHEN others THEN
    PERFORM set_config('probe.p623','FALLO (esperaba PERMITIDO, vino '||SQLSTATE||': '||SQLERRM||')',false);
    PERFORM set_config('probe.p625','N/A (no hubo primer checkout)',false); RETURN; END;
  SELECT v.checkout_at, v.estado INTO v_out1, v_estado FROM public.visitas_comerciales v WHERE v.id = v_id;
  PERFORM set_config('probe.p623', CASE
    WHEN v_out1 IS NULL THEN 'ROJO (la RPC paso pero checkout_at quedo NULL)'
    WHEN v_estado IS DISTINCT FROM 'realizada' THEN 'FALLO (checkout_at ok pero el estado quedo: '||coalesce(v_estado,'nulo')||')'
    ELSE 'OK (la FILA quedo con checkout_at y estado=realizada)' END, false);
  -- SEGUNDO checkout sobre la misma visita -> PA029 (mig 285). Se mide el RECHAZO, no el efecto
  -- sobre checkout_at: el harness corre en UNA transaccion con `now()` congelado, asi que un
  -- segundo UPDATE escribiria el mismo timestamp y "no cambio" nunca probaria que no piso.
  BEGIN
    PERFORM public.checkout_visita_comercial(v_id, NULL, NULL);
    SELECT v.checkout_at INTO v_out2 FROM public.visitas_comerciales v WHERE v.id = v_id;
    v_seg := 'ROJO (SIN GUARD — permitio el segundo checkout sin rechazo)';
  EXCEPTION WHEN sqlstate 'PA029' THEN
    v_seg := 'OK (PA029 rechaza el doble checkout)';
  WHEN others THEN
    v_seg := 'FALLO (esperaba PA029, vino '||SQLSTATE||': '||SQLERRM||')';
  END;
  PERFORM set_config('probe.p625', v_seg, false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('probe.p623','FALLO ('||SQLSTATE||' '||SQLERRM||')',false);
  PERFORM set_config('probe.p625','FALLO ('||SQLSTATE||' '||SQLERRM||')',false);
END $$;

-- P626 — checkout con la JORNADA de la visita ya cerrada -> PA019. Se arma una visita propia con
-- check-in, se cierra la jornada de ase1 y recien ahi se intenta el checkout.
DO $$ DECLARE v_p uuid; v_v uuid; v_lat numeric; v_lng numeric; v_gt uuid; v_ase1 uuid; v_admgt uuid; BEGIN
  IF coalesce(current_setting('probe.vj_ready',true),'')<>'1' THEN PERFORM set_config('probe.p626','N/A',false); RETURN; END IF;
  IF to_regprocedure('public.checkout_visita_comercial(uuid,numeric,numeric)') IS NULL THEN
    PERFORM set_config('probe.p626','ROJO — RPC AUSENTE',false); RETURN; END IF;
  v_gt := NULLIF(current_setting('probe.co_gt',true),'')::uuid;
  v_ase1 := NULLIF(current_setting('probe.co_ase1',true),'')::uuid;
  v_admgt := NULLIF(current_setting('probe.co_admgt',true),'')::uuid;
  v_lat := NULLIF(current_setting('probe.vj_lat',true),'')::numeric;
  v_lng := NULLIF(current_setting('probe.vj_lng',true),'')::numeric;
  BEGIN
    -- fixture propio, como OWNER: prospecto fresco + visita de hoy con check-in ya puesto
    PERFORM set_config('role','none', true);
    INSERT INTO public.prospectos (nombre, tipo, pais_id, asesor_id, creado_por, estado_pipeline, lat, lng)
      VALUES ('QA P626 jornada cerrada','farmacia',v_gt,v_ase1,v_admgt,'nuevo',v_lat,v_lng) RETURNING id INTO v_p;
    INSERT INTO public.visitas_comerciales
      (prospecto_id, asesor_id, pais_id, jornada_id, fecha_planificada, estado, planificada_por,
       checkin_at, checkin_origen)
      VALUES (v_p, v_ase1, v_gt, NULLIF(current_setting('probe.vj_jornada',true),'')::uuid,
              CURRENT_DATE, 'en_curso', v_admgt, now(), 'en_linea')
      RETURNING id INTO v_v;
  EXCEPTION WHEN others THEN
    PERFORM set_config('probe.p626','FALLO (no se pudo armar el fixture: '||SQLSTATE||' '||SQLERRM||')',false); RETURN; END;
  -- ase1 cierra su jornada
  PERFORM set_config('request.jwt.claims', json_build_object('sub', current_setting('probe.co_ase1',true), 'role','authenticated')::text, true);
  PERFORM set_config('role','authenticated', true);
  BEGIN
    PERFORM public.cerrar_jornada(NULL,NULL,NULL,'QA cierre P626');
  EXCEPTION WHEN others THEN
    PERFORM set_config('probe.p626','FALLO (ase1 no pudo cerrar su jornada: '||SQLSTATE||' '||SQLERRM||')',false); RETURN; END;
  BEGIN
    PERFORM public.checkout_visita_comercial(v_v, NULL, NULL);
    PERFORM set_config('probe.p626','ROJO (PERMITIO checkout con la jornada YA CERRADA)',false);
  EXCEPTION WHEN sqlstate 'PA019' THEN PERFORM set_config('probe.p626','OK (PA019 la jornada de esa visita ya esta cerrada)',false);
  WHEN others THEN PERFORM set_config('probe.p626','FALLO (esperaba PA019, vino '||SQLSTATE||': '||SQLERRM||')',false);
  END;
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p626','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;
SELECT set_config('role','none', true);

-- ============================================================================================
-- config_visitas_efectiva()
-- Cuerpo real: LANGUAGE sql, devuelve UNA fila desde private.mi_pais(). No hay gate de rol ni
-- RAISE: no rechaza a nadie. Los defaults salen de radio_checkin_m()/precision_max_checkin_m(),
-- que envuelven la consulta en COALESCE(..., 150) y COALESCE(..., 100).
-- ============================================================================================
-- P627 — POSITIVO: el asesor lee la config de SU pais, con las 4 columnas del contrato.
SELECT set_config('request.jwt.claims', json_build_object('sub', current_setting('probe.co_ase1',true), 'role','authenticated')::text, true);
SELECT set_config('role','authenticated', true);
DO $$ DECLARE r record; v_n int; BEGIN
  IF coalesce(current_setting('probe.co_ready',true),'')<>'1' THEN PERFORM set_config('probe.p627','N/A',false); RETURN; END IF;
  IF to_regprocedure('public.config_visitas_efectiva()') IS NULL THEN
    PERFORM set_config('probe.p627','ROJO — RPC AUSENTE',false); RETURN; END IF;
  SELECT count(*) INTO v_n FROM public.config_visitas_efectiva();
  SELECT * INTO r FROM public.config_visitas_efectiva() LIMIT 1;
  PERFORM set_config('probe.p627', CASE
    WHEN v_n <> 1 THEN 'ROJO (devolvio '||v_n||' filas, esperaba exactamente 1)'
    WHEN r.pais_id IS DISTINCT FROM NULLIF(current_setting('probe.co_gt',true),'')::uuid
      THEN 'ROJO (devolvio el pais '||coalesce(r.pais_id::text,'nulo')||' y el asesor es de GT)'
    WHEN r.radio_checkin_m IS NULL OR r.precision_max_m IS NULL
      THEN 'ROJO (radio o precision vinieron NULL: eso es "sin limite", no un umbral)'
    ELSE 'OK (1 fila del pais del asesor: radio='||r.radio_checkin_m||' precision='||r.precision_max_m||' hay_fila='||r.hay_fila||')' END, false);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p627','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;

-- P628 — D5, EL CASO FAIL-CLOSED: GT no tiene fila en config_visitas_pais (el fixture de la 273 la
-- deja ausente A PROPOSITO). hay_fila tiene que ser false Y los umbrales tienen que venir 150/100,
-- nunca NULL ni un valor que signifique "sin limite". Un NULL aca abriria el check-in a cualquier
-- distancia, que es exactamente lo que la decision D5 vino a evitar.
DO $$ DECLARE r record; BEGIN
  IF coalesce(current_setting('probe.co_ready',true),'')<>'1' THEN PERFORM set_config('probe.p628','N/A',false); RETURN; END IF;
  IF to_regprocedure('public.config_visitas_efectiva()') IS NULL THEN
    PERFORM set_config('probe.p628','ROJO — RPC AUSENTE',false); RETURN; END IF;
  SELECT * INTO r FROM public.config_visitas_efectiva() LIMIT 1;
  IF r.hay_fila THEN
    -- control del control: si alguien sembro la config de GT, esta probe ya no mide el default
    PERFORM set_config('probe.p628','N/A (GT TIENE fila en config_visitas_pais: el default no se ejercita aca)',false); RETURN; END IF;
  PERFORM set_config('probe.p628', CASE
    WHEN r.radio_checkin_m IS NULL OR r.precision_max_m IS NULL
      THEN 'ROJO — FAIL-OPEN (sin fila de config los umbrales vinieron NULL: check-in a cualquier distancia)'
    WHEN r.radio_checkin_m = 150 AND r.precision_max_m = 100
      THEN 'OK (hay_fila=false y el default fail-closed 150/100 igual llega)'
    ELSE 'FALLO (hay_fila=false pero los defaults son '||r.radio_checkin_m||'/'||r.precision_max_m||', esperaba 150/100)' END, false);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p628','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;
SELECT set_config('role','none', true);

-- P629 — ROL NO COMERCIAL (un medico). Medido, no supuesto: la RPC NO rechaza, y esta bien que no
-- lo haga. `mi_pais()` lee `perfiles.pais_id` sin mirar el rol, asi que un medico recibe la config
-- de SU PROPIO pais: un radio de check-in y una precision maxima no son dato reservado, y no hay
-- nada que un no comercial pueda hacer con ellos. Esta probe existe para dejar escrito que la
-- ausencia de gate por rol es DELIBERADA — sin ella, la proxima auditoria la lee como un hueco y
-- "arregla" algo que no esta roto. Lo que si seria rojo esta cubierto: devolver el pais de OTRO.
SELECT set_config('request.jwt.claims', json_build_object('sub', current_setting('probe.co_medf',true), 'role','authenticated')::text, true);
SELECT set_config('role','authenticated', true);
DO $$ DECLARE r record; v_n int; v_pais_med uuid; BEGIN
  IF coalesce(current_setting('probe.co_ready',true),'')<>'1' THEN PERFORM set_config('probe.p629','N/A',false); RETURN; END IF;
  IF to_regprocedure('public.config_visitas_efectiva()') IS NULL THEN
    PERFORM set_config('probe.p629','ROJO — RPC AUSENTE',false); RETURN; END IF;
  BEGIN
    SELECT count(*) INTO v_n FROM public.config_visitas_efectiva();
    SELECT * INTO r FROM public.config_visitas_efectiva() LIMIT 1;
  EXCEPTION WHEN insufficient_privilege THEN
    PERFORM set_config('probe.p629','RECHAZA (42501 al rol no comercial)',false); RETURN;
  WHEN others THEN
    PERFORM set_config('probe.p629','RECHAZA ('||SQLSTATE||': '||SQLERRM||')',false); RETURN;
  END;
  PERFORM set_config('role','none', true);
  SELECT pais_id INTO v_pais_med FROM public.perfiles WHERE id = NULLIF(current_setting('probe.co_medf',true),'')::uuid;
  PERFORM set_config('probe.p629', CASE
    WHEN v_n = 0 THEN 'ROJO (no rechaza pero devuelve 0 filas: ni gate ni dato)'
    WHEN r.pais_id IS NOT DISTINCT FROM v_pais_med
      THEN 'OK (NO RECHAZA por diseno — devuelve la config del PROPIO pais del medico ('||coalesce(r.pais_id::text,'nulo')
           ||', '||r.radio_checkin_m||'/'||r.precision_max_m||'): mi_pais() no mira el rol. Un radio de check-in no es dato reservado; que no haya gate por rol NO es un hueco.)'
    ELSE 'ROJO (devolvio el pais '||coalesce(r.pais_id::text,'nulo')||' que NO es el del medico ('||coalesce(v_pais_med::text,'nulo')||'))' END, false);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p629','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;
SELECT set_config('role','none', true);

-- P630 — CENSO: la RPC no devuelve ninguna columna de coordenada ni de identidad. Es lo que impide
-- que manana alguien agregue `lat`/`lng` al RETURNS TABLE "para el mapa" sin que nadie lo note.
DO $$ DECLARE v_oid oid; v_cols text[]; v_malas text; BEGIN
  v_oid := to_regprocedure('public.config_visitas_efectiva()');
  IF v_oid IS NULL THEN PERFORM set_config('probe.p630','ROJO — RPC AUSENTE',false); RETURN; END IF;
  SELECT array_agg(a.name ORDER BY a.ord) INTO v_cols
    FROM unnest((SELECT proargnames FROM pg_proc WHERE oid=v_oid),
                (SELECT proargmodes FROM pg_proc WHERE oid=v_oid)) WITH ORDINALITY AS a(name, mode, ord)
   WHERE a.mode IN ('t','o');
  SELECT string_agg(c, ', ') INTO v_malas FROM unnest(coalesce(v_cols,'{}')) c
   WHERE c LIKE '%\_lat' OR c LIKE '%\_lng' OR c IN ('email','telefono','nombre_completo');
  PERFORM set_config('probe.p630', CASE
    WHEN v_malas IS NOT NULL THEN 'ROJO — COLUMNAS INDEBIDAS en el retorno: '||v_malas
    WHEN v_cols IS DISTINCT FROM ARRAY['pais_id','radio_checkin_m','precision_max_m','hay_fila']
      THEN 'ROJO (el retorno no es el contratado: '||coalesce(array_to_string(v_cols,', '),'(vacio)')||')'
    ELSE 'OK (4 columnas: pais_id, radio_checkin_m, precision_max_m, hay_fila)' END, false);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p630','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;

-- ############################################################################################
-- P631-P634 — privilegios de tabla sobre perfiles y sobre el modulo comercial (mig 284)
-- ############################################################################################
-- `public.perfiles` es la tabla con mas datos personales del sistema: email, telefono, direccion
-- del consultorio, lat/lng, avatar. Nacio con el ACL default de Supabase —ALL para anon y para
-- authenticated— y NUNCA se reboco: no hay un solo GRANT sobre perfiles en todo git.
--
-- Hasta hoy eso no era explotable: las cinco policies de la tabla dependen de auth.uid(), que para
-- anon es NULL, asi que la RLS lo frena. Pero **TRUNCATE NO PASA POR RLS**. Un privilegio de
-- TRUNCATE en manos de anon es la capacidad de vaciar la tabla entera, y la unica barrera que hubo
-- durante toda la vida del proyecto fue que nadie lo intentara.
--
-- P631 mide anon (los 7, tiene que quedar en 0). P632 mide authenticated, que SI necesita
-- SELECT/INSERT/UPDATE/DELETE —la RLS los filtra fila por fila— pero no tiene nada que hacer con
-- TRUNCATE/REFERENCES/TRIGGER. P633 es el control positivo: que la lectura normal siga viva.
-- P634 es el censo del modulo comercial, que hoy ya esta limpio y tiene que seguir estandolo.

-- P631 — CENSO: anon sin los 6 privilegios de escritura/DDL sobre perfiles, y CON el SELECT.
-- El SELECT se conserva a proposito y NO es una fuga —la RLS deja a anon en cero filas—: es el
-- permiso que necesita TODA policy que consulte `perfiles` en su USING para poder evaluarse y
-- DECIR QUE NO —36 policies en 29 tablas, medido 6-sep-2026; la cifra lleva fecha porque es estado
-- de la base, no una constante—. Una policy corre con los privilegios del LLAMANTE: sin SELECT, ese EXISTS lanza
-- 42501 antes de decidir nada y la tabla entera deja de responderle a anon. Medido: revocarlo
-- rompio produccion y el harness entero. Por eso el SELECT se mide como REQUISITO, no como sobra.
SELECT set_config('role','none', true);
DO $$ DECLARE v_tiene text; BEGIN
  IF to_regclass('public.perfiles') IS NULL THEN
    PERFORM set_config('probe.p631','ROJO — TABLA AUSENTE (esto NO es un rechazo)',false); RETURN; END IF;
  SELECT string_agg(p, ', ' ORDER BY p) INTO v_tiene
    FROM unnest(ARRAY['INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER']) p
   WHERE has_table_privilege('anon', 'public.perfiles', p);
  PERFORM set_config('probe.p631', CASE
    WHEN NOT has_table_privilege('anon','public.perfiles','SELECT')
      THEN 'ROJO — SIN SELECT: toda policy que consulta perfiles lanza 42501 a anon en vez de negar en silencio (ver P635)'
    WHEN v_tiene IS NULL
      THEN 'OK (anon sin los 6 de escritura/DDL; conserva SELECT, que las policies necesitan para evaluarse)'
    ELSE 'ROJO (anon conserva sobre perfiles: '||v_tiene||
         CASE WHEN has_table_privilege('anon','public.perfiles','TRUNCATE')
              THEN ' — TRUNCATE NO PASA POR RLS: es vaciar la tabla' ELSE '' END||')' END, false);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p631','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;

-- P632 — authenticated sobre perfiles: los 4 de DML SI (la RLS los acota fila por fila), los otros
-- 3 NO. Se reportan las dos direcciones por separado: un privilegio DE MENOS rompe la app, uno DE
-- MAS la expone, y confundir los dos casos en un solo "ROJO" hace perder el diagnostico.
DO $$ DECLARE v_falta text; v_sobra text; BEGIN
  IF to_regclass('public.perfiles') IS NULL THEN
    PERFORM set_config('probe.p632','ROJO — TABLA AUSENTE (esto NO es un rechazo)',false); RETURN; END IF;
  SELECT string_agg(p, ', ' ORDER BY p) INTO v_falta
    FROM unnest(ARRAY['SELECT','INSERT','UPDATE','DELETE']) p
   WHERE NOT has_table_privilege('authenticated', 'public.perfiles', p);
  SELECT string_agg(p, ', ' ORDER BY p) INTO v_sobra
    FROM unnest(ARRAY['TRUNCATE','REFERENCES','TRIGGER']) p
   WHERE has_table_privilege('authenticated', 'public.perfiles', p);
  PERFORM set_config('probe.p632', CASE
    WHEN v_falta IS NOT NULL AND v_sobra IS NOT NULL
      THEN 'ROJO (de MENOS: '||v_falta||' | de MAS: '||v_sobra||')'
    WHEN v_falta IS NOT NULL THEN 'ROJO — DE MENOS: '||v_falta||' (la RLS los necesita; sin ellos la app se rompe)'
    WHEN v_sobra IS NOT NULL THEN 'ROJO — DE MAS: '||v_sobra
    ELSE 'OK (authenticated con los 4 de DML y sin TRUNCATE/REFERENCES/TRIGGER)' END, false);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p632','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;

-- P633 — CONTROL POSITIVO. Un usuario real leyendo SU PROPIO perfil por SELECT normal. Tiene que
-- estar VERDE antes y despues de la 284: si la revocacion se pasa de la raya y le saca el SELECT a
-- authenticated, P632 lo dice por catalogo y esta lo dice por el camino real. Las dos hacen falta:
-- el catalogo no prueba que la policy `Ver propio perfil` siga funcionando.
SELECT set_config('request.jwt.claims', json_build_object('sub', current_setting('probe.co_medf',true), 'role','authenticated')::text, true);
SELECT set_config('role','authenticated', true);
DO $$ DECLARE v_n int; v_yo uuid; BEGIN
  IF coalesce(current_setting('probe.co_ready',true),'')<>'1' THEN PERFORM set_config('probe.p633','N/A',false); RETURN; END IF;
  v_yo := NULLIF(current_setting('probe.co_medf',true),'')::uuid;
  BEGIN
    SELECT count(*) INTO v_n FROM public.perfiles p WHERE p.id = v_yo;
    PERFORM set_config('probe.p633', CASE
      WHEN v_n = 1 THEN 'OK (el usuario lee su propio perfil: 1 fila; la 284 no rompio la lectura normal)'
      WHEN v_n = 0 THEN 'ROJO (el usuario NO puede leer su propio perfil: se reboco de mas o la policy se rompio)'
      ELSE 'FALLO (esperaba 1 fila, vinieron '||v_n||')' END, false);
  EXCEPTION WHEN insufficient_privilege THEN
    PERFORM set_config('probe.p633','ROJO (42501 al leer el propio perfil: se le saco el SELECT a authenticated)',false);
  WHEN others THEN PERFORM set_config('probe.p633','FALLO ('||SQLSTATE||' '||SQLERRM||')',false);
  END;
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p633','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;
SELECT set_config('role','none', true);

-- P634 — CENSO del modulo comercial: anon sin NINGUNO de los 7 sobre las 9 tablas del frente.
-- P458 (bloque 264) ya cubre 3 de estas con una regla MAS estricta —authenticated solo con SELECT—
-- y se deja como esta: extenderlo a las 9 le cambiaria la semantica, porque no todas las tablas del
-- frente tienen por que limitarse a SELECT. Este censo pregunta otra cosa y la pregunta para todas.
-- Hoy nace VERDE (medido: las 9 con anon en cero). Existe para que siga estandolo: la proxima tabla
-- del frente nace con el ACL default de Supabase, igual que nacio perfiles.
DO $$ DECLARE v_malas text; v_n int; BEGIN
  SELECT count(*), string_agg(t||':'||p, ', ' ORDER BY t, p) FILTER (WHERE tiene) INTO v_n, v_malas
    FROM (
      SELECT t, p, has_table_privilege('anon', t, p) AS tiene
        FROM unnest(ARRAY['public.asesores_perfil','public.prospectos','public.prospecto_contactos',
                          'public.jornadas_comerciales','public.visitas_comerciales',
                          'public.reportes_visita','public.visita_adjuntos',
                          'public.material_comercial','public.config_visitas_pais']) t
       CROSS JOIN unnest(ARRAY['SELECT','INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER']) p
       WHERE to_regclass(t) IS NOT NULL) s;
  PERFORM set_config('probe.p634', CASE
    WHEN v_n < 63 THEN 'ROJO — CENSO INCOMPLETO ('||v_n||' de 63 pares tabla/privilegio: falta alguna de las 9 tablas)'
    WHEN v_malas IS NULL THEN 'OK (las 9 tablas del frente comercial, 7 privilegios cada una: anon en cero)'
    ELSE 'ROJO (anon tiene: '||v_malas||')' END, false);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p634','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;

-- ############################################################################################
-- P635 / P636 — la clase de probe que le faltaba a toda migracion de privilegios
-- ############################################################################################
-- LA LECCION, del 6-sep-2026: la primera version de la mig 284 hizo `REVOKE ALL ON perfiles FROM
-- anon` y ROMPIO PRODUCCION. El dry-run no lo vio, porque un dry-run de privilegios mira el
-- CATALOGO —quien tiene que— y no EJERCITA al rol contra las tablas que dependen de el.
--
-- Una policy se evalua con los privilegios del LLAMANTE. Toda policy que consulta `perfiles` en su
-- USING (36 policies en 29 tablas, medido 6-sep-2026) dejaba de poder evaluarse: en vez de negar en
-- silencio —EXISTS sobre perfiles con auth.uid() NULL da false— lanzaba 42501 duro, y la tabla
-- entera dejaba de responderle a anon.
--
-- P635 es esa probe: como anon, contra tres tablas dependientes. Habria estado ROJA antes de
-- aplicar. P636 es su contraprueba: revoca el SELECT DE VERDAD dentro de un savepoint que despues
-- deshace, y confirma que P635 se pondria roja si el privilegio faltara.

-- P635 — Como ANON, sin claims: tres tablas cuyas policies consultan `perfiles`.
-- TRES veredictos distintos, que son tres cosas distintas y no se pueden confundir:
--   42501  -> a anon le falta un privilegio que el USING de la policy necesita. La tabla esta ROTA
--             para anon: no niega, revienta.
--   N > 0  -> FUGA. La policy dejo pasar filas a un anonimo.
--   0 filas sin error -> lo correcto: la policy pudo evaluarse y dijo que no.
SELECT set_config('role','none',true);
SELECT set_config('request.jwt.claims', NULL, true);
SELECT set_config('role','anon',true);
DO $$
DECLARE r record; v_roto text := ''; v_rotograve text := ''; v_fuga text := ''; v_ok int := 0; v_n int; v_faltan text := '';
BEGIN
  FOR r IN SELECT unnest(ARRAY['public.clinicas','public.empresas_proveedoras',
                               'public.visitas_agendadas']) AS t
  LOOP
    IF to_regclass(r.t) IS NULL THEN v_faltan := v_faltan||r.t||' '; CONTINUE; END IF;
    BEGIN
      EXECUTE 'SELECT count(*) FROM '||r.t INTO v_n;
      IF v_n > 0 THEN v_fuga := v_fuga||r.t||'='||v_n||' ';
      ELSE v_ok := v_ok + 1; END IF;
    EXCEPTION WHEN insufficient_privilege THEN
      -- 42501 CON grant (empresas_proveedoras kept) = policy rota (hazard); SIN grant (clinicas/visitas revocadas) = correcto.
      IF has_table_privilege('anon', r.t, 'SELECT') THEN v_rotograve := v_rotograve||r.t||' ';
      ELSE v_roto := v_roto||r.t||' '; END IF;
    WHEN others THEN
      v_fuga := v_fuga||r.t||':'||SQLSTATE||' ';
    END;
  END LOOP;
  PERFORM set_config('probe.p635', CASE
    WHEN v_faltan <> ''    THEN 'ROJO — TABLAS AUSENTES: '||v_faltan||'(esto NO es un rechazo)'
    WHEN v_rotograve <> '' THEN 'ROJO (42501 CON grant (policy rota): '||v_rotograve||')'
    WHEN v_fuga <> ''      THEN 'ROJO (anon ve filas — fuga: '||v_fuga||')'
    WHEN v_roto <> ''      THEN 'OK (42501 sin grant en tablas revocadas por 324: '||v_roto||'; sin fuga)'
    WHEN v_ok = 3          THEN 'OK (0 filas, sin error, en las 3: la policy pudo evaluarse y dijo que no)'
    ELSE 'FALLO (solo '||v_ok||' de 3 tablas medidas)' END, false);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p635','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;
SELECT set_config('role','none',true);

-- P636 — CONTRAPRUEBA DE P635, sin tocar prod. Revoca el SELECT de anon sobre perfiles DE VERDAD,
-- comprueba que `clinicas` pasa a dar 42501, y deshace el REVOKE con un RAISE propio (PX001) que
-- revierte el savepoint del bloque interno. Sin esto, P635 es una promesa: pasaria en verde aunque
-- fuera incapaz de detectar el 42501 que dice detectar.
--
-- El veredicto vive en una VARIABLE plpgsql y se publica DESPUES de cerrar el bloque: un set_config
-- hecho adentro se revierte junto con el savepoint (leccion de P470-P477).
DO $$
DECLARE v_n int; v_caso text; v_volvio boolean;
BEGIN
  IF to_regclass('public.clinicas') IS NULL OR to_regclass('public.perfiles') IS NULL THEN
    PERFORM set_config('probe.p636','ROJO — TABLAS AUSENTES (esto NO es un rechazo)',false); RETURN; END IF;
  IF NOT has_table_privilege('anon','public.perfiles','SELECT') THEN
    PERFORM set_config('probe.p636','N/A (anon ya esta sin SELECT: no hay nada que revocar y devolver)',false); RETURN; END IF;

  BEGIN
    REVOKE SELECT ON public.perfiles FROM anon;
    PERFORM set_config('role','anon', true);
    BEGIN
      SELECT count(*) INTO v_n FROM public.clinicas;
      v_caso := 'ROJO — CONTRAPRUEBA CAIDA (sin el SELECT sobre perfiles, anon igual leyo clinicas: '
                ||v_n||' filas; P635 no puede detectar lo que dice detectar)';
    EXCEPTION WHEN insufficient_privilege THEN
      v_caso := 'OK';
    WHEN others THEN
      v_caso := 'FALLO (esperaba 42501, vino '||SQLSTATE||': '||SQLERRM||')';
    END;
    PERFORM set_config('role','none', true);
    -- deshace el REVOKE: el savepoint del bloque revierte la DDL
    RAISE EXCEPTION 'PROBE_UNDO' USING ERRCODE = 'PX001';
  EXCEPTION
    WHEN sqlstate 'PX001' THEN NULL;
    WHEN OTHERS THEN v_caso := coalesce(v_caso, 'FALLO fuera del caso ('||SQLSTATE||' '||SQLERRM||')');
  END;

  PERFORM set_config('role','none', true);
  -- y lo que hace que esta probe sea segura: que el privilegio VOLVIO.
  v_volvio := has_table_privilege('anon','public.perfiles','SELECT');
  PERFORM set_config('probe.p636', CASE
    WHEN NOT v_volvio THEN 'ROJO — EL REVOKE NO SE DESHIZO: anon quedo sin SELECT sobre perfiles. '
                           'Es dentro de la transaccion del harness, asi que el ROLLBACK final lo cubre, '
                           'pero el savepoint no funciono y esta probe no se puede usar asi.'
    WHEN v_caso = 'OK' THEN 'OK (sin el SELECT, clinicas da 42501 a anon; el REVOKE se deshizo y el privilegio volvio)'
    ELSE coalesce(v_caso,'FALLO (sin veredicto)') END, false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('role','none', true);
  PERFORM set_config('probe.p636','FALLO ('||SQLSTATE||' '||SQLERRM||')',false);
END $$;
SELECT set_config('role','none',true);

-- ############################################################################################
-- P649-P661 — tarjeta publica del asesor (mig 288)
-- ############################################################################################
-- La UNICA superficie anonima del modulo. No la sirve PostgREST: la resuelve una edge con
-- service_role, y `anon` no tiene EXECUTE sobre ninguna de las cuatro RPCs.
--
-- El nucleo de estas probes es que los CUATRO motivos de no-respuesta —token inexistente,
-- consentimiento apagado, ficha inactiva, perfil inactivo— devuelven EXACTAMENTE lo mismo. Si
-- alguno se distinguiera, la resolutora seria un oraculo que le confirma a un anonimo que cierto
-- token existe pero esta apagado.
--
-- Fixture propio con tres pares perfil+ficha frescos: el caso feliz, uno con ficha inactiva y uno
-- con PERFIL inactivo. Los tres nacen con la tarjeta apagada, que es el default.
SELECT set_config('role','none', true);
DO $$
DECLARE v_gt uuid := NULLIF(current_setting('probe.co_gt',true),'')::uuid;
        v_a uuid; v_b uuid; v_c uuid;
BEGIN
  IF coalesce(current_setting('probe.co_ready',true),'')<>'1' THEN
    PERFORM set_config('probe.tj_ready','0',false);
    PERFORM set_config('probe.tj_fx','ROJO — FIXTURE COMERCIAL AUSENTE (esto NO es un rechazo)',false); RETURN; END IF;
  IF to_regprocedure('public.tarjeta_publica_por_token(text)') IS NULL THEN
    PERFORM set_config('probe.tj_ready','0',false);
    PERFORM set_config('probe.tj_fx','ROJO — MIG 288 AUSENTE (esto NO es un rechazo)',false); RETURN; END IF;

  v_a := gen_random_uuid(); v_b := gen_random_uuid(); v_c := gen_random_uuid();

  -- (A) el caso feliz: perfil activo, ficha activa
  INSERT INTO auth.users (id) VALUES (v_a);
  INSERT INTO public.perfiles (id, email, nombre_completo, rol, pais_id, activo)
    VALUES (v_a, 'p649.a@example.invalid', 'QA TJ Asesor Feliz', 'asesor_comercial', v_gt, true);
  INSERT INTO public.asesores_perfil (id, codigo_asesor, pais_id, activo, cargo, territorio, telefono, celular)
    VALUES (v_a, 'QA-TJ-A', v_gt, true, 'Ejecutivo', 'Zona 1', '2222-0001', '5555-0001');

  -- (B) FICHA inactiva
  INSERT INTO auth.users (id) VALUES (v_b);
  INSERT INTO public.perfiles (id, email, nombre_completo, rol, pais_id, activo)
    VALUES (v_b, 'p649.b@example.invalid', 'QA TJ Ficha Inactiva', 'asesor_comercial', v_gt, true);
  INSERT INTO public.asesores_perfil (id, codigo_asesor, pais_id, activo)
    VALUES (v_b, 'QA-TJ-B', v_gt, false);

  -- (C) PERFIL inactivo, ficha activa: los dos flags se miran por separado
  INSERT INTO auth.users (id) VALUES (v_c);
  INSERT INTO public.perfiles (id, email, nombre_completo, rol, pais_id, activo)
    VALUES (v_c, 'p649.c@example.invalid', 'QA TJ Perfil Inactivo', 'asesor_comercial', v_gt, false);
  INSERT INTO public.asesores_perfil (id, codigo_asesor, pais_id, activo)
    VALUES (v_c, 'QA-TJ-C', v_gt, true);

  PERFORM set_config('probe.tj_a', v_a::text, false);
  PERFORM set_config('probe.tj_b', v_b::text, false);
  PERFORM set_config('probe.tj_c', v_c::text, false);
  PERFORM set_config('probe.tj_tok_a', (SELECT tarjeta_token FROM public.asesores_perfil WHERE id=v_a), false);
  PERFORM set_config('probe.tj_tok_b', (SELECT tarjeta_token FROM public.asesores_perfil WHERE id=v_b), false);
  PERFORM set_config('probe.tj_tok_c', (SELECT tarjeta_token FROM public.asesores_perfil WHERE id=v_c), false);
  PERFORM set_config('probe.tj_ready','1', false);
  PERFORM set_config('probe.tj_fx','OK (fixture tarjeta: 3 pares perfil+ficha — feliz, ficha inactiva, perfil inactivo)', false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('probe.tj_ready','0',false);
  PERFORM set_config('probe.tj_fx','ROJO ('||SQLSTATE||' '||SQLERRM||')',false);
END $$;

-- P649 — EL DEFAULT: una ficha nueva nace APAGADA y con token propio. Que el default sea false no
-- es cosmetico: una tarjeta que naciera encendida publicaria el telefono de alguien que nunca lo
-- pidio. Y los tokens tienen que ser DISTINTOS entre si — si el DEFAULT se evaluara una sola vez
-- en vez de por fila, el UNIQUE lo cazaria, pero la probe lo dice explicito.
DO $$ DECLARE v_pub int; v_vacio int; v_dist int; v_tot int; BEGIN
  IF coalesce(current_setting('probe.tj_ready',true),'')<>'1' THEN PERFORM set_config('probe.p649','N/A',false); RETURN; END IF;
  SELECT count(*) FILTER (WHERE ap.tarjeta_publica),
         count(*) FILTER (WHERE coalesce(ap.tarjeta_token,'') = ''),
         count(DISTINCT ap.tarjeta_token), count(*)
    INTO v_pub, v_vacio, v_dist, v_tot
    FROM public.asesores_perfil ap
   WHERE ap.id IN (NULLIF(current_setting('probe.tj_a',true),'')::uuid,
                   NULLIF(current_setting('probe.tj_b',true),'')::uuid,
                   NULLIF(current_setting('probe.tj_c',true),'')::uuid);
  PERFORM set_config('probe.p649', CASE
    WHEN v_tot <> 3      THEN 'FALLO (el fixture no sembro 3 fichas, sembro '||v_tot||')'
    WHEN v_pub > 0       THEN 'ROJO — NACE ENCENDIDA ('||v_pub||' de 3 con tarjeta_publica=true sin que nadie consintiera)'
    WHEN v_vacio > 0     THEN 'ROJO ('||v_vacio||' ficha(s) con tarjeta_token nulo o vacio)'
    WHEN v_dist <> v_tot THEN 'ROJO (tokens repetidos: '||v_dist||' distintos para '||v_tot||' fichas — el DEFAULT no se evalua por fila)'
    ELSE 'OK (3 fichas nuevas: apagadas, con token propio y distinto cada una)' END, false);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p649','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;

-- P650 — token VALIDO pero consentimiento APAGADO -> no responde.
DO $$ DECLARE v_r jsonb; BEGIN
  IF coalesce(current_setting('probe.tj_ready',true),'')<>'1' THEN PERFORM set_config('probe.p650','N/A',false); RETURN; END IF;
  v_r := public.tarjeta_publica_por_token(current_setting('probe.tj_tok_a',true));
  PERFORM set_config('probe.p650', CASE WHEN v_r IS NULL
    THEN 'OK (consentimiento apagado: no devuelve nada)'
    ELSE 'ROJO — PUBLICA SIN CONSENTIMIENTO: '||v_r::text END, false);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p650','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;

-- P654 — token INEXISTENTE -> exactamente lo mismo que P650. Los dos NULL: indistinguibles.
DO $$ DECLARE v_r jsonb; BEGIN
  IF coalesce(current_setting('probe.tj_ready',true),'')<>'1' THEN PERFORM set_config('probe.p654','N/A',false); RETURN; END IF;
  v_r := public.tarjeta_publica_por_token('token-que-no-existe-en-ninguna-parte-0000');
  PERFORM set_config('probe.p654', CASE WHEN v_r IS NULL
    THEN 'OK (token inexistente: mismo NULL que el consentimiento apagado, no se distinguen)'
    ELSE 'ROJO (un token inexistente devolvio algo: '||v_r::text||')' END, false);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p654','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;

-- P657 — tarjeta_set_consentimiento: el asesor enciende LA PROPIA. La RPC no toma id, asi que lo
-- que hay que probar es que el sujeto es auth.uid(): se enciende como el asesor A y se verifica que
-- la unica que quedo encendida POR ESTA LLAMADA es la de A.
--
-- SE MIDE EL DELTA Y NO EL TOTAL. La version original contaba TODAS las fichas con
-- tarjeta_publica=true, o sea toda la tabla, y asumia que no habia ninguna encendida de antes. Eso
-- fue cierto el dia que se escribio y dejo de serlo apenas la feature se uso: la probe se pone roja
-- sola por un dato ajeno, sin que nada este mal. Paso el 7-sep-2026, con la ficha QA-ASE-01
-- encendida para verificar la edge. La pregunta que la probe quiere responder es "a quien encendio
-- ESTA llamada", no "cuantas tarjetas hay encendidas en el mundo".
SELECT set_config('role','none', true);
DO $$ BEGIN
  PERFORM set_config('probe.tj_pub_antes',
    coalesce((SELECT string_agg(ap.id::text, ',' ORDER BY ap.id)
                FROM public.asesores_perfil ap WHERE ap.tarjeta_publica), ''), false);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.tj_pub_antes','', false); END $$;
DO $$ DECLARE v_a text; BEGIN
  v_a := coalesce(current_setting('probe.tj_a',true),'');
  IF v_a <> '' THEN
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_a, 'role','authenticated')::text, true);
  END IF;
EXCEPTION WHEN OTHERS THEN NULL; END $$;
SELECT set_config('role','authenticated', true);
DO $$ DECLARE v_a uuid; v_mias int; v_ajenas int; v_sello timestamptz; BEGIN
  IF coalesce(current_setting('probe.tj_ready',true),'')<>'1' THEN PERFORM set_config('probe.p657','N/A',false); RETURN; END IF;
  IF to_regprocedure('public.tarjeta_set_consentimiento(boolean)') IS NULL THEN
    PERFORM set_config('probe.p657','ROJO — RPC AUSENTE',false); RETURN; END IF;
  v_a := NULLIF(current_setting('probe.tj_a',true),'')::uuid;
  BEGIN
    PERFORM public.tarjeta_set_consentimiento(true);
  EXCEPTION WHEN others THEN
    PERFORM set_config('probe.p657','FALLO (el asesor no pudo encender la propia: '||SQLSTATE||' '||SQLERRM||')',false); RETURN; END;
  PERFORM set_config('role','none', true);
  -- v_ajenas = las que quedaron publicadas y NO lo estaban antes de la llamada, sacando la de A.
  -- string_to_array('', ',') da {""}, que no matchea ningun uuid: con la tabla vacia de tarjetas
  -- encendidas el delta sigue siendo el total, que es lo correcto.
  SELECT count(*) FILTER (WHERE ap.id = v_a),
         count(*) FILTER (WHERE ap.id <> v_a
                            AND NOT (ap.id::text = ANY (string_to_array(
                                  coalesce(current_setting('probe.tj_pub_antes',true),''), ',')))),
         max(ap.tarjeta_consentimiento_at) FILTER (WHERE ap.id = v_a)
    INTO v_mias, v_ajenas, v_sello
    FROM public.asesores_perfil ap WHERE ap.tarjeta_publica;
  PERFORM set_config('probe.p657', CASE
    WHEN v_mias = 0     THEN 'ROJO (encendio pero la ficha del asesor NO quedo publicada)'
    WHEN v_ajenas > 0   THEN 'ROJO — TOCO FICHAS AJENAS ('||v_ajenas||' de otros se publicaron POR ESTA LLAMADA)'
    WHEN v_sello IS NULL THEN 'FALLO (quedo publicada pero sin tarjeta_consentimiento_at)'
    ELSE 'OK (encendio SOLO la propia, con el sello de consentimiento puesto)' END, false);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p657','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;
SELECT set_config('role','none', true);

-- P651 — CENSO DEL RETORNO. Con consentimiento encendido devuelve EXACTAMENTE seis claves. Es censo
-- y no un caso: manana alguien agrega `email` o `codigo_asesor` "para el QR" y un test que solo
-- mirara `nombre_completo` no se enteraria.
DO $$ DECLARE v_r jsonb; v_claves text[]; v_malas text; BEGIN
  IF coalesce(current_setting('probe.tj_ready',true),'')<>'1' THEN PERFORM set_config('probe.p651','N/A',false); RETURN; END IF;
  v_r := public.tarjeta_publica_por_token(current_setting('probe.tj_tok_a',true));
  IF v_r IS NULL THEN
    PERFORM set_config('probe.p651','ROJO (con consentimiento ENCENDIDO no devolvio nada)',false); RETURN; END IF;
  SELECT array_agg(k ORDER BY k) INTO v_claves FROM jsonb_object_keys(v_r) k;
  SELECT string_agg(k, ', ') INTO v_malas FROM unnest(v_claves) k
   WHERE k IN ('id','email','pais_id','codigo_asesor','bio','supervisor_id','tarjeta_token',
               'foto_path','activo','fecha_ingreso');
  PERFORM set_config('probe.p651', CASE
    WHEN v_malas IS NOT NULL THEN 'ROJO — CAMPOS PROHIBIDOS en la tarjeta publica: '||v_malas
    WHEN v_claves IS DISTINCT FROM ARRAY['cargo','celular','foto_publica_path','nombre_completo','telefono','territorio']
      THEN 'ROJO (el retorno no es el contratado: '||array_to_string(v_claves,', ')||')'
    WHEN v_r->>'nombre_completo' IS NULL THEN 'FALLO (las 6 claves estan pero nombre_completo vino nulo)'
    ELSE 'OK (exactamente 6 claves: cargo, celular, foto_publica_path, nombre_completo, telefono, territorio)' END, false);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p651','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;

-- P652 / P653 — ficha inactiva y PERFIL inactivo. Los dos flags se miran por separado: con uno solo
-- en el WHERE, uno de los dos casos publicaria. Se les enciende el consentimiento a proposito para
-- que lo unico que los frene sea el flag de actividad.
DO $$ DECLARE v_rb jsonb; v_rc jsonb; BEGIN
  IF coalesce(current_setting('probe.tj_ready',true),'')<>'1' THEN
    PERFORM set_config('probe.p652','N/A',false); PERFORM set_config('probe.p653','N/A',false); RETURN; END IF;
  UPDATE public.asesores_perfil SET tarjeta_publica = true, tarjeta_consentimiento_at = now()
   WHERE id IN (NULLIF(current_setting('probe.tj_b',true),'')::uuid,
                NULLIF(current_setting('probe.tj_c',true),'')::uuid);
  v_rb := public.tarjeta_publica_por_token(current_setting('probe.tj_tok_b',true));
  v_rc := public.tarjeta_publica_por_token(current_setting('probe.tj_tok_c',true));
  PERFORM set_config('probe.p652', CASE WHEN v_rb IS NULL
    THEN 'OK (ficha activo=false: no responde aunque el consentimiento este encendido)'
    ELSE 'ROJO (ficha INACTIVA publicada: '||v_rb::text||')' END, false);
  PERFORM set_config('probe.p653', CASE WHEN v_rc IS NULL
    THEN 'OK (perfil activo=false: no responde aunque la ficha este activa y consentida)'
    ELSE 'ROJO (perfil INACTIVO publicado: '||v_rc::text||')' END, false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('probe.p652','FALLO ('||SQLSTATE||' '||SQLERRM||')',false);
  PERFORM set_config('probe.p653','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;

-- P655 / P656 — anon y authenticated NO pueden llamar a la resolutora. EJERCITADO, no leido del
-- catalogo: la leccion de la 284 es que el catalogo dice quien tiene el privilegio y no que pasa
-- cuando se usa. Aca lo que se mide es el 42501 real.
SELECT set_config('role','none',true);
SELECT set_config('request.jwt.claims', NULL, true);
SELECT set_config('role','anon',true);
DO $$ DECLARE v_r jsonb; BEGIN
  IF coalesce(current_setting('probe.tj_ready',true),'')<>'1' THEN PERFORM set_config('probe.p655','N/A',false); RETURN; END IF;
  BEGIN
    v_r := public.tarjeta_publica_por_token(current_setting('probe.tj_tok_a',true));
    PERFORM set_config('probe.p655','ROJO — ANON EJECUTO LA RESOLUTORA (devolvio: '||coalesce(v_r::text,'NULL')||')',false);
  EXCEPTION WHEN insufficient_privilege THEN
    PERFORM set_config('probe.p655','OK (42501: anon no puede ejecutarla; la llama la edge con service_role)',false);
  WHEN others THEN PERFORM set_config('probe.p655','FALLO (esperaba 42501, vino '||SQLSTATE||': '||SQLERRM||')',false);
  END;
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p655','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;
SELECT set_config('role','none',true);
SELECT set_config('request.jwt.claims', json_build_object('sub', current_setting('probe.co_ase1',true), 'role','authenticated')::text, true);
SELECT set_config('role','authenticated',true);
DO $$ DECLARE v_r jsonb; BEGIN
  IF coalesce(current_setting('probe.tj_ready',true),'')<>'1' THEN PERFORM set_config('probe.p656','N/A',false); RETURN; END IF;
  BEGIN
    v_r := public.tarjeta_publica_por_token(current_setting('probe.tj_tok_a',true));
    PERFORM set_config('probe.p656','ROJO — AUTHENTICATED EJECUTO LA RESOLUTORA (devolvio: '||coalesce(v_r::text,'NULL')||')',false);
  EXCEPTION WHEN insufficient_privilege THEN
    PERFORM set_config('probe.p656','OK (42501: ni authenticated; solo service_role)',false);
  WHEN others THEN PERFORM set_config('probe.p656','FALLO (esperaba 42501, vino '||SQLSTATE||': '||SQLERRM||')',false);
  END;
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p656','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;
SELECT set_config('role','none',true);

-- P658 — tarjeta_apagar_de_asesor: el admin del pais SI apaga. Control positivo de P659/P660: sin
-- el, los dos 42501 tambien los cumpliria una RPC que rechaza a todo el mundo.
SELECT set_config('request.jwt.claims', json_build_object('sub', current_setting('probe.co_admgt',true), 'role','authenticated')::text, true);
SELECT set_config('role','authenticated', true);
DO $$ DECLARE v_a uuid; v_pub boolean; BEGIN
  IF coalesce(current_setting('probe.tj_ready',true),'')<>'1' THEN PERFORM set_config('probe.p658','N/A',false); RETURN; END IF;
  IF to_regprocedure('public.tarjeta_apagar_de_asesor(uuid)') IS NULL THEN
    PERFORM set_config('probe.p658','ROJO — RPC AUSENTE',false); RETURN; END IF;
  v_a := NULLIF(current_setting('probe.tj_a',true),'')::uuid;
  -- control del control: tiene que estar ENCENDIDA antes, si no apagar no prueba nada.
  PERFORM set_config('role','none', true);
  SELECT tarjeta_publica INTO v_pub FROM public.asesores_perfil WHERE id = v_a;
  PERFORM set_config('role','authenticated', true);
  IF NOT COALESCE(v_pub, false) THEN
    PERFORM set_config('probe.p658','FALLO (la tarjeta no estaba encendida: apagarla no mide nada)',false); RETURN; END IF;
  BEGIN
    PERFORM public.tarjeta_apagar_de_asesor(v_a);
  EXCEPTION WHEN others THEN
    PERFORM set_config('probe.p658','FALLO (el admin del pais no pudo apagar: '||SQLSTATE||' '||SQLERRM||')',false); RETURN; END;
  PERFORM set_config('role','none', true);
  SELECT tarjeta_publica INTO v_pub FROM public.asesores_perfil WHERE id = v_a;
  PERFORM set_config('probe.p658', CASE WHEN COALESCE(v_pub,true)
    THEN 'ROJO (la RPC paso pero la tarjeta sigue publicada)'
    ELSE 'OK (el admin del pais apago la tarjeta; se verifico la FILA)' END, false);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p658','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;
SELECT set_config('role','none', true);

-- P659 — admin de OTRO pais -> 42501. El pais sale de la FICHA, no de un parametro.
SELECT set_config('request.jwt.claims', json_build_object('sub', current_setting('probe.co_admhn',true), 'role','authenticated')::text, true);
SELECT set_config('role','authenticated', true);
DO $$ BEGIN
  IF coalesce(current_setting('probe.tj_ready',true),'')<>'1' THEN PERFORM set_config('probe.p659','N/A',false); RETURN; END IF;
  IF to_regprocedure('public.tarjeta_apagar_de_asesor(uuid)') IS NULL THEN
    PERFORM set_config('probe.p659','ROJO — RPC AUSENTE',false); RETURN; END IF;
  BEGIN
    PERFORM public.tarjeta_apagar_de_asesor(NULLIF(current_setting('probe.tj_a',true),'')::uuid);
    PERFORM set_config('probe.p659','ROJO (PERMITIO — el admin de HN apago una tarjeta de GT)',false);
  EXCEPTION WHEN insufficient_privilege THEN
    PERFORM set_config('probe.p659','OK (42501 no_autorizado al admin de otro pais)',false);
  WHEN others THEN PERFORM set_config('probe.p659','FALLO (esperaba 42501, vino '||SQLSTATE||': '||SQLERRM||')',false);
  END;
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p659','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;
SELECT set_config('role','none', true);

-- P660 — un ASESOR cualquiera tampoco apaga la de otro: apagar es del admin, no de un par.
SELECT set_config('request.jwt.claims', json_build_object('sub', current_setting('probe.co_ase1',true), 'role','authenticated')::text, true);
SELECT set_config('role','authenticated', true);
DO $$ BEGIN
  IF coalesce(current_setting('probe.tj_ready',true),'')<>'1' THEN PERFORM set_config('probe.p660','N/A',false); RETURN; END IF;
  IF to_regprocedure('public.tarjeta_apagar_de_asesor(uuid)') IS NULL THEN
    PERFORM set_config('probe.p660','ROJO — RPC AUSENTE',false); RETURN; END IF;
  BEGIN
    PERFORM public.tarjeta_apagar_de_asesor(NULLIF(current_setting('probe.tj_a',true),'')::uuid);
    PERFORM set_config('probe.p660','ROJO (PERMITIO — un asesor apago la tarjeta de otro)',false);
  EXCEPTION WHEN insufficient_privilege THEN
    PERFORM set_config('probe.p660','OK (42501 no_autorizado a un asesor sin autoridad de pais)',false);
  WHEN others THEN PERFORM set_config('probe.p660','FALLO (esperaba 42501, vino '||SQLSTATE||': '||SQLERRM||')',false);
  END;
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p660','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;
SELECT set_config('role','none', true);

-- P661 — rotar el token: el link que el asesor ya repartio deja de resolver. Se enciende de nuevo
-- (P658 la apago) para que lo unico que cambie entre las dos consultas sea el token.
DO $$ DECLARE v_a text; BEGIN
  v_a := coalesce(current_setting('probe.tj_a',true),'');
  IF v_a <> '' THEN
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_a, 'role','authenticated')::text, true);
  END IF;
EXCEPTION WHEN OTHERS THEN NULL; END $$;
SELECT set_config('role','authenticated', true);
DO $$ DECLARE v_a uuid; v_viejo text; v_nuevo text; v_r_viejo jsonb; v_r_nuevo jsonb; v_rot timestamptz; BEGIN
  IF coalesce(current_setting('probe.tj_ready',true),'')<>'1' THEN PERFORM set_config('probe.p661','N/A',false); RETURN; END IF;
  IF to_regprocedure('public.tarjeta_rotar_token()') IS NULL THEN
    PERFORM set_config('probe.p661','ROJO — RPC AUSENTE',false); RETURN; END IF;
  v_a := NULLIF(current_setting('probe.tj_a',true),'')::uuid;
  v_viejo := current_setting('probe.tj_tok_a',true);
  BEGIN
    PERFORM public.tarjeta_set_consentimiento(true);   -- P658 la habia apagado
    PERFORM public.tarjeta_rotar_token();
  EXCEPTION WHEN others THEN
    PERFORM set_config('probe.p661','FALLO (no se pudo rotar: '||SQLSTATE||' '||SQLERRM||')',false); RETURN; END;
  PERFORM set_config('role','none', true);
  SELECT ap.tarjeta_token, ap.tarjeta_token_rotado_at INTO v_nuevo, v_rot
    FROM public.asesores_perfil ap WHERE ap.id = v_a;
  v_r_viejo := public.tarjeta_publica_por_token(v_viejo);
  v_r_nuevo := public.tarjeta_publica_por_token(v_nuevo);
  PERFORM set_config('probe.p661', CASE
    WHEN v_nuevo IS NOT DISTINCT FROM v_viejo THEN 'ROJO (el token no cambio)'
    WHEN v_rot IS NULL          THEN 'FALLO (roto pero sin tarjeta_token_rotado_at)'
    WHEN v_r_viejo IS NOT NULL  THEN 'ROJO — EL TOKEN VIEJO SIGUE RESOLVIENDO: '||v_r_viejo::text
    WHEN v_r_nuevo IS NULL      THEN 'ROJO (el token NUEVO tampoco resuelve: la rotacion rompio la tarjeta)'
    ELSE 'OK (token nuevo resuelve, el viejo dejo de hacerlo, y quedo el sello de rotacion)' END, false);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p661','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;
SELECT set_config('role','none', true);

-- ############################################################################################
-- P662-P671 — foto de la tarjeta publica (mig 289)
-- ############################################################################################
-- Dos cosas distintas se miden aca.
--
-- (1) LA RPC `guardar_foto_publica_asesor` Y SU GUARD DE PATH. La policy de storage ya impide
-- SUBIR fuera del propio prefijo, pero la RPC escribe una COLUMNA de otra tabla: sin el guard, un
-- asesor podria registrar como suya la foto de otro y publicar una cara ajena en su tarjeta. El
-- path lo arma el cliente y no se confia en el (molde PA023 de la 274).
--
-- (2) QUE EL BUCKET SEA PRIVADO DE VERDAD. No se lee del catalogo que `public=false`: se INSERTA
-- una fila en storage.objects y se intenta LEERLA con cada rol. La leccion de la 284 es que el
-- catalogo dice quien tiene el permiso y no que pasa cuando se usa; y un bucket que se creyo
-- privado es exactamente el modo de falla que esta migracion vino a evitar, porque una URL de
-- objeto publico sobrevive a revocar el consentimiento.
-- P671 es el control positivo: sin el, los ceros de P669 y P670 tambien los daria un bucket al que
-- no puede entrar nadie, o una fila que nunca se inserto.
SELECT set_config('role','none', true);
DO $$
DECLARE v_gt uuid := NULLIF(current_setting('probe.co_gt',true),'')::uuid;
        v_d uuid; v_obj text;
BEGIN
  IF coalesce(current_setting('probe.tj_ready',true),'')<>'1' THEN
    PERFORM set_config('probe.fo_ready','0',false);
    PERFORM set_config('probe.fo_fx','ROJO — FIXTURE DE TARJETA AUSENTE (esto NO es un rechazo)',false); RETURN; END IF;
  IF to_regprocedure('public.guardar_foto_publica_asesor(text)') IS NULL THEN
    PERFORM set_config('probe.fo_ready','0',false);
    PERFORM set_config('probe.fo_fx','ROJO — MIG 289 AUSENTE (esto NO es un rechazo)',false); RETURN; END IF;

  -- (D) un perfil SIN ficha de asesor: es el sujeto de PA031, y no lo hay en el fixture de la 288.
  v_d := gen_random_uuid();
  INSERT INTO auth.users (id) VALUES (v_d);
  INSERT INTO public.perfiles (id, email, nombre_completo, rol, pais_id, activo)
    VALUES (v_d, 'p662.d@example.invalid', 'QA FOTO Sin Ficha', 'asesor_comercial', v_gt, true);

  -- Un objeto REAL en el bucket, a nombre del asesor feliz del fixture de la 288.
  v_obj := coalesce(current_setting('probe.tj_a',true),'') || '/qa-foto-p662.png';
  INSERT INTO storage.objects (bucket_id, name, owner)
    VALUES ('tarjetas-asesor', v_obj, NULLIF(current_setting('probe.tj_a',true),'')::uuid);

  PERFORM set_config('probe.fo_d', v_d::text, false);
  PERFORM set_config('probe.fo_obj', v_obj, false);
  PERFORM set_config('probe.fo_ready','1', false);
  PERFORM set_config('probe.fo_fx','OK (fixture foto: 1 perfil sin ficha + 1 objeto en tarjetas-asesor)', false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('probe.fo_ready','0',false);
  PERFORM set_config('probe.fo_fx','ROJO ('||SQLSTATE||' '||SQLERRM||')',false);
END $$;

-- P662 — sin ficha de asesor -> PA031. No es 42501: no es un problema de autoridad sino de que el
-- sujeto no existe como asesor.
SELECT set_config('request.jwt.claims', json_build_object('sub', current_setting('probe.fo_d',true), 'role','authenticated')::text, true);
SELECT set_config('role','authenticated', true);
DO $$ BEGIN
  IF coalesce(current_setting('probe.fo_ready',true),'')<>'1' THEN PERFORM set_config('probe.p662','N/A',false); RETURN; END IF;
  BEGIN
    PERFORM public.guardar_foto_publica_asesor(current_setting('probe.fo_d',true)||'/x.png');
    PERFORM set_config('probe.p662','ROJO (PERMITIO — alguien sin ficha guardo una foto publica)',false);
  EXCEPTION WHEN sqlstate 'PA031' THEN
    PERFORM set_config('probe.p662','OK (PA031 sin ficha de asesor)',false);
  WHEN others THEN PERFORM set_config('probe.p662','FALLO (esperaba PA031, vino '||SQLSTATE||': '||SQLERRM||')',false);
  END;
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p662','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;
SELECT set_config('role','none', true);

-- P663 — CONTROL POSITIVO de P664/P665/P666: el asesor SI guarda un path que empieza con su id, y
-- se verifica la FILA. Sin esto, los tres PA032 tambien los cumpliria una RPC que rechaza todo.
SELECT set_config('request.jwt.claims', json_build_object('sub', current_setting('probe.tj_a',true), 'role','authenticated')::text, true);
SELECT set_config('role','authenticated', true);
DO $$ DECLARE v_p text; v_esp text; BEGIN
  IF coalesce(current_setting('probe.fo_ready',true),'')<>'1' THEN PERFORM set_config('probe.p663','N/A',false); RETURN; END IF;
  v_esp := current_setting('probe.tj_a',true)||'/qa-foto-p663.png';
  BEGIN
    PERFORM public.guardar_foto_publica_asesor(v_esp);
  EXCEPTION WHEN others THEN
    PERFORM set_config('probe.p663','FALLO (el dueno no pudo guardar su propia foto: '||SQLSTATE||' '||SQLERRM||')',false); RETURN; END;
  PERFORM set_config('role','none', true);
  SELECT foto_publica_path INTO v_p FROM public.asesores_perfil WHERE id = NULLIF(current_setting('probe.tj_a',true),'')::uuid;
  PERFORM set_config('probe.p663', CASE WHEN v_p IS NOT DISTINCT FROM v_esp
    THEN 'OK (el asesor guardo su propia foto; se verifico la FILA)'
    ELSE 'ROJO (la RPC paso pero la columna quedo en '||COALESCE(v_p,'(nulo)')||')' END, false);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p663','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;
SELECT set_config('role','none', true);

-- P664 — EL GUARD: un path con el prefijo de OTRO asesor -> PA032. Es la probe que impide publicar
-- la cara ajena en la tarjeta propia.
SELECT set_config('request.jwt.claims', json_build_object('sub', current_setting('probe.tj_a',true), 'role','authenticated')::text, true);
SELECT set_config('role','authenticated', true);
DO $$ BEGIN
  IF coalesce(current_setting('probe.fo_ready',true),'')<>'1' THEN PERFORM set_config('probe.p664','N/A',false); RETURN; END IF;
  BEGIN
    PERFORM public.guardar_foto_publica_asesor(current_setting('probe.tj_b',true)||'/ajena.png');
    PERFORM set_config('probe.p664','ROJO (PERMITIO — registro como suya la foto de OTRO asesor)',false);
  EXCEPTION WHEN sqlstate 'PA032' THEN
    PERFORM set_config('probe.p664','OK (PA032 el path no empieza con el propio id)',false);
  WHEN others THEN PERFORM set_config('probe.p664','FALLO (esperaba PA032, vino '||SQLSTATE||': '||SQLERRM||')',false);
  END;
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p664','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;
SELECT set_config('role','none', true);

-- P665 — el prefijo propio pero SIN archivo ({id}/) -> PA032. Un path a medias no es un objeto.
SELECT set_config('request.jwt.claims', json_build_object('sub', current_setting('probe.tj_a',true), 'role','authenticated')::text, true);
SELECT set_config('role','authenticated', true);
DO $$ BEGIN
  IF coalesce(current_setting('probe.fo_ready',true),'')<>'1' THEN PERFORM set_config('probe.p665','N/A',false); RETURN; END IF;
  BEGIN
    PERFORM public.guardar_foto_publica_asesor(current_setting('probe.tj_a',true)||'/');
    PERFORM set_config('probe.p665','ROJO (PERMITIO — guardo un path sin archivo)',false);
  EXCEPTION WHEN sqlstate 'PA032' THEN
    PERFORM set_config('probe.p665','OK (PA032 path sin segundo segmento)',false);
  WHEN others THEN PERFORM set_config('probe.p665','FALLO (esperaba PA032, vino '||SQLSTATE||': '||SQLERRM||')',false);
  END;
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p665','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;
SELECT set_config('role','none', true);

-- P666 — prefijo propio pero con un TERCER segmento -> PA032. Ningun cliente nuestro produce eso.
SELECT set_config('request.jwt.claims', json_build_object('sub', current_setting('probe.tj_a',true), 'role','authenticated')::text, true);
SELECT set_config('role','authenticated', true);
DO $$ BEGIN
  IF coalesce(current_setting('probe.fo_ready',true),'')<>'1' THEN PERFORM set_config('probe.p666','N/A',false); RETURN; END IF;
  BEGIN
    PERFORM public.guardar_foto_publica_asesor(current_setting('probe.tj_a',true)||'/sub/dir.png');
    PERFORM set_config('probe.p666','ROJO (PERMITIO — guardo un path de tres segmentos)',false);
  EXCEPTION WHEN sqlstate 'PA032' THEN
    PERFORM set_config('probe.p666','OK (PA032 path con tercer segmento)',false);
  WHEN others THEN PERFORM set_config('probe.p666','FALLO (esperaba PA032, vino '||SQLSTATE||': '||SQLERRM||')',false);
  END;
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p666','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;
SELECT set_config('role','none', true);

-- P667 — NULL BORRA la foto. Quien puede publicar su cara tiene que poder despublicarla sin
-- depender de nadie: es el mismo derecho que enciende la tarjeta, no un caso de error.
SELECT set_config('request.jwt.claims', json_build_object('sub', current_setting('probe.tj_a',true), 'role','authenticated')::text, true);
SELECT set_config('role','authenticated', true);
DO $$ DECLARE v_p text; BEGIN
  IF coalesce(current_setting('probe.fo_ready',true),'')<>'1' THEN PERFORM set_config('probe.p667','N/A',false); RETURN; END IF;
  -- control del control: tiene que haber foto antes, si no borrarla no mide nada (la puso P663).
  PERFORM set_config('role','none', true);
  SELECT foto_publica_path INTO v_p FROM public.asesores_perfil WHERE id = NULLIF(current_setting('probe.tj_a',true),'')::uuid;
  PERFORM set_config('role','authenticated', true);
  IF v_p IS NULL THEN
    PERFORM set_config('probe.p667','FALLO (no habia foto que borrar: borrarla no mide nada)',false); RETURN; END IF;
  BEGIN
    PERFORM public.guardar_foto_publica_asesor(NULL);
  EXCEPTION WHEN others THEN
    PERFORM set_config('probe.p667','FALLO (no pudo borrar su foto: '||SQLSTATE||' '||SQLERRM||')',false); RETURN; END;
  PERFORM set_config('role','none', true);
  SELECT foto_publica_path INTO v_p FROM public.asesores_perfil WHERE id = NULLIF(current_setting('probe.tj_a',true),'')::uuid;
  PERFORM set_config('probe.p667', CASE WHEN v_p IS NULL
    THEN 'OK (NULL borro la foto; se verifico la FILA)'
    ELSE 'ROJO (la RPC paso pero la columna quedo en '||v_p||')' END, false);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p667','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;
SELECT set_config('role','none', true);

-- P668 — `anon` no ejecuta la RPC. EJERCITADO, no leido del catalogo: la leccion de la 284 es que
-- tener el permiso y poder usarlo son dos preguntas distintas.
SELECT set_config('request.jwt.claims', json_build_object('role','anon')::text, true);
SELECT set_config('role','anon', true);
DO $$ BEGIN
  IF coalesce(current_setting('probe.fo_ready',true),'')<>'1' THEN PERFORM set_config('probe.p668','N/A',false); RETURN; END IF;
  BEGIN
    PERFORM public.guardar_foto_publica_asesor('x/y.png');
    PERFORM set_config('probe.p668','ROJO (PERMITIO — anon ejecuto guardar_foto_publica_asesor)',false);
  EXCEPTION WHEN insufficient_privilege THEN
    PERFORM set_config('probe.p668','OK (42501 anon sin EXECUTE)',false);
  WHEN others THEN PERFORM set_config('probe.p668','FALLO (esperaba 42501, vino '||SQLSTATE||': '||SQLERRM||')',false);
  END;
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p668','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;
SELECT set_config('role','none', true);

-- P669 — EL BUCKET ES PRIVADO: `anon` NO ve el objeto. Es la probe que sostiene toda la decision de
-- la 289 — con un bucket publico la URL del objeto responderia para siempre y apagar el
-- consentimiento no la mataria.
SELECT set_config('request.jwt.claims', json_build_object('role','anon')::text, true);
SELECT set_config('role','anon', true);
DO $$ DECLARE v_n int; BEGIN
  IF coalesce(current_setting('probe.fo_ready',true),'')<>'1' THEN PERFORM set_config('probe.p669','N/A',false); RETURN; END IF;
  BEGIN
    SELECT count(*) INTO v_n FROM storage.objects
     WHERE bucket_id='tarjetas-asesor' AND name = current_setting('probe.fo_obj',true);
    PERFORM set_config('probe.p669', CASE WHEN COALESCE(v_n,0) = 0
      THEN 'OK (anon no ve el objeto del bucket privado)'
      ELSE 'ROJO (PERMITIO — anon leyo '||v_n||' objeto(s) de tarjetas-asesor)' END, false);
  EXCEPTION WHEN insufficient_privilege THEN
    PERFORM set_config('probe.p669','OK (42501 anon ni siquiera puede consultar storage.objects)',false);
  WHEN others THEN PERFORM set_config('probe.p669','FALLO ('||SQLSTATE||': '||SQLERRM||')',false);
  END;
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p669','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;
SELECT set_config('role','none', true);

-- P670 — otro ASESOR autenticado tampoco ve la foto ajena. El SELECT de authenticated existe SOLO
-- para que cada uno vea la suya; si alcanzara al bucket entero seria el molde fotos-medicos otra vez.
SELECT set_config('request.jwt.claims', json_build_object('sub', current_setting('probe.co_ase1',true), 'role','authenticated')::text, true);
SELECT set_config('role','authenticated', true);
DO $$ DECLARE v_n int; BEGIN
  IF coalesce(current_setting('probe.fo_ready',true),'')<>'1' THEN PERFORM set_config('probe.p670','N/A',false); RETURN; END IF;
  BEGIN
    SELECT count(*) INTO v_n FROM storage.objects
     WHERE bucket_id='tarjetas-asesor' AND name = current_setting('probe.fo_obj',true);
    PERFORM set_config('probe.p670', CASE WHEN COALESCE(v_n,0) = 0
      THEN 'OK (otro asesor no ve la foto ajena)'
      ELSE 'ROJO (PERMITIO — un asesor leyo la foto de otro)' END, false);
  EXCEPTION WHEN insufficient_privilege THEN
    PERFORM set_config('probe.p670','OK (42501)',false);
  WHEN others THEN PERFORM set_config('probe.p670','FALLO ('||SQLSTATE||': '||SQLERRM||')',false);
  END;
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p670','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;
SELECT set_config('role','none', true);

-- P671 — CONTROL POSITIVO de P669/P670: el DUENO SI ve su objeto. Sin esta, los dos ceros de arriba
-- los daria igual un bucket inaccesible para todos, o una fila que nunca se llego a insertar.
SELECT set_config('request.jwt.claims', json_build_object('sub', current_setting('probe.tj_a',true), 'role','authenticated')::text, true);
SELECT set_config('role','authenticated', true);
DO $$ DECLARE v_n int; BEGIN
  IF coalesce(current_setting('probe.fo_ready',true),'')<>'1' THEN PERFORM set_config('probe.p671','N/A',false); RETURN; END IF;
  BEGIN
    SELECT count(*) INTO v_n FROM storage.objects
     WHERE bucket_id='tarjetas-asesor' AND name = current_setting('probe.fo_obj',true);
    PERFORM set_config('probe.p671', CASE WHEN COALESCE(v_n,0) = 1
      THEN 'OK (el dueno SI ve su foto: P669/P670 miden algo)'
      ELSE 'ROJO (el dueno no ve su propia foto: los ceros de P669/P670 no prueban nada)' END, false);
  EXCEPTION WHEN others THEN
    PERFORM set_config('probe.p671','FALLO ('||SQLSTATE||': '||SQLERRM||')',false);
  END;
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p671','FALLO ('||SQLSTATE||' '||SQLERRM||')',false); END $$;
SELECT set_config('role','none', true);

-- ############################################################################################
-- P672-P677 — validacion de fecha_ingreso y celular en guardar_asesor_perfil (mig 290)
-- ############################################################################################
-- QUE SE MIDE. Dos guards nuevos de la RPC, PA033 (fecha_ingreso fuera de rango) y PA034 (celular
-- con menos de 7 o mas de 15 digitos). Se ejercita la RPC como el admin de pais, que es el unico
-- camino real: el formulario valida lo mismo antes de llamar, pero el formulario no es la barrera
-- —la escritura tambien llega por otras pantallas, scripts o la API directa— y es justo por eso
-- que estos codigos son alcanzables.
--
-- POR QUE EL LIMITE SUPERIOR DE LA FECHA NO ES UN CHECK. Depende de CURRENT_DATE, y un CHECK con
-- una expresion no inmutable no se puede crear. El celular SI tiene CHECK estructural
-- (`asesores_perfil_celular_formato`) ADEMAS del guard: la RPC atrapa el caso con el errcode que el
-- front sabe pintar, y el CHECK atrapa cualquier INSERT que no pase por la RPC. P677 mide eso.
--
-- LOS CONTROLES POSITIVOS NO SON DECORACION. Sin P674 y P676, los cinco rechazos de arriba tambien
-- los daria una RPC que rechaza TODO — por ejemplo si el gate de pais fallara antes de llegar a la
-- validacion. Que un valor bueno pase es lo que prueba que lo que se esta midiendo es el guard.
--
-- El sujeto es una ficha REAL de GT y todo lo que se escribe muere con el ROLLBACK del harness.
SELECT set_config('role','none', true);
DO $$
DECLARE v_gt uuid := 'cbbbbe6d-59fe-4cf2-91ee-3e31ba1d5909';
        v_adm uuid; v_ase uuid; v_cod text; v_err text;
BEGIN
  IF to_regprocedure('public.guardar_asesor_perfil(uuid,text,uuid,text,text,text,text,date,text,boolean)') IS NULL THEN
    PERFORM set_config('probe.va_ready','0',false);
    PERFORM set_config('probe.va_fx','ROJO — RPC AUSENTE (esto NO es un rechazo)',false); RETURN; END IF;

  SELECT id INTO v_adm FROM public.perfiles WHERE email='adminpais.qa@ezpayconnect.com';
  SELECT ap.id, ap.codigo_asesor INTO v_ase, v_cod
    FROM public.asesores_perfil ap JOIN public.perfiles p ON p.id = ap.id
   WHERE ap.pais_id = v_gt AND p.rol IN ('asesor_comercial','supervisor_comercial')
   ORDER BY ap.id LIMIT 1;
  IF v_adm IS NULL OR v_ase IS NULL THEN
    PERFORM set_config('probe.va_ready','0',false);
    PERFORM set_config('probe.va_fx','ROJO — FIXTURE AUSENTE (admin_pais GT o ficha de GT)',false); RETURN; END IF;

  PERFORM set_config('probe.va_adm', v_adm::text, false);
  PERFORM set_config('probe.va_ase', v_ase::text, false);
  PERFORM set_config('probe.va_cod', v_cod, false);
  PERFORM set_config('probe.va_ready','1', false);
  PERFORM set_config('probe.va_fx','OK (fixture validacion: admin_pais GT + ficha real de GT '||v_cod||')', false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('probe.va_ready','0',false);
  PERFORM set_config('probe.va_fx','ROJO ('||SQLSTATE||' '||SQLERRM||')',false);
END $$;

-- Un solo bloque para los seis casos: comparten sujeto y sesion, y separarlos obligaria a repetir
-- la impersonacion seis veces. Cada caso tiene su propio handler, asi que uno que reviente no
-- arrastra a los otros.
DO $$
DECLARE v_gt uuid := 'cbbbbe6d-59fe-4cf2-91ee-3e31ba1d5909';
        v_ase uuid := NULLIF(current_setting('probe.va_ase',true),'')::uuid;
        v_cod text := coalesce(current_setting('probe.va_cod',true),'QA-VA');
        v_err text;
BEGIN
  IF coalesce(current_setting('probe.va_ready',true),'')<>'1' THEN
    PERFORM set_config('probe.p672','N/A (fixture ausente)',false);
    PERFORM set_config('probe.p673','N/A (fixture ausente)',false);
    PERFORM set_config('probe.p674','N/A (fixture ausente)',false);
    PERFORM set_config('probe.p675','N/A (fixture ausente)',false);
    PERFORM set_config('probe.p676','N/A (fixture ausente)',false);
    PERFORM set_config('probe.p677','N/A (fixture ausente)',false);
    RETURN; END IF;

  PERFORM set_config('request.jwt.claims',
    json_build_object('sub', current_setting('probe.va_adm',true), 'role','authenticated')::text, true);
  PERFORM set_config('role','authenticated', true);

  -- P672 — fecha absurda hacia el FUTURO. Es el caso que Oscar metio a mano el 7-sep: la pantalla
  -- acepto '2227-01-01' y quedo guardado.
  BEGIN
    PERFORM public.guardar_asesor_perfil(v_ase, v_cod, v_gt, NULL,NULL,NULL,NULL, DATE '2227-01-01');
    v_err := NULL;
  EXCEPTION WHEN OTHERS THEN v_err := SQLSTATE; END;
  PERFORM set_config('probe.p672', CASE
    WHEN v_err = 'PA033' THEN 'OK (PA033)'
    WHEN v_err IS NULL   THEN 'ROJO (PERMITIO fecha_ingreso 2227-01-01)'
    ELSE 'ROJO (rechazo con '||v_err||', se esperaba PA033)' END, false);

  -- P673 — fecha absurda hacia el PASADO. La negativa por el otro extremo: un rango que solo corta
  -- de un lado deja la mitad del agujero abierto.
  BEGIN
    PERFORM public.guardar_asesor_perfil(v_ase, v_cod, v_gt, NULL,NULL,NULL,NULL, DATE '1999-12-31');
    v_err := NULL;
  EXCEPTION WHEN OTHERS THEN v_err := SQLSTATE; END;
  PERFORM set_config('probe.p673', CASE
    WHEN v_err = 'PA033' THEN 'OK (PA033)'
    WHEN v_err IS NULL   THEN 'ROJO (PERMITIO fecha_ingreso 1999-12-31)'
    ELSE 'ROJO (rechazo con '||v_err||', se esperaba PA033)' END, false);

  -- P674 — CONTROL POSITIVO de la fecha: hoy tiene que entrar.
  BEGIN
    PERFORM public.guardar_asesor_perfil(v_ase, v_cod, v_gt, NULL,NULL,NULL,NULL, CURRENT_DATE);
    v_err := NULL;
  EXCEPTION WHEN OTHERS THEN v_err := SQLSTATE||' '||SQLERRM; END;
  PERFORM set_config('probe.p674', CASE WHEN v_err IS NULL
    THEN 'OK (CURRENT_DATE entra: P672/P673 miden el rango y no un rechazo total)'
    ELSE 'ROJO (rechazo una fecha VALIDA: '||v_err||')' END, false);

  -- P675 — celular sin un solo digito.
  BEGIN
    PERFORM public.guardar_asesor_perfil(v_ase, v_cod, v_gt, NULL,NULL,NULL, 'abc', NULL);
    v_err := NULL;
  EXCEPTION WHEN OTHERS THEN v_err := SQLSTATE; END;
  PERFORM set_config('probe.p675', CASE
    WHEN v_err = 'PA034' THEN 'OK (PA034)'
    WHEN v_err IS NULL   THEN 'ROJO (PERMITIO celular "abc")'
    ELSE 'ROJO (rechazo con '||v_err||', se esperaba PA034)' END, false);

  -- P676 — celular con digitos pero DEMASIADO CORTO. Distinto de P675: 'abc' tiene cero digitos y
  -- lo cortaria hasta un `IS NOT NULL` mal hecho; '123' obliga a que el conteo exista de verdad.
  BEGIN
    PERFORM public.guardar_asesor_perfil(v_ase, v_cod, v_gt, NULL,NULL,NULL, '123', NULL);
    v_err := NULL;
  EXCEPTION WHEN OTHERS THEN v_err := SQLSTATE; END;
  PERFORM set_config('probe.p676', CASE
    WHEN v_err = 'PA034' THEN 'OK (PA034)'
    WHEN v_err IS NULL   THEN 'ROJO (PERMITIO celular "123", 3 digitos)'
    ELSE 'ROJO (rechazo con '||v_err||', se esperaba PA034)' END, false);

  -- P677 — CONTROL POSITIVO del celular: el formato real que usa el modulo, con prefijo y guion,
  -- son 11 digitos y tiene que entrar. Sin esta, los dos PA034 de arriba tambien los daria una
  -- validacion que rechaza cualquier celular.
  BEGIN
    PERFORM public.guardar_asesor_perfil(v_ase, v_cod, v_gt, NULL,NULL,NULL, '+502 5500-0100', NULL);
    v_err := NULL;
  EXCEPTION WHEN OTHERS THEN v_err := SQLSTATE||' '||SQLERRM; END;
  PERFORM set_config('probe.p677', CASE WHEN v_err IS NULL
    THEN 'OK (+502 5500-0100 entra: 11 digitos, y el CHECK de la tabla tampoco lo bloquea)'
    ELSE 'ROJO (rechazo un celular VALIDO: '||v_err||')' END, false);

  PERFORM set_config('role','none', true);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('role','none', true);
  PERFORM set_config('probe.p672','FALLO ('||SQLSTATE||' '||SQLERRM||')',false);
END $$;
SELECT set_config('role','none', true);

-- ============================================================
-- MIG 291 · ninguna cita se completa sin nota + contexto de la visita (P678-P685)
-- ============================================================
-- Medido el 13-sep contra prod ANTES de la migracion: de 1 cita 'completada', 1 sin nota. El boton
-- "Finalizar" de ConsultaPage solo cambiaba citas.estado y nunca guardaba el SOAP.
--
-- POR QUE P678 ES LA PROBE QUE IMPORTA. El pedido original ponia el gate dentro de
-- actualizar_estado_cita, pero NINGUNA pantalla usa esa RPC: useCitas.updateCita y
-- useMedicoCitas.updateCitaEstado hacen UPDATE DIRECTO a citas por PostgREST, y la policy
-- citas_update_medico lo permite sin condicion. P679 (la RPC) habria dado verde con el agujero
-- real intacto. Por eso el gate es un trigger y P678 ejercita el camino directo.
--
-- LOS TRES CONTROLES NEGATIVOS NO SON DECORACION. P680 (con nota pasa), P681 (cancelada pasa sin
-- nota) y P682 (una cita ya completada no se re-bloquea) son lo que distingue un gate de un
-- trigger que rompe toda escritura sobre citas. Sin ellos, P678/P679 tambien darian verde con un
-- trigger que lanza siempre.
--
-- P685 mide la decision de alcance: auditoria_ia hoy la ve SOLO su autor (policy `medico_id =
-- auth.uid()`). obtener_contexto_visita es SECURITY DEFINER, asi que si devolviera las sugerencias
-- con el mismo scope que la nota estaria ampliando el acceso a texto de IA sobre datos medicos al
-- super_admin y al admin de clinica. P685 prueba que NO lo hace.
--
-- Todo lo que se escribe acá muere con el ROLLBACK del harness.
DO $$
DECLARE v_pac bigint; v_med uuid; v_clin uuid; v_otro uuid; v_sa uuid;
        v_sin bigint; v_con bigint; v_can bigint; v_ya bigint; v_nota integer;
BEGIN
  SELECT c.paciente_id, c.medico_id, c.clinica_id INTO v_pac, v_med, v_clin
    FROM public.citas c WHERE c.medico_id IS NOT NULL ORDER BY c.id LIMIT 1;
  SELECT id INTO v_sa FROM public.perfiles WHERE rol='super_admin' ORDER BY id LIMIT 1;
  -- medico SIN cita con ese paciente: mismo idioma que probe.np_ajeno mas arriba
  SELECT m.id INTO v_otro FROM public.perfiles m
   WHERE m.rol='medico' AND m.id <> v_med
     AND NOT EXISTS (SELECT 1 FROM public.citas c2 WHERE c2.medico_id=m.id AND c2.paciente_id=v_pac)
   ORDER BY m.id LIMIT 1;

  IF v_pac IS NULL OR v_med IS NULL OR v_sa IS NULL OR v_otro IS NULL THEN
    PERFORM set_config('probe.nc_ready','0',false);
    PERFORM set_config('probe.nc_fx','ROJO — FIXTURE AUSENTE (cita con medico, super_admin o medico ajeno)',false);
    RETURN; END IF;

  -- Cuatro citas nuevas: separadas a proposito, para que el veredicto de una no dependa del
  -- estado en que la dejo la anterior.
  INSERT INTO public.citas (paciente_id, medico_id, clinica_id, fecha, hora_inicio, hora_fin, estado)
  VALUES (v_pac, v_med, v_clin, CURRENT_DATE, '09:00', '09:30', 'en_curso') RETURNING id INTO v_sin;
  INSERT INTO public.citas (paciente_id, medico_id, clinica_id, fecha, hora_inicio, hora_fin, estado)
  VALUES (v_pac, v_med, v_clin, CURRENT_DATE, '10:00', '10:30', 'en_curso') RETURNING id INTO v_con;
  INSERT INTO public.citas (paciente_id, medico_id, clinica_id, fecha, hora_inicio, hora_fin, estado)
  VALUES (v_pac, v_med, v_clin, CURRENT_DATE, '11:00', '11:30', 'en_curso') RETURNING id INTO v_can;
  -- Esta nace completada por INSERT: el trigger es BEFORE UPDATE, asi que no dispara al crearla.
  INSERT INTO public.citas (paciente_id, medico_id, clinica_id, fecha, hora_inicio, hora_fin, estado)
  VALUES (v_pac, v_med, v_clin, CURRENT_DATE, '12:00', '12:30', 'completada') RETURNING id INTO v_ya;

  -- La unica con nota, y con una sugerencia de IA colgada de esa nota.
  INSERT INTO public.expediente_notas (cita_id, paciente_id, medico_id, subjetivo)
  VALUES (v_con, v_pac, v_med, 'probe 291') RETURNING id INTO v_nota;
  INSERT INTO public.auditoria_ia (medico_id, paciente_id, consulta_id, prompt, respuesta_ia)
  VALUES (v_med, v_pac::int, v_nota, 'prompt de prueba', 'respuesta de prueba');

  PERFORM set_config('probe.nc_med',  v_med::text,  false);
  PERFORM set_config('probe.nc_otro', v_otro::text, false);
  PERFORM set_config('probe.nc_sa',   v_sa::text,   false);
  PERFORM set_config('probe.nc_sin',  v_sin::text,  false);
  PERFORM set_config('probe.nc_con',  v_con::text,  false);
  PERFORM set_config('probe.nc_can',  v_can::text,  false);
  PERFORM set_config('probe.nc_ya',   v_ya::text,   false);
  PERFORM set_config('probe.nc_ready','1', false);
  PERFORM set_config('probe.nc_fx','OK (4 citas + 1 nota + 1 fila de IA sobre paciente '||v_pac||')', false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('probe.nc_ready','0',false);
  PERFORM set_config('probe.nc_fx','ROJO ('||SQLSTATE||' '||SQLERRM||')',false);
END $$;

-- Bloque 1: lo que hace el MEDICO DUEÑO de la cita. Es el camino real de las dos pantallas.
DO $$
DECLARE v_sin bigint := NULLIF(current_setting('probe.nc_sin',true),'')::bigint;
        v_con bigint := NULLIF(current_setting('probe.nc_con',true),'')::bigint;
        v_can bigint := NULLIF(current_setting('probe.nc_can',true),'')::bigint;
        v_ya  bigint := NULLIF(current_setting('probe.nc_ya', true),'')::bigint;
        v_err text; v_j jsonb; v_n int;
BEGIN
  IF coalesce(current_setting('probe.nc_ready',true),'')<>'1' THEN
    PERFORM set_config('probe.p678','N/A (fixture ausente)',false);
    PERFORM set_config('probe.p679','N/A (fixture ausente)',false);
    PERFORM set_config('probe.p680','N/A (fixture ausente)',false);
    PERFORM set_config('probe.p681','N/A (fixture ausente)',false);
    PERFORM set_config('probe.p682','N/A (fixture ausente)',false);
    PERFORM set_config('probe.p683','N/A (fixture ausente)',false);
    RETURN; END IF;

  PERFORM set_config('request.jwt.claims',
    json_build_object('sub', current_setting('probe.nc_med',true), 'role','authenticated')::text, true);
  PERFORM set_config('role','authenticated', true);

  -- P678 — UPDATE DIRECTO a 'completada' sin nota. El agujero que el pedido original no cubria.
  BEGIN
    UPDATE public.citas SET estado='completada' WHERE id = v_sin;
    v_err := NULL;
  EXCEPTION WHEN OTHERS THEN v_err := SQLSTATE; END;
  PERFORM set_config('probe.p678', CASE
    WHEN v_err = 'PE001' THEN 'OK (PE001)'
    WHEN v_err IS NULL   THEN 'ROJO (COMPLETO por UPDATE directo una cita SIN nota)'
    ELSE 'ROJO (rechazo con '||v_err||', se esperaba PE001)' END, false);

  -- P679 — la misma negativa por la RPC. Hereda el gate del trigger, no lo repite.
  BEGIN
    PERFORM public.actualizar_estado_cita(v_sin, 'completada');
    v_err := NULL;
  EXCEPTION WHEN OTHERS THEN v_err := SQLSTATE; END;
  PERFORM set_config('probe.p679', CASE
    WHEN v_err = 'PE001' THEN 'OK (PE001)'
    WHEN v_err IS NULL   THEN 'ROJO (la RPC COMPLETO una cita SIN nota)'
    ELSE 'ROJO (rechazo con '||v_err||', se esperaba PE001)' END, false);

  -- P680 — CONTROL POSITIVO: con nota, completar tiene que pasar.
  BEGIN
    UPDATE public.citas SET estado='completada' WHERE id = v_con;
    v_err := NULL;
  EXCEPTION WHEN OTHERS THEN v_err := SQLSTATE||' '||SQLERRM; END;
  PERFORM set_config('probe.p680', CASE WHEN v_err IS NULL
    THEN 'OK (con nota completa: P678/P679 miden la nota y no un bloqueo total)'
    ELSE 'ROJO (bloqueo una cita CON nota: '||v_err||')' END, false);

  -- P681 — CONTROL NEGATIVO: los otros estados no se tocan. Cancelar sin nota sigue siendo valido.
  BEGIN
    UPDATE public.citas SET estado='cancelada' WHERE id = v_can;
    v_err := NULL;
  EXCEPTION WHEN OTHERS THEN v_err := SQLSTATE||' '||SQLERRM; END;
  PERFORM set_config('probe.p681', CASE WHEN v_err IS NULL
    THEN 'OK (cancelar sin nota pasa: el gate es solo la transicion A completada)'
    ELSE 'ROJO (el gate se comio otro estado: '||v_err||')' END, false);

  -- P682 — una cita YA completada que se vuelve a tocar no se re-bloquea. Sin la mitad
  -- `OLD.estado IS DISTINCT FROM` del WHEN, borrar la nota dejaria la fila congelada para siempre.
  BEGIN
    UPDATE public.citas SET estado='completada' WHERE id = v_ya;
    v_err := NULL;
  EXCEPTION WHEN OTHERS THEN v_err := SQLSTATE||' '||SQLERRM; END;
  PERFORM set_config('probe.p682', CASE WHEN v_err IS NULL
    THEN 'OK (re-tocar una completada no dispara el trigger)'
    ELSE 'ROJO (bloqueo una cita que YA estaba completada: '||v_err||')' END, false);

  -- P683 — el contexto de la visita para el medico AUTOR: nota + su sugerencia de IA.
  IF to_regprocedure('public.obtener_contexto_visita(bigint)') IS NULL THEN
    PERFORM set_config('probe.p683','ROJO — RPC AUSENTE (esto NO es un rechazo)',false);
  ELSE
    BEGIN
      v_j := public.obtener_contexto_visita(v_con);
      v_n := jsonb_array_length(v_j->'sugerencias_ia');
      PERFORM set_config('probe.p683', CASE
        WHEN v_j->'nota' IS NULL OR v_j->'nota' = 'null'::jsonb
          THEN 'ROJO (devolvio la visita SIN la nota)'
        WHEN v_n <> 1 THEN 'ROJO (sugerencias_ia='||v_n||', se esperaba 1)'
        ELSE 'OK (nota + 1 sugerencia de IA en un solo jsonb)' END, false);
    EXCEPTION WHEN OTHERS THEN
      PERFORM set_config('probe.p683','ROJO ('||SQLSTATE||' '||SQLERRM||')',false);
    END;
  END IF;

  PERFORM set_config('role','none', true);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('role','none', true);
  PERFORM set_config('probe.p678','FALLO ('||SQLSTATE||' '||SQLERRM||')',false);
END $$;
SELECT set_config('role','none', true);

-- Bloque 2: un medico SIN relacion con el paciente. La negativa del gate de lectura.
DO $$
DECLARE v_con bigint := NULLIF(current_setting('probe.nc_con',true),'')::bigint; v_j jsonb; v_err text;
BEGIN
  IF coalesce(current_setting('probe.nc_ready',true),'')<>'1' THEN
    PERFORM set_config('probe.p684','N/A (fixture ausente)',false); RETURN; END IF;
  IF to_regprocedure('public.obtener_contexto_visita(bigint)') IS NULL THEN
    PERFORM set_config('probe.p684','ROJO — RPC AUSENTE (esto NO es un rechazo)',false); RETURN; END IF;

  PERFORM set_config('request.jwt.claims',
    json_build_object('sub', current_setting('probe.nc_otro',true), 'role','authenticated')::text, true);
  PERFORM set_config('role','authenticated', true);
  BEGIN
    v_j := public.obtener_contexto_visita(v_con);
    v_err := NULL;
  EXCEPTION WHEN OTHERS THEN v_err := SQLSTATE; END;
  PERFORM set_config('probe.p684', CASE
    WHEN v_err = '42501' THEN 'OK (42501 no_autorizado)'
    WHEN v_err IS NULL   THEN 'ROJO (un medico ajeno LEYO la visita)'
    ELSE 'ROJO (rechazo con '||v_err||', se esperaba 42501)' END, false);
  PERFORM set_config('role','none', true);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('role','none', true);
  PERFORM set_config('probe.p684','FALLO ('||SQLSTATE||' '||SQLERRM||')',false);
END $$;
SELECT set_config('role','none', true);

-- Bloque 3: el super_admin. Pasa el gate de la NOTA y aun asi no ve la IA ajena.
DO $$
DECLARE v_con bigint := NULLIF(current_setting('probe.nc_con',true),'')::bigint; v_j jsonb; v_n int;
BEGIN
  IF coalesce(current_setting('probe.nc_ready',true),'')<>'1' THEN
    PERFORM set_config('probe.p685','N/A (fixture ausente)',false); RETURN; END IF;
  IF to_regprocedure('public.obtener_contexto_visita(bigint)') IS NULL THEN
    PERFORM set_config('probe.p685','ROJO — RPC AUSENTE (esto NO es un rechazo)',false); RETURN; END IF;

  PERFORM set_config('request.jwt.claims',
    json_build_object('sub', current_setting('probe.nc_sa',true), 'role','authenticated')::text, true);
  PERFORM set_config('role','authenticated', true);
  v_j := public.obtener_contexto_visita(v_con);
  v_n := jsonb_array_length(v_j->'sugerencias_ia');
  PERFORM set_config('probe.p685', CASE
    WHEN v_j->'nota' IS NULL OR v_j->'nota' = 'null'::jsonb
      THEN 'ROJO (el super_admin no vio la nota, que SI le corresponde)'
    WHEN v_n <> 0 THEN 'ROJO (vio '||v_n||' sugerencia(s) de IA ajenas — la RPC AMPLIO el acceso)'
    ELSE 'OK (ve la nota, sugerencias_ia vacio: la RPC no amplia auditoria_ia)' END, false);
  PERFORM set_config('role','none', true);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('role','none', true);
  PERFORM set_config('probe.p685','FALLO ('||SQLSTATE||' '||SQLERRM||')',false);
END $$;
SELECT set_config('role','none', true);

-- ============================================================
-- MIG 294 · medicos: anon cerrado y scope por pais del proveedor (P686-P693)
-- ============================================================
-- Hallazgo medido el 16-sep: tres policies de SELECT con USING(true) —medicos_select (PUBLIC),
-- "Allow anon read medicos" y "Allow authenticated read medicos"— que NO estaban en el repo. Al ser
-- PERMISSIVE se combinan con OR y anulaban el scoping por pais de las versionadas. Cualquier
-- authenticated leia todos los medicos de todos los paises; anon leia 7 columnas por el GRANT de la 073.
--
-- P689 ES LA PROBE QUE IMPIDE "ARREGLARLO" ROMPIENDO EL PRODUCTO: si se cierra de mas, el proveedor
-- deja de ver los medicos de SU pais y VisitadorDetallePage se queda sin nombres. Las tres de
-- regresion (P691-P693) son lo mismo para paciente, medico y admin_pais: el DROP de tres policies es
-- exactamente el movimiento que en la mig 284 rompio prod.
--
-- El medico "de otro pais" se fabrica moviendo a SV uno de los 8 que hoy tienen pais NULL: no se
-- puede INSERT en medicos sin una fila en perfiles (FK medicos_id_perfiles_fkey). Muere con el ROLLBACK.
SELECT set_config('role','none', true);
DO $$
DECLARE v_gt uuid := 'cbbbbe6d-59fe-4cf2-91ee-3e31ba1d5909';
        v_sv uuid; v_prov uuid; v_med uuid; v_pac uuid; v_adm uuid; v_ajeno uuid; n int;
BEGIN
  SELECT id INTO v_sv FROM public.configuracion_pais WHERE codigo='SV';
  SELECT id INTO v_prov FROM public.cuentas_proveedor WHERE email='farmacianueva1@test.com';
  SELECT id INTO v_med  FROM public.medicos WHERE pais_id = v_gt ORDER BY id LIMIT 1;
  SELECT auth_user_id INTO v_pac FROM public.pacientes
   WHERE auth_user_id IS NOT NULL AND pais_id = v_gt LIMIT 1;
  SELECT id INTO v_adm FROM public.perfiles WHERE rol='admin_pais' AND pais_id = v_gt LIMIT 1;
  SELECT id INTO v_ajeno FROM public.medicos WHERE pais_id IS NULL ORDER BY id LIMIT 1;

  IF v_sv IS NULL OR v_prov IS NULL OR v_med IS NULL OR v_pac IS NULL OR v_adm IS NULL OR v_ajeno IS NULL THEN
    PERFORM set_config('probe.pm_ready','0',false);
    PERFORM set_config('probe.pm_fx','ROJO — FIXTURE AUSENTE (pais SV, proveedor, medico GT, paciente GT, admin_pais o medico sin pais)',false);
    RETURN; END IF;

  UPDATE public.medicos SET pais_id = v_sv WHERE id = v_ajeno;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN
    PERFORM set_config('probe.pm_ready','0',false);
    PERFORM set_config('probe.pm_fx','ROJO — no se pudo mover el medico ajeno a SV',false); RETURN; END IF;

  PERFORM set_config('probe.pm_prov',  v_prov::text,  false);
  PERFORM set_config('probe.pm_med',   v_med::text,   false);
  PERFORM set_config('probe.pm_pac',   v_pac::text,   false);
  PERFORM set_config('probe.pm_adm',   v_adm::text,   false);
  PERFORM set_config('probe.pm_ajeno', v_ajeno::text, false);
  PERFORM set_config('probe.pm_ready','1', false);
  PERFORM set_config('probe.pm_fx','OK (proveedor GT + medico GT + paciente GT + admin_pais GT + 1 medico movido a SV)', false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('probe.pm_ready','0',false);
  PERFORM set_config('probe.pm_fx','ROJO ('||SQLSTATE||' '||SQLERRM||')',false);
END $$;

-- P686 — anon. Despues de la 294 no tiene ni columnas ni policy: tiene que dar 42501, o 0 filas si
-- alguna via le dejara llegar a la RLS. "Ve filas" es el estado que esta migracion cierra.
DO $$
DECLARE n bigint;
BEGIN
  BEGIN
    PERFORM set_config('request.jwt.claims','{"role":"anon"}', true);
    PERFORM set_config('role','anon', true);
    SELECT count(*) INTO n FROM public.medicos;
    PERFORM set_config('role','none', true);
    PERFORM set_config('probe.p686', CASE WHEN n = 0 THEN 'OK (anon ve 0 filas)'
      ELSE 'ROJO (anon LEE '||n||' medicos sin sesion)' END, false);
  EXCEPTION WHEN insufficient_privilege THEN
    PERFORM set_config('role','none', true);
    PERFORM set_config('probe.p686','OK (42501: anon sin privilegio sobre medicos)',false);
  WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    PERFORM set_config('probe.p686','FALLO ('||SQLSTATE||' '||SQLERRM||')',false);
  END;
END $$;
SELECT set_config('role','none', true);

-- P687 — authenticated SIN identidad: un uuid que no es medico, ni paciente, ni proveedor, ni admin.
-- Mide que la policy abierta ya no esta: antes veia TODO.
DO $$
DECLARE n bigint;
BEGIN
  BEGIN
    PERFORM set_config('request.jwt.claims',
      json_build_object('sub', gen_random_uuid()::text, 'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    SELECT count(*) INTO n FROM public.medicos;
    PERFORM set_config('role','none', true);
    PERFORM set_config('probe.p687', CASE WHEN n = 0 THEN 'OK (authenticated sin identidad ve 0)'
      ELSE 'ROJO (un authenticated cualquiera ve '||n||' medicos)' END, false);
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    PERFORM set_config('probe.p687','FALLO ('||SQLSTATE||' '||SQLERRM||')',false);
  END;
END $$;
SELECT set_config('role','none', true);

-- P688/P689/P690 — el proveedor: no cruza de pais, si ve el suyo, y no ve los que no tienen pais.
DO $$
DECLARE v_ajeno uuid := NULLIF(current_setting('probe.pm_ajeno',true),'')::uuid;
        v_gt uuid := 'cbbbbe6d-59fe-4cf2-91ee-3e31ba1d5909'; n bigint; n_nulos bigint;
BEGIN
  IF coalesce(current_setting('probe.pm_ready',true),'')<>'1' THEN
    PERFORM set_config('probe.p688','N/A (fixture ausente)',false);
    PERFORM set_config('probe.p689','N/A (fixture ausente)',false);
    PERFORM set_config('probe.p690','N/A (fixture ausente)',false);
    RETURN; END IF;
  BEGIN
    PERFORM set_config('request.jwt.claims',
      json_build_object('sub', current_setting('probe.pm_prov',true), 'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);

    SELECT count(*) INTO n FROM public.medicos WHERE id = v_ajeno;
    PERFORM set_config('probe.p688', CASE WHEN n = 0 THEN 'OK (no ve al medico de SV)'
      ELSE 'ROJO (el proveedor de GT VE un medico de SV)' END, false);

    SELECT count(*) INTO n FROM public.medicos WHERE pais_id = v_gt;
    PERFORM set_config('probe.p689', CASE WHEN n > 0
      THEN 'OK (ve '||n||' medicos de su pais: VisitadorDetallePage sigue andando)'
      ELSE 'ROJO (el proveedor NO ve ningun medico de SU pais — se cerro de mas)' END, false);

    SELECT count(*) INTO n_nulos FROM public.medicos WHERE pais_id IS NULL;
    PERFORM set_config('probe.p690', CASE WHEN n_nulos = 0 THEN 'OK (no ve medicos sin pais: fail-closed)'
      ELSE 'ROJO (ve '||n_nulos||' medicos con pais NULL)' END, false);

    PERFORM set_config('role','none', true);
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    PERFORM set_config('probe.p688','FALLO ('||SQLSTATE||' '||SQLERRM||')',false);
  END;
END $$;
SELECT set_config('role','none', true);

-- P691/P692/P693 — REGRESION del DROP de las tres policies. Son las que se romperian si el cierre se
-- pasara de la raya, que es lo que paso con la mig 284.
DO $$
DECLARE v_gt uuid := 'cbbbbe6d-59fe-4cf2-91ee-3e31ba1d5909'; n bigint;
BEGIN
  IF coalesce(current_setting('probe.pm_ready',true),'')<>'1' THEN
    PERFORM set_config('probe.p691','N/A (fixture ausente)',false);
    PERFORM set_config('probe.p692','N/A (fixture ausente)',false);
    PERFORM set_config('probe.p693','N/A (fixture ausente)',false);
    RETURN; END IF;

  BEGIN  -- paciente de GT
    PERFORM set_config('request.jwt.claims',
      json_build_object('sub', current_setting('probe.pm_pac',true), 'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    SELECT count(*) INTO n FROM public.medicos WHERE pais_id = v_gt;
    PERFORM set_config('role','none', true);
    PERFORM set_config('probe.p691', CASE WHEN n > 0 THEN 'OK (paciente sigue viendo los '||n||' de su pais)'
      ELSE 'ROJO (el paciente dejo de ver los medicos de su pais)' END, false);
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    PERFORM set_config('probe.p691','FALLO ('||SQLSTATE||' '||SQLERRM||')',false);
  END;

  BEGIN  -- el medico y su propio perfil
    PERFORM set_config('request.jwt.claims',
      json_build_object('sub', current_setting('probe.pm_med',true), 'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    SELECT count(*) INTO n FROM public.medicos WHERE id = current_setting('probe.pm_med',true)::uuid;
    PERFORM set_config('role','none', true);
    PERFORM set_config('probe.p692', CASE WHEN n = 1 THEN 'OK (el medico sigue viendo su perfil)'
      ELSE 'ROJO (el medico NO ve su propio perfil)' END, false);
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    PERFORM set_config('probe.p692','FALLO ('||SQLSTATE||' '||SQLERRM||')',false);
  END;

  BEGIN  -- admin_pais de GT
    PERFORM set_config('request.jwt.claims',
      json_build_object('sub', current_setting('probe.pm_adm',true), 'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    SELECT count(*) INTO n FROM public.medicos WHERE pais_id = v_gt;
    PERFORM set_config('role','none', true);
    PERFORM set_config('probe.p693', CASE WHEN n > 0 THEN 'OK (admin_pais sigue viendo los '||n||' de su pais)'
      ELSE 'ROJO (el admin_pais dejo de ver los medicos de su pais)' END, false);
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    PERFORM set_config('probe.p693','FALLO ('||SQLSTATE||' '||SQLERRM||')',false);
  END;
END $$;
SELECT set_config('role','none', true);

-- ============================================================
-- MIG 295 · las 6 RPCs de medicos no las ejecuta anon (P694-P703)
-- ============================================================
-- La 294 cerro la TABLA. Estas seis funciones son SECURITY DEFINER con dueno postgres: no pasan por
-- la RLS, asi que con EXECUTE abierto a anon el cierre quedaba puenteado — se listaban, buscaban y
-- contaban medicos sin sesion llamando a la RPC en vez de a la tabla.
--
-- LAS CUATRO POSITIVAS (P700-P703) SON LA MITAD QUE IMPORTA. Revocar de mas aca no rompe una
-- pantalla: rompe SEIS (CitasPage, useClinicaCitas, useAdmisionCitas, useWebAppCitas,
-- PaisDashboardPage, ClinicaDashboardPage). Sin ellas, "anon da 42501" tambien lo daria un REVOKE a
-- todo el mundo.
--
-- P699 distingue DOS cortes distintos de guardar_foto_medico: el del ACL (42501, que es el que esta
-- migracion pone) y el del cuerpo ('no_auth', P0001, que ya existia). Si sale P0001, el ACL sigue
-- abierto y lo unico que frena es la logica interna.
SELECT set_config('role','none', true);
DO $$
DECLARE v_gt uuid := 'cbbbbe6d-59fe-4cf2-91ee-3e31ba1d5909';
        v_med uuid; n bigint; v_err text;
BEGIN
  v_med := NULLIF(current_setting('probe.pm_med', true), '')::uuid;  -- del fixture PM_FX (mig 294)
  IF v_med IS NULL THEN
    PERFORM set_config('probe.p694','N/A (fixture PM_FX ausente)',false);
    PERFORM set_config('probe.p695','N/A (fixture PM_FX ausente)',false);
    PERFORM set_config('probe.p696','N/A (fixture PM_FX ausente)',false);
    PERFORM set_config('probe.p697','N/A (fixture PM_FX ausente)',false);
    PERFORM set_config('probe.p698','N/A (fixture PM_FX ausente)',false);
    PERFORM set_config('probe.p699','N/A (fixture PM_FX ausente)',false);
    RETURN; END IF;

  PERFORM set_config('request.jwt.claims','{"role":"anon"}', true);
  PERFORM set_config('role','anon', true);

  -- P694 — listar_medicos_por_pais
  BEGIN
    SELECT count(*) INTO n FROM public.listar_medicos_por_pais(v_gt);
    PERFORM set_config('probe.p694','ROJO (anon LISTO '||n||' medicos por RPC)',false);
  EXCEPTION WHEN insufficient_privilege THEN PERFORM set_config('probe.p694','OK (42501)',false);
    WHEN OTHERS THEN PERFORM set_config('probe.p694','FALLO ('||SQLSTATE||' '||SQLERRM||')',false);
  END;

  -- P695 — obtener_medicos_por_ids
  BEGIN
    SELECT count(*) INTO n FROM public.obtener_medicos_por_ids(ARRAY[v_med]::uuid[]);
    PERFORM set_config('probe.p695','ROJO (anon OBTUVO '||n||' medicos por id)',false);
  EXCEPTION WHEN insufficient_privilege THEN PERFORM set_config('probe.p695','OK (42501)',false);
    WHEN OTHERS THEN PERFORM set_config('probe.p695','FALLO ('||SQLSTATE||' '||SQLERRM||')',false);
  END;

  -- P696 — contar_medicos_por_pais
  BEGIN
    SELECT public.contar_medicos_por_pais(v_gt) INTO n;
    PERFORM set_config('probe.p696','ROJO (anon CONTO '||n||' medicos del pais)',false);
  EXCEPTION WHEN insufficient_privilege THEN PERFORM set_config('probe.p696','OK (42501)',false);
    WHEN OTHERS THEN PERFORM set_config('probe.p696','FALLO ('||SQLSTATE||' '||SQLERRM||')',false);
  END;

  -- P697 — contar_medicos_por_ids
  BEGIN
    SELECT public.contar_medicos_por_ids(ARRAY[v_med]::uuid[]) INTO n;
    PERFORM set_config('probe.p697','ROJO (anon CONTO '||n||' medicos por id)',false);
  EXCEPTION WHEN insufficient_privilege THEN PERFORM set_config('probe.p697','OK (42501)',false);
    WHEN OTHERS THEN PERFORM set_config('probe.p697','FALLO ('||SQLSTATE||' '||SQLERRM||')',false);
  END;

  -- P698 — buscar_medicos: BORRADA por la mig 308. Era la unica de las seis sin UN SOLO consumidor
  -- en el repo, y SECURITY DEFINER sin search_path: codigo muerto con privilegio no se parchea, se
  -- saca. Se conserva el NUMERO (son historial permanente, mismo criterio que la allowlist de
  -- PA-FAILOPEN) y cambia lo que mide: antes "anon no puede ejecutarla", ahora "ya no existe para
  -- nadie". Se mira pg_proc por NOMBRE y sin filtrar por firma, asi que tambien detecta que alguien
  -- la recree con otra firma — y recrearla tal cual reintroduciria los dos defectos que cerro la
  -- mig 307 en sus hermanas (sin search_path, y el `OR pais_id IS NULL` que cuela a los sin pais).
  BEGIN
    SELECT count(*) INTO n FROM pg_proc pr JOIN pg_namespace ns ON ns.oid = pr.pronamespace
     WHERE ns.nspname = 'public' AND pr.proname = 'buscar_medicos';
    PERFORM set_config('probe.p698', CASE WHEN n = 0
      THEN 'OK (borrada por la mig 308: 0 sobrecargas en pg_proc)'
      ELSE 'ROJO (buscar_medicos volvio a existir: '||n||' sobrecarga(s))' END, false);
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('probe.p698','FALLO ('||SQLSTATE||' '||SQLERRM||')',false);
  END;

  -- P699 — guardar_foto_medico: tiene que cortar el ACL (42501), NO el cuerpo ('no_auth', P0001)
  BEGIN
    PERFORM public.guardar_foto_medico('https://ejemplo.invalid/x.jpg');
    PERFORM set_config('probe.p699','ROJO (anon EJECUTO guardar_foto_medico sin error)',false);
  EXCEPTION WHEN insufficient_privilege THEN PERFORM set_config('probe.p699','OK (42501: corta el ACL)',false);
    WHEN OTHERS THEN
      v_err := SQLSTATE||' '||SQLERRM;
      PERFORM set_config('probe.p699', CASE WHEN SQLERRM ILIKE '%no_auth%'
        THEN 'ROJO (corto el CUERPO con no_auth, no el ACL: anon todavia puede ejecutarla)'
        ELSE 'FALLO ('||v_err||')' END, false);
  END;

  PERFORM set_config('role','none', true);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('role','none', true);
  PERFORM set_config('probe.p694','FALLO ('||SQLSTATE||' '||SQLERRM||')',false);
END $$;
SELECT set_config('role','none', true);

-- P700-P703 — NO-REGRESION. Las cuatro con consumidor real siguen respondiendo con un authenticated
-- de verdad. Si esto se pone rojo, se rompieron seis pantallas con sesion.
DO $$
DECLARE v_gt uuid := 'cbbbbe6d-59fe-4cf2-91ee-3e31ba1d5909';
        v_med uuid; n bigint;
BEGIN
  v_med := NULLIF(current_setting('probe.pm_med', true), '')::uuid;
  IF v_med IS NULL OR coalesce(current_setting('probe.pm_ready',true),'')<>'1' THEN
    PERFORM set_config('probe.p700','N/A (fixture PM_FX ausente)',false);
    PERFORM set_config('probe.p701','N/A (fixture PM_FX ausente)',false);
    PERFORM set_config('probe.p702','N/A (fixture PM_FX ausente)',false);
    PERFORM set_config('probe.p703','N/A (fixture PM_FX ausente)',false);
    RETURN; END IF;

  PERFORM set_config('request.jwt.claims',
    json_build_object('sub', current_setting('probe.pm_pac',true), 'role','authenticated')::text, true);
  PERFORM set_config('role','authenticated', true);

  BEGIN
    SELECT count(*) INTO n FROM public.listar_medicos_por_pais(v_gt);
    PERFORM set_config('probe.p700', CASE WHEN n > 0 THEN 'OK (listar devuelve '||n||')'
      ELSE 'ROJO (listar_medicos_por_pais devolvio 0 con authenticated)' END, false);
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p700','ROJO ('||SQLSTATE||' '||SQLERRM||')',false);
  END;

  BEGIN
    SELECT count(*) INTO n FROM public.obtener_medicos_por_ids(ARRAY[v_med]::uuid[]);
    PERFORM set_config('probe.p701', CASE WHEN n = 1 THEN 'OK (obtener por ids devuelve 1)'
      ELSE 'ROJO (obtener_medicos_por_ids devolvio '||n||' con authenticated)' END, false);
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p701','ROJO ('||SQLSTATE||' '||SQLERRM||')',false);
  END;

  BEGIN
    SELECT public.contar_medicos_por_pais(v_gt) INTO n;
    PERFORM set_config('probe.p702', CASE WHEN n > 0 THEN 'OK (contar por pais devuelve '||n||')'
      ELSE 'ROJO (contar_medicos_por_pais devolvio 0 con authenticated)' END, false);
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p702','ROJO ('||SQLSTATE||' '||SQLERRM||')',false);
  END;

  BEGIN
    SELECT public.contar_medicos_por_ids(ARRAY[v_med]::uuid[]) INTO n;
    PERFORM set_config('probe.p703', CASE WHEN n = 1 THEN 'OK (contar por ids devuelve 1)'
      ELSE 'ROJO (contar_medicos_por_ids devolvio '||n||' con authenticated)' END, false);
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p703','ROJO ('||SQLSTATE||' '||SQLERRM||')',false);
  END;

  PERFORM set_config('role','none', true);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('role','none', true);
  PERFORM set_config('probe.p700','FALLO ('||SQLSTATE||' '||SQLERRM||')',false);
END $$;
SELECT set_config('role','none', true);

-- ============================================================
-- MIG 296 · listar_clinicas_por_pais: anon afuera + gate de pais (LC_FX, P704-P710)
-- ============================================================
-- La funcion es SECURITY DEFINER: NO pasa por la RLS de public.clinicas. Por eso hacen falta las dos
-- mitades — sacar a anon del ACL (P704) y, para el resto, un gate interno que replique esa RLS
-- (P705-P710). Sin gate, cualquier `authenticated` pasaba el pais_id que quisiera.
--
-- POR QUE EL FIXTURE SIEMBRA UNA CLINICA EN OTRO PAIS. En prod hay 2 clinicas y las DOS son de
-- Guatemala. Una probe "paciente de GT pide otro pais -> 0 filas" daria 0 TAMBIEN SIN GATE, porque
-- ese pais no tiene clinicas: mediria cero. Con la clinica sembrada, el "0 filas" solo puede venir
-- del gate — sin gate, P705 y P707 devuelven 1. Eso es lo que las hace rojas primero de verdad.
--
-- LOS CUATRO CONTROLES POSITIVOS (P706, P708, P709, P710) SON LA MITAD QUE IMPORTA. Un gate que
-- cierra de mas da "0 filas" en todas las cruzadas igual que uno correcto. P706 es el mas filoso:
-- los 11 pacientes de prod NO tienen fila en `perfiles`, asi que un gate armado solo sobre
-- `perfiles`/`get_auth_user_pais_id()` los dejaria a todos afuera y rompería el agendado de citas.
SELECT set_config('role','none', true);
DO $$
DECLARE v_gt uuid := 'cbbbbe6d-59fe-4cf2-91ee-3e31ba1d5909';
        v_pac uuid; v_sa uuid; v_ap uuid; v_ap_pais uuid; v_otro uuid; v_doc uuid; v_seed uuid;
BEGIN
  -- Paciente con cuenta cuyo pais es GT (la rama `pacientes` de la policy).
  SELECT pa.auth_user_id INTO v_pac FROM public.pacientes pa
   WHERE pa.auth_user_id IS NOT NULL AND pa.pais_id = v_gt ORDER BY pa.auth_user_id LIMIT 1;
  SELECT p.id INTO v_sa FROM public.perfiles p WHERE p.rol = 'super_admin' ORDER BY p.id LIMIT 1;
  SELECT p.id, p.pais_id INTO v_ap, v_ap_pais FROM public.perfiles p
   WHERE p.rol = 'admin_pais' AND p.pais_id IS NOT NULL ORDER BY p.id LIMIT 1;

  -- "Otro pais" se elige CONTRA los dos paises que participan, no se hardcodea: si manana el
  -- admin_pais que sale primero es de otro pais, la prueba cruzada tiene que seguir siendo cruzada.
  SELECT cp.id INTO v_otro FROM public.configuracion_pais cp
   WHERE cp.id <> v_gt AND cp.id IS DISTINCT FROM v_ap_pais ORDER BY cp.codigo LIMIT 1;

  SELECT c.doctor_id INTO v_doc FROM public.clinicas c WHERE c.doctor_id IS NOT NULL LIMIT 1;

  IF v_pac IS NULL OR v_sa IS NULL OR v_ap IS NULL OR v_otro IS NULL OR v_doc IS NULL THEN
    PERFORM set_config('probe.lc_fx','ROJO (faltan fixtures: pac='||coalesce(v_pac::text,'-')
      ||' sa='||coalesce(v_sa::text,'-')||' ap='||coalesce(v_ap::text,'-')
      ||' otro='||coalesce(v_otro::text,'-')||' doc='||coalesce(v_doc::text,'-')||')', false);
    RETURN;
  END IF;

  -- La clinica sembrada en v_otro. Se revierte con el ROLLBACK del harness, como todo lo demas.
  INSERT INTO public.clinicas (doctor_id, nombre, pais_id)
  VALUES (v_doc, 'LC_FX_clinica_semilla_otro_pais', v_otro)
  RETURNING id INTO v_seed;

  PERFORM set_config('probe.lc_pac',  v_pac::text,     false);
  PERFORM set_config('probe.lc_sa',   v_sa::text,      false);
  PERFORM set_config('probe.lc_ap',   v_ap::text,      false);
  PERFORM set_config('probe.lc_appa', v_ap_pais::text, false);
  PERFORM set_config('probe.lc_otro', v_otro::text,    false);
  PERFORM set_config('probe.lc_ready','1',             false);
  PERFORM set_config('probe.lc_fx','OK (paciente GT + super_admin + admin_pais + clinica semilla en otro pais)', false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('probe.lc_fx','ROJO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;
SELECT set_config('role','none', true);

-- P704 — anon no puede ejecutarla. Es la mitad del ACL; el gate no la cubre.
DO $$
DECLARE v_gt uuid := 'cbbbbe6d-59fe-4cf2-91ee-3e31ba1d5909'; n bigint;
BEGIN
  IF coalesce(current_setting('probe.lc_ready', true),'') <> '1' THEN
    PERFORM set_config('probe.p704','N/A (fixture LC_FX ausente)', false); RETURN; END IF;

  PERFORM set_config('request.jwt.claims','{"role":"anon"}', true);
  PERFORM set_config('role','anon', true);
  BEGIN
    SELECT count(*) INTO n FROM public.listar_clinicas_por_pais(v_gt);
    PERFORM set_config('probe.p704','ROJO (anon LISTO '||n||' clinicas sin sesion)', false);
  EXCEPTION WHEN insufficient_privilege THEN PERFORM set_config('probe.p704','OK (42501)', false);
    WHEN OTHERS THEN PERFORM set_config('probe.p704','FALLO ('||SQLSTATE||' '||SQLERRM||')', false);
  END;
  PERFORM set_config('role','none', true);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('role','none', true);
  PERFORM set_config('probe.p704','FALLO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;
SELECT set_config('role','none', true);

-- P705/P706 — el paciente. P705 es la roja-primero (pide otro pais, que SI tiene una clinica);
-- P706 es el control positivo que prueba que el gate no lo dejo afuera de su propio pais.
DO $$
DECLARE v_gt uuid := 'cbbbbe6d-59fe-4cf2-91ee-3e31ba1d5909'; n bigint;
BEGIN
  IF coalesce(current_setting('probe.lc_ready', true),'') <> '1' THEN
    PERFORM set_config('probe.p705','N/A (fixture LC_FX ausente)', false);
    PERFORM set_config('probe.p706','N/A (fixture LC_FX ausente)', false); RETURN; END IF;

  PERFORM set_config('request.jwt.claims',
    json_build_object('sub', current_setting('probe.lc_pac', true), 'role','authenticated')::text, true);
  PERFORM set_config('role','authenticated', true);

  BEGIN
    SELECT count(*) INTO n FROM public.listar_clinicas_por_pais(
      current_setting('probe.lc_otro', true)::uuid);
    PERFORM set_config('probe.p705', CASE WHEN n = 0 THEN 'OK (0 filas: el gate corta el cruce de pais)'
      ELSE 'ROJO (paciente de GT leyo '||n||' clinicas de OTRO pais)' END, false);
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p705','FALLO ('||SQLSTATE||' '||SQLERRM||')', false);
  END;

  BEGIN
    SELECT count(*) INTO n FROM public.listar_clinicas_por_pais(v_gt);
    PERFORM set_config('probe.p706', CASE WHEN n > 0 THEN 'OK (control positivo: ve '||n||' de su pais)'
      ELSE 'ROJO (el gate dejo al PACIENTE afuera de su propio pais: se rompe AgendarCitaModal)' END, false);
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p706','ROJO ('||SQLSTATE||' '||SQLERRM||')', false);
  END;

  PERFORM set_config('role','none', true);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('role','none', true);
  PERFORM set_config('probe.p705','FALLO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;
SELECT set_config('role','none', true);

-- P707/P710 — el admin_pais. P707 cruzada (roja-primero), P710 su propio pais (control positivo).
DO $$
DECLARE n bigint;
BEGIN
  IF coalesce(current_setting('probe.lc_ready', true),'') <> '1' THEN
    PERFORM set_config('probe.p707','N/A (fixture LC_FX ausente)', false);
    PERFORM set_config('probe.p710','N/A (fixture LC_FX ausente)', false); RETURN; END IF;

  PERFORM set_config('request.jwt.claims',
    json_build_object('sub', current_setting('probe.lc_ap', true), 'role','authenticated')::text, true);
  PERFORM set_config('role','authenticated', true);

  BEGIN
    SELECT count(*) INTO n FROM public.listar_clinicas_por_pais(
      current_setting('probe.lc_otro', true)::uuid);
    PERFORM set_config('probe.p707', CASE WHEN n = 0 THEN 'OK (0 filas: admin_pais no cruza de pais)'
      ELSE 'ROJO (admin_pais leyo '||n||' clinicas de un pais ajeno)' END, false);
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p707','FALLO ('||SQLSTATE||' '||SQLERRM||')', false);
  END;

  BEGIN
    SELECT count(*) INTO n FROM public.listar_clinicas_por_pais(
      current_setting('probe.lc_appa', true)::uuid);
    PERFORM set_config('probe.p710', CASE WHEN n > 0 THEN 'OK (control positivo: ve '||n||' de SU pais)'
      ELSE 'ROJO (el gate dejo al admin_pais afuera de su propio pais)' END, false);
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p710','ROJO ('||SQLSTATE||' '||SQLERRM||')', false);
  END;

  PERFORM set_config('role','none', true);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('role','none', true);
  PERFORM set_config('probe.p707','FALLO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;
SELECT set_config('role','none', true);

-- P708/P709 — super_admin. Los dos son CONTROL POSITIVO: sin ellos, "todas las cruzadas dan 0"
-- tambien lo cumpliria un gate que cierra para todo el mundo.
DO $$
DECLARE v_gt uuid := 'cbbbbe6d-59fe-4cf2-91ee-3e31ba1d5909'; n bigint;
BEGIN
  IF coalesce(current_setting('probe.lc_ready', true),'') <> '1' THEN
    PERFORM set_config('probe.p708','N/A (fixture LC_FX ausente)', false);
    PERFORM set_config('probe.p709','N/A (fixture LC_FX ausente)', false); RETURN; END IF;

  PERFORM set_config('request.jwt.claims',
    json_build_object('sub', current_setting('probe.lc_sa', true), 'role','authenticated')::text, true);
  PERFORM set_config('role','authenticated', true);

  BEGIN
    SELECT count(*) INTO n FROM public.listar_clinicas_por_pais(
      current_setting('probe.lc_otro', true)::uuid);
    PERFORM set_config('probe.p708', CASE WHEN n > 0 THEN 'OK (super_admin ve '||n||' en pais ajeno)'
      ELSE 'ROJO (super_admin no ve la clinica semilla: el gate cierra de mas)' END, false);
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p708','ROJO ('||SQLSTATE||' '||SQLERRM||')', false);
  END;

  BEGIN
    SELECT count(*) INTO n FROM public.listar_clinicas_por_pais(v_gt);
    PERFORM set_config('probe.p709', CASE WHEN n > 0 THEN 'OK (super_admin ve '||n||' en GT)'
      ELSE 'ROJO (super_admin no ve las clinicas de GT)' END, false);
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p709','ROJO ('||SQLSTATE||' '||SQLERRM||')', false);
  END;

  PERFORM set_config('role','none', true);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('role','none', true);
  PERFORM set_config('probe.p708','FALLO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;
SELECT set_config('role','none', true);

-- ============================================================
-- MIG 297 · invitaciones_*: policy propia para admin_pais (IN_FX, P711-P720)
-- ============================================================
-- Defecto INVERSO al de las migs 294/295/296: ahi sobraba acceso, aca faltaba. El admin_pais tenia
-- los dos items en el sidebar y las dos tablas no tenian una sola policy que lo contemplara: lista
-- VACIA, sin error. Y en clinicas era peor que inutil, porque crear-invitacion-clinica SI lo
-- autoriza — creaba la invitacion y despues no la veia.
--
-- EL FIXTURE SIEMBRA UNA INVITACION DE MEDICO EN OTRO PAIS. En prod invitaciones_medico tiene 2
-- filas y las dos son de GT: "el admin de GT no ve las de SV" daria 0 sin policy, con policy, y con
-- una policy rota que no filtre nada. Con la semilla, el 0 solo puede venir del scoping.
-- (invitaciones_clinica ya tiene 1 de GT y 1 de SV en prod, asi que ahi la distincion es real sin
-- sembrar: P713 exige ver EXACTAMENTE la de GT.)
--
-- P716-P718 SON LA PARTE QUE NADIE MIRA. La policy es FOR ALL y va SIN `WITH CHECK` explicito, asi
-- que el WITH CHECK hereda el USING. Que eso alcance para impedir que un admin_pais inserte en otro
-- pais (P717) o mueva una fila suya de pais (P718) es una afirmacion sobre como se comporta esta
-- base, no sobre lo que dice el manual: se mide.
--
-- P719/P720 son la leccion de la mig 284: una policy se evalua con los privilegios del LLAMANTE, y
-- esta hace un EXISTS sobre `perfiles`. Si un rol no pudiera leer `perfiles`, la policy no negaria
-- en silencio: lanzaria 42501 y romperia la tabla para ese rol. Se EJERCITA a anon en vez de mirar
-- el catalogo.
SELECT set_config('role','none', true);
DO $$
DECLARE v_gt uuid := 'cbbbbe6d-59fe-4cf2-91ee-3e31ba1d5909';
        v_ap uuid; v_appa uuid; v_sa uuid; v_otro uuid; v_med uuid;
BEGIN
  SELECT p.id, p.pais_id INTO v_ap, v_appa FROM public.perfiles p
   WHERE p.rol = 'admin_pais' AND p.pais_id IS NOT NULL ORDER BY p.id LIMIT 1;
  SELECT p.id INTO v_sa  FROM public.perfiles p WHERE p.rol = 'super_admin' ORDER BY p.id LIMIT 1;
  SELECT p.id INTO v_med FROM public.perfiles p WHERE p.rol = 'medico' ORDER BY p.id LIMIT 1;

  -- "Otro pais" se elige CONTRA el pais del admin, no se hardcodea.
  SELECT cp.id INTO v_otro FROM public.configuracion_pais cp
   WHERE cp.id IS DISTINCT FROM v_appa ORDER BY cp.codigo LIMIT 1;

  IF v_ap IS NULL OR v_sa IS NULL OR v_med IS NULL OR v_otro IS NULL THEN
    PERFORM set_config('probe.in_fx','ROJO (faltan fixtures: ap='||coalesce(v_ap::text,'-')
      ||' sa='||coalesce(v_sa::text,'-')||' med='||coalesce(v_med::text,'-')
      ||' otro='||coalesce(v_otro::text,'-')||')', false);
    RETURN; END IF;

  INSERT INTO public.invitaciones_medico (pais_id, email, nombre_completo)
  VALUES (v_otro, 'in_fx_semilla_otro_pais@ejemplo.invalid', 'IN_FX semilla otro pais');

  PERFORM set_config('probe.in_ap',   v_ap::text,   false);
  PERFORM set_config('probe.in_appa', v_appa::text, false);
  PERFORM set_config('probe.in_sa',   v_sa::text,   false);
  PERFORM set_config('probe.in_med',  v_med::text,  false);
  PERFORM set_config('probe.in_otro', v_otro::text, false);
  PERFORM set_config('probe.in_ready','1',          false);
  PERFORM set_config('probe.in_fx','OK (admin_pais + super_admin + medico + semilla de medico en otro pais)', false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('probe.in_fx','ROJO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;
SELECT set_config('role','none', true);

-- P711/P712/P713 — LECTURA del admin_pais. Rojas primero: sin la 297 ve 0 en las tres.
DO $$
DECLARE n bigint; n2 bigint; v_pais uuid;
BEGIN
  IF coalesce(current_setting('probe.in_ready', true),'') <> '1' THEN
    PERFORM set_config('probe.p711','N/A (fixture IN_FX ausente)', false);
    PERFORM set_config('probe.p712','N/A (fixture IN_FX ausente)', false);
    PERFORM set_config('probe.p713','N/A (fixture IN_FX ausente)', false); RETURN; END IF;

  PERFORM set_config('request.jwt.claims',
    json_build_object('sub', current_setting('probe.in_ap', true), 'role','authenticated')::text, true);
  PERFORM set_config('role','authenticated', true);

  BEGIN
    SELECT count(*) INTO n FROM public.invitaciones_medico
     WHERE pais_id = current_setting('probe.in_appa', true)::uuid;
    PERFORM set_config('probe.p711', CASE WHEN n > 0
      THEN 'OK (admin_pais ve '||n||' invitaciones de medico de SU pais)'
      ELSE 'ROJO (ve 0 invitaciones de medico de su propio pais)' END, false);
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p711','ROJO ('||SQLSTATE||' '||SQLERRM||')', false);
  END;

  BEGIN
    SELECT count(*) INTO n FROM public.invitaciones_medico
     WHERE pais_id = current_setting('probe.in_otro', true)::uuid;
    PERFORM set_config('probe.p712', CASE WHEN n = 0
      THEN 'OK (0 filas: no ve la semilla de otro pais)'
      ELSE 'ROJO (admin_pais leyo '||n||' invitaciones de medico de OTRO pais)' END, false);
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p712','FALLO ('||SQLSTATE||' '||SQLERRM||')', false);
  END;

  -- invitaciones_clinica tiene 1 de GT y 1 de SV en prod: ve UNA y tiene que ser la suya.
  BEGIN
    SELECT count(*), count(*) FILTER (WHERE pais_id = current_setting('probe.in_appa', true)::uuid)
      INTO n, n2 FROM public.invitaciones_clinica;
    PERFORM set_config('probe.p713', CASE WHEN n > 0 AND n = n2
      THEN 'OK (ve '||n||' invitaciones de clinica, todas de SU pais)'
      WHEN n = 0 THEN 'ROJO (ve 0 invitaciones de clinica)'
      ELSE 'ROJO (ve '||n||' invitaciones de clinica pero solo '||n2||' son de su pais)' END, false);
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p713','ROJO ('||SQLSTATE||' '||SQLERRM||')', false);
  END;

  PERFORM set_config('role','none', true);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('role','none', true);
  PERFORM set_config('probe.p711','FALLO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;
SELECT set_config('role','none', true);

-- P714/P715 — CONTROLES. Sin ellos, "el admin_pais ve lo suyo" tambien lo cumpliria una policy
-- USING(true), que es exactamente como nacio el hallazgo de `medicos` de la mig 294.
DO $$
DECLARE n bigint;
BEGIN
  IF coalesce(current_setting('probe.in_ready', true),'') <> '1' THEN
    PERFORM set_config('probe.p714','N/A (fixture IN_FX ausente)', false);
    PERFORM set_config('probe.p715','N/A (fixture IN_FX ausente)', false); RETURN; END IF;

  PERFORM set_config('request.jwt.claims',
    json_build_object('sub', current_setting('probe.in_sa', true), 'role','authenticated')::text, true);
  PERFORM set_config('role','authenticated', true);
  BEGIN
    SELECT count(DISTINCT pais_id) INTO n FROM public.invitaciones_medico;
    PERFORM set_config('probe.p714', CASE WHEN n >= 2
      THEN 'OK (no-regresion: super_admin sigue viendo '||n||' paises)'
      ELSE 'ROJO (super_admin ve invitaciones de '||n||' pais: se le achico el alcance)' END, false);
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p714','ROJO ('||SQLSTATE||' '||SQLERRM||')', false);
  END;
  PERFORM set_config('role','none', true);

  PERFORM set_config('request.jwt.claims',
    json_build_object('sub', current_setting('probe.in_med', true), 'role','authenticated')::text, true);
  PERFORM set_config('role','authenticated', true);
  BEGIN
    SELECT count(*) INTO n FROM public.invitaciones_medico;
    PERFORM set_config('probe.p715', CASE WHEN n = 0
      THEN 'OK (un medico sigue viendo 0: la policy no abrio a todos)'
      ELSE 'ROJO (un rol sin autoridad ve '||n||' invitaciones)' END, false);
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p715','FALLO ('||SQLSTATE||' '||SQLERRM||')', false);
  END;
  PERFORM set_config('role','none', true);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('role','none', true);
  PERFORM set_config('probe.p714','FALLO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;
SELECT set_config('role','none', true);

-- P716/P717/P718 — ESCRITURA. La policy es FOR ALL sin WITH CHECK explicito: hereda el USING.
-- P716 prueba que el alcance de escritura existe; P717 y P718 que el WITH CHECK heredado alcanza.
DO $$
DECLARE v_id uuid; n bigint;
BEGIN
  IF coalesce(current_setting('probe.in_ready', true),'') <> '1' THEN
    PERFORM set_config('probe.p716','N/A (fixture IN_FX ausente)', false);
    PERFORM set_config('probe.p717','N/A (fixture IN_FX ausente)', false);
    PERFORM set_config('probe.p718','N/A (fixture IN_FX ausente)', false); RETURN; END IF;

  PERFORM set_config('request.jwt.claims',
    json_build_object('sub', current_setting('probe.in_ap', true), 'role','authenticated')::text, true);
  PERFORM set_config('role','authenticated', true);

  -- P716 — INSERT en SU pais: el alcance FOR ALL que decidio Oscar.
  BEGIN
    INSERT INTO public.invitaciones_medico (pais_id, email, nombre_completo)
    VALUES (current_setting('probe.in_appa', true)::uuid, 'p716_propio@ejemplo.invalid', 'P716 propio')
    RETURNING id INTO v_id;
    PERFORM set_config('probe.p716','OK (admin_pais inserta en SU pais)', false);
  EXCEPTION WHEN insufficient_privilege THEN
    PERFORM set_config('probe.p716','ROJO (42501: no puede insertar ni en su propio pais)', false);
    WHEN OTHERS THEN PERFORM set_config('probe.p716','FALLO ('||SQLSTATE||' '||SQLERRM||')', false);
  END;

  -- P717 — INSERT en OTRO pais: lo tiene que cortar el WITH CHECK heredado.
  BEGIN
    INSERT INTO public.invitaciones_medico (pais_id, email, nombre_completo)
    VALUES (current_setting('probe.in_otro', true)::uuid, 'p717_ajeno@ejemplo.invalid', 'P717 ajeno');
    PERFORM set_config('probe.p717','ROJO (inserto una invitacion en un pais AJENO)', false);
  EXCEPTION WHEN insufficient_privilege THEN
    PERFORM set_config('probe.p717','OK (42501: el WITH CHECK heredado corta el INSERT cruzado)', false);
    WHEN OTHERS THEN PERFORM set_config('probe.p717','FALLO ('||SQLSTATE||' '||SQLERRM||')', false);
  END;

  -- P718 — UPDATE que MUEVE la fila a otro pais. USING mira la vieja y WITH CHECK la nueva: la
  -- nueva ya no satisface el predicado, asi que tiene que fallar. Es la pregunta exacta de Oscar.
  BEGIN
    IF v_id IS NULL THEN
      PERFORM set_config('probe.p718','N/A (P716 no dejo fila para mover)', false);
    ELSE
      UPDATE public.invitaciones_medico
         SET pais_id = current_setting('probe.in_otro', true)::uuid
       WHERE id = v_id;
      GET DIAGNOSTICS n = ROW_COUNT;
      PERFORM set_config('probe.p718', CASE WHEN n = 0
        THEN 'OK (0 filas: el USING ya no alcanza la fila movida)'
        ELSE 'ROJO (movio '||n||' fila(s) de invitacion a un pais AJENO)' END, false);
    END IF;
  EXCEPTION WHEN insufficient_privilege THEN
    PERFORM set_config('probe.p718','OK (42501: el WITH CHECK heredado corta el cambio de pais)', false);
    WHEN OTHERS THEN PERFORM set_config('probe.p718','FALLO ('||SQLSTATE||' '||SQLERRM||')', false);
  END;

  PERFORM set_config('role','none', true);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('role','none', true);
  PERFORM set_config('probe.p716','FALLO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;
SELECT set_config('role','none', true);

-- P719/P720 — anon EJERCITADO (leccion mig 284). Tiene que dar 0 filas SIN error: la policy nueva
-- es TO PUBLIC y hace un EXISTS sobre `perfiles`; si anon no pudiera leer `perfiles`, lanzaria
-- 42501 en vez de negar en silencio, y romperia las dos tablas para ese rol.
DO $$
DECLARE n bigint;
BEGIN
  PERFORM set_config('request.jwt.claims','{"role":"anon"}', true);
  PERFORM set_config('role','anon', true);

  BEGIN
    SELECT count(*) INTO n FROM public.invitaciones_medico;
    PERFORM set_config('probe.p719', CASE WHEN n = 0 THEN 'OK (0 filas, sin 42501)'
      ELSE 'ROJO (anon ve '||n||' invitaciones de medico)' END, false);
  EXCEPTION WHEN insufficient_privilege THEN
    IF has_table_privilege('anon','public.invitaciones_medico','SELECT')
      THEN PERFORM set_config('probe.p719','ROJO (42501 CON grant (policy rota): invitaciones_medico)', false);
      ELSE PERFORM set_config('probe.p719','OK (42501 sin grant: anon revocada tras 324)', false); END IF;
    WHEN OTHERS THEN PERFORM set_config('probe.p719','FALLO ('||SQLSTATE||' '||SQLERRM||')', false);
  END;

  BEGIN
    SELECT count(*) INTO n FROM public.invitaciones_clinica;
    PERFORM set_config('probe.p720', CASE WHEN n = 0 THEN 'OK (0 filas, sin 42501)'
      ELSE 'ROJO (anon ve '||n||' invitaciones de clinica)' END, false);
  EXCEPTION WHEN insufficient_privilege THEN
    IF has_table_privilege('anon','public.invitaciones_clinica','SELECT')
      THEN PERFORM set_config('probe.p720','ROJO (42501 CON grant (policy rota): invitaciones_clinica)', false);
      ELSE PERFORM set_config('probe.p720','OK (42501 sin grant: anon revocada tras 324)', false); END IF;
    WHEN OTHERS THEN PERFORM set_config('probe.p720','FALLO ('||SQLSTATE||' '||SQLERRM||')', false);
  END;

  PERFORM set_config('role','none', true);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('role','none', true);
  PERFORM set_config('probe.p719','FALLO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;
SELECT set_config('role','none', true);

-- ============================================================
-- MIG 298 · anon sin escritura sobre public, y sin recibirla por default (P721-P724)
-- ============================================================
-- P721 es el molde de P635: EJERCITA al rol contra tablas de verdad en vez de mirar el catalogo.
-- La leccion de la mig 284 es que un cambio de privilegios no se verifica preguntando quien tiene
-- que, sino viendo QUE PASA CUANDO SE USA — revocar de mas no niega en silencio, lanza 42501.
--
-- LA MUESTRA NO ES CAPRICHOSA. Se midio antes que devuelve anon hoy en cada candidata:
--   0 filas  -> pacientes, recetas, receta_items, expediente_notas, signos_vitales, examenes,
--               citas, clinicas, invitaciones_medico, facturas, transacciones   <- van a P721
--   42501    -> medicos, chat_mensajes (anon NO tiene SELECT ahi)               <- NO van
--   21 filas -> configuracion_pais (catalogo publico legitimo, lo lee el registro de proveedor)
--                                                                               <- NO va
-- Meter una de las dos ultimas clases en una probe de "0 filas sin error" la pondria roja sin que
-- hubiera nada roto, que es la forma mas rapida de que un harness deje de significar algo.
SELECT set_config('role','none', true);
DO $$
DECLARE t text; n bigint; v_mal text := ''; v_ok int := 0; v_ng text := '';
BEGIN
  PERFORM set_config('request.jwt.claims','{"role":"anon"}', true);
  PERFORM set_config('role','anon', true);
  FOREACH t IN ARRAY ARRAY['pacientes','recetas','receta_items','expediente_notas','signos_vitales',
                           'examenes','citas','clinicas','invitaciones_medico','facturas','transacciones'] LOOP
    BEGIN
      EXECUTE format('SELECT count(*) FROM public.%I', t) INTO n;
      IF n = 0 THEN v_ok := v_ok + 1;
      ELSE v_mal := v_mal || t || '=' || n || ' filas; '; END IF;
    EXCEPTION WHEN insufficient_privilege THEN
      -- 42501 CON grant = policy rota (hazard mig284); 42501 SIN grant = correcto post-324.
      IF has_table_privilege('anon','public.'||t,'SELECT') THEN v_mal := v_mal || t || '=42501 CON grant (policy rota); ';
      ELSE v_ng := v_ng || t || ' '; END IF;
      WHEN OTHERS THEN v_mal := v_mal || t || '=' || SQLSTATE || '; ';
    END;
  END LOOP;
  PERFORM set_config('role','none', true);
  PERFORM set_config('probe.p721', CASE WHEN v_mal = ''
    THEN 'OK ('||v_ok||' con 0 filas; sin grant/42501-correcto: '||coalesce(nullif(v_ng,''),'ninguna')||')'
    ELSE 'ROJO (' || v_mal || ')' END, false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('role','none', true);
  PERFORM set_config('probe.p721','FALLO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;
SELECT set_config('role','none', true);

-- P722 — CONTRAPRUEBA de P721, molde de P636. Sin esto, P721 verde podria significar "todo bien"
-- o "la probe no detecta nada". Se le quita el SELECT a anon sobre una tabla de la muestra dentro
-- de un SAVEPOINT: el mismo codigo de P721 tiene que pasar de 0-filas a 42501, y despues vuelve.
DO $$
DECLARE n bigint; v_res text;
BEGIN
  PERFORM set_config('role','none', true);
  BEGIN
    EXECUTE 'REVOKE SELECT ON public.pacientes FROM anon';

    PERFORM set_config('request.jwt.claims','{"role":"anon"}', true);
    PERFORM set_config('role','anon', true);
    BEGIN
      SELECT count(*) INTO n FROM public.pacientes;
      v_res := 'ROJO (sin el GRANT anon igual leyo ' || n || ': el detector de P721 no detecta)';
    EXCEPTION WHEN insufficient_privilege THEN
      v_res := 'OK (sin el GRANT da 42501: P721 distingue 0-filas de tabla-rota)';
      WHEN OTHERS THEN v_res := 'FALLO (' || SQLSTATE || ' ' || SQLERRM || ')';
    END;
    PERFORM set_config('role','none', true);

    -- Se revierte SIEMPRE, con o sin exito, levantando para deshacer el REVOKE de la subtransaccion.
    RAISE EXCEPTION 'm298_rollback_contraprueba';
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    IF SQLERRM <> 'm298_rollback_contraprueba' THEN
      v_res := coalesce(v_res, 'FALLO (' || SQLSTATE || ' ' || SQLERRM || ')');
    END IF;
  END;
  PERFORM set_config('probe.p722', coalesce(v_res, 'FALLO (sin veredicto)'), false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('role','none', true);
  PERFORM set_config('probe.p722','FALLO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;
SELECT set_config('role','none', true);

-- P723 — CENSO GLOBAL del residuo. No mira "las 73" de aquel dia: mira TODA public, asi que una
-- tabla nueva que naciera abierta tambien cae. Es el centinela que convierte "hay que acordarse de
-- revisar" en "se pone rojo solo".
DO $$
DECLARE n_tab int; n_col int; v_lista text;
BEGIN
  SELECT count(DISTINCT table_name), coalesce(string_agg(DISTINCT table_name, ', '), '')
    INTO n_tab, v_lista
    FROM information_schema.role_table_grants
   WHERE table_schema='public' AND grantee='anon'
     AND privilege_type IN ('INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER');

  SELECT count(*) INTO n_col FROM information_schema.column_privileges
   WHERE table_schema='public' AND grantee='anon'
     AND privilege_type IN ('INSERT','UPDATE','REFERENCES');

  PERFORM set_config('probe.p723', CASE WHEN n_tab = 0 AND n_col = 0
    THEN 'OK (0 relaciones y 0 columnas con escritura para anon en todo public)'
    ELSE 'ROJO (' || n_tab || ' relacion(es) y ' || n_col || ' columna(s): ' || left(v_lista, 250) || ')' END, false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('probe.p723','FALLO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;

-- P724 — LA FABRICA. Crea una tabla y mira con que ACL nace. Es la unica probe que cubre el caso
-- que la mig 298 NO pudo cerrar: la entrada de pg_default_acl de `supabase_admin`, intocable desde
-- la conexion del CLI (42501). Hoy es inerte porque las 128 relaciones de public las crea
-- `postgres`; si eso cambiara, esto se pone rojo sin que nadie tenga que sospecharlo.
DO $$
DECLARE v_acl text; v_mal text := '';
BEGIN
  BEGIN
    EXECUTE 'CREATE TABLE public._p724_probe_defacl (id int)';
    SELECT coalesce(array_to_string(c.relacl, ' '), '(NULL)') INTO v_acl
      FROM pg_class c JOIN pg_namespace ns ON ns.oid=c.relnamespace
     WHERE ns.nspname='public' AND c.relname='_p724_probe_defacl';
    IF has_table_privilege('anon','public._p724_probe_defacl','INSERT')   THEN v_mal := v_mal||'INSERT '; END IF;
    IF has_table_privilege('anon','public._p724_probe_defacl','UPDATE')   THEN v_mal := v_mal||'UPDATE '; END IF;
    IF has_table_privilege('anon','public._p724_probe_defacl','DELETE')   THEN v_mal := v_mal||'DELETE '; END IF;
    IF has_table_privilege('anon','public._p724_probe_defacl','TRUNCATE') THEN v_mal := v_mal||'TRUNCATE '; END IF;
    IF has_table_privilege('anon','public._p724_probe_defacl','SELECT')   THEN v_mal := v_mal||'SELECT '; END IF;
    EXECUTE 'DROP TABLE public._p724_probe_defacl';
    PERFORM set_config('probe.p724', CASE WHEN v_mal = ''
      THEN 'OK (una tabla nueva no le da nada a anon)'
      ELSE 'ROJO (una tabla NUEVA nace con ' || v_mal || 'para anon: el default volvio)' END, false);
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('probe.p724','FALLO ('||SQLSTATE||' '||SQLERRM||')', false);
  END;
END $$;

-- ============================================================
-- MIG 299 · el paciente no ve staff como medico (LS_FX, P725-P727)
-- ============================================================
-- Una fila en `medicos` NO significa "es medico": crear-staff-clinica crea una para cualquier staff
-- porque medico_clinicas.medico_id tiene FK a esa tabla. El rol real vive en perfiles.rol, y
-- buscar_medicos_paciente (mig 184) nunca lo miraba. Medido el 18-sep contra prod: un paciente REAL
-- de GT recibia 5 "medicos" y uno era un admin_clinica.
--
-- EL FIXTURE SIEMBRA SU PROPIO STAFF EN VEZ DE USAR LOS 9 QUE YA HAY EN PROD. Dos razones: los de
-- prod pueden cambiar de rol o desactivarse y la probe se volveria muda sin avisar; y hacen falta
-- dos escenarios que ningun dato real cubre — un staff con pais_id que COINCIDE con el del paciente
-- (hoy hay 1 sola fila asi) y un paciente SIN pais_id (hoy hay 0). Sembrando, los dos son firmes.
--
-- P726 ES LA MITAD QUE IMPORTA. "El staff no aparece" tambien lo cumple una RPC que no devuelve
-- nada: sin el control positivo, esta probe pasaria con la funcion rota.
SELECT set_config('role','none', true);
DO $$
DECLARE v_gt constant uuid := 'cbbbbe6d-59fe-4cf2-91ee-3e31ba1d5909';
        v_staff uuid := gen_random_uuid();
        v_pac   uuid := gen_random_uuid();
        v_esp   uuid;
        v_real  uuid;
BEGIN
  -- Sin raw_user_meta_data->>'tipo'='paciente', on_auth_user_created_paciente no hace nada.
  INSERT INTO auth.users (id) VALUES (v_staff), (v_pac);

  INSERT INTO especialidades (nombre, activo)
  VALUES ('LS_FX especialidad solo-staff', true) RETURNING id INTO v_esp;

  INSERT INTO perfiles (id, email, nombre_completo, rol, activo, pais_id)
  VALUES (v_staff, 'ls_fx_staff@ejemplo.invalid', 'LS_FX Staff Secretaria', 'secretaria', true, v_gt);

  INSERT INTO medicos (id, nombre_completo, activo, pais_id, especialidad_id)
  VALUES (v_staff, 'LS_FX Staff Secretaria', true, v_gt, v_esp);

  INSERT INTO pacientes (auth_user_id, nombre, apellido, activo, pais_id)
  VALUES (v_pac, 'LS_FX', 'Paciente', true, v_gt);

  SELECT m.id INTO v_real FROM medicos m
   WHERE m.activo AND m.pais_id = v_gt
     AND EXISTS (SELECT 1 FROM perfiles p WHERE p.id = m.id AND p.rol = 'medico')
   ORDER BY m.id LIMIT 1;

  PERFORM set_config('probe.ls_staff', v_staff::text, false);
  PERFORM set_config('probe.ls_pac',   v_pac::text,   false);
  PERFORM set_config('probe.ls_esp',   v_esp::text,   false);
  PERFORM set_config('probe.ls_real',  coalesce(v_real::text,''), false);
  PERFORM set_config('probe.ls_ready', '1', false);
  PERFORM set_config('probe.ls_fx',
    'OK (staff secretaria + paciente + especialidad solo-staff'
    || CASE WHEN v_real IS NULL THEN ' | SIN medico real para el control' ELSE ' + medico real' END || ')', false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('probe.ls_fx','ROJO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;
SELECT set_config('role','none', true);

-- P725 — el staff no aparece, en los DOS escenarios de pais.
DO $$
DECLARE n1 bigint; n2 bigint; n3 bigint; v_staff uuid; v_pac uuid;
BEGIN
  IF coalesce(current_setting('probe.ls_ready', true),'') <> '1' THEN
    PERFORM set_config('probe.p725','N/A (fixture LS_FX ausente)', false); RETURN; END IF;
  v_staff := current_setting('probe.ls_staff', true)::uuid;
  v_pac   := current_setting('probe.ls_pac',   true)::uuid;

  PERFORM set_config('request.jwt.claims',
    json_build_object('sub', v_pac, 'role','authenticated')::text, true);

  -- escenario A: el paciente tiene pais_id y COINCIDE con el del staff.
  SELECT count(*) INTO n1 FROM public.buscar_medicos_paciente() b WHERE b.id = v_staff;

  -- escenario B: el paciente NO tiene pais_id -> antes de la 299 la condicion se volvia universal.
  UPDATE pacientes SET pais_id = NULL WHERE auth_user_id = v_pac;
  SELECT count(*) INTO n2 FROM public.buscar_medicos_paciente() b WHERE b.id = v_staff;
  SELECT count(*) INTO n3 FROM public.buscar_medicos_paciente() b
   WHERE NOT EXISTS (SELECT 1 FROM perfiles p WHERE p.id = b.id AND p.rol = 'medico');
  UPDATE pacientes SET pais_id = 'cbbbbe6d-59fe-4cf2-91ee-3e31ba1d5909'::uuid WHERE auth_user_id = v_pac;

  PERFORM set_config('probe.p725', CASE
    WHEN n1 = 0 AND n2 = 0 AND n3 = 0 THEN 'OK (staff invisible con pais coincidente y con pais NULL; 0 no-medicos)'
    WHEN n1 > 0 THEN 'ROJO (el staff aparece con pais_id coincidente)'
    WHEN n2 > 0 THEN 'ROJO (el staff aparece con el paciente SIN pais_id: rama universal)'
    ELSE 'ROJO (la RPC devuelve '||n3||' no-medico(s) con el paciente sin pais_id)' END, false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('probe.p725','FALLO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;
SELECT set_config('role','none', true);

-- P726 — CONTRAPRUEBA / control positivo: un medico REAL del mismo pais SI aparece. Sin esto,
-- P725 verde no distingue "cerre la fuga" de "rompi la busqueda".
DO $$
DECLARE n bigint; v_real uuid;
BEGIN
  IF coalesce(current_setting('probe.ls_ready', true),'') <> '1'
     OR coalesce(current_setting('probe.ls_real', true),'') = '' THEN
    PERFORM set_config('probe.p726','N/A (fixture LS_FX o medico real ausente)', false); RETURN; END IF;
  v_real := current_setting('probe.ls_real', true)::uuid;

  PERFORM set_config('request.jwt.claims',
    json_build_object('sub', current_setting('probe.ls_pac', true), 'role','authenticated')::text, true);
  SELECT count(*) INTO n FROM public.buscar_medicos_paciente() b WHERE b.id = v_real;
  PERFORM set_config('probe.p726', CASE WHEN n = 1
    THEN 'OK (control positivo: el medico real sigue apareciendo)'
    ELSE 'ROJO (el medico real aparece '||n||' veces: la RPC quedo rota)' END, false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('probe.p726','ROJO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;
SELECT set_config('role','none', true);

-- P727 — listar_especialidades_activas: la especialidad que SOLO tiene al staff no puede salir en
-- el <select> del modal, y las que tienen medicos reales si. Cubre el cambio 2 de la mig 299, que
-- de otro modo no tendria ninguna probe.
DO $$
DECLARE n_staff bigint; n_tot bigint;
BEGIN
  IF coalesce(current_setting('probe.ls_ready', true),'') <> '1' THEN
    PERFORM set_config('probe.p727','N/A (fixture LS_FX ausente)', false); RETURN; END IF;

  PERFORM set_config('request.jwt.claims',
    json_build_object('sub', current_setting('probe.ls_pac', true), 'role','authenticated')::text, true);
  SELECT count(*) INTO n_staff FROM public.listar_especialidades_activas() e
   WHERE e.id = current_setting('probe.ls_esp', true)::uuid;
  SELECT count(*) INTO n_tot FROM public.listar_especialidades_activas();

  PERFORM set_config('probe.p727', CASE
    WHEN n_staff > 0 THEN 'ROJO (la especialidad solo-staff aparece en el catalogo)'
    WHEN n_tot = 0   THEN 'ROJO (el catalogo quedo VACIO: cerro de mas)'
    ELSE 'OK (la solo-staff no aparece y quedan '||n_tot||' especialidades reales)' END, false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('probe.p727','FALLO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;
SELECT set_config('role','none', true);

-- Limpieza del fixture. El harness entero termina en ROLLBACK, asi que esto es prolijidad: deja la
-- transaccion sin filas de prueba por si alguien corre el archivo a mano sin el rollback.
DO $$
DECLARE v_staff uuid; v_pac uuid; v_esp uuid;
BEGIN
  IF coalesce(current_setting('probe.ls_ready', true),'') <> '1' THEN RETURN; END IF;
  v_staff := current_setting('probe.ls_staff', true)::uuid;
  v_pac   := current_setting('probe.ls_pac',   true)::uuid;
  v_esp   := current_setting('probe.ls_esp',   true)::uuid;
  DELETE FROM pacientes     WHERE auth_user_id = v_pac;
  DELETE FROM medicos       WHERE id = v_staff;
  DELETE FROM perfiles      WHERE id = v_staff;
  DELETE FROM especialidades WHERE id = v_esp;
  DELETE FROM auth.users    WHERE id IN (v_staff, v_pac);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('probe.ls_fx',
    coalesce(current_setting('probe.ls_fx', true),'') || ' | limpieza fallo ('||SQLSTATE||')', false);
END $$;
SELECT set_config('role','none', true);

-- ============================================================
-- MIG 300 · fail-open trivaluado + funciones sin gate (FO_FX, P728-P738)
-- ============================================================
-- LA LAGUNA QUE ESTO CIERRA NO ES SOLO anon. P683-P685 (mig 291) ya probaban
-- obtener_contexto_visita, pero SIEMPRE con medicos autenticados, donde
-- `v_cita.medico_id = auth.uid()` compara dos uuid no nulos y da false limpio. El agujero vivia en
-- los dos casos que esas probes no tocaban: anon (auth.uid() NULL) y un authenticated cualquiera
-- sobre una cita SIN medico asignado (medico_id NULL). Por eso cada fail-open se prueba con LOS DOS
-- actores, y la cita del fixture es a proposito una sin medico.
--
-- LOS CONTROLES POSITIVOS SON LA MITAD QUE IMPORTA: "anon no puede" tambien lo cumple una funcion
-- que no le sirve a nadie. P730 y P733 verifican que el medico duenio sigue trabajando.
SELECT set_config('role','none', true);
DO $$
DECLARE v_pac constant uuid := '0dd0c68c-026c-4ebc-9475-e6791cc54933';
        v_med constant uuid := '09d243d5-b222-482a-9762-94a582e9e752';
        v_emp uuid; v_cnul bigint; v_cmed bigint; v_camp int;
BEGIN
  SELECT id INTO v_cnul FROM citas WHERE medico_id IS NULL ORDER BY id LIMIT 1;
  SELECT id INTO v_cmed FROM citas WHERE medico_id = v_med ORDER BY id LIMIT 1;
  SELECT empresa_id INTO v_emp FROM planes_visitador_contratados WHERE estado='activo' LIMIT 1;
  SELECT id INTO v_camp FROM campanas_publicitarias ORDER BY id LIMIT 1;

  IF v_cnul IS NULL OR v_cmed IS NULL OR v_emp IS NULL OR v_camp IS NULL THEN
    PERFORM set_config('probe.fo_fx','ROJO (faltan fixtures: cita_sin_medico='||coalesce(v_cnul::text,'-')
      ||' cita_del_medico='||coalesce(v_cmed::text,'-')||' empresa='||coalesce(v_emp::text,'-')
      ||' campana='||coalesce(v_camp::text,'-')||')', false);
    RETURN; END IF;

  PERFORM set_config('probe.fo_pac',  v_pac::text,  false);
  PERFORM set_config('probe.fo_med',  v_med::text,  false);
  PERFORM set_config('probe.fo_cnul', v_cnul::text, false);
  PERFORM set_config('probe.fo_cmed', v_cmed::text, false);
  PERFORM set_config('probe.fo_emp',  v_emp::text,  false);
  PERFORM set_config('probe.fo_camp', v_camp::text, false);
  PERFORM set_config('probe.fo_est0', (SELECT estado FROM citas WHERE id = v_cmed), false);
  PERFORM set_config('probe.fo_ready','1', false);
  PERFORM set_config('probe.fo_fx','OK (cita SIN medico='||v_cnul||' | cita del medico='||v_cmed
    ||' | empresa con planes | campana)', false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('probe.fo_fx','ROJO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;
SELECT set_config('role','none', true);

-- P728/P729 — actualizar_estado_cita: ESCRITURA. No alcanza con "no lanzo": se mira si el estado
-- cambio de verdad, porque una funcion puede correr sin error y no escribir (y al reves).
DO $$
DECLARE v_c bigint; v_e0 text; v_e1 text; v_err text;
BEGIN
  IF coalesce(current_setting('probe.fo_ready', true),'') <> '1' THEN
    PERFORM set_config('probe.p728','N/A (fixture FO_FX ausente)', false);
    PERFORM set_config('probe.p729','N/A (fixture FO_FX ausente)', false); RETURN; END IF;
  v_c := current_setting('probe.fo_cnul', true)::bigint;

  -- anon
  SELECT estado INTO v_e0 FROM citas WHERE id = v_c;
  PERFORM set_config('request.jwt.claims','{"role":"anon"}', true);
  v_err := '(sin error)';
  BEGIN PERFORM public.actualizar_estado_cita(v_c, 'no_show');
  EXCEPTION WHEN OTHERS THEN v_err := SQLSTATE; END;
  SELECT estado INTO v_e1 FROM citas WHERE id = v_c;
  PERFORM set_config('probe.p728', CASE WHEN v_e1 = v_e0
    THEN 'OK (anon no cambio el estado; err='||v_err||')'
    ELSE 'ROJO (anon cambio el estado de '||v_e0||' a '||v_e1||')' END, false);

  -- authenticated SIN rol
  PERFORM set_config('request.jwt.claims',
    json_build_object('sub', current_setting('probe.fo_pac', true), 'role','authenticated')::text, true);
  v_err := '(sin error)';
  BEGIN PERFORM public.actualizar_estado_cita(v_c, 'no_show');
  EXCEPTION WHEN OTHERS THEN v_err := SQLSTATE; END;
  SELECT estado INTO v_e1 FROM citas WHERE id = v_c;
  PERFORM set_config('probe.p729', CASE WHEN v_e1 = v_e0
    THEN 'OK (paciente sin rol no cambio el estado; err='||v_err||')'
    ELSE 'ROJO (un paciente cambio el estado de una cita ajena: '||v_e0||' -> '||v_e1||')' END, false);
  PERFORM set_config('request.jwt.claims','', true);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('probe.p728','FALLO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;
SELECT set_config('role','none', true);

-- P730 — CONTROL POSITIVO: el medico duenio SI puede sobre SU cita.
DO $$
DECLARE v_c bigint; v_e text;
BEGIN
  IF coalesce(current_setting('probe.fo_ready', true),'') <> '1' THEN
    PERFORM set_config('probe.p730','N/A (fixture FO_FX ausente)', false); RETURN; END IF;
  v_c := current_setting('probe.fo_cmed', true)::bigint;
  PERFORM set_config('request.jwt.claims',
    json_build_object('sub', current_setting('probe.fo_med', true), 'role','authenticated')::text, true);
  BEGIN
    PERFORM public.actualizar_estado_cita(v_c, 'confirmada');
    SELECT estado INTO v_e FROM citas WHERE id = v_c;
    PERFORM set_config('probe.p730', CASE WHEN v_e = 'confirmada'
      THEN 'OK (control positivo: el medico cambio SU cita)'
      ELSE 'ROJO (el medico no pudo: quedo en '||v_e||')' END, false);
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('probe.p730','ROJO ('||SQLSTATE||' '||SQLERRM||': la RPC quedo rota)', false);
  END;
  UPDATE citas SET estado = current_setting('probe.fo_est0', true) WHERE id = v_c;
  PERFORM set_config('request.jwt.claims','', true);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('probe.p730','FALLO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;
SELECT set_config('role','none', true);

-- P731/P732/P733 — obtener_contexto_visita. P732 es LA probe que faltaba: authenticated sin rol
-- contra una cita SIN medico asignado.
DO $$
DECLARE j jsonb; v_cnul bigint; v_cmed bigint;
BEGIN
  IF coalesce(current_setting('probe.fo_ready', true),'') <> '1' THEN
    PERFORM set_config('probe.p731','N/A (fixture FO_FX ausente)', false);
    PERFORM set_config('probe.p732','N/A (fixture FO_FX ausente)', false);
    PERFORM set_config('probe.p733','N/A (fixture FO_FX ausente)', false); RETURN; END IF;
  v_cnul := current_setting('probe.fo_cnul', true)::bigint;
  v_cmed := current_setting('probe.fo_cmed', true)::bigint;

  PERFORM set_config('request.jwt.claims','{"role":"anon"}', true);
  BEGIN SELECT public.obtener_contexto_visita(v_cnul) INTO j;
        PERFORM set_config('probe.p731','ROJO (anon obtuvo la nota clinica de una cita ajena)', false);
  EXCEPTION WHEN insufficient_privilege THEN PERFORM set_config('probe.p731','OK (42501)', false);
    WHEN OTHERS THEN PERFORM set_config('probe.p731','OK ('||SQLSTATE||')', false); END;

  PERFORM set_config('request.jwt.claims',
    json_build_object('sub', current_setting('probe.fo_pac', true), 'role','authenticated')::text, true);
  BEGIN SELECT public.obtener_contexto_visita(v_cnul) INTO j;
        PERFORM set_config('probe.p732','ROJO (un paciente obtuvo la nota de una cita SIN medico)', false);
  EXCEPTION WHEN insufficient_privilege THEN PERFORM set_config('probe.p732','OK (42501)', false);
    WHEN OTHERS THEN PERFORM set_config('probe.p732','OK ('||SQLSTATE||')', false); END;

  PERFORM set_config('request.jwt.claims',
    json_build_object('sub', current_setting('probe.fo_med', true), 'role','authenticated')::text, true);
  BEGIN SELECT public.obtener_contexto_visita(v_cmed) INTO j;
        PERFORM set_config('probe.p733', CASE WHEN j IS NOT NULL
          THEN 'OK (control positivo: el medico obtiene el contexto de SU cita)'
          ELSE 'ROJO (devolvio NULL al medico duenio)' END, false);
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('probe.p733','ROJO ('||SQLSTATE||': la RPC quedo rota para su duenio)', false); END;
  PERFORM set_config('request.jwt.claims','', true);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('probe.p731','FALLO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;
SELECT set_config('role','none', true);

-- P734/P735 — get_planes_visitador_proveedor con una empresa AJENA que SI tiene planes activos.
-- La empresa importa: con una sin planes, "0 filas" no distingue el gate del dato vacio.
DO $$
DECLARE n bigint; v_emp uuid;
BEGIN
  IF coalesce(current_setting('probe.fo_ready', true),'') <> '1' THEN
    PERFORM set_config('probe.p734','N/A (fixture FO_FX ausente)', false);
    PERFORM set_config('probe.p735','N/A (fixture FO_FX ausente)', false); RETURN; END IF;
  v_emp := current_setting('probe.fo_emp', true)::uuid;

  PERFORM set_config('request.jwt.claims','{"role":"anon"}', true);
  BEGIN SELECT count(*) INTO n FROM public.get_planes_visitador_proveedor(v_emp);
        PERFORM set_config('probe.p734', CASE WHEN n = 0 THEN 'OK (0 filas)'
          ELSE 'ROJO (anon leyo '||n||' planes de una empresa ajena)' END, false);
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p734','OK ('||SQLSTATE||')', false); END;

  PERFORM set_config('request.jwt.claims',
    json_build_object('sub', current_setting('probe.fo_pac', true), 'role','authenticated')::text, true);
  BEGIN SELECT count(*) INTO n FROM public.get_planes_visitador_proveedor(v_emp);
        PERFORM set_config('probe.p735', CASE WHEN n = 0 THEN 'OK (0 filas)'
          ELSE 'ROJO (un paciente leyo '||n||' planes de una empresa ajena)' END, false);
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p735','OK ('||SQLSTATE||')', false); END;
  PERFORM set_config('request.jwt.claims','', true);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('probe.p734','FALLO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;
SELECT set_config('role','none', true);

-- P736 — registrar_campana_metrica: se mide el DELTA, no el error. Es la unica forma de distinguir
-- "corto" de "corrio y escribio igual".
DO $$
DECLARE n0 bigint; n1 bigint; v_err text := '(sin error)';
BEGIN
  IF coalesce(current_setting('probe.fo_ready', true),'') <> '1' THEN
    PERFORM set_config('probe.p736','N/A (fixture FO_FX ausente)', false); RETURN; END IF;
  SELECT count(*) INTO n0 FROM campana_metricas;
  PERFORM set_config('request.jwt.claims','{"role":"anon"}', true);
  BEGIN
    PERFORM public.registrar_campana_metrica(current_setting('probe.fo_camp', true)::int,
              NULL, NULL, 'p736', 'p736', true, 'P736', NULL);
  EXCEPTION WHEN OTHERS THEN v_err := SQLSTATE; END;
  SELECT count(*) INTO n1 FROM campana_metricas;
  PERFORM set_config('probe.p736', CASE WHEN n1 = n0
    THEN 'OK (anon no escribio; err='||v_err||')'
    ELSE 'ROJO (anon inserto '||(n1-n0)||' fila(s) en campana_metricas)' END, false);
  PERFORM set_config('request.jwt.claims','', true);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('probe.p736','FALLO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;
SELECT set_config('role','none', true);

-- P737 — los dos de slots: anon cortado, y CONTROL POSITIVO con un authenticated real, porque los
-- llaman AgendarCitaModal y useVisitasAgendadas y romperlos rompe el agendado de citas.
DO $$
DECLARE n bigint; v_med uuid; v_mal text := ''; v_ok text := '';
BEGIN
  IF coalesce(current_setting('probe.fo_ready', true),'') <> '1' THEN
    PERFORM set_config('probe.p737','N/A (fixture FO_FX ausente)', false); RETURN; END IF;
  v_med := current_setting('probe.fo_med', true)::uuid;

  PERFORM set_config('request.jwt.claims','{"role":"anon"}', true);
  BEGIN SELECT count(*) INTO n FROM public.slots_ocupados_cita(v_med, '2000-01-01','2035-01-01');
        v_mal := v_mal || 'slots_ocupados_cita respondio a anon ('||n||' filas); ';
  EXCEPTION WHEN OTHERS THEN v_ok := v_ok || 'slots_cita corta ('||SQLSTATE||'); '; END;
  BEGIN SELECT count(*) INTO n FROM public.get_slots_ocupados(v_med, '2000-01-01','2035-01-01');
        v_mal := v_mal || 'get_slots_ocupados respondio a anon ('||n||' filas); ';
  EXCEPTION WHEN OTHERS THEN v_ok := v_ok || 'get_slots corta ('||SQLSTATE||'); '; END;

  PERFORM set_config('request.jwt.claims',
    json_build_object('sub', current_setting('probe.fo_pac', true), 'role','authenticated')::text, true);
  BEGIN SELECT count(*) INTO n FROM public.slots_ocupados_cita(v_med, '2000-01-01','2035-01-01');
        IF n = 0 THEN v_mal := v_mal || 'CONTROL+ slots_ocupados_cita devolvio 0 a un authenticated; ';
        ELSE v_ok := v_ok || 'CONTROL+ authenticated ve '||n||' slots; '; END IF;
  EXCEPTION WHEN OTHERS THEN v_mal := v_mal || 'CONTROL+ slots_ocupados_cita fallo ('||SQLSTATE||'); '; END;
  BEGIN PERFORM count(*) FROM public.get_slots_ocupados(v_med, '2000-01-01','2035-01-01');
        v_ok := v_ok || 'CONTROL+ get_slots responde; ';
  EXCEPTION WHEN OTHERS THEN v_mal := v_mal || 'CONTROL+ get_slots_ocupados fallo ('||SQLSTATE||'); '; END;

  PERFORM set_config('probe.p737', CASE WHEN v_mal = '' THEN 'OK ('||v_ok||')' ELSE 'ROJO ('||v_mal||')' END, false);
  PERFORM set_config('request.jwt.claims','', true);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('probe.p737','FALLO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;
SELECT set_config('role','none', true);

-- P738 — las dos que pierden EXECUTE, y la contraparte que NO se puede romper: la llamada interna.
-- Se ejercita con una SECDEF propia en vez de invocar notificar_campana_enviada, que manda
-- notificaciones de verdad — un harness no puede tener efectos sobre datos de gente.
DO $$
DECLARE n bigint; v_mal text := '';
BEGIN
  IF has_function_privilege('anon','public.obtener_admins_ezpay()','EXECUTE')
     OR has_function_privilege('authenticated','public.obtener_admins_ezpay()','EXECUTE') THEN
    v_mal := v_mal || 'obtener_admins_ezpay sigue ejecutable; '; END IF;
  IF has_function_privilege('anon','public.obtener_clinica_principal_medico(uuid)','EXECUTE')
     OR has_function_privilege('authenticated','public.obtener_clinica_principal_medico(uuid)','EXECUTE') THEN
    v_mal := v_mal || 'obtener_clinica_principal_medico sigue ejecutable; '; END IF;
  IF EXISTS (SELECT 1 FROM pg_proc pr, unnest(coalesce(pr.proacl,'{}'::aclitem[])) a
              WHERE pr.oid IN ('public.obtener_admins_ezpay()'::regprocedure,
                               'public.obtener_clinica_principal_medico(uuid)'::regprocedure)
                AND a::text LIKE '=%') THEN
    v_mal := v_mal || 'PUBLIC conserva EXECUTE en alguna de las dos; '; END IF;

  BEGIN
    EXECUTE 'CREATE FUNCTION public._p738_interna() RETURNS bigint LANGUAGE sql SECURITY DEFINER '
         || 'SET search_path TO ''public'' AS ''SELECT count(*) FROM public.obtener_admins_ezpay()''';
    PERFORM set_config('request.jwt.claims',
      json_build_object('sub', current_setting('probe.fo_pac', true), 'role','authenticated')::text, true);
    SELECT public._p738_interna() INTO n;
    IF coalesce(n,0) = 0 THEN v_mal := v_mal || 'la llamada INTERNA devolvio 0: se rompio la cadena; '; END IF;
    PERFORM set_config('request.jwt.claims','', true);
    EXECUTE 'DROP FUNCTION public._p738_interna()';
  EXCEPTION WHEN OTHERS THEN
    v_mal := v_mal || 'la llamada INTERNA fallo ('||SQLSTATE||'); ';
  END;

  PERFORM set_config('probe.p738', CASE WHEN v_mal = ''
    THEN 'OK (sin EXECUTE para anon/authenticated/PUBLIC, y la llamada interna sigue viva)'
    ELSE 'ROJO ('||v_mal||')' END, false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('probe.p738','FALLO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;
SELECT set_config('role','none', true);

-- ============================================================
-- MIG 301 · anon sin EXECUTE en 49 funciones + fabrica cerrada (P739-P744)
-- ============================================================
-- P739 es un CENSO, no una muestra: mide QUE conjunto de SECDEF de public le queda ejecutable a
-- anon, no cuantas. Una probe que mirara 3 nombres fijos se volveria muda el dia que aparezca la
-- cuarta; una que solo contara 11 se quedaria callada si se va una y entra otra. Por eso compara
-- el CONJUNTO contra la lista esperada y publica lo que sobra y lo que falta.
--
-- Las esperadas eran 11 en dos grupos; desde la mig 327 quedan 10:
--   · `registrar_proveedor` — era la unica excepcion por PRODUCTO (flujo pre-login). La mig 327 le
--     revoco anon y PUBLIC: el alta real corre con sesion (signUp con autoconfirm devuelve sesion).
--     Ya NO esta en la lista; si reaparece con EXECUTE para anon, P739 la marca como "sobra".
--   · las 10 — excepcion TECNICA: viven dentro del USING de policies RLS sobre 30 tablas
--     donde anon tiene SELECT. Una policy se evalua con los privilegios del LLAMANTE (mig 284),
--     asi que revocarles el EXECUTE no le niega nada a anon: hace que esas 30 tablas le lancen
--     42501. Quedan afuera del barrido a proposito. Sacarlas de verdad exige reescribir las
--     policies para que no dependan de ellas — frente propio, pendiente.
SELECT set_config('role','none', true);
DO $$
DECLARE v_sobran text; v_faltan text; v_n int;
  esperadas constant text[] := ARRAY[
    'get_auth_user_rol','get_auth_user_pais_id','mi_empresa_proveedor','mi_rol_proveedor',
    'mi_clinica_id','puede_ver_conversacion','supervisa_cuenta_proveedor',
    'get_empresa_id_proveedor','get_empresa_id_session','admin_clinica_de_medico'];
BEGIN
  SELECT count(*) INTO v_n FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
   WHERE n.nspname='public' AND p.prosecdef AND has_function_privilege('anon', p.oid,'EXECUTE');

  SELECT string_agg(DISTINCT p.proname, ', ') INTO v_sobran
    FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
   WHERE n.nspname='public' AND p.prosecdef AND has_function_privilege('anon', p.oid,'EXECUTE')
     AND NOT (p.proname = ANY(esperadas));

  SELECT string_agg(e, ', ') INTO v_faltan FROM unnest(esperadas) e
   WHERE NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
                      WHERE n.nspname='public' AND p.proname = e
                        AND has_function_privilege('anon', p.oid,'EXECUTE'));

  PERFORM set_config('probe.p739', CASE
    WHEN v_sobran IS NULL AND v_faltan IS NULL
      THEN 'OK (quedan las 10 esperadas: las usadas en policies; registrar_proveedor sin anon desde la 327)'
    WHEN v_faltan IS NOT NULL
      THEN 'ROJO (el barrido se paso: perdieron anon '||v_faltan||')'
    ELSE 'ROJO ('||v_n||' ejecutables por anon; sobran: '||left(v_sobran,200)||')'
    END, false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('probe.p739','FALLO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;

-- P740 — anon EJERCITADO sobre una muestra de las REVOCADAS. El catalogo dice quien tiene que;
-- esto dice que pasa cuando se usa (leccion de la mig 284). La muestra NO puede incluir ninguna
-- de las 10 que quedan: seria un chequeo que pasa siempre y no mide nada.
DO $$
DECLARE v_mal text := ''; v_ok int := 0; t text;
BEGIN
  PERFORM set_config('request.jwt.claims','{"role":"anon"}', true);
  PERFORM set_config('role','anon', true);
  -- La muestra son EXPRESIONES DE LLAMADA, no nombres: dos de estas toman parametro y un
  -- `%I()` pelado habria dado 42883 (funcion inexistente) en vez de 42501, o sea verde por el
  -- motivo equivocado. El valor del argumento da igual: el ACL se chequea antes de ejecutar.
  FOREACH t IN ARRAY ARRAY['paciente_examenes()','mis_conversaciones()','contactos_chat()',
                           'afiliaciones_de_clinica()','estado_plan_visitas()',
                           'puede_auditar_chat()','destinatarios_conversacion(NULL::uuid)',
                           'mensajes_conversacion(NULL::uuid)'] LOOP
    BEGIN
      EXECUTE 'SELECT public.' || t;
      v_mal := v_mal || t || ' respondio; ';
    EXCEPTION WHEN insufficient_privilege THEN v_ok := v_ok + 1;
      WHEN OTHERS THEN v_mal := v_mal || t || '=' || SQLSTATE || ' (se esperaba 42501); ';
    END;
  END LOOP;
  PERFORM set_config('role','none', true);
  PERFORM set_config('probe.p740', CASE WHEN v_mal = ''
    THEN 'OK ('||v_ok||'/8 dan 42501 a anon)' ELSE 'ROJO ('||v_mal||')' END, false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('role','none', true);
  PERFORM set_config('probe.p740','FALLO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;
SELECT set_config('role','none', true);

-- P741 — CONTROL NEGATIVO de la excepcion tecnica. Sin esta, P739/P740 en verde tambien los cumpliria
-- un REVOKE a todo el mundo, que dejaria 30 tablas tirando 42501. Desde la mig 327 registrar_proveedor
-- se controla al reves: tiene que estar SIN anon (lo ejercita P833).
-- Por eso no alcanza con mirar el ACL de las 10: se EJERCITA una muestra de las tablas que las
-- llaman desde su USING, que es donde el sintoma aparece de verdad.
DO $$
DECLARE v_mal text := ''; t text; v_n int;
BEGIN
  IF has_function_privilege('anon',
    'public.registrar_proveedor(text,text,text,uuid,text,text,text,text,text,text)','EXECUTE') THEN
    v_mal := v_mal || 'registrar_proveedor recupero anon (la mig 327 se lo revoco); ';
  END IF;

  FOREACH t IN ARRAY ARRAY['get_auth_user_rol','get_auth_user_pais_id','mi_empresa_proveedor',
                           'mi_rol_proveedor','mi_clinica_id','puede_ver_conversacion',
                           'supervisa_cuenta_proveedor','get_empresa_id_proveedor',
                           'get_empresa_id_session','admin_clinica_de_medico'] LOOP
    SELECT count(*) INTO v_n FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
     WHERE n.nspname='public' AND p.proname=t AND has_function_privilege('anon', p.oid,'EXECUTE');
    IF v_n = 0 THEN v_mal := v_mal || t || ' perdio anon (la usan policies); '; END IF;
  END LOOP;

  PERFORM set_config('request.jwt.claims','{"role":"anon"}', true);
  PERFORM set_config('role','anon', true);
  FOREACH t IN ARRAY ARRAY['perfiles','citas','cuentas_proveedor','pacientes','clinicas'] LOOP
    BEGIN
      EXECUTE format('SELECT count(*) FROM public.%I', t) INTO v_n;
    EXCEPTION WHEN insufficient_privilege THEN
      -- 42501 CON grant = policy rota (perfiles/cuentas_proveedor/pacientes kept); SIN grant (citas/clinicas revocadas) = correcto.
      IF has_table_privilege('anon','public.'||t,'SELECT') THEN v_mal := v_mal || 'la tabla '||t||' lanza 42501 CON grant a anon (policy rota); '; END IF;
      WHEN OTHERS THEN v_mal := v_mal || 'la tabla '||t||' dio '||SQLSTATE||' a anon; ';
    END;
  END LOOP;
  PERFORM set_config('role','none', true);
  PERFORM set_config('request.jwt.claims','', true);

  PERFORM set_config('probe.p741', CASE WHEN v_mal = ''
    THEN 'OK (registrar_proveedor sin anon; las 10 de policies intactas; 5 tablas: 0 filas (kept) o 42501-sin-grant (revocadas))'
    ELSE 'ROJO ('||v_mal||')' END, false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('role','none', true);
  PERFORM set_config('probe.p741','FALLO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;
SELECT set_config('role','none', true);

-- P742 — CONTROL POSITIVO: la cadena interna sigue viva. Una SECDEF de dueno postgres llama a una
-- de las REVOCADAS (no a una de las 11, que no probaria nada), invocada por un authenticated que
-- ya NO tiene EXECUTE sobre la de adentro.
DO $$
DECLARE v_mal text := '';
BEGIN
  BEGIN
    EXECUTE 'CREATE FUNCTION public._p742_cadena() RETURNS bigint LANGUAGE sql SECURITY DEFINER '
         || 'SET search_path TO ''public'' AS ''SELECT count(*) FROM public.contactos_chat()''';
    PERFORM set_config('request.jwt.claims',
      '{"sub":"0dd0c68c-026c-4ebc-9475-e6791cc54933","role":"authenticated"}', true);
    PERFORM set_config('role','authenticated', true);
    PERFORM public._p742_cadena();
    PERFORM set_config('role','none', true);
    PERFORM set_config('request.jwt.claims','', true);
    EXECUTE 'DROP FUNCTION public._p742_cadena()';
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    v_mal := 'la cadena interna fallo ('||SQLSTATE||')';
  END;
  PERFORM set_config('probe.p742', CASE WHEN v_mal = ''
    THEN 'OK (una SECDEF de postgres sigue llamando a una revocada)' ELSE 'ROJO ('||v_mal||')' END, false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('probe.p742','FALLO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;
SELECT set_config('role','none', true);

-- P743 — liberar_examen_al_paciente: el COALESCE. Se prueban los DOS actores contra un examen ajeno.
DO $$
DECLARE v_ex integer; j jsonb; v_mal text := '';
BEGIN
  SELECT id INTO v_ex FROM examenes ORDER BY id LIMIT 1;
  IF v_ex IS NULL THEN
    PERFORM set_config('probe.p743','N/A (no hay examenes)', false); RETURN; END IF;

  PERFORM set_config('request.jwt.claims','{"role":"anon"}', true);
  PERFORM set_config('role','anon', true);
  BEGIN SELECT public.liberar_examen_al_paciente(v_ex) INTO j;
        v_mal := v_mal || 'anon libero; ';
  EXCEPTION WHEN OTHERS THEN NULL; END;
  PERFORM set_config('role','none', true);

  PERFORM set_config('request.jwt.claims',
    '{"sub":"0dd0c68c-026c-4ebc-9475-e6791cc54933","role":"authenticated"}', true);
  PERFORM set_config('role','authenticated', true);
  BEGIN SELECT public.liberar_examen_al_paciente(v_ex) INTO j;
        v_mal := v_mal || 'un authenticated sin relacion libero; ';
  EXCEPTION WHEN OTHERS THEN NULL; END;
  PERFORM set_config('role','none', true);
  PERFORM set_config('request.jwt.claims','', true);

  PERFORM set_config('probe.p743', CASE WHEN v_mal = ''
    THEN 'OK (ni anon ni un authenticated ajeno liberan)' ELSE 'ROJO ('||v_mal||')' END, false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('role','none', true);
  PERFORM set_config('probe.p743','FALLO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;
SELECT set_config('role','none', true);

-- P744 — LA FABRICA, ejercitada: se crean una funcion y una secuencia y se mira con que nacen. Es
-- la unica probe que cubre lo que la 301 NO pudo cerrar — la entrada de pg_default_acl de
-- supabase_admin, intocable desde esta conexion (42501). Hoy es inerte porque todo lo crea
-- `postgres`; si eso cambiara, esto se pone rojo sin que nadie tenga que sospecharlo.
DO $$
DECLARE v_mal text := '';
BEGIN
  BEGIN
    EXECUTE 'CREATE FUNCTION public._p744_nueva() RETURNS int LANGUAGE sql AS ''SELECT 1''';
    EXECUTE 'CREATE SEQUENCE public._p744_seq';
    IF has_function_privilege('anon','public._p744_nueva()','EXECUTE') THEN
      v_mal := v_mal || 'FUNCION nueva ejecutable por anon; '; END IF;
    IF EXISTS (SELECT 1 FROM pg_proc pr, unnest(coalesce(pr.proacl,'{}'::aclitem[])) a
                WHERE pr.oid='public._p744_nueva()'::regprocedure AND a::text LIKE '=%') THEN
      v_mal := v_mal || 'FUNCION nueva ejecutable por PUBLIC; '; END IF;
    IF has_sequence_privilege('anon','public._p744_seq','USAGE') THEN
      v_mal := v_mal || 'SECUENCIA nueva con USAGE para anon; '; END IF;
    EXECUTE 'DROP SEQUENCE public._p744_seq';
    EXECUTE 'DROP FUNCTION public._p744_nueva()';
  EXCEPTION WHEN OTHERS THEN v_mal := v_mal || 'no se pudo probar ('||SQLSTATE||'); ';
  END;
  PERFORM set_config('probe.p744', CASE WHEN v_mal = ''
    THEN 'OK (funcion y secuencia nuevas no le dan nada a anon/PUBLIC)'
    ELSE 'ROJO ('||v_mal||')' END, false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('probe.p744','FALLO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;
SELECT set_config('role','none', true);

-- ============================================================
-- MIG 302 · security_invoker en las 4 vistas de F8 (P745-P749)
-- ============================================================
-- Una vista SIN security_invoker corre con los privilegios de su DUENO. Las 4 son de `postgres`,
-- que tiene rolbypassrls: la RLS de las tablas base no se evaluaba, y `anon` —que tiene SELECT
-- sobre las 4— las leia enteras por REST sin sesion. Medido el 20-sep: v_pacientes_actividad
-- devolvia los 26 pacientes con nombre y telefono mientras la tabla `pacientes` le daba 0 al
-- mismo actor.
--
-- Estos 5 probes cubren los tres lados, porque los tres pueden romperse por separado:
--   P745-P747  la fuga esta cerrada (anon en cero)
--   P748       el actor LEGITIMO no se rompio (el paciente sigue viendo lo suyo)
--   P749       el CAMINO REAL no se rompio (service_role, que es quien las consulta de verdad)
-- Sin P748/P749, un cambio que dejara las vistas devolviendo 0 a todo el mundo daria verde en los
-- tres primeros y nadie se enteraria hasta ver un panel vacio.
SELECT set_config('role','none', true);

-- P745 — anon sobre v_pacientes_actividad. Es la que mas PHI expone por fila.
DO $$
DECLARE n bigint; n_base bigint; v_err text;
BEGIN
  SELECT count(*) INTO n_base FROM public.pacientes;   -- como postgres: el universo
  PERFORM set_config('request.jwt.claims','{"role":"anon"}', true);
  PERFORM set_config('role','anon', true);
  BEGIN
    SELECT count(*) INTO n FROM public.v_pacientes_actividad; v_err := NULL;
  EXCEPTION WHEN OTHERS THEN n := -1; v_err := SQLSTATE;
  END;
  PERFORM set_config('role','none', true);
  PERFORM set_config('request.jwt.claims','', true);
  PERFORM set_config('probe.p745', CASE
    WHEN n = 0 THEN 'OK (anon ve 0 de '||n_base||' pacientes)'
    WHEN n < 0 AND v_err='42501' AND has_table_privilege('anon','public.v_pacientes_actividad','SELECT')
      THEN 'ROJO (42501 CON grant (vista/policy rota): v_pacientes_actividad)'
    WHEN n < 0 AND v_err='42501' THEN 'OK (42501 sin grant: vista revocada tras 324)'
    WHEN n < 0 THEN 'FALLO ('||coalesce(v_err,'?')||')'
    ELSE 'ROJO (anon ve '||n||' filas de v_pacientes_actividad; nombre y telefono de cada paciente)'
    END, false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('role','none', true);
  PERFORM set_config('probe.p745','FALLO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;
SELECT set_config('role','none', true);

-- P746 — anon sobre v_citas_hoy, CON UNA CITA DE HOY SEMBRADA. La vista filtra
-- `WHERE fecha = CURRENT_DATE`: sin fixture, el dia que no haya agenda el probe daria 0 y seria
-- verde por estar vacia, no por estar protegida. Ese es exactamente el error que casi comete el
-- censo del 20-sep, que la midio un dia sin citas. El harness entero corre en BEGIN/ROLLBACK, asi
-- que la cita no persiste.
DO $$
DECLARE n bigint; v_pid bigint; v_mid uuid; v_hay bigint; v_err text;
BEGIN
  -- El medico se toma de `medicos`, NO de `perfiles WHERE rol='medico'`: citas.medico_id tiene
  -- FK `fk_citas_medico -> medicos(id)`, y un perfil con rol='medico' NO implica fila en
  -- `medicos`. Dos fixtures anteriores de este mismo harness (lineas ~10759 y ~13814) crean
  -- perfiles medico con gen_random_uuid() y sin fila en medicos, asi que la version anterior
  -- fallaba con 23503 cuando uno de esos uuid aleatorios ordenaba por debajo del primer medico
  -- real (~7% de las corridas). Paso tres veces y fallo a la cuarta: era intermitente, no rota.
  SELECT id INTO v_pid FROM public.pacientes ORDER BY id LIMIT 1;
  SELECT m.id INTO v_mid FROM public.medicos m ORDER BY m.id LIMIT 1;
  IF v_pid IS NULL OR v_mid IS NULL THEN
    PERFORM set_config('probe.p746','N/A (no hay paciente o medico para sembrar)', false); RETURN;
  END IF;

  INSERT INTO public.citas (medico_id, paciente_id, fecha, hora_inicio, hora_fin, estado, motivo)
  VALUES (v_mid, v_pid, CURRENT_DATE, '09:00', '09:30', 'agendada', 'FIXTURE P746');

  SELECT count(*) INTO v_hay FROM public.citas WHERE fecha = CURRENT_DATE;

  PERFORM set_config('request.jwt.claims','{"role":"anon"}', true);
  PERFORM set_config('role','anon', true);
  BEGIN
    SELECT count(*) INTO n FROM public.v_citas_hoy; v_err := NULL;
  EXCEPTION WHEN OTHERS THEN n := -1; v_err := SQLSTATE;
  END;
  PERFORM set_config('role','none', true);
  PERFORM set_config('request.jwt.claims','', true);

  PERFORM set_config('probe.p746', CASE
    WHEN v_hay = 0 THEN 'ROJO (la fixture no quedo: el probe no medira nada)'
    WHEN n = 0 THEN 'OK (anon ve 0 con '||v_hay||' cita(s) de HOY en la base)'
    WHEN n < 0 AND v_err='42501' AND has_table_privilege('anon','public.v_citas_hoy','SELECT')
      THEN 'ROJO (42501 CON grant (vista/policy rota): v_citas_hoy)'
    WHEN n < 0 AND v_err='42501' THEN 'OK (42501 sin grant: v_citas_hoy revocada tras 324)'
    WHEN n < 0 THEN 'FALLO ('||coalesce(v_err,'?')||')'
    ELSE 'ROJO (anon ve '||n||' cita(s) de hoy: paciente, telefono y medico)'
    END, false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('role','none', true);
  PERFORM set_config('request.jwt.claims','', true);
  PERFORM set_config('probe.p746','FALLO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;
SELECT set_config('role','none', true);

-- P747 — anon sobre las otras dos. Agregados del negocio, no PHI individual, pero la misma clase.
DO $$
DECLARE v_mal text := ''; t text; n bigint;
BEGIN
  PERFORM set_config('request.jwt.claims','{"role":"anon"}', true);
  PERFORM set_config('role','anon', true);
  FOREACH t IN ARRAY ARRAY['v_estadisticas_medico','v_resumen_mensual'] LOOP
    BEGIN
      EXECUTE format('SELECT count(*) FROM public.%I', t) INTO n;
      IF n <> 0 THEN v_mal := v_mal || t||'='||n||' filas; '; END IF;
    EXCEPTION WHEN insufficient_privilege THEN
      -- 42501 CON grant (vista kept) = rota; SIN grant (vista revocada) = correcto.
      IF has_table_privilege('anon','public.'||t,'SELECT') THEN v_mal := v_mal || t||'=42501 CON grant (vista rota); '; END IF;
      WHEN OTHERS THEN v_mal := v_mal || t||'='||SQLSTATE||'; ';
    END;
  END LOOP;
  PERFORM set_config('role','none', true);
  PERFORM set_config('request.jwt.claims','', true);
  PERFORM set_config('probe.p747', CASE WHEN v_mal = ''
    THEN 'OK (anon ve 0 filas o 42501-sin-grant en las dos)' ELSE 'ROJO ('||v_mal||')' END, false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('role','none', true);
  PERFORM set_config('probe.p747','FALLO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;
SELECT set_config('role','none', true);

-- P748 — CONTROL POSITIVO: el paciente sigue viendo SU fila, y solo la suya. security_invoker no
-- apaga la vista: le aplica RLS fila por fila. El paciente pasa de ver 26 a ver 1 por la policy
-- `Paciente ve su perfil` (auth_user_id = auth.uid()) sobre `pacientes`. Un 0 aca seria tan malo
-- como un 26: querria decir que el fix rompio al actor legitimo.
DO $$
DECLARE n bigint; n_base bigint; v_pac constant uuid := '0dd0c68c-026c-4ebc-9475-e6791cc54933';
BEGIN
  SELECT count(*) INTO n_base FROM public.pacientes;
  PERFORM set_config('request.jwt.claims',
    json_build_object('sub', v_pac, 'role','authenticated')::text, true);
  PERFORM set_config('role','authenticated', true);
  BEGIN
    SELECT count(*) INTO n FROM public.v_pacientes_actividad;
  EXCEPTION WHEN OTHERS THEN n := -1;
  END;
  PERFORM set_config('role','none', true);
  PERFORM set_config('request.jwt.claims','', true);
  PERFORM set_config('probe.p748', CASE
    WHEN n = 1 THEN 'OK (el paciente ve su fila y solo la suya, de '||n_base||')'
    WHEN n = 0 THEN 'ROJO (el paciente ve 0: el fix rompio al actor legitimo)'
    WHEN n < 0 THEN 'ROJO (error al ejercitar la vista como el paciente)'
    ELSE 'ROJO (el paciente ve '||n||' filas: ve pacientes ajenos)'
    END, false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('role','none', true);
  PERFORM set_config('request.jwt.claims','', true);
  PERFORM set_config('probe.p748','FALLO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;
SELECT set_config('role','none', true);

-- P749 — CONTROL POSITIVO: service_role sigue viendo las 4 completas. Es el camino de lectura REAL:
-- reportes-detalle, exportar-csv y reportes-resumen consultan estas vistas con
-- createClient(url, SERVICE_ROLE_KEY) —el cliente anon+JWT lo usan solo para getUser()—, y
-- service_role tiene rolbypassrls. Este probe es lo que protege esos 5 call-sites de que alguien
-- "endurezca" las vistas mas adelante y vacie el panel de reportes sin darse cuenta.
DO $$
DECLARE v_mal text := ''; n bigint; n_pac bigint;
BEGIN
  SELECT count(*) INTO n_pac FROM public.pacientes;
  PERFORM set_config('request.jwt.claims','{"role":"service_role"}', true);
  PERFORM set_config('role','service_role', true);
  BEGIN
    SELECT count(*) INTO n FROM public.v_pacientes_actividad;
    IF n <> n_pac THEN v_mal := v_mal || 'v_pacientes_actividad='||n||' de '||n_pac||'; '; END IF;
    SELECT count(*) INTO n FROM public.v_estadisticas_medico;
    IF n = 0 THEN v_mal := v_mal || 'v_estadisticas_medico=0; '; END IF;
    SELECT count(*) INTO n FROM public.v_resumen_mensual;
    IF n = 0 THEN v_mal := v_mal || 'v_resumen_mensual=0; '; END IF;
    PERFORM count(*) FROM public.v_citas_hoy;   -- puede ser 0 legitimamente (depende del dia)
  EXCEPTION WHEN OTHERS THEN v_mal := v_mal || 'error '||SQLSTATE||'; ';
  END;
  PERFORM set_config('role','none', true);
  PERFORM set_config('request.jwt.claims','', true);
  PERFORM set_config('probe.p749', CASE WHEN v_mal = ''
    THEN 'OK (service_role ve las 4; los 5 call-sites de reportes intactos)'
    ELSE 'ROJO ('||v_mal||')' END, false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('role','none', true);
  PERFORM set_config('request.jwt.claims','', true);
  PERFORM set_config('probe.p749','FALLO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;
SELECT set_config('role','none', true);

-- ============================================================
-- MIG 303 · gate en crear_clinica_con_dueno + camino interno separado (P750-P754)
-- ============================================================
-- La RPC era SECDEF sin gate y la ejecuta `authenticated`: creaba clinicas y membresias a nombre
-- de cualquier medico. El gate reproduce las dos policies de INSERT que la tabla `clinicas` ya
-- tenia y que la RPC salteaba por ser SECURITY DEFINER.
--
-- Los 5 probes son los 5 caminos reales, y los positivos pesan tanto como los negativos:
--   P750 el dueno legitimo                     -> funciona
--   P751 un medico a nombre de OTRO            -> 42501
--   P752 un actor sin relacion (paciente)      -> 42501
--   P753 super_admin a nombre de un medico     -> funciona  (brazo puede_admin_pais)
--   P754 RUTA B de punta a punta               -> funciona  (camino interno, auth.uid() NULL)
--
-- P754 es el que sostiene todo el diseno. La Ruta B (invitacion de admin EzPay sin clinica) corre
-- por la edge `registrar-medico-invitacion` con service_role, ANTES de que exista sesion:
-- auth.uid() es NULL. Un gate con COALESCE en la funcion publica la rechaza con 42501 — medido, y
-- contraprobado por mutacion. Por eso el cuerpo vive en private y la Ruta B lo llama directo.
-- Sin P754, alguien "simplifica" volviendo a enrutar la Ruta B por la publica y rompe el alta de
-- medicos sin que ningun probe se entere.
--
-- Cada probe revierte sus propias escrituras con una subtransaccion (RAISE con marcador): si no,
-- las clinicas que siembra uno contaminarian los conteos del siguiente.
SELECT set_config('role','none', true);

DO $$
DECLARE
  v_pais uuid; v_med uuid; v_med2 uuid; v_sa uuid; v_sint uuid; v_id uuid; v_n bigint;
  v_pac constant uuid := '0dd0c68c-026c-4ebc-9475-e6791cc54933';
  v_tok uuid; v_r text;
BEGIN
  SELECT id INTO v_pais FROM public.configuracion_pais WHERE activo LIMIT 1;
  SELECT id INTO v_sa   FROM public.perfiles WHERE rol='super_admin' AND activo LIMIT 1;
  -- medicos con fila REAL en `medicos`: medico_clinicas.medico_id tiene FK a medicos, asi que un
  -- doctor_id que no este ahi fallaria por FK y no por el gate (mediria otra cosa).
  SELECT m.id INTO v_med  FROM public.medicos m ORDER BY m.id LIMIT 1;
  SELECT m.id INTO v_med2 FROM public.medicos m WHERE m.id <> v_med ORDER BY m.id LIMIT 1;
  SELECT pf.id INTO v_sint FROM public.perfiles pf
   WHERE NOT EXISTS (SELECT 1 FROM public.medicos m WHERE m.id = pf.id)
     AND pf.id <> v_pac AND coalesce(pf.rol,'') <> 'super_admin' ORDER BY pf.id LIMIT 1;

  IF v_pais IS NULL OR v_med IS NULL OR v_sa IS NULL THEN
    PERFORM set_config('probe.p750','N/A (faltan actores)', false);
    PERFORM set_config('probe.p751','N/A (faltan actores)', false);
    PERFORM set_config('probe.p752','N/A (faltan actores)', false);
    PERFORM set_config('probe.p753','N/A (faltan actores)', false);
    PERFORM set_config('probe.p754','N/A (faltan actores)', false);
    RETURN;
  END IF;

  -- ---------------------------------------------------------------- P750
  v_r := 'no se ejecuto';
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',v_med,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    v_id := public.crear_clinica_con_dueno(v_med, 'PROBE P750', v_pais);
    PERFORM set_config('role','none', true);
    IF v_id IS NULL THEN v_r := 'ROJO (devolvio NULL)';
    ELSIF NOT EXISTS (SELECT 1 FROM public.medico_clinicas mc
                       WHERE mc.clinica_id=v_id AND mc.medico_id=v_med) THEN
      v_r := 'ROJO (creo la clinica pero no la membresia: se perdio la atomicidad)';
    ELSE v_r := 'OK (el dueno crea la suya, con membresia)'; END IF;
    RAISE EXCEPTION 'P750_RB';
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    IF SQLERRM <> 'P750_RB' THEN v_r := 'ROJO (el dueno legitimo fue rechazado: '||SQLSTATE||')'; END IF;
  END;
  PERFORM set_config('probe.p750', v_r, false);

  -- ---------------------------------------------------------------- P751
  IF v_med2 IS NULL THEN
    PERFORM set_config('probe.p751','N/A (hay un solo medico en la base)', false);
  ELSE
    v_r := 'ROJO (un medico creo una clinica a nombre de OTRO)';
    BEGIN
      PERFORM set_config('request.jwt.claims', json_build_object('sub',v_med,'role','authenticated')::text, true);
      PERFORM set_config('role','authenticated', true);
      PERFORM public.crear_clinica_con_dueno(v_med2, 'PROBE P751', v_pais);
      PERFORM set_config('role','none', true);
      RAISE EXCEPTION 'P751_RB';
    EXCEPTION WHEN OTHERS THEN
      PERFORM set_config('role','none', true);
      IF SQLSTATE = '42501' THEN v_r := 'OK (42501)';
      ELSIF SQLERRM <> 'P751_RB' THEN v_r := 'ROJO (corto con '||SQLSTATE||', se esperaba 42501)'; END IF;
    END;
    PERFORM set_config('probe.p751', v_r, false);
  END IF;

  -- ---------------------------------------------------------------- P752
  v_r := 'ROJO (un paciente creo una clinica a nombre de un medico)';
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',v_pac,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    PERFORM public.crear_clinica_con_dueno(v_med, 'PROBE P752', v_pais);
    PERFORM set_config('role','none', true);
    RAISE EXCEPTION 'P752_RB';
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    IF SQLSTATE = '42501' THEN v_r := 'OK (42501)';
    ELSIF SQLERRM <> 'P752_RB' THEN v_r := 'ROJO (corto con '||SQLSTATE||', se esperaba 42501)'; END IF;
  END;
  PERFORM set_config('probe.p752', v_r, false);

  -- ---------------------------------------------------------------- P753
  -- CONTROL POSITIVO del brazo puede_admin_pais: un gate que solo mirara auth.uid() daria verde en
  -- P750-P752 y le romperia el alta administrativa a super_admin/admin_pais, que la tabla YA permite.
  v_r := 'no se ejecuto';
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',v_sa,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    v_id := public.crear_clinica_con_dueno(v_med, 'PROBE P753', v_pais);
    PERFORM set_config('role','none', true);
    v_r := CASE WHEN v_id IS NULL THEN 'ROJO (devolvio NULL)'
                ELSE 'OK (super_admin crea a nombre de un medico)' END;
    RAISE EXCEPTION 'P753_RB';
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    IF SQLERRM <> 'P753_RB' THEN v_r := 'ROJO (el super_admin fue rechazado: '||SQLSTATE||')'; END IF;
  END;
  PERFORM set_config('probe.p753', v_r, false);

  -- ---------------------------------------------------------------- P754
  IF v_sint IS NULL THEN
    PERFORM set_config('probe.p754','N/A (no hay perfil sin fila en medicos para el alta)', false);
  ELSE
    v_r := 'no se ejecuto';
    BEGIN
      v_tok := gen_random_uuid();
      INSERT INTO public.invitaciones_medico
        (id, token, pais_id, email, nombre_completo, clinica_id, estado, expires_at)
      VALUES (gen_random_uuid(), v_tok, v_pais, 'probe754@ezpay.test', 'Probe 754',
              NULL, 'pendiente', now() + interval '1 day');

      PERFORM set_config('request.jwt.claims','{"role":"service_role"}', true);
      PERFORM set_config('role','service_role', true);
      PERFORM public.registrar_medico_desde_invitacion(
        v_tok, v_sint, 'probe754@ezpay.test', 'Probe 754');
      PERFORM set_config('role','none', true);
      PERFORM set_config('request.jwt.claims','', true);

      SELECT count(*) INTO v_n
        FROM public.clinicas c
        JOIN public.medico_clinicas mc ON mc.clinica_id=c.id AND mc.medico_id=v_sint
       WHERE c.doctor_id=v_sint AND c.nombre='Consultorio Probe 754';
      v_r := CASE WHEN v_n = 1
                  THEN 'OK (la Ruta B crea el consultorio con auth.uid() NULL)'
                  ELSE 'ROJO (la Ruta B no dejo el consultorio: '||v_n||')' END;
      RAISE EXCEPTION 'P754_RB';
    EXCEPTION WHEN OTHERS THEN
      PERFORM set_config('role','none', true);
      PERFORM set_config('request.jwt.claims','', true);
      IF SQLERRM <> 'P754_RB' THEN
        v_r := 'ROJO (la Ruta B se rompio: '||SQLSTATE||' '||SQLERRM||')';
      END IF;
    END;
    PERFORM set_config('probe.p754', v_r, false);
  END IF;

  PERFORM set_config('request.jwt.claims','', true);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('role','none', true);
  PERFORM set_config('request.jwt.claims','', true);
  PERFORM set_config('probe.p750', coalesce(current_setting('probe.p750', true),'FALLO ('||SQLSTATE||')'), false);
  PERFORM set_config('probe.p754','FALLO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;
SELECT set_config('role','none', true);

-- ============================================================
-- MIG 304 · configuracion_sistema oculta los datos bancarios a anon (P755-P758)
-- ============================================================
-- La policy "Cualquiera lee configuracion" era FOR SELECT TO public USING (true), y anon tiene
-- SELECT sobre la tabla: las 21 filas se leian por REST sin sesion, incluidas 5 de cobro (banco,
-- cuenta_bancaria, tipo_cuenta, titular_cuenta, email_pagos). Se reemplazo por dos policies con
-- el rol nombrado — `TO public` no sirve para la excepcion porque public tambien alcanza a
-- authenticated.
--
-- Los 4 probes cubren los tres lados, y los positivos pesan tanto como el negativo:
--   P755 anon NO ve las 5           (la fuga, cerrada; se verifica por NOMBRE de clave)
--   P756 anon SI ve las otras 16    (control positivo: no se cerro de mas)
--   P757 authenticated ve las 21    (el camino que no debia tocarse)
--   P758 service_role ve las 21     (la edge actualizar-configuracion)
-- Sin P756/P757/P758, una policy que devolviera 0 filas a todo el mundo daria verde en P755 y
-- romperia el branding del front publico y el panel de configuracion sin que nadie se entere.
SELECT set_config('role','none', true);

DO $$
DECLARE
  v_tot bigint; v_n bigint; v_l text;
  bancarias constant text[] := ARRAY['banco','cuenta_bancaria','tipo_cuenta','titular_cuenta','email_pagos'];
BEGIN
  SELECT count(*) INTO v_tot FROM public.configuracion_sistema;

  -- ---------------------------------------------------------------- P755 / P756 (anon)
  PERFORM set_config('request.jwt.claims','{"role":"anon"}', true);
  PERFORM set_config('role','anon', true);
  BEGIN
    SELECT count(*), string_agg(clave, ', ' ORDER BY clave) INTO v_n, v_l
      FROM public.configuracion_sistema WHERE clave = ANY(bancarias);
    PERFORM set_config('probe.p755', CASE WHEN v_n = 0
      THEN 'OK (anon no ve ninguna de las 5 claves bancarias)'
      ELSE 'ROJO (anon ve '||v_n||': '||coalesce(v_l,'')||')' END, false);
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('probe.p755','FALLO ('||SQLSTATE||')', false);
  END;

  BEGIN
    SELECT count(*) INTO v_n FROM public.configuracion_sistema;
    SELECT count(*) INTO v_tot FROM (SELECT 1 FROM public.configuracion_sistema
      WHERE clave IN ('app_nombre','color_primario','sistema_moneda','notif_email_activo')) s;
    PERFORM set_config('probe.p756', CASE
      WHEN v_n = 0 THEN 'ROJO (anon ve 0 filas: se cerro de mas, se rompe el branding publico)'
      WHEN v_tot <> 4 THEN 'ROJO (anon solo ve '||v_tot||' de las 4 claves de branding/sistema)'
      ELSE 'OK (anon ve '||v_n||' filas no bancarias, con las 4 de branding/sistema)' END, false);
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('probe.p756','FALLO ('||SQLSTATE||')', false);
  END;
  PERFORM set_config('role','none', true);
  PERFORM set_config('request.jwt.claims','', true);

  -- ---------------------------------------------------------------- P757 (authenticated)
  SELECT count(*) INTO v_tot FROM public.configuracion_sistema;   -- universo, como postgres
  PERFORM set_config('request.jwt.claims',
    '{"sub":"0dd0c68c-026c-4ebc-9475-e6791cc54933","role":"authenticated"}', true);
  PERFORM set_config('role','authenticated', true);
  BEGIN
    SELECT count(*) INTO v_n FROM public.configuracion_sistema;
    SELECT string_agg(b, ', ') INTO v_l FROM unnest(bancarias) b
     WHERE NOT EXISTS (SELECT 1 FROM public.configuracion_sistema cs WHERE cs.clave = b);
    PERFORM set_config('probe.p757', CASE
      WHEN v_l IS NOT NULL THEN 'ROJO (un authenticated perdio: '||v_l||')'
      WHEN v_n <> v_tot     THEN 'ROJO (un authenticated ve '||v_n||' de '||v_tot||')'
      ELSE 'OK (un authenticated ve las '||v_n||', bancarias incluidas)' END, false);
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('probe.p757','FALLO ('||SQLSTATE||')', false);
  END;
  PERFORM set_config('role','none', true);
  PERFORM set_config('request.jwt.claims','', true);

  -- ---------------------------------------------------------------- P758 (service_role / la edge)
  PERFORM set_config('request.jwt.claims','{"role":"service_role"}', true);
  PERFORM set_config('role','service_role', true);
  BEGIN
    SELECT count(*) INTO v_n FROM public.configuracion_sistema;
    PERFORM set_config('probe.p758', CASE WHEN v_n = v_tot
      THEN 'OK (service_role ve las '||v_n||': actualizar-configuracion intacta)'
      ELSE 'ROJO (service_role ve '||v_n||' de '||v_tot||')' END, false);
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('probe.p758','FALLO ('||SQLSTATE||')', false);
  END;
  PERFORM set_config('role','none', true);
  PERFORM set_config('request.jwt.claims','', true);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('role','none', true);
  PERFORM set_config('request.jwt.claims','', true);
  PERFORM set_config('probe.p755','FALLO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;
SELECT set_config('role','none', true);

-- ============================================================
-- MIG 305 · notificaciones: UPDATE por columna + broadcasts cerradas (P759-P765)
-- ============================================================
-- `authenticated` tenia UPDATE a nivel TABLA y la policy `notificaciones_update_propias` incluia
-- `OR usuario_id IS NULL`: cualquier cuenta podia reescribir las 3 filas broadcast (titulo,
-- mensaje, tipo, metadata, rol_destinatario) y APROPIARSELAS poniendose como usuario_id. El mismo
-- brazo en la policy de SELECT hacia que anon las leyera. El fix: grant por COLUMNA (leida,
-- estado), sin brazo de broadcast en UPDATE ni en SELECT, y DELETE revocado.
--
-- Siete probes. Los cuatro positivos no son relleno: sin ellos, un cierre de mas daria verde en
-- los negativos y dejaria muda la campana de notificaciones, o rompería el panel de admin.
--   P759 apropiacion bloqueada (42501 de COLUMNA, no de RLS)
--   P760 el texto no es escribible (titulo)
--   P761 broadcasts no escribibles, con y SIN WHERE  <- ver la nota de P761
--   P762 anon y un authenticated ajeno no las LEEN
--   P763 CONTROL: el dueno ve las suyas y marca leida
--   P764 CONTROL: `estado` sigue escribible (el flujo del panel de admin)
--   P765 CONTROL: service_role intacto + DELETE revocado + catalogo limpio
SELECT set_config('role','none', true);

DO $$
DECLARE
  v_med constant uuid := '09d243d5-b222-482a-9762-94a582e9e752';  -- medico real con notifs propias
  v_pac constant uuid := '0dd0c68c-026c-4ebc-9475-e6791cc54933';  -- paciente real sin notifs
  v_bc uuid; v_mia uuid; v_rc int; v_n bigint; v_err text; v_r text; v_mal text := '';
BEGIN
  SELECT id INTO v_bc  FROM public.notificaciones WHERE usuario_id IS NULL ORDER BY created_at LIMIT 1;
  SELECT id INTO v_mia FROM public.notificaciones WHERE usuario_id = v_med ORDER BY created_at LIMIT 1;
  IF v_bc IS NULL OR v_mia IS NULL THEN
    PERFORM set_config('probe.p759','N/A (sin broadcast o sin notif propia)', false);
    PERFORM set_config('probe.p760','N/A', false); PERFORM set_config('probe.p761','N/A', false);
    PERFORM set_config('probe.p762','N/A', false); PERFORM set_config('probe.p763','N/A', false);
    PERFORM set_config('probe.p764','N/A', false); PERFORM set_config('probe.p765','N/A', false);
    RETURN;
  END IF;

  -- P759 — APROPIACION. Tiene que cortar el privilegio de COLUMNA, no la RLS: se distingue por el
  -- mensaje, porque la RLS dice "row-level security policy". Si lo cortara la RLS seguiria estando
  -- mal (usuario_id no deberia ser escribible en ninguna fila, ni en la propia).
  v_r := 'ROJO (la apropiacion funciono)';
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',v_pac,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    UPDATE public.notificaciones SET usuario_id = v_pac WHERE id = v_bc;
    PERFORM set_config('role','none', true);
    RAISE EXCEPTION 'P759_RB';
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    v_err := SQLERRM;
    IF v_err <> 'P759_RB' THEN
      IF SQLSTATE <> '42501' THEN v_r := 'ROJO (corto con '||SQLSTATE||', se esperaba 42501)';
      ELSIF v_err ILIKE '%row-level security%' THEN v_r := 'ROJO (lo corto la RLS, no el privilegio de columna)';
      ELSE v_r := 'OK (42501 por privilegio de columna: usuario_id no es escribible)'; END IF;
    END IF;
  END;
  PERFORM set_config('probe.p759', v_r, false);

  -- P760 — el TEXTO. Sobre su PROPIA fila, para que el corte sea el grant y no la RLS.
  v_r := 'ROJO (se pudo reescribir `titulo`)';
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',v_med,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    UPDATE public.notificaciones SET titulo = 'PROBE P760' WHERE id = v_mia;
    PERFORM set_config('role','none', true);
    RAISE EXCEPTION 'P760_RB';
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    v_err := SQLERRM;
    IF v_err <> 'P760_RB' THEN
      IF SQLSTATE <> '42501' THEN v_r := 'ROJO (corto con '||SQLSTATE||')';
      ELSIF v_err ILIKE '%row-level security%' THEN v_r := 'ROJO (lo corto la RLS sobre su propia fila)';
      ELSE v_r := 'OK (42501 por columna: el texto no es escribible ni en la fila propia)'; END IF;
    END IF;
  END;
  PERFORM set_config('probe.p760', v_r, false);

  -- P761 — BROADCASTS no escribibles. Van los DOS casos y no es redundancia: un UPDATE que lee
  -- columnas (WHERE o RETURNING) aplica TAMBIEN las policies de SELECT, asi que la version con
  -- WHERE la puede estar cortando el cierre de LECTURA y no el de escritura. La version sin WHERE
  -- no necesita SELECT y ejercita el USING del UPDATE a solas. Se descubrio porque la contraprueba
  -- por mutacion de esa pieza NO disparaba con la version con WHERE.
  v_mal := '';
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',v_pac,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    UPDATE public.notificaciones SET leida = false WHERE id = v_bc;
    GET DIAGNOSTICS v_rc = ROW_COUNT;
    IF v_rc <> 0 THEN v_mal := v_mal || 'con WHERE toco '||v_rc||'; '; END IF;
    UPDATE public.notificaciones SET leida = false;
    GET DIAGNOSTICS v_rc = ROW_COUNT;
    IF v_rc <> 0 THEN v_mal := v_mal || 'SIN WHERE toco '||v_rc||'; '; END IF;
    PERFORM set_config('role','none', true);
    RAISE EXCEPTION 'P761_RB';
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    IF SQLERRM <> 'P761_RB' AND SQLSTATE <> '42501' THEN
      v_mal := v_mal || 'corto con '||SQLSTATE||'; ';
    END IF;
  END;
  PERFORM set_config('probe.p761', CASE WHEN v_mal = ''
    THEN 'OK (0 filas con WHERE y 0 sin WHERE)' ELSE 'ROJO ('||v_mal||')' END, false);

  -- P762 — y tampoco las LEEN.
  v_mal := '';
  PERFORM set_config('request.jwt.claims','{"role":"anon"}', true);
  PERFORM set_config('role','anon', true);
  BEGIN
    SELECT count(*) INTO v_n FROM public.notificaciones;
    IF v_n <> 0 THEN v_mal := v_mal || 'anon ve '||v_n||'; '; END IF;
  EXCEPTION WHEN insufficient_privilege THEN
    -- 42501 CON grant = policy rota; SIN grant (notificaciones revocada) = correcto.
    IF has_table_privilege('anon','public.notificaciones','SELECT') THEN v_mal := v_mal || 'anon=42501 CON grant (policy rota); '; END IF;
    WHEN OTHERS THEN v_mal := v_mal || 'anon='||SQLSTATE||'; '; END;
  PERFORM set_config('role','none', true);
  PERFORM set_config('request.jwt.claims', json_build_object('sub',v_pac,'role','authenticated')::text, true);
  PERFORM set_config('role','authenticated', true);
  BEGIN
    SELECT count(*) INTO v_n FROM public.notificaciones;
    IF v_n <> 0 THEN v_mal := v_mal || 'un authenticated ajeno ve '||v_n||'; '; END IF;
  EXCEPTION WHEN OTHERS THEN v_mal := v_mal || 'ajeno='||SQLSTATE||'; '; END;
  PERFORM set_config('role','none', true);
  PERFORM set_config('request.jwt.claims','', true);
  PERFORM set_config('probe.p762', CASE WHEN v_mal = ''
    THEN 'OK (anon y un ajeno ven 0 broadcasts)' ELSE 'ROJO ('||v_mal||')' END, false);

  -- P763 — CONTROL POSITIVO: el dueno sigue viendo y marcando las suyas.
  v_r := 'no se ejecuto';
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',v_med,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    SELECT count(*) INTO v_n FROM public.notificaciones;
    IF v_n = 0 THEN v_r := 'ROJO (el dueno dejo de ver las suyas: campana muda)';
    ELSE
      UPDATE public.notificaciones SET leida = true WHERE id = v_mia;
      GET DIAGNOSTICS v_rc = ROW_COUNT;
      v_r := CASE WHEN v_rc = 1 THEN 'OK (ve '||v_n||' y marca la suya)'
                  ELSE 'ROJO (no pudo marcar la suya: '||v_rc||' filas)' END;
    END IF;
    PERFORM set_config('role','none', true);
    RAISE EXCEPTION 'P763_RB';
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    IF SQLERRM <> 'P763_RB' THEN v_r := 'ROJO (el camino legitimo fallo: '||SQLSTATE||')'; END IF;
  END;
  PERFORM set_config('probe.p763', v_r, false);

  -- P764 — CONTROL POSITIVO: `estado`. Es lo que mueve el panel de admin
  -- (useNotificacionesAdmin: en_proceso / completada / archivada). El alcance original de la
  -- migracion otorgaba solo `leida` y habria roto ese panel; este probe es el que lo vigila.
  v_r := 'no se ejecuto';
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',v_med,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    UPDATE public.notificaciones SET estado = 'en_proceso', leida = true WHERE id = v_mia;
    GET DIAGNOSTICS v_rc = ROW_COUNT;
    PERFORM set_config('role','none', true);
    v_r := CASE WHEN v_rc = 1 THEN 'OK (estado escribible: el panel de admin sigue vivo)'
                ELSE 'ROJO (estado afecto '||v_rc||' filas)' END;
    RAISE EXCEPTION 'P764_RB';
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    IF SQLERRM <> 'P764_RB' THEN v_r := 'ROJO (estado no es escribible: se rompe el panel de admin, '||SQLSTATE||')'; END IF;
  END;
  PERFORM set_config('probe.p764', v_r, false);
  PERFORM set_config('request.jwt.claims','', true);

  -- P765 — catalogo + service_role + DELETE.
  v_mal := '';
  IF has_table_privilege('authenticated','public.notificaciones','UPDATE') THEN v_mal := v_mal || 'auth conserva UPDATE de tabla; '; END IF;
  IF has_table_privilege('authenticated','public.notificaciones','DELETE') THEN v_mal := v_mal || 'auth conserva DELETE; '; END IF;
  IF NOT has_table_privilege('service_role','public.notificaciones','UPDATE') THEN v_mal := v_mal || 'service_role PERDIO UPDATE (rompe las edges); '; END IF;
  IF NOT has_column_privilege('authenticated','public.notificaciones','leida','UPDATE')
     OR NOT has_column_privilege('authenticated','public.notificaciones','estado','UPDATE') THEN
    v_mal := v_mal || 'falta el grant sobre leida/estado; '; END IF;
  SELECT count(*) INTO v_n FROM pg_policy pol JOIN pg_class c ON c.oid=pol.polrelid
    JOIN pg_namespace ns ON ns.oid=c.relnamespace
   WHERE ns.nspname='public' AND c.relname='notificaciones'
     AND pol.polname IN ('notificaciones_update_propias','notificaciones_select_propias');
  IF v_n <> 0 THEN v_mal := v_mal || 'sobrevivio una policy vieja; '; END IF;
  PERFORM set_config('probe.p765', CASE WHEN v_mal = ''
    THEN 'OK (grant por columna, sin DELETE, service_role intacto, catalogo limpio)'
    ELSE 'ROJO ('||v_mal||')' END, false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('role','none', true);
  PERFORM set_config('request.jwt.claims','', true);
  PERFORM set_config('probe.p765','FALLO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;
SELECT set_config('role','none', true);

-- ============================================================
-- MIG 306 · buckets campanas y productos confinados por empresa (P766-P770)
-- ============================================================
-- Las policies de escritura de estos dos buckets miraban solo bucket_id + auth.role(): cualquier
-- cuenta autenticada podia subir o BORRAR la creatividad de cualquier anunciante, y los dos
-- buckets son publicos. Ahora el prefijo del path tiene que ser la empresa del caller.
--
-- NOTA DE MEDICION: storage.objects trae un trigger BEFORE DELETE (`protect_objects_delete`) que
-- rechaza TODO borrado directo por SQL salvo que el GUC `storage.allow_delete_query` valga 'true'.
-- Es un guard de plataforma, no una policy. Estos probes lo levantan LOCAL a la transaccion del
-- harness para que lo que decida el borrado sea la RLS: sin eso, los casos de DELETE darian verde
-- por el trigger y no por el confinamiento — verdes por el motivo equivocado.
--
-- Cinco probes. P766, P768 y P770 son los positivos y no son relleno: un confinamiento de mas
-- rompe el alta de creatividades de TODOS los anunciantes y el form de house-ads del admin.
--   P766 cada empresa opera en su propio prefijo (los 2 buckets)
--   P767 y NO en el de otra, ni subiendo ni borrando (los 2 buckets)
--   P768 el super_admin sube la house-ad PLANA en campanas
--   P769 ...y NO puede en productos (la asimetria, ejercitada)
--   P770 los 14 objetos intactos, lectura publica viva, catalogo limpio
SELECT set_config('role','none', true);

DO $$
DECLARE
  v_cta_a constant uuid := '9ca0b977-3c91-48dc-aa04-2f1fab766963';  -- cuenta de la empresa A
  v_emp_a constant text := '411d6f8c-a405-49d6-9ed6-fbeb0db05133';
  v_cta_b constant uuid := '5c9e60a7-6885-486b-adfd-c691d0db33a6';  -- cuenta de la empresa B
  v_emp_b constant text := 'cc17afe8-fcd5-4ab0-84c4-08ba919d8481';
  v_sa    constant uuid := '41904e2c-5ef3-4fee-bd48-9ea58e0c8c37';  -- super_admin real
  v_plano constant text := '1780525121711.png';
  v_mal text := ''; v_rc int; v_n bigint; v_obj0 bigint;
BEGIN
  SELECT count(*) INTO v_obj0 FROM storage.objects WHERE bucket_id IN ('campanas','productos');
  PERFORM set_config('storage.allow_delete_query', 'true', true);   -- ver NOTA DE MEDICION

  -- ---------------------------------------------------------------- P766
  v_mal := '';
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',v_cta_a,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    INSERT INTO storage.objects (bucket_id, name, owner) VALUES ('campanas',  v_emp_a||'/_p766.png', v_cta_a);
    INSERT INTO storage.objects (bucket_id, name, owner) VALUES ('productos', v_emp_a||'/_p766.png', v_cta_a);
    DELETE FROM storage.objects WHERE name = v_emp_a||'/_p766.png';
    GET DIAGNOSTICS v_rc = ROW_COUNT;
    PERFORM set_config('role','none', true);
    IF v_rc <> 2 THEN v_mal := 'borro '||v_rc||' de sus 2 objetos'; END IF;
    RAISE EXCEPTION 'P766_RB';
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    IF SQLERRM <> 'P766_RB' THEN v_mal := 'la empresa no pudo operar en su prefijo ('||SQLSTATE||')'; END IF;
  END;
  PERFORM set_config('probe.p766', CASE WHEN v_mal = ''
    THEN 'OK (sube y borra en su propio prefijo, campanas y productos)' ELSE 'ROJO ('||v_mal||')' END, false);

  -- ---------------------------------------------------------------- P767
  v_mal := '';
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',v_cta_a,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    INSERT INTO storage.objects (bucket_id, name, owner) VALUES ('campanas', v_emp_b||'/_p767.png', v_cta_a);
    v_mal := v_mal || 'subio a campanas de otra empresa; ';
    PERFORM set_config('role','none', true);
    RAISE EXCEPTION 'P767_RB';
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    IF SQLERRM <> 'P767_RB' AND SQLSTATE <> '42501' THEN v_mal := v_mal||'campanas corto con '||SQLSTATE||'; '; END IF;
  END;
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',v_cta_a,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    INSERT INTO storage.objects (bucket_id, name, owner) VALUES ('productos', v_emp_b||'/_p767.png', v_cta_a);
    v_mal := v_mal || 'subio a productos de otra empresa; ';
    PERFORM set_config('role','none', true);
    RAISE EXCEPTION 'P767_RB';
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    IF SQLERRM <> 'P767_RB' AND SQLSTATE <> '42501' THEN v_mal := v_mal||'productos corto con '||SQLSTATE||'; '; END IF;
  END;
  -- el DELETE cruzado es la mitad que mas duele: borrar la creatividad de otro anunciante.
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',v_cta_a,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    DELETE FROM storage.objects WHERE bucket_id='campanas' AND split_part(name,'/',1) = v_emp_b;
    GET DIAGNOSTICS v_rc = ROW_COUNT;
    PERFORM set_config('role','none', true);
    IF v_rc <> 0 THEN v_mal := v_mal||'borro '||v_rc||' objeto(s) de otra empresa; '; END IF;
    RAISE EXCEPTION 'P767_RB';
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    IF SQLERRM <> 'P767_RB' AND SQLSTATE <> '42501' THEN v_mal := v_mal||'el DELETE cruzado corto con '||SQLSTATE||'; '; END IF;
  END;
  -- ...y tampoco el objeto plano del admin, que no es de nadie.
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',v_cta_b,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    DELETE FROM storage.objects WHERE bucket_id='campanas' AND name = v_plano;
    GET DIAGNOSTICS v_rc = ROW_COUNT;
    PERFORM set_config('role','none', true);
    IF v_rc <> 0 THEN v_mal := v_mal||'un proveedor borro el objeto plano del admin; '; END IF;
    RAISE EXCEPTION 'P767_RB';
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    IF SQLERRM <> 'P767_RB' AND SQLSTATE <> '42501' THEN v_mal := v_mal||'el plano corto con '||SQLSTATE||'; '; END IF;
  END;
  PERFORM set_config('probe.p767', CASE WHEN v_mal = ''
    THEN 'OK (no sube ni borra en prefijo ajeno, ni el plano del admin)' ELSE 'ROJO ('||v_mal||')' END, false);

  -- ---------------------------------------------------------------- P768
  v_mal := '';
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',v_sa,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    INSERT INTO storage.objects (bucket_id, name, owner) VALUES ('campanas', '_p768_housead.png', v_sa);
    DELETE FROM storage.objects WHERE bucket_id='campanas' AND name='_p768_housead.png';
    GET DIAGNOSTICS v_rc = ROW_COUNT;
    PERFORM set_config('role','none', true);
    IF v_rc <> 1 THEN v_mal := 'borro '||v_rc||' de su house-ad'; END IF;
    RAISE EXCEPTION 'P768_RB';
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    IF SQLERRM <> 'P768_RB' THEN v_mal := 'el super_admin no pudo subir la house-ad plana ('||SQLSTATE||')'; END IF;
  END;
  PERFORM set_config('probe.p768', CASE WHEN v_mal = ''
    THEN 'OK (house-ad plana: PlanesPublicidadConfigPage sigue viva)' ELSE 'ROJO ('||v_mal||')' END, false);

  -- ---------------------------------------------------------------- P769
  -- La asimetria EJERCITADA: el brazo de super_admin existe en campanas y NO en productos. Si
  -- alguien lo copiara "por simetria", este probe lo ve.
  v_mal := 'ROJO (el super_admin subio a productos: la asimetria se perdio)';
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',v_sa,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    INSERT INTO storage.objects (bucket_id, name, owner) VALUES ('productos', '_p769_admin.png', v_sa);
    PERFORM set_config('role','none', true);
    RAISE EXCEPTION 'P769_RB';
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    IF SQLSTATE = '42501' THEN v_mal := 'OK (42501: productos no tiene brazo de admin, a proposito)';
    ELSIF SQLERRM <> 'P769_RB' THEN v_mal := 'ROJO (corto con '||SQLSTATE||', se esperaba 42501)'; END IF;
  END;
  PERFORM set_config('probe.p769', v_mal, false);
  PERFORM set_config('request.jwt.claims','', true);

  -- ---------------------------------------------------------------- P770
  v_mal := '';
  SELECT count(*) INTO v_n FROM storage.objects WHERE bucket_id IN ('campanas','productos');
  IF v_n <> v_obj0 THEN v_mal := v_mal||'los buckets pasaron de '||v_obj0||' a '||v_n||' objetos; '; END IF;
  SELECT count(*) INTO v_n FROM storage.objects WHERE name ~ '_p76[6-9]';
  IF v_n <> 0 THEN v_mal := v_mal||'quedaron '||v_n||' objetos de prueba; '; END IF;
  IF NOT EXISTS (SELECT 1 FROM storage.objects WHERE bucket_id='campanas' AND name = v_plano) THEN
    v_mal := v_mal||'el objeto plano desaparecio; '; END IF;
  SELECT count(*) INTO v_n FROM pg_policy pol JOIN pg_class c ON c.oid=pol.polrelid
    JOIN pg_namespace ns ON ns.oid=c.relnamespace
   WHERE ns.nspname='storage' AND c.relname='objects' AND pol.polcmd::text='r'
     AND pg_get_expr(pol.polqual,pol.polrelid) ~ '(campanas|productos)';
  IF v_n <> 2 THEN v_mal := v_mal||'hay '||v_n||' policies de lectura publica, se esperaban 2; '; END IF;
  SELECT count(*) INTO v_n FROM storage.buckets WHERE id IN ('campanas','productos') AND public;
  IF v_n <> 2 THEN v_mal := v_mal||'un bucket dejo de ser publico; '; END IF;
  SELECT count(*) INTO v_n FROM pg_policy pol JOIN pg_class c ON c.oid=pol.polrelid
    JOIN pg_namespace ns ON ns.oid=c.relnamespace
   WHERE ns.nspname='storage' AND c.relname='objects'
     AND pol.polname IN ('Usuarios autenticados pueden subir campanas','Usuarios autenticados pueden eliminar campanas',
                         'Autenticados suben productos','Autenticados eliminan productos');
  IF v_n <> 0 THEN v_mal := v_mal||'sobrevivieron '||v_n||' policies viejas; '; END IF;
  PERFORM set_config('probe.p770', CASE WHEN v_mal = ''
    THEN 'OK (14 objetos intactos, lectura publica viva, catalogo limpio)' ELSE 'ROJO ('||v_mal||')' END, false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('role','none', true);
  PERFORM set_config('request.jwt.claims','', true);
  PERFORM set_config('probe.p770','FALLO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;
SELECT set_config('role','none', true);

-- ============================================================
-- MIG 307 · gate de pais + search_path en las 4 RPCs de medicos (GP_FX, P771-P778)
-- ============================================================
-- Las cuatro eran SECDEF sin search_path y sin gate, con el filtro
--     (p_pais_id IS NULL OR m.pais_id = p_pais_id OR m.pais_id IS NULL)
-- que ve de mas por dos vias. useClinicaCitas.ts:72 llama SIN argumento, asi que una clinica
-- recibia el padron de medicos de TODOS los paises. Ahora: filtro estricto `= v_pais` y gate de
-- tres brazos (admin del pais · el pais propio · tener clinica en ese pais).
--
-- LOS ACTORES SE SIEMBRAN, NO SE ELIGEN DE LA BASE. La primera version de estos probes tomaba
-- `perfiles WHERE rol='admin_clinica' ... ORDER BY id LIMIT 1`. Contra prod aislada eso daba el
-- unico admin_clinica real (pais Guatemala, 5 medicos) y salia verde; DENTRO del harness completo
-- elegia otro que algun fixture anterior deja creado en el pais "DEMO - No operativo", que tiene
-- CERO medicos, y P771 daba ROJO "0 filas" sin que el gate hubiera cortado nada: media que el pais
-- estaba vacio. Misma clase de fragilidad que tenia P746. Elegir un actor por rol con ORDER BY
-- depende de lo que hayan hecho las ~800 probes anteriores en la misma transaccion.
--
-- Ocho probes, y los positivos no son relleno: los 7 call-sites reales tienen que seguir
-- funcionando. Un gate que cortara de mas dejaria en verde a los negativos y vaciaria la agenda
-- de la clinica, el dashboard de pais y el de la clinica.
--
-- P777 y P778 cubren los dos caminos que NINGUN call-site de hoy ejercita:
--   · P777 el camino PC025 (v_pais NULL): hace falta un actor sin pais en perfiles NI en pacientes.
--   · P778 el TERCER brazo del gate. Con p_pais_id NULL el segundo brazo (`v_pais =
--     mi_pais_viewer()`) es siempre verdadero y corta el circuito antes, asi que el tercero solo se
--     activa con un medico que pida explicitamente el pais de una clinica suya que NO es su pais.
SELECT set_config('role','none', true);

-- ---------------- GP_FX — fixture ----------------
DO $$
DECLARE
  v_a uuid;   -- pais A: el que TIENE medicos (para los positivos)
  v_b uuid;   -- pais B: otro pais activo (para los negativos y el brazo 3)
  v_adm_cli uuid; v_adm_pais uuid; v_sinpais uuid; v_cruz uuid; v_med_b uuid; v_cli uuid;
BEGIN
  -- El pais A se elige por TENER medicos activos, no por orden de id: si no los tiene, P771 mide
  -- "pais vacio" en vez de "el gate deja pasar".
  SELECT m.pais_id INTO v_a FROM public.medicos m
   WHERE m.activo AND m.pais_id IS NOT NULL
   GROUP BY m.pais_id ORDER BY count(*) DESC, m.pais_id LIMIT 1;
  SELECT cp.id INTO v_b FROM public.configuracion_pais cp
   WHERE cp.activo AND cp.id <> v_a ORDER BY cp.id LIMIT 1;
  IF v_a IS NULL OR v_b IS NULL THEN
    PERFORM set_config('probe.gp_ready','0', false);
    PERFORM set_config('probe.gp_fx','ROJO (hace falta 1 pais con medicos + otro pais activo)', false); RETURN;
  END IF;

  -- (1) admin_clinica DETERMINISTA en el pais A
  v_adm_cli := gen_random_uuid();
  INSERT INTO auth.users (id) VALUES (v_adm_cli);
  INSERT INTO public.perfiles (id, email, nombre_completo, rol, pais_id, activo)
    VALUES (v_adm_cli, 'gp.adminclinica@example.invalid', 'QA GP admin_clinica', 'admin_clinica', v_a, true);

  -- (2) admin_pais DETERMINISTA en el pais A
  v_adm_pais := gen_random_uuid();
  INSERT INTO auth.users (id) VALUES (v_adm_pais);
  INSERT INTO public.perfiles (id, email, nombre_completo, rol, pais_id, activo)
    VALUES (v_adm_pais, 'gp.adminpais@example.invalid', 'QA GP admin_pais', 'admin_pais', v_a, true);

  -- (3) actor SIN pais: mi_pais_viewer() recorre perfiles -> cuentas_proveedor -> empresa ->
  --     pacientes; con este los cuatro dan NULL, que es la unica forma de llegar a PC025.
  v_sinpais := gen_random_uuid();
  INSERT INTO auth.users (id) VALUES (v_sinpais);
  INSERT INTO public.perfiles (id, email, nombre_completo, rol, pais_id, activo)
    VALUES (v_sinpais, 'gp.sinpais@example.invalid', 'QA GP sin pais', 'medico', NULL, true);

  -- (4) un medico EN EL PAIS B, para que P778 pueda afirmar que VE algo y no solo que no lanzo.
  v_med_b := gen_random_uuid();
  INSERT INTO auth.users (id) VALUES (v_med_b);
  INSERT INTO public.perfiles (id, email, nombre_completo, rol, pais_id, activo)
    VALUES (v_med_b, 'gp.medico.b@example.invalid', 'QA GP medico del pais B', 'medico', v_b, true);
  INSERT INTO public.medicos (id, nombre_completo, email, activo, pais_id)
    VALUES (v_med_b, 'QA GP medico del pais B', 'gp.medico.b@example.invalid', true, v_b);

  -- (5) medico CRUZADO: su perfil es del pais A, pero tiene una clinica en el pais B.
  --     medico_clinicas.medico_id tiene FK a `medicos`, asi que necesita fila ahi tambien.
  v_cruz := gen_random_uuid();
  INSERT INTO auth.users (id) VALUES (v_cruz);
  INSERT INTO public.perfiles (id, email, nombre_completo, rol, pais_id, activo)
    VALUES (v_cruz, 'gp.cruzado@example.invalid', 'QA GP medico cruzado', 'medico', v_a, true);
  INSERT INTO public.medicos (id, nombre_completo, email, activo, pais_id)
    VALUES (v_cruz, 'QA GP medico cruzado', 'gp.cruzado@example.invalid', true, v_a);
  v_cli := gen_random_uuid();
  INSERT INTO public.clinicas (id, doctor_id, nombre, pais_id, activa)
    VALUES (v_cli, v_cruz, 'QA GP clinica del pais B', v_b, true);
  INSERT INTO public.medico_clinicas (medico_id, clinica_id, es_principal)
    VALUES (v_cruz, v_cli, false);

  PERFORM set_config('probe.gp_a', v_a::text, false);
  PERFORM set_config('probe.gp_b', v_b::text, false);
  PERFORM set_config('probe.gp_adm_cli',  v_adm_cli::text, false);
  PERFORM set_config('probe.gp_adm_pais', v_adm_pais::text, false);
  PERFORM set_config('probe.gp_sinpais',  v_sinpais::text, false);
  PERFORM set_config('probe.gp_cruz',     v_cruz::text, false);
  PERFORM set_config('probe.gp_ready','1', false);
  PERFORM set_config('probe.gp_fx','OK (paisA con '||
    (SELECT count(*) FROM public.medicos m WHERE m.activo AND m.pais_id=v_a)||
    ' medicos + paisB con 1 sembrado; admin_clinica, admin_pais, sin-pais y medico cruzado)', false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('probe.gp_ready','0', false);
  PERFORM set_config('probe.gp_fx','ROJO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;
SELECT set_config('role','none', true);

-- ---------------- P771-P778 ----------------
DO $$
DECLARE
  v_a uuid; v_b uuid; v_adm_cli uuid; v_adm_pais uuid; v_sinpais uuid; v_cruz uuid; v_sa uuid;
  ids uuid[]; n bigint; v_r text;
BEGIN
  IF coalesce(current_setting('probe.gp_ready', true),'0') <> '1' THEN
    PERFORM set_config('probe.p771','N/A (fixture GP no sembro)', false);
    PERFORM set_config('probe.p772','N/A', false); PERFORM set_config('probe.p773','N/A', false);
    PERFORM set_config('probe.p774','N/A', false); PERFORM set_config('probe.p775','N/A', false);
    PERFORM set_config('probe.p776','N/A', false); PERFORM set_config('probe.p777','N/A', false);
    PERFORM set_config('probe.p778','N/A', false);
    RETURN;
  END IF;
  v_a        := current_setting('probe.gp_a', true)::uuid;
  v_b        := current_setting('probe.gp_b', true)::uuid;
  v_adm_cli  := current_setting('probe.gp_adm_cli', true)::uuid;
  v_adm_pais := current_setting('probe.gp_adm_pais', true)::uuid;
  v_sinpais  := current_setting('probe.gp_sinpais', true)::uuid;
  v_cruz     := current_setting('probe.gp_cruz', true)::uuid;
  SELECT id INTO v_sa FROM public.perfiles WHERE rol='super_admin' AND activo ORDER BY id LIMIT 1;
  SELECT array_agg(id) INTO ids FROM (SELECT id FROM public.medicos ORDER BY id LIMIT 5) s;

  -- P771 (a) — admin_clinica SIN argumento. Es el caller de useClinicaCitas.ts:72 y el que mas
  -- riesgo corria: si el gate cortara aca, la agenda de la clinica se queda sin medicos.
  v_r := 'no se ejecuto';
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',v_adm_cli,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    SELECT count(*) INTO n FROM public.listar_medicos_por_pais();
    PERFORM set_config('role','none', true);
    v_r := CASE WHEN n > 0 THEN 'OK (responde '||n||' medicos de su pais)'
                ELSE 'ROJO (0 filas con '||(SELECT count(*) FROM public.medicos m WHERE m.activo AND m.pais_id=v_a)
                     ||' medicos activos en su pais: la agenda de la clinica se queda vacia)' END;
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    v_r := 'ROJO (corto con '||SQLSTATE||' '||SQLERRM||')';
  END;
  PERFORM set_config('probe.p771', v_r, false);

  -- P772 (b) — el mismo admin_clinica pidiendo el pais B -> PC026.
  v_r := 'ROJO (vio un pais ajeno)';
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',v_adm_cli,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    PERFORM count(*) FROM public.listar_medicos_por_pais(v_b);
    PERFORM set_config('role','none', true);
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    v_r := CASE WHEN SQLSTATE = 'PC026' THEN 'OK (PC026)'
                ELSE 'ROJO (corto con '||SQLSTATE||', se esperaba PC026)' END;
  END;
  PERFORM set_config('probe.p772', v_r, false);

  -- P773 (c) — admin_pais sobre SU pais. Caller: PaisDashboardPage.tsx:104.
  v_r := 'no se ejecuto';
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',v_adm_pais,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    SELECT public.contar_medicos_por_pais(v_a) INTO n;
    PERFORM set_config('role','none', true);
    v_r := CASE WHEN n > 0 THEN 'OK (cuenta '||n||' en su pais)'
                ELSE 'ROJO (conto 0 en un pais que tiene medicos)' END;
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    v_r := 'ROJO (el dashboard de pais se rompe: '||SQLSTATE||' '||SQLERRM||')';
  END;
  PERFORM set_config('probe.p773', v_r, false);

  -- P774 (d) — admin_pais sobre el pais B -> PC026.
  v_r := 'ROJO (conto un pais ajeno)';
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',v_adm_pais,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    PERFORM public.contar_medicos_por_pais(v_b);
    PERFORM set_config('role','none', true);
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    v_r := CASE WHEN SQLSTATE = 'PC026' THEN 'OK (PC026)'
                ELSE 'ROJO (corto con '||SQLSTATE||', se esperaba PC026)' END;
  END;
  PERFORM set_config('probe.p774', v_r, false);

  -- P775 (e) — super_admin puede pedir CUALQUIER pais. El fixture sembro un medico en el pais B,
  -- asi que aca se puede afirmar que VE algo, no solo que no lanzo.
  v_r := 'no se ejecuto';
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',v_sa,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    SELECT count(*) INTO n FROM public.listar_medicos_por_pais(v_b);
    PERFORM set_config('role','none', true);
    v_r := CASE WHEN n > 0 THEN 'OK (ve '||n||' del pais ajeno, sin excepcion)'
                ELSE 'ROJO (0 filas: el fixture sembro 1 medico en ese pais)' END;
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    v_r := 'ROJO (el super_admin fue rechazado: '||SQLSTATE||')';
  END;
  PERFORM set_config('probe.p775', v_r, false);

  -- P776 (f) — anon en las DOS: el REVOKE de la 295 + esta migracion.
  v_r := '';
  PERFORM set_config('request.jwt.claims','{"role":"anon"}', true);
  PERFORM set_config('role','anon', true);
  BEGIN PERFORM public.listar_medicos_por_pais(v_a); v_r := v_r||'listar respondio; ';
  EXCEPTION WHEN insufficient_privilege THEN NULL;
    WHEN OTHERS THEN v_r := v_r||'listar='||SQLSTATE||' (se esperaba 42501); '; END;
  BEGIN PERFORM public.obtener_medicos_por_ids(ids); v_r := v_r||'obtener_por_ids respondio; ';
  EXCEPTION WHEN insufficient_privilege THEN NULL;
    WHEN OTHERS THEN v_r := v_r||'obtener='||SQLSTATE||' (se esperaba 42501); '; END;
  PERFORM set_config('role','none', true);
  PERFORM set_config('request.jwt.claims','', true);
  PERFORM set_config('probe.p776', CASE WHEN v_r = ''
    THEN 'OK (42501 en las dos)' ELSE 'ROJO ('||v_r||')' END, false);

  -- P777 (g) — actor SIN pais por ninguna via -> PC025.
  v_r := 'ROJO (no lanzo PC025)';
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',v_sinpais,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    PERFORM count(*) FROM public.listar_medicos_por_pais();
    PERFORM set_config('role','none', true);
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    v_r := CASE WHEN SQLSTATE = 'PC025' THEN 'OK (PC025 pais requerido)'
                ELSE 'ROJO (corto con '||SQLSTATE||', se esperaba PC025)' END;
  END;
  PERFORM set_config('probe.p777', v_r, false);

  -- P778 (h) — TERCER BRAZO: medico del pais A pidiendo el pais B, donde esta SU clinica.
  -- Es el unico camino que activa el EXISTS sobre medico_clinicas.
  v_r := 'no se ejecuto';
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',v_cruz,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    SELECT count(*) INTO n FROM public.listar_medicos_por_pais(v_b);
    PERFORM set_config('role','none', true);
    v_r := CASE WHEN n > 0 THEN 'OK (el 3er brazo habilita: ve '||n||' del pais de su clinica)'
                ELSE 'ROJO (paso el gate pero vio 0, con 1 medico sembrado en ese pais)' END;
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    v_r := 'ROJO (el 3er brazo no habilita: '||SQLSTATE||' '||SQLERRM||')';
  END;
  PERFORM set_config('probe.p778', v_r, false);
  PERFORM set_config('request.jwt.claims','', true);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('role','none', true);
  PERFORM set_config('request.jwt.claims','', true);
  PERFORM set_config('probe.p778','FALLO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;
SELECT set_config('role','none', true);


-- ============================================================
-- MIG 309 · "Admin ve visitas de su pais" de cmd=ALL a SELECT (VAG_FX, P779-P782)
-- ============================================================
-- La policy nacio como `FOR ALL`, asi que ademas de la lectura que su nombre promete le daba a
-- super_admin y a admin_pais INSERT/UPDATE/DELETE sobre visitas_agendadas. Medido el 20-sep contra
-- prod: un admin_pais borraba 1 fila y actualizaba 1 fila por PostgREST directo. Ningun front lo
-- usa — el unico write del repo sobre esta tabla es el INSERT de proveedor en
-- useVisitasAgendadas.ts:186 — y las 7 RPCs que la escriben son todas SECURITY DEFINER, asi que
-- no dependen de la RLS del llamante.
--
-- ESTAS PROBES MIDEN ROW_COUNT, NO SQLSTATE. Es la trampa del frente: en UPDATE y DELETE la RLS
-- FILTRA FILAS EN SILENCIO, no lanza. Una probe que espere 42501 sale roja con la migracion bien
-- aplicada. Lo unico que distingue el antes del despues es cuantas filas toco.
--
-- NO HAY PROBE DE INSERT, a proposito. `trg_gate_visita_pais` es BEFORE INSERT y los triggers
-- BEFORE corren ANTES del WITH CHECK de la RLS, asi que para un admin (cuyo
-- mi_empresa_proveedor() es NULL) el INSERT muere con P0001 "sin plan de visitas activo" IGUAL
-- antes que despues. Una probe de INSERT seria verde en los dos escenarios: no mediria nada.
--
-- EL ADMIN_PAIS SE SIEMBRA; el super_admin se lee. La afirmacion del admin_pais depende de SU
-- pais, asi que elegirlo con ORDER BY dentro del harness repite el ROJO fantasma de P771/P746
-- (un fixture anterior deja admin_pais en un pais vacio). Para super_admin la policy mira solo el
-- rol, asi que cualquiera activo sirve.
--
-- LOS CONTEOS SE CALIBRAN SOLOS. No se hardcodea "14": para cuando corren estas probes, ~800
-- probes anteriores pudieron sembrar visitas en la misma transaccion. Cada probe compara contra lo
-- que hay en la base en ese momento, medido como postgres antes de impersonar.
SELECT set_config('role','none', true);

-- ---------------- VAG_FX — fixture ----------------
DO $$
DECLARE
  v_pais uuid; v_adm uuid; v_sa uuid; v_vid uuid;
  v_n_pais bigint; v_n_total bigint; v_n_ajenas bigint;
BEGIN
  -- Pais A = el que TIENE visitas. Si se eligiera por orden de id se mediria "pais vacio".
  SELECT v.pais_id INTO v_pais FROM public.visitas_agendadas v
   WHERE v.pais_id IS NOT NULL
   GROUP BY v.pais_id ORDER BY count(*) DESC, v.pais_id LIMIT 1;
  SELECT id INTO v_sa FROM public.perfiles WHERE rol='super_admin' AND activo ORDER BY id LIMIT 1;
  IF v_pais IS NULL OR v_sa IS NULL THEN
    PERFORM set_config('probe.vag_ready','0', false);
    PERFORM set_config('probe.vag_fx','ROJO (hace falta 1 pais con visitas + 1 super_admin activo)', false); RETURN;
  END IF;

  -- admin_pais DETERMINISTA en el pais que tiene las visitas
  v_adm := gen_random_uuid();
  INSERT INTO auth.users (id) VALUES (v_adm);
  INSERT INTO public.perfiles (id, email, nombre_completo, rol, pais_id, activo)
    VALUES (v_adm, 'vag.adminpais@example.invalid', 'QA VAG admin_pais', 'admin_pais', v_pais, true);

  -- fila objetivo de las mutaciones: la primera visita de ese pais
  SELECT v.id INTO v_vid FROM public.visitas_agendadas v
   WHERE v.pais_id = v_pais ORDER BY v.id LIMIT 1;

  SELECT count(*) INTO v_n_pais   FROM public.visitas_agendadas v WHERE v.pais_id = v_pais;
  SELECT count(*) INTO v_n_total  FROM public.visitas_agendadas;
  SELECT count(*) INTO v_n_ajenas FROM public.visitas_agendadas v
   WHERE v.pais_id IS DISTINCT FROM v_pais;

  PERFORM set_config('probe.vag_pais',   v_pais::text, false);
  PERFORM set_config('probe.vag_adm',    v_adm::text, false);
  PERFORM set_config('probe.vag_sa',     v_sa::text, false);
  PERFORM set_config('probe.vag_vid',    v_vid::text, false);
  PERFORM set_config('probe.vag_npais',  v_n_pais::text, false);
  PERFORM set_config('probe.vag_ntotal', v_n_total::text, false);
  PERFORM set_config('probe.vag_ready','1', false);
  PERFORM set_config('probe.vag_fx','OK (pais con '||v_n_pais||' visitas, '||v_n_total||
    ' en total, '||v_n_ajenas||' de otros paises; admin_pais sembrado, super_admin leido)', false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('probe.vag_ready','0', false);
  PERFORM set_config('probe.vag_fx','ROJO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;
SELECT set_config('role','none', true);

-- ---------------- P779-P782 ----------------
DO $$
DECLARE
  v_adm uuid; v_sa uuid; v_vid uuid;
  v_npais bigint; v_ntotal bigint;
  n bigint; n_ap bigint; n_sa bigint; v_ajenas bigint; v_r text; v_e text;
BEGIN
  IF coalesce(current_setting('probe.vag_ready', true),'0') <> '1' THEN
    PERFORM set_config('probe.p779','N/A (fixture VAG no sembro)', false);
    PERFORM set_config('probe.p780','N/A', false); PERFORM set_config('probe.p781','N/A', false);
    PERFORM set_config('probe.p782','N/A', false);
    RETURN;
  END IF;
  v_adm    := current_setting('probe.vag_adm', true)::uuid;
  v_sa     := current_setting('probe.vag_sa', true)::uuid;
  v_vid    := current_setting('probe.vag_vid', true)::uuid;
  v_npais  := current_setting('probe.vag_npais', true)::bigint;
  v_ntotal := current_setting('probe.vag_ntotal', true)::bigint;

  -- P779 (a) — CONTROL POSITIVO: el admin_pais sigue LEYENDO las visitas de su pais. Si la
  -- migracion cortara de mas, el panel de pais se queda en blanco y eso no se nota hasta prod.
  v_r := 'no se ejecuto';
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',v_adm,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    SELECT count(*) INTO n FROM public.visitas_agendadas;
    SELECT count(*) INTO v_ajenas FROM public.visitas_agendadas v
     WHERE v.pais_id IS DISTINCT FROM current_setting('probe.vag_pais', true)::uuid;
    PERFORM set_config('role','none', true);
    v_r := CASE
      WHEN v_ajenas > 0 THEN 'ROJO (ve '||v_ajenas||' visita(s) de otros paises)'
      WHEN n = v_npais  THEN 'OK (lee sus '||n||'/'||v_npais||' visitas, 0 ajenas)'
      ELSE 'ROJO (ve '||n||' de las '||v_npais||' de su pais: la migracion corto la LECTURA)'
    END;
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    v_r := 'ROJO (la lectura corto con '||SQLSTATE||' '||SQLERRM||')';
  END;
  PERFORM set_config('probe.p779', v_r, false);

  -- P780 (b) — CONTROL POSITIVO: el super_admin sigue viendolo todo. Lee por partida doble (esta
  -- policy y "Admin ezpay ve todas las visitas"), asi que un 0 aca seria muy raro.
  v_r := 'no se ejecuto';
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',v_sa,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    SELECT count(*) INTO n FROM public.visitas_agendadas;
    PERFORM set_config('role','none', true);
    v_r := CASE WHEN n = v_ntotal THEN 'OK (lee las '||n||'/'||v_ntotal||', sin restriccion)'
                ELSE 'ROJO (ve '||n||' de '||v_ntotal||')' END;
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    v_r := 'ROJO (la lectura corto con '||SQLSTATE||' '||SQLERRM||')';
  END;
  PERFORM set_config('probe.p780', v_r, false);

  -- P781 (c) — EL HUECO, brazo UPDATE. Directo por rol, NO por RPC. `comentario_admin` esta fuera
  -- del alcance de trg_gate_visita_pais, que es `BEFORE INSERT OR UPDATE OF medico_id`: el trigger
  -- NO es una segunda barrera para un UPDATE arbitrario, la unica barrera es la policy.
  -- La escritura va en subtransaccion que SIEMPRE aborta, asi que ni siquiera cuando el hueco
  -- esta abierto queda nada tocado.
  n_ap := -1; n_sa := -1; v_e := '';
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',v_adm,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    UPDATE public.visitas_agendadas SET comentario_admin = 'VAG_PROBE_781' WHERE id = v_vid;
    GET DIAGNOSTICS n_ap = ROW_COUNT;
    RAISE EXCEPTION 'VAG_RB';
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    IF SQLERRM <> 'VAG_RB' THEN v_e := v_e||' adminpais='||SQLSTATE||' '||SQLERRM; END IF;
  END;
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',v_sa,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    UPDATE public.visitas_agendadas SET comentario_admin = 'VAG_PROBE_781' WHERE id = v_vid;
    GET DIAGNOSTICS n_sa = ROW_COUNT;
    RAISE EXCEPTION 'VAG_RB';
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    IF SQLERRM <> 'VAG_RB' THEN v_e := v_e||' superadmin='||SQLSTATE||' '||SQLERRM; END IF;
  END;
  v_r := CASE
    WHEN v_e <> ''               THEN 'FALLO (no midio ROW_COUNT:'||v_e||')'
    WHEN n_ap = 0 AND n_sa = 0   THEN 'OK (UPDATE directo en cero: admin_pais 0, super_admin 0)'
    ELSE 'ROJO (UPDATE directo TOCA filas: admin_pais '||n_ap||', super_admin '||n_sa||')'
  END;
  PERFORM set_config('probe.p781', v_r, false);

  -- P782 (d) — EL HUECO, brazo DELETE. Es el mas caro de los dos: no hay ningun trigger BEFORE
  -- DELETE en la tabla, asi que la policy era lo unico que se interponia entre un admin y borrar
  -- la agenda de un visitador.
  n_ap := -1; n_sa := -1; v_e := '';
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',v_adm,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    DELETE FROM public.visitas_agendadas WHERE id = v_vid;
    GET DIAGNOSTICS n_ap = ROW_COUNT;
    RAISE EXCEPTION 'VAG_RB';
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    IF SQLERRM <> 'VAG_RB' THEN v_e := v_e||' adminpais='||SQLSTATE||' '||SQLERRM; END IF;
  END;
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',v_sa,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    DELETE FROM public.visitas_agendadas WHERE id = v_vid;
    GET DIAGNOSTICS n_sa = ROW_COUNT;
    RAISE EXCEPTION 'VAG_RB';
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    IF SQLERRM <> 'VAG_RB' THEN v_e := v_e||' superadmin='||SQLSTATE||' '||SQLERRM; END IF;
  END;
  v_r := CASE
    WHEN v_e <> ''               THEN 'FALLO (no midio ROW_COUNT:'||v_e||')'
    WHEN n_ap = 0 AND n_sa = 0   THEN 'OK (DELETE directo en cero: admin_pais 0, super_admin 0)'
    ELSE 'ROJO (DELETE directo BORRA filas: admin_pais '||n_ap||', super_admin '||n_sa||')'
  END;
  PERFORM set_config('probe.p782', v_r, false);
  PERFORM set_config('request.jwt.claims','', true);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('role','none', true);
  PERFORM set_config('request.jwt.claims','', true);
  PERFORM set_config('probe.p782','FALLO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;
SELECT set_config('role','none', true);


-- ============================================================
-- MIG 310 · examen_adjuntos (EA_FX, P783-P789)
-- ============================================================
-- La escritura de examen_adjuntos NO tiene policy: entra solo por
-- public.registrar_examen_adjunto(), SECURITY DEFINER, mismo patron que visitas_comerciales.
-- Estas probes ejercitan las dos caras: que la RPC deje pasar a quien corresponde y corte al
-- resto, y que la lectura de la tabla use el MISMO helper que gobierna storage y examenes.
--
-- P788 necesita `storage.allow_delete_query`: storage.objects tiene un BEFORE DELETE
-- (protect_objects_delete) que rechaza TODO borrado por SQL directo, con policy o sin ella. Sin
-- apagarlo la probe mediria el trigger y no la policy. Es lo mismo que hizo falta en la mig 306.
SELECT set_config('role','none', true);

-- ---------------- EA_FX — fixture ----------------
DO $$
DECLARE
  v_emp uuid; v_lab uuid; v_ajeno uuid; v_med uuid; v_pac uuid;
  v_ex_no int; v_ex_si int; v_url text;
BEGIN
  -- El laboratorio se elige por TENER examenes; si se eligiera por orden de id las probes
  -- medirian un lab sin nada y saldrian verdes por vacio.
  SELECT e.laboratorio_id INTO v_emp FROM public.examenes e
   WHERE e.laboratorio_id IS NOT NULL
   GROUP BY e.laboratorio_id ORDER BY count(*) DESC, e.laboratorio_id LIMIT 1;

  SELECT e.id INTO v_ex_no FROM public.examenes e
   WHERE e.laboratorio_id = v_emp AND NOT e.liberado_al_paciente ORDER BY e.id LIMIT 1;
  SELECT e.id, COALESCE(NULLIF(split_part(e.archivo_url,'/resultados-examenes/',2),''), e.archivo_url)
    INTO v_ex_si, v_url
    FROM public.examenes e
   WHERE e.laboratorio_id = v_emp AND e.liberado_al_paciente AND e.archivo_url IS NOT NULL
   ORDER BY e.id LIMIT 1;

  SELECT cp.id INTO v_lab FROM public.cuentas_proveedor cp
   WHERE cp.empresa_id = v_emp AND cp.activo ORDER BY cp.id LIMIT 1;
  SELECT cp.id INTO v_ajeno FROM public.cuentas_proveedor cp
   WHERE cp.empresa_id IS DISTINCT FROM v_emp AND cp.activo ORDER BY cp.id LIMIT 1;

  SELECT p.auth_user_id INTO v_pac FROM public.pacientes p
   JOIN public.examenes e ON e.paciente_id = p.id
   WHERE e.id = v_ex_si AND p.auth_user_id IS NOT NULL LIMIT 1;

  IF v_emp IS NULL OR v_ex_no IS NULL OR v_ex_si IS NULL OR v_lab IS NULL
     OR v_ajeno IS NULL OR v_pac IS NULL OR v_url IS NULL THEN
    PERFORM set_config('probe.ea_ready','0', false);
    PERFORM set_config('probe.ea_fx','ROJO (falta fixture: emp='||COALESCE(v_emp::text,'-')
      ||' ex_no='||COALESCE(v_ex_no::text,'-')||' ex_si='||COALESCE(v_ex_si::text,'-')
      ||' lab='||COALESCE(v_lab::text,'-')||' ajeno='||COALESCE(v_ajeno::text,'-')
      ||' pac='||COALESCE(v_pac::text,'-')||' url='||COALESCE(v_url,'-')||')', false);
    RETURN;
  END IF;

  -- medico SIN NINGUNA relacion con estos examenes: se siembra, no se busca. Buscar "un medico"
  -- con ORDER BY dentro del harness devuelve lo que dejo algun fixture anterior.
  v_med := gen_random_uuid();
  INSERT INTO auth.users (id) VALUES (v_med);
  INSERT INTO public.perfiles (id, email, nombre_completo, rol, activo)
    VALUES (v_med, 'ea.medico.ajeno@example.invalid', 'QA EA medico sin relacion', 'medico', true);

  -- dos adjuntos sembrados como postgres (la RPC no puede crear el del examen liberado: PE002).
  -- P787 necesita los DOS para que el veredicto del paciente distinga 1 de 2 y de 0.
  INSERT INTO public.examen_adjuntos (examen_id, storage_path, mime_type, subido_por)
   VALUES (v_ex_no, v_emp::text||'/ea-fx-nolib.pdf', 'application/pdf', v_lab),
          (v_ex_si, v_emp::text||'/ea-fx-lib.pdf',   'application/pdf', v_lab);

  -- objetos en el bucket. Para P788: uno atado a un adjunto, uno atado a examenes.archivo_url
  -- (se reusa el que ya existe) y uno suelto. Para P789 hace falta ademas el del examen
  -- LIBERADO, que es el unico que el paciente puede alcanzar, y solo por la rama de adjuntos.
  INSERT INTO storage.objects (bucket_id, name, owner)
   VALUES ('resultados-examenes', v_emp::text||'/ea-fx-nolib.pdf', NULL),
          ('resultados-examenes', v_emp::text||'/ea-fx-lib.pdf',   NULL),
          ('resultados-examenes', v_emp::text||'/ea-fx-libre.pdf', NULL)
   ON CONFLICT DO NOTHING;

  PERFORM set_config('probe.ea_emp',   v_emp::text, false);
  PERFORM set_config('probe.ea_lab',   v_lab::text, false);
  PERFORM set_config('probe.ea_ajeno', v_ajeno::text, false);
  PERFORM set_config('probe.ea_med',   v_med::text, false);
  PERFORM set_config('probe.ea_pac',   v_pac::text, false);
  PERFORM set_config('probe.ea_exno',  v_ex_no::text, false);
  PERFORM set_config('probe.ea_exsi',  v_ex_si::text, false);
  PERFORM set_config('probe.ea_url',   v_url, false);
  PERFORM set_config('probe.ea_ready','1', false);
  PERFORM set_config('probe.ea_fx','OK (lab '||v_emp::text||': examen no-liberado '||v_ex_no
    ||', liberado '||v_ex_si||'; 2 adjuntos y 3 objetos sembrados)', false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('probe.ea_ready','0', false);
  PERFORM set_config('probe.ea_fx','ROJO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;
SELECT set_config('role','none', true);

-- ---------------- P783-P788 ----------------
DO $$
DECLARE
  v_lab uuid; v_ajeno uuid; v_med uuid; v_pac uuid; v_emp uuid;
  v_exno int; v_exsi int; v_url text;
  v_fila public.examen_adjuntos; v_r text; n bigint;
  n_lab bigint; n_med bigint; n_pac bigint;
  n_adj bigint; n_exa bigint; n_lib bigint; v_e text; v_ok_lib boolean;
BEGIN
  IF coalesce(current_setting('probe.ea_ready', true),'0') <> '1' THEN
    PERFORM set_config('probe.p783','N/A (fixture EA no sembro)', false);
    PERFORM set_config('probe.p784','N/A', false); PERFORM set_config('probe.p785','N/A', false);
    PERFORM set_config('probe.p786','N/A', false); PERFORM set_config('probe.p787','N/A', false);
    PERFORM set_config('probe.p788','N/A', false); PERFORM set_config('probe.p789','N/A', false);
    RETURN;
  END IF;
  v_emp   := current_setting('probe.ea_emp', true)::uuid;
  v_lab   := current_setting('probe.ea_lab', true)::uuid;
  v_ajeno := current_setting('probe.ea_ajeno', true)::uuid;
  v_med   := current_setting('probe.ea_med', true)::uuid;
  v_pac   := current_setting('probe.ea_pac', true)::uuid;
  v_exno  := current_setting('probe.ea_exno', true)::int;
  v_exsi  := current_setting('probe.ea_exsi', true)::int;
  v_url   := current_setting('probe.ea_url', true);

  -- P783 (a) — CONTROL POSITIVO: el lab duenio registra sobre un examen NO liberado.
  -- Tambien es la prueba de que FORCE ROW LEVEL SECURITY no deja afuera a la propia RPC:
  -- la tabla no tiene policy de INSERT, asi que si FORCE alcanzara al DEFINER, esto daria 42501.
  v_r := 'no se ejecuto';
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',v_lab,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    v_fila := public.registrar_examen_adjunto(v_exno, v_emp::text||'/ea-p783.pdf', 'application/pdf');
    PERFORM set_config('role','none', true);
    v_r := CASE WHEN v_fila.id IS NOT NULL AND v_fila.examen_id = v_exno AND v_fila.subido_por = v_lab
                THEN 'OK (adjunto '||v_fila.id||' creado por la RPC; FORCE RLS no bloquea al DEFINER)'
                ELSE 'ROJO (la RPC devolvio una fila inesperada)' END;
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    v_r := 'ROJO (el lab duenio NO pudo registrar: '||SQLSTATE||' '||SQLERRM||')';
  END;
  PERFORM set_config('probe.p783', v_r, false);

  -- P784 (b) — examen YA LIBERADO: PE002.
  v_r := 'no se ejecuto';
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',v_lab,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    v_fila := public.registrar_examen_adjunto(v_exsi, v_emp::text||'/ea-p784.pdf', 'application/pdf');
    PERFORM set_config('role','none', true);
    v_r := 'ROJO (adjunto '||v_fila.id||' creado sobre un examen LIBERADO)';
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    v_r := CASE WHEN SQLSTATE = 'PE002' THEN 'OK (PE002 sobre examen liberado)'
                ELSE 'ROJO (corto con '||SQLSTATE||' en vez de PE002: '||SQLERRM||')' END;
  END;
  PERFORM set_config('probe.p784', v_r, false);

  -- P785 (c) — lab de OTRA empresa sobre el mismo examen: 42501.
  v_r := 'no se ejecuto';
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',v_ajeno,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    v_fila := public.registrar_examen_adjunto(v_exno, v_emp::text||'/ea-p785.pdf', 'application/pdf');
    PERFORM set_config('role','none', true);
    v_r := 'ROJO (un lab AJENO adjunto sobre el examen de otra empresa: fila '||v_fila.id||')';
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    v_r := CASE WHEN SQLSTATE = '42501' THEN 'OK (42501 al lab ajeno)'
                ELSE 'ROJO (corto con '||SQLSTATE||' en vez de 42501: '||SQLERRM||')' END;
  END;
  PERFORM set_config('probe.p785', v_r, false);

  -- P786 (d) — medico sin relacion y paciente: ninguno es el lab ni super_admin -> 42501 los dos.
  v_e := '';
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',v_med,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    v_fila := public.registrar_examen_adjunto(v_exno, v_emp::text||'/ea-p786a.pdf', NULL);
    PERFORM set_config('role','none', true);
    v_e := v_e || ' medico=PASO(fila '||v_fila.id||')';
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    IF SQLSTATE <> '42501' THEN v_e := v_e || ' medico='||SQLSTATE; END IF;
  END;
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',v_pac,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    v_fila := public.registrar_examen_adjunto(v_exsi, v_emp::text||'/ea-p786b.pdf', NULL);
    PERFORM set_config('role','none', true);
    v_e := v_e || ' paciente=PASO(fila '||v_fila.id||')';
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    IF SQLSTATE <> '42501' THEN v_e := v_e || ' paciente='||SQLSTATE; END IF;
  END;
  PERFORM set_config('probe.p786',
    CASE WHEN v_e = '' THEN 'OK (42501 a medico sin relacion y a paciente)'
         ELSE 'ROJO (no dieron 42501:'||v_e||')' END, false);

  -- P787 (e) — la LECTURA de examen_adjuntos usa el mismo helper que storage y examenes.
  -- Hay 2 adjuntos sembrados (uno en el examen liberado, otro en el no liberado) + el de P783.
  -- El paciente solo debe ver el del examen LIBERADO; el medico sin relacion, ninguno.
  n_lab := -1; n_med := -1; n_pac := -1; v_e := '';
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',v_lab,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    SELECT count(*) INTO n_lab FROM public.examen_adjuntos a WHERE a.examen_id IN (v_exno, v_exsi);
    PERFORM set_config('role','none', true);
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true); v_e := v_e||' lab='||SQLSTATE;
  END;
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',v_med,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    SELECT count(*) INTO n_med FROM public.examen_adjuntos a WHERE a.examen_id IN (v_exno, v_exsi);
    PERFORM set_config('role','none', true);
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true); v_e := v_e||' med='||SQLSTATE;
  END;
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',v_pac,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    SELECT count(*) INTO n_pac FROM public.examen_adjuntos a WHERE a.examen_id IN (v_exno, v_exsi);
    PERFORM set_config('role','none', true);
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true); v_e := v_e||' pac='||SQLSTATE;
  END;
  PERFORM set_config('probe.p787',
    CASE WHEN v_e <> ''                       THEN 'FALLO (error leyendo:'||v_e||')'
         WHEN n_lab >= 3 AND n_med = 0 AND n_pac = 1
           THEN 'OK (lab ve '||n_lab||', medico sin relacion 0, paciente solo el liberado: 1)'
         ELSE 'ROJO (lab='||n_lab||' medico='||n_med||' paciente='||n_pac
              ||'; esperado lab>=3, medico=0, paciente=1)' END, false);

  -- P788 (f) — la policy DELETE del bucket. Se apaga el trigger protect_objects_delete para que
  -- decida la POLICY y no el trigger; si no, los tres casos darian 42501 y no mediria nada.
  n_adj := -1; n_exa := -1; n_lib := -1; v_e := '';
  BEGIN
    PERFORM set_config('storage.allow_delete_query','true', true);
    PERFORM set_config('request.jwt.claims', json_build_object('sub',v_lab,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);

    DELETE FROM storage.objects o
     WHERE o.bucket_id='resultados-examenes' AND o.name = v_emp::text||'/ea-fx-nolib.pdf';
    GET DIAGNOSTICS n_adj = ROW_COUNT;

    DELETE FROM storage.objects o
     WHERE o.bucket_id='resultados-examenes' AND o.name = v_url;
    GET DIAGNOSTICS n_exa = ROW_COUNT;

    DELETE FROM storage.objects o
     WHERE o.bucket_id='resultados-examenes' AND o.name = v_emp::text||'/ea-fx-libre.pdf';
    GET DIAGNOSTICS n_lib = ROW_COUNT;

    PERFORM set_config('role','none', true);
    RAISE EXCEPTION 'EA_RB';
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    IF SQLERRM <> 'EA_RB' THEN v_e := SQLSTATE||' '||SQLERRM; END IF;
  END;
  PERFORM set_config('probe.p788',
    CASE WHEN v_e <> ''                             THEN 'FALLO (no midio ROW_COUNT: '||v_e||')'
         WHEN n_adj = 0 AND n_exa = 0 AND n_lib = 1
           THEN 'OK (referenciado por adjunto 0, por examenes.archivo_url 0, libre 1)'
         ELSE 'ROJO (adjunto='||n_adj||' examen='||n_exa||' libre='||n_lib
              ||'; esperado 0/0/1)' END, false);

  -- P789 (g) — LA RAMA NUEVA del EXISTS de resultados_scoped_select, medida sobre storage.objects.
  -- Los dos objetos de esta probe estan adjuntados via examen_adjuntos y NINGUNO figura en
  -- examenes.archivo_url, asi que la unica via posible es la rama de adjuntos. El paciente
  -- tampoco entra por el brazo de tenant: su mi_empresa_proveedor() es NULL.
  -- Discrimina porque el paciente tiene que ver UNO y no DOS: el adjunto del examen liberado si,
  -- el del NO liberado no. Una rama que dejara pasar de mas daria 2 y saldria roja.
  n_lab := -1; n_med := -1; n_pac := -1; v_ok_lib := NULL; v_e := '';
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',v_lab,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    SELECT count(*) INTO n_lab FROM storage.objects o
     WHERE o.bucket_id='resultados-examenes'
       AND o.name IN (v_emp::text||'/ea-fx-lib.pdf', v_emp::text||'/ea-fx-nolib.pdf');
    PERFORM set_config('role','none', true);
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true); v_e := v_e||' lab='||SQLSTATE;
  END;
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',v_pac,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    SELECT count(*) INTO n_pac FROM storage.objects o
     WHERE o.bucket_id='resultados-examenes'
       AND o.name IN (v_emp::text||'/ea-fx-lib.pdf', v_emp::text||'/ea-fx-nolib.pdf');
    SELECT EXISTS (SELECT 1 FROM storage.objects o
                    WHERE o.bucket_id='resultados-examenes'
                      AND o.name = v_emp::text||'/ea-fx-lib.pdf') INTO v_ok_lib;
    PERFORM set_config('role','none', true);
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true); v_e := v_e||' pac='||SQLSTATE;
  END;
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',v_med,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    SELECT count(*) INTO n_med FROM storage.objects o
     WHERE o.bucket_id='resultados-examenes'
       AND o.name IN (v_emp::text||'/ea-fx-lib.pdf', v_emp::text||'/ea-fx-nolib.pdf');
    PERFORM set_config('role','none', true);
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true); v_e := v_e||' med='||SQLSTATE;
  END;
  PERFORM set_config('probe.p789',
    CASE WHEN v_e <> ''  THEN 'FALLO (error leyendo storage:'||v_e||')'
         WHEN n_lab = 2 AND n_pac = 1 AND COALESCE(v_ok_lib,false) AND n_med = 0
           THEN 'OK (el paciente abre el adjunto del examen liberado por la rama nueva; no ve el del no liberado; medico sin relacion 0; lab 2)'
         ELSE 'ROJO (lab='||n_lab||' paciente='||n_pac||' ve_el_liberado='||COALESCE(v_ok_lib::text,'NULL')
              ||' medico='||n_med||'; esperado 2 / 1 / true / 0)' END, false);

  PERFORM set_config('request.jwt.claims','', true);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('role','none', true);
  PERFORM set_config('request.jwt.claims','', true);
  PERFORM set_config('probe.p789','FALLO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;
SELECT set_config('role','none', true);


-- ============================================================
-- MIG 311 · revertir_liberacion_examen (RV_FX, P790-P795)
-- ============================================================
-- Revertir alcanza al MISMO conjunto que puede liberar: medico que ordeno, medico que atiende,
-- admin de la clinica, super_admin. El laboratorio NO, aunque vea el examen y pueda adjuntarle
-- archivos desde la mig 310 — P792 es la probe que fija esa decision.
--
-- LOS EXAMENES SE SIEMBRAN, no se toman de prod. Cuatro, uno por caso, para que ninguna probe
-- dependa del efecto de otra: si P793 ("ya no liberado") usara el examen que P790 acaba de
-- revertir, reordenar el archivo la rompe en silencio. Ademas prod tiene los 7 liberados con el
-- MISMO medico y la MISMA clinica, asi que un actor que pasa el gate para uno lo pasa para todos
-- y no se podria construir el caso negativo.
SELECT set_config('role','none', true);

-- ---------------- RV_FX — fixture ----------------
DO $$
DECLARE
  v_pac_id int; v_pac uuid; v_lab_emp uuid; v_lab uuid;
  v_med uuid; v_ajeno uuid;
  v_ok int; v_pacx int; v_nolib int; v_neg int;
  c_flib constant timestamptz := timestamptz '2026-01-15 10:00:00+00';
BEGIN
  -- paciente REAL con auth_user_id: paciente_es_mio() tiene que dar true de verdad
  SELECT p.id, p.auth_user_id INTO v_pac_id, v_pac
    FROM public.pacientes p WHERE p.auth_user_id IS NOT NULL ORDER BY p.id LIMIT 1;
  -- laboratorio con cuenta activa: el lab tiene que VER el examen para que P792 signifique algo
  SELECT cp.empresa_id, cp.id INTO v_lab_emp, v_lab
    FROM public.cuentas_proveedor cp WHERE cp.activo ORDER BY cp.id LIMIT 1;
  IF v_pac IS NULL OR v_lab IS NULL THEN
    PERFORM set_config('probe.rv_ready','0', false);
    PERFORM set_config('probe.rv_fx','ROJO (falta paciente con auth_user_id o cuenta de proveedor activa)', false);
    RETURN;
  END IF;

  -- dos medicos sembrados: el que "ordeno" los examenes y uno sin ninguna relacion
  v_med := gen_random_uuid();
  INSERT INTO auth.users (id) VALUES (v_med);
  INSERT INTO public.perfiles (id, email, nombre_completo, rol, activo)
    VALUES (v_med, 'rv.medico@example.invalid', 'QA RV medico del examen', 'medico', true);
  v_ajeno := gen_random_uuid();
  INSERT INTO auth.users (id) VALUES (v_ajeno);
  INSERT INTO public.perfiles (id, email, nombre_completo, rol, activo)
    VALUES (v_ajeno, 'rv.ajeno@example.invalid', 'QA RV medico sin relacion', 'medico', true);

  -- Cuatro examenes. clinica_id se deja en NULL A PROPOSITO: asi el gate depende solo de
  -- medico_id / medico_atiende_paciente / super_admin y el brazo de es_admin_clinica no puede
  -- colarse y dar un verde por el motivo equivocado.
  INSERT INTO public.examenes (tipo, paciente_id, medico_id, laboratorio_id, clinica_id, estado,
                               liberado_al_paciente, fecha_liberacion, liberado_por)
       VALUES ('QA RV revertible',  v_pac_id, v_med, v_lab_emp, NULL,
               'completado'::public.examen_estado, true,  c_flib, v_med)
  RETURNING id INTO v_ok;
  INSERT INTO public.examenes (tipo, paciente_id, medico_id, laboratorio_id, clinica_id, estado,
                               liberado_al_paciente, fecha_liberacion, liberado_por)
       VALUES ('QA RV paciente',    v_pac_id, v_med, v_lab_emp, NULL,
               'completado'::public.examen_estado, true,  c_flib, v_med)
  RETURNING id INTO v_pacx;
  INSERT INTO public.examenes (tipo, paciente_id, medico_id, laboratorio_id, clinica_id, estado,
                               liberado_al_paciente, fecha_liberacion, liberado_por)
       VALUES ('QA RV no liberado', v_pac_id, v_med, v_lab_emp, NULL,
               'completado'::public.examen_estado, false, NULL,   NULL)
  RETURNING id INTO v_nolib;
  INSERT INTO public.examenes (tipo, paciente_id, medico_id, laboratorio_id, clinica_id, estado,
                               liberado_al_paciente, fecha_liberacion, liberado_por)
       VALUES ('QA RV negativos',   v_pac_id, v_med, v_lab_emp, NULL,
               'completado'::public.examen_estado, true,  c_flib, v_med)
  RETURNING id INTO v_neg;

  -- adjunto sobre el examen de P794: sin el, "el paciente pierde los adjuntos" no se puede medir
  INSERT INTO public.examen_adjuntos (examen_id, storage_path, mime_type, subido_por)
    VALUES (v_pacx, v_lab_emp::text||'/rv-fx.pdf', 'application/pdf', v_lab);

  PERFORM set_config('probe.rv_pac',   v_pac::text, false);
  PERFORM set_config('probe.rv_med',   v_med::text, false);
  PERFORM set_config('probe.rv_ajeno', v_ajeno::text, false);
  PERFORM set_config('probe.rv_lab',   v_lab::text, false);
  PERFORM set_config('probe.rv_ok',    v_ok::text, false);
  PERFORM set_config('probe.rv_pacx',  v_pacx::text, false);
  PERFORM set_config('probe.rv_nolib', v_nolib::text, false);
  PERFORM set_config('probe.rv_neg',   v_neg::text, false);
  PERFORM set_config('probe.rv_flib',  c_flib::text, false);
  PERFORM set_config('probe.rv_ready','1', false);
  PERFORM set_config('probe.rv_fx','OK (4 examenes sembrados: revertible '||v_ok||', paciente '||v_pacx
    ||', no-liberado '||v_nolib||', negativos '||v_neg||'; 2 medicos y 1 adjunto)', false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('probe.rv_ready','0', false);
  PERFORM set_config('probe.rv_fx','ROJO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;
SELECT set_config('role','none', true);

-- ---------------- P790-P795 ----------------
DO $$
DECLARE
  v_pac uuid; v_med uuid; v_ajeno uuid; v_lab uuid;
  v_ok int; v_pacx int; v_nolib int; v_neg int; v_flib timestamptz;
  v_res jsonb; v_r text; n bigint;
  b_ver boolean; b_adj bigint; a_ver boolean; a_adj bigint;
  a_flib timestamptz; a_lpor uuid; a_rpor uuid; a_frev timestamptz; v_lib boolean;
  n_lab bigint; v_e text;
BEGIN
  IF coalesce(current_setting('probe.rv_ready', true),'0') <> '1' THEN
    PERFORM set_config('probe.p790','N/A (fixture RV no sembro)', false);
    PERFORM set_config('probe.p791','N/A', false); PERFORM set_config('probe.p792','N/A', false);
    PERFORM set_config('probe.p793','N/A', false); PERFORM set_config('probe.p794','N/A', false);
    PERFORM set_config('probe.p795','N/A', false);
    RETURN;
  END IF;
  v_pac   := current_setting('probe.rv_pac', true)::uuid;
  v_med   := current_setting('probe.rv_med', true)::uuid;
  v_ajeno := current_setting('probe.rv_ajeno', true)::uuid;
  v_lab   := current_setting('probe.rv_lab', true)::uuid;
  v_ok    := current_setting('probe.rv_ok', true)::int;
  v_pacx  := current_setting('probe.rv_pacx', true)::int;
  v_nolib := current_setting('probe.rv_nolib', true)::int;
  v_neg   := current_setting('probe.rv_neg', true)::int;
  v_flib  := current_setting('probe.rv_flib', true)::timestamptz;

  -- P790 (a) — CONTROL POSITIVO: el medico que ordeno revierte.
  v_r := 'no se ejecuto';
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',v_med,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    v_res := public.revertir_liberacion_examen(v_ok);
    PERFORM set_config('role','none', true);
    SELECT e.liberado_al_paciente INTO v_lib FROM public.examenes e WHERE e.id = v_ok;
    v_r := CASE WHEN COALESCE(v_res->>'revertido','') = 'true' AND v_lib = false
                THEN 'OK (revertido, liberado_al_paciente quedo en false)'
                ELSE 'ROJO (devolvio '||COALESCE(v_res::text,'NULL')||' y liberado='||COALESCE(v_lib::text,'NULL')||')' END;
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    v_r := 'ROJO (el medico que ordeno NO pudo revertir: '||SQLSTATE||' '||SQLERRM||')';
  END;
  PERFORM set_config('probe.p790', v_r, false);

  -- P791 (b) — medico SIN relacion: PE004.
  v_r := 'no se ejecuto';
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',v_ajeno,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    v_res := public.revertir_liberacion_examen(v_neg);
    PERFORM set_config('role','none', true);
    v_r := 'ROJO (un medico sin relacion revirtio: '||COALESCE(v_res::text,'NULL')||')';
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    v_r := CASE WHEN SQLSTATE = 'PE004' THEN 'OK (PE004 al medico sin relacion)'
                ELSE 'ROJO (corto con '||SQLSTATE||' en vez de PE004: '||SQLERRM||')' END;
  END;
  PERFORM set_config('probe.p791', v_r, false);

  -- P792 (c) — EL LABORATORIO. Es la probe que fija la decision de Oscar. Dos mitades, y la
  -- primera importa tanto como la segunda: si el lab NO viera el examen, el PE004 no probaria
  -- nada (cualquiera que no ve nada "no puede"). Tiene que VER y aun asi no poder.
  n_lab := -1; v_e := '';
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',v_lab,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    SELECT count(*) INTO n_lab FROM public.examenes e WHERE e.id = v_neg;
    PERFORM set_config('role','none', true);
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true); v_e := v_e||' ver='||SQLSTATE;
  END;
  v_r := 'no se ejecuto';
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',v_lab,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    v_res := public.revertir_liberacion_examen(v_neg);
    PERFORM set_config('role','none', true);
    v_r := 'ROJO (el LABORATORIO revirtio: '||COALESCE(v_res::text,'NULL')||')';
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    v_r := CASE WHEN SQLSTATE = 'PE004' THEN 'PE004'
                ELSE 'ROJO (corto con '||SQLSTATE||' en vez de PE004: '||SQLERRM||')' END;
  END;
  PERFORM set_config('probe.p792',
    CASE WHEN v_e <> ''         THEN 'FALLO (no pudo medir si el lab ve:'||v_e||')'
         WHEN v_r <> 'PE004'    THEN v_r
         WHEN n_lab <> 1        THEN 'ROJO (el lab NO ve el examen (n='||n_lab||'): el PE004 no prueba nada)'
         ELSE 'OK (el lab VE el examen y aun asi recibe PE004)' END, false);

  -- P793 (d) — revertir algo que no estaba liberado: no-op, sin excepcion y sin gastar errcode.
  v_r := 'no se ejecuto';
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',v_med,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    v_res := public.revertir_liberacion_examen(v_nolib);
    PERFORM set_config('role','none', true);
    SELECT e.revertido_por IS NULL AND e.fecha_reversion IS NULL INTO v_lib
      FROM public.examenes e WHERE e.id = v_nolib;
    v_r := CASE WHEN COALESCE(v_res->>'ya_no_liberado','') = 'true' AND v_lib
                THEN 'OK (ya_no_liberado sin excepcion, y no ensucio revertido_por/fecha_reversion)'
                WHEN COALESCE(v_res->>'ya_no_liberado','') = 'true'
                THEN 'ROJO (ya_no_liberado OK pero escribio revertido_por/fecha_reversion en un no-op)'
                ELSE 'ROJO (devolvio '||COALESCE(v_res::text,'NULL')||')' END;
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    v_r := 'ROJO (el no-op lanzo excepcion '||SQLSTATE||': '||SQLERRM||')';
  END;
  PERFORM set_config('probe.p793', v_r, false);

  -- P794 (e) — el paciente pierde el examen Y sus adjuntos en la misma operacion.
  -- Se mide ANTES y DESPUES: un "no lo ve" al final no prueba nada si tampoco lo veia antes.
  b_ver := NULL; b_adj := -1; a_ver := NULL; a_adj := -1; v_e := '';
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',v_pac,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    b_ver := private.puede_ver_examen(v_pacx);
    SELECT count(*) INTO b_adj FROM public.examen_adjuntos a WHERE a.examen_id = v_pacx;
    PERFORM set_config('role','none', true);
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true); v_e := v_e||' antes='||SQLSTATE;
  END;
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',v_med,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    PERFORM public.revertir_liberacion_examen(v_pacx);
    PERFORM set_config('role','none', true);
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true); v_e := v_e||' revertir='||SQLSTATE;
  END;
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',v_pac,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    a_ver := private.puede_ver_examen(v_pacx);
    SELECT count(*) INTO a_adj FROM public.examen_adjuntos a WHERE a.examen_id = v_pacx;
    PERFORM set_config('role','none', true);
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true); v_e := v_e||' despues='||SQLSTATE;
  END;
  PERFORM set_config('probe.p794',
    CASE WHEN v_e <> ''                          THEN 'FALLO (error midiendo:'||v_e||')'
         WHEN NOT COALESCE(b_ver,false) OR b_adj < 1
           THEN 'ROJO (control positivo caido: ANTES el paciente veia examen='||COALESCE(b_ver::text,'NULL')
                ||' adjuntos='||b_adj||'; la probe no mide nada)'
         WHEN COALESCE(a_ver,true) OR a_adj <> 0
           THEN 'ROJO (DESPUES sigue viendo examen='||COALESCE(a_ver::text,'NULL')||' adjuntos='||a_adj||')'
         ELSE 'OK (antes examen=true adjuntos='||b_adj||'; despues examen=false adjuntos=0)' END, false);

  -- P795 (f) — la auditoria: revertir NO pisa el rastro de la liberacion.
  -- Se mira el examen que P790 ya revirtio, con el valor sembrado por el fixture como referencia.
  BEGIN
    SELECT e.fecha_liberacion, e.liberado_por, e.revertido_por, e.fecha_reversion
      INTO a_flib, a_lpor, a_rpor, a_frev
      FROM public.examenes e WHERE e.id = v_ok;
    PERFORM set_config('probe.p795',
      CASE WHEN a_flib IS DISTINCT FROM v_flib
             THEN 'ROJO (fecha_liberacion cambio: sembrada '||v_flib||', ahora '||COALESCE(a_flib::text,'NULL')||')'
           WHEN a_lpor IS DISTINCT FROM v_med
             THEN 'ROJO (liberado_por cambio: sembrado '||v_med||', ahora '||COALESCE(a_lpor::text,'NULL')||')'
           WHEN a_rpor IS DISTINCT FROM v_med
             THEN 'ROJO (revertido_por deberia ser quien revirtio ('||v_med||'), es '||COALESCE(a_rpor::text,'NULL')||')'
           WHEN a_frev IS NULL
             THEN 'ROJO (fecha_reversion quedo NULL)'
           ELSE 'OK (fecha_liberacion y liberado_por intactas; revertido_por y fecha_reversion llenas)' END, false);
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('probe.p795','FALLO ('||SQLSTATE||' '||SQLERRM||')', false);
  END;

  PERFORM set_config('request.jwt.claims','', true);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('role','none', true);
  PERFORM set_config('request.jwt.claims','', true);
  PERFORM set_config('probe.p795','FALLO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;
SELECT set_config('role','none', true);


-- ============================================================
-- MIG 312 · notificar_resultado_examen: ruta al paciente + metadata (NR_FX, P796-P799)
-- ============================================================
-- La notificacion que el laboratorio le manda al medico apuntaba a /medico/citas, una lista sin
-- relacion con el examen, y salia con metadata en el default '{}'. Ahora apunta a la ficha del
-- paciente y lleva {"examen_id": N, "paciente_id": M}.
--
-- P799 esta aca porque esto fue un CREATE OR REPLACE COMPLETO de la funcion: el gate no se toco
-- en el diseno, pero reescribir el cuerpo entero es exactamente la forma en que un gate se pierde
-- sin que nadie lo note.
SELECT set_config('role','none', true);

-- ---------------- NR_FX — fixture ----------------
DO $$
DECLARE
  v_emp uuid; v_lab uuid; v_ajeno uuid; v_med uuid; v_pac int;
  v_ex_con int; v_ex_sin int;
BEGIN
  SELECT cp.empresa_id, cp.id INTO v_emp, v_lab
    FROM public.cuentas_proveedor cp WHERE cp.activo ORDER BY cp.id LIMIT 1;
  SELECT cp.id INTO v_ajeno FROM public.cuentas_proveedor cp
   WHERE cp.activo AND cp.empresa_id IS DISTINCT FROM v_emp ORDER BY cp.id LIMIT 1;
  SELECT p.id INTO v_pac FROM public.pacientes p ORDER BY p.id LIMIT 1;
  IF v_emp IS NULL OR v_lab IS NULL OR v_ajeno IS NULL OR v_pac IS NULL THEN
    PERFORM set_config('probe.nr_ready','0', false);
    PERFORM set_config('probe.nr_fx','ROJO (faltan 2 empresas proveedoras activas o un paciente)', false);
    RETURN;
  END IF;

  -- El medico destinatario se siembra: notificaciones.usuario_id tiene FK a auth.users, y ademas
  -- un medico propio garantiza que las notificaciones que lee la probe son SOLO las suyas, sin
  -- mezclarse con las ~52 que ya tienen los medicos reales.
  v_med := gen_random_uuid();
  INSERT INTO auth.users (id) VALUES (v_med);
  INSERT INTO public.perfiles (id, email, nombre_completo, rol, activo)
    VALUES (v_med, 'nr.medico@example.invalid', 'QA NR medico destinatario', 'medico', true);

  INSERT INTO public.examenes (tipo, paciente_id, medico_id, laboratorio_id, estado)
       VALUES ('QA NR con paciente', v_pac, v_med, v_emp, 'completado'::public.examen_estado)
  RETURNING id INTO v_ex_con;
  -- paciente_id NULL = el examen walk-in que el laboratorio carga sin paciente registrado
  INSERT INTO public.examenes (tipo, paciente_id, medico_id, laboratorio_id, estado)
       VALUES ('QA NR walk-in', NULL, v_med, v_emp, 'completado'::public.examen_estado)
  RETURNING id INTO v_ex_sin;

  PERFORM set_config('probe.nr_lab',    v_lab::text, false);
  PERFORM set_config('probe.nr_ajeno',  v_ajeno::text, false);
  PERFORM set_config('probe.nr_med',    v_med::text, false);
  PERFORM set_config('probe.nr_pac',    v_pac::text, false);
  PERFORM set_config('probe.nr_excon',  v_ex_con::text, false);
  PERFORM set_config('probe.nr_exsin',  v_ex_sin::text, false);
  PERFORM set_config('probe.nr_ready','1', false);
  PERFORM set_config('probe.nr_fx','OK (lab '||v_emp::text||'; examen con paciente '||v_ex_con
    ||' (pac '||v_pac||'), walk-in '||v_ex_sin||'; medico destinatario sembrado)', false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('probe.nr_ready','0', false);
  PERFORM set_config('probe.nr_fx','ROJO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;
SELECT set_config('role','none', true);

-- ---------------- P796-P799 ----------------
DO $$
DECLARE
  v_lab uuid; v_ajeno uuid; v_med uuid; v_pac int; v_excon int; v_exsin int;
  u_con text; u_sin text; m_con jsonb; m_sin jsonb; v_r text; n bigint;
BEGIN
  IF coalesce(current_setting('probe.nr_ready', true),'0') <> '1' THEN
    PERFORM set_config('probe.p796','N/A (fixture NR no sembro)', false);
    PERFORM set_config('probe.p797','N/A', false); PERFORM set_config('probe.p798','N/A', false);
    PERFORM set_config('probe.p799','N/A', false);
    RETURN;
  END IF;
  v_lab   := current_setting('probe.nr_lab', true)::uuid;
  v_ajeno := current_setting('probe.nr_ajeno', true)::uuid;
  v_med   := current_setting('probe.nr_med', true)::uuid;
  v_pac   := current_setting('probe.nr_pac', true)::int;
  v_excon := current_setting('probe.nr_excon', true)::int;
  v_exsin := current_setting('probe.nr_exsin', true)::int;

  -- Una sola llamada por examen, con el rol del laboratorio duenio. P796/P797/P798 leen la misma
  -- fila desde angulos distintos, asi que se dispara una vez y se mide tres veces.
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',v_lab,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    PERFORM public.notificar_resultado_examen(v_excon);
    PERFORM public.notificar_resultado_examen(v_exsin);
    PERFORM set_config('role','none', true);
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
  END;

  SELECT n2.accion_url, n2.metadata INTO u_con, m_con FROM public.notificaciones n2
   WHERE n2.usuario_id = v_med AND n2.metadata->>'examen_id' = v_excon::text
   ORDER BY n2.created_at DESC LIMIT 1;
  SELECT n2.accion_url, n2.metadata INTO u_sin, m_sin FROM public.notificaciones n2
   WHERE n2.usuario_id = v_med AND n2.metadata->>'examen_id' = v_exsin::text
   ORDER BY n2.created_at DESC LIMIT 1;

  -- P796 (a) — la ruta a la ficha del paciente, comparada contra la cadena exacta.
  PERFORM set_config('probe.p796',
    CASE WHEN u_con IS NULL THEN 'ROJO (no se creo la notificacion del examen con paciente)'
         WHEN u_con = '/medico/pacientes/'||v_pac::text||'/detalle'
           THEN 'OK (accion_url = '||u_con||')'
         ELSE 'ROJO (accion_url = '||COALESCE(u_con,'NULL')
              ||', se esperaba /medico/pacientes/'||v_pac::text||'/detalle)' END, false);

  -- P797 (b) — el walk-in cae al destino historico. Sin esta probe, un `||` sobre un paciente_id
  -- NULL daria la cadena entera en NULL y la notificacion quedaria SIN accion_url, que es peor
  -- que el /medico/citas de antes.
  PERFORM set_config('probe.p797',
    CASE WHEN u_sin IS NULL THEN 'ROJO (walk-in: accion_url quedo NULL o no se creo la notificacion)'
         WHEN u_sin = '/medico/citas' THEN 'OK (walk-in cae a /medico/citas)'
         ELSE 'ROJO (walk-in apunta a '||u_sin||')' END, false);

  -- P798 (c) — metadata en los dos casos. En el walk-in la clave paciente_id tiene que ESTAR y
  -- valer null: un front que la lea distingue "sin paciente" de "notificacion vieja sin metadata".
  PERFORM set_config('probe.p798',
    CASE WHEN m_con IS NULL OR m_sin IS NULL THEN 'ROJO (falta alguna de las dos notificaciones)'
         WHEN m_con->>'examen_id' <> v_excon::text OR m_con->>'paciente_id' <> v_pac::text
           THEN 'ROJO (metadata con paciente = '||m_con::text||')'
         WHEN m_sin->>'examen_id' <> v_exsin::text
           THEN 'ROJO (metadata walk-in sin examen_id = '||m_sin::text||')'
         WHEN NOT (m_sin ? 'paciente_id') OR m_sin->>'paciente_id' IS NOT NULL
           THEN 'ROJO (metadata walk-in deberia traer paciente_id en null, trae '||m_sin::text||')'
         ELSE 'OK (con paciente '||m_con::text||' · walk-in '||m_sin::text||')' END, false);

  -- P799 (d) — EL GATE. No lo cambio el diseno, pero la 312 reescribio el cuerpo entero de la
  -- funcion y asi es como un gate desaparece sin que nadie lo note. Un laboratorio de OTRA
  -- empresa sobre el mismo examen tiene que seguir recibiendo PT002.
  v_r := 'no se ejecuto';
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',v_ajeno,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    PERFORM public.notificar_resultado_examen(v_excon);
    PERFORM set_config('role','none', true);
    v_r := 'ROJO (un laboratorio AJENO pudo notificar el examen de otra empresa)';
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    v_r := CASE WHEN SQLSTATE = 'PT002' THEN 'PT002'
                ELSE 'ROJO (corto con '||SQLSTATE||' en vez de PT002: '||SQLERRM||')' END;
  END;
  -- Contraprueba del contador: el lab ajeno no debe haber dejado NINGUNA fila extra.
  SELECT count(*) INTO n FROM public.notificaciones n3
   WHERE n3.usuario_id = v_med AND n3.metadata->>'examen_id' = v_excon::text;
  PERFORM set_config('probe.p799',
    CASE WHEN v_r <> 'PT002' THEN v_r
         WHEN n <> 1 THEN 'ROJO (PT002 OK pero quedaron '||n||' notificaciones para ese examen, se esperaba 1)'
         ELSE 'OK (PT002 al lab ajeno, y sigue habiendo 1 sola notificacion del examen)' END, false);

  PERFORM set_config('request.jwt.claims','', true);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('role','none', true);
  PERFORM set_config('request.jwt.claims','', true);
  PERFORM set_config('probe.p799','FALLO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;
SELECT set_config('role','none', true);

-- ================================================================================
-- MIG 325 — PROBES: guard anti-auto-escalada del paciente sobre public.pacientes
-- Actor Paciente QA elegido COMO postgres en PG_FX antes de impersonar.
-- Camino legitimo de escritura de columnas privilegiadas (0c): SOLO admin_pais/super_admin
-- via la policy ALL "Admin ve pacientes de su pais" (auth.uid()=admin != auth_user_id del
-- paciente -> el guard no interviene). NO existe policy UPDATE de medico sobre pacientes.
-- ================================================================================
-- ---------------- PG_FX — fixture ----------------
DO $$
DECLARE v_uid uuid; v_pac bigint; v_otro bigint; v_admin uuid;
BEGIN
  SELECT p.auth_user_id, p.id INTO v_uid, v_pac
    FROM public.pacientes p WHERE p.email='paciente.qa@ezpayconnect.com';
  SELECT p.id INTO v_otro FROM public.pacientes p
   WHERE p.id <> v_pac AND p.auth_user_id IS NOT NULL ORDER BY p.id LIMIT 1;
  SELECT pf.id INTO v_admin FROM public.perfiles pf
    JOIN public.pacientes pq ON pq.email='paciente.qa@ezpayconnect.com'
   WHERE pf.rol='admin_pais' AND pf.activo AND pf.pais_id = pq.pais_id LIMIT 1;
  IF v_uid IS NULL OR v_pac IS NULL THEN
    PERFORM set_config('probe.pg_ready','0', false);
    PERFORM set_config('probe.pg_fx','ROJO (no se encontro Paciente QA con auth_user_id)', false);
    RETURN;
  END IF;
  PERFORM set_config('probe.pg_uid', v_uid::text, false);
  PERFORM set_config('probe.pg_pac', v_pac::text, false);
  PERFORM set_config('probe.pg_otro', COALESCE(v_otro::text,''), false);
  PERFORM set_config('probe.pg_admin', COALESCE(v_admin::text,''), false);
  PERFORM set_config('probe.pg_ready','1', false);
  PERFORM set_config('probe.pg_fx','OK (QA pac '||v_pac||'; otro_pac '||COALESCE(v_otro::text,'<none>')
    ||'; admin_pais '||COALESCE(v_admin::text,'<none>')||')', false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('probe.pg_ready','0', false);
  PERFORM set_config('probe.pg_fx','ROJO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;
SELECT set_config('role','none', true);

-- ---------------- P801-P810 — el paciente NO puede cambiar columnas privilegiadas de su fila ----------------
DO $$
DECLARE
  cols text[][] := ARRAY[
    ARRAY['p801','medico_id','gen_random_uuid()'],
    ARRAY['p802','medico_primario_id','gen_random_uuid()'],
    ARRAY['p803','clinica_primaria_id','gen_random_uuid()'],
    ARRAY['p804','pais_id','gen_random_uuid()'],
    ARRAY['p805','activo','false'],
    ARRAY['p806','email','''__hack__@x.invalid'''],
    ARRAY['p807','foto_path','''hack/otro.jpg'''],
    ARRAY['p808','id','999999999'],
    ARRAY['p809','created_at','(now() - interval ''365 days'')'],
    ARRAY['p810','auth_user_id','gen_random_uuid()']
  ];
  v_uid uuid; v_pac bigint; k text; col text; val text; v_before text; v_after text; i int;
BEGIN
  IF coalesce(current_setting('probe.pg_ready', true),'0') <> '1' THEN
    FOR i IN 1..array_length(cols,1) LOOP PERFORM set_config('probe.'||cols[i][1],'N/A (fixture PG no sembro)', false); END LOOP;
    RETURN;
  END IF;
  FOR i IN 1..array_length(cols,1) LOOP PERFORM set_config('probe.'||cols[i][1],'FALLO (no ejecuto)', false); END LOOP;
  v_uid := current_setting('probe.pg_uid', true)::uuid;
  v_pac := current_setting('probe.pg_pac', true)::bigint;
  FOR i IN 1..array_length(cols,1) LOOP
    k := cols[i][1]; col := cols[i][2]; val := cols[i][3];
    EXECUTE format('SELECT %I::text FROM public.pacientes WHERE id=%s', col, v_pac) INTO v_before;
    BEGIN
      PERFORM set_config('request.jwt.claims', json_build_object('sub', v_uid::text, 'role','authenticated')::text, true);
      PERFORM set_config('role','authenticated', true);
      EXECUTE format('UPDATE public.pacientes SET %I = %s WHERE id=%s', col, val, v_pac);
      PERFORM set_config('role','none', true);
      PERFORM set_config('probe.'||k, 'ROJO (paciente cambio '||col||' de su propia fila sin 42501)', false);
    EXCEPTION
      WHEN insufficient_privilege THEN
        PERFORM set_config('role','none', true);
        EXECUTE format('SELECT %I::text FROM public.pacientes WHERE id=%s', col, v_pac) INTO v_after;
        PERFORM set_config('probe.'||k, CASE WHEN v_after IS NOT DISTINCT FROM v_before
            THEN 'OK (42501 y '||col||' intacto)'
            ELSE 'ROJO (42501 pero '||col||' cambio: '||COALESCE(v_before,'NULL')||' -> '||COALESCE(v_after,'NULL')||')' END, false);
      WHEN OTHERS THEN
        PERFORM set_config('role','none', true);
        PERFORM set_config('probe.'||k, 'ROJO ('||col||' corto con '||SQLSTATE||' en vez de 42501: '||SQLERRM||')', false);
    END;
  END LOOP;
  PERFORM set_config('request.jwt.claims','', true);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('role','none', true);
  PERFORM set_config('probe.p801','FALLO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;
SELECT set_config('role','none', true);

-- ---------------- P811 — el paciente SI puede cambiar las columnas editables del form ----------------
DO $$
DECLARE v_uid uuid; v_pac bigint; n int; v_tel text;
BEGIN
  IF coalesce(current_setting('probe.pg_ready', true),'0') <> '1' THEN PERFORM set_config('probe.p811','N/A (fixture PG no sembro)', false); RETURN; END IF;
  v_uid := current_setting('probe.pg_uid', true)::uuid; v_pac := current_setting('probe.pg_pac', true)::bigint;
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_uid::text, 'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    UPDATE public.pacientes SET nombre='QA N', apellido='QA A', telefono='+502 5555-0000',
      fecha_nacimiento='1990-01-01', genero='otro', direccion='Calle QA 123',
      alergias='ninguna QA', notas='nota QA', emergencia_nombre='Contacto QA', emergencia_telefono='+502 5555-1111'
     WHERE id=v_pac;
    GET DIAGNOSTICS n = ROW_COUNT;
    PERFORM set_config('role','none', true);
    SELECT telefono INTO v_tel FROM public.pacientes WHERE id=v_pac;
    PERFORM set_config('probe.p811', CASE WHEN n=1 AND v_tel='+502 5555-0000'
        THEN 'OK (1 fila, columnas editables del form cambiadas)'
        ELSE 'ROJO (n='||n||', telefono='||COALESCE(v_tel,'NULL')||')' END, false);
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('role','none', true);
    PERFORM set_config('probe.p811','ROJO (columnas editables cortaron con '||SQLSTATE||': '||SQLERRM||')', false);
  END;
  PERFORM set_config('request.jwt.claims','', true);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none', true); PERFORM set_config('probe.p811','FALLO ('||SQLSTATE||')', false);
END $$;
SELECT set_config('role','none', true);

-- ---------------- P812 — el paciente NO puede tocar la fila de otro paciente (0 filas) ----------------
DO $$
DECLARE v_uid uuid; v_otro bigint; n int;
BEGIN
  IF coalesce(current_setting('probe.pg_ready',true),'0')<>'1' OR coalesce(current_setting('probe.pg_otro',true),'')='' THEN
    PERFORM set_config('probe.p812','N/A (sin otro paciente o fixture no sembro)', false); RETURN; END IF;
  v_uid := current_setting('probe.pg_uid',true)::uuid; v_otro := current_setting('probe.pg_otro',true)::bigint;
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',v_uid::text,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    UPDATE public.pacientes SET alergias='HACK QA' WHERE id=v_otro;
    GET DIAGNOSTICS n = ROW_COUNT;
    PERFORM set_config('role','none', true);
    PERFORM set_config('probe.p812', CASE WHEN n=0 THEN 'OK (0 filas: no toca la fila de otro paciente)' ELSE 'ROJO (afecto '||n||' filas de otro paciente)' END, false);
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none', true);
    PERFORM set_config('probe.p812','ROJO (corto con '||SQLSTATE||')', false);
  END;
  PERFORM set_config('request.jwt.claims','', true);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none', true); PERFORM set_config('probe.p812','FALLO ('||SQLSTATE||')', false);
END $$;
SELECT set_config('role','none', true);

-- ---------------- P813 — NO-REGRESION: admin_pais del pais del paciente SI puede cambiar medico_id ----------------
-- Camino legitimo unico (0c): policy ALL "Admin ve pacientes de su pais". No hay policy UPDATE de
-- medico sobre pacientes, asi que NO se prueba un camino de medico (no se inventa uno).
DO $$
DECLARE v_admin uuid; v_pac bigint; v_before uuid; v_after uuid; n int;
BEGIN
  IF coalesce(current_setting('probe.pg_ready',true),'0')<>'1' OR coalesce(current_setting('probe.pg_admin',true),'')='' THEN
    PERFORM set_config('probe.p813','N/A (no hay admin_pais activo en el pais del paciente QA)', false); RETURN; END IF;
  v_admin := current_setting('probe.pg_admin',true)::uuid; v_pac := current_setting('probe.pg_pac',true)::bigint;
  SELECT medico_id INTO v_before FROM public.pacientes WHERE id=v_pac;
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',v_admin::text,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated', true);
    UPDATE public.pacientes SET medico_id=gen_random_uuid() WHERE id=v_pac;
    GET DIAGNOSTICS n = ROW_COUNT;
    PERFORM set_config('role','none', true);
    SELECT medico_id INTO v_after FROM public.pacientes WHERE id=v_pac;
    PERFORM set_config('probe.p813', CASE WHEN n=1 AND v_after IS DISTINCT FROM v_before
        THEN 'OK (admin_pais cambio medico_id por el camino legitimo; el guard no lo bloquea)'
        ELSE 'ROJO (n='||n||': el guard bloqueo al admin_pais o RLS no dejo)' END, false);
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none', true);
    PERFORM set_config('probe.p813','ROJO (admin_pais corto con '||SQLSTATE||': '||SQLERRM||')', false);
  END;
  PERFORM set_config('request.jwt.claims','', true);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none', true); PERFORM set_config('probe.p813','FALLO ('||SQLSTATE||')', false);
END $$;
SELECT set_config('role','none', true);

-- ---------------- P814 — estructural: trigger habilitado + funcion INVOKER + search_path '' ----------------
DO $$
DECLARE v_tgen char; v_sec boolean; v_cfg text[]; v_msg text := '';
BEGIN
  SELECT t.tgenabled INTO v_tgen FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace ns ON ns.oid=c.relnamespace
    WHERE ns.nspname='public' AND c.relname='pacientes' AND t.tgname='trg_pacientes_guard_update' AND NOT t.tgisinternal;
  SELECT p.prosecdef, p.proconfig INTO v_sec, v_cfg FROM pg_proc p JOIN pg_namespace ns ON ns.oid=p.pronamespace
    WHERE ns.nspname='private' AND p.proname='pacientes_guard_update';
  IF v_tgen IS NULL THEN v_msg := v_msg||'trigger ausente; '; ELSIF v_tgen<>'O' THEN v_msg := v_msg||'trigger no habilitado ('||v_tgen||'); '; END IF;
  IF v_sec IS NULL THEN v_msg := v_msg||'funcion ausente; ';
  ELSE
    IF v_sec<>false THEN v_msg := v_msg||'funcion DEFINER (debe ser INVOKER); '; END IF;
    IF v_cfg IS NULL OR NOT EXISTS (SELECT 1 FROM unnest(v_cfg) e WHERE e LIKE 'search_path=%' AND btrim(split_part(e,'=',2),'"') = '') THEN v_msg := v_msg||'search_path != vacio; '; END IF;
  END IF;
  PERFORM set_config('probe.p814', CASE WHEN v_msg='' THEN 'OK (trigger habilitado + funcion INVOKER + search_path vacio)' ELSE 'ROJO ('||v_msg||')' END, false);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p814','FALLO ('||SQLSTATE||')', false);
END $$;
SELECT set_config('role','none', true);


-- ================================================================================
-- MIG 323 — PROBES: gate de estado de empresa (lote 2). Actor admin elegido como postgres.
-- Grupo B: activa->OK, suspendida->42501. Grupo A: activa->valor, suspendida->NULL/false.
-- Onboarding: rechazada ve su empresa + B bloqueada; pendiente ve empresa+equipo + UPDATE perfil.
-- Estructural: 17 B con exigir_empresa_activa; 2 exentas sin.
-- ================================================================================
-- ---------------- PGR_FX ----------------
DO $$
DECLARE v_admin uuid; v_emp uuid; v_co uuid;
BEGIN
  SELECT cp.id, cp.empresa_id INTO v_admin, v_emp FROM public.cuentas_proveedor cp
    JOIN public.empresas_proveedoras e ON e.id=cp.empresa_id
   WHERE cp.activo AND cp.rol_en_empresa='admin' AND e.estado='activa'
     AND EXISTS (SELECT 1 FROM public.cuentas_proveedor c2 WHERE c2.empresa_id=cp.empresa_id AND c2.id<>cp.id AND c2.activo)
   ORDER BY cp.id LIMIT 1;
  IF v_admin IS NULL THEN
    PERFORM set_config('probe.pgr_ready','0',false);
    PERFORM set_config('probe.pgr_fx','ROJO (no hay admin de empresa activa con co-miembro)',false); RETURN;
  END IF;
  SELECT id INTO v_co FROM public.cuentas_proveedor WHERE empresa_id=v_emp AND id<>v_admin AND activo LIMIT 1;
  PERFORM set_config('probe.pgr_admin', v_admin::text, false);
  PERFORM set_config('probe.pgr_emp', v_emp::text, false);
  PERFORM set_config('probe.pgr_co', v_co::text, false);
  PERFORM set_config('probe.pgr_ready','1', false);
  PERFORM set_config('probe.pgr_fx','OK (admin '||v_admin::text||', empresa '||v_emp::text||', co '||v_co::text||')', false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('probe.pgr_ready','0',false);
  PERFORM set_config('probe.pgr_fx','ROJO ('||SQLSTATE||' '||SQLERRM||')',false);
END $$;
SELECT set_config('role','none', true);

-- ---------------- P815-P818 GRUPO B: activa OK / suspendida 42501 ----------------
DO $$
DECLARE v_admin uuid; v_emp uuid; v_co uuid; claims text; st text;
  r_act text; r_sus text; ss text;
BEGIN
  IF coalesce(current_setting('probe.pgr_ready',true),'0')<>'1' THEN
    PERFORM set_config('probe.p815','N/A',false); PERFORM set_config('probe.p816','N/A',false);
    PERFORM set_config('probe.p817','N/A',false); PERFORM set_config('probe.p818','N/A',false); RETURN;
  END IF;
  v_admin:=current_setting('probe.pgr_admin',true)::uuid; v_emp:=current_setting('probe.pgr_emp',true)::uuid; v_co:=current_setting('probe.pgr_co',true)::uuid;
  claims:=json_build_object('sub',v_admin::text,'role','authenticated')::text;

  -- P815 staff: cambiar_estado_miembro_proveedor(co,false)
  UPDATE public.empresas_proveedoras SET estado='activa' WHERE id=v_emp;
  r_act:='?'; r_sus:='?';
  BEGIN PERFORM set_config('request.jwt.claims',claims,true); PERFORM set_config('role','authenticated',true);
    PERFORM public.cambiar_estado_miembro_proveedor(v_co,false); PERFORM set_config('role','none',true); r_act:='OK';
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true); r_act:='ERR '||SQLSTATE; END;
  UPDATE public.empresas_proveedoras SET estado='suspendida' WHERE id=v_emp;
  BEGIN PERFORM set_config('request.jwt.claims',claims,true); PERFORM set_config('role','authenticated',true);
    PERFORM public.cambiar_estado_miembro_proveedor(v_co,true); PERFORM set_config('role','none',true); r_sus:='NO_BLOQUEO';
  EXCEPTION WHEN insufficient_privilege THEN PERFORM set_config('role','none',true); r_sus:='42501';
           WHEN OTHERS THEN PERFORM set_config('role','none',true); r_sus:='ERR '||SQLSTATE; END;
  PERFORM set_config('probe.p815', CASE WHEN r_act='OK' AND r_sus='42501' THEN 'OK (staff: activa OK, suspendida 42501)' ELSE 'ROJO (activa='||r_act||' suspendida='||r_sus||')' END, false);

  -- P816 chat: contactos_chat()
  UPDATE public.empresas_proveedoras SET estado='activa' WHERE id=v_emp;
  BEGIN PERFORM set_config('request.jwt.claims',claims,true); PERFORM set_config('role','authenticated',true);
    PERFORM count(*) FROM public.contactos_chat(); PERFORM set_config('role','none',true); r_act:='OK';
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true); r_act:='ERR '||SQLSTATE; END;
  UPDATE public.empresas_proveedoras SET estado='suspendida' WHERE id=v_emp;
  BEGIN PERFORM set_config('request.jwt.claims',claims,true); PERFORM set_config('role','authenticated',true);
    PERFORM count(*) FROM public.contactos_chat(); PERFORM set_config('role','none',true); r_sus:='NO_BLOQUEO';
  EXCEPTION WHEN insufficient_privilege THEN PERFORM set_config('role','none',true); r_sus:='42501';
           WHEN OTHERS THEN PERFORM set_config('role','none',true); r_sus:='ERR '||SQLSTATE; END;
  PERFORM set_config('probe.p816', CASE WHEN r_act='OK' AND r_sus='42501' THEN 'OK (chat: activa OK, suspendida 42501)' ELSE 'ROJO (activa='||r_act||' suspendida='||r_sus||')' END, false);

  -- P817 visitas: get_visitas_proveedor()
  UPDATE public.empresas_proveedoras SET estado='activa' WHERE id=v_emp;
  BEGIN PERFORM set_config('request.jwt.claims',claims,true); PERFORM set_config('role','authenticated',true);
    PERFORM public.get_visitas_proveedor(); PERFORM set_config('role','none',true); r_act:='OK';
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true); r_act:='ERR '||SQLSTATE; END;
  UPDATE public.empresas_proveedoras SET estado='suspendida' WHERE id=v_emp;
  BEGIN PERFORM set_config('request.jwt.claims',claims,true); PERFORM set_config('role','authenticated',true);
    PERFORM public.get_visitas_proveedor(); PERFORM set_config('role','none',true); r_sus:='NO_BLOQUEO';
  EXCEPTION WHEN insufficient_privilege THEN PERFORM set_config('role','none',true); r_sus:='42501';
           WHEN OTHERS THEN PERFORM set_config('role','none',true); r_sus:='ERR '||SQLSTATE; END;
  PERFORM set_config('probe.p817', CASE WHEN r_act='OK' AND r_sus='42501' THEN 'OK (visitas: activa OK, suspendida 42501)' ELSE 'ROJO (activa='||r_act||' suspendida='||r_sus||')' END, false);

  -- P818 invitacion: invitar_miembro_proveedor (gate 42501 antes de validar args). suspendida->42501.
  UPDATE public.empresas_proveedoras SET estado='suspendida' WHERE id=v_emp;
  BEGIN PERFORM set_config('request.jwt.claims',claims,true); PERFORM set_config('role','authenticated',true);
    PERFORM public.invitar_miembro_proveedor('x@x.invalid','QA','visitador_medico',NULL); PERFORM set_config('role','none',true); r_sus:='NO_BLOQUEO';
  EXCEPTION WHEN insufficient_privilege THEN PERFORM set_config('role','none',true); r_sus:='42501';
           WHEN OTHERS THEN PERFORM set_config('role','none',true); r_sus:='ERR '||SQLSTATE; END;
  PERFORM set_config('probe.p818', CASE WHEN r_sus='42501' THEN 'OK (invitacion: suspendida 42501)' ELSE 'ROJO (suspendida='||r_sus||')' END, false);

  PERFORM set_config('request.jwt.claims','',true);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true);
  PERFORM set_config('probe.p815','FALLO ('||SQLSTATE||')',false); END $$;
SELECT set_config('role','none', true);

-- ---------------- P819-P821 GRUPO A helpers: activa valor / suspendida NULL-false ----------------
DO $$
DECLARE v_admin uuid; v_emp uuid; claims text; u uuid; b boolean;
  a1 text; s1 text;
BEGIN
  IF coalesce(current_setting('probe.pgr_ready',true),'0')<>'1' THEN
    PERFORM set_config('probe.p819','N/A',false); PERFORM set_config('probe.p820','N/A',false); PERFORM set_config('probe.p821','N/A',false); RETURN; END IF;
  v_admin:=current_setting('probe.pgr_admin',true)::uuid; v_emp:=current_setting('probe.pgr_emp',true)::uuid;
  claims:=json_build_object('sub',v_admin::text,'role','authenticated')::text;

  -- P819 get_empresa_id_proveedor
  UPDATE public.empresas_proveedoras SET estado='activa' WHERE id=v_emp;
  PERFORM set_config('request.jwt.claims',claims,true); PERFORM set_config('role','authenticated',true);
  u:=public.get_empresa_id_proveedor(); PERFORM set_config('role','none',true); a1:=COALESCE(u::text,'NULL');
  UPDATE public.empresas_proveedoras SET estado='suspendida' WHERE id=v_emp;
  PERFORM set_config('request.jwt.claims',claims,true); PERFORM set_config('role','authenticated',true);
  u:=public.get_empresa_id_proveedor(); PERFORM set_config('role','none',true); s1:=COALESCE(u::text,'NULL');
  PERFORM set_config('probe.p819', CASE WHEN a1=v_emp::text AND s1='NULL' THEN 'OK (activa=empresa, suspendida=NULL)' ELSE 'ROJO (activa='||a1||' suspendida='||s1||')' END, false);

  -- P820 puede_aprobar_visitas
  UPDATE public.empresas_proveedoras SET estado='activa' WHERE id=v_emp;
  PERFORM set_config('request.jwt.claims',claims,true); PERFORM set_config('role','authenticated',true);
  b:=private.puede_aprobar_visitas(); PERFORM set_config('role','none',true); a1:=b::text;
  UPDATE public.empresas_proveedoras SET estado='suspendida' WHERE id=v_emp;
  PERFORM set_config('request.jwt.claims',claims,true); PERFORM set_config('role','authenticated',true);
  b:=private.puede_aprobar_visitas(); PERFORM set_config('role','none',true); s1:=b::text;
  PERFORM set_config('probe.p820', CASE WHEN a1='true' AND s1='false' THEN 'OK (activa=true, suspendida=false)' ELSE 'ROJO (activa='||a1||' suspendida='||s1||')' END, false);

  -- P821 puede_auditar_chat (admin -> true activa, false suspendida)
  UPDATE public.empresas_proveedoras SET estado='activa' WHERE id=v_emp;
  PERFORM set_config('request.jwt.claims',claims,true); PERFORM set_config('role','authenticated',true);
  b:=public.puede_auditar_chat(); PERFORM set_config('role','none',true); a1:=b::text;
  UPDATE public.empresas_proveedoras SET estado='suspendida' WHERE id=v_emp;
  PERFORM set_config('request.jwt.claims',claims,true); PERFORM set_config('role','authenticated',true);
  b:=public.puede_auditar_chat(); PERFORM set_config('role','none',true); s1:=b::text;
  PERFORM set_config('probe.p821', CASE WHEN a1='true' AND s1='false' THEN 'OK (activa=true, suspendida=false)' ELSE 'ROJO (activa='||a1||' suspendida='||s1||')' END, false);

  PERFORM set_config('request.jwt.claims','',true);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true);
  PERFORM set_config('probe.p819','FALLO ('||SQLSTATE||')',false); END $$;
SELECT set_config('role','none', true);

-- ---------------- P822 onboarding RECHAZADA / P823 PENDIENTE ----------------
DO $$
DECLARE v_admin uuid; v_emp uuid; v_co uuid; claims text; n int; r_emp text; r_b text; r_eq text; r_upd text;
BEGIN
  IF coalesce(current_setting('probe.pgr_ready',true),'0')<>'1' THEN
    PERFORM set_config('probe.p822','N/A',false); PERFORM set_config('probe.p823','N/A',false); RETURN; END IF;
  v_admin:=current_setting('probe.pgr_admin',true)::uuid; v_emp:=current_setting('probe.pgr_emp',true)::uuid; v_co:=current_setting('probe.pgr_co',true)::uuid;
  claims:=json_build_object('sub',v_admin::text,'role','authenticated')::text;

  -- P822 rechazada: ve su empresa (1) + accion B 42501
  UPDATE public.empresas_proveedoras SET estado='rechazada' WHERE id=v_emp;
  PERFORM set_config('request.jwt.claims',claims,true); PERFORM set_config('role','authenticated',true);
  SELECT count(*) INTO n FROM public.empresas_proveedoras WHERE id=v_emp; PERFORM set_config('role','none',true); r_emp:='ve_empresa='||n;
  BEGIN PERFORM set_config('request.jwt.claims',claims,true); PERFORM set_config('role','authenticated',true);
    PERFORM public.cambiar_estado_miembro_proveedor(v_co,false); PERFORM set_config('role','none',true); r_b:='NO_BLOQUEO';
  EXCEPTION WHEN insufficient_privilege THEN PERFORM set_config('role','none',true); r_b:='42501';
           WHEN OTHERS THEN PERFORM set_config('role','none',true); r_b:='ERR '||SQLSTATE; END;
  PERFORM set_config('probe.p822', CASE WHEN n=1 AND r_b='42501' THEN 'OK (rechazada ve su empresa (1) y accion B 42501)' ELSE 'ROJO ('||r_emp||' B='||r_b||')' END, false);

  -- P823 pendiente: ve empresa+equipo + UPDATE perfil empresa OK
  UPDATE public.empresas_proveedoras SET estado='pendiente' WHERE id=v_emp;
  PERFORM set_config('request.jwt.claims',claims,true); PERFORM set_config('role','authenticated',true);
  SELECT count(*) INTO n FROM public.empresas_proveedoras WHERE id=v_emp; r_emp:='emp='||n;
  SELECT count(*) INTO n FROM public.cuentas_proveedor WHERE empresa_id=v_emp; r_eq:='equipo='||n;
  PERFORM set_config('role','none',true);
  BEGIN PERFORM set_config('request.jwt.claims',claims,true); PERFORM set_config('role','authenticated',true);
    UPDATE public.empresas_proveedoras SET telefono=COALESCE(telefono,'') WHERE id=v_emp; GET DIAGNOSTICS n=ROW_COUNT;
    PERFORM set_config('role','none',true); r_upd:='upd='||n;
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true); r_upd:='upd_ERR '||SQLSTATE; END;
  PERFORM set_config('probe.p823', CASE WHEN r_emp='emp=1' AND r_eq LIKE 'equipo=%' AND r_upd='upd=1' THEN 'OK (pendiente ve empresa+equipo y UPDATE perfil OK; '||r_eq||')' ELSE 'ROJO ('||r_emp||' '||r_eq||' '||r_upd||')' END, false);

  PERFORM set_config('request.jwt.claims','',true);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true);
  PERFORM set_config('probe.p822','FALLO ('||SQLSTATE||')',false); END $$;
SELECT set_config('role','none', true);

-- ---------------- P824 estructural: 17 B con exigir_empresa_activa, 2 exentas sin ----------------
DO $$
DECLARE n_b int; n_ex int;
BEGIN
  SELECT count(*) INTO n_b FROM pg_proc p JOIN pg_namespace ns ON ns.oid=p.pronamespace
   WHERE ns.nspname='public' AND p.proname IN ('contactos_chat','get_visitas_proveedor','sincronizar_mis_canales','notificar_visita_resultado',
     'abrir_canal_administracion','abrir_canal_equipo','abrir_directo','asignar_visitador_equipo','cambiar_auditoria_chat',
     'cambiar_estado_miembro_proveedor','cambiar_rol_proveedor','asignar_rol_miembro','asignar_sucursal_a_miembro',
     'autorizar_invitacion_staff','alta_miembro_farmacia','invitar_miembro_farmacia','invitar_miembro_proveedor')
     AND p.prosrc ILIKE '%exigir_empresa_activa%';
  SELECT count(*) INTO n_ex FROM pg_proc p JOIN pg_namespace ns ON ns.oid=p.pronamespace
   WHERE ns.nspname='public' AND p.proname IN ('aceptar_invitacion_proveedor','vincular_membresia_proveedor')
     AND p.prosrc ILIKE '%exigir_empresa_activa%';
  PERFORM set_config('probe.p824', CASE WHEN n_b=17 AND n_ex=0 THEN 'OK (17 B con guard, 2 exentas sin)' ELSE 'ROJO (B con guard='||n_b||'/17, exentas con guard='||n_ex||')' END, false);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('probe.p824','FALLO ('||SQLSTATE||')',false); END $$;
SELECT set_config('role','none', true);


-- ---------------- P825 — INVARIANTE: cuentas_proveedor por rol (admin ve equipo; no-admin solo su fila) ----------------
-- Contraprueba: policy 2 SIN el filtro de rol (mutacion en savepoint) -> no-admin ve el equipo -> ROJO.
DO $$
DECLARE emp uuid; adm uuid; nonadm uuid; nonrol text; claims text; n_adm int; n_non int; n_bad int := -1;
BEGIN
  SELECT cp.empresa_id INTO emp FROM public.cuentas_proveedor cp JOIN public.empresas_proveedoras e ON e.id=cp.empresa_id
   WHERE cp.activo AND e.estado='activa' AND cp.rol_en_empresa='admin'
     AND EXISTS (SELECT 1 FROM public.cuentas_proveedor c2 WHERE c2.empresa_id=cp.empresa_id AND c2.activo AND c2.rol_en_empresa<>'admin')
   ORDER BY cp.empresa_id LIMIT 1;
  IF emp IS NULL THEN PERFORM set_config('probe.p825','N/A (sin empresa activa con admin y no-admin)',false); RETURN; END IF;
  SELECT id INTO adm FROM public.cuentas_proveedor WHERE empresa_id=emp AND activo AND rol_en_empresa='admin' LIMIT 1;
  SELECT id, rol_en_empresa INTO nonadm, nonrol FROM public.cuentas_proveedor WHERE empresa_id=emp AND activo AND rol_en_empresa<>'admin' LIMIT 1;

  -- admin ve el equipo
  claims:=json_build_object('sub',adm::text,'role','authenticated')::text;
  PERFORM set_config('request.jwt.claims',claims,true); PERFORM set_config('role','authenticated',true);
  SELECT count(*) INTO n_adm FROM public.cuentas_proveedor WHERE empresa_id=emp; PERFORM set_config('role','none',true);

  -- no-admin ve SOLO su fila
  claims:=json_build_object('sub',nonadm::text,'role','authenticated')::text;
  PERFORM set_config('request.jwt.claims',claims,true); PERFORM set_config('role','authenticated',true);
  SELECT count(*) INTO n_non FROM public.cuentas_proveedor WHERE empresa_id=emp; PERFORM set_config('role','none',true);

  -- CONTRAPRUEBA (savepoint que se descarta): policy 2 sin filtro de rol -> no-admin ve el equipo
  BEGIN
    DROP POLICY "Proveedor admin ve cuentas de su empresa" ON public.cuentas_proveedor;
    CREATE POLICY "Proveedor admin ve cuentas de su empresa" ON public.cuentas_proveedor
      FOR SELECT TO authenticated USING (empresa_id = private.mi_empresa_onboarding());
    PERFORM set_config('request.jwt.claims',claims,true); PERFORM set_config('role','authenticated',true);
    SELECT count(*) INTO n_bad FROM public.cuentas_proveedor WHERE empresa_id=emp; PERFORM set_config('role','none',true);
    RAISE EXCEPTION 'SENT825';
  EXCEPTION WHEN raise_exception THEN
    IF SQLERRM <> 'SENT825' THEN RAISE; END IF;
  END;

  PERFORM set_config('request.jwt.claims','',true);
  PERFORM set_config('probe.p825',
    CASE WHEN n_adm > 1 AND n_non = 1 AND n_bad > 1
      THEN 'OK (admin ve '||n_adm||', '||nonrol||' ve 1; contraprueba sin filtro ve '||n_bad||')'
      ELSE 'ROJO (admin='||n_adm||' '||nonrol||'='||n_non||' contraprueba='||n_bad||')' END, false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
  PERFORM set_config('probe.p825','FALLO ('||SQLSTATE||' '||SQLERRM||')',false);
END $$;
SELECT set_config('role','none', true);


-- ================================================================================
-- MIG 326 — PROBES M5 (jerarquia) + M4 (cuenta inactiva). Actores elegidos como postgres.
-- OK = comportamiento arreglado; ROJO = comportamiento viejo (vulnerable). SIN mig dan ROJO.
-- ================================================================================
-- ---------------- P826 M5 vincular_membresia_proveedor (jerarquia) ----------------
-- Negativos: 42501 CON el mensaje de jerarquia y SIN fila creada. Positivos: la fila creada lleva la
-- empresa del caller, el rol pedido y activo=true. Precondiciones como aserciones ('fixture roto').
DO $$
DECLARE
  gerente uuid := 'e2fa65d4-f294-4f72-ab4c-df8d18cefe63';   -- gerente_farmacia nivel 80 (no es_admin)
  adminf  uuid := 'e7935069-fd08-4ac5-a094-9c481313f4d3';   -- admin farmacia (es_admin), misma empresa
  msg_jer CONSTANT text := '%solo puedes conceder roles de nivel inferior al tuyo%';
  cg text; ca text; emp uuid; fx text := ''; n int := 0; u record; fila text;
  e1 text; e2 text; e3 text; e4 text; r1 text; r2 text; r3 text; r4 text;
BEGIN
  cg := json_build_object('sub',gerente::text,'role','authenticated')::text;
  ca := json_build_object('sub',adminf::text,'role','authenticated')::text;

  -- precondiciones (como postgres)
  SELECT cp.empresa_id INTO emp FROM public.cuentas_proveedor cp JOIN public.empresas_proveedoras e ON e.id = cp.empresa_id
   WHERE cp.id = gerente AND cp.rol_en_empresa = 'gerente_farmacia' AND cp.activo AND e.tipo = 'farmacia' AND e.estado = 'activa';
  IF emp IS NULL THEN fx := fx||' gerente'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.cuentas_proveedor WHERE id = adminf AND empresa_id = emp AND rol_en_empresa = 'admin' AND activo) THEN
    fx := fx||' adminf'; END IF;
  -- 4 usuarios auth libres (sin cuenta_proveedor, perfil ni paciente), uno por variable
  FOR u IN SELECT au.email FROM auth.users au WHERE au.email IS NOT NULL AND trim(au.email) <> ''
      AND NOT EXISTS (SELECT 1 FROM public.cuentas_proveedor cp WHERE cp.id = au.id)
      AND NOT EXISTS (SELECT 1 FROM public.perfiles p WHERE p.id = au.id)
      AND NOT EXISTS (SELECT 1 FROM public.pacientes pa WHERE pa.auth_user_id = au.id)
      ORDER BY au.created_at DESC, au.id LIMIT 4 LOOP
    n := n + 1;
    IF n = 1 THEN e1 := u.email; ELSIF n = 2 THEN e2 := u.email; ELSIF n = 3 THEN e3 := u.email; ELSE e4 := u.email; END IF;
  END LOOP;
  -- 4 emails, distintos, y cada uno resuelve a UN usuario (vincular busca por lower(email))
  IF n <> 4 OR (SELECT count(*) FROM auth.users au WHERE lower(au.email) IN (lower(e1),lower(e2),lower(e3),lower(e4))) <> 4 THEN
    fx := fx||' emails(n='||n||')'; END IF;
  IF fx <> '' THEN RAISE EXCEPTION 'fixture roto:%', fx; END IF;

  -- NEGATIVO: gerente (80) concede 'admin' (100) -> 42501 jerarquia, sin fila
  BEGIN PERFORM set_config('request.jwt.claims',cg,true); PERFORM set_config('role','authenticated',true);
    PERFORM public.vincular_membresia_proveedor(e1,'admin','QA',NULL,NULL);
    PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true); r1 := 'PASO(admin creado)';
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
    r1 := CASE WHEN SQLSTATE = '42501' AND SQLERRM ILIKE msg_jer THEN '42501' ELSE 'ERR '||SQLSTATE||' '||SQLERRM END; END;
  IF EXISTS (SELECT 1 FROM public.cuentas_proveedor cp JOIN auth.users au ON au.id = cp.id WHERE lower(au.email) = lower(e1)) THEN
    r1 := r1||' +FILA'; END IF;

  -- NEGATIVO nivel igual: gerente (80) concede 'gerente_farmacia' (80) -> 42501 jerarquia, sin fila
  BEGIN PERFORM set_config('request.jwt.claims',cg,true); PERFORM set_config('role','authenticated',true);
    PERFORM public.vincular_membresia_proveedor(e2,'gerente_farmacia','QA',NULL,NULL);
    PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true); r2 := 'PASO(par creado)';
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
    r2 := CASE WHEN SQLSTATE = '42501' AND SQLERRM ILIKE msg_jer THEN '42501' ELSE 'ERR '||SQLSTATE||' '||SQLERRM END; END;
  IF EXISTS (SELECT 1 FROM public.cuentas_proveedor cp JOIN auth.users au ON au.id = cp.id WHERE lower(au.email) = lower(e2)) THEN
    r2 := r2||' +FILA'; END IF;

  -- POSITIVO: gerente (80) concede 'supervisor' (60) -> fila con empresa del caller, rol pedido, activa
  BEGIN PERFORM set_config('request.jwt.claims',cg,true); PERFORM set_config('role','authenticated',true);
    PERFORM public.vincular_membresia_proveedor(e3,'supervisor','QA',NULL,NULL);
    PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true); r3 := 'OK';
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
    r3 := 'ERR '||SQLSTATE||' '||SQLERRM; END;
  SELECT cp.empresa_id::text||'/'||cp.rol_en_empresa||'/'||cp.activo INTO fila
    FROM public.cuentas_proveedor cp JOIN auth.users au ON au.id = cp.id WHERE lower(au.email) = lower(e3);
  IF r3 = 'OK' AND fila IS DISTINCT FROM emp::text||'/supervisor/true' THEN r3 := 'FILA MAL ('||COALESCE(fila,'sin fila')||')'; END IF;

  -- POSITIVO: admin (es_admin) concede 'admin' -> fila con empresa del caller, rol pedido, activa
  BEGIN PERFORM set_config('request.jwt.claims',ca,true); PERFORM set_config('role','authenticated',true);
    PERFORM public.vincular_membresia_proveedor(e4,'admin','QA',NULL,NULL);
    PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true); r4 := 'OK';
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
    r4 := 'ERR '||SQLSTATE||' '||SQLERRM; END;
  fila := NULL;
  SELECT cp.empresa_id::text||'/'||cp.rol_en_empresa||'/'||cp.activo INTO fila
    FROM public.cuentas_proveedor cp JOIN auth.users au ON au.id = cp.id WHERE lower(au.email) = lower(e4);
  IF r4 = 'OK' AND fila IS DISTINCT FROM emp::text||'/admin/true' THEN r4 := 'FILA MAL ('||COALESCE(fila,'sin fila')||')'; END IF;

  PERFORM set_config('probe.p826', CASE WHEN r1 = '42501' AND r2 = '42501' AND r3 = 'OK' AND r4 = 'OK'
    THEN 'OK (gerente->admin 42501; gerente->gerente_farmacia 42501; gerente->supervisor OK+fila; admin->admin OK+fila)'
    ELSE 'ROJO (gerente->admin='||r1||' gerente->gerente_farmacia='||r2||' gerente->supervisor='||r3||' admin->admin='||r4||')' END, false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
  PERFORM set_config('probe.p826', CASE WHEN SQLERRM LIKE 'fixture roto%' THEN 'ROJO ('||SQLERRM||')'
    ELSE 'FALLO ('||SQLSTATE||' '||SQLERRM||')' END, false);
END $$;
SELECT set_config('role','none', true);

-- ---------------- P827 M5 autorizar_invitacion_staff directo ----------------
-- Negativos: 42501 CON el mensaje de jerarquia. Positivos: el JSON trae la empresa y el tipo del caller.
-- La funcion es de solo lectura: no hay fila destino que verificar.
DO $$
DECLARE
  gerente uuid := 'e2fa65d4-f294-4f72-ab4c-df8d18cefe63';   -- gerente_farmacia nivel 80 (no es_admin)
  adminf  uuid := 'e7935069-fd08-4ac5-a094-9c481313f4d3';   -- admin farmacia (es_admin), misma empresa
  msg_jer CONSTANT text := '%solo puedes conceder roles de nivel inferior al tuyo%';
  cg text; ca text; emp uuid; tipo text; fx text := ''; j jsonb;
  r1 text; r2 text; r3 text; r4 text;
BEGIN
  cg := json_build_object('sub',gerente::text,'role','authenticated')::text;
  ca := json_build_object('sub',adminf::text,'role','authenticated')::text;

  -- precondiciones (como postgres)
  SELECT cp.empresa_id, e.tipo INTO emp, tipo FROM public.cuentas_proveedor cp JOIN public.empresas_proveedoras e ON e.id = cp.empresa_id
   WHERE cp.id = gerente AND cp.rol_en_empresa = 'gerente_farmacia' AND cp.activo AND e.tipo = 'farmacia' AND e.estado = 'activa';
  IF emp IS NULL THEN fx := fx||' gerente'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.cuentas_proveedor WHERE id = adminf AND empresa_id = emp AND rol_en_empresa = 'admin' AND activo) THEN
    fx := fx||' adminf'; END IF;
  IF fx <> '' THEN RAISE EXCEPTION 'fixture roto:%', fx; END IF;

  -- NEGATIVO: gerente (80) -> 'admin' (100)
  BEGIN PERFORM set_config('request.jwt.claims',cg,true); PERFORM set_config('role','authenticated',true);
    PERFORM public.autorizar_invitacion_staff('admin');
    PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true); r1 := 'PASO';
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
    r1 := CASE WHEN SQLSTATE = '42501' AND SQLERRM ILIKE msg_jer THEN '42501' ELSE 'ERR '||SQLSTATE||' '||SQLERRM END; END;

  -- NEGATIVO nivel igual: gerente (80) -> 'gerente_farmacia' (80)
  BEGIN PERFORM set_config('request.jwt.claims',cg,true); PERFORM set_config('role','authenticated',true);
    PERFORM public.autorizar_invitacion_staff('gerente_farmacia');
    PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true); r2 := 'PASO';
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
    r2 := CASE WHEN SQLSTATE = '42501' AND SQLERRM ILIKE msg_jer THEN '42501' ELSE 'ERR '||SQLSTATE||' '||SQLERRM END; END;

  -- POSITIVO: gerente (80) -> 'supervisor' (60): JSON con empresa y tipo del caller
  j := NULL;
  BEGIN PERFORM set_config('request.jwt.claims',cg,true); PERFORM set_config('role','authenticated',true);
    j := public.autorizar_invitacion_staff('supervisor');
    PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true); r3 := 'OK';
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
    r3 := 'ERR '||SQLSTATE||' '||SQLERRM; END;
  IF r3 = 'OK' AND ((j->>'empresa_id') IS DISTINCT FROM emp::text OR (j->>'tipo') IS DISTINCT FROM tipo) THEN
    r3 := 'JSON MAL ('||COALESCE(j::text,'NULL')||')'; END IF;

  -- POSITIVO: admin (es_admin) -> 'admin': JSON con empresa y tipo del caller
  j := NULL;
  BEGIN PERFORM set_config('request.jwt.claims',ca,true); PERFORM set_config('role','authenticated',true);
    j := public.autorizar_invitacion_staff('admin');
    PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true); r4 := 'OK';
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
    r4 := 'ERR '||SQLSTATE||' '||SQLERRM; END;
  IF r4 = 'OK' AND ((j->>'empresa_id') IS DISTINCT FROM emp::text OR (j->>'tipo') IS DISTINCT FROM tipo) THEN
    r4 := 'JSON MAL ('||COALESCE(j::text,'NULL')||')'; END IF;

  PERFORM set_config('probe.p827', CASE WHEN r1 = '42501' AND r2 = '42501' AND r3 = 'OK' AND r4 = 'OK'
    THEN 'OK (gerente->admin 42501; gerente->gerente_farmacia 42501; gerente->supervisor OK+json; admin->admin OK+json)'
    ELSE 'ROJO (gerente->admin='||r1||' gerente->gerente_farmacia='||r2||' gerente->supervisor='||r3||' admin->admin='||r4||')' END, false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
  PERFORM set_config('probe.p827', CASE WHEN SQLERRM LIKE 'fixture roto%' THEN 'ROJO ('||SQLERRM||')'
    ELSE 'FALLO ('||SQLSTATE||' '||SQLERRM||')' END, false);
END $$;
SELECT set_config('role','none', true);

-- ---------------- P828 M4 cuenta inactiva ----------------
-- Negativos: 42501 CON el mensaje de la causa y la fila destino (activo, rol, audita_chat, equipo_id)
-- intacta. Positivos: las 4 RPCs con el caller activo, verificando el efecto. cambiar_rol_proveedor usa
-- 'lectura': la empresa es laboratorio_farmaceutico (sin filas en roles_empresa_catalogo) y la RPC valida
-- contra su lista fija. Cada UPDATE de preparacion exige ROW_COUNT = 1.
DO $$
DECLARE
  adm    uuid := '9ca0b977-3c91-48dc-aa04-2f1fab766963';   -- admin de emp
  co     uuid := 'd50e7efd-d0c6-4f14-a47b-f6b4845b25e9';   -- miembro destino de emp
  emp    uuid := '411d6f8c-a405-49d6-9ed6-fbeb0db05133';   -- laboratorio_farmaceutico
  equipo uuid := '7f29111c-6b7f-4772-8eb6-0d736048c9e8';   -- equipo de emp
  pac    uuid := '5bfb5b4c-dc91-4714-93cb-a292faa6717d';   -- paciente, sin cuenta_proveedor
  msg_inact CONSTANT text := '%Cuenta proveedora inactiva%';
  msg_susp  CONSTANT text := '%Empresa proveedora no activa%';
  msg_pac   CONSTANT text := '%Solo un administrador%';
  c_adm text; c_pac text; fx text := ''; rc int; snap text; s text; tipo_orig text;
  co_activo boolean; co_rol text; co_aud boolean; co_eq uuid; snap_ini text; r_rest text := 'OK';
  r_est text; r_aud text; r_rol text; r_vis text; r_comb text; r_susp text;
  p_est text; p_aud text; p_rol text; p_vis text; r_pac text;
BEGIN
  c_adm := json_build_object('sub',adm::text,'role','authenticated')::text;
  c_pac := json_build_object('sub',pac::text,'role','authenticated')::text;

  -- tipo NO data-driven: cambiar_rol_proveedor rechaza farmacia/empresa_afin. Dentro del harness el
  -- fixture FX12 convierte a esta empresa en 'farmacia' (para P65/P66): se fija aca y se restaura al final.
  SELECT tipo INTO tipo_orig FROM public.empresas_proveedoras WHERE id = emp;
  IF tipo_orig IN ('farmacia','empresa_afin') THEN
    UPDATE public.empresas_proveedoras SET tipo = 'laboratorio_farmaceutico' WHERE id = emp;
    GET DIAGNOSTICS rc = ROW_COUNT; IF rc <> 1 THEN RAISE EXCEPTION 'fixture roto: fijar tipo emp rc=%', rc; END IF;
  END IF;

  -- precondiciones (como postgres)
  IF NOT EXISTS (SELECT 1 FROM public.cuentas_proveedor WHERE id = adm AND empresa_id = emp AND rol_en_empresa = 'admin' AND activo) THEN
    fx := fx||' adm'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.cuentas_proveedor WHERE id = co AND empresa_id = emp AND activo AND NOT audita_chat
      AND rol_en_empresa NOT IN ('admin','lectura') AND equipo_id IS DISTINCT FROM equipo) THEN fx := fx||' co'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.empresas_proveedoras WHERE id = emp AND estado = 'activa' AND tipo NOT IN ('farmacia','empresa_afin')) THEN
    fx := fx||' emp'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.equipos_visitadores WHERE id = equipo AND empresa_id = emp) THEN fx := fx||' equipo'; END IF;
  IF EXISTS (SELECT 1 FROM public.cuentas_proveedor WHERE id = pac) OR NOT EXISTS (SELECT 1 FROM public.pacientes WHERE auth_user_id = pac) THEN
    fx := fx||' pac'; END IF;
  IF fx <> '' THEN RAISE EXCEPTION 'fixture roto:%', fx; END IF;
  -- valores originales de co (como postgres), para restaurarlos al final
  SELECT activo, rol_en_empresa, audita_chat, equipo_id, row(activo, rol_en_empresa, audita_chat, equipo_id)::text
    INTO co_activo, co_rol, co_aud, co_eq, snap_ini FROM public.cuentas_proveedor WHERE id = co;
  snap := snap_ini;

  -- ===== admin INACTIVO, empresa activa: las 4 RPCs -> 42501 cuenta inactiva, sin efecto =====
  UPDATE public.cuentas_proveedor SET activo = false WHERE id = adm;
  GET DIAGNOSTICS rc = ROW_COUNT; IF rc <> 1 THEN RAISE EXCEPTION 'fixture roto: desactivar adm rc=%', rc; END IF;

  BEGIN PERFORM set_config('request.jwt.claims',c_adm,true); PERFORM set_config('role','authenticated',true);
    PERFORM public.cambiar_estado_miembro_proveedor(co,false);
    PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true); r_est := 'PASO';
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
    r_est := CASE WHEN SQLSTATE = '42501' AND SQLERRM ILIKE msg_inact THEN '42501' ELSE 'ERR '||SQLSTATE||' '||SQLERRM END; END;
  SELECT row(activo, rol_en_empresa, audita_chat, equipo_id)::text INTO s FROM public.cuentas_proveedor WHERE id = co;
  IF s IS DISTINCT FROM snap THEN r_est := r_est||' +EFECTO'; snap := s; END IF;

  BEGIN PERFORM set_config('request.jwt.claims',c_adm,true); PERFORM set_config('role','authenticated',true);
    PERFORM public.cambiar_auditoria_chat(co,true);
    PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true); r_aud := 'PASO';
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
    r_aud := CASE WHEN SQLSTATE = '42501' AND SQLERRM ILIKE msg_inact THEN '42501' ELSE 'ERR '||SQLSTATE||' '||SQLERRM END; END;
  SELECT row(activo, rol_en_empresa, audita_chat, equipo_id)::text INTO s FROM public.cuentas_proveedor WHERE id = co;
  IF s IS DISTINCT FROM snap THEN r_aud := r_aud||' +EFECTO'; snap := s; END IF;

  BEGIN PERFORM set_config('request.jwt.claims',c_adm,true); PERFORM set_config('role','authenticated',true);
    PERFORM public.cambiar_rol_proveedor(co,'admin');
    PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true); r_rol := 'PASO';
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
    r_rol := CASE WHEN SQLSTATE = '42501' AND SQLERRM ILIKE msg_inact THEN '42501' ELSE 'ERR '||SQLSTATE||' '||SQLERRM END; END;
  SELECT row(activo, rol_en_empresa, audita_chat, equipo_id)::text INTO s FROM public.cuentas_proveedor WHERE id = co;
  IF s IS DISTINCT FROM snap THEN r_rol := r_rol||' +EFECTO'; snap := s; END IF;

  BEGIN PERFORM set_config('request.jwt.claims',c_adm,true); PERFORM set_config('role','authenticated',true);
    PERFORM public.asignar_visitador_equipo(co,equipo);
    PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true); r_vis := 'PASO';
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
    r_vis := CASE WHEN SQLSTATE = '42501' AND SQLERRM ILIKE msg_inact THEN '42501' ELSE 'ERR '||SQLSTATE||' '||SQLERRM END; END;
  SELECT row(activo, rol_en_empresa, audita_chat, equipo_id)::text INTO s FROM public.cuentas_proveedor WHERE id = co;
  IF s IS DISTINCT FROM snap THEN r_vis := r_vis||' +EFECTO'; snap := s; END IF;

  -- ===== combinado: admin INACTIVO + empresa SUSPENDIDA -> prevalece 'Cuenta proveedora inactiva' =====
  UPDATE public.empresas_proveedoras SET estado = 'suspendida' WHERE id = emp;
  GET DIAGNOSTICS rc = ROW_COUNT; IF rc <> 1 THEN RAISE EXCEPTION 'fixture roto: suspender emp rc=%', rc; END IF;
  BEGIN PERFORM set_config('request.jwt.claims',c_adm,true); PERFORM set_config('role','authenticated',true);
    PERFORM public.cambiar_estado_miembro_proveedor(co,false);
    PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true); r_comb := 'PASO';
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
    r_comb := CASE WHEN SQLSTATE = '42501' AND SQLERRM ILIKE msg_inact THEN '42501' ELSE 'ERR '||SQLSTATE||' '||SQLERRM END; END;
  SELECT row(activo, rol_en_empresa, audita_chat, equipo_id)::text INTO s FROM public.cuentas_proveedor WHERE id = co;
  IF s IS DISTINCT FROM snap THEN r_comb := r_comb||' +EFECTO'; snap := s; END IF;

  -- ===== no-regresion 323: admin ACTIVO + empresa SUSPENDIDA -> 42501 empresa no activa =====
  UPDATE public.cuentas_proveedor SET activo = true WHERE id = adm;
  GET DIAGNOSTICS rc = ROW_COUNT; IF rc <> 1 THEN RAISE EXCEPTION 'fixture roto: reactivar adm rc=%', rc; END IF;
  BEGIN PERFORM set_config('request.jwt.claims',c_adm,true); PERFORM set_config('role','authenticated',true);
    PERFORM public.cambiar_estado_miembro_proveedor(co,false);
    PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true); r_susp := 'PASO';
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
    r_susp := CASE WHEN SQLSTATE = '42501' AND SQLERRM ILIKE msg_susp THEN '42501' ELSE 'ERR '||SQLSTATE||' '||SQLERRM END; END;
  SELECT row(activo, rol_en_empresa, audita_chat, equipo_id)::text INTO s FROM public.cuentas_proveedor WHERE id = co;
  IF s IS DISTINCT FROM snap THEN r_susp := r_susp||' +EFECTO'; snap := s; END IF;
  UPDATE public.empresas_proveedoras SET estado = 'activa' WHERE id = emp;
  GET DIAGNOSTICS rc = ROW_COUNT; IF rc <> 1 THEN RAISE EXCEPTION 'fixture roto: reactivar emp rc=%', rc; END IF;

  -- ===== controles positivos: admin ACTIVO, empresa activa, las 4 RPCs con su efecto =====
  BEGIN PERFORM set_config('request.jwt.claims',c_adm,true); PERFORM set_config('role','authenticated',true);
    PERFORM public.cambiar_estado_miembro_proveedor(co,false);
    PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true); p_est := 'PASA';
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
    p_est := 'ERR '||SQLSTATE||' '||SQLERRM; END;
  IF p_est = 'PASA' AND NOT EXISTS (SELECT 1 FROM public.cuentas_proveedor WHERE id = co AND activo = false) THEN p_est := 'PASA SIN EFECTO'; END IF;

  BEGIN PERFORM set_config('request.jwt.claims',c_adm,true); PERFORM set_config('role','authenticated',true);
    PERFORM public.cambiar_auditoria_chat(co,true);
    PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true); p_aud := 'PASA';
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
    p_aud := 'ERR '||SQLSTATE||' '||SQLERRM; END;
  IF p_aud = 'PASA' AND NOT EXISTS (SELECT 1 FROM public.cuentas_proveedor WHERE id = co AND audita_chat) THEN p_aud := 'PASA SIN EFECTO'; END IF;

  BEGIN PERFORM set_config('request.jwt.claims',c_adm,true); PERFORM set_config('role','authenticated',true);
    PERFORM public.cambiar_rol_proveedor(co,'lectura');
    PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true); p_rol := 'PASA';
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
    p_rol := 'ERR '||SQLSTATE||' '||SQLERRM; END;
  IF p_rol = 'PASA' AND NOT EXISTS (SELECT 1 FROM public.cuentas_proveedor WHERE id = co AND rol_en_empresa = 'lectura') THEN p_rol := 'PASA SIN EFECTO'; END IF;

  BEGIN PERFORM set_config('request.jwt.claims',c_adm,true); PERFORM set_config('role','authenticated',true);
    PERFORM public.asignar_visitador_equipo(co,equipo);
    PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true); p_vis := 'PASA';
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
    p_vis := 'ERR '||SQLSTATE||' '||SQLERRM; END;
  IF p_vis = 'PASA' AND NOT EXISTS (SELECT 1 FROM public.cuentas_proveedor WHERE id = co AND equipo_id = equipo) THEN p_vis := 'PASA SIN EFECTO'; END IF;

  -- ===== no-proveedor (paciente): el gate nuevo no lo frena; lo frena la RPC (P0001 'Solo un administrador') =====
  SELECT row(activo, rol_en_empresa, audita_chat, equipo_id)::text INTO snap FROM public.cuentas_proveedor WHERE id = co;
  BEGIN PERFORM set_config('request.jwt.claims',c_pac,true); PERFORM set_config('role','authenticated',true);
    PERFORM public.cambiar_estado_miembro_proveedor(co,true);
    PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true); r_pac := 'PASO';
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
    r_pac := CASE WHEN SQLSTATE = 'P0001' AND SQLERRM ILIKE msg_pac THEN 'P0001' ELSE 'ERR '||SQLSTATE||' '||SQLERRM END; END;
  SELECT row(activo, rol_en_empresa, audita_chat, equipo_id)::text INTO s FROM public.cuentas_proveedor WHERE id = co;
  IF s IS DISTINCT FROM snap THEN r_pac := r_pac||' +EFECTO'; END IF;

  -- restaurar la fila de co a sus valores previos al probe, y verificar contra el snapshot inicial
  UPDATE public.cuentas_proveedor SET activo = co_activo, rol_en_empresa = co_rol, audita_chat = co_aud, equipo_id = co_eq
   WHERE id = co;
  GET DIAGNOSTICS rc = ROW_COUNT; IF rc <> 1 THEN RAISE EXCEPTION 'fixture roto: restaurar co rc=%', rc; END IF;
  SELECT row(activo, rol_en_empresa, audita_chat, equipo_id)::text INTO s FROM public.cuentas_proveedor WHERE id = co;
  IF s IS DISTINCT FROM snap_ini THEN r_rest := 'co no restaurada ('||COALESCE(s,'NULL')||' <> '||snap_ini||')'; END IF;

  -- restaurar el tipo que traia la empresa (no altera a los probes que corran despues)
  IF tipo_orig IN ('farmacia','empresa_afin') THEN
    UPDATE public.empresas_proveedoras SET tipo = tipo_orig WHERE id = emp;
    GET DIAGNOSTICS rc = ROW_COUNT; IF rc <> 1 THEN RAISE EXCEPTION 'fixture roto: restaurar tipo emp rc=%', rc; END IF;
  END IF;

  PERFORM set_config('probe.p828', CASE WHEN r_est = '42501' AND r_aud = '42501' AND r_rol = '42501' AND r_vis = '42501'
      AND r_comb = '42501' AND r_susp = '42501'
      AND p_est = 'PASA' AND p_aud = 'PASA' AND p_rol = 'PASA' AND p_vis = 'PASA' AND r_pac = 'P0001' AND r_rest = 'OK'
    THEN 'OK (inactivo: estado/aud/rol/visitador 42501 sin efecto; inactivo+suspendida 42501 cuenta; suspendida 42501 empresa; activo: 4 RPCs PASA con efecto; paciente P0001; co restaurada)'
    ELSE 'ROJO (est='||r_est||' aud='||r_aud||' rol='||r_rol||' vis='||r_vis||' comb='||r_comb||' susp='||r_susp
      ||' | ctrl est='||p_est||' aud='||p_aud||' rol='||p_rol||' vis='||p_vis||' | pac='||r_pac||' | restaurar='||r_rest||')' END, false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
  PERFORM set_config('probe.p828', CASE WHEN SQLERRM LIKE 'fixture roto%' THEN 'ROJO ('||SQLERRM||')'
    ELSE 'FALLO ('||SQLSTATE||' '||SQLERRM||')' END, false);
END $$;
SELECT set_config('role','none', true);

-- ================================================================================
-- MIG 327 — registrar_proveedor: identidad unica + email de auth + pais operativo + sin anon.
-- OK = comportamiento de la 327; con 327_rollback aplicado dan ROJO. Fixtures elegidos como postgres.
-- Cada probe publica el veredicto en probe.pNNN y el detalle por caso en probe.pNNN_det
-- (caso|esperado|obtenido|sqlstate|mensaje, separados por ' ;; ').
-- Todo lo que un probe crea o modifica se restaura al snapshot inicial y la restauracion se verifica
-- (conteos de empresas_proveedoras / cuentas_proveedor, email de auth.users).
-- ================================================================================
-- ---------------- P829 alta legitima: usuario sin identidad + pais GT ----------------
DO $$
DECLARE
  l1 uuid; l1_email text; gt uuid; claims text; fx text := ''; ret uuid; det text := ''; rc int;
  n_emp_ini bigint; n_cp_ini bigint; n_emp0 bigint; n_cp0 bigint; n_emp1 bigint; n_cp1 bigint;
  fila text; r1 text; r2 text; r_rest text := 'OK';
  ajeno CONSTANT text := 'p829.ajeno@evil.test';
  msg_id CONSTANT text := '%ya tiene una identidad en la plataforma%';
BEGIN
  -- precondiciones (como postgres)
  SELECT id INTO gt FROM public.configuracion_pais WHERE codigo = 'GT' AND activo IS TRUE;
  IF gt IS NULL THEN fx := fx||' pais GT'; END IF;
  SELECT au.id, au.email INTO l1, l1_email FROM auth.users au
   WHERE NULLIF(trim(au.email),'') IS NOT NULL AND lower(au.email) <> ajeno
     AND NOT EXISTS (SELECT 1 FROM public.perfiles x WHERE x.id = au.id)
     AND NOT EXISTS (SELECT 1 FROM public.pacientes x WHERE x.auth_user_id = au.id)
     AND NOT EXISTS (SELECT 1 FROM public.medicos x WHERE x.id = au.id)
     AND NOT EXISTS (SELECT 1 FROM public.cuentas_proveedor x WHERE x.id = au.id)
     AND NOT EXISTS (SELECT 1 FROM public.asesores_perfil x WHERE x.id = au.id)
     AND NOT EXISTS (SELECT 1 FROM public.usuario_roles x WHERE x.usuario_id = au.id)
   ORDER BY au.created_at DESC, au.id LIMIT 1;
  IF l1 IS NULL THEN fx := fx||' usuario libre'; END IF;
  IF fx <> '' THEN RAISE EXCEPTION 'fixture roto:%', fx; END IF;
  claims := json_build_object('sub',l1::text,'role','authenticated')::text;
  SELECT count(*) INTO n_emp_ini FROM public.empresas_proveedoras; SELECT count(*) INTO n_cp_ini FROM public.cuentas_proveedor;
  n_emp0 := n_emp_ini; n_cp0 := n_cp_ini;

  -- POSITIVO: alta con p_email AJENO -> la cuenta queda con el email de auth
  BEGIN PERFORM set_config('request.jwt.claims',claims,true); PERFORM set_config('role','authenticated',true);
    ret := public.registrar_proveedor('P829 QA','farmacia',NULL,gt,NULL,NULL,'p829@qa.test',NULL,'P829 QA',ajeno);
    PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true); r1 := 'OK';
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
    r1 := 'ERR '||SQLSTATE||' '||SQLERRM; END;
  IF r1 = 'OK' THEN
    SELECT e.estado||'/'||COALESCE(e.pais_id::text,'NULL')||'/'||cp.rol_en_empresa||'/'||cp.activo||'/'||lower(cp.email) INTO fila
      FROM public.cuentas_proveedor cp JOIN public.empresas_proveedoras e ON e.id = cp.empresa_id
     WHERE cp.id = l1 AND cp.empresa_id = ret;
    IF fila IS DISTINCT FROM 'pendiente/'||gt::text||'/admin/true/'||lower(l1_email) THEN
      r1 := 'FILA MAL ('||COALESCE(fila,'sin fila')||'; esperado email '||lower(l1_email)||')'; END IF;
    SELECT count(*) INTO n_emp1 FROM public.empresas_proveedoras; SELECT count(*) INTO n_cp1 FROM public.cuentas_proveedor;
    IF n_emp1 <> n_emp0 + 1 OR n_cp1 <> n_cp0 + 1 THEN r1 := r1||' (conteos '||n_emp0||'->'||n_emp1||' / '||n_cp0||'->'||n_cp1||')'; END IF;
  END IF;
  det := det||'alta usuario libre + GT, p_email ajeno|OK, email de auth|'||r1||'|'||CASE WHEN r1 = 'OK' THEN '00000' ELSE '-' END||'|'||COALESCE(fila,'');

  -- NEGATIVO: el mismo usuario repite el alta -> ya es proveedor -> 42501, sin filas nuevas
  SELECT count(*) INTO n_emp0 FROM public.empresas_proveedoras; SELECT count(*) INTO n_cp0 FROM public.cuentas_proveedor;
  BEGIN PERFORM set_config('request.jwt.claims',claims,true); PERFORM set_config('role','authenticated',true);
    PERFORM public.registrar_proveedor('P829 QA bis','farmacia',NULL,gt,NULL,NULL,'p829@qa.test',NULL,'P829 QA',ajeno);
    PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true); r2 := 'PASO|00000|';
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
    r2 := CASE WHEN SQLSTATE = '42501' AND SQLERRM ILIKE msg_id THEN '42501' ELSE 'ERR' END||'|'||SQLSTATE||'|'||SQLERRM; END;
  SELECT count(*) INTO n_emp1 FROM public.empresas_proveedoras; SELECT count(*) INTO n_cp1 FROM public.cuentas_proveedor;
  IF n_emp1 <> n_emp0 OR n_cp1 <> n_cp0 THEN r2 := r2||' +FILAS'; END IF;
  det := det||' ;; segundo alta del mismo usuario|42501 identidad|'||r2;

  -- RESTAURACION: borrar la cuenta y la empresa del alta positiva y volver a los conteos iniciales
  IF ret IS NOT NULL THEN
    DELETE FROM public.cuentas_proveedor WHERE id = l1 AND empresa_id = ret;
    GET DIAGNOSTICS rc = ROW_COUNT; IF rc <> 1 THEN RAISE EXCEPTION 'fixture roto: borrar cuenta P829 rc=%', rc; END IF;
    DELETE FROM public.empresas_proveedoras WHERE id = ret;
    GET DIAGNOSTICS rc = ROW_COUNT; IF rc <> 1 THEN RAISE EXCEPTION 'fixture roto: borrar empresa P829 rc=%', rc; END IF;
  END IF;
  SELECT count(*) INTO n_emp1 FROM public.empresas_proveedoras; SELECT count(*) INTO n_cp1 FROM public.cuentas_proveedor;
  IF n_emp1 <> n_emp_ini OR n_cp1 <> n_cp_ini THEN
    r_rest := 'conteos no vuelven ('||n_emp_ini||'->'||n_emp1||' / '||n_cp_ini||'->'||n_cp1||')'; END IF;
  det := det||' ;; restauracion (conteos al snapshot)|emp='||n_emp_ini||' cp='||n_cp_ini||'|'||r_rest||'|-|emp='||n_emp1||' cp='||n_cp1;

  PERFORM set_config('probe.p829_det', det, false);
  PERFORM set_config('probe.p829', CASE WHEN r1 = 'OK' AND split_part(r2,'|',1) = '42501' AND r2 NOT LIKE '%+FILAS%' AND r_rest = 'OK'
    THEN 'OK (alta: empresa pendiente GT + cuenta admin activa con email de auth; segundo alta 42501 sin filas; restaurado)'
    ELSE 'ROJO (alta='||r1||' | segundo='||r2||' | restauracion='||r_rest||')' END, false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
  PERFORM set_config('probe.p829', CASE WHEN SQLERRM LIKE 'fixture roto%' THEN 'ROJO ('||SQLERRM||')'
    ELSE 'FALLO ('||SQLSTATE||' '||SQLERRM||')' END, false);
END $$;
SELECT set_config('role','none', true);

-- ---------------- P830 exclusion total: cualquier identidad previa -> 42501, sin filas ----------------
-- Casos reales: paciente, medico, staff, super_admin, proveedor, asesor. medicos, asesores_perfil y
-- usuario_roles tienen FK de su uid a perfiles(id): son subconjunto de perfiles POR ESQUEMA, y un
-- "medico sin perfil" no se puede construir. La probe ASERTA esas 3 FK: si alguien quita una, la rama
-- propia de esa tabla pasa a ser alcanzable sola y esta probe da ROJO hasta que se le agregue su caso.
DO $$
DECLARE
  gt uuid; fx text := ''; det text := ''; bad text := ''; c record; fk_falta text; rc int; v_emp uuid;
  res text; n_emp_ini bigint; n_cp_ini bigint; n_emp0 bigint; n_cp0 bigint; n_emp1 bigint; n_cp1 bigint;
  tiene_cp0 boolean; r_rest text := 'OK';
  msg_id CONSTANT text := '%ya tiene una identidad en la plataforma%';
BEGIN
  SELECT id INTO gt FROM public.configuracion_pais WHERE codigo = 'GT' AND activo IS TRUE;
  IF gt IS NULL THEN RAISE EXCEPTION 'fixture roto: pais GT'; END IF;
  SELECT count(*) INTO n_emp_ini FROM public.empresas_proveedoras; SELECT count(*) INTO n_cp_ini FROM public.cuentas_proveedor;

  -- invariante de esquema que hace redundantes las ramas medicos/asesores_perfil/usuario_roles
  SELECT string_agg(x.t, ', ') INTO fk_falta FROM (VALUES ('medicos','id'),('asesores_perfil','id'),('usuario_roles','usuario_id')) x(t, col)
   WHERE NOT EXISTS (SELECT 1 FROM pg_constraint k
      WHERE k.contype = 'f' AND k.conrelid = ('public.'||x.t)::regclass AND k.confrelid = 'public.perfiles'::regclass
        AND k.conkey = ARRAY[(SELECT a.attnum FROM pg_attribute a WHERE a.attrelid = ('public.'||x.t)::regclass AND a.attname = x.col)]);
  det := 'FK uid->perfiles en medicos, asesores_perfil, usuario_roles|las 3 presentes|'||COALESCE('faltan: '||fk_falta,'presentes')||'|-|';
  IF fk_falta IS NOT NULL THEN bad := bad||'FK a perfiles ausente en '||fk_falta||' (agregar caso sintetico); '; END IF;

  FOR c IN
    SELECT * FROM (VALUES
      ('paciente',    (SELECT pa.auth_user_id FROM public.pacientes pa WHERE pa.auth_user_id IS NOT NULL
                         AND NOT EXISTS (SELECT 1 FROM public.perfiles x WHERE x.id = pa.auth_user_id)
                         AND NOT EXISTS (SELECT 1 FROM public.cuentas_proveedor x WHERE x.id = pa.auth_user_id)
                       ORDER BY pa.auth_user_id LIMIT 1)),
      ('medico',      (SELECT m.id FROM public.medicos m ORDER BY m.id LIMIT 1)),
      ('perfil staff',(SELECT p.id FROM public.perfiles p WHERE p.rol NOT IN ('medico','super_admin')
                         AND NOT EXISTS (SELECT 1 FROM public.medicos x WHERE x.id = p.id)
                         AND NOT EXISTS (SELECT 1 FROM public.asesores_perfil x WHERE x.id = p.id) ORDER BY p.id LIMIT 1)),
      ('super_admin', (SELECT p.id FROM public.perfiles p WHERE p.rol = 'super_admin' ORDER BY p.id LIMIT 1)),
      ('proveedor',   (SELECT cp.id FROM public.cuentas_proveedor cp
                        WHERE NOT EXISTS (SELECT 1 FROM public.pacientes x WHERE x.auth_user_id = cp.id) ORDER BY cp.id LIMIT 1)),
      ('asesor',      (SELECT a.id FROM public.asesores_perfil a ORDER BY a.id LIMIT 1))
    ) v(caso, uid)
  LOOP
    IF c.uid IS NULL THEN RAISE EXCEPTION 'fixture roto: sin uid para %', c.caso; END IF;
    SELECT EXISTS (SELECT 1 FROM public.cuentas_proveedor WHERE id = c.uid) INTO tiene_cp0;
    SELECT count(*) INTO n_emp0 FROM public.empresas_proveedoras; SELECT count(*) INTO n_cp0 FROM public.cuentas_proveedor;
    BEGIN
      PERFORM set_config('request.jwt.claims', json_build_object('sub',c.uid::text,'role','authenticated')::text, true);
      PERFORM set_config('role','authenticated',true);
      PERFORM public.registrar_proveedor('P830 QA','farmacia',NULL,gt,NULL,NULL,'p830@qa.test',NULL,'P830 QA','p830@qa.test');
      PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
      res := 'PASO|00000|';
    EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
      res := CASE WHEN SQLSTATE = '42501' AND SQLERRM ILIKE msg_id THEN '42501' ELSE 'ERR' END||'|'||SQLSTATE||'|'||SQLERRM;
    END;
    SELECT count(*) INTO n_emp1 FROM public.empresas_proveedoras; SELECT count(*) INTO n_cp1 FROM public.cuentas_proveedor;
    IF n_emp1 <> n_emp0 OR n_cp1 <> n_cp0
       OR (NOT tiene_cp0 AND EXISTS (SELECT 1 FROM public.cuentas_proveedor WHERE id = c.uid)) THEN res := res||' +FILAS'; END IF;
    -- restauracion: si el alta paso (sin la 327), borrar su cuenta y su empresa
    IF NOT tiene_cp0 THEN
      v_emp := NULL;
      SELECT empresa_id INTO v_emp FROM public.cuentas_proveedor WHERE id = c.uid;
      IF v_emp IS NOT NULL THEN
        DELETE FROM public.cuentas_proveedor WHERE id = c.uid;
        GET DIAGNOSTICS rc = ROW_COUNT; IF rc <> 1 THEN RAISE EXCEPTION 'fixture roto: borrar cuenta P830 % rc=%', c.caso, rc; END IF;
        DELETE FROM public.empresas_proveedoras WHERE id = v_emp;
        GET DIAGNOSTICS rc = ROW_COUNT; IF rc <> 1 THEN RAISE EXCEPTION 'fixture roto: borrar empresa P830 % rc=%', c.caso, rc; END IF;
      END IF;
    END IF;
    det := det||' ;; '||c.caso||'|42501 identidad|'||res;
    IF split_part(res,'|',1) <> '42501' OR res LIKE '%+FILAS%' THEN bad := bad||c.caso||'='||res||'; '; END IF;
  END LOOP;

  SELECT count(*) INTO n_emp1 FROM public.empresas_proveedoras; SELECT count(*) INTO n_cp1 FROM public.cuentas_proveedor;
  IF n_emp1 <> n_emp_ini OR n_cp1 <> n_cp_ini THEN
    r_rest := 'conteos no vuelven ('||n_emp_ini||'->'||n_emp1||' / '||n_cp_ini||'->'||n_cp1||')'; END IF;
  det := det||' ;; restauracion (conteos al snapshot)|emp='||n_emp_ini||' cp='||n_cp_ini||'|'||r_rest||'|-|emp='||n_emp1||' cp='||n_cp1;

  PERFORM set_config('probe.p830_det', det, false);
  PERFORM set_config('probe.p830', CASE WHEN bad = '' AND r_rest = 'OK'
    THEN 'OK (6 identidades reales -> 42501 con mensaje, sin filas: paciente, medico, staff, super_admin, proveedor, asesor; FK a perfiles presentes; restaurado)'
    ELSE 'ROJO ('||left(bad,800)||' | restauracion='||r_rest||')' END, false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
  PERFORM set_config('probe.p830', CASE WHEN SQLERRM LIKE 'fixture roto%' THEN 'ROJO ('||SQLERRM||')'
    ELSE 'FALLO ('||SQLSTATE||' '||SQLERRM||')' END, false);
END $$;
SELECT set_config('role','none', true);

-- ---------------- P831 pais operativo: NULL, DEMO 'ZZ', inexistente -> 22023, sin filas ----------------
DO $$
DECLARE
  l2 uuid; zz uuid; inexistente uuid := gen_random_uuid(); claims text; fx text := ''; det text := ''; bad text := '';
  c record; res text; rc int; v_emp uuid; r_rest text := 'OK';
  n_emp_ini bigint; n_cp_ini bigint; n_emp0 bigint; n_cp0 bigint; n_emp1 bigint; n_cp1 bigint;
  msg_pais CONSTANT text := '%País no válido para el registro%';
BEGIN
  SELECT id INTO zz FROM public.configuracion_pais WHERE codigo = 'ZZ';
  IF zz IS NULL THEN fx := fx||' pais ZZ'; END IF;
  IF EXISTS (SELECT 1 FROM public.configuracion_pais WHERE id = inexistente) THEN fx := fx||' uuid inexistente existe'; END IF;
  SELECT au.id INTO l2 FROM auth.users au
   WHERE NULLIF(trim(au.email),'') IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM public.perfiles x WHERE x.id = au.id)
     AND NOT EXISTS (SELECT 1 FROM public.pacientes x WHERE x.auth_user_id = au.id)
     AND NOT EXISTS (SELECT 1 FROM public.medicos x WHERE x.id = au.id)
     AND NOT EXISTS (SELECT 1 FROM public.cuentas_proveedor x WHERE x.id = au.id)
     AND NOT EXISTS (SELECT 1 FROM public.asesores_perfil x WHERE x.id = au.id)
     AND NOT EXISTS (SELECT 1 FROM public.usuario_roles x WHERE x.usuario_id = au.id)
   ORDER BY au.created_at DESC, au.id LIMIT 1;
  IF l2 IS NULL THEN fx := fx||' usuario libre'; END IF;
  IF fx <> '' THEN RAISE EXCEPTION 'fixture roto:%', fx; END IF;
  claims := json_build_object('sub',l2::text,'role','authenticated')::text;
  SELECT count(*) INTO n_emp_ini FROM public.empresas_proveedoras; SELECT count(*) INTO n_cp_ini FROM public.cuentas_proveedor;

  FOR c IN SELECT * FROM (VALUES ('pais NULL', NULL::uuid), ('pais DEMO ZZ', zz), ('pais inexistente', inexistente)) v(caso, pid) LOOP
    SELECT count(*) INTO n_emp0 FROM public.empresas_proveedoras; SELECT count(*) INTO n_cp0 FROM public.cuentas_proveedor;
    BEGIN PERFORM set_config('request.jwt.claims',claims,true); PERFORM set_config('role','authenticated',true);
      PERFORM public.registrar_proveedor('P831 QA','farmacia',NULL,c.pid,NULL,NULL,'p831@qa.test',NULL,'P831 QA','p831@qa.test');
      PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true); res := 'PASO|00000|';
    EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
      res := CASE WHEN SQLSTATE = '22023' AND SQLERRM ILIKE msg_pais THEN '22023' ELSE 'ERR' END||'|'||SQLSTATE||'|'||SQLERRM; END;
    SELECT count(*) INTO n_emp1 FROM public.empresas_proveedoras; SELECT count(*) INTO n_cp1 FROM public.cuentas_proveedor;
    IF n_emp1 <> n_emp0 OR n_cp1 <> n_cp0 THEN res := res||' +FILAS'; END IF;
    det := det||CASE WHEN det = '' THEN '' ELSE ' ;; ' END||c.caso||'|22023 pais|'||res;
    IF split_part(res,'|',1) <> '22023' OR res LIKE '%+FILAS%' THEN bad := bad||c.caso||'='||res||'; '; END IF;
    -- restauracion: si el alta paso (sin la 327), borrar su cuenta Y su empresa antes del caso siguiente
    v_emp := NULL;
    SELECT empresa_id INTO v_emp FROM public.cuentas_proveedor WHERE id = l2;
    IF v_emp IS NOT NULL THEN
      DELETE FROM public.cuentas_proveedor WHERE id = l2;
      GET DIAGNOSTICS rc = ROW_COUNT; IF rc <> 1 THEN RAISE EXCEPTION 'fixture roto: borrar cuenta P831 % rc=%', c.caso, rc; END IF;
      DELETE FROM public.empresas_proveedoras WHERE id = v_emp;
      GET DIAGNOSTICS rc = ROW_COUNT; IF rc <> 1 THEN RAISE EXCEPTION 'fixture roto: borrar empresa P831 % rc=%', c.caso, rc; END IF;
    END IF;
  END LOOP;

  SELECT count(*) INTO n_emp1 FROM public.empresas_proveedoras; SELECT count(*) INTO n_cp1 FROM public.cuentas_proveedor;
  IF n_emp1 <> n_emp_ini OR n_cp1 <> n_cp_ini THEN
    r_rest := 'conteos no vuelven ('||n_emp_ini||'->'||n_emp1||' / '||n_cp_ini||'->'||n_cp1||')'; END IF;
  det := det||' ;; restauracion (conteos al snapshot)|emp='||n_emp_ini||' cp='||n_cp_ini||'|'||r_rest||'|-|emp='||n_emp1||' cp='||n_cp1;

  PERFORM set_config('probe.p831_det', det, false);
  PERFORM set_config('probe.p831', CASE WHEN bad = '' AND r_rest = 'OK'
    THEN 'OK (pais NULL / ZZ / inexistente -> 22023 con mensaje, sin filas; restaurado)'
    ELSE 'ROJO ('||left(bad,800)||' | restauracion='||r_rest||')' END, false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
  PERFORM set_config('probe.p831', CASE WHEN SQLERRM LIKE 'fixture roto%' THEN 'ROJO ('||SQLERRM||')'
    ELSE 'FALLO ('||SQLSTATE||' '||SQLERRM||')' END, false);
END $$;
SELECT set_config('role','none', true);

-- ---------------- P832 sesion y email: sin sub -> P0001; auth.users.email NULL -> 22023 ----------------
DO $$
DECLARE
  l3 uuid; l3_email text; gt uuid; fx text := ''; det text := ''; rc int; r1 text; r2 text; v_emp uuid;
  r_rest text := 'OK'; email_fin text;
  n_emp_ini bigint; n_cp_ini bigint; n_emp0 bigint; n_cp0 bigint; n_emp1 bigint; n_cp1 bigint;
BEGIN
  SELECT id INTO gt FROM public.configuracion_pais WHERE codigo = 'GT' AND activo IS TRUE;
  IF gt IS NULL THEN fx := fx||' pais GT'; END IF;
  SELECT au.id, au.email INTO l3, l3_email FROM auth.users au
   WHERE NULLIF(trim(au.email),'') IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM public.perfiles x WHERE x.id = au.id)
     AND NOT EXISTS (SELECT 1 FROM public.pacientes x WHERE x.auth_user_id = au.id)
     AND NOT EXISTS (SELECT 1 FROM public.medicos x WHERE x.id = au.id)
     AND NOT EXISTS (SELECT 1 FROM public.cuentas_proveedor x WHERE x.id = au.id)
     AND NOT EXISTS (SELECT 1 FROM public.asesores_perfil x WHERE x.id = au.id)
     AND NOT EXISTS (SELECT 1 FROM public.usuario_roles x WHERE x.usuario_id = au.id)
   ORDER BY au.created_at DESC, au.id LIMIT 1;
  IF l3 IS NULL THEN fx := fx||' usuario libre'; END IF;
  IF fx <> '' THEN RAISE EXCEPTION 'fixture roto:%', fx; END IF;
  SELECT count(*) INTO n_emp_ini FROM public.empresas_proveedoras; SELECT count(*) INTO n_cp_ini FROM public.cuentas_proveedor;

  -- authenticated SIN sub -> auth.uid() NULL -> 'Usuario no autenticado' (P0001), sin filas
  n_emp0 := n_emp_ini; n_cp0 := n_cp_ini;
  BEGIN PERFORM set_config('request.jwt.claims','{"role":"authenticated"}',true); PERFORM set_config('role','authenticated',true);
    PERFORM public.registrar_proveedor('P832 QA','farmacia',NULL,gt,NULL,NULL,'p832@qa.test',NULL,'P832 QA','p832@qa.test');
    PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true); r1 := 'PASO|00000|';
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
    r1 := CASE WHEN SQLSTATE = 'P0001' AND SQLERRM ILIKE '%Usuario no autenticado%' THEN 'P0001' ELSE 'ERR' END||'|'||SQLSTATE||'|'||SQLERRM; END;
  SELECT count(*) INTO n_emp1 FROM public.empresas_proveedoras; SELECT count(*) INTO n_cp1 FROM public.cuentas_proveedor;
  IF n_emp1 <> n_emp0 OR n_cp1 <> n_cp0 THEN r1 := r1||' +FILAS'; END IF;
  det := 'sin sub (auth.uid NULL)|P0001 no autenticado|'||r1;

  -- usuario libre con email NULL en auth.users -> 22023, sin filas (el p_email NO lo rescata)
  UPDATE auth.users SET email = NULL WHERE id = l3;
  GET DIAGNOSTICS rc = ROW_COUNT; IF rc <> 1 THEN RAISE EXCEPTION 'fixture roto: email NULL rc=%', rc; END IF;
  SELECT count(*) INTO n_emp0 FROM public.empresas_proveedoras; SELECT count(*) INTO n_cp0 FROM public.cuentas_proveedor;
  BEGIN PERFORM set_config('request.jwt.claims', json_build_object('sub',l3::text,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated',true);
    PERFORM public.registrar_proveedor('P832 QA','farmacia',NULL,gt,NULL,NULL,'p832@qa.test',NULL,'P832 QA','p832.rescate@evil.test');
    PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true); r2 := 'PASO|00000|';
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
    r2 := CASE WHEN SQLSTATE = '22023' AND SQLERRM ILIKE '%no tiene email%' THEN '22023' ELSE 'ERR' END||'|'||SQLSTATE||'|'||SQLERRM; END;
  SELECT count(*) INTO n_emp1 FROM public.empresas_proveedoras; SELECT count(*) INTO n_cp1 FROM public.cuentas_proveedor;
  IF n_emp1 <> n_emp0 OR n_cp1 <> n_cp0 THEN r2 := r2||' +FILAS'; END IF;
  det := det||' ;; auth.users.email NULL, p_email de rescate|22023 sin email|'||r2;

  -- RESTAURACION: si el alta paso (sin la 327), borrar cuenta y empresa; devolver el email original a l3
  SELECT empresa_id INTO v_emp FROM public.cuentas_proveedor WHERE id = l3;
  IF v_emp IS NOT NULL THEN
    DELETE FROM public.cuentas_proveedor WHERE id = l3;
    GET DIAGNOSTICS rc = ROW_COUNT; IF rc <> 1 THEN RAISE EXCEPTION 'fixture roto: borrar cuenta P832 rc=%', rc; END IF;
    DELETE FROM public.empresas_proveedoras WHERE id = v_emp;
    GET DIAGNOSTICS rc = ROW_COUNT; IF rc <> 1 THEN RAISE EXCEPTION 'fixture roto: borrar empresa P832 rc=%', rc; END IF;
  END IF;
  UPDATE auth.users SET email = l3_email WHERE id = l3;
  GET DIAGNOSTICS rc = ROW_COUNT; IF rc <> 1 THEN RAISE EXCEPTION 'fixture roto: restaurar email rc=%', rc; END IF;
  SELECT email INTO email_fin FROM auth.users WHERE id = l3;
  IF email_fin IS DISTINCT FROM l3_email THEN r_rest := 'email de l3 no vuelve ('||COALESCE(email_fin,'NULL')||')'; END IF;
  SELECT count(*) INTO n_emp1 FROM public.empresas_proveedoras; SELECT count(*) INTO n_cp1 FROM public.cuentas_proveedor;
  IF n_emp1 <> n_emp_ini OR n_cp1 <> n_cp_ini THEN
    r_rest := r_rest||' / conteos no vuelven ('||n_emp_ini||'->'||n_emp1||' / '||n_cp_ini||'->'||n_cp1||')'; END IF;
  det := det||' ;; restauracion (email de l3 + conteos al snapshot)|email original, emp='||n_emp_ini||' cp='||n_cp_ini||'|'||r_rest
        ||'|-|email '||CASE WHEN email_fin IS NOT DISTINCT FROM l3_email THEN 'igual al original' ELSE 'DISTINTO' END||', emp='||n_emp1||' cp='||n_cp1;

  PERFORM set_config('probe.p832_det', det, false);
  PERFORM set_config('probe.p832', CASE WHEN split_part(r1,'|',1) = 'P0001' AND r1 NOT LIKE '%+FILAS%'
      AND split_part(r2,'|',1) = '22023' AND r2 NOT LIKE '%+FILAS%' AND r_rest = 'OK'
    THEN 'OK (sin sub P0001; email de auth NULL 22023; sin filas; email y conteos restaurados)'
    ELSE 'ROJO (sin_sub='||r1||' | email_null='||r2||' | restauracion='||r_rest||')' END, false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
  PERFORM set_config('probe.p832', CASE WHEN SQLERRM LIKE 'fixture roto%' THEN 'ROJO ('||SQLERRM||')'
    ELSE 'FALLO ('||SQLSTATE||' '||SQLERRM||')' END, false);
END $$;
SELECT set_config('role','none', true);

-- ---------------- P833 anon y PUBLIC sin EXECUTE (catalogo + ejercitado) ----------------
DO $$
DECLARE
  f CONSTANT regprocedure := 'public.registrar_proveedor(text,text,text,uuid,text,text,text,text,text,text)'::regprocedure;
  gt uuid; det text := ''; r_anon text; h_anon boolean; h_pub boolean; h_auth boolean; h_srv boolean;
  n_emp0 bigint; n_cp0 bigint; n_emp1 bigint; n_cp1 bigint;
BEGIN
  SELECT id INTO gt FROM public.configuracion_pais WHERE codigo = 'GT' AND activo IS TRUE;
  h_anon := has_function_privilege('anon', f, 'EXECUTE');
  h_pub  := EXISTS (SELECT 1 FROM pg_proc p, aclexplode(p.proacl) a WHERE p.oid = f AND a.grantee = 0);
  h_auth := has_function_privilege('authenticated', f, 'EXECUTE');
  h_srv  := has_function_privilege('service_role', f, 'EXECUTE');
  det := 'catalogo|anon=f public=f authenticated=t service_role=t|anon='||h_anon||' public='||h_pub||' authenticated='||h_auth||' service_role='||h_srv||'|-|';

  SELECT count(*) INTO n_emp0 FROM public.empresas_proveedoras; SELECT count(*) INTO n_cp0 FROM public.cuentas_proveedor;
  BEGIN PERFORM set_config('request.jwt.claims','{"role":"anon"}',true); PERFORM set_config('role','anon',true);
    PERFORM public.registrar_proveedor('P833 QA','farmacia',NULL,gt,NULL,NULL,'p833@qa.test',NULL,'P833 QA','p833@qa.test');
    PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true); r_anon := 'PASO|00000|';
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
    r_anon := CASE WHEN SQLSTATE = '42501' AND SQLERRM ILIKE '%permission denied for function registrar_proveedor%' THEN '42501' ELSE 'ERR' END
              ||'|'||SQLSTATE||'|'||SQLERRM; END;
  SELECT count(*) INTO n_emp1 FROM public.empresas_proveedoras; SELECT count(*) INTO n_cp1 FROM public.cuentas_proveedor;
  IF n_emp1 <> n_emp0 OR n_cp1 <> n_cp0 THEN r_anon := r_anon||' +FILAS'; END IF;
  det := det||' ;; anon llama registrar_proveedor|42501 permission denied|'||r_anon;

  PERFORM set_config('probe.p833_det', det, false);
  PERFORM set_config('probe.p833', CASE WHEN NOT h_anon AND NOT h_pub AND h_auth AND h_srv
      AND split_part(r_anon,'|',1) = '42501' AND r_anon NOT LIKE '%+FILAS%'
    THEN 'OK (anon y PUBLIC sin EXECUTE; authenticated y service_role con EXECUTE; anon ejercitado 42501)'
    ELSE 'ROJO (anon='||h_anon||' public='||h_pub||' authenticated='||h_auth||' service_role='||h_srv||' | anon llama='||r_anon||')' END, false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
  PERFORM set_config('probe.p833','FALLO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;
SELECT set_config('role','none', true);

-- ================================================================================
-- MIG 328 — la emision de recetas pasa SOLO por emitir_receta (P834-P839).
-- OK = comportamiento de la 328; con 328_rollback aplicado dan ROJO P834, P835, P837, P838 y P839.
-- P836 es el control POSITIVO (emitir_receta + notificar_receta + fijar_modalidad_grupo siguen
-- funcionando) y queda OK con o sin la 328. Fixtures elegidos como postgres, fuera de la
-- impersonacion. Detalle por caso en probe.pNNN_det (caso|esperado|obtenido|sqlstate|mensaje,
-- separados por ' ;; '). Todo lo que un probe crea o modifica se restaura y se verifica.
-- ================================================================================
-- ---------------- P834 medico: INSERT directo en recetas -> 42501, sin filas ----------------
DO $$
DECLARE
  m uuid; p bigint; rid bigint; res text; rc int; det text; r_rest text := 'OK';
  n_rec0 bigint; n_his0 bigint; n_rec1 bigint; n_his1 bigint;
BEGIN
  SELECT pa.medico_id, pa.id INTO m, p FROM public.pacientes pa JOIN public.perfiles pf ON pf.id = pa.medico_id
   WHERE pf.rol = 'medico' AND pf.activo IS TRUE ORDER BY pa.medico_id, pa.id LIMIT 1;
  IF m IS NULL THEN RAISE EXCEPTION 'fixture roto: medico con paciente propio'; END IF;
  SELECT count(*) INTO n_rec0 FROM public.recetas; SELECT count(*) INTO n_his0 FROM public.historial_medico;

  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',m::text,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated',true);
    INSERT INTO public.recetas (paciente_id, medico_id, estado) VALUES (p, m, 'activa') RETURNING id INTO rid;
    PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
    res := 'PASO|00000|receta '||rid;
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
    res := CASE WHEN SQLSTATE = '42501' AND SQLERRM ILIKE 'permission denied for table recetas' THEN '42501' ELSE 'ERR' END||'|'||SQLSTATE||'|'||SQLERRM;
  END;
  SELECT count(*) INTO n_rec1 FROM public.recetas; SELECT count(*) INTO n_his1 FROM public.historial_medico;
  IF n_rec1 <> n_rec0 OR n_his1 <> n_his0 THEN res := res||' +FILAS'; END IF;
  det := 'medico INSERT directo en recetas (paciente propio '||p||')|42501 permission denied for table recetas|'||res;

  -- restauracion: si paso (sin la 328), borrar la receta y el historial que dispara su trigger
  IF rid IS NOT NULL THEN
    DELETE FROM public.historial_medico WHERE referencia_id = rid::text AND tipo_evento = 'receta';
    DELETE FROM public.recetas WHERE id = rid; GET DIAGNOSTICS rc = ROW_COUNT;
    IF rc <> 1 THEN RAISE EXCEPTION 'fixture roto: borrar receta P834 rc=%', rc; END IF;
  END IF;
  SELECT count(*) INTO n_rec1 FROM public.recetas; SELECT count(*) INTO n_his1 FROM public.historial_medico;
  IF n_rec1 <> n_rec0 OR n_his1 <> n_his0 THEN
    r_rest := 'conteos no vuelven (recetas '||n_rec0||'->'||n_rec1||' / historial '||n_his0||'->'||n_his1||')'; END IF;
  det := det||' ;; restauracion|recetas='||n_rec0||' historial='||n_his0||'|'||r_rest||'|-|recetas='||n_rec1||' historial='||n_his1;

  PERFORM set_config('probe.p834_det', det, false);
  PERFORM set_config('probe.p834', CASE WHEN split_part(res,'|',1) = '42501' AND res NOT LIKE '%+FILAS%' AND r_rest = 'OK'
    THEN 'OK (medico con paciente propio: INSERT directo en recetas -> 42501 permission denied, sin filas)'
    ELSE 'ROJO (insert='||res||' | restauracion='||r_rest||')' END, false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
  PERFORM set_config('probe.p834', CASE WHEN SQLERRM LIKE 'fixture roto%' THEN 'ROJO ('||SQLERRM||')'
    ELSE 'FALLO ('||SQLSTATE||' '||SQLERRM||')' END, false);
END $$;
SELECT set_config('role','none', true);

-- ---------------- P835 medico: INSERT directo en receta_items de una receta PROPIA -> 42501 ----------------
DO $$
DECLARE
  m uuid; rid bigint; iid bigint; res text; rc int; det text; r_rest text := 'OK'; n0 bigint; n1 bigint;
BEGIN
  SELECT r.medico_id, r.id INTO m, rid FROM public.recetas r JOIN public.perfiles pf ON pf.id = r.medico_id
   WHERE pf.rol = 'medico' AND pf.activo IS TRUE ORDER BY r.medico_id, r.id LIMIT 1;
  IF rid IS NULL THEN RAISE EXCEPTION 'fixture roto: receta propia de un medico'; END IF;
  SELECT count(*) INTO n0 FROM public.receta_items;

  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',m::text,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated',true);
    INSERT INTO public.receta_items (receta_id, nombre_medicamento, dosis, frecuencia, cantidad)
    VALUES (rid, 'P835 QA', '1', 'c/8h', 1) RETURNING id INTO iid;
    PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
    res := 'PASO|00000|item '||iid;
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
    res := CASE WHEN SQLSTATE = '42501' AND SQLERRM ILIKE 'permission denied for table receta_items' THEN '42501' ELSE 'ERR' END||'|'||SQLSTATE||'|'||SQLERRM;
  END;
  SELECT count(*) INTO n1 FROM public.receta_items;
  IF n1 <> n0 THEN res := res||' +FILAS'; END IF;
  det := 'medico INSERT en receta_items de su receta '||rid||'|42501 permission denied for table receta_items|'||res;

  IF iid IS NOT NULL THEN
    DELETE FROM public.receta_items WHERE id = iid; GET DIAGNOSTICS rc = ROW_COUNT;
    IF rc <> 1 THEN RAISE EXCEPTION 'fixture roto: borrar item P835 rc=%', rc; END IF;
  END IF;
  SELECT count(*) INTO n1 FROM public.receta_items;
  IF n1 <> n0 THEN r_rest := 'conteo no vuelve ('||n0||'->'||n1||')'; END IF;
  det := det||' ;; restauracion|receta_items='||n0||'|'||r_rest||'|-|receta_items='||n1;

  PERFORM set_config('probe.p835_det', det, false);
  PERFORM set_config('probe.p835', CASE WHEN split_part(res,'|',1) = '42501' AND res NOT LIKE '%+FILAS%' AND r_rest = 'OK'
    THEN 'OK (medico: INSERT en receta_items de una receta propia -> 42501 permission denied, sin filas)'
    ELSE 'ROJO (insert='||res||' | restauracion='||r_rest||')' END, false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
  PERFORM set_config('probe.p835', CASE WHEN SQLERRM LIKE 'fixture roto%' THEN 'ROJO ('||SQLERRM||')'
    ELSE 'FALLO ('||SQLSTATE||' '||SQLERRM||')' END, false);
END $$;
SELECT set_config('role','none', true);

-- ---------------- P836 POSITIVO: emitir_receta + lectura propia + notificar_receta + fijar_modalidad_grupo ----------------
-- Medico que ATIENDE al paciente (cita): es el gate de emitir_receta (PR009) y de notificar_receta (PT002).
DO $$
DECLARE
  c record; m uuid; p bigint; med bigint; farm integer; claims text; j jsonb; rid bigint; det text := ''; rc int;
  r_emit text; r_fila text; r_sel text; r_not text; r_mod text; r_rest text := 'OK'; v_n bigint;
  n_rec0 bigint; n_it0 bigint; n_av0 bigint; n_his0 bigint; n_np0 bigint;
  n_rec1 bigint; n_it1 bigint; n_av1 bigint; n_his1 bigint; n_np1 bigint;
  corr_existia boolean; corr_num bigint; corr_upd timestamptz; corr_fin text;
BEGIN
  -- fixture: par (medico, paciente) con cita, verificado BAJO los claims del medico
  FOR c IN SELECT DISTINCT ci.medico_id, ci.paciente_id FROM public.citas ci
             JOIN public.perfiles pf ON pf.id = ci.medico_id
            WHERE pf.rol = 'medico' AND pf.activo IS TRUE AND ci.paciente_id IS NOT NULL
            ORDER BY 1, 2 LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub',c.medico_id::text,'role','authenticated')::text, true);
    IF COALESCE(private.medico_atiende_paciente(c.paciente_id), false) AND COALESCE(private.tiene_rol(ARRAY['medico']), false) THEN
      m := c.medico_id; p := c.paciente_id; EXIT; END IF;
  END LOOP;
  PERFORM set_config('request.jwt.claims','',true);
  SELECT md.id INTO med FROM public.medicamentos md LEFT JOIN public.medicamentos_categorias mc ON mc.codigo = md.categoria_regulatoria
   WHERE md.activo IS TRUE AND NOT COALESCE(mc.requiere_acuse, false) ORDER BY md.id LIMIT 1;
  SELECT f.id INTO farm FROM public.farmacias f ORDER BY f.id LIMIT 1;
  IF m IS NULL OR med IS NULL OR farm IS NULL THEN
    RAISE EXCEPTION 'fixture roto: medico-atiende-paciente=% medicamento=% farmacia=%', m, med, farm; END IF;
  claims := json_build_object('sub',m::text,'role','authenticated')::text;

  SELECT count(*) INTO n_rec0 FROM public.recetas;           SELECT count(*) INTO n_it0 FROM public.receta_items;
  SELECT count(*) INTO n_av0 FROM public.recetas_avanzadas;  SELECT count(*) INTO n_his0 FROM public.historial_medico;
  SELECT count(*) INTO n_np0 FROM public.notificaciones_pacientes;
  SELECT true, ultimo_numero, updated_at INTO corr_existia, corr_num, corr_upd FROM public.medico_correlativos WHERE medico_id = m;
  corr_existia := COALESCE(corr_existia, false);

  -- (1) emitir por la RPC
  BEGIN
    PERFORM set_config('request.jwt.claims', claims, true); PERFORM set_config('role','authenticated',true);
    j := public.emitir_receta(p, 'P836 QA', jsonb_build_array(jsonb_build_object(
           'medicamento_id', med, 'nombre_medicamento', 'P836 QA', 'dosis', '1', 'frecuencia', 'c/8h',
           'cantidad', 1, 'farmacia_id', farm)));
    PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
    rid := (j->>'receta_id')::bigint; r_emit := 'OK';
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
    r_emit := 'ERR '||SQLSTATE||' '||SQLERRM; END;
  det := 'emitir_receta como medico que atiende|OK|'||r_emit||'|'||CASE WHEN r_emit = 'OK' THEN '00000' ELSE '-' END||'|'||COALESCE(j::text,'');

  IF rid IS NOT NULL THEN
    -- (2) la fila: correlativo, recetas_avanzadas con emitida_at, 1 item
    SELECT 'correlativo='||COALESCE(r.numero_correlativo::text,'NULL')
         ||' avanzada_emitida='||EXISTS (SELECT 1 FROM public.recetas_avanzadas a WHERE a.receta_base_id = r.id AND a.emitida_at IS NOT NULL)
         ||' items='||(SELECT count(*) FROM public.receta_items i WHERE i.receta_id = r.id)
      INTO r_fila FROM public.recetas r WHERE r.id = rid;
    det := det||' ;; fila emitida|correlativo=' ||(j->>'numero_correlativo')||' avanzada_emitida=true items=1|'||COALESCE(r_fila,'SIN FILA')||'|-|';

    -- (3) el medico LEE sus items (policy receta_items_medico_select)
    BEGIN
      PERFORM set_config('request.jwt.claims', claims, true); PERFORM set_config('role','authenticated',true);
      SELECT count(*) INTO v_n FROM public.receta_items WHERE receta_id = rid;
      PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
      r_sel := 've '||v_n;
    EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
      r_sel := 'ERR '||SQLSTATE||' '||SQLERRM; END;
    det := det||' ;; medico SELECT items de su receta|ve 1|'||r_sel||'|-|';

    -- (4) notificar_receta (escritor legitimo: UPDATE recetas.notificado)
    BEGIN
      PERFORM set_config('request.jwt.claims', claims, true); PERFORM set_config('role','authenticated',true);
      PERFORM public.notificar_receta(rid);
      PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
      SELECT CASE WHEN notificado THEN 'OK notificado=true' ELSE 'notificado=false' END INTO r_not FROM public.recetas WHERE id = rid;
    EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
      r_not := 'ERR '||SQLSTATE||' '||SQLERRM; END;
    det := det||' ;; notificar_receta|OK notificado=true|'||r_not||'|-|';

    -- (5) fijar_modalidad_grupo (escritor legitimo: UPDATE receta_items.modalidad)
    BEGIN
      PERFORM set_config('request.jwt.claims', claims, true); PERFORM set_config('role','authenticated',true);
      j := public.fijar_modalidad_grupo(rid, farm, 'delivery');
      PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
      SELECT 'items='||(j->>'items')||' modalidad='||string_agg(DISTINCT COALESCE(i.modalidad,'NULL'), ',') INTO r_mod
        FROM public.receta_items i WHERE i.receta_id = rid;
    EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
      r_mod := 'ERR '||SQLSTATE||' '||SQLERRM; END;
    det := det||' ;; fijar_modalidad_grupo delivery|items=1 modalidad=delivery|'||r_mod||'|-|';

    -- RESTAURACION: todo lo que creo la emision + la notificacion, y el correlativo del medico
    DELETE FROM public.notificaciones_pacientes WHERE paciente_id = p AND tipo = 'receta' AND created_at = now();
    DELETE FROM public.historial_medico WHERE referencia_id = rid::text AND tipo_evento = 'receta';
    DELETE FROM public.recetas_avanzadas WHERE receta_base_id = rid; GET DIAGNOSTICS rc = ROW_COUNT;
    IF rc <> 1 THEN RAISE EXCEPTION 'fixture roto: borrar recetas_avanzadas P836 rc=%', rc; END IF;
    DELETE FROM public.receta_items WHERE receta_id = rid; GET DIAGNOSTICS rc = ROW_COUNT;
    IF rc <> 1 THEN RAISE EXCEPTION 'fixture roto: borrar items P836 rc=%', rc; END IF;
    DELETE FROM public.recetas WHERE id = rid; GET DIAGNOSTICS rc = ROW_COUNT;
    IF rc <> 1 THEN RAISE EXCEPTION 'fixture roto: borrar receta P836 rc=%', rc; END IF;
  END IF;
  IF corr_existia THEN
    UPDATE public.medico_correlativos SET ultimo_numero = corr_num, updated_at = corr_upd WHERE medico_id = m;
  ELSE
    DELETE FROM public.medico_correlativos WHERE medico_id = m;
  END IF;
  SELECT count(*) INTO n_rec1 FROM public.recetas;           SELECT count(*) INTO n_it1 FROM public.receta_items;
  SELECT count(*) INTO n_av1 FROM public.recetas_avanzadas;  SELECT count(*) INTO n_his1 FROM public.historial_medico;
  SELECT count(*) INTO n_np1 FROM public.notificaciones_pacientes;
  SELECT COALESCE((SELECT ultimo_numero::text||'@'||updated_at::text FROM public.medico_correlativos WHERE medico_id = m), 'sin fila') INTO corr_fin;
  IF (n_rec1, n_it1, n_av1, n_his1, n_np1) IS DISTINCT FROM (n_rec0, n_it0, n_av0, n_his0, n_np0)
     OR corr_fin IS DISTINCT FROM (CASE WHEN corr_existia THEN corr_num::text||'@'||corr_upd::text ELSE 'sin fila' END) THEN
    r_rest := 'no vuelve: rec '||n_rec0||'->'||n_rec1||' it '||n_it0||'->'||n_it1||' av '||n_av0||'->'||n_av1
            ||' his '||n_his0||'->'||n_his1||' np '||n_np0||'->'||n_np1||' correlativo '||corr_fin; END IF;
  det := det||' ;; restauracion (5 conteos + correlativo)|rec='||n_rec0||' it='||n_it0||' av='||n_av0||' his='||n_his0||' np='||n_np0
        ||'|'||r_rest||'|-|rec='||n_rec1||' it='||n_it1||' av='||n_av1||' his='||n_his1||' np='||n_np1;

  PERFORM set_config('probe.p836_det', det, false);
  PERFORM set_config('probe.p836', CASE
    WHEN r_emit = 'OK' AND r_fila NOT LIKE 'correlativo=NULL%' AND r_fila LIKE '%avanzada_emitida=true items=1'
     AND r_sel = 've 1' AND r_not = 'OK notificado=true' AND r_mod = 'items=1 modalidad=delivery' AND r_rest = 'OK'
    THEN 'OK (emitir_receta con correlativo + recetas_avanzadas.emitida_at + item; el medico lee su item; notificar_receta y fijar_modalidad_grupo funcionan; restaurado)'
    ELSE 'ROJO (emitir='||r_emit||' | fila='||COALESCE(r_fila,'-')||' | select='||COALESCE(r_sel,'-')||' | notificar='||COALESCE(r_not,'-')
         ||' | modalidad='||COALESCE(r_mod,'-')||' | restauracion='||r_rest||')' END, false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
  PERFORM set_config('probe.p836', CASE WHEN SQLERRM LIKE 'fixture roto%' THEN 'ROJO ('||SQLERRM||')'
    ELSE 'FALLO ('||SQLSTATE||' '||SQLERRM||')' END, false);
END $$;
SELECT set_config('role','none', true);

-- ---------------- P837 medico: UPDATE / DELETE directo de un item de su receta -> 0 filas ----------------
-- Antes de la 328, receta_items_medico_all (ALL) le dejaba cambiar o borrar items ya emitidos.
-- El item objetivo lo siembra el probe como postgres (no se toca ningun item real).
DO $$
DECLARE
  m uuid; rid bigint; iid bigint; det text; rc int; r_upd text; r_del text; r_rest text := 'OK'; v_n int;
  n0 bigint; n1 bigint; cant_fin int;
BEGIN
  SELECT r.medico_id, r.id INTO m, rid FROM public.recetas r JOIN public.perfiles pf ON pf.id = r.medico_id
   WHERE pf.rol = 'medico' AND pf.activo IS TRUE ORDER BY r.medico_id, r.id LIMIT 1;
  IF rid IS NULL THEN RAISE EXCEPTION 'fixture roto: receta propia de un medico'; END IF;
  SELECT count(*) INTO n0 FROM public.receta_items;
  INSERT INTO public.receta_items (receta_id, nombre_medicamento, dosis, frecuencia, cantidad)
  VALUES (rid, 'P837 QA', '1', 'c/8h', 1) RETURNING id INTO iid;

  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',m::text,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated',true);
    UPDATE public.receta_items SET cantidad = 99 WHERE id = iid; GET DIAGNOSTICS v_n = ROW_COUNT;
    PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
    r_upd := v_n||' filas|00000|';
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
    r_upd := 'ERR|'||SQLSTATE||'|'||SQLERRM; END;
  SELECT cantidad INTO cant_fin FROM public.receta_items WHERE id = iid;
  det := 'medico UPDATE cantidad de un item de su receta '||rid||'|0 filas|'||r_upd||'cantidad='||COALESCE(cant_fin::text,'NULL');

  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',m::text,'role','authenticated')::text, true);
    PERFORM set_config('role','authenticated',true);
    DELETE FROM public.receta_items WHERE id = iid; GET DIAGNOSTICS v_n = ROW_COUNT;
    PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
    r_del := v_n||' filas|00000|';
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
    r_del := 'ERR|'||SQLSTATE||'|'||SQLERRM; END;
  det := det||' ;; medico DELETE de ese item|0 filas|'||r_del||'sigue='||EXISTS (SELECT 1 FROM public.receta_items WHERE id = iid);

  DELETE FROM public.receta_items WHERE id = iid;
  SELECT count(*) INTO n1 FROM public.receta_items;
  IF n1 <> n0 THEN r_rest := 'conteo no vuelve ('||n0||'->'||n1||')'; END IF;
  det := det||' ;; restauracion (item sembrado borrado)|receta_items='||n0||'|'||r_rest||'|-|receta_items='||n1;

  PERFORM set_config('probe.p837_det', det, false);
  PERFORM set_config('probe.p837', CASE WHEN r_upd LIKE '0 filas|%' AND cant_fin = 1 AND r_del LIKE '0 filas|%' AND r_rest = 'OK'
    THEN 'OK (el medico ya no cambia ni borra items de su receta: UPDATE y DELETE 0 filas)'
    ELSE 'ROJO (update='||r_upd||' cantidad='||COALESCE(cant_fin::text,'NULL')||' | delete='||r_del||' | restauracion='||r_rest||')' END, false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
  PERFORM set_config('probe.p837', CASE WHEN SQLERRM LIKE 'fixture roto%' THEN 'ROJO ('||SQLERRM||')'
    ELSE 'FALLO ('||SQLSTATE||' '||SQLERRM||')' END, false);
END $$;
SELECT set_config('role','none', true);

-- ---------------- P838 super_admin conserva SELECT/UPDATE/DELETE sin INSERT; service_role intacto ----------------
DO $$
DECLARE
  sa uuid; rid bigint; iid bigint; iid_srv bigint; claims text; det text; r_ins text; r_sel text; r_upd text; r_del text; r_srv text;
  r_rest text := 'OK'; v_n int; n0 bigint; n1 bigint; iid_sa bigint;
BEGIN
  FOR sa IN SELECT p.id FROM public.perfiles p WHERE p.rol = 'super_admin' AND p.activo IS TRUE ORDER BY p.id LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub',sa::text,'role','authenticated')::text, true);
    EXIT WHEN COALESCE(private.tiene_rol(ARRAY['super_admin']), false);
  END LOOP;
  IF NOT COALESCE(private.tiene_rol(ARRAY['super_admin']), false) THEN sa := NULL; END IF;
  PERFORM set_config('request.jwt.claims','',true);
  SELECT r.id INTO rid FROM public.recetas r ORDER BY r.id LIMIT 1;
  IF sa IS NULL OR rid IS NULL THEN RAISE EXCEPTION 'fixture roto: super_admin=% receta=%', sa, rid; END IF;
  claims := json_build_object('sub',sa::text,'role','authenticated')::text;
  SELECT count(*) INTO n0 FROM public.receta_items;
  INSERT INTO public.receta_items (receta_id, nombre_medicamento, dosis, frecuencia, cantidad)
  VALUES (rid, 'P838 QA', '1', 'c/8h', 1) RETURNING id INTO iid;

  -- INSERT -> 42501
  BEGIN
    PERFORM set_config('request.jwt.claims', claims, true); PERFORM set_config('role','authenticated',true);
    INSERT INTO public.receta_items (receta_id, nombre_medicamento, dosis, frecuencia, cantidad)
    VALUES (rid, 'P838 QA sa', '1', 'c/8h', 1) RETURNING id INTO iid_sa;
    PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
    r_ins := 'PASO|00000|item '||iid_sa;
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
    r_ins := CASE WHEN SQLSTATE = '42501' AND SQLERRM ILIKE 'permission denied for table receta_items' THEN '42501' ELSE 'ERR' END||'|'||SQLSTATE||'|'||SQLERRM; END;
  det := 'super_admin INSERT en receta_items|42501 permission denied|'||r_ins;
  IF iid_sa IS NOT NULL THEN DELETE FROM public.receta_items WHERE id = iid_sa; END IF;

  -- SELECT / UPDATE / DELETE -> 1 fila cada uno
  BEGIN
    PERFORM set_config('request.jwt.claims', claims, true); PERFORM set_config('role','authenticated',true);
    SELECT count(*) INTO v_n FROM public.receta_items WHERE id = iid; r_sel := v_n||' filas';
    UPDATE public.receta_items SET cantidad = 2 WHERE id = iid; GET DIAGNOSTICS v_n = ROW_COUNT; r_upd := v_n||' filas';
    DELETE FROM public.receta_items WHERE id = iid; GET DIAGNOSTICS v_n = ROW_COUNT; r_del := v_n||' filas';
    PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
    r_del := COALESCE(r_del,'')||' ERR '||SQLSTATE||' '||SQLERRM; END;
  det := det||' ;; super_admin SELECT / UPDATE / DELETE del item sembrado|1 / 1 / 1|'||COALESCE(r_sel,'-')||' / '||COALESCE(r_upd,'-')||' / '||COALESCE(r_del,'-')||'|-|';

  -- service_role (edges) sigue insertando
  BEGIN
    PERFORM set_config('request.jwt.claims','{"role":"service_role"}', true); PERFORM set_config('role','service_role',true);
    INSERT INTO public.receta_items (receta_id, nombre_medicamento, dosis, frecuencia, cantidad)
    VALUES (rid, 'P838 QA srv', '1', 'c/8h', 1) RETURNING id INTO iid_srv;
    PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
    r_srv := 'OK';
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
    r_srv := 'ERR '||SQLSTATE||' '||SQLERRM; END;
  det := det||' ;; service_role INSERT en receta_items|OK|'||r_srv||'|-|';

  DELETE FROM public.receta_items WHERE id IN (iid, iid_srv);
  SELECT count(*) INTO n1 FROM public.receta_items;
  IF n1 <> n0 THEN r_rest := 'conteo no vuelve ('||n0||'->'||n1||')'; END IF;
  det := det||' ;; restauracion|receta_items='||n0||'|'||r_rest||'|-|receta_items='||n1;

  PERFORM set_config('probe.p838_det', det, false);
  PERFORM set_config('probe.p838', CASE WHEN split_part(r_ins,'|',1) = '42501' AND r_sel = '1 filas' AND r_upd = '1 filas'
      AND r_del = '1 filas' AND r_srv = 'OK' AND r_rest = 'OK'
    THEN 'OK (super_admin: INSERT 42501, SELECT/UPDATE/DELETE 1 fila; service_role inserta; restaurado)'
    ELSE 'ROJO (insert='||r_ins||' | sel='||COALESCE(r_sel,'-')||' upd='||COALESCE(r_upd,'-')||' del='||COALESCE(r_del,'-')
         ||' | service_role='||COALESCE(r_srv,'-')||' | restauracion='||r_rest||')' END, false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
  PERFORM set_config('probe.p838', CASE WHEN SQLERRM LIKE 'fixture roto%' THEN 'ROJO ('||SQLERRM||')'
    ELSE 'FALLO ('||SQLSTATE||' '||SQLERRM||')' END, false);
END $$;
SELECT set_config('role','none', true);

-- ---------------- P839 catalogo: sin INSERT para authenticated/anon/PUBLIC, sin policy INSERT/ALL, emitir_receta intacta ----------------
DO $$
DECLARE det text := ''; bad text := ''; t text; x text; pol text;
BEGIN
  FOREACH t IN ARRAY ARRAY['recetas','receta_items'] LOOP
    x := 'authenticated='||has_any_column_privilege('authenticated', ('public.'||t)::regclass, 'INSERT')
       ||' anon='||has_any_column_privilege('anon', ('public.'||t)::regclass, 'INSERT')
       ||' public='||EXISTS (SELECT 1 FROM pg_class c, aclexplode(c.relacl) a WHERE c.oid = ('public.'||t)::regclass AND a.grantee = 0 AND a.privilege_type = 'INSERT')
       ||' service_role='||has_table_privilege('service_role', ('public.'||t)::regclass, 'INSERT');
    det := det||CASE WHEN det = '' THEN '' ELSE ' ;; ' END||'INSERT en '||t||'|authenticated=false anon=false public=false service_role=true|'||x||'|-|';
    IF x <> 'authenticated=false anon=false public=false service_role=true' THEN bad := bad||t||': '||x||'; '; END IF;
  END LOOP;

  SELECT string_agg(c.relname||'.'||p.polname||'('||p.polcmd::text||')', ', ' ORDER BY 1) INTO pol
    FROM pg_policy p JOIN pg_class c ON c.oid = p.polrelid
   WHERE p.polrelid IN ('public.recetas'::regclass, 'public.receta_items'::regclass) AND p.polcmd IN ('a','*')
     AND (0 = ANY(p.polroles) OR 'authenticated'::regrole::oid = ANY(p.polroles));
  det := det||' ;; policies INSERT o ALL para authenticated/public|ninguna|'||COALESCE(pol,'ninguna')||'|-|';
  IF pol IS NOT NULL THEN bad := bad||'policies: '||pol||'; '; END IF;

  SELECT string_agg(p.polname||'='||p.polcmd::text, ',' ORDER BY p.polname) INTO pol FROM pg_policy p
   WHERE p.polrelid = 'public.receta_items'::regclass AND p.polname LIKE 'receta_items_%';
  det := det||' ;; policies receta_items_* |medico_select=r,superadmin_delete=d,superadmin_select=r,superadmin_update=w|'||COALESCE(pol,'ninguna')||'|-|';
  IF pol IS DISTINCT FROM 'receta_items_medico_select=r,receta_items_superadmin_delete=d,receta_items_superadmin_select=r,receta_items_superadmin_update=w' THEN
    bad := bad||'set receta_items_*: '||COALESCE(pol,'ninguna')||'; '; END IF;

  SELECT md5(p.prosrc)||' '||pg_get_userbyid(p.proowner)||' '||ARRAY(SELECT a::text FROM unnest(p.proacl) a ORDER BY 1)::text INTO x
    FROM pg_proc p WHERE p.oid = 'public.emitir_receta(bigint,text,jsonb)'::regprocedure;
  det := det||' ;; emitir_receta md5 owner acl|74d7013aeea17659bbafb84d780d644b postgres {authenticated=X/postgres,postgres=X/postgres,service_role=X/postgres}|'||COALESCE(x,'NULL')||'|-|';
  IF x IS DISTINCT FROM '74d7013aeea17659bbafb84d780d644b postgres {authenticated=X/postgres,postgres=X/postgres,service_role=X/postgres}' THEN
    bad := bad||'emitir_receta: '||COALESCE(x,'NULL')||'; '; END IF;

  PERFORM set_config('probe.p839_det', det, false);
  PERFORM set_config('probe.p839', CASE WHEN bad = ''
    THEN 'OK (recetas y receta_items sin INSERT para authenticated/anon/PUBLIC, sin policy INSERT/ALL; service_role intacto; emitir_receta intacta)'
    ELSE 'ROJO ('||left(bad,800)||')' END, false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('probe.p839','FALLO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;
SELECT set_config('role','none', true);

-- ================================================================================
-- MIG 329 — el despacho rechaza recetas canceladas (P840-P847).
-- OK = comportamiento de la 329; con 329_rollback aplicado dan ROJO P840-P845 y P847.
-- P846 es CONTROL: confirmar_recepcion_receta NO se toca (confirma algo ya entregado).
-- Fixture elegido como postgres: primer item sin dispensar, ruteado, de una receta ACTIVA con token
-- vigente, y la primera cuenta de su empresa con recetas_dispensar + entregas_gestionar + sucursal
-- visible. Caso A: la receta pasada a 'cancelada' dentro del probe -> PR010, firma sin cambios.
-- Caso B: activa -> OK con efecto verificado. Todo se restaura (ids previos, item, stock, fila
-- avanzada, estado) y se verifica contra la firma del snapshot. El token nunca se publica.
-- ================================================================================

-- ---------------- P840 verificar_receta_despacho ----------------
DO $$
DECLARE
  rid bigint; iid bigint; farm integer; nom text; emp uuid; ra uuid; tok text; ctok text; pac bigint; pac_uid uuid;
  cta uuid; c record; det text := ''; r_can text; r_act text; r_rest text := 'OK'; st text; msg text; j jsonb; v_n bigint;
  sig0 text; sig1 text; sig2 text; eff text;
  disp0 uuid[]; ent0 bigint[]; fal0 bigint[]; rev0 bigint[]; conf0 uuid[]; it0 record; stock0 jsonb; ra0 record; est0 text; sig_orig text; mod_orig text; emp_est0 text;
BEGIN
  SELECT ri.id, ri.receta_id, ri.farmacia_id, ri.nombre_medicamento, f.empresa_id, ra_.id, ra_.dispatch_token, ra_.confirmacion_token, r.paciente_id
    INTO iid, rid, farm, nom, emp, ra, tok, ctok, pac
    FROM public.receta_items ri JOIN public.farmacias f ON f.id = ri.farmacia_id
    JOIN public.recetas r ON r.id = ri.receta_id JOIN public.recetas_avanzadas ra_ ON ra_.receta_base_id = r.id
   WHERE ri.dispensado = false AND ra_.dispatch_token_expira_at > now() AND ra_.confirmacion_token_expira_at > now()
     AND r.estado = 'activa'
   ORDER BY ri.receta_id, ri.id LIMIT 1;
  IF iid IS NULL THEN RAISE EXCEPTION 'fixture roto: item ruteado de receta activa con token vigente'; END IF;
  -- el gate de estado de empresa (mig 322) exige empresa 'activa': si la dejo en otro estado un probe anterior
  -- del harness, se activa aca como fixture y se restaura al final (verificado).
  SELECT e.estado INTO emp_est0 FROM public.empresas_proveedoras e WHERE e.id = emp;
  IF emp_est0 IS DISTINCT FROM 'activa' THEN UPDATE public.empresas_proveedoras SET estado = 'activa' WHERE id = emp; END IF;
  FOR c IN SELECT cp.id FROM public.cuentas_proveedor cp WHERE cp.empresa_id = emp AND cp.activo IS TRUE ORDER BY cp.id LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub',c.id::text,'role','authenticated')::text, true);
    IF COALESCE(private.tiene_permiso('recetas_dispensar'), false) AND COALESCE(private.tiene_permiso('entregas_gestionar'), false)
       AND COALESCE(private.sucursal_visible(farm), false) THEN cta := c.id; EXIT; END IF;
  END LOOP;
  PERFORM set_config('request.jwt.claims','',true);
  IF cta IS NULL THEN RAISE EXCEPTION 'fixture roto: cuenta de farmacia con dispensar + entregas + sucursal visible'; END IF;
  SELECT p.auth_user_id INTO pac_uid FROM public.pacientes p WHERE p.id = pac;
  -- snapshot
  SELECT r.estado INTO est0 FROM public.recetas r WHERE r.id = rid;
  SELECT array_agg(id) INTO disp0 FROM public.dispensaciones WHERE receta_avanzada_id = ra;
  SELECT array_agg(id) INTO ent0 FROM public.entregas WHERE receta_base_id = rid;
  SELECT array_agg(id) INTO fal0 FROM private.delivery_autocreate_fallos WHERE receta_base_id = rid;
  SELECT array_agg(id) INTO rev0 FROM private.reveal_log WHERE receta_base_id = rid;
  SELECT array_agg(id) INTO conf0 FROM public.confirmaciones_receta WHERE receta_avanzada_id = ra;
  SELECT dispensado, dispensado_at, modalidad INTO it0 FROM public.receta_items WHERE id = iid;
  SELECT jsonb_agg(jsonb_build_object('id', id, 's', stock_actual, 'u', updated_at)) INTO stock0
    FROM public.farmacia_medicamentos WHERE farmacia_id = farm AND nombre_medicamento = nom;
  SELECT estado_dispensacion, fecha_dispensacion, farmacia_id, updated_at INTO ra0 FROM public.recetas_avanzadas WHERE id = ra;
  sig0 := concat_ws(' | ',
    'rec='||COALESCE((SELECT estado FROM public.recetas WHERE id = rid),'-'),
    'disp='||(SELECT count(*) FROM public.dispensaciones WHERE receta_avanzada_id = ra),
    'item='||COALESCE((SELECT dispensado::text||'@'||COALESCE(dispensado_at::text,'-')||'@'||COALESCE(modalidad,'-') FROM public.receta_items WHERE id = iid),'-'),
    'stock='||COALESCE((SELECT string_agg(id::text||':'||stock_actual||'@'||updated_at, ',' ORDER BY id) FROM public.farmacia_medicamentos WHERE farmacia_id = farm AND nombre_medicamento = nom),'-'),
    'ra='||COALESCE((SELECT COALESCE(estado_dispensacion,'-')||'@'||COALESCE(fecha_dispensacion::text,'-')||'@'||COALESCE(farmacia_id,'-')||'@'||updated_at FROM public.recetas_avanzadas WHERE id = ra),'-'),
    'entregas='||(SELECT count(*) FROM public.entregas WHERE receta_base_id = rid),
    'fallos='||(SELECT count(*) FROM private.delivery_autocreate_fallos WHERE receta_base_id = rid),
    'reveal='||(SELECT count(*) FROM private.reveal_log WHERE receta_base_id = rid),
    'confirm='||(SELECT count(*) FROM public.confirmaciones_receta WHERE receta_avanzada_id = ra));
  sig_orig := sig0; mod_orig := it0.modalidad;

  -- A) receta CANCELADA
  UPDATE public.recetas SET estado = 'cancelada' WHERE id = rid;
  st := '00000'; msg := ''; j := NULL;
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',cta::text,'role','authenticated')::text, true); PERFORM set_config('role','authenticated',true);
    j := public.verificar_receta_despacho(tok);
    PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
    st := SQLSTATE; msg := SQLERRM; END;
  r_can := CASE WHEN st = '00000' THEN 'OK' ELSE 'ERR' END;
  r_can := st||' '||msg;
  UPDATE public.recetas SET estado = est0 WHERE id = rid;
  sig1 := concat_ws(' | ',
    'rec='||COALESCE((SELECT estado FROM public.recetas WHERE id = rid),'-'),
    'disp='||(SELECT count(*) FROM public.dispensaciones WHERE receta_avanzada_id = ra),
    'item='||COALESCE((SELECT dispensado::text||'@'||COALESCE(dispensado_at::text,'-')||'@'||COALESCE(modalidad,'-') FROM public.receta_items WHERE id = iid),'-'),
    'stock='||COALESCE((SELECT string_agg(id::text||':'||stock_actual||'@'||updated_at, ',' ORDER BY id) FROM public.farmacia_medicamentos WHERE farmacia_id = farm AND nombre_medicamento = nom),'-'),
    'ra='||COALESCE((SELECT COALESCE(estado_dispensacion,'-')||'@'||COALESCE(fecha_dispensacion::text,'-')||'@'||COALESCE(farmacia_id,'-')||'@'||updated_at FROM public.recetas_avanzadas WHERE id = ra),'-'),
    'entregas='||(SELECT count(*) FROM public.entregas WHERE receta_base_id = rid),
    'fallos='||(SELECT count(*) FROM private.delivery_autocreate_fallos WHERE receta_base_id = rid),
    'reveal='||(SELECT count(*) FROM private.reveal_log WHERE receta_base_id = rid),
    'confirm='||(SELECT count(*) FROM public.confirmaciones_receta WHERE receta_avanzada_id = ra));
  DELETE FROM public.dispensaciones WHERE receta_avanzada_id = ra AND NOT (id = ANY(COALESCE(disp0, '{}')));
  DELETE FROM public.entregas WHERE receta_base_id = rid AND NOT (id = ANY(COALESCE(ent0, '{}')));
  DELETE FROM private.delivery_autocreate_fallos WHERE receta_base_id = rid AND NOT (id = ANY(COALESCE(fal0, '{}')));
  DELETE FROM private.reveal_log WHERE receta_base_id = rid AND NOT (id = ANY(COALESCE(rev0, '{}')));
  DELETE FROM public.confirmaciones_receta WHERE receta_avanzada_id = ra AND NOT (id = ANY(COALESCE(conf0, '{}')));
  UPDATE public.receta_items SET dispensado = it0.dispensado, dispensado_at = it0.dispensado_at, modalidad = it0.modalidad WHERE id = iid;
  UPDATE public.farmacia_medicamentos fm SET stock_actual = x.s, updated_at = x.u
    FROM jsonb_to_recordset(COALESCE(stock0, '[]')) AS x(id uuid, s integer, u timestamptz) WHERE fm.id = x.id;
  UPDATE public.recetas_avanzadas SET estado_dispensacion = ra0.estado_dispensacion, fecha_dispensacion = ra0.fecha_dispensacion,
         farmacia_id = ra0.farmacia_id, updated_at = ra0.updated_at WHERE id = ra;
  UPDATE public.recetas SET estado = est0 WHERE id = rid;

  det := 'cancelada|PR010 Receta cancelada: no se puede despachar|'||CASE WHEN r_can = 'PR010 Receta cancelada: no se puede despachar' THEN 'OK' ELSE 'ROJO' END||'|'||st||'|'||msg
         ||' ;; cancelada: sin filas ni cambios|firma igual al snapshot|'||CASE WHEN sig1 = sig0 THEN 'igual' ELSE 'DISTINTA' END||'|-|';
  -- B) receta ACTIVA -> OK, efecto verificado y restaurado
  st := '00000'; msg := ''; j := NULL;
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',cta::text,'role','authenticated')::text, true); PERFORM set_config('role','authenticated',true);
    j := public.verificar_receta_despacho(tok);
    PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
    st := SQLSTATE; msg := SQLERRM; END;
  r_act := CASE WHEN st = '00000' THEN 'OK' ELSE 'ERR' END;
  eff := 'receta_id='||COALESCE(j->>'receta_id','-')||' coincide='||((j->>'receta_id')::bigint = rid);
  det := det||' ;; activa|OK|'||r_act||' '||COALESCE(eff,'-')||'|'||st||'|'||msg;
  IF r_act = 'OK' AND NOT ((j->>'receta_id')::bigint = rid) THEN r_act := 'OK-SIN-EFECTO'; END IF;
  DELETE FROM public.dispensaciones WHERE receta_avanzada_id = ra AND NOT (id = ANY(COALESCE(disp0, '{}')));
  DELETE FROM public.entregas WHERE receta_base_id = rid AND NOT (id = ANY(COALESCE(ent0, '{}')));
  DELETE FROM private.delivery_autocreate_fallos WHERE receta_base_id = rid AND NOT (id = ANY(COALESCE(fal0, '{}')));
  DELETE FROM private.reveal_log WHERE receta_base_id = rid AND NOT (id = ANY(COALESCE(rev0, '{}')));
  DELETE FROM public.confirmaciones_receta WHERE receta_avanzada_id = ra AND NOT (id = ANY(COALESCE(conf0, '{}')));
  UPDATE public.receta_items SET dispensado = it0.dispensado, dispensado_at = it0.dispensado_at, modalidad = it0.modalidad WHERE id = iid;
  UPDATE public.farmacia_medicamentos fm SET stock_actual = x.s, updated_at = x.u
    FROM jsonb_to_recordset(COALESCE(stock0, '[]')) AS x(id uuid, s integer, u timestamptz) WHERE fm.id = x.id;
  UPDATE public.recetas_avanzadas SET estado_dispensacion = ra0.estado_dispensacion, fecha_dispensacion = ra0.fecha_dispensacion,
         farmacia_id = ra0.farmacia_id, updated_at = ra0.updated_at WHERE id = ra;
  UPDATE public.recetas SET estado = est0 WHERE id = rid;

  sig2 := concat_ws(' | ',
    'rec='||COALESCE((SELECT estado FROM public.recetas WHERE id = rid),'-'),
    'disp='||(SELECT count(*) FROM public.dispensaciones WHERE receta_avanzada_id = ra),
    'item='||COALESCE((SELECT dispensado::text||'@'||COALESCE(dispensado_at::text,'-')||'@'||COALESCE(modalidad,'-') FROM public.receta_items WHERE id = iid),'-'),
    'stock='||COALESCE((SELECT string_agg(id::text||':'||stock_actual||'@'||updated_at, ',' ORDER BY id) FROM public.farmacia_medicamentos WHERE farmacia_id = farm AND nombre_medicamento = nom),'-'),
    'ra='||COALESCE((SELECT COALESCE(estado_dispensacion,'-')||'@'||COALESCE(fecha_dispensacion::text,'-')||'@'||COALESCE(farmacia_id,'-')||'@'||updated_at FROM public.recetas_avanzadas WHERE id = ra),'-'),
    'entregas='||(SELECT count(*) FROM public.entregas WHERE receta_base_id = rid),
    'fallos='||(SELECT count(*) FROM private.delivery_autocreate_fallos WHERE receta_base_id = rid),
    'reveal='||(SELECT count(*) FROM private.reveal_log WHERE receta_base_id = rid),
    'confirm='||(SELECT count(*) FROM public.confirmaciones_receta WHERE receta_avanzada_id = ra));
  IF sig2 IS DISTINCT FROM sig_orig THEN r_rest := 'firma no vuelve al snapshot original'; END IF;
  UPDATE public.empresas_proveedoras SET estado = emp_est0 WHERE id = emp AND estado IS DISTINCT FROM emp_est0;
  IF (SELECT estado FROM public.empresas_proveedoras WHERE id = emp) IS DISTINCT FROM emp_est0 THEN
    r_rest := r_rest||' / estado de empresa no vuelve'; END IF;
  det := det||' ;; empresa del fixture|estado original '||COALESCE(emp_est0,'-')||'|'||CASE WHEN emp_est0 = 'activa' THEN 'ya activa' ELSE 'activada para el probe y restaurada' END||'|-|';
  det := det||' ;; restauracion|firma igual al snapshot|'||r_rest||'|-|';

  PERFORM set_config('probe.p840_det', det, false);
  PERFORM set_config('probe.p840', CASE WHEN (r_can = 'PR010 Receta cancelada: no se puede despachar') AND sig1 = sig0 AND r_act = 'OK' AND r_rest = 'OK'
    THEN 'OK (verificar_receta_despacho: cancelada -> PR010, activa -> OK con efecto; restaurado)'
    ELSE 'ROJO (cancelada='||r_can||' | activa='||r_act||' '||COALESCE(eff,'-')||' | firma_cancelada='||(sig1 = sig0)||' | restauracion='||r_rest||')' END, false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
  PERFORM set_config('probe.p840', CASE WHEN SQLERRM LIKE 'fixture roto%' THEN 'ROJO ('||SQLERRM||')'
    ELSE 'FALLO ('||SQLSTATE||' '||SQLERRM||')' END, false);
END $$;
SELECT set_config('role','none', true);

-- ---------------- P841 registrar_dispensacion (token) ----------------
DO $$
DECLARE
  rid bigint; iid bigint; farm integer; nom text; emp uuid; ra uuid; tok text; ctok text; pac bigint; pac_uid uuid;
  cta uuid; c record; det text := ''; r_can text; r_act text; r_rest text := 'OK'; st text; msg text; j jsonb; v_n bigint;
  sig0 text; sig1 text; sig2 text; eff text;
  disp0 uuid[]; ent0 bigint[]; fal0 bigint[]; rev0 bigint[]; conf0 uuid[]; it0 record; stock0 jsonb; ra0 record; est0 text; sig_orig text; mod_orig text; emp_est0 text;
BEGIN
  SELECT ri.id, ri.receta_id, ri.farmacia_id, ri.nombre_medicamento, f.empresa_id, ra_.id, ra_.dispatch_token, ra_.confirmacion_token, r.paciente_id
    INTO iid, rid, farm, nom, emp, ra, tok, ctok, pac
    FROM public.receta_items ri JOIN public.farmacias f ON f.id = ri.farmacia_id
    JOIN public.recetas r ON r.id = ri.receta_id JOIN public.recetas_avanzadas ra_ ON ra_.receta_base_id = r.id
   WHERE ri.dispensado = false AND ra_.dispatch_token_expira_at > now() AND ra_.confirmacion_token_expira_at > now()
     AND r.estado = 'activa'
   ORDER BY ri.receta_id, ri.id LIMIT 1;
  IF iid IS NULL THEN RAISE EXCEPTION 'fixture roto: item ruteado de receta activa con token vigente'; END IF;
  -- el gate de estado de empresa (mig 322) exige empresa 'activa': si la dejo en otro estado un probe anterior
  -- del harness, se activa aca como fixture y se restaura al final (verificado).
  SELECT e.estado INTO emp_est0 FROM public.empresas_proveedoras e WHERE e.id = emp;
  IF emp_est0 IS DISTINCT FROM 'activa' THEN UPDATE public.empresas_proveedoras SET estado = 'activa' WHERE id = emp; END IF;
  FOR c IN SELECT cp.id FROM public.cuentas_proveedor cp WHERE cp.empresa_id = emp AND cp.activo IS TRUE ORDER BY cp.id LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub',c.id::text,'role','authenticated')::text, true);
    IF COALESCE(private.tiene_permiso('recetas_dispensar'), false) AND COALESCE(private.tiene_permiso('entregas_gestionar'), false)
       AND COALESCE(private.sucursal_visible(farm), false) THEN cta := c.id; EXIT; END IF;
  END LOOP;
  PERFORM set_config('request.jwt.claims','',true);
  IF cta IS NULL THEN RAISE EXCEPTION 'fixture roto: cuenta de farmacia con dispensar + entregas + sucursal visible'; END IF;
  SELECT p.auth_user_id INTO pac_uid FROM public.pacientes p WHERE p.id = pac;
  -- snapshot
  SELECT r.estado INTO est0 FROM public.recetas r WHERE r.id = rid;
  SELECT array_agg(id) INTO disp0 FROM public.dispensaciones WHERE receta_avanzada_id = ra;
  SELECT array_agg(id) INTO ent0 FROM public.entregas WHERE receta_base_id = rid;
  SELECT array_agg(id) INTO fal0 FROM private.delivery_autocreate_fallos WHERE receta_base_id = rid;
  SELECT array_agg(id) INTO rev0 FROM private.reveal_log WHERE receta_base_id = rid;
  SELECT array_agg(id) INTO conf0 FROM public.confirmaciones_receta WHERE receta_avanzada_id = ra;
  SELECT dispensado, dispensado_at, modalidad INTO it0 FROM public.receta_items WHERE id = iid;
  SELECT jsonb_agg(jsonb_build_object('id', id, 's', stock_actual, 'u', updated_at)) INTO stock0
    FROM public.farmacia_medicamentos WHERE farmacia_id = farm AND nombre_medicamento = nom;
  SELECT estado_dispensacion, fecha_dispensacion, farmacia_id, updated_at INTO ra0 FROM public.recetas_avanzadas WHERE id = ra;
  sig0 := concat_ws(' | ',
    'rec='||COALESCE((SELECT estado FROM public.recetas WHERE id = rid),'-'),
    'disp='||(SELECT count(*) FROM public.dispensaciones WHERE receta_avanzada_id = ra),
    'item='||COALESCE((SELECT dispensado::text||'@'||COALESCE(dispensado_at::text,'-')||'@'||COALESCE(modalidad,'-') FROM public.receta_items WHERE id = iid),'-'),
    'stock='||COALESCE((SELECT string_agg(id::text||':'||stock_actual||'@'||updated_at, ',' ORDER BY id) FROM public.farmacia_medicamentos WHERE farmacia_id = farm AND nombre_medicamento = nom),'-'),
    'ra='||COALESCE((SELECT COALESCE(estado_dispensacion,'-')||'@'||COALESCE(fecha_dispensacion::text,'-')||'@'||COALESCE(farmacia_id,'-')||'@'||updated_at FROM public.recetas_avanzadas WHERE id = ra),'-'),
    'entregas='||(SELECT count(*) FROM public.entregas WHERE receta_base_id = rid),
    'fallos='||(SELECT count(*) FROM private.delivery_autocreate_fallos WHERE receta_base_id = rid),
    'reveal='||(SELECT count(*) FROM private.reveal_log WHERE receta_base_id = rid),
    'confirm='||(SELECT count(*) FROM public.confirmaciones_receta WHERE receta_avanzada_id = ra));
  sig_orig := sig0; mod_orig := it0.modalidad;

  -- A) receta CANCELADA
  UPDATE public.recetas SET estado = 'cancelada' WHERE id = rid;
  st := '00000'; msg := ''; j := NULL;
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',cta::text,'role','authenticated')::text, true); PERFORM set_config('role','authenticated',true);
    j := public.registrar_dispensacion(tok, ARRAY[iid], 'P841 QA');
    PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
    st := SQLSTATE; msg := SQLERRM; END;
  r_can := CASE WHEN st = '00000' THEN 'OK' ELSE 'ERR' END;
  r_can := st||' '||msg;
  UPDATE public.recetas SET estado = est0 WHERE id = rid;
  sig1 := concat_ws(' | ',
    'rec='||COALESCE((SELECT estado FROM public.recetas WHERE id = rid),'-'),
    'disp='||(SELECT count(*) FROM public.dispensaciones WHERE receta_avanzada_id = ra),
    'item='||COALESCE((SELECT dispensado::text||'@'||COALESCE(dispensado_at::text,'-')||'@'||COALESCE(modalidad,'-') FROM public.receta_items WHERE id = iid),'-'),
    'stock='||COALESCE((SELECT string_agg(id::text||':'||stock_actual||'@'||updated_at, ',' ORDER BY id) FROM public.farmacia_medicamentos WHERE farmacia_id = farm AND nombre_medicamento = nom),'-'),
    'ra='||COALESCE((SELECT COALESCE(estado_dispensacion,'-')||'@'||COALESCE(fecha_dispensacion::text,'-')||'@'||COALESCE(farmacia_id,'-')||'@'||updated_at FROM public.recetas_avanzadas WHERE id = ra),'-'),
    'entregas='||(SELECT count(*) FROM public.entregas WHERE receta_base_id = rid),
    'fallos='||(SELECT count(*) FROM private.delivery_autocreate_fallos WHERE receta_base_id = rid),
    'reveal='||(SELECT count(*) FROM private.reveal_log WHERE receta_base_id = rid),
    'confirm='||(SELECT count(*) FROM public.confirmaciones_receta WHERE receta_avanzada_id = ra));
  DELETE FROM public.dispensaciones WHERE receta_avanzada_id = ra AND NOT (id = ANY(COALESCE(disp0, '{}')));
  DELETE FROM public.entregas WHERE receta_base_id = rid AND NOT (id = ANY(COALESCE(ent0, '{}')));
  DELETE FROM private.delivery_autocreate_fallos WHERE receta_base_id = rid AND NOT (id = ANY(COALESCE(fal0, '{}')));
  DELETE FROM private.reveal_log WHERE receta_base_id = rid AND NOT (id = ANY(COALESCE(rev0, '{}')));
  DELETE FROM public.confirmaciones_receta WHERE receta_avanzada_id = ra AND NOT (id = ANY(COALESCE(conf0, '{}')));
  UPDATE public.receta_items SET dispensado = it0.dispensado, dispensado_at = it0.dispensado_at, modalidad = it0.modalidad WHERE id = iid;
  UPDATE public.farmacia_medicamentos fm SET stock_actual = x.s, updated_at = x.u
    FROM jsonb_to_recordset(COALESCE(stock0, '[]')) AS x(id uuid, s integer, u timestamptz) WHERE fm.id = x.id;
  UPDATE public.recetas_avanzadas SET estado_dispensacion = ra0.estado_dispensacion, fecha_dispensacion = ra0.fecha_dispensacion,
         farmacia_id = ra0.farmacia_id, updated_at = ra0.updated_at WHERE id = ra;
  UPDATE public.recetas SET estado = est0 WHERE id = rid;

  det := 'cancelada|PR010 Receta cancelada: no se puede despachar|'||CASE WHEN r_can = 'PR010 Receta cancelada: no se puede despachar' THEN 'OK' ELSE 'ROJO' END||'|'||st||'|'||msg
         ||' ;; cancelada: sin filas ni cambios|firma igual al snapshot|'||CASE WHEN sig1 = sig0 THEN 'igual' ELSE 'DISTINTA' END||'|-|';
  -- B) receta ACTIVA -> OK, efecto verificado y restaurado
  st := '00000'; msg := ''; j := NULL;
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',cta::text,'role','authenticated')::text, true); PERFORM set_config('role','authenticated',true);
    j := public.registrar_dispensacion(tok, ARRAY[iid], 'P841 QA');
    PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
    st := SQLSTATE; msg := SQLERRM; END;
  r_act := CASE WHEN st = '00000' THEN 'OK' ELSE 'ERR' END;
  eff := 'despachados='||COALESCE(j->>'despachados','-')
    ||' item_dispensado='||(SELECT dispensado FROM public.receta_items WHERE id = iid)
    ||' dispensaciones+'||((SELECT count(*) FROM public.dispensaciones WHERE receta_avanzada_id = ra) - COALESCE(array_length(disp0,1),0))
    ||' estado_dispensacion='||COALESCE((SELECT estado_dispensacion FROM public.recetas_avanzadas WHERE id = ra),'-');
  det := det||' ;; activa|OK|'||r_act||' '||COALESCE(eff,'-')||'|'||st||'|'||msg;
  IF r_act = 'OK' AND NOT ((j->>'despachados') = '1' AND (SELECT dispensado FROM public.receta_items WHERE id = iid) IS TRUE
    AND (SELECT count(*) FROM public.dispensaciones WHERE receta_avanzada_id = ra) = COALESCE(array_length(disp0,1),0) + 1
    AND (SELECT estado_dispensacion FROM public.recetas_avanzadas WHERE id = ra) IN ('dispensada','parcial')) THEN r_act := 'OK-SIN-EFECTO'; END IF;
  DELETE FROM public.dispensaciones WHERE receta_avanzada_id = ra AND NOT (id = ANY(COALESCE(disp0, '{}')));
  DELETE FROM public.entregas WHERE receta_base_id = rid AND NOT (id = ANY(COALESCE(ent0, '{}')));
  DELETE FROM private.delivery_autocreate_fallos WHERE receta_base_id = rid AND NOT (id = ANY(COALESCE(fal0, '{}')));
  DELETE FROM private.reveal_log WHERE receta_base_id = rid AND NOT (id = ANY(COALESCE(rev0, '{}')));
  DELETE FROM public.confirmaciones_receta WHERE receta_avanzada_id = ra AND NOT (id = ANY(COALESCE(conf0, '{}')));
  UPDATE public.receta_items SET dispensado = it0.dispensado, dispensado_at = it0.dispensado_at, modalidad = it0.modalidad WHERE id = iid;
  UPDATE public.farmacia_medicamentos fm SET stock_actual = x.s, updated_at = x.u
    FROM jsonb_to_recordset(COALESCE(stock0, '[]')) AS x(id uuid, s integer, u timestamptz) WHERE fm.id = x.id;
  UPDATE public.recetas_avanzadas SET estado_dispensacion = ra0.estado_dispensacion, fecha_dispensacion = ra0.fecha_dispensacion,
         farmacia_id = ra0.farmacia_id, updated_at = ra0.updated_at WHERE id = ra;
  UPDATE public.recetas SET estado = est0 WHERE id = rid;

  sig2 := concat_ws(' | ',
    'rec='||COALESCE((SELECT estado FROM public.recetas WHERE id = rid),'-'),
    'disp='||(SELECT count(*) FROM public.dispensaciones WHERE receta_avanzada_id = ra),
    'item='||COALESCE((SELECT dispensado::text||'@'||COALESCE(dispensado_at::text,'-')||'@'||COALESCE(modalidad,'-') FROM public.receta_items WHERE id = iid),'-'),
    'stock='||COALESCE((SELECT string_agg(id::text||':'||stock_actual||'@'||updated_at, ',' ORDER BY id) FROM public.farmacia_medicamentos WHERE farmacia_id = farm AND nombre_medicamento = nom),'-'),
    'ra='||COALESCE((SELECT COALESCE(estado_dispensacion,'-')||'@'||COALESCE(fecha_dispensacion::text,'-')||'@'||COALESCE(farmacia_id,'-')||'@'||updated_at FROM public.recetas_avanzadas WHERE id = ra),'-'),
    'entregas='||(SELECT count(*) FROM public.entregas WHERE receta_base_id = rid),
    'fallos='||(SELECT count(*) FROM private.delivery_autocreate_fallos WHERE receta_base_id = rid),
    'reveal='||(SELECT count(*) FROM private.reveal_log WHERE receta_base_id = rid),
    'confirm='||(SELECT count(*) FROM public.confirmaciones_receta WHERE receta_avanzada_id = ra));
  IF sig2 IS DISTINCT FROM sig_orig THEN r_rest := 'firma no vuelve al snapshot original'; END IF;
  UPDATE public.empresas_proveedoras SET estado = emp_est0 WHERE id = emp AND estado IS DISTINCT FROM emp_est0;
  IF (SELECT estado FROM public.empresas_proveedoras WHERE id = emp) IS DISTINCT FROM emp_est0 THEN
    r_rest := r_rest||' / estado de empresa no vuelve'; END IF;
  det := det||' ;; empresa del fixture|estado original '||COALESCE(emp_est0,'-')||'|'||CASE WHEN emp_est0 = 'activa' THEN 'ya activa' ELSE 'activada para el probe y restaurada' END||'|-|';
  det := det||' ;; restauracion|firma igual al snapshot|'||r_rest||'|-|';

  PERFORM set_config('probe.p841_det', det, false);
  PERFORM set_config('probe.p841', CASE WHEN (r_can = 'PR010 Receta cancelada: no se puede despachar') AND sig1 = sig0 AND r_act = 'OK' AND r_rest = 'OK'
    THEN 'OK (registrar_dispensacion (token): cancelada -> PR010, activa -> OK con efecto; restaurado)'
    ELSE 'ROJO (cancelada='||r_can||' | activa='||r_act||' '||COALESCE(eff,'-')||' | firma_cancelada='||(sig1 = sig0)||' | restauracion='||r_rest||')' END, false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
  PERFORM set_config('probe.p841', CASE WHEN SQLERRM LIKE 'fixture roto%' THEN 'ROJO ('||SQLERRM||')'
    ELSE 'FALLO ('||SQLSTATE||' '||SQLERRM||')' END, false);
END $$;
SELECT set_config('role','none', true);

-- ---------------- P842 registrar_dispensacion_dirigida (receta_id) ----------------
DO $$
DECLARE
  rid bigint; iid bigint; farm integer; nom text; emp uuid; ra uuid; tok text; ctok text; pac bigint; pac_uid uuid;
  cta uuid; c record; det text := ''; r_can text; r_act text; r_rest text := 'OK'; st text; msg text; j jsonb; v_n bigint;
  sig0 text; sig1 text; sig2 text; eff text;
  disp0 uuid[]; ent0 bigint[]; fal0 bigint[]; rev0 bigint[]; conf0 uuid[]; it0 record; stock0 jsonb; ra0 record; est0 text; sig_orig text; mod_orig text; emp_est0 text;
BEGIN
  SELECT ri.id, ri.receta_id, ri.farmacia_id, ri.nombre_medicamento, f.empresa_id, ra_.id, ra_.dispatch_token, ra_.confirmacion_token, r.paciente_id
    INTO iid, rid, farm, nom, emp, ra, tok, ctok, pac
    FROM public.receta_items ri JOIN public.farmacias f ON f.id = ri.farmacia_id
    JOIN public.recetas r ON r.id = ri.receta_id JOIN public.recetas_avanzadas ra_ ON ra_.receta_base_id = r.id
   WHERE ri.dispensado = false AND ra_.dispatch_token_expira_at > now() AND ra_.confirmacion_token_expira_at > now()
     AND r.estado = 'activa'
   ORDER BY ri.receta_id, ri.id LIMIT 1;
  IF iid IS NULL THEN RAISE EXCEPTION 'fixture roto: item ruteado de receta activa con token vigente'; END IF;
  -- el gate de estado de empresa (mig 322) exige empresa 'activa': si la dejo en otro estado un probe anterior
  -- del harness, se activa aca como fixture y se restaura al final (verificado).
  SELECT e.estado INTO emp_est0 FROM public.empresas_proveedoras e WHERE e.id = emp;
  IF emp_est0 IS DISTINCT FROM 'activa' THEN UPDATE public.empresas_proveedoras SET estado = 'activa' WHERE id = emp; END IF;
  FOR c IN SELECT cp.id FROM public.cuentas_proveedor cp WHERE cp.empresa_id = emp AND cp.activo IS TRUE ORDER BY cp.id LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub',c.id::text,'role','authenticated')::text, true);
    IF COALESCE(private.tiene_permiso('recetas_dispensar'), false) AND COALESCE(private.tiene_permiso('entregas_gestionar'), false)
       AND COALESCE(private.sucursal_visible(farm), false) THEN cta := c.id; EXIT; END IF;
  END LOOP;
  PERFORM set_config('request.jwt.claims','',true);
  IF cta IS NULL THEN RAISE EXCEPTION 'fixture roto: cuenta de farmacia con dispensar + entregas + sucursal visible'; END IF;
  SELECT p.auth_user_id INTO pac_uid FROM public.pacientes p WHERE p.id = pac;
  -- snapshot
  SELECT r.estado INTO est0 FROM public.recetas r WHERE r.id = rid;
  SELECT array_agg(id) INTO disp0 FROM public.dispensaciones WHERE receta_avanzada_id = ra;
  SELECT array_agg(id) INTO ent0 FROM public.entregas WHERE receta_base_id = rid;
  SELECT array_agg(id) INTO fal0 FROM private.delivery_autocreate_fallos WHERE receta_base_id = rid;
  SELECT array_agg(id) INTO rev0 FROM private.reveal_log WHERE receta_base_id = rid;
  SELECT array_agg(id) INTO conf0 FROM public.confirmaciones_receta WHERE receta_avanzada_id = ra;
  SELECT dispensado, dispensado_at, modalidad INTO it0 FROM public.receta_items WHERE id = iid;
  SELECT jsonb_agg(jsonb_build_object('id', id, 's', stock_actual, 'u', updated_at)) INTO stock0
    FROM public.farmacia_medicamentos WHERE farmacia_id = farm AND nombre_medicamento = nom;
  SELECT estado_dispensacion, fecha_dispensacion, farmacia_id, updated_at INTO ra0 FROM public.recetas_avanzadas WHERE id = ra;
  sig0 := concat_ws(' | ',
    'rec='||COALESCE((SELECT estado FROM public.recetas WHERE id = rid),'-'),
    'disp='||(SELECT count(*) FROM public.dispensaciones WHERE receta_avanzada_id = ra),
    'item='||COALESCE((SELECT dispensado::text||'@'||COALESCE(dispensado_at::text,'-')||'@'||COALESCE(modalidad,'-') FROM public.receta_items WHERE id = iid),'-'),
    'stock='||COALESCE((SELECT string_agg(id::text||':'||stock_actual||'@'||updated_at, ',' ORDER BY id) FROM public.farmacia_medicamentos WHERE farmacia_id = farm AND nombre_medicamento = nom),'-'),
    'ra='||COALESCE((SELECT COALESCE(estado_dispensacion,'-')||'@'||COALESCE(fecha_dispensacion::text,'-')||'@'||COALESCE(farmacia_id,'-')||'@'||updated_at FROM public.recetas_avanzadas WHERE id = ra),'-'),
    'entregas='||(SELECT count(*) FROM public.entregas WHERE receta_base_id = rid),
    'fallos='||(SELECT count(*) FROM private.delivery_autocreate_fallos WHERE receta_base_id = rid),
    'reveal='||(SELECT count(*) FROM private.reveal_log WHERE receta_base_id = rid),
    'confirm='||(SELECT count(*) FROM public.confirmaciones_receta WHERE receta_avanzada_id = ra));
  sig_orig := sig0; mod_orig := it0.modalidad;

  -- A) receta CANCELADA
  UPDATE public.recetas SET estado = 'cancelada' WHERE id = rid;
  st := '00000'; msg := ''; j := NULL;
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',cta::text,'role','authenticated')::text, true); PERFORM set_config('role','authenticated',true);
    j := public.registrar_dispensacion_dirigida(rid, ARRAY[iid], 'P842 QA');
    PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
    st := SQLSTATE; msg := SQLERRM; END;
  r_can := CASE WHEN st = '00000' THEN 'OK' ELSE 'ERR' END;
  r_can := st||' '||msg;
  UPDATE public.recetas SET estado = est0 WHERE id = rid;
  sig1 := concat_ws(' | ',
    'rec='||COALESCE((SELECT estado FROM public.recetas WHERE id = rid),'-'),
    'disp='||(SELECT count(*) FROM public.dispensaciones WHERE receta_avanzada_id = ra),
    'item='||COALESCE((SELECT dispensado::text||'@'||COALESCE(dispensado_at::text,'-')||'@'||COALESCE(modalidad,'-') FROM public.receta_items WHERE id = iid),'-'),
    'stock='||COALESCE((SELECT string_agg(id::text||':'||stock_actual||'@'||updated_at, ',' ORDER BY id) FROM public.farmacia_medicamentos WHERE farmacia_id = farm AND nombre_medicamento = nom),'-'),
    'ra='||COALESCE((SELECT COALESCE(estado_dispensacion,'-')||'@'||COALESCE(fecha_dispensacion::text,'-')||'@'||COALESCE(farmacia_id,'-')||'@'||updated_at FROM public.recetas_avanzadas WHERE id = ra),'-'),
    'entregas='||(SELECT count(*) FROM public.entregas WHERE receta_base_id = rid),
    'fallos='||(SELECT count(*) FROM private.delivery_autocreate_fallos WHERE receta_base_id = rid),
    'reveal='||(SELECT count(*) FROM private.reveal_log WHERE receta_base_id = rid),
    'confirm='||(SELECT count(*) FROM public.confirmaciones_receta WHERE receta_avanzada_id = ra));
  DELETE FROM public.dispensaciones WHERE receta_avanzada_id = ra AND NOT (id = ANY(COALESCE(disp0, '{}')));
  DELETE FROM public.entregas WHERE receta_base_id = rid AND NOT (id = ANY(COALESCE(ent0, '{}')));
  DELETE FROM private.delivery_autocreate_fallos WHERE receta_base_id = rid AND NOT (id = ANY(COALESCE(fal0, '{}')));
  DELETE FROM private.reveal_log WHERE receta_base_id = rid AND NOT (id = ANY(COALESCE(rev0, '{}')));
  DELETE FROM public.confirmaciones_receta WHERE receta_avanzada_id = ra AND NOT (id = ANY(COALESCE(conf0, '{}')));
  UPDATE public.receta_items SET dispensado = it0.dispensado, dispensado_at = it0.dispensado_at, modalidad = it0.modalidad WHERE id = iid;
  UPDATE public.farmacia_medicamentos fm SET stock_actual = x.s, updated_at = x.u
    FROM jsonb_to_recordset(COALESCE(stock0, '[]')) AS x(id uuid, s integer, u timestamptz) WHERE fm.id = x.id;
  UPDATE public.recetas_avanzadas SET estado_dispensacion = ra0.estado_dispensacion, fecha_dispensacion = ra0.fecha_dispensacion,
         farmacia_id = ra0.farmacia_id, updated_at = ra0.updated_at WHERE id = ra;
  UPDATE public.recetas SET estado = est0 WHERE id = rid;

  det := 'cancelada|PR010 Receta cancelada: no se puede despachar|'||CASE WHEN r_can = 'PR010 Receta cancelada: no se puede despachar' THEN 'OK' ELSE 'ROJO' END||'|'||st||'|'||msg
         ||' ;; cancelada: sin filas ni cambios|firma igual al snapshot|'||CASE WHEN sig1 = sig0 THEN 'igual' ELSE 'DISTINTA' END||'|-|';
  -- B) receta ACTIVA -> OK, efecto verificado y restaurado
  st := '00000'; msg := ''; j := NULL;
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',cta::text,'role','authenticated')::text, true); PERFORM set_config('role','authenticated',true);
    j := public.registrar_dispensacion_dirigida(rid, ARRAY[iid], 'P842 QA');
    PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
    st := SQLSTATE; msg := SQLERRM; END;
  r_act := CASE WHEN st = '00000' THEN 'OK' ELSE 'ERR' END;
  eff := 'despachados='||COALESCE(j->>'despachados','-')
    ||' item_dispensado='||(SELECT dispensado FROM public.receta_items WHERE id = iid)
    ||' dispensaciones+'||((SELECT count(*) FROM public.dispensaciones WHERE receta_avanzada_id = ra) - COALESCE(array_length(disp0,1),0))
    ||' estado_dispensacion='||COALESCE((SELECT estado_dispensacion FROM public.recetas_avanzadas WHERE id = ra),'-');
  det := det||' ;; activa|OK|'||r_act||' '||COALESCE(eff,'-')||'|'||st||'|'||msg;
  IF r_act = 'OK' AND NOT ((j->>'despachados') = '1' AND (SELECT dispensado FROM public.receta_items WHERE id = iid) IS TRUE
    AND (SELECT count(*) FROM public.dispensaciones WHERE receta_avanzada_id = ra) = COALESCE(array_length(disp0,1),0) + 1
    AND (SELECT estado_dispensacion FROM public.recetas_avanzadas WHERE id = ra) IN ('dispensada','parcial')) THEN r_act := 'OK-SIN-EFECTO'; END IF;
  DELETE FROM public.dispensaciones WHERE receta_avanzada_id = ra AND NOT (id = ANY(COALESCE(disp0, '{}')));
  DELETE FROM public.entregas WHERE receta_base_id = rid AND NOT (id = ANY(COALESCE(ent0, '{}')));
  DELETE FROM private.delivery_autocreate_fallos WHERE receta_base_id = rid AND NOT (id = ANY(COALESCE(fal0, '{}')));
  DELETE FROM private.reveal_log WHERE receta_base_id = rid AND NOT (id = ANY(COALESCE(rev0, '{}')));
  DELETE FROM public.confirmaciones_receta WHERE receta_avanzada_id = ra AND NOT (id = ANY(COALESCE(conf0, '{}')));
  UPDATE public.receta_items SET dispensado = it0.dispensado, dispensado_at = it0.dispensado_at, modalidad = it0.modalidad WHERE id = iid;
  UPDATE public.farmacia_medicamentos fm SET stock_actual = x.s, updated_at = x.u
    FROM jsonb_to_recordset(COALESCE(stock0, '[]')) AS x(id uuid, s integer, u timestamptz) WHERE fm.id = x.id;
  UPDATE public.recetas_avanzadas SET estado_dispensacion = ra0.estado_dispensacion, fecha_dispensacion = ra0.fecha_dispensacion,
         farmacia_id = ra0.farmacia_id, updated_at = ra0.updated_at WHERE id = ra;
  UPDATE public.recetas SET estado = est0 WHERE id = rid;

  sig2 := concat_ws(' | ',
    'rec='||COALESCE((SELECT estado FROM public.recetas WHERE id = rid),'-'),
    'disp='||(SELECT count(*) FROM public.dispensaciones WHERE receta_avanzada_id = ra),
    'item='||COALESCE((SELECT dispensado::text||'@'||COALESCE(dispensado_at::text,'-')||'@'||COALESCE(modalidad,'-') FROM public.receta_items WHERE id = iid),'-'),
    'stock='||COALESCE((SELECT string_agg(id::text||':'||stock_actual||'@'||updated_at, ',' ORDER BY id) FROM public.farmacia_medicamentos WHERE farmacia_id = farm AND nombre_medicamento = nom),'-'),
    'ra='||COALESCE((SELECT COALESCE(estado_dispensacion,'-')||'@'||COALESCE(fecha_dispensacion::text,'-')||'@'||COALESCE(farmacia_id,'-')||'@'||updated_at FROM public.recetas_avanzadas WHERE id = ra),'-'),
    'entregas='||(SELECT count(*) FROM public.entregas WHERE receta_base_id = rid),
    'fallos='||(SELECT count(*) FROM private.delivery_autocreate_fallos WHERE receta_base_id = rid),
    'reveal='||(SELECT count(*) FROM private.reveal_log WHERE receta_base_id = rid),
    'confirm='||(SELECT count(*) FROM public.confirmaciones_receta WHERE receta_avanzada_id = ra));
  IF sig2 IS DISTINCT FROM sig_orig THEN r_rest := 'firma no vuelve al snapshot original'; END IF;
  UPDATE public.empresas_proveedoras SET estado = emp_est0 WHERE id = emp AND estado IS DISTINCT FROM emp_est0;
  IF (SELECT estado FROM public.empresas_proveedoras WHERE id = emp) IS DISTINCT FROM emp_est0 THEN
    r_rest := r_rest||' / estado de empresa no vuelve'; END IF;
  det := det||' ;; empresa del fixture|estado original '||COALESCE(emp_est0,'-')||'|'||CASE WHEN emp_est0 = 'activa' THEN 'ya activa' ELSE 'activada para el probe y restaurada' END||'|-|';
  det := det||' ;; restauracion|firma igual al snapshot|'||r_rest||'|-|';

  PERFORM set_config('probe.p842_det', det, false);
  PERFORM set_config('probe.p842', CASE WHEN (r_can = 'PR010 Receta cancelada: no se puede despachar') AND sig1 = sig0 AND r_act = 'OK' AND r_rest = 'OK'
    THEN 'OK (registrar_dispensacion_dirigida (receta_id): cancelada -> PR010, activa -> OK con efecto; restaurado)'
    ELSE 'ROJO (cancelada='||r_can||' | activa='||r_act||' '||COALESCE(eff,'-')||' | firma_cancelada='||(sig1 = sig0)||' | restauracion='||r_rest||')' END, false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
  PERFORM set_config('probe.p842', CASE WHEN SQLERRM LIKE 'fixture roto%' THEN 'ROJO ('||SQLERRM||')'
    ELSE 'FALLO ('||SQLSTATE||' '||SQLERRM||')' END, false);
END $$;
SELECT set_config('role','none', true);

-- ---------------- P843 revelar_items_receta ----------------
DO $$
DECLARE
  rid bigint; iid bigint; farm integer; nom text; emp uuid; ra uuid; tok text; ctok text; pac bigint; pac_uid uuid;
  cta uuid; c record; det text := ''; r_can text; r_act text; r_rest text := 'OK'; st text; msg text; j jsonb; v_n bigint;
  sig0 text; sig1 text; sig2 text; eff text;
  disp0 uuid[]; ent0 bigint[]; fal0 bigint[]; rev0 bigint[]; conf0 uuid[]; it0 record; stock0 jsonb; ra0 record; est0 text; sig_orig text; mod_orig text; emp_est0 text;
BEGIN
  SELECT ri.id, ri.receta_id, ri.farmacia_id, ri.nombre_medicamento, f.empresa_id, ra_.id, ra_.dispatch_token, ra_.confirmacion_token, r.paciente_id
    INTO iid, rid, farm, nom, emp, ra, tok, ctok, pac
    FROM public.receta_items ri JOIN public.farmacias f ON f.id = ri.farmacia_id
    JOIN public.recetas r ON r.id = ri.receta_id JOIN public.recetas_avanzadas ra_ ON ra_.receta_base_id = r.id
   WHERE ri.dispensado = false AND ra_.dispatch_token_expira_at > now() AND ra_.confirmacion_token_expira_at > now()
     AND r.estado = 'activa'
   ORDER BY ri.receta_id, ri.id LIMIT 1;
  IF iid IS NULL THEN RAISE EXCEPTION 'fixture roto: item ruteado de receta activa con token vigente'; END IF;
  -- el gate de estado de empresa (mig 322) exige empresa 'activa': si la dejo en otro estado un probe anterior
  -- del harness, se activa aca como fixture y se restaura al final (verificado).
  SELECT e.estado INTO emp_est0 FROM public.empresas_proveedoras e WHERE e.id = emp;
  IF emp_est0 IS DISTINCT FROM 'activa' THEN UPDATE public.empresas_proveedoras SET estado = 'activa' WHERE id = emp; END IF;
  FOR c IN SELECT cp.id FROM public.cuentas_proveedor cp WHERE cp.empresa_id = emp AND cp.activo IS TRUE ORDER BY cp.id LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub',c.id::text,'role','authenticated')::text, true);
    IF COALESCE(private.tiene_permiso('recetas_dispensar'), false) AND COALESCE(private.tiene_permiso('entregas_gestionar'), false)
       AND COALESCE(private.sucursal_visible(farm), false) THEN cta := c.id; EXIT; END IF;
  END LOOP;
  PERFORM set_config('request.jwt.claims','',true);
  IF cta IS NULL THEN RAISE EXCEPTION 'fixture roto: cuenta de farmacia con dispensar + entregas + sucursal visible'; END IF;
  SELECT p.auth_user_id INTO pac_uid FROM public.pacientes p WHERE p.id = pac;
  -- snapshot
  SELECT r.estado INTO est0 FROM public.recetas r WHERE r.id = rid;
  SELECT array_agg(id) INTO disp0 FROM public.dispensaciones WHERE receta_avanzada_id = ra;
  SELECT array_agg(id) INTO ent0 FROM public.entregas WHERE receta_base_id = rid;
  SELECT array_agg(id) INTO fal0 FROM private.delivery_autocreate_fallos WHERE receta_base_id = rid;
  SELECT array_agg(id) INTO rev0 FROM private.reveal_log WHERE receta_base_id = rid;
  SELECT array_agg(id) INTO conf0 FROM public.confirmaciones_receta WHERE receta_avanzada_id = ra;
  SELECT dispensado, dispensado_at, modalidad INTO it0 FROM public.receta_items WHERE id = iid;
  SELECT jsonb_agg(jsonb_build_object('id', id, 's', stock_actual, 'u', updated_at)) INTO stock0
    FROM public.farmacia_medicamentos WHERE farmacia_id = farm AND nombre_medicamento = nom;
  SELECT estado_dispensacion, fecha_dispensacion, farmacia_id, updated_at INTO ra0 FROM public.recetas_avanzadas WHERE id = ra;
  sig0 := concat_ws(' | ',
    'rec='||COALESCE((SELECT estado FROM public.recetas WHERE id = rid),'-'),
    'disp='||(SELECT count(*) FROM public.dispensaciones WHERE receta_avanzada_id = ra),
    'item='||COALESCE((SELECT dispensado::text||'@'||COALESCE(dispensado_at::text,'-')||'@'||COALESCE(modalidad,'-') FROM public.receta_items WHERE id = iid),'-'),
    'stock='||COALESCE((SELECT string_agg(id::text||':'||stock_actual||'@'||updated_at, ',' ORDER BY id) FROM public.farmacia_medicamentos WHERE farmacia_id = farm AND nombre_medicamento = nom),'-'),
    'ra='||COALESCE((SELECT COALESCE(estado_dispensacion,'-')||'@'||COALESCE(fecha_dispensacion::text,'-')||'@'||COALESCE(farmacia_id,'-')||'@'||updated_at FROM public.recetas_avanzadas WHERE id = ra),'-'),
    'entregas='||(SELECT count(*) FROM public.entregas WHERE receta_base_id = rid),
    'fallos='||(SELECT count(*) FROM private.delivery_autocreate_fallos WHERE receta_base_id = rid),
    'reveal='||(SELECT count(*) FROM private.reveal_log WHERE receta_base_id = rid),
    'confirm='||(SELECT count(*) FROM public.confirmaciones_receta WHERE receta_avanzada_id = ra));
  sig_orig := sig0; mod_orig := it0.modalidad;

  -- A) receta CANCELADA
  UPDATE public.recetas SET estado = 'cancelada' WHERE id = rid;
  st := '00000'; msg := ''; j := NULL;
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',cta::text,'role','authenticated')::text, true); PERFORM set_config('role','authenticated',true);
    j := public.revelar_items_receta(rid, 'bandeja');
    PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
    st := SQLSTATE; msg := SQLERRM; END;
  r_can := CASE WHEN st = '00000' THEN 'OK' ELSE 'ERR' END;
  r_can := st||' '||msg;
  UPDATE public.recetas SET estado = est0 WHERE id = rid;
  sig1 := concat_ws(' | ',
    'rec='||COALESCE((SELECT estado FROM public.recetas WHERE id = rid),'-'),
    'disp='||(SELECT count(*) FROM public.dispensaciones WHERE receta_avanzada_id = ra),
    'item='||COALESCE((SELECT dispensado::text||'@'||COALESCE(dispensado_at::text,'-')||'@'||COALESCE(modalidad,'-') FROM public.receta_items WHERE id = iid),'-'),
    'stock='||COALESCE((SELECT string_agg(id::text||':'||stock_actual||'@'||updated_at, ',' ORDER BY id) FROM public.farmacia_medicamentos WHERE farmacia_id = farm AND nombre_medicamento = nom),'-'),
    'ra='||COALESCE((SELECT COALESCE(estado_dispensacion,'-')||'@'||COALESCE(fecha_dispensacion::text,'-')||'@'||COALESCE(farmacia_id,'-')||'@'||updated_at FROM public.recetas_avanzadas WHERE id = ra),'-'),
    'entregas='||(SELECT count(*) FROM public.entregas WHERE receta_base_id = rid),
    'fallos='||(SELECT count(*) FROM private.delivery_autocreate_fallos WHERE receta_base_id = rid),
    'reveal='||(SELECT count(*) FROM private.reveal_log WHERE receta_base_id = rid),
    'confirm='||(SELECT count(*) FROM public.confirmaciones_receta WHERE receta_avanzada_id = ra));
  DELETE FROM public.dispensaciones WHERE receta_avanzada_id = ra AND NOT (id = ANY(COALESCE(disp0, '{}')));
  DELETE FROM public.entregas WHERE receta_base_id = rid AND NOT (id = ANY(COALESCE(ent0, '{}')));
  DELETE FROM private.delivery_autocreate_fallos WHERE receta_base_id = rid AND NOT (id = ANY(COALESCE(fal0, '{}')));
  DELETE FROM private.reveal_log WHERE receta_base_id = rid AND NOT (id = ANY(COALESCE(rev0, '{}')));
  DELETE FROM public.confirmaciones_receta WHERE receta_avanzada_id = ra AND NOT (id = ANY(COALESCE(conf0, '{}')));
  UPDATE public.receta_items SET dispensado = it0.dispensado, dispensado_at = it0.dispensado_at, modalidad = it0.modalidad WHERE id = iid;
  UPDATE public.farmacia_medicamentos fm SET stock_actual = x.s, updated_at = x.u
    FROM jsonb_to_recordset(COALESCE(stock0, '[]')) AS x(id uuid, s integer, u timestamptz) WHERE fm.id = x.id;
  UPDATE public.recetas_avanzadas SET estado_dispensacion = ra0.estado_dispensacion, fecha_dispensacion = ra0.fecha_dispensacion,
         farmacia_id = ra0.farmacia_id, updated_at = ra0.updated_at WHERE id = ra;
  UPDATE public.recetas SET estado = est0 WHERE id = rid;

  det := 'cancelada|PR010 Receta cancelada: no se puede despachar|'||CASE WHEN r_can = 'PR010 Receta cancelada: no se puede despachar' THEN 'OK' ELSE 'ROJO' END||'|'||st||'|'||msg
         ||' ;; cancelada: sin filas ni cambios|firma igual al snapshot|'||CASE WHEN sig1 = sig0 THEN 'igual' ELSE 'DISTINTA' END||'|-|';
  -- B) receta ACTIVA -> OK, efecto verificado y restaurado
  st := '00000'; msg := ''; j := NULL;
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',cta::text,'role','authenticated')::text, true); PERFORM set_config('role','authenticated',true);
    j := public.revelar_items_receta(rid, 'bandeja');
    PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
    st := SQLSTATE; msg := SQLERRM; END;
  r_act := CASE WHEN st = '00000' THEN 'OK' ELSE 'ERR' END;
  eff := 'items_con_el_fixture='||EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(j,'[]')) e WHERE (e->>'item_id')::bigint = iid)||' reveal_log+'||((SELECT count(*) FROM private.reveal_log WHERE receta_base_id = rid) - COALESCE(array_length(rev0,1),0));
  det := det||' ;; activa|OK|'||r_act||' '||COALESCE(eff,'-')||'|'||st||'|'||msg;
  IF r_act = 'OK' AND NOT (EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(j,'[]')) e WHERE (e->>'item_id')::bigint = iid) AND (SELECT count(*) FROM private.reveal_log WHERE receta_base_id = rid) = COALESCE(array_length(rev0,1),0) + 1) THEN r_act := 'OK-SIN-EFECTO'; END IF;
  DELETE FROM public.dispensaciones WHERE receta_avanzada_id = ra AND NOT (id = ANY(COALESCE(disp0, '{}')));
  DELETE FROM public.entregas WHERE receta_base_id = rid AND NOT (id = ANY(COALESCE(ent0, '{}')));
  DELETE FROM private.delivery_autocreate_fallos WHERE receta_base_id = rid AND NOT (id = ANY(COALESCE(fal0, '{}')));
  DELETE FROM private.reveal_log WHERE receta_base_id = rid AND NOT (id = ANY(COALESCE(rev0, '{}')));
  DELETE FROM public.confirmaciones_receta WHERE receta_avanzada_id = ra AND NOT (id = ANY(COALESCE(conf0, '{}')));
  UPDATE public.receta_items SET dispensado = it0.dispensado, dispensado_at = it0.dispensado_at, modalidad = it0.modalidad WHERE id = iid;
  UPDATE public.farmacia_medicamentos fm SET stock_actual = x.s, updated_at = x.u
    FROM jsonb_to_recordset(COALESCE(stock0, '[]')) AS x(id uuid, s integer, u timestamptz) WHERE fm.id = x.id;
  UPDATE public.recetas_avanzadas SET estado_dispensacion = ra0.estado_dispensacion, fecha_dispensacion = ra0.fecha_dispensacion,
         farmacia_id = ra0.farmacia_id, updated_at = ra0.updated_at WHERE id = ra;
  UPDATE public.recetas SET estado = est0 WHERE id = rid;

  sig2 := concat_ws(' | ',
    'rec='||COALESCE((SELECT estado FROM public.recetas WHERE id = rid),'-'),
    'disp='||(SELECT count(*) FROM public.dispensaciones WHERE receta_avanzada_id = ra),
    'item='||COALESCE((SELECT dispensado::text||'@'||COALESCE(dispensado_at::text,'-')||'@'||COALESCE(modalidad,'-') FROM public.receta_items WHERE id = iid),'-'),
    'stock='||COALESCE((SELECT string_agg(id::text||':'||stock_actual||'@'||updated_at, ',' ORDER BY id) FROM public.farmacia_medicamentos WHERE farmacia_id = farm AND nombre_medicamento = nom),'-'),
    'ra='||COALESCE((SELECT COALESCE(estado_dispensacion,'-')||'@'||COALESCE(fecha_dispensacion::text,'-')||'@'||COALESCE(farmacia_id,'-')||'@'||updated_at FROM public.recetas_avanzadas WHERE id = ra),'-'),
    'entregas='||(SELECT count(*) FROM public.entregas WHERE receta_base_id = rid),
    'fallos='||(SELECT count(*) FROM private.delivery_autocreate_fallos WHERE receta_base_id = rid),
    'reveal='||(SELECT count(*) FROM private.reveal_log WHERE receta_base_id = rid),
    'confirm='||(SELECT count(*) FROM public.confirmaciones_receta WHERE receta_avanzada_id = ra));
  IF sig2 IS DISTINCT FROM sig_orig THEN r_rest := 'firma no vuelve al snapshot original'; END IF;
  UPDATE public.empresas_proveedoras SET estado = emp_est0 WHERE id = emp AND estado IS DISTINCT FROM emp_est0;
  IF (SELECT estado FROM public.empresas_proveedoras WHERE id = emp) IS DISTINCT FROM emp_est0 THEN
    r_rest := r_rest||' / estado de empresa no vuelve'; END IF;
  det := det||' ;; empresa del fixture|estado original '||COALESCE(emp_est0,'-')||'|'||CASE WHEN emp_est0 = 'activa' THEN 'ya activa' ELSE 'activada para el probe y restaurada' END||'|-|';
  det := det||' ;; restauracion|firma igual al snapshot|'||r_rest||'|-|';

  PERFORM set_config('probe.p843_det', det, false);
  PERFORM set_config('probe.p843', CASE WHEN (r_can = 'PR010 Receta cancelada: no se puede despachar') AND sig1 = sig0 AND r_act = 'OK' AND r_rest = 'OK'
    THEN 'OK (revelar_items_receta: cancelada -> PR010, activa -> OK con efecto; restaurado)'
    ELSE 'ROJO (cancelada='||r_can||' | activa='||r_act||' '||COALESCE(eff,'-')||' | firma_cancelada='||(sig1 = sig0)||' | restauracion='||r_rest||')' END, false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
  PERFORM set_config('probe.p843', CASE WHEN SQLERRM LIKE 'fixture roto%' THEN 'ROJO ('||SQLERRM||')'
    ELSE 'FALLO ('||SQLSTATE||' '||SQLERRM||')' END, false);
END $$;
SELECT set_config('role','none', true);

-- ---------------- P844 crear_entrega ----------------
DO $$
DECLARE
  rid bigint; iid bigint; farm integer; nom text; emp uuid; ra uuid; tok text; ctok text; pac bigint; pac_uid uuid;
  cta uuid; c record; det text := ''; r_can text; r_act text; r_rest text := 'OK'; st text; msg text; j jsonb; v_n bigint;
  sig0 text; sig1 text; sig2 text; eff text;
  disp0 uuid[]; ent0 bigint[]; fal0 bigint[]; rev0 bigint[]; conf0 uuid[]; it0 record; stock0 jsonb; ra0 record; est0 text; sig_orig text; mod_orig text; emp_est0 text;
BEGIN
  SELECT ri.id, ri.receta_id, ri.farmacia_id, ri.nombre_medicamento, f.empresa_id, ra_.id, ra_.dispatch_token, ra_.confirmacion_token, r.paciente_id
    INTO iid, rid, farm, nom, emp, ra, tok, ctok, pac
    FROM public.receta_items ri JOIN public.farmacias f ON f.id = ri.farmacia_id
    JOIN public.recetas r ON r.id = ri.receta_id JOIN public.recetas_avanzadas ra_ ON ra_.receta_base_id = r.id
   WHERE ri.dispensado = false AND ra_.dispatch_token_expira_at > now() AND ra_.confirmacion_token_expira_at > now()
     AND r.estado = 'activa'
   ORDER BY ri.receta_id, ri.id LIMIT 1;
  IF iid IS NULL THEN RAISE EXCEPTION 'fixture roto: item ruteado de receta activa con token vigente'; END IF;
  -- el gate de estado de empresa (mig 322) exige empresa 'activa': si la dejo en otro estado un probe anterior
  -- del harness, se activa aca como fixture y se restaura al final (verificado).
  SELECT e.estado INTO emp_est0 FROM public.empresas_proveedoras e WHERE e.id = emp;
  IF emp_est0 IS DISTINCT FROM 'activa' THEN UPDATE public.empresas_proveedoras SET estado = 'activa' WHERE id = emp; END IF;
  FOR c IN SELECT cp.id FROM public.cuentas_proveedor cp WHERE cp.empresa_id = emp AND cp.activo IS TRUE ORDER BY cp.id LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub',c.id::text,'role','authenticated')::text, true);
    IF COALESCE(private.tiene_permiso('recetas_dispensar'), false) AND COALESCE(private.tiene_permiso('entregas_gestionar'), false)
       AND COALESCE(private.sucursal_visible(farm), false) THEN cta := c.id; EXIT; END IF;
  END LOOP;
  PERFORM set_config('request.jwt.claims','',true);
  IF cta IS NULL THEN RAISE EXCEPTION 'fixture roto: cuenta de farmacia con dispensar + entregas + sucursal visible'; END IF;
  SELECT p.auth_user_id INTO pac_uid FROM public.pacientes p WHERE p.id = pac;
  -- snapshot
  SELECT r.estado INTO est0 FROM public.recetas r WHERE r.id = rid;
  SELECT array_agg(id) INTO disp0 FROM public.dispensaciones WHERE receta_avanzada_id = ra;
  SELECT array_agg(id) INTO ent0 FROM public.entregas WHERE receta_base_id = rid;
  SELECT array_agg(id) INTO fal0 FROM private.delivery_autocreate_fallos WHERE receta_base_id = rid;
  SELECT array_agg(id) INTO rev0 FROM private.reveal_log WHERE receta_base_id = rid;
  SELECT array_agg(id) INTO conf0 FROM public.confirmaciones_receta WHERE receta_avanzada_id = ra;
  SELECT dispensado, dispensado_at, modalidad INTO it0 FROM public.receta_items WHERE id = iid;
  SELECT jsonb_agg(jsonb_build_object('id', id, 's', stock_actual, 'u', updated_at)) INTO stock0
    FROM public.farmacia_medicamentos WHERE farmacia_id = farm AND nombre_medicamento = nom;
  SELECT estado_dispensacion, fecha_dispensacion, farmacia_id, updated_at INTO ra0 FROM public.recetas_avanzadas WHERE id = ra;
  sig0 := concat_ws(' | ',
    'rec='||COALESCE((SELECT estado FROM public.recetas WHERE id = rid),'-'),
    'disp='||(SELECT count(*) FROM public.dispensaciones WHERE receta_avanzada_id = ra),
    'item='||COALESCE((SELECT dispensado::text||'@'||COALESCE(dispensado_at::text,'-')||'@'||COALESCE(modalidad,'-') FROM public.receta_items WHERE id = iid),'-'),
    'stock='||COALESCE((SELECT string_agg(id::text||':'||stock_actual||'@'||updated_at, ',' ORDER BY id) FROM public.farmacia_medicamentos WHERE farmacia_id = farm AND nombre_medicamento = nom),'-'),
    'ra='||COALESCE((SELECT COALESCE(estado_dispensacion,'-')||'@'||COALESCE(fecha_dispensacion::text,'-')||'@'||COALESCE(farmacia_id,'-')||'@'||updated_at FROM public.recetas_avanzadas WHERE id = ra),'-'),
    'entregas='||(SELECT count(*) FROM public.entregas WHERE receta_base_id = rid),
    'fallos='||(SELECT count(*) FROM private.delivery_autocreate_fallos WHERE receta_base_id = rid),
    'reveal='||(SELECT count(*) FROM private.reveal_log WHERE receta_base_id = rid),
    'confirm='||(SELECT count(*) FROM public.confirmaciones_receta WHERE receta_avanzada_id = ra));
  sig_orig := sig0; mod_orig := it0.modalidad;
  UPDATE public.receta_items SET modalidad = 'delivery' WHERE receta_id = rid AND farmacia_id = farm;  -- fixture: grupo delivery
  SELECT dispensado, dispensado_at, modalidad INTO it0 FROM public.receta_items WHERE id = iid;
  sig0 := concat_ws(' | ',
    'rec='||COALESCE((SELECT estado FROM public.recetas WHERE id = rid),'-'),
    'disp='||(SELECT count(*) FROM public.dispensaciones WHERE receta_avanzada_id = ra),
    'item='||COALESCE((SELECT dispensado::text||'@'||COALESCE(dispensado_at::text,'-')||'@'||COALESCE(modalidad,'-') FROM public.receta_items WHERE id = iid),'-'),
    'stock='||COALESCE((SELECT string_agg(id::text||':'||stock_actual||'@'||updated_at, ',' ORDER BY id) FROM public.farmacia_medicamentos WHERE farmacia_id = farm AND nombre_medicamento = nom),'-'),
    'ra='||COALESCE((SELECT COALESCE(estado_dispensacion,'-')||'@'||COALESCE(fecha_dispensacion::text,'-')||'@'||COALESCE(farmacia_id,'-')||'@'||updated_at FROM public.recetas_avanzadas WHERE id = ra),'-'),
    'entregas='||(SELECT count(*) FROM public.entregas WHERE receta_base_id = rid),
    'fallos='||(SELECT count(*) FROM private.delivery_autocreate_fallos WHERE receta_base_id = rid),
    'reveal='||(SELECT count(*) FROM private.reveal_log WHERE receta_base_id = rid),
    'confirm='||(SELECT count(*) FROM public.confirmaciones_receta WHERE receta_avanzada_id = ra));
  -- A) receta CANCELADA
  UPDATE public.recetas SET estado = 'cancelada' WHERE id = rid;
  st := '00000'; msg := ''; j := NULL;
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',cta::text,'role','authenticated')::text, true); PERFORM set_config('role','authenticated',true);
    j := public.crear_entrega(rid, farm);
    PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
    st := SQLSTATE; msg := SQLERRM; END;
  r_can := CASE WHEN st = '00000' THEN 'OK' ELSE 'ERR' END;
  r_can := st||' '||msg;
  UPDATE public.recetas SET estado = est0 WHERE id = rid;
  sig1 := concat_ws(' | ',
    'rec='||COALESCE((SELECT estado FROM public.recetas WHERE id = rid),'-'),
    'disp='||(SELECT count(*) FROM public.dispensaciones WHERE receta_avanzada_id = ra),
    'item='||COALESCE((SELECT dispensado::text||'@'||COALESCE(dispensado_at::text,'-')||'@'||COALESCE(modalidad,'-') FROM public.receta_items WHERE id = iid),'-'),
    'stock='||COALESCE((SELECT string_agg(id::text||':'||stock_actual||'@'||updated_at, ',' ORDER BY id) FROM public.farmacia_medicamentos WHERE farmacia_id = farm AND nombre_medicamento = nom),'-'),
    'ra='||COALESCE((SELECT COALESCE(estado_dispensacion,'-')||'@'||COALESCE(fecha_dispensacion::text,'-')||'@'||COALESCE(farmacia_id,'-')||'@'||updated_at FROM public.recetas_avanzadas WHERE id = ra),'-'),
    'entregas='||(SELECT count(*) FROM public.entregas WHERE receta_base_id = rid),
    'fallos='||(SELECT count(*) FROM private.delivery_autocreate_fallos WHERE receta_base_id = rid),
    'reveal='||(SELECT count(*) FROM private.reveal_log WHERE receta_base_id = rid),
    'confirm='||(SELECT count(*) FROM public.confirmaciones_receta WHERE receta_avanzada_id = ra));
  DELETE FROM public.dispensaciones WHERE receta_avanzada_id = ra AND NOT (id = ANY(COALESCE(disp0, '{}')));
  DELETE FROM public.entregas WHERE receta_base_id = rid AND NOT (id = ANY(COALESCE(ent0, '{}')));
  DELETE FROM private.delivery_autocreate_fallos WHERE receta_base_id = rid AND NOT (id = ANY(COALESCE(fal0, '{}')));
  DELETE FROM private.reveal_log WHERE receta_base_id = rid AND NOT (id = ANY(COALESCE(rev0, '{}')));
  DELETE FROM public.confirmaciones_receta WHERE receta_avanzada_id = ra AND NOT (id = ANY(COALESCE(conf0, '{}')));
  UPDATE public.receta_items SET dispensado = it0.dispensado, dispensado_at = it0.dispensado_at, modalidad = it0.modalidad WHERE id = iid;
  UPDATE public.farmacia_medicamentos fm SET stock_actual = x.s, updated_at = x.u
    FROM jsonb_to_recordset(COALESCE(stock0, '[]')) AS x(id uuid, s integer, u timestamptz) WHERE fm.id = x.id;
  UPDATE public.recetas_avanzadas SET estado_dispensacion = ra0.estado_dispensacion, fecha_dispensacion = ra0.fecha_dispensacion,
         farmacia_id = ra0.farmacia_id, updated_at = ra0.updated_at WHERE id = ra;
  UPDATE public.recetas SET estado = est0 WHERE id = rid;

  det := 'cancelada|PR010 Receta cancelada: no se puede despachar|'||CASE WHEN r_can = 'PR010 Receta cancelada: no se puede despachar' THEN 'OK' ELSE 'ROJO' END||'|'||st||'|'||msg
         ||' ;; cancelada: sin filas ni cambios|firma igual al snapshot|'||CASE WHEN sig1 = sig0 THEN 'igual' ELSE 'DISTINTA' END||'|-|';
  -- B) receta ACTIVA -> OK, efecto verificado y restaurado
  st := '00000'; msg := ''; j := NULL;
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',cta::text,'role','authenticated')::text, true); PERFORM set_config('role','authenticated',true);
    j := public.crear_entrega(rid, farm);
    PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
    st := SQLSTATE; msg := SQLERRM; END;
  r_act := CASE WHEN st = '00000' THEN 'OK' ELSE 'ERR' END;
  eff := 'entrega_id='||COALESCE(j->>'entrega_id','-')||' entregas+'||((SELECT count(*) FROM public.entregas WHERE receta_base_id = rid) - COALESCE(array_length(ent0,1),0));
  det := det||' ;; activa|OK|'||r_act||' '||COALESCE(eff,'-')||'|'||st||'|'||msg;
  IF r_act = 'OK' AND NOT ((j->>'entrega_id') IS NOT NULL AND (SELECT count(*) FROM public.entregas WHERE receta_base_id = rid) = COALESCE(array_length(ent0,1),0) + 1) THEN r_act := 'OK-SIN-EFECTO'; END IF;
  DELETE FROM public.dispensaciones WHERE receta_avanzada_id = ra AND NOT (id = ANY(COALESCE(disp0, '{}')));
  DELETE FROM public.entregas WHERE receta_base_id = rid AND NOT (id = ANY(COALESCE(ent0, '{}')));
  DELETE FROM private.delivery_autocreate_fallos WHERE receta_base_id = rid AND NOT (id = ANY(COALESCE(fal0, '{}')));
  DELETE FROM private.reveal_log WHERE receta_base_id = rid AND NOT (id = ANY(COALESCE(rev0, '{}')));
  DELETE FROM public.confirmaciones_receta WHERE receta_avanzada_id = ra AND NOT (id = ANY(COALESCE(conf0, '{}')));
  UPDATE public.receta_items SET dispensado = it0.dispensado, dispensado_at = it0.dispensado_at, modalidad = it0.modalidad WHERE id = iid;
  UPDATE public.farmacia_medicamentos fm SET stock_actual = x.s, updated_at = x.u
    FROM jsonb_to_recordset(COALESCE(stock0, '[]')) AS x(id uuid, s integer, u timestamptz) WHERE fm.id = x.id;
  UPDATE public.recetas_avanzadas SET estado_dispensacion = ra0.estado_dispensacion, fecha_dispensacion = ra0.fecha_dispensacion,
         farmacia_id = ra0.farmacia_id, updated_at = ra0.updated_at WHERE id = ra;
  UPDATE public.recetas SET estado = est0 WHERE id = rid;
  UPDATE public.receta_items SET modalidad = mod_orig WHERE receta_id = rid AND farmacia_id = farm;
  sig2 := concat_ws(' | ',
    'rec='||COALESCE((SELECT estado FROM public.recetas WHERE id = rid),'-'),
    'disp='||(SELECT count(*) FROM public.dispensaciones WHERE receta_avanzada_id = ra),
    'item='||COALESCE((SELECT dispensado::text||'@'||COALESCE(dispensado_at::text,'-')||'@'||COALESCE(modalidad,'-') FROM public.receta_items WHERE id = iid),'-'),
    'stock='||COALESCE((SELECT string_agg(id::text||':'||stock_actual||'@'||updated_at, ',' ORDER BY id) FROM public.farmacia_medicamentos WHERE farmacia_id = farm AND nombre_medicamento = nom),'-'),
    'ra='||COALESCE((SELECT COALESCE(estado_dispensacion,'-')||'@'||COALESCE(fecha_dispensacion::text,'-')||'@'||COALESCE(farmacia_id,'-')||'@'||updated_at FROM public.recetas_avanzadas WHERE id = ra),'-'),
    'entregas='||(SELECT count(*) FROM public.entregas WHERE receta_base_id = rid),
    'fallos='||(SELECT count(*) FROM private.delivery_autocreate_fallos WHERE receta_base_id = rid),
    'reveal='||(SELECT count(*) FROM private.reveal_log WHERE receta_base_id = rid),
    'confirm='||(SELECT count(*) FROM public.confirmaciones_receta WHERE receta_avanzada_id = ra));
  IF sig2 IS DISTINCT FROM sig_orig THEN r_rest := 'firma no vuelve al snapshot original'; END IF;
  UPDATE public.empresas_proveedoras SET estado = emp_est0 WHERE id = emp AND estado IS DISTINCT FROM emp_est0;
  IF (SELECT estado FROM public.empresas_proveedoras WHERE id = emp) IS DISTINCT FROM emp_est0 THEN
    r_rest := r_rest||' / estado de empresa no vuelve'; END IF;
  det := det||' ;; empresa del fixture|estado original '||COALESCE(emp_est0,'-')||'|'||CASE WHEN emp_est0 = 'activa' THEN 'ya activa' ELSE 'activada para el probe y restaurada' END||'|-|';
  det := det||' ;; restauracion|firma igual al snapshot|'||r_rest||'|-|';

  PERFORM set_config('probe.p844_det', det, false);
  PERFORM set_config('probe.p844', CASE WHEN (r_can = 'PR010 Receta cancelada: no se puede despachar') AND sig1 = sig0 AND r_act = 'OK' AND r_rest = 'OK'
    THEN 'OK (crear_entrega: cancelada -> PR010, activa -> OK con efecto; restaurado)'
    ELSE 'ROJO (cancelada='||r_can||' | activa='||r_act||' '||COALESCE(eff,'-')||' | firma_cancelada='||(sig1 = sig0)||' | restauracion='||r_rest||')' END, false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
  PERFORM set_config('probe.p844', CASE WHEN SQLERRM LIKE 'fixture roto%' THEN 'ROJO ('||SQLERRM||')'
    ELSE 'FALLO ('||SQLSTATE||' '||SQLERRM||')' END, false);
END $$;
SELECT set_config('role','none', true);

-- ---------------- P845 fijar_modalidad_grupo (paciente) ----------------
DO $$
DECLARE
  rid bigint; iid bigint; farm integer; nom text; emp uuid; ra uuid; tok text; ctok text; pac bigint; pac_uid uuid;
  cta uuid; c record; det text := ''; r_can text; r_act text; r_rest text := 'OK'; st text; msg text; j jsonb; v_n bigint;
  sig0 text; sig1 text; sig2 text; eff text;
  disp0 uuid[]; ent0 bigint[]; fal0 bigint[]; rev0 bigint[]; conf0 uuid[]; it0 record; stock0 jsonb; ra0 record; est0 text; sig_orig text; mod_orig text; emp_est0 text;
BEGIN
  SELECT ri.id, ri.receta_id, ri.farmacia_id, ri.nombre_medicamento, f.empresa_id, ra_.id, ra_.dispatch_token, ra_.confirmacion_token, r.paciente_id
    INTO iid, rid, farm, nom, emp, ra, tok, ctok, pac
    FROM public.receta_items ri JOIN public.farmacias f ON f.id = ri.farmacia_id
    JOIN public.recetas r ON r.id = ri.receta_id JOIN public.recetas_avanzadas ra_ ON ra_.receta_base_id = r.id
   WHERE ri.dispensado = false AND ra_.dispatch_token_expira_at > now() AND ra_.confirmacion_token_expira_at > now()
     AND r.estado = 'activa'
   ORDER BY ri.receta_id, ri.id LIMIT 1;
  IF iid IS NULL THEN RAISE EXCEPTION 'fixture roto: item ruteado de receta activa con token vigente'; END IF;
  -- el gate de estado de empresa (mig 322) exige empresa 'activa': si la dejo en otro estado un probe anterior
  -- del harness, se activa aca como fixture y se restaura al final (verificado).
  SELECT e.estado INTO emp_est0 FROM public.empresas_proveedoras e WHERE e.id = emp;
  IF emp_est0 IS DISTINCT FROM 'activa' THEN UPDATE public.empresas_proveedoras SET estado = 'activa' WHERE id = emp; END IF;
  FOR c IN SELECT cp.id FROM public.cuentas_proveedor cp WHERE cp.empresa_id = emp AND cp.activo IS TRUE ORDER BY cp.id LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub',c.id::text,'role','authenticated')::text, true);
    IF COALESCE(private.tiene_permiso('recetas_dispensar'), false) AND COALESCE(private.tiene_permiso('entregas_gestionar'), false)
       AND COALESCE(private.sucursal_visible(farm), false) THEN cta := c.id; EXIT; END IF;
  END LOOP;
  PERFORM set_config('request.jwt.claims','',true);
  IF cta IS NULL THEN RAISE EXCEPTION 'fixture roto: cuenta de farmacia con dispensar + entregas + sucursal visible'; END IF;
  SELECT p.auth_user_id INTO pac_uid FROM public.pacientes p WHERE p.id = pac;
  -- snapshot
  SELECT r.estado INTO est0 FROM public.recetas r WHERE r.id = rid;
  SELECT array_agg(id) INTO disp0 FROM public.dispensaciones WHERE receta_avanzada_id = ra;
  SELECT array_agg(id) INTO ent0 FROM public.entregas WHERE receta_base_id = rid;
  SELECT array_agg(id) INTO fal0 FROM private.delivery_autocreate_fallos WHERE receta_base_id = rid;
  SELECT array_agg(id) INTO rev0 FROM private.reveal_log WHERE receta_base_id = rid;
  SELECT array_agg(id) INTO conf0 FROM public.confirmaciones_receta WHERE receta_avanzada_id = ra;
  SELECT dispensado, dispensado_at, modalidad INTO it0 FROM public.receta_items WHERE id = iid;
  SELECT jsonb_agg(jsonb_build_object('id', id, 's', stock_actual, 'u', updated_at)) INTO stock0
    FROM public.farmacia_medicamentos WHERE farmacia_id = farm AND nombre_medicamento = nom;
  SELECT estado_dispensacion, fecha_dispensacion, farmacia_id, updated_at INTO ra0 FROM public.recetas_avanzadas WHERE id = ra;
  sig0 := concat_ws(' | ',
    'rec='||COALESCE((SELECT estado FROM public.recetas WHERE id = rid),'-'),
    'disp='||(SELECT count(*) FROM public.dispensaciones WHERE receta_avanzada_id = ra),
    'item='||COALESCE((SELECT dispensado::text||'@'||COALESCE(dispensado_at::text,'-')||'@'||COALESCE(modalidad,'-') FROM public.receta_items WHERE id = iid),'-'),
    'stock='||COALESCE((SELECT string_agg(id::text||':'||stock_actual||'@'||updated_at, ',' ORDER BY id) FROM public.farmacia_medicamentos WHERE farmacia_id = farm AND nombre_medicamento = nom),'-'),
    'ra='||COALESCE((SELECT COALESCE(estado_dispensacion,'-')||'@'||COALESCE(fecha_dispensacion::text,'-')||'@'||COALESCE(farmacia_id,'-')||'@'||updated_at FROM public.recetas_avanzadas WHERE id = ra),'-'),
    'entregas='||(SELECT count(*) FROM public.entregas WHERE receta_base_id = rid),
    'fallos='||(SELECT count(*) FROM private.delivery_autocreate_fallos WHERE receta_base_id = rid),
    'reveal='||(SELECT count(*) FROM private.reveal_log WHERE receta_base_id = rid),
    'confirm='||(SELECT count(*) FROM public.confirmaciones_receta WHERE receta_avanzada_id = ra));
  sig_orig := sig0; mod_orig := it0.modalidad;

  -- A) receta CANCELADA
  UPDATE public.recetas SET estado = 'cancelada' WHERE id = rid;
  st := '00000'; msg := ''; j := NULL;
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',pac_uid::text,'role','authenticated')::text, true); PERFORM set_config('role','authenticated',true);
    j := public.fijar_modalidad_grupo(rid, farm, CASE WHEN it0.modalidad = 'delivery' THEN 'pickup' ELSE 'delivery' END);
    PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
    st := SQLSTATE; msg := SQLERRM; END;
  r_can := CASE WHEN st = '00000' THEN 'OK' ELSE 'ERR' END;
  r_can := st||' '||msg;
  UPDATE public.recetas SET estado = est0 WHERE id = rid;
  sig1 := concat_ws(' | ',
    'rec='||COALESCE((SELECT estado FROM public.recetas WHERE id = rid),'-'),
    'disp='||(SELECT count(*) FROM public.dispensaciones WHERE receta_avanzada_id = ra),
    'item='||COALESCE((SELECT dispensado::text||'@'||COALESCE(dispensado_at::text,'-')||'@'||COALESCE(modalidad,'-') FROM public.receta_items WHERE id = iid),'-'),
    'stock='||COALESCE((SELECT string_agg(id::text||':'||stock_actual||'@'||updated_at, ',' ORDER BY id) FROM public.farmacia_medicamentos WHERE farmacia_id = farm AND nombre_medicamento = nom),'-'),
    'ra='||COALESCE((SELECT COALESCE(estado_dispensacion,'-')||'@'||COALESCE(fecha_dispensacion::text,'-')||'@'||COALESCE(farmacia_id,'-')||'@'||updated_at FROM public.recetas_avanzadas WHERE id = ra),'-'),
    'entregas='||(SELECT count(*) FROM public.entregas WHERE receta_base_id = rid),
    'fallos='||(SELECT count(*) FROM private.delivery_autocreate_fallos WHERE receta_base_id = rid),
    'reveal='||(SELECT count(*) FROM private.reveal_log WHERE receta_base_id = rid),
    'confirm='||(SELECT count(*) FROM public.confirmaciones_receta WHERE receta_avanzada_id = ra));
  DELETE FROM public.dispensaciones WHERE receta_avanzada_id = ra AND NOT (id = ANY(COALESCE(disp0, '{}')));
  DELETE FROM public.entregas WHERE receta_base_id = rid AND NOT (id = ANY(COALESCE(ent0, '{}')));
  DELETE FROM private.delivery_autocreate_fallos WHERE receta_base_id = rid AND NOT (id = ANY(COALESCE(fal0, '{}')));
  DELETE FROM private.reveal_log WHERE receta_base_id = rid AND NOT (id = ANY(COALESCE(rev0, '{}')));
  DELETE FROM public.confirmaciones_receta WHERE receta_avanzada_id = ra AND NOT (id = ANY(COALESCE(conf0, '{}')));
  UPDATE public.receta_items SET dispensado = it0.dispensado, dispensado_at = it0.dispensado_at, modalidad = it0.modalidad WHERE id = iid;
  UPDATE public.farmacia_medicamentos fm SET stock_actual = x.s, updated_at = x.u
    FROM jsonb_to_recordset(COALESCE(stock0, '[]')) AS x(id uuid, s integer, u timestamptz) WHERE fm.id = x.id;
  UPDATE public.recetas_avanzadas SET estado_dispensacion = ra0.estado_dispensacion, fecha_dispensacion = ra0.fecha_dispensacion,
         farmacia_id = ra0.farmacia_id, updated_at = ra0.updated_at WHERE id = ra;
  UPDATE public.recetas SET estado = est0 WHERE id = rid;

  det := 'cancelada|PR010 Receta cancelada: no se puede despachar|'||CASE WHEN r_can = 'PR010 Receta cancelada: no se puede despachar' THEN 'OK' ELSE 'ROJO' END||'|'||st||'|'||msg
         ||' ;; cancelada: sin filas ni cambios|firma igual al snapshot|'||CASE WHEN sig1 = sig0 THEN 'igual' ELSE 'DISTINTA' END||'|-|';
  -- B) receta ACTIVA -> OK, efecto verificado y restaurado
  st := '00000'; msg := ''; j := NULL;
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub',pac_uid::text,'role','authenticated')::text, true); PERFORM set_config('role','authenticated',true);
    j := public.fijar_modalidad_grupo(rid, farm, CASE WHEN it0.modalidad = 'delivery' THEN 'pickup' ELSE 'delivery' END);
    PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
    st := SQLSTATE; msg := SQLERRM; END;
  r_act := CASE WHEN st = '00000' THEN 'OK' ELSE 'ERR' END;
  eff := 'items='||COALESCE(j->>'items','-')||' modalidad='||COALESCE((SELECT modalidad FROM public.receta_items WHERE id = iid),'-');
  det := det||' ;; activa|OK|'||r_act||' '||COALESCE(eff,'-')||'|'||st||'|'||msg;
  IF r_act = 'OK' AND NOT ((j->>'items')::int >= 1 AND (SELECT modalidad FROM public.receta_items WHERE id = iid) IS DISTINCT FROM it0.modalidad) THEN r_act := 'OK-SIN-EFECTO'; END IF;
  DELETE FROM public.dispensaciones WHERE receta_avanzada_id = ra AND NOT (id = ANY(COALESCE(disp0, '{}')));
  DELETE FROM public.entregas WHERE receta_base_id = rid AND NOT (id = ANY(COALESCE(ent0, '{}')));
  DELETE FROM private.delivery_autocreate_fallos WHERE receta_base_id = rid AND NOT (id = ANY(COALESCE(fal0, '{}')));
  DELETE FROM private.reveal_log WHERE receta_base_id = rid AND NOT (id = ANY(COALESCE(rev0, '{}')));
  DELETE FROM public.confirmaciones_receta WHERE receta_avanzada_id = ra AND NOT (id = ANY(COALESCE(conf0, '{}')));
  UPDATE public.receta_items SET dispensado = it0.dispensado, dispensado_at = it0.dispensado_at, modalidad = it0.modalidad WHERE id = iid;
  UPDATE public.farmacia_medicamentos fm SET stock_actual = x.s, updated_at = x.u
    FROM jsonb_to_recordset(COALESCE(stock0, '[]')) AS x(id uuid, s integer, u timestamptz) WHERE fm.id = x.id;
  UPDATE public.recetas_avanzadas SET estado_dispensacion = ra0.estado_dispensacion, fecha_dispensacion = ra0.fecha_dispensacion,
         farmacia_id = ra0.farmacia_id, updated_at = ra0.updated_at WHERE id = ra;
  UPDATE public.recetas SET estado = est0 WHERE id = rid;

  sig2 := concat_ws(' | ',
    'rec='||COALESCE((SELECT estado FROM public.recetas WHERE id = rid),'-'),
    'disp='||(SELECT count(*) FROM public.dispensaciones WHERE receta_avanzada_id = ra),
    'item='||COALESCE((SELECT dispensado::text||'@'||COALESCE(dispensado_at::text,'-')||'@'||COALESCE(modalidad,'-') FROM public.receta_items WHERE id = iid),'-'),
    'stock='||COALESCE((SELECT string_agg(id::text||':'||stock_actual||'@'||updated_at, ',' ORDER BY id) FROM public.farmacia_medicamentos WHERE farmacia_id = farm AND nombre_medicamento = nom),'-'),
    'ra='||COALESCE((SELECT COALESCE(estado_dispensacion,'-')||'@'||COALESCE(fecha_dispensacion::text,'-')||'@'||COALESCE(farmacia_id,'-')||'@'||updated_at FROM public.recetas_avanzadas WHERE id = ra),'-'),
    'entregas='||(SELECT count(*) FROM public.entregas WHERE receta_base_id = rid),
    'fallos='||(SELECT count(*) FROM private.delivery_autocreate_fallos WHERE receta_base_id = rid),
    'reveal='||(SELECT count(*) FROM private.reveal_log WHERE receta_base_id = rid),
    'confirm='||(SELECT count(*) FROM public.confirmaciones_receta WHERE receta_avanzada_id = ra));
  IF sig2 IS DISTINCT FROM sig_orig THEN r_rest := 'firma no vuelve al snapshot original'; END IF;
  UPDATE public.empresas_proveedoras SET estado = emp_est0 WHERE id = emp AND estado IS DISTINCT FROM emp_est0;
  IF (SELECT estado FROM public.empresas_proveedoras WHERE id = emp) IS DISTINCT FROM emp_est0 THEN
    r_rest := r_rest||' / estado de empresa no vuelve'; END IF;
  det := det||' ;; empresa del fixture|estado original '||COALESCE(emp_est0,'-')||'|'||CASE WHEN emp_est0 = 'activa' THEN 'ya activa' ELSE 'activada para el probe y restaurada' END||'|-|';
  det := det||' ;; restauracion|firma igual al snapshot|'||r_rest||'|-|';

  PERFORM set_config('probe.p845_det', det, false);
  PERFORM set_config('probe.p845', CASE WHEN (r_can = 'PR010 Receta cancelada: no se puede despachar') AND sig1 = sig0 AND r_act = 'OK' AND r_rest = 'OK'
    THEN 'OK (fijar_modalidad_grupo (paciente): cancelada -> PR010, activa -> OK con efecto; restaurado)'
    ELSE 'ROJO (cancelada='||r_can||' | activa='||r_act||' '||COALESCE(eff,'-')||' | firma_cancelada='||(sig1 = sig0)||' | restauracion='||r_rest||')' END, false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
  PERFORM set_config('probe.p845', CASE WHEN SQLERRM LIKE 'fixture roto%' THEN 'ROJO ('||SQLERRM||')'
    ELSE 'FALLO ('||SQLSTATE||' '||SQLERRM||')' END, false);
END $$;
SELECT set_config('role','none', true);

-- ---------------- P846 confirmar_recepcion_receta (control: no se toca) ----------------
DO $$
DECLARE
  rid bigint; iid bigint; farm integer; nom text; emp uuid; ra uuid; tok text; ctok text; pac bigint; pac_uid uuid;
  cta uuid; c record; det text := ''; r_can text; r_act text; r_rest text := 'OK'; st text; msg text; j jsonb; v_n bigint;
  sig0 text; sig1 text; sig2 text; eff text;
  disp0 uuid[]; ent0 bigint[]; fal0 bigint[]; rev0 bigint[]; conf0 uuid[]; it0 record; stock0 jsonb; ra0 record; est0 text; sig_orig text; mod_orig text; emp_est0 text;
BEGIN
  SELECT ri.id, ri.receta_id, ri.farmacia_id, ri.nombre_medicamento, f.empresa_id, ra_.id, ra_.dispatch_token, ra_.confirmacion_token, r.paciente_id
    INTO iid, rid, farm, nom, emp, ra, tok, ctok, pac
    FROM public.receta_items ri JOIN public.farmacias f ON f.id = ri.farmacia_id
    JOIN public.recetas r ON r.id = ri.receta_id JOIN public.recetas_avanzadas ra_ ON ra_.receta_base_id = r.id
   WHERE ri.dispensado = false AND ra_.dispatch_token_expira_at > now() AND ra_.confirmacion_token_expira_at > now()
     AND r.estado = 'activa'
   ORDER BY ri.receta_id, ri.id LIMIT 1;
  IF iid IS NULL THEN RAISE EXCEPTION 'fixture roto: item ruteado de receta activa con token vigente'; END IF;
  -- el gate de estado de empresa (mig 322) exige empresa 'activa': si la dejo en otro estado un probe anterior
  -- del harness, se activa aca como fixture y se restaura al final (verificado).
  SELECT e.estado INTO emp_est0 FROM public.empresas_proveedoras e WHERE e.id = emp;
  IF emp_est0 IS DISTINCT FROM 'activa' THEN UPDATE public.empresas_proveedoras SET estado = 'activa' WHERE id = emp; END IF;
  FOR c IN SELECT cp.id FROM public.cuentas_proveedor cp WHERE cp.empresa_id = emp AND cp.activo IS TRUE ORDER BY cp.id LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub',c.id::text,'role','authenticated')::text, true);
    IF COALESCE(private.tiene_permiso('recetas_dispensar'), false) AND COALESCE(private.tiene_permiso('entregas_gestionar'), false)
       AND COALESCE(private.sucursal_visible(farm), false) THEN cta := c.id; EXIT; END IF;
  END LOOP;
  PERFORM set_config('request.jwt.claims','',true);
  IF cta IS NULL THEN RAISE EXCEPTION 'fixture roto: cuenta de farmacia con dispensar + entregas + sucursal visible'; END IF;
  SELECT p.auth_user_id INTO pac_uid FROM public.pacientes p WHERE p.id = pac;
  -- snapshot
  SELECT r.estado INTO est0 FROM public.recetas r WHERE r.id = rid;
  SELECT array_agg(id) INTO disp0 FROM public.dispensaciones WHERE receta_avanzada_id = ra;
  SELECT array_agg(id) INTO ent0 FROM public.entregas WHERE receta_base_id = rid;
  SELECT array_agg(id) INTO fal0 FROM private.delivery_autocreate_fallos WHERE receta_base_id = rid;
  SELECT array_agg(id) INTO rev0 FROM private.reveal_log WHERE receta_base_id = rid;
  SELECT array_agg(id) INTO conf0 FROM public.confirmaciones_receta WHERE receta_avanzada_id = ra;
  SELECT dispensado, dispensado_at, modalidad INTO it0 FROM public.receta_items WHERE id = iid;
  SELECT jsonb_agg(jsonb_build_object('id', id, 's', stock_actual, 'u', updated_at)) INTO stock0
    FROM public.farmacia_medicamentos WHERE farmacia_id = farm AND nombre_medicamento = nom;
  SELECT estado_dispensacion, fecha_dispensacion, farmacia_id, updated_at INTO ra0 FROM public.recetas_avanzadas WHERE id = ra;
  sig0 := concat_ws(' | ',
    'rec='||COALESCE((SELECT estado FROM public.recetas WHERE id = rid),'-'),
    'disp='||(SELECT count(*) FROM public.dispensaciones WHERE receta_avanzada_id = ra),
    'item='||COALESCE((SELECT dispensado::text||'@'||COALESCE(dispensado_at::text,'-')||'@'||COALESCE(modalidad,'-') FROM public.receta_items WHERE id = iid),'-'),
    'stock='||COALESCE((SELECT string_agg(id::text||':'||stock_actual||'@'||updated_at, ',' ORDER BY id) FROM public.farmacia_medicamentos WHERE farmacia_id = farm AND nombre_medicamento = nom),'-'),
    'ra='||COALESCE((SELECT COALESCE(estado_dispensacion,'-')||'@'||COALESCE(fecha_dispensacion::text,'-')||'@'||COALESCE(farmacia_id,'-')||'@'||updated_at FROM public.recetas_avanzadas WHERE id = ra),'-'),
    'entregas='||(SELECT count(*) FROM public.entregas WHERE receta_base_id = rid),
    'fallos='||(SELECT count(*) FROM private.delivery_autocreate_fallos WHERE receta_base_id = rid),
    'reveal='||(SELECT count(*) FROM private.reveal_log WHERE receta_base_id = rid),
    'confirm='||(SELECT count(*) FROM public.confirmaciones_receta WHERE receta_avanzada_id = ra));
  sig_orig := sig0; mod_orig := it0.modalidad;

  -- A) receta CANCELADA
  UPDATE public.recetas SET estado = 'cancelada' WHERE id = rid;
  st := '00000'; msg := ''; j := NULL;
  BEGIN
    PERFORM set_config('request.jwt.claims','{"role":"service_role"}', true); PERFORM set_config('role','service_role',true);
    j := to_jsonb(public.confirmar_recepcion_receta(ctok, NULL, 'P846 QA'));
    PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
    st := SQLSTATE; msg := SQLERRM; END;
  r_can := CASE WHEN st = '00000' THEN 'OK' ELSE 'ERR' END;
  r_can := st||' '||msg;

  DELETE FROM public.dispensaciones WHERE receta_avanzada_id = ra AND NOT (id = ANY(COALESCE(disp0, '{}')));
  DELETE FROM public.entregas WHERE receta_base_id = rid AND NOT (id = ANY(COALESCE(ent0, '{}')));
  DELETE FROM private.delivery_autocreate_fallos WHERE receta_base_id = rid AND NOT (id = ANY(COALESCE(fal0, '{}')));
  DELETE FROM private.reveal_log WHERE receta_base_id = rid AND NOT (id = ANY(COALESCE(rev0, '{}')));
  DELETE FROM public.confirmaciones_receta WHERE receta_avanzada_id = ra AND NOT (id = ANY(COALESCE(conf0, '{}')));
  UPDATE public.receta_items SET dispensado = it0.dispensado, dispensado_at = it0.dispensado_at, modalidad = it0.modalidad WHERE id = iid;
  UPDATE public.farmacia_medicamentos fm SET stock_actual = x.s, updated_at = x.u
    FROM jsonb_to_recordset(COALESCE(stock0, '[]')) AS x(id uuid, s integer, u timestamptz) WHERE fm.id = x.id;
  UPDATE public.recetas_avanzadas SET estado_dispensacion = ra0.estado_dispensacion, fecha_dispensacion = ra0.fecha_dispensacion,
         farmacia_id = ra0.farmacia_id, updated_at = ra0.updated_at WHERE id = ra;
  UPDATE public.recetas SET estado = est0 WHERE id = rid;
  sig1 := concat_ws(' | ',
    'rec='||COALESCE((SELECT estado FROM public.recetas WHERE id = rid),'-'),
    'disp='||(SELECT count(*) FROM public.dispensaciones WHERE receta_avanzada_id = ra),
    'item='||COALESCE((SELECT dispensado::text||'@'||COALESCE(dispensado_at::text,'-')||'@'||COALESCE(modalidad,'-') FROM public.receta_items WHERE id = iid),'-'),
    'stock='||COALESCE((SELECT string_agg(id::text||':'||stock_actual||'@'||updated_at, ',' ORDER BY id) FROM public.farmacia_medicamentos WHERE farmacia_id = farm AND nombre_medicamento = nom),'-'),
    'ra='||COALESCE((SELECT COALESCE(estado_dispensacion,'-')||'@'||COALESCE(fecha_dispensacion::text,'-')||'@'||COALESCE(farmacia_id,'-')||'@'||updated_at FROM public.recetas_avanzadas WHERE id = ra),'-'),
    'entregas='||(SELECT count(*) FROM public.entregas WHERE receta_base_id = rid),
    'fallos='||(SELECT count(*) FROM private.delivery_autocreate_fallos WHERE receta_base_id = rid),
    'reveal='||(SELECT count(*) FROM private.reveal_log WHERE receta_base_id = rid),
    'confirm='||(SELECT count(*) FROM public.confirmaciones_receta WHERE receta_avanzada_id = ra));
  det := 'cancelada|sin rechazo (no se toca)|'||CASE WHEN r_can = '00000 ' THEN 'OK' ELSE 'ROJO' END||'|'||st||'|'||msg
         ||' ;; cancelada: firma tras restaurar|firma igual al snapshot|'||CASE WHEN sig1 = sig0 THEN 'igual' ELSE 'DISTINTA' END||'|-|';
  -- B) receta ACTIVA -> OK, efecto verificado y restaurado
  st := '00000'; msg := ''; j := NULL;
  BEGIN
    PERFORM set_config('request.jwt.claims','{"role":"service_role"}', true); PERFORM set_config('role','service_role',true);
    j := to_jsonb(public.confirmar_recepcion_receta(ctok, NULL, 'P846 QA'));
    PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
  EXCEPTION WHEN OTHERS THEN PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
    st := SQLSTATE; msg := SQLERRM; END;
  r_act := CASE WHEN st = '00000' THEN 'OK' ELSE 'ERR' END;
  eff := 'estado='||COALESCE(j #>> '{}','-');
  det := det||' ;; activa|confirmada o ya_confirmada|'||r_act||' '||COALESCE(eff,'-')||'|'||st||'|'||msg;
  IF r_act = 'OK' AND NOT ((j #>> '{}') IN ('confirmada','ya_confirmada')) THEN r_act := 'OK-SIN-EFECTO'; END IF;
  DELETE FROM public.dispensaciones WHERE receta_avanzada_id = ra AND NOT (id = ANY(COALESCE(disp0, '{}')));
  DELETE FROM public.entregas WHERE receta_base_id = rid AND NOT (id = ANY(COALESCE(ent0, '{}')));
  DELETE FROM private.delivery_autocreate_fallos WHERE receta_base_id = rid AND NOT (id = ANY(COALESCE(fal0, '{}')));
  DELETE FROM private.reveal_log WHERE receta_base_id = rid AND NOT (id = ANY(COALESCE(rev0, '{}')));
  DELETE FROM public.confirmaciones_receta WHERE receta_avanzada_id = ra AND NOT (id = ANY(COALESCE(conf0, '{}')));
  UPDATE public.receta_items SET dispensado = it0.dispensado, dispensado_at = it0.dispensado_at, modalidad = it0.modalidad WHERE id = iid;
  UPDATE public.farmacia_medicamentos fm SET stock_actual = x.s, updated_at = x.u
    FROM jsonb_to_recordset(COALESCE(stock0, '[]')) AS x(id uuid, s integer, u timestamptz) WHERE fm.id = x.id;
  UPDATE public.recetas_avanzadas SET estado_dispensacion = ra0.estado_dispensacion, fecha_dispensacion = ra0.fecha_dispensacion,
         farmacia_id = ra0.farmacia_id, updated_at = ra0.updated_at WHERE id = ra;
  UPDATE public.recetas SET estado = est0 WHERE id = rid;

  sig2 := concat_ws(' | ',
    'rec='||COALESCE((SELECT estado FROM public.recetas WHERE id = rid),'-'),
    'disp='||(SELECT count(*) FROM public.dispensaciones WHERE receta_avanzada_id = ra),
    'item='||COALESCE((SELECT dispensado::text||'@'||COALESCE(dispensado_at::text,'-')||'@'||COALESCE(modalidad,'-') FROM public.receta_items WHERE id = iid),'-'),
    'stock='||COALESCE((SELECT string_agg(id::text||':'||stock_actual||'@'||updated_at, ',' ORDER BY id) FROM public.farmacia_medicamentos WHERE farmacia_id = farm AND nombre_medicamento = nom),'-'),
    'ra='||COALESCE((SELECT COALESCE(estado_dispensacion,'-')||'@'||COALESCE(fecha_dispensacion::text,'-')||'@'||COALESCE(farmacia_id,'-')||'@'||updated_at FROM public.recetas_avanzadas WHERE id = ra),'-'),
    'entregas='||(SELECT count(*) FROM public.entregas WHERE receta_base_id = rid),
    'fallos='||(SELECT count(*) FROM private.delivery_autocreate_fallos WHERE receta_base_id = rid),
    'reveal='||(SELECT count(*) FROM private.reveal_log WHERE receta_base_id = rid),
    'confirm='||(SELECT count(*) FROM public.confirmaciones_receta WHERE receta_avanzada_id = ra));
  IF sig2 IS DISTINCT FROM sig_orig THEN r_rest := 'firma no vuelve al snapshot original'; END IF;
  UPDATE public.empresas_proveedoras SET estado = emp_est0 WHERE id = emp AND estado IS DISTINCT FROM emp_est0;
  IF (SELECT estado FROM public.empresas_proveedoras WHERE id = emp) IS DISTINCT FROM emp_est0 THEN
    r_rest := r_rest||' / estado de empresa no vuelve'; END IF;
  det := det||' ;; empresa del fixture|estado original '||COALESCE(emp_est0,'-')||'|'||CASE WHEN emp_est0 = 'activa' THEN 'ya activa' ELSE 'activada para el probe y restaurada' END||'|-|';
  det := det||' ;; restauracion|firma igual al snapshot|'||r_rest||'|-|';

  PERFORM set_config('probe.p846_det', det, false);
  PERFORM set_config('probe.p846', CASE WHEN (r_can = '00000 ') AND sig1 = sig0 AND r_act = 'OK' AND r_rest = 'OK'
    THEN 'OK (confirmar_recepcion_receta (control: no se toca): cancelada -> sin cambio, activa -> OK con efecto; restaurado)'
    ELSE 'ROJO (cancelada='||r_can||' | activa='||r_act||' '||COALESCE(eff,'-')||' | firma_cancelada='||(sig1 = sig0)||' | restauracion='||r_rest||')' END, false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('role','none',true); PERFORM set_config('request.jwt.claims','',true);
  PERFORM set_config('probe.p846', CASE WHEN SQLERRM LIKE 'fixture roto%' THEN 'ROJO ('||SQLERRM||')'
    ELSE 'FALLO ('||SQLSTATE||' '||SQLERRM||')' END, false);
END $$;
SELECT set_config('role','none', true);

-- ---------------- P847 catalogo: 6 funciones con el chequeo, metadata intacta, confirmar sin tocar ----------------
DO $$
DECLARE det text := ''; bad text := ''; e record; r record;
BEGIN
  FOR e IN SELECT * FROM (VALUES
    ('public.verificar_receta_despacho(text)'), ('public.registrar_dispensacion(text,bigint[],text)'),
    ('public.registrar_dispensacion_dirigida(bigint,bigint[],text)'), ('public.revelar_items_receta(bigint,text)'),
    ('public.crear_entrega(bigint,integer)'), ('public.fijar_modalidad_grupo(bigint,integer,text)')) x(f) LOOP
    SELECT p.prosecdef, pg_get_userbyid(p.proowner) AS owner, p.proconfig::text AS cfg,
           has_function_privilege('authenticated', p.oid, 'EXECUTE') AS auth, has_function_privilege('anon', p.oid, 'EXECUTE') AS anon,
           (position('Receta cancelada: no se puede despachar' in p.prosrc) > 0 AND position('PR010' in p.prosrc) > 0) AS chequeo
      INTO r FROM pg_proc p WHERE p.oid = e.f::regprocedure;
    det := det||CASE WHEN det = '' THEN '' ELSE ' ;; ' END||e.f||'|chequeo=t secdef=t owner=postgres cfg=search_path="" auth=t anon=f|'
           ||'chequeo='||r.chequeo||' secdef='||r.prosecdef||' owner='||r.owner||' cfg='||COALESCE(r.cfg,'NULL')||' auth='||r.auth||' anon='||r.anon||'|-|';
    IF NOT (r.chequeo AND r.prosecdef AND r.owner = 'postgres' AND r.cfg = '{"search_path=\"\""}' AND r.auth AND NOT r.anon) THEN
      bad := bad||e.f||'; '; END IF;
  END LOOP;
  SELECT md5(prosrc) INTO r FROM pg_proc WHERE oid = 'public.confirmar_recepcion_receta(text,inet,text)'::regprocedure;
  det := det||' ;; confirmar_recepcion_receta md5|b94e4d21e567ceeb38fb83ebf9a83b03|'||r.md5||'|-|';
  IF r.md5 IS DISTINCT FROM 'b94e4d21e567ceeb38fb83ebf9a83b03' THEN bad := bad||'confirmar_recepcion_receta cambio; '; END IF;
  PERFORM set_config('probe.p847_det', det, false);
  PERFORM set_config('probe.p847', CASE WHEN bad = ''
    THEN 'OK (6 funciones con el chequeo PR010 y metadata intacta; confirmar_recepcion_receta sin tocar)'
    ELSE 'ROJO ('||left(bad,800)||')' END, false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('probe.p847','FALLO ('||SQLSTATE||' '||SQLERRM||')', false);
END $$;
SELECT set_config('role','none', true);

